CREATE INDEX tasks_parent ON public.tasks USING btree (parent_task_id) WHERE (parent_task_id IS NOT NULL);
CREATE INDEX tasks_recurrence_open_idx ON public.tasks USING btree (status, due_on) WHERE (recurrence IS NOT NULL);
CREATE INDEX tasks_recurrence_parent_id_idx ON public.tasks USING btree (recurrence_parent_id);
CREATE INDEX idx_test_requests_status ON public.test_requests USING btree (status);
CREATE INDEX tg_over_lookup ON public.tg_overrides USING btree (target_table, row_key) WHERE active;
CREATE UNIQUE INDEX tg_over_one_active ON public.tg_overrides USING btree (target_table, row_key, field_name) WHERE active;
CREATE UNIQUE INDEX third_party_material_natural_key ON public.third_party_material USING btree (metrc_tag, source_row);
CREATE INDEX idx_time_entries_emp_date ON public.time_entries USING btree (employee_id, work_date);
CREATE INDEX time_entries_emp_date_idx ON public.time_entries USING btree (employee_id, work_date DESC);
CREATE INDEX time_entries_open_idx ON public.time_entries USING btree (employee_id, work_date) WHERE (clock_out IS NULL);
CREATE UNIQUE INDEX time_entries_source_ref_key ON public.time_entries USING btree (source, source_ref) WHERE (source_ref IS NOT NULL);
CREATE UNIQUE INDEX turnaround_target_scope ON public.turnaround_target USING btree (scope, COALESCE(scope_value, ''::text), stage);
CREATE INDEX uilabels_page_idx ON public.ui_labels USING btree (surface, page_key, kind);
CREATE UNIQUE INDEX one_default_per_user ON public.user_dashboard USING btree (user_id) WHERE is_default;
CREATE INDEX vr_key_time ON public.verification_runs USING btree (check_key, ran_at DESC);
CREATE UNIQUE INDEX watchdog_findings_fingerprint_once ON public.watchdog_findings USING btree (fingerprint) WHERE (fingerprint IS NOT NULL);
CREATE INDEX wf_fp ON public.watchdog_findings USING btree (fingerprint, observed_at DESC);
CREATE INDEX wf_search ON public.watchdog_findings USING gin (to_tsvector('english'::regconfig, COALESCE(search_text, ''::text)));
CREATE INDEX wf_when ON public.watchdog_findings USING btree (observed_at DESC);
CREATE INDEX zone_active ON public.zone USING btree (active, sort);
CREATE INDEX zsr_zone_idx ON public.zone_staffing_requirements USING btree (zone_id, effective_from DESC);

