CREATE OR REPLACE FUNCTION public._tg_autofix_probe()
 RETURNS integer
 LANGUAGE sql
AS $function$ select 1 $function$
;
CREATE OR REPLACE FUNCTION public.agent_sheet_reconciliation()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare run bigint; n int := 0; r record; mapped int;
begin
  insert into watchdog_runs default values returning id into run;
  select count(*) into mapped from sheet_column_map where role='package_tag';

  if mapped = 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (run, 'sheet_recon_unmapped', 'elevated',
      'No imported spreadsheet has been matched to Metrc yet',
      'Sheet Sync, in Settings', 'Whoever owns the inventory sheet', 'Since the sheet was first imported',
      'A spreadsheet nobody has reconciled is a second set of numbers that can drift from the legal record without anyone noticing. Staff act on the sheet; the state acts on Metrc.',
      'The reconciliation agent looked for a column marked as the package tag on each imported sheet and found none.',
      'Open Sheet Sync and say which column holds the package tag. Reconciliation then runs by itself every hour.',
      'Sources with a package tag column mapped: 0', 0, 'sheet_sync', 'sheet reconciliation unmapped');
    return 1;
  end if;

  for r in
    select source_name, verdict, rows_affected, total_difference, severity, example
    from v_sheet_metrc_alerts
  loop
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text, evidence)
    values (run,
      'sheet_recon_' || md5(r.source_name || r.verdict), r.severity,
      r.rows_affected || ' package' || case when r.rows_affected=1 then '' else 's' end
        || ' where the sheet and Metrc do not agree — ' || lower(r.verdict),
      'The ' || r.source_name || ', checked against Metrc',
      'Whoever maintains the ' || r.source_name,
      'From the most recent import of that sheet',
      case r.verdict
        when 'QUANTITY DISAGREES' then 'Staff are picking, allocating and selling against numbers that do not match the legal record. Every one of these is either a Metrc entry nobody made or stock that has moved without being recorded.'
        when 'IN THE SHEET, NOT IN METRC' then 'The sheet names stock that does not exist in Metrc. Either the tag is wrong or the package was never created — and material that is not in Metrc cannot lawfully be sold.'
        when 'IN METRC, NOT IN THE SHEET' then 'Real stock is missing from the sheet the floor works off, so it will not be picked, allocated or sold. It ages in place while people believe it is not there.'
        else 'A row that cannot be checked at all is a row nobody is accountable for.'
      end,
      'The reconciliation agent joined every imported sheet row to Metrc on the package tag and compared quantities to three decimal places.',
      case r.verdict
        when 'QUANTITY DISAGREES' then 'Count the packages physically, then correct Metrc or the sheet — and record which one was wrong.'
        when 'IN THE SHEET, NOT IN METRC' then 'Check each tag against Metrc. If the package is real, create it in Metrc. If the tag is mistyped, fix the sheet.'
        when 'IN METRC, NOT IN THE SHEET' then 'Add the missing packages to the sheet so the floor can see them, or explain why they are deliberately excluded.'
        else 'Fill in the missing quantities on the sheet.'
      end,
      r.rows_affected || ' rows, total difference ' || coalesce(r.total_difference,0),
      r.rows_affected, 'sheet_vs_metrc',
      lower(r.source_name || ' ' || r.verdict),
      (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from (
         select package_tag, sheet_row, sheet_item, metrc_item, sheet_quantity,
                metrc_quantity, metrc_unit, difference, what_it_means
         from v_sheet_metrc_reconciliation
         where verdict = r.verdict limit 200) x));
    n := n + 1;
  end loop;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rec jsonb;
  uid uuid;
begin
  rec := to_jsonb(case when tg_op = 'DELETE' then old else new end);
  begin
    uid := auth.uid();
  exception when others then uid := null;
  end;
  insert into audit_events(actor, actor_name, entity, entity_id, action, old_value, new_value)
  values (uid, f_actor(), tg_table_name,
          coalesce(rec->>'id', rec->>'key', rec->>'user_id', '?'),
          tg_op,
          case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end);
  return case when tg_op = 'DELETE' then old else new end;
end $function$
;
CREATE OR REPLACE FUNCTION public.audit_secret_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  insert into audit_events(actor, entity, entity_id, action, new_value)
  values (auth.uid(), 'integration_secrets', new.name, tg_op, jsonb_build_object('set', true));
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.bootstrap_app_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    insert into public.app_users(user_id, role)
    values (new.id, case when (select count(*) from public.app_users) = 0
                         then 'owner'::public.app_role else 'readonly'::public.app_role end);
  exception when others then
    -- Bootstrap must never break account creation; a missed row is repairable after the fact.
    null;
  end;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.current_app_role()
 RETURNS app_role
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select role from app_users where user_id = auth.uid()), 'readonly'::app_role)
$function$
;
CREATE OR REPLACE FUNCTION public.enforce_allocation_netting()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare total numeric; lotqty numeric; code text;
begin
  select quantity, lot_code into lotqty, code from lots where id = new.lot_id;
  select coalesce(sum(approved_qty),0) into total
    from allocations where lot_id = new.lot_id and id <> coalesce(new.id, gen_random_uuid());
  if total + new.approved_qty > lotqty then
    raise exception 'Over-allocation on lot %: % already approved + % requested > % available',
      code, total, new.approved_qty, lotqty;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.enforce_coa_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare c coa_status;
begin
  if new.status = 'ready_to_ship' then
    if new.coa_id is null then
      raise exception 'Lot % cannot be Ready To Ship: no COA linked', new.lot_code;
    end if;
    select status into c from coas where id = new.coa_id;
    if c not in ('pass','remediation_pass') then
      raise exception 'Lot % cannot be Ready To Ship: COA status is %', new.lot_code, c;
    end if;
    if new.expires_on is not null and new.expires_on < current_date then
      raise exception 'Lot % cannot be Ready To Ship: expired %', new.lot_code, new.expires_on;
    end if;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.enforce_ship_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare s lot_status; code text;
begin
  select status, lot_code into s, code from lots where id = new.lot_id;
  if s not in ('ready_to_ship','shipped') then
    raise exception 'Lot % cannot ship: status is %, requires ready_to_ship', code, s;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.enforce_wo_release_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status in ('released','in_production')
     and not exists (select 1 from allocations a
                     where a.work_order_id = new.id and a.release = 'released') then
    raise exception 'Work order % cannot be released: no released material allocation', new.wo_code;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_actor()
 RETURNS text
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v text;
begin
  -- A real signed-in human is the best answer available.
  begin
    v := nullif(auth.uid()::text, '');
    if v is not null then return 'user:' || v; end if;
  exception when others then null;  -- no request context; keep going
  end;

  -- An agent that declares itself: `set app.agent = 'agent-b'` on its session.
  begin
    v := nullif(current_setting('app.agent', true), '');
    if v is not null then return 'agent:' || v; end if;
  exception when others then null;
  end;

  -- Connection-level identity. psql, the MCP server and cron each set this differently,
  -- so it is weaker than the above but far better than nothing.
  v := nullif(current_setting('application_name', true), '');
  if v is not null and v not in ('psql', '') then return 'app:' || v; end if;

  return 'role:' || session_user;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_ai_end_session(p_user uuid DEFAULT auth.uid())
 RETURNS integer
 LANGUAGE sql
AS $function$
  with done as (
    update ai_write_approval set revoked_at = now()
    where user_id = p_user and revoked_at is null and expires_at is null
    returning 1)
  select count(*)::int from done;
$function$
;
CREATE OR REPLACE FUNCTION public.f_ai_key_present()
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from app_secrets
    where key = 'ANTHROPIC_API_KEY' and coalesce(btrim(value), '') <> ''
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_ai_may(p_user uuid, p_system text, p_action text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  with pol as (select * from ai_write_policy where system = lower(p_system)),
       grant_row as (
         select * from ai_write_approval
         where user_id = p_user and system = lower(p_system)
           and revoked_at is null
           and (expires_at is null or expires_at > now())
           and (action is null or action = p_action)
         order by granted_at desc limit 1
       )
  select case
    when p_user is null then jsonb_build_object(
      'verdict', 'refused',
      'why', 'Owner hard rule, 8 Aug 2026: nothing is ever automatic. This was reached with no signed-in person - a schedule, a background scan or a cron job. Background work may propose an action and must never perform one.',
      'system', lower(p_system), 'action', p_action, 'automatic', true)
    when (select never_allowed from pol) then jsonb_build_object(
      'verdict', 'refused', 'why', (select why from pol), 'permanent', true,
      'system', lower(p_system), 'action', p_action)
    when not exists (select 1 from pol) then jsonb_build_object(
      'verdict', 'ask',
      'why', 'This system is not registered in ai_write_policy. Nothing unregistered is written to without the person saying so first. If this is a capability on someone''s device, the answer is no: only the camera and the microphone are ever used, on a computer, and only when switched on.',
      'system', lower(p_system), 'action', p_action, 'registered', false)
    when not (select company_enabled from pol) then jsonb_build_object(
      'verdict', 'refused',
      'why', (select why from pol),
      'system', lower(p_system), 'action', p_action, 'blocked_by', 'company')
    when (select manual_only from pol) then jsonb_build_object(
      'verdict', 'manual_only',
      'why', (select why from pol),
      'instruction', 'Do NOT perform this. Write out the exact steps the person takes in ' ||
                     (select label from pol) || ', in order, with the values to enter, and explain what each step does and what it will look like when it worked.',
      'system', lower(p_system), 'action', p_action, 'registered', true)
    when exists (select 1 from grant_row) then jsonb_build_object(
      'verdict', 'allowed',
      'why', coalesce((select 'Approved until ' || to_char(expires_at,'HH24:MI') || '.' from grant_row),
                      'Approved for this sign-in session. It ends when they sign out, not on a timer.'),
      'system', lower(p_system), 'action', p_action, 'registered', true)
    when not (select writes_allowed from pol) and (select kind from pol) = 'device' then jsonb_build_object(
      'verdict', 'ask', 'why', (select why from pol),
      'system', lower(p_system), 'action', p_action, 'registered', true, 'device', true)
    when not (select writes_allowed from pol) then jsonb_build_object(
      'verdict', 'refused', 'why', (select why from pol),
      'system', lower(p_system), 'action', p_action, 'registered', true)
    else jsonb_build_object(
      'verdict', 'ask', 'why', (select why from pol),
      'ask', 'Show exactly what will change, then offer: allow once, allow for this session, or no.',
      'system', lower(p_system), 'action', p_action, 'registered', true)
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_ai_model_for(p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select jsonb_build_object(
    'provider', coalesce((select preferred_provider from ai_user_access where user_id = p_user),
                         (select provider from ai_settings limit 1), 'anthropic'),
    'model',    coalesce((select preferred_model from ai_user_access where user_id = p_user),
                         (select model from ai_settings limit 1), 'claude-opus-5'),
    'source',   case when exists (select 1 from ai_user_access
                                   where user_id = p_user and preferred_model is not null)
                     then 'this user''s own choice' else 'company default' end,
    'via_bridge', coalesce((select bridge_enabled from ai_settings limit 1), true),
    'daily_limit',   (select daily_call_limit from ai_user_access where user_id = p_user),
    'monthly_limit', (select monthly_call_limit from ai_user_access where user_id = p_user),
    'note', 'Null limits mean no cap - the user is on their own plan through the desktop bridge.'
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_alert_all_admins(p_finding_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  f record;
  r record;
  v_missing text[];
  v_body text;
  v_sent int := 0;
  v_sol text;
  v_days_open int;
begin
  select * into f from watchdog_findings where id = p_finding_id;
  if not found then
    raise exception 'No finding with id %', p_finding_id;
  end if;

  select missing into v_missing from v_finding_alert_ready where id = p_finding_id;

  if array_length(v_missing, 1) is not null then
    raise exception
      'RULE J4 - this finding cannot be sent. Missing: %. Every alert must carry who, what, when, where, why, how, solutions and the guard''s recommendation. Fill them in and try again.',
      array_to_string(v_missing, ', ');
  end if;

  v_days_open := greatest(0, (current_date - f.observed_at::date));

  select string_agg('   ' || i || '. ' || s, E'\n' order by i)
    into v_sol
  from unnest(f.solutions) with ordinality as t(s, i);

  v_body :=
    'WHAT'            || E'\n' || '   ' || coalesce(f.what,'') || E'\n' ||
    case when coalesce(f.the_arithmetic,'') <> ''
         then '   Arithmetic: ' || f.the_arithmetic || E'\n' else '' end ||
    case when f.pounds  is not null then '   Weight at stake: ' || f.pounds  || ' lb' || E'\n' else '' end ||
    case when f.dollars is not null then '   Money at stake: $' || f.dollars || E'\n' else '' end ||
    E'\n' ||
    'WHO'             || E'\n' || '   Accountable: ' || coalesce(f.who_is_accountable,'') || E'\n' ||
                                  '   Raised by: the guard, ' || coalesce(f.how_it_was_detected,'a scheduled check') || E'\n' || E'\n' ||
    'WHEN'            || E'\n' || '   Started: ' || coalesce(f.when_it_started,'') || E'\n' ||
                                  '   Detected: ' || to_char(f.observed_at, 'DD Mon YYYY HH24:MI') || E'\n' ||
                                  '   Open for: ' || v_days_open || ' days' || E'\n' || E'\n' ||
    'WHERE'           || E'\n' || '   ' || coalesce(f.where_it_is,'') || E'\n' || E'\n' ||
    'WHY IT MATTERS'  || E'\n' || '   ' || coalesce(f.why_it_matters,'') || E'\n' || E'\n' ||
    'HOW IT WAS FOUND'|| E'\n' || '   ' || coalesce(f.how_it_was_detected,'') || E'\n' || E'\n' ||
    'SOLUTIONS'       || E'\n' || coalesce(v_sol,'') || E'\n' || E'\n' ||
    'THE GUARD''S RECOMMENDATION' || E'\n' || '   ' || coalesce(f.guard_recommendation,'') || E'\n' || E'\n' ||
    '---' || E'\n' ||
    'This issue could not be resolved automatically, so every admin has been told (rule J3).' || E'\n' ||
    'It will not clear itself. An owner or executive must record fix / leave / ignore /' || E'\n' ||
    'reset with a written reason (rule H1) - ignoring is a decision, not a deletion.';

  for r in
    select distinct ar.email, ar.full_name, ar.role
    from alert_recipient ar
    where ar.active
      and lower(ar.role) in ('owner','executive','admin','dept_head')
      and coalesce(ar.email,'') <> ''
  loop
    insert into alert_outbox (entity_type, entity_key, source, source_ref, severity, role,
                              channel, subject, body, raised_on, days_open, reminder_number)
    values ('watchdog_finding', p_finding_id::text, 'guard', f.fingerprint,
            coalesce(f.severity,'elevated'), r.role, 'email',
            upper(coalesce(f.severity,'elevated')) || ' - ' || left(coalesce(f.what,'Unresolved guard issue'), 120),
            'For ' || coalesce(r.full_name, r.email) || E'\n\n' || v_body,
            current_date, v_days_open, 0);
    v_sent := v_sent + 1;
  end loop;

  if v_sent = 0 then
    raise warning 'RULE J3 - finding % is ready to send but NO active admin recipient has an email address. The alert went nowhere. Add recipients to alert_recipient.', p_finding_id;
  end if;

  return v_sent;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_alert_recipient_count()
 RETURNS integer
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select (select count(*) from alert_recipient r
           where r.active and coalesce(btrim(r.email), '') <> '')
       + (select count(*) from auth.users au
           where au.email is not null
             and not exists (select 1 from alert_recipient r
                              where lower(btrim(r.email)) = lower(au.email::text) and r.active));
$function$
;
CREATE OR REPLACE FUNCTION public.f_all_ours(p_licences text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case when p_licences is null or btrim(p_licences) = '' then false
         else not exists (
           select 1 from unnest(string_to_array(p_licences, ',')) x
           where btrim(x) <> '' and not f_is_ours(btrim(x)))
         end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_allowed_endpoints(p_licence text)
 RETURNS text[]
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(array_agg(endpoint order by endpoint), '{}')
  from metrc_endpoint_capability where licence = p_licence and allowed;
$function$
;
CREATE OR REPLACE FUNCTION public.f_any_ours(p_licences text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case when p_licences is null or btrim(p_licences) = '' then false
         else exists (
           select 1 from unnest(string_to_array(p_licences, ',')) x
           where f_is_ours(btrim(x)))
         end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_assertion_probe(p_sql text, p_schema text DEFAULT NULL::text)
 RETURNS TABLE(n integer, sample jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_n integer; v_sample jsonb;
begin
  if p_schema is not null then
    execute format('set local search_path = %I, public, pg_temp', p_schema);
  end if;

  execute format('select count(*)::int from (%s) q', p_sql) into v_n;
  execute format(
    'select coalesce(jsonb_agg(to_jsonb(v)), ''[]''::jsonb) from (select * from (%s) q limit 20) v',
    p_sql) into v_sample;

  return query select v_n, v_sample;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_assign_login_ids(p_dry_run boolean DEFAULT true)
 RETURNS TABLE(employee_code text, full_name text, proposed_login_id text, note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_try text; v_base text; v_n int;
begin
  create temp table _claimed (lid text primary key) on commit drop;
  insert into _claimed select e.login_id from public.employees e where e.login_id is not null;

  for r in
    select e.id, e.employee_code, e.full_name, p.surname, p.first_i, p.middle_i
    from public.employees e, lateral public.f_login_id_parts(e.full_name) p
    where e.login_id is null
    order by e.employee_code
  loop
    if r.surname = '' or r.first_i = '' then
      employee_code := r.employee_code; full_name := r.full_name;
      proposed_login_id := null; note := 'SKIPPED — cannot parse name';
      return next; continue;
    end if;

    v_base := r.first_i || r.middle_i || left(r.surname, 1);
    v_try := v_base; v_n := 1;
    while exists (select 1 from _claimed where lid = v_try) loop
      v_n := v_n + 1;
      v_try := v_base || v_n::text;
    end loop;

    insert into _claimed values (v_try);
    if not p_dry_run then
      update public.employees set login_id = v_try where id = r.id;
    end if;

    employee_code := r.employee_code; full_name := r.full_name;
    proposed_login_id := v_try;
    note := case when v_n > 1 then 'collision — numbered'
                 when r.middle_i = '' then 'initials — no middle name'
                 else 'initials' end;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_automap_tag_column(p_source uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare best record;
begin
  select * into best from f_detect_tag_column(p_source) limit 1;
  if best is null then
    return 'No column in this sheet contains Metrc package tags. Nothing was mapped.';
  end if;
  insert into sheet_column_map (source_id, role, sheet_column)
  values (p_source, 'package_tag', best.sheet_column)
  on conflict (source_id, role) do update set sheet_column = excluded.sheet_column;
  return 'Mapped "' || best.sheet_column || '" as the package tag — ' || best.confidence
    || ' (' || best.matched_metrc || ' of ' || best.rows_tested || ' rows matched a real Metrc package).';
end $function$
;
CREATE OR REPLACE FUNCTION public.f_brain_memory_for(p_user uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'corrections', coalesce((
      select jsonb_agg(jsonb_build_object(
               'about', about, 'was_wrong', was_wrong,
               'what_is_true', what_is_true, 'evidence', evidence)
               order by decided_at desc nulls last)
      from brain_correction where status = 'approved'), '[]'::jsonb),

    'facts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'fact', fact, 'because', because, 'query', source_sql)
               order by learned_at desc)
      from (select * from brain_fact where retired_at is null
            order by learned_at desc limit 40) f), '[]'::jsonb),

    'recent', coalesce((
      select jsonb_agg(jsonb_build_object(
               'asked', question, 'answered', left(coalesce(answer,''), 400))
               order by at desc)
      from (select * from brain_conversation
            where user_id = p_user and at > now() - interval '1 day'
            order by at desc limit 6) r), '[]'::jsonb),

    'how_to_use', 'CORRECTIONS OUTRANK YOUR TRAINING. A person watched you get that wrong; a paragraph written last week did not. If a correction contradicts what you were about to say, the correction wins and you say so plainly. FACTS carry the query that produced them - re-derive rather than trust when the number matters. RECENT is this person''s last day, so a follow-up continues rather than restarting.'
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_bridge_model_for(p_user uuid)
 RETURNS text
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select coalesce(
    (select m.bridge_alias from ai_user_access a
       join ai_models m on m.id = a.preferred_model
      where a.user_id = p_user and m.enabled),
    (select m.bridge_alias from ai_settings s
       join ai_models m on m.id = s.model
      where m.enabled limit 1),
    'sonnet');
$function$
;
