CREATE OR REPLACE FUNCTION public.f_can_see_page(p_user uuid, p_view_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (
    select u.role::text as role, coalesce(r.rank, 0) as rank
    from app_users u left join app_roles r on r.role = u.role::text
    where u.user_id = p_user
  ),
  page as (
    select nr.view_key, nr.category,
           coalesce(sp.min_rank, 0) as needs_rank,
           coalesce(pc.is_shared, false) as shared
    from nav_registry nr
    left join sensitive_page_policy sp on sp.view_key = nr.view_key
    left join page_category_policy  pc on pc.category = nr.category
    where nr.view_key = p_view_key and nr.enabled
  )
  select exists (
    select 1 from page p, me
    -- DEPTH: rank must clear the page's sensitivity
    where me.rank >= p.needs_rank
    -- BREADTH: the category is shared, or granted to this user
      and (p.shared
           or exists (select 1 from user_department_access d
                      where d.user_id = p_user and d.category = p.category)
           -- owner and executive are not department-bound
           or me.rank >= 90)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_check_harvest_cycle()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r          record;
  v_target   int := public.f_rule('room_cycle_days')::int;
  v_raised   int := 0;
  v_id       bigint;
begin
  for r in
    select * from public.v_harvest_cycle_by_room
     where cycles_over_target > 0 or days_overdue_now > 0
     order by flower_room
  loop
    v_id := null;
    insert into public.watchdog_findings (
      observed_at, fingerprint, severity, what, where_it_is, who_is_accountable,
      when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, evidence, record_count, solutions, guard_recommendation)
    values (
      now(),
      'harvest_cycle_breach|' || r.flower_room || '|target=' || v_target,
      case when r.days_overdue_now > 14 then 'critical' else 'elevated' end,
      r.flower_room || ' is not meeting the ' || v_target || '-day harvest cycle: it '
        || 'averages ' || r.average_cycle_days || ' days, ' || r.average_slip_days
        || ' days over, across ' || r.cycles_measured || ' measured cycles.',
      'Flower room ' || r.flower_room || ', Cultivation. Source: metrc_harvests via '
        || 'v_harvest_cycle_compliance.',
      'Cultivation lead, and upper management for the rule itself.',
      'Last pull started ' || r.last_pull_start || ', ' || r.days_since_last_pull
        || ' days ago. Next pull was due ' || r.next_pull_due
        || case when r.days_overdue_now > 0
                then ' — ' || r.days_overdue_now || ' days ago.'
                else '.' end,
      'Every day of slip is lost capacity. Four rooms at a ' || v_target || '-day cycle '
        || 'yield ' || public.f_pulls_per_year() || ' pulls a year; at '
        || r.average_cycle_days || ' days they yield '
        || round(365.0 * 4 / nullif(r.average_cycle_days, 0), 0) || '. The facility '
        || 'cadence is correct at every other week — the loss is entirely room turnaround.',
      'Measured live from Metrc harvest records by f_check_harvest_cycle, comparing '
        || 'consecutive pull events per room against conversion_factors.room_cycle_days. '
        || 'Multi-day takedowns collapsed via pull_event_span_days.',
      'Cultivation to state what consumes the extra ' || r.average_slip_days
        || ' days between takedown and the next pull, or upper management to change '
        || 'room_cycle_days to the number the operation actually runs.',
      'Average ' || r.average_cycle_days || ' days against a ' || v_target
        || '-day rule = ' || r.average_slip_days || ' days slip per cycle. Observed range '
        || r.fastest_cycle_days || ' to ' || r.slowest_cycle_days || ' days.',
      jsonb_build_object('room', r.flower_room, 'target_days', v_target,
                         'average_cycle_days', r.average_cycle_days,
                         'cycles_measured', r.cycles_measured,
                         'cycles_over_target', r.cycles_over_target,
                         'last_pull_start', r.last_pull_start,
                         'next_pull_due', r.next_pull_due,
                         'days_overdue_now', r.days_overdue_now),
      r.cycles_over_target,
      array[
        'Record the turnaround steps between takedown and re-plant so the '
          || r.average_slip_days || ' days is visible rather than inferred.',
        'Change room_cycle_days in conversion_factors to the achievable number, which '
          || 'moves every schedule, forecast and assertion at once.',
        'Leave the rule at ' || v_target || ' and treat the gap as a stated improvement '
          || 'target, accepting that the badge stays lit until it closes.'
      ],
      'Do not change the rule to silence the badge. The ' || v_target || '-day cycle is '
        || 'the owner''s stated target and the flag is correct. Record what consumes the '
        || 'turnaround first — the number cannot be managed until it is visible.'
    )
    on conflict do nothing
    returning id into v_id;

    if v_id is not null then
      v_raised := v_raised + 1;
    end if;
  end loop;

  return v_raised;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_check_reason(p_action text, p_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_review_date date DEFAULT NULL::date, p_second_approver text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare pol reason_policy; rc reason_code_catalog; valid text;
begin
  select * into pol from reason_policy where action_key = p_action;
  if not found then
    raise exception 'No reason policy exists for the action "%". Add a row to reason_policy first, so the rule is visible in Settings rather than buried in code.', p_action
      using errcode = 'check_violation';
  end if;

  if not pol.enforced then return; end if;

  select string_agg(code, ', ' order by sort_order) into valid
  from reason_code_catalog
  where active and (applies_to = '{}' or p_action = any(applies_to));

  if pol.require_code then
    if coalesce(p_code,'') = '' then
      raise exception '%', 'A reason CODE is required to ' || lower(pol.label) || '.' ||
        chr(10) || 'Valid codes: ' || coalesce(valid,'(none active)') ||
        chr(10) || 'Why: a code can be counted and trended across months. Free text cannot.'
        using errcode = 'check_violation';
    end if;
    select * into rc from reason_code_catalog where code = p_code and active;
    if not found then
      raise exception '%', '"' || p_code || '" is not an active reason code.' ||
        chr(10) || 'Valid codes: ' || coalesce(valid,'(none active)')
        using errcode = 'check_violation';
    end if;
    if rc.applies_to <> '{}' and not (p_action = any(rc.applies_to)) then
      raise exception '%', 'Reason code "' || p_code || '" does not apply to ' || pol.label ||
        '. It is restricted to: ' || array_to_string(rc.applies_to, ', ')
        using errcode = 'check_violation';
    end if;
  end if;

  if (pol.require_note or coalesce(rc.requires_note,false))
     and length(trim(coalesce(p_note,''))) < pol.min_note_chars then
    raise exception '%', 'A written reason of at least ' || pol.min_note_chars ||
      ' characters is required to ' || lower(pol.label) || '. You gave ' ||
      length(trim(coalesce(p_note,''))) || '.' || chr(10) ||
      'Why: in six months nobody will remember what a two-word note meant. Say what differs and what you decided.'
      using errcode = 'check_violation';
  end if;

  if (pol.require_review_date or coalesce(rc.requires_review_date,false)) and p_review_date is null then
    raise exception '%', 'A review date is required to ' || lower(pol.label) ||
      '. This is postponing, not closing - it must come back on a date somebody owns.'
      using errcode = 'check_violation';
  end if;

  if pol.require_second_approver and coalesce(p_second_approver,'') = '' then
    raise exception '%', 'A second approver is required to ' || lower(pol.label) ||
      '. Separation of duties: the person proposing cannot be the only person agreeing.'
      using errcode = 'check_violation';
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_check_stock_ageing(p_by text DEFAULT 'watcher'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stale_lb numeric; v_stale_tags int;
  v_remnant_tags int;  v_remnant_lb numeric;
  v_nopolicy int; v_nopolicy_cats text;
  v_raised int := 0;
begin
  select coalesce(round(sum(lb),1),0), count(*)
    into v_stale_lb, v_stale_tags
    from v_stock_ageing where ageing_verdict like 'STALE%';

  select count(*), coalesce(round(sum(lb),3),0)
    into v_remnant_tags, v_remnant_lb
    from v_stock_ageing where remnant_verdict is not null;

  select count(distinct category), string_agg(distinct category, ', ')
    into v_nopolicy, v_nopolicy_cats
    from v_stock_ageing where ageing_verdict like 'NO POLICY%';

  if v_stale_tags > 0 then
    insert into watchdog_findings (
      observed_at, fingerprint, severity, what, where_it_is, who_is_accountable,
      when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, evidence, record_count, pounds, solutions, guard_recommendation)
    select now(), 'stock_ageing_stale|' || to_char(current_date,'IYYY-IW'), 'elevated',
      v_stale_tags || ' packages are past their category''s shelf life, holding '
        || v_stale_lb || ' lb. Material held on purpose in Quarantine or the biomass '
        || 'freezer is NOT counted here.',
      'v_stock_ageing where ageing_verdict is STALE. Rooms: '
        || coalesce((select string_agg(distinct location, ', ') from v_stock_ageing
                      where ageing_verdict like 'STALE%'), 'none'),
      'Cultivation for flower, Manufacturing for pre-rolls and edibles.',
      'Oldest package packaged ' || coalesce((select min(packaged_on)::text from v_stock_ageing
                                               where ageing_verdict like 'STALE%'), 'unknown'),
      'Cured product loses weight and terpenes. Anything past its window either sells at a '
        || 'discount, goes to extraction, or is destroyed — and each of those is a decision '
        || 'somebody has to take rather than let happen.',
      'f_check_stock_ageing, daily, comparing each package''s own age against '
        || 'stock_ageing_policy for its category.',
      'Review the list and decide per tag: sell, send to extraction, or destroy. Record the '
        || 'decision either way.',
      v_stale_tags || ' tags, ' || v_stale_lb || ' lb past their category window.',
      (select jsonb_agg(jsonb_build_object('tag', tag, 'category', category, 'room', location,
                                           'lb', lb, 'days', days_held))
         from v_stock_ageing where ageing_verdict like 'STALE%'),
      v_stale_tags, v_stale_lb,
      array['Sell it, at a discount if that is what it takes.',
            'Send it to extraction — old flower is still good feedstock.',
            'Destroy it and record the loss, which is honest and closes the tag.',
            'If it is being held deliberately, move it to a holding room so the clock stops '
              || 'and the reason is recorded, rather than leaving it to look like neglect.'],
      'Do not widen stock_ageing_policy to make this quiet. The window is what the owner '
        || 'believes about his own product; if it is wrong, change it deliberately and say '
        || 'why in the policy''s why column.'
    on conflict do nothing;
    v_raised := v_raised + 1;
  end if;

  if v_remnant_tags > 0 then
    insert into watchdog_findings (
      observed_at, fingerprint, severity, what, where_it_is, who_is_accountable,
      when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, evidence, record_count, pounds, solutions, guard_recommendation)
    select now(), 'stock_remnants|' || to_char(current_date,'IYYY-IW'), 'watch',
      v_remnant_tags || ' tags hold only a remnant — ' || v_remnant_lb
        || ' lb between all of them. These are worked-down packages that were never '
        || 'finished out in Metrc.',
      'v_stock_ageing where remnant_verdict is set.',
      'Whoever works the package down closes it. Cultivation and Manufacturing.',
      'Accumulating since the platform began.',
      'A remnant is bookkeeping, not spoilage. Each one still counts as an open package, '
        || 'inflates the tag count, and appears in every on-hand list a person has to read. '
        || v_remnant_tags || ' tags for ' || v_remnant_lb || ' lb is noise drowning signal.',
      'f_check_stock_ageing, daily, against stock_ageing_policy.remnant_under_lb.',
      'Finish these out in Metrc. The weight is negligible; the clutter is not.',
      v_remnant_tags || ' tags holding ' || v_remnant_lb || ' lb, an average of '
        || round(v_remnant_lb / nullif(v_remnant_tags,0), 4) || ' lb each.',
      jsonb_build_object('tags', v_remnant_tags, 'lb', v_remnant_lb),
      v_remnant_tags, v_remnant_lb,
      array['Finish them out in Metrc in one pass.',
            'Adjust the residue to zero with a recorded reason.',
            'Raise remnant_under_lb in stock_ageing_policy if the threshold is wrong — but '
              || 'say why, because the point is to find abandoned tags, not to stop looking.'],
      'Low severity on purpose. This is housekeeping, not risk. It becomes risk when the '
        || 'clutter is thick enough that nobody reads the on-hand list any more.'
    on conflict do nothing;
    v_raised := v_raised + 1;
  end if;

  if v_nopolicy > 0 then
    insert into watchdog_findings (
      observed_at, fingerprint, severity, what, where_it_is, who_is_accountable,
      when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, evidence, record_count, solutions, guard_recommendation)
    values (now(), 'stock_ageing_no_policy|' || v_nopolicy_cats, 'elevated',
      v_nopolicy || ' product category(ies) have no ageing policy: ' || v_nopolicy_cats,
      'stock_ageing_policy. A category with no row is neither watched nor knowingly excused.',
      'Agent I, Database COO.',
      'Since the category first appeared in Metrc.',
      'A category with no policy is invisible to the ageing check. Seeds were counted as '
        || 'spoiling flower for exactly this reason until 18 Aug 2026 — 24 tags of a '
        || 'genetics library reported as ageing stock.',
      'f_check_stock_ageing found packages whose category has no stock_ageing_policy row.',
      'Add a row saying whether it ages, after how long, and what counts as a remnant — with '
        || 'the reasoning in the why column.',
      v_nopolicy || ' categories unpoliced.',
      jsonb_build_object('categories', v_nopolicy_cats), v_nopolicy,
      array['Add the policy row with a written why.',
            'If the category is obsolete, retire it rather than leaving it unpoliced.'],
      'Do not default a new category to "does not age" to clear this. Seeds genuinely do not '
        || 'age; most things do, and guessing wrong in that direction hides real spoilage.');
    v_raised := v_raised + 1;
  end if;

  return jsonb_build_object(
    'findings_raised', v_raised,
    'stale_tags', v_stale_tags, 'stale_lb', v_stale_lb,
    'remnant_tags', v_remnant_tags, 'remnant_lb', v_remnant_lb,
    'categories_without_policy', v_nopolicy,
    'note', case when v_raised = 0
                 then 'Nothing stale, nothing abandoned, every category policed.'
                 else 'Findings raised. The owner should not have to notice this himself.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_check_tag_reconciliation(p_by text DEFAULT 'watcher'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_absent int; v_broken int; v_absent_lb numeric; v_broken_lb numeric;
  b_absent int; b_broken int; v_raised int := 0;
begin
  select count(distinct package_tag), round(coalesce(sum(lb),0)::numeric,1)
    into v_absent, v_absent_lb
    from v_metrc_apex_tag_reconciliation where verdict like 'ABSENT FROM APEX%';
  select count(distinct package_tag), round(coalesce(sum(lb),0)::numeric,1)
    into v_broken, v_broken_lb
    from v_metrc_apex_tag_reconciliation where verdict like 'APEX HAS IT%';

  select max_tags into b_absent from tag_reconciliation_baseline where verdict_class='ABSENT FROM APEX';
  select max_tags into b_broken from tag_reconciliation_baseline where verdict_class='JOIN BROKEN';

  /* Ratchet DOWN on improvement — recovered ground is kept. */
  update tag_reconciliation_baseline set max_tags = v_absent, measured_lb = v_absent_lb, set_on = current_date
   where verdict_class='ABSENT FROM APEX' and v_absent < max_tags;
  update tag_reconciliation_baseline set max_tags = v_broken, measured_lb = v_broken_lb, set_on = current_date
   where verdict_class='JOIN BROKEN' and v_broken < max_tags;

  if v_absent > b_absent then
    insert into watchdog_findings (observed_at, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, evidence, record_count, pounds, solutions, guard_recommendation)
    values (now(), 'tag_recon_absent_grew|' || to_char(current_date,'IYYY-IW'), 'critical',
      'Tags ABSENT FROM APEX grew to ' || v_absent || ' against a ratchet of ' || b_absent
        || '. New sales are shipping without an Apex invoice RIGHT NOW.',
      'v_metrc_apex_tag_reconciliation, verdict ABSENT FROM APEX.',
      'Agent S, Sales & Apex.', 'Detected ' || current_date || '.',
      'Every tag above the ratchet is a fresh shipment with no invoice — not backlog, new leakage.',
      'f_check_tag_reconciliation daily against tag_reconciliation_baseline.',
      'Find the manifests newer than the baseline date in the ABSENT class and invoice them.',
      v_absent || ' vs ratchet ' || b_absent || '; ' || v_absent_lb || ' lb in class.',
      jsonb_build_object('now', v_absent, 'ratchet', b_absent, 'lb', v_absent_lb),
      v_absent - b_absent, v_absent_lb,
      array['Invoice the new shipments in Apex.',
            'If deal-docs landed and closed old ones while new appeared, the net can still '
              || 'breach — read the per-manifest list, not just the count.'],
      'Never raise the baseline to quiet this. The ratchet only moves down.');
    v_raised := v_raised + 1;
  end if;

  if v_broken > b_broken then
    insert into watchdog_findings (observed_at, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, evidence, record_count, solutions, guard_recommendation)
    values (now(), 'tag_recon_joinbroken_grew|' || to_char(current_date,'IYYY-IW'), 'elevated',
      'JOIN BROKEN tags grew to ' || v_broken || ' against a ratchet of ' || b_broken || '.',
      'v_metrc_apex_tag_reconciliation, verdict APEX HAS IT.',
      'Agent S, Sales & Apex.', 'Detected ' || current_date || '.',
      'Apex holds these orders; only the licence-format join loses them. Growth means the '
        || 'join repair has not shipped or has regressed.',
      'f_check_tag_reconciliation daily against tag_reconciliation_baseline.',
      'Land the licence-digits comparison in the standing match rule.',
      v_broken || ' vs ratchet ' || b_broken || '.',
      jsonb_build_object('now', v_broken, 'ratchet', b_broken),
      v_broken - b_broken,
      array['Repair the join on licence digits — digits must agree exactly.'],
      'Never widen matching beyond digits-agree: suffix-variant matching produced 163 '
        || 'false pairs from 4 licences on 9 Aug.');
    v_raised := v_raised + 1;
  end if;

  return jsonb_build_object('raised', v_raised,
    'absent', v_absent, 'absent_ratchet', b_absent,
    'join_broken', v_broken, 'join_broken_ratchet', b_broken,
    'note', case when v_raised = 0 then 'Both classes at or below their ratchets.'
                 else 'Growth detected — findings raised.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_clear_ai_key()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  select role::text into v_role from app_users where user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive') then
    return jsonb_build_object('ok', false, 'message', 'Only an owner or an executive can remove the company key.');
  end if;
  update app_secrets set value = '' where key = 'ANTHROPIC_API_KEY';
  return jsonb_build_object('ok', true,
    'message', 'Removed. Questions fall back to the desktop bridge, which is free and slower.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_close_finding(p_fingerprint text, p_closed_by text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r finding_remediation; proof bigint; proof_at timestamptz;
begin
  select * into r from finding_remediation where fingerprint = p_fingerprint;
  if not found then
    raise exception 'No finding with fingerprint %', p_fingerprint using errcode='no_data_found';
  end if;
  if r.state = 'closed' then
    return 'Already closed at ' || r.closed_at;
  end if;

  select cl.id, cl.ran_at into proof, proof_at
  from conformance_ledger cl
  where cl.verdict = 'PASS'
    and cl.ran_at > r.raised_at
    and cl.subject_kind = r.subject_kind
    and cl.subject_ref  = r.subject_ref
    and (r.policy_key is null or cl.policy_key = r.policy_key)
  order by cl.ran_at desc
  limit 1;

  if proof is null then
    raise exception '%', 'CANNOT CLOSE ' || p_fingerprint || E'.\n' ||
      'Closure requires the check that raised this finding to PASS again, recorded in ' ||
      'conformance_ledger after ' || r.raised_at || '. No such row exists.' || E'\n' ||
      'Claiming a fix is not evidence; the check passing is. Re-run the checker for ' ||
      coalesce(r.subject_kind,'?') || ' / ' || coalesce(r.subject_ref,'?') ||
      ' and try again.' || E'\n' ||
      'If this finding should stand as an accepted risk instead, set state=''accepted_risk'' ' ||
      'with 40+ characters of accepted_reason and a named accepted_by.'
      using errcode = 'check_violation';
  end if;

  update finding_remediation
     set state = 'closed', closed_at = now(), closed_by_ledger_id = proof,
         claimed_by = coalesce(p_closed_by, claimed_by), updated_at = now()
   where fingerprint = p_fingerprint;

  return 'Closed. Proof: conformance_ledger row ' || proof || ' PASSED at ' || proof_at || '.';
end $function$
;
CREATE OR REPLACE FUNCTION public.f_coa_compliance_summary(p_from date DEFAULT '2000-01-01'::date, p_to date DEFAULT '2999-12-31'::date, p_group_by text DEFAULT 'yr'::text)
 RETURNS TABLE(grouping_value text, verdict text, action text, tags bigint, lb numeric, units numeric, oldest date, newest date, oldest_days integer)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE
AS $function$
begin
  return query execute format($f$
    select coalesce(%I::text,'(none)') as grouping_value,
           verdict, action,
           count(*)::bigint,
           round(sum(lb),1),
           sum(units),
           min(packaged_on), max(packaged_on), max(days_old)::integer
    from v_rpt_coa_compliance
    where packaged_on between $1 and $2
    group by 1,2,3
    order by 1, 2
  $f$, p_group_by) using p_from, p_to;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_company_key(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select nullif(btrim(regexp_replace(
    regexp_replace(lower(coalesce(p_name,'')),
      '\s*[-,]?\s*(inc|inc\.|llc|l\.l\.c\.|corp|corp\.|corporation|company|co|ltd|limited)\b\.?', '', 'g'),
    '[^a-z0-9]+', ' ', 'g')), '');
$function$
;
CREATE OR REPLACE FUNCTION public.f_concentrate_rate_per_lb(p_item text)
 RETURNS numeric
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select m.dollars_per_gram * 453.592 from public.concentrate_rate_map m
      where p_item ilike m.match_pattern order by m.sort limit 1),
    (select g.badder_crude_per_pound from public.v_cost_of_goods g))
$function$
;
CREATE OR REPLACE FUNCTION public.f_copy_role(p_from text, p_new_key text, p_new_label text, p_rank integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if exists (select 1 from app_roles where role = p_new_key) then
    return 'A role called ' || p_new_key || ' already exists. Pick another key.';
  end if;
  if not exists (select 1 from app_roles where role = p_from) then
    return 'No role called ' || p_from || ' to copy from.';
  end if;
  insert into app_roles (role, label, rank, built_in)
  select p_new_key, p_new_label, coalesce(p_rank, rank), false from app_roles where role = p_from;
  insert into role_permissions (role, action, allowed)
  select p_new_key, action, allowed from role_permissions where role = p_from;
  insert into nav_role_visibility (view_key, role, visible)
  select view_key, p_new_key, visible from nav_role_visibility where role = p_from;
  get diagnostics n = row_count;
  return 'Created ' || p_new_label || ' from ' || p_from || ' with '
    || (select count(*) from role_permissions where role = p_new_key)::text || ' permissions and '
    || n::text || ' page grants. Edit it freely - built-in roles stay untouched.';
end $function$
;
CREATE OR REPLACE FUNCTION public.f_cost_rate(p_material text, p_on date, p_tag text DEFAULT NULL::text, p_batch text DEFAULT NULL::text, p_brand text DEFAULT NULL::text, p_product_line text DEFAULT NULL::text, p_category text DEFAULT NULL::text)
 RETURNS TABLE(cost_per_lb numeric, cost_per_unit numeric, scope text, scope_key text, set_by text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select r.cost_per_lb, r.cost_per_unit, r.scope, r.scope_key, r.set_by
  from inventory_cost_rate r
  where r.material = p_material
    and p_on >= r.effective_from
    and (r.effective_to is null or p_on < r.effective_to)
    and ((r.scope='tag'          and r.scope_key = p_tag)
      or (r.scope='batch'        and r.scope_key = p_batch)
      or (r.scope='brand'        and r.scope_key = p_brand)
      or (r.scope='product_line' and r.scope_key = p_product_line)
      or (r.scope='category'     and r.scope_key = p_category)
      or  r.scope='global')
  order by case r.scope when 'tag' then 1 when 'batch' then 2 when 'brand' then 3
                        when 'product_line' then 4 when 'category' then 5 else 6 end,
           r.effective_from desc
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_cost_tracking(p_on date DEFAULT CURRENT_DATE, p_tag text DEFAULT NULL::text, p_batch text DEFAULT NULL::text, p_brand text DEFAULT NULL::text, p_product_line text DEFAULT NULL::text, p_category text DEFAULT NULL::text)
 RETURNS TABLE(track_labor boolean, track_packaging boolean, scope text, set_by text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select p.track_labor, p.track_packaging, p.scope, p.set_by
  from cost_tracking_policy p
  where p_on >= p.effective_from and (p.effective_to is null or p_on < p.effective_to)
    and ((p.scope='tag' and p.scope_key=p_tag) or (p.scope='batch' and p.scope_key=p_batch)
      or (p.scope='brand' and p.scope_key=p_brand)
      or (p.scope='product_line' and p.scope_key=p_product_line)
      or (p.scope='category' and p.scope_key=p_category) or p.scope='global')
  order by case p.scope when 'tag' then 1 when 'batch' then 2 when 'brand' then 3
                        when 'product_line' then 4 when 'category' then 5 else 6 end
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_date_default(p_user uuid, p_view_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select jsonb_build_object(
    'preset_key', coalesce(
        (select p.preset_key from user_page_date_default p
          where p.user_id = p_user and p.view_key = p_view_key),
        (select u.default_date_preset from user_settings u where u.user_id = p_user),
        (select case when r.date_column is null then 'all' else 'this_month' end
           from report_registry r
           join nav_registry n on n.table_ref = r.fact_view
          where n.view_key = p_view_key limit 1),
        'this_month'),
    'custom_from', (select p.custom_from from user_page_date_default p
                     where p.user_id = p_user and p.view_key = p_view_key),
    'custom_to',   (select p.custom_to from user_page_date_default p
                     where p.user_id = p_user and p.view_key = p_view_key),
    'scope', coalesce((select u.date_default_scope from user_settings u
                        where u.user_id = p_user), 'remember_last'),
    'source', case
       when exists (select 1 from user_page_date_default p
                     where p.user_id = p_user and p.view_key = p_view_key)
            then 'this user, this page'
       when exists (select 1 from user_settings u
                     where u.user_id = p_user and u.default_date_preset is not null)
            then 'this user, everywhere'
       else 'page default' end
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_department_dashboard(p_dept text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS TABLE(department text, ord integer, kpi text, value numeric, unit text, tone text, context text, drill text, computed_at timestamp with time zone, tile_kind text, honours_range boolean, range_note text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
with w as (
  select coalesce(p_from, date '2023-01-01') f,
         coalesce(p_to,   current_date)      t,
         (coalesce(p_to, current_date) >= current_date - 1
          and coalesce(p_from, date '2023-01-01') <= date '2023-01-01') as is_all_time,
         (coalesce(p_to, current_date) >= current_date - 1)             as ends_today),
flow as not materialized (
  select
    (select coalesce(sum(pounds),0) from v_transfer_line, w
      where direction='OUTBOUND' and voided<>'True' and received_on between w.f and w.t) sold_lb,
    (select coalesce(sum(nullif(t2.source_row->>'Receiver Wholesale Price','')::numeric),0)
       from metrc_rpt_package_transfers t2, w
      where f_is_ours(coalesce(nullif(t2.source_row->>'Dest. Lic.',''), t2.destination_licence))
        and not f_is_ours(coalesce(nullif(t2.source_row->>'Origin Lic.',''), t2.licence))
        and coalesce(t2.source_row->>'Voided','False') <> 'True'
        and t2.received_on between w.f and w.t) spend_usd,
    (select coalesce(sum(f_to_pounds(coalesce((p.raw->>'CreatedQuantity')::numeric,0),
              coalesce(nullif(p.raw->>'UnitOfMeasureName',''),'Grams'))),0)
       from metrc_packages p, w
      where nullif(p.raw->>'SourceHarvestNames','') is not null
        and nullif(p.raw->>'SourcePackageLabels','') is null
        and f_is_weight(coalesce(nullif(p.raw->>'UnitOfMeasureName',''),'Grams'))
        and (p.raw->>'PackagedDate')::date between w.f and w.t) produced_lb,
    (select coalesce(sum(s.pounds),0) from v_forensic_sold_by_tag s, w
      where s.invoice_match='NO APEX INVOICE' and not s.internal_transfer
        and s.shipped_on between w.f and w.t) noinvoice_lb,
    (select coalesce(sum(coalesce(x.exit_lb,0)),0) from v_third_party_forensic x, w
      where x.exit_shipped_on between w.f and w.t) tp_resold_lb,
    (select count(distinct fingerprint) from watchdog_findings, w
      where observed_at::date between w.f and w.t) findings),
k as not materialized (select '(sold and shipped|third-party spend|produced from our harvests|no apex invoice|resold at markup|watchdog findings)' pat),
led as not materialized (
  select p.tag, p.uom, p.lab_testing_state,
         coalesce(p.raw #>> '{Item,ProductCategoryName}','(uncategorised)') as category,
         p.item_name,
         p.packaged_on,
         least(nullif(p.raw->>'FinishedDate','')::date, nullif(p.raw->>'ArchivedDate','')::date) as closed_on,
         nullif(p.raw->>'LabTestingStateDate','')::date    as submitted_on,
         nullif(p.raw->>'LabTestingRecordedDate','')::date as result_on,
         case when least(nullif(p.raw->>'FinishedDate','')::date, nullif(p.raw->>'ArchivedDate','')::date) is not null
              then coalesce((p.raw->>'InitialQuantity')::numeric, coalesce(p.quantity,0))
              else coalesce(p.quantity,0) end as qty_basis
  from (select distinct on (d.tag) d.* from metrc_packages d
        order by d.tag, (coalesce(d.quantity,0) > 0 and not coalesce((d.raw->>'IsFinished')::boolean,false)) desc,
                 (d.source_state = 'active') desc nulls last, d.synced_at desc nulls last) p
),
rate as not materialized (
  select cost_per_pound from cost_model where scope='cultivation' order by effective_from desc limit 1
),
asof as not materialized (
  select
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.category ilike 'bud%' and l.packaged_on <= w.t
        and (l.closed_on is null or l.closed_on > w.t))                              as dried_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t)) as total_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t)
        and l.lab_testing_state = 'TestPassed' and l.result_on <= w.t)               as sellable_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l join stock_ageing_policy pol on pol.category = l.category, w
      where l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t)
        and pol.ages and ((w.t - l.packaged_on) * interval '1 day') > pol.stale_after) as ageing_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.category ~* 'concentrate' and l.packaged_on <= w.t
        and (l.closed_on is null or l.closed_on > w.t))                              as conc_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where (l.category ~* 'fresh.?frozen' or l.item_name ~* 'fresh.?frozen')
        and l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t))     as ff_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where (l.category ~* '(shake|trim)' or l.item_name ~* '(shake|trim)')
        and l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t))     as shake_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where (l.category ~* '(shake|trim)' or l.item_name ~* '(shake|trim)')
        and l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t)
        and l.lab_testing_state='TestPassed' and l.result_on <= w.t)                 as shake_passed_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.category ~* 'pre.?roll' and l.packaged_on <= w.t
        and (l.closed_on is null or l.closed_on > w.t))                              as preroll_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.category ~* 'pre.?roll' and l.packaged_on <= w.t
        and (l.closed_on is null or l.closed_on > w.t)
        and (l.submitted_on is null or l.submitted_on > w.t))                        as preroll_untested_lb,
    (select count(*) from v_moisture_accounting m, w
      where m.harvest_start_date <= w.t and (m.finished::date is null or m.finished::date > w.t)) as open_h,
    (select coalesce(round(sum(m.wet_lb),1),0) from v_moisture_accounting m, w
      where m.harvest_start_date <= w.t and (m.finished::date is null or m.finished::date > w.t)) as open_wet_lb,
    (select count(*) from v_moisture_accounting m, w
      where m.harvest_start_date <= w.t and (m.finished::date is null or m.finished::date > w.t)
        and (w.t - m.harvest_start_date) > f_rule('harvest_open_max_days'))          as open_too_long,
    (select coalesce(round(sum(greatest(m.wet_lb - m.packaged_lb - m.recorded_waste_lb - m.moisture_lb, 0)),1),0)
       from v_moisture_accounting m, w
      where m.finished::date <= w.t and coalesce(m.moisture_lb,0) <= 0)              as phantom_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.submitted_on <= w.t and (l.result_on is null or l.result_on > w.t)
        and (l.closed_on is null or l.closed_on > w.t))                              as at_lab_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.packaged_on <= w.t and (l.closed_on is null or l.closed_on > w.t)
        and (l.submitted_on is null or l.submitted_on > w.t))                        as unsubmitted_lb,
    (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
       from led l, w where l.result_on <= w.t and l.lab_testing_state = 'TestFailed'
        and (l.closed_on is null or l.closed_on > w.t))                              as failed_lb
),
wflow as not materialized (
  select
    (select round(avg(h.dry_days_to_first_package) filter (where h.dry_days_to_first_package is not null),1)
       from v_harvest_forensic h, w where h.harvest_closed between w.f and w.t)      as avg_dry,
    (select count(*) from v_harvest_forensic h, w
      where h.harvest_closed between w.f and w.t
        and h.dry_days_to_first_package::numeric > f_rule('dry_window_max_days'))    as dried_long,
    (select round(avg(h.conversion_pct) filter (where h.harvest_closed is not null),1)
       from v_harvest_forensic h, w where h.harvest_closed between w.f and w.t)      as conv,
    /* APEX ROAD, ONE ROW PER INVOICE. mv_forensic_sales is one row per LINE
       carrying the invoice total on every line — a bare sum multiplies each
       invoice by its line count (the 10x trap caught 19 Aug 2026). */
    (select coalesce(round(sum(d.total_usd),0),0)
       from (select distinct on (s.invoice_number) s.invoice_number, s.total_usd, s.order_date
               from mv_forensic_sales s where not s.cancelled order by s.invoice_number) d, w
      where d.order_date between w.f and w.t)                                        as apex_rev,
    (select count(*)
       from (select distinct on (s.invoice_number) s.invoice_number, s.order_date
               from mv_forensic_sales s where not s.cancelled order by s.invoice_number) d, w
      where d.order_date between w.f and w.t)                                        as apex_n,
    (select coalesce(round(sum(nullif(t4.source_row->>'Receiver Wholesale Price','')::numeric),0),0)
       from metrc_rpt_package_transfers t4, w
      where f_is_ours(coalesce(nullif(t4.source_row->>'Origin Lic.',''), t4.licence))
        and not f_is_ours(coalesce(nullif(t4.source_row->>'Dest. Lic.',''), t4.destination_licence))
        and coalesce(t4.source_row->>'Voided','False') <> 'True'
        and t4.received_on between w.f and w.t)                                      as metrc_decl,
    (select count(distinct t3.manifest_number) from metrc_rpt_package_transfers t3, w
      where t3.received_on between w.f and w.t
        and coalesce(t3.source_row->>'Voided','False') <> 'True')                    as manifests_n,
    (select count(*) from v_forensic_sold_by_tag s, w
      where s.shipped_on between w.f and w.t)                                        as sale_lines,
    (select count(*) from v_forensic_sold_by_tag s, w
      where s.invoice_match='NO APEX INVOICE' and not s.internal_transfer
        and s.shipped_on between w.f and w.t)                                        as noinv_lines
),
basis as not materialized (select '  ·  AS OF ' || (select t from w) || ', derived from the ledger. Quantity basis: initial for packages that later closed, current for those still open — the mirror holds no per-day quantities.' note),
wnote as not materialized (select '  ·  Recomputed strictly for ' || (select f from w) || ' to ' || (select t from w) || '.' note),
main as (
select b.department, b.ord,
       case when b.kpi ilike '%year to date%' and not (select is_all_time from w)
            then replace(b.kpi, ', year to date', ' in the selected range')
            else b.kpi end                                              as kpi,
       case
         when b.kpi ilike '%sold and shipped%'           then round((select sold_lb from flow)::numeric,1)
         when b.kpi ilike '%third-party spend%'          then round((select spend_usd from flow)::numeric,0)
         when b.kpi ilike '%produced from our harvests%' then round((select produced_lb from flow)::numeric,1)
         when b.kpi ilike '%no apex invoice%' and b.department <> 'Sales & Cash' then round((select noinvoice_lb from flow)::numeric,1)
         when b.kpi ilike '%resold at markup%'           then round((select tp_resold_lb from flow)::numeric,1)
         when b.kpi ilike '%watchdog findings%'          then (select findings from flow)::numeric
         when b.department = 'Sales & Cash' and b.ord = 70 then (select apex_rev from wflow)
         when b.department = 'Sales & Cash' and b.ord = 72 then (select sale_lines from wflow)::numeric
         when b.department = 'Sales & Cash' and b.ord = 73 then (select noinv_lines from wflow)::numeric
         when not (select is_all_time from w) and b.department = 'Sales & Cash' and b.ord = 71 then (select manifests_n from wflow)::numeric
         when not (select is_all_time from w) and b.department = 'Cultivation' and b.kpi = 'Average dry time'            then coalesce((select avg_dry from wflow), 0)
         when not (select is_all_time from w) and b.department = 'Cultivation' and b.kpi = 'Harvests dried too long'     then (select dried_long from wflow)::numeric
         when not (select is_all_time from w) and b.department = 'Cultivation' and b.kpi = 'Conversion, dried flower only' then coalesce((select conv from wflow), 0)
         when not (select ends_today from w) then
           case
             when b.kpi = 'Dried flower on hand'                                     then (select dried_lb from asof)
             when b.kpi = 'In the rooms, dry-equivalent'                             then (select open_wet_lb from asof)
             when b.kpi = 'Harvests open too long'                                   then (select open_too_long from asof)::numeric
             when b.kpi = 'Moisture loss not recorded'                               then (select phantom_lb from asof)
             when b.kpi in ('Out at the laboratory, no result','Out for testing')    then (select at_lab_lb from asof)
             when b.kpi = 'Never submitted for testing'                              then (select unsubmitted_lb from asof)
             when b.kpi = 'Failed testing on hand'                                   then (select failed_lb from asof)
             when b.department='Inventory' and b.kpi = 'Total on hand, dry-equivalent' then (select total_lb from asof)
             when b.department='Inventory' and b.kpi = 'Sellable right now'          then (select sellable_lb from asof)
             when b.department='Inventory' and b.kpi = 'Ageing stock'                then (select ageing_lb from asof)
             when b.department='Manufacturing' and b.kpi = 'Concentrate on hand'     then (select conc_lb from asof)
             when b.department='Manufacturing' and b.kpi = 'Fresh frozen on hand'    then (select ff_lb from asof)
             when b.department='Manufacturing' and b.kpi = 'Fresh frozen dry-equivalent' then round((select ff_lb from asof) / nullif(f_rule('fresh_frozen_wet_to_dry'),0), 1)
             when b.department='Manufacturing' and b.kpi = 'Shake and trim on hand'  then (select shake_lb from asof)
             when b.department='Infused Pre-Rolls & Flower' and b.kpi = 'Pre-rolls on hand' then (select preroll_lb from asof)
             when b.department='Infused Pre-Rolls & Flower' and b.kpi = 'Pre-rolls never tested' then (select preroll_untested_lb from asof)
             when b.department='Infused Pre-Rolls & Flower' and b.kpi = 'Shake and trim available' then (select shake_passed_lb from asof)
             when b.department='Finance' and b.kpi = 'Value of stock on hand'        then round((select total_lb from asof) * (select cost_per_pound from rate), 0)
             when b.department='Finance' and b.kpi = 'Failed testing value'          then round((select failed_lb from asof) * (select cost_per_pound from rate), 0)
             when b.department='Finance' and b.kpi = 'Untested stock value'          then round((select unsubmitted_lb from asof) * (select cost_per_pound from rate), 0)
             else b.value end
         else b.value end                                               as value,
       b.unit, b.tone,
       case
         when b.department = 'Sales & Cash' and b.ord = 70
           then 'TWO ANSWERS, BOTH SHOWN. APEX (the sales source of record): $'
                || to_char((select apex_rev from wflow), 'FM999,999,990') || ' across '
                || (select apex_n from wflow) || ' invoices, one row per invoice, cancelled excluded. '
                || 'METRC declared-price road: $' || to_char((select metrc_decl from wflow), 'FM999,999,990')
                || ' — a compliance declaration, never a realised sale. The gap is the reconciliation work, '
                || 'not a rounding.' || (select note from wnote)
         when b.department = 'Sales & Cash' and b.ord in (72,73)
           then b.context || (select note from wnote)
         when not (select is_all_time from w) and b.department = 'Sales & Cash' and b.ord = 71
           then b.context || (select note from wnote)
         when not (select is_all_time from w) and b.department = 'Cultivation'
              and b.kpi in ('Average dry time','Harvests dried too long','Conversion, dried flower only')
           then b.context || (select note from wnote) || ' Harvests CLOSED inside the window.'
         when not (select ends_today from w) and (
              b.kpi in ('Dried flower on hand','In the rooms, dry-equivalent','Harvests open too long',
                        'Moisture loss not recorded','Out at the laboratory, no result','Out for testing',
                        'Never submitted for testing','Failed testing on hand')
              or (b.department='Inventory' and b.kpi in ('Total on hand, dry-equivalent','Sellable right now','Ageing stock'))
              or (b.department='Manufacturing' and b.kpi in ('Concentrate on hand','Fresh frozen on hand','Fresh frozen dry-equivalent','Shake and trim on hand'))
              or (b.department='Infused Pre-Rolls & Flower')
              or (b.department='Finance')) then
           case when b.kpi = 'In the rooms, dry-equivalent'
                then 'WET pounds across ' || (select open_h from asof) || ' harvests open at the date shown. '
                     || 'Dry-equivalent exists only once moisture is recorded at close, so a past date shows wet.'
                when b.department='Finance'
                then 'TODAY''S owner cost rate applied to the as-of pounds — no historical rate table exists yet.'
                when b.department='Inventory' and b.kpi = 'Ageing stock'
                then 'Category ageing policy applied to the as-of position. Holding-room suspensions are today''s — the mirror holds no room history.'
                else b.context end || (select note from basis)
         when not (select ends_today from w) and b.department='Inventory' and b.kpi in ('On a truck right now','Cross-licence tags')
           then b.context || '  ·  AS AT TODAY ONLY: in-transit state exists only in the current sync — the mirror holds no per-day transit ledger.'
         when not (select ends_today from w) and b.department='Metrc'
           then b.context || '  ·  Mirror totals are sync-state, not dated events — they cannot be restated.'
         else
           b.context ||
             case
               when b.kpi ~* (select pat from k)
                 then '  ·  Recomputed for ' || (select f from w) || ' to ' || (select t from w) || '.'
               when b.kpi ilike '%inventory variance%'
                 then '  ·  ALL TIME against today''s count. A variance needs an opening position, '
                      || 'and no counted position exists for a past date — so this tile does not move with the range.'
               else '  ·  Position as at today.'
             end
       end                                                              as context,
       b.drill, b.computed_at,
       case when b.kpi ~* (select pat from k) then 'FLOW'
            when b.department = 'Sales & Cash' and b.ord in (70,72,73) then 'FLOW'
            when b.kpi ilike '%inventory variance%' then 'ALL TIME ONLY'
            when not (select ends_today from w) then 'POSITION AS OF ' || (select t from w)
            else 'POSITION' end                                         as tile_kind,
       case when b.kpi ~* (select pat from k) then true
            when b.kpi ilike '%inventory variance%' then false
            else true end                                               as honours_range,
       case when b.kpi ~* (select pat from k) or (b.department='Sales & Cash' and b.ord in (70,72,73)) then 'Recomputed for the selected range'
            when b.kpi ilike '%inventory variance%' then 'All time — a variance needs an opening position'
            when not (select ends_today from w) then 'Restated as of ' || (select t from w) || ' from the ledger'
            else 'Position as at today' end                             as range_note
from mv_department_dashboard b
where b.department = p_dept
),
extras as (
  select 'Command'::text as department, x.ord, x.kpi, x.value, x.unit, 'info'::text as tone,
         x.context || '  ·  Computed strictly from events dated ' || (select f from w) || ' to ' || (select t from w) || '.' as context,
         x.drill, now() as computed_at, 'FLOW'::text as tile_kind, true as honours_range,
         'Recomputed for the selected range'::text as range_note
  from (
    select 91 as ord, 'Harvests cut in the window' as kpi,
           (select count(*)::numeric from v_moisture_accounting m, w where m.harvest_start_date between w.f and w.t) as value,
           '' as unit,
           'Wet weight cut: ' || (select coalesce(round(sum(m.wet_lb),1),0) from v_moisture_accounting m, w
              where m.harvest_start_date between w.f and w.t) || ' lb.' as context,
           'moisture_loss_register' as drill
    union all
    select 92, 'Ran past the open limit in the window',
           (select count(*)::numeric from v_moisture_accounting m, w
             where m.finished::date between w.f and w.t
               and (m.finished::date - m.harvest_start_date) > f_rule('harvest_open_max_days')),
           '',
           'Harvests CLOSED inside the window whose open duration exceeded the owner rule of '
             || f_rule('harvest_open_max_days') || ' days.',
           'harvest_issues'
    union all
    select 93, 'Water recorded in the window',
           (select coalesce(round(sum(m.moisture_lb),1),0) from v_moisture_accounting m, w
             where m.finished::date between w.f and w.t),
           'lb',
           'Moisture written on the ' || (select count(*) from v_moisture_accounting m, w
              where m.finished::date between w.f and w.t) || ' harvests closed inside the window.',
           'moisture_loss_register'
    union all
    select 94, 'Failed testing in the window',
           (select coalesce(round(sum(f_to_pounds(l.qty_basis, l.uom)) filter (where f_is_weight(l.uom)),1),0)
              from led l, w where l.lab_testing_state='TestFailed' and l.result_on between w.f and w.t),
           'lb',
           (select count(*) from led l, w where l.lab_testing_state='TestFailed' and l.result_on between w.f and w.t)
             || ' packages whose FAILED result was recorded inside the window (weight-based pounds shown).',
           'failed_testing_by_origin'
    union all
    select 95, 'Submitted for testing in the window',
           (select count(*)::numeric from led l, w
             where l.submitted_on between w.f and w.t and l.lab_testing_state is distinct from 'NotSubmitted'),
           '',
           'Packages whose testing submission date falls inside the window.',
           'lab_results'
  ) x
  where p_dept = 'Command' and not (select is_all_time from w)
)
select * from main
union all
select * from extras
order by ord;
$function$
;
CREATE OR REPLACE FUNCTION public.f_detect_tag_column(p_source uuid)
 RETURNS TABLE(sheet_column text, rows_tested integer, tags_matched integer, matched_metrc integer, confidence text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  with sample as (select data from public.sheet_rows where source_id = p_source limit 300),
  cols as (select distinct k from sample, lateral jsonb_object_keys(data) k),
  scored as (
    select c.k as col,
      count(*) as rows_tested,
      count(*) filter (where trim(s.data ->> c.k) ~ '^1A4[A-Z0-9]{21}$') as tags_matched,
      count(*) filter (where exists (
        select 1 from public.metrc_packages p
        where p.raw->>'Label' = trim(s.data ->> c.k))) as matched_metrc
    from cols c cross join sample s group by c.k)
  select col, rows_tested, tags_matched, matched_metrc,
    case
      when matched_metrc::numeric / nullif(rows_tested,0) >= 0.8 then 'CERTAIN — matches real Metrc package tags'
      when tags_matched::numeric / nullif(rows_tested,0) >= 0.8 then 'LIKELY — correct tag format but not found in Metrc'
      when tags_matched > 0 then 'POSSIBLE — some values look like tags'
      else 'NO' end
  from scored where tags_matched > 0 or matched_metrc > 0
  order by matched_metrc desc, tags_matched desc;
$function$
;
CREATE OR REPLACE FUNCTION public.f_document_url(p_storage_path text, p_download boolean DEFAULT false)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case when p_storage_path is null then null else
    'https://fxetuqjryttnypgepsru.supabase.co/functions/v1/document?path='
    || p_storage_path || case when p_download then '&download=1' else '' end
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_drain_punch_queue(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_emp uuid; v_entry uuid; v_src text;
        v_ok int := 0; v_dup int := 0; v_bad int := 0; v_err int := 0;
begin
  for r in select * from public.punch_queue
            where status='queued' order by punched_at limit p_limit
  loop
    select id into v_emp from public.employees
     where (r.login_id is not null and upper(login_id) = upper(r.login_id))
        or (r.badge_code is not null and badge_code = r.badge_code);

    if v_emp is null then
      update public.punch_queue set status='rejected', error='no matching employee',
             attempts = attempts + 1 where id = r.id;
      v_bad := v_bad + 1; continue;
    end if;

    if exists (select 1 from public.time_entries t
                where t.employee_id = v_emp
                  and (abs(extract(epoch from (t.clock_in - r.punched_at))) < 60
                    or abs(extract(epoch from (coalesce(t.clock_out, r.punched_at) - r.punched_at))) < 60)) then
      update public.punch_queue set status='duplicate' where id = r.id;
      v_dup := v_dup + 1; continue;
    end if;

    select coalesce(d.kind,'kiosk') into v_src
    from public.punch_devices d where d.id = r.device_id;
    if v_src not in ('kiosk','scanner') then v_src := 'kiosk'; end if;

    begin
      select f.entry_id into v_entry
      from public.f_punch(v_emp, r.kind, v_src, r.device_id,
                          r.lat, r.lon, r.accuracy_m, r.punched_at) f;
      update public.punch_queue set status='applied', time_entry_id = v_entry,
             attempts = attempts + 1, error = null where id = r.id;
      v_ok := v_ok + 1;
    exception when others then
      update public.punch_queue
         set status = case when attempts + 1 >= 5 then 'rejected' else 'queued' end,
             error = SQLERRM, attempts = attempts + 1 where id = r.id;
      v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('applied', v_ok, 'duplicates', v_dup,
                            'no_match', v_bad, 'errored', v_err);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_duplicate_audit()
 RETURNS TABLE(table_name text, key_columns text, dup_groups bigint, extra_rows bigint, unique_indexes bigint)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; q text; g bigint; x bigint; u bigint;
begin
  for r in select dk.table_name t, dk.key_columns k from public.duplicate_key dk order by dk.table_name loop
    if to_regclass('public.' || quote_ident(r.t)) is null then continue; end if;
    q := format(
      'select coalesce(count(*),0), coalesce(sum(n)-count(*),0) from (select %s, count(*) n from public.%I group by %s having count(*)>1) z',
      array_to_string(array(select quote_ident(c) from unnest(r.k) c), ', '), r.t,
      array_to_string(array(select quote_ident(c) from unnest(r.k) c), ', '));
    execute q into g, x;
    select count(*) into u from pg_indexes i
      where i.schemaname='public' and i.tablename=r.t and i.indexdef ilike '%unique%';
    table_name := r.t; key_columns := array_to_string(r.k, ' + ');
    dup_groups := g; extra_rows := x; unique_indexes := u;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_employee_capacity_upd()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_emp   uuid;
  v_days  integer;
  v_per   numeric;
  v_start time := time '07:00';
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to change work schedules. Owner, HR or admin only.'
      using errcode = '42501';
  end if;

  select id into v_emp from public.employees where employee_code = old.employee_code;
  if v_emp is null then
    raise exception 'No employee with code %', old.employee_code;
  end if;

  if new.payroll_target_hours is distinct from old.payroll_target_hours then
    update public.employees set weekly_target_hours = new.payroll_target_hours where id = v_emp;
  end if;

  -- Capacity is a SUM over employee_work_schedules, so a new weekly total
  -- has to be distributed back across days. Even split over the requested
  -- day count, Monday first. Anyone needing uneven days edits the
  -- underlying rows directly — this is the sane default, not the only way.
  if new.weekly_capacity_hours is distinct from old.weekly_capacity_hours
     or new.days_per_week is distinct from old.days_per_week then

    v_days := coalesce(new.days_per_week, old.days_per_week, 5);
    if v_days < 1 or v_days > 7 then
      raise exception 'Days per week must be 1 to 7, got %', v_days;
    end if;
    if coalesce(new.weekly_capacity_hours,0) <= 0 then
      raise exception 'Weekly capacity must be greater than zero';
    end if;

    v_per := round(new.weekly_capacity_hours::numeric / v_days, 2);
    if v_per > 24 then
      raise exception 'That is % hours per day across % days', v_per, v_days;
    end if;

    delete from public.employee_work_schedules where employee_id = v_emp;
    insert into public.employee_work_schedules (employee_id, weekday, start_time, end_time)
    select v_emp, g, v_start, v_start + (v_per || ' hours')::interval
    from generate_series(1, v_days) g;
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_employee_login_id_bi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.login_id is null and new.full_name is not null then
    begin
      new.login_id := public.f_next_login_id(new.full_name);
    exception when others then
      new.login_id := null;   -- unparseable name: leave it for HR rather than block the hire
    end;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_endpoint_allowed(p_licence text, p_endpoint text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select allowed from metrc_endpoint_capability
      where licence = p_licence and endpoint = p_endpoint),
    true);   -- unknown combinations are permitted; only explicit denials block
$function$
;
CREATE OR REPLACE FUNCTION public.f_endpoint_denial_reason(p_licence text, p_endpoint text)
 RETURNS text
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select why from metrc_endpoint_capability
   where licence = p_licence and endpoint = p_endpoint and not allowed;
$function$
;
CREATE OR REPLACE FUNCTION public.f_explain_late(p_time_entry_id uuid, p_reason_code text, p_explanation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_t public.time_entries%rowtype; v_occ uuid;
begin
  select * into v_t from public.time_entries where id = p_time_entry_id;
  if v_t.id is null then raise exception 'No such punch.'; end if;
  if coalesce(v_t.late_minutes,0) <= 0 then
    return jsonb_build_object('ok', true, 'note', 'not late — nothing to explain');
  end if;
  if v_t.work_date <> current_date then
    raise exception 'A reason can only be given on the day. Ask HR to correct an older punch.';
  end if;
  if length(btrim(coalesce(p_explanation,''))) < 4 or coalesce(p_reason_code,'') = '' then
    raise exception 'A reason code and a short explanation are both required.';
  end if;

  select id into v_occ from public.attendance_occurrences
   where employee_id = v_t.employee_id and work_date = v_t.work_date and kind = 'late'
   order by created_at desc limit 1;

  if v_occ is not null then
    update public.attendance_occurrences
       set reason_code = p_reason_code,
           explanation = btrim(p_explanation),
           status = 'awaiting_explanation'
     where id = v_occ;
  else
    insert into public.attendance_occurrences
      (employee_id, work_date, kind, minutes, reason_code, explanation, points, status, time_entry_id)
    select v_t.employee_id, v_t.work_date, 'late', v_t.late_minutes,
           p_reason_code, btrim(p_explanation),
           (select points_late from public.attendance_policy limit 1),
           'awaiting_explanation', v_t.id
    returning id into v_occ;
  end if;

  return jsonb_build_object('ok', true, 'occurrence_id', v_occ,
    'note', 'Recorded. A manager decides whether it is excused — an explanation is '
            'not self-approval, and the points stand until someone rules on them.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_facility_type(p_licence text)
 RETURNS text
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select lt.facility_type
  from licence_type_prefix lt
  where upper(btrim(coalesce(p_licence,''))) like lt.prefix || '%'
  order by length(lt.prefix) desc
  limit 1
$function$
;
CREATE OR REPLACE FUNCTION public.f_field_coverage(p_pattern text DEFAULT 'metrc_rpt_%'::text)
 RETURNS TABLE(table_name text, column_name text, data_type text, rows bigint, non_null bigint, pct_filled numeric, verdict text)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE
AS $function$
declare r record; n bigint; f bigint;
begin
  for r in
    select c.table_name::text as t, c.column_name::text as c, c.data_type::text as d
    from information_schema.columns c
    join information_schema.tables tb
      on tb.table_schema = c.table_schema and tb.table_name = c.table_name
    where c.table_schema = 'public'
      and tb.table_type = 'BASE TABLE'
      and c.table_name like p_pattern
    order by c.table_name, c.ordinal_position
  loop
    execute format('select count(*), count(%I) from public.%I', r.c, r.t) into n, f;
    table_name := r.t; column_name := r.c; data_type := r.d;
    rows := n; non_null := f;
    pct_filled := case when n = 0 then null else round(100.0 * f / n, 1) end;
    verdict := case
      when n = 0            then 'table is empty'
      when f = 0            then 'ALWAYS NULL — the OS has this column and never captures it'
      when f < n * 0.02     then 'barely populated (<2%)'
      when f < n            then 'partially populated'
      else 'fully populated' end;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_fiscal_year_start(p_on date DEFAULT CURRENT_DATE)
 RETURNS date
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select make_date(
    case when extract(month from p_on)::int >= coalesce((select value::int from configurations
                                                          where key='fiscal_year_start_month'), 1)
         then extract(year from p_on)::int else extract(year from p_on)::int - 1 end,
    coalesce((select value::int from configurations where key='fiscal_year_start_month'), 1),
    1);
$function$
;
CREATE OR REPLACE FUNCTION public.f_flower_room_from_harvest_name(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select 'F' || substring(regexp_replace(p_name, '^.*\d{8}', ''), '[fF] ?([1-4])')
$function$
;
CREATE OR REPLACE FUNCTION public.f_guard_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp date; v_name text; v_date date;
begin
  select e.badge_expires, e.full_name into v_exp, v_name
  from public.employees e where e.id = new.employee_id;
  select o.work_date into v_date from public.open_shifts o where o.id = new.open_shift_id;

  if v_exp is not null and v_date is not null and v_exp < v_date then
    raise exception
      'Cannot claim that shift: % has an agent registration that expires on %, before the shift on %.',
      v_name, v_exp, v_date using errcode='23514';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_guard_occurrence_requires_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_req boolean; v_name text;
begin
  select requires_clock_in, full_name into v_req, v_name
  from public.employees where id = new.employee_id;

  if v_req is false then
    raise exception
      'Cannot raise an attendance occurrence for %: they are not required to clock in. Change it in Settings if that is wrong.',
      v_name using errcode='23514';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_guard_offboarding_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_open text; v_name text;
begin
  if new.status <> 'complete' or coalesce(old.status,'') = 'complete' then
    return new;
  end if;

  select e.full_name into v_name from public.employees e where e.id = new.employee_id;

  select string_agg(s.title, '; ' order by s.ordinal) into v_open
  from public.lifecycle_progress p
  join public.lifecycle_steps s on s.id = p.step_id
  where p.employee_id = new.employee_id and s.phase = 'offboarding'
    and s.blocks_close and s.active and p.done_at is null and p.na_reason is null;

  if v_open is not null then
    raise exception
      'Cannot close the departure for %: outstanding obligations — %. Mark each done, or record why it does not apply.',
      coalesce(v_name,'this employee'), v_open using errcode='23514';
  end if;

  -- Belt and braces on the two that carry a deadline, whether or not a
  -- checklist row was ever raised for this person.
  if new.ccc_deactivated_on is null then
    raise exception
      'Cannot close: the Cannabis Agent Registration has not been deactivated in Metrc. An active registration for someone who has left is a finding.'
      using errcode='23514';
  end if;
  if new.system_access_revoked_on is null then
    raise exception
      'Cannot close: system access has not been revoked. Termination must revoke at the identity layer.'
      using errcode='23514';
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_guard_schedulable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp date; v_badge text; v_name text; v_status text; v_req text; v_steps text;
begin
  select e.badge_expires, e.metrc_agent_badge, e.full_name, e.status::text
    into v_exp, v_badge, v_name, v_status
  from public.employees e where e.id = new.employee_id;

  if v_name is null then
    raise exception 'No employee record for that id.' using errcode='23503';
  end if;
  if v_status <> 'active' then
    raise exception 'Cannot schedule %: they are not an active employee.', v_name
      using errcode='23514';
  end if;
  if v_badge is null and v_exp is null then
    raise exception
      'Cannot schedule %: no Cannabis Agent Registration on file. A person without a registration cannot legally be on the floor.',
      v_name using errcode='23514';
  end if;
  if v_exp is not null and v_exp < new.work_date then
    raise exception
      'Cannot schedule % on %: their agent registration expired on %. They cannot legally work that day.',
      v_name, new.work_date, v_exp using errcode='23514';
  end if;

  select string_agg(cr.name, ', ') into v_req
  from public.employee_compliance ec
  join public.compliance_requirements cr on cr.id = ec.requirement_id
  where ec.employee_id = new.employee_id and cr.blocks_work and cr.active
    and (ec.status = 'expired'
         or (ec.status = 'held' and ec.expires_on is not null and ec.expires_on < new.work_date));
  if v_req is not null then
    raise exception 'Cannot schedule % on %: expired requirement — %.',
      v_name, new.work_date, v_req using errcode='23514';
  end if;

  -- NEW: onboarding steps marked blocks_start must be done before this person
  -- can be scheduled at all. I-9, agent registration, gowning SOP, PIN.
  select string_agg(s.title, '; ' order by s.ordinal) into v_steps
  from public.lifecycle_progress p
  join public.lifecycle_steps s on s.id = p.step_id
  where p.employee_id = new.employee_id and s.phase = 'onboarding'
    and s.blocks_start and s.active and p.done_at is null and p.na_reason is null;

  if v_steps is not null then
    raise exception
      'Cannot schedule %: onboarding is not complete. Outstanding — %.',
      v_name, v_steps using errcode='23514';
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_harvest_accountable(p_harvest text, p_flower_room text, p_drying_room text, p_finished date, p_stage text)
 RETURNS TABLE(employee_id uuid, full_name text, basis text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select e.id, e.full_name,
         case when r.scope = 'harvest' then 'assigned to this harvest directly'
              else 'assigned to ' || coalesce(r.flower_room, r.drying_room)
                   || ' from ' || r.effective_from
                   || coalesce(' to ' || r.effective_to, ' (still current)') end
  from harvest_responsibility r
  join employees e on e.id = r.employee_id
  where r.stage = p_stage
    and (
      (r.scope = 'harvest' and r.harvest_name = p_harvest)
      or (r.scope = 'room_period'
          and ( (p_stage = 'grow' and r.flower_room  is not distinct from p_flower_room)
             or (p_stage <> 'grow' and r.drying_room is not distinct from p_drying_room) )
          and (p_finished is null or r.effective_from <= p_finished)
          and (r.effective_to is null or p_finished is null or r.effective_to >= p_finished))
    )
  order by (r.scope = 'harvest') desc, r.effective_from desc nulls last
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_harvest_is_fresh_frozen(p_name text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select p_name ~* '(^|[^a-z])FF([^a-z]|$)'
$function$
;
CREATE OR REPLACE FUNCTION public.f_heal_stale_matviews(p_by text DEFAULT 'watcher'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  h         record;
  t0        timestamptz;
  v_healed  int := 0;
  v_failed  int := 0;
  v_chronic int := 0;
  v_names   text[] := '{}';
  v_err     text;
begin
  for h in select * from v_matview_health where is_stale order by matview loop
    t0 := clock_timestamp();
    v_err := null;

    begin
      execute format('select %I(%L)', h.refresh_fn, p_by);
    /* query_canceled EXPLICITLY — WHEN OTHERS does not catch a statement timeout, and a
       timeout is the failure this whole mechanism was built for. */
    exception when query_canceled or others then
      v_err := left(sqlerrm, 400);
    end;

    if v_err is null then
      insert into matview_refresh_run (matview, started_at, finished_at, ms, ok, run_by)
      values (h.matview, t0, clock_timestamp(),
              round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int, true, p_by);
      v_healed := v_healed + 1;
      v_names := v_names || h.matview;

      if h.heals_last_24h + 1 > h.heals_per_day_ok then
        v_chronic := v_chronic + 1;
        insert into watchdog_findings (
          observed_at, fingerprint, severity, what, where_it_is, who_is_accountable,
          when_it_started, why_it_matters, how_it_was_detected, what_to_do,
          the_arithmetic, evidence, record_count, solutions, guard_recommendation)
        values (
          now(), 'matview_chronic_heal|' || h.matview, 'elevated',
          h.matview || ' has gone stale and been auto-healed ' || (h.heals_last_24h + 1)
            || ' times in 24 hours, against a normal of ' || h.heals_per_day_ok
            || '. The numbers on screen are current; the machinery producing them is not well.',
          'Materialised view ' || h.matview || ', refreshed by ' || h.refresh_fn || '.',
          'Agent I, Database COO.',
          'First heal in this window: ' || coalesce(
            (select to_char(min(started_at), 'DD Mon HH24:MI') from matview_refresh_run r
              where r.matview = h.matview and r.run_by = 'watcher'
                and r.started_at > now() - interval '24 hours'), 'unknown'),
          'Healing on repeat converts a visible outage into an invisible chronic one, and '
            || 'the underlying cause — a scheduled refresh that is not completing — goes '
            || 'unfixed because nothing ever surfaces it.',
          'f_heal_stale_matviews compared heals in the last 24h against '
            || 'matview_heal_policy.heals_per_day_ok.',
          'Find why the SCHEDULED refresh is not completing rather than leaving the watcher '
            || 'to carry it. matview_refresh_run holds this view''s durations and errors.',
          (h.heals_last_24h + 1) || ' heals in 24h against a normal of ' || h.heals_per_day_ok
            || '; policy max age ' || h.max_age,
          jsonb_build_object('matview', h.matview, 'heals_24h', h.heals_last_24h + 1,
                             'normal', h.heals_per_day_ok, 'max_age', h.max_age::text,
                             'refresh_fn', h.refresh_fn),
          h.heals_last_24h + 1,
          array[
            'Fix why the scheduled job is not completing — the durations in '
              || 'matview_refresh_run show whether it is slow or erroring.',
            'Give this view its own less frequent job with a longer timeout, as was done '
              || 'for mv_tag_evidence.',
            'Raise max_age in matview_heal_policy if the view genuinely does not need to be '
              || 'that fresh — a real answer, but say so in the why column.'],
          'Do not raise heals_per_day_ok to silence this. The count is the symptom. The '
            || 'watcher is holding this view up by hand and something should be doing it '
            || 'on schedule.');
      end if;

    else
      insert into matview_refresh_run (matview, started_at, finished_at, ms, ok, error, run_by)
      values (h.matview, t0, clock_timestamp(),
              round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int, false, v_err, p_by);
      v_failed := v_failed + 1;

      insert into watchdog_findings (
        observed_at, fingerprint, severity, what, where_it_is, who_is_accountable,
        when_it_started, why_it_matters, how_it_was_detected, what_to_do,
        the_arithmetic, evidence, record_count, solutions, guard_recommendation)
      values (
        now(), 'matview_heal_failed|' || h.matview, 'critical',
        h.matview || ' is stale and the watcher COULD NOT refresh it. The dashboards it '
          || 'feeds are showing old numbers right now.',
        'Materialised view ' || h.matview || ', refresh function ' || h.refresh_fn || '.',
        'Agent I, Database COO.',
        'Last successful computation: ' || coalesce(h.computed_at::text, 'never recorded')
          || '. Age at detection: ' || coalesce(h.age::text, 'unmeasurable') || '.',
        'Every tile fed by this view is presenting a stale figure as a current position — '
          || 'the exact failure found on 17 Aug 2026 when the Command dashboard read '
          || 'DATA 3 DAYS OLD after 477 silent refresh failures.',
        'f_heal_stale_matviews attempted the refresh and it errored.',
        'Read the error below and fix the refresh. Until it succeeds, every figure from '
          || 'this view must be treated as of ' || coalesce(h.computed_at::text, 'an unknown time') || '.',
        'Policy max age ' || h.max_age || ', actual age ' || coalesce(h.age::text, 'unmeasurable'),
        jsonb_build_object('matview', h.matview, 'error', v_err,
                           'refresh_fn', h.refresh_fn, 'age', h.age::text),
        1,
        array[
          'Fix the refresh — the error text is on this finding.',
          'If it is a timeout, give the view its own job with a longer statement_timeout '
            || 'SET BY THE JOB, not inside the function — it cannot extend a statement '
            || 'already running.',
          'If the view is no longer needed, retire it and remove its policy row rather than '
            || 'leaving a permanently failing heal.'],
        'Do not deactivate the policy row to stop the alert. A view nobody refreshes and '
          || 'nobody watches is how the dashboard came to be three days old.');
    end if;
  end loop;

  return jsonb_build_object(
    'checked', (select count(*) from v_matview_health),
    'healed', v_healed, 'healed_views', v_names,
    'heal_failed', v_failed, 'chronic', v_chronic,
    'note', case
      when v_failed > 0 then 'A refresh FAILED — a critical finding is open and the affected dashboards are stale.'
      when v_chronic > 0 then 'Healed, but this view is being healed too often. A finding is open.'
      when v_healed > 0 then 'Stale views were healed. Nothing is presenting old numbers as current.'
      else 'Nothing was stale.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_audit_pack(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to, 'generated_at', now()),
    'agents', (select jsonb_agg(jsonb_build_object(
        'name', full_name, 'employee_code', employee_code,
        'agent_licence', metrc_agent_badge, 'expires', badge_expires,
        'status', status::text,
        'valid_through_period', (badge_expires is not null and badge_expires >= p_to)))
      from public.employees where status::text = 'active'),
    'licences_expiring_in_period', (select count(*) from public.employees
       where status::text='active' and badge_expires between p_from and p_to),
    'training_evidence', (select jsonb_agg(jsonb_build_object(
        'employee', full_name, 'document', title, 'version', version,
        'signed_at', signed_at, 'state', state))
      from public.v_document_compliance),
    'documents_unsigned', (select count(*) from public.v_document_compliance where state <> 'signed'),
    'incidents', (select jsonb_agg(jsonb_build_object(
        'reference', incident_no, 'occurred', occurred_at, 'kind', kind,
        'severity', severity, 'osha_recordable', osha_recordable,
        'ccc_reportable', ccc_reportable, 'status', status))
      from public.hr_incidents where occurred_at::date between p_from and p_to),
    'osha_recordable_count', (select count(*) from public.hr_incidents
       where occurred_at::date between p_from and p_to and osha_recordable),
    'ccc_reportable_count', (select count(*) from public.hr_incidents
       where occurred_at::date between p_from and p_to and ccc_reportable),
    'offboarding_obligations_open', (select count(*) from public.v_offboarding_open),
    'lifecycle_legal_outstanding', (select count(*) from public.v_lifecycle_open where is_legal)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_hr_deliver_all()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m record; v_people int; v_batch int; v_msgs int := 0; v_rows int := 0; v_skipped int := 0;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to deliver HR messages.' using errcode='42501';
  end if;

  for m in
    select * from public.hr_message
     where approved_at is not null and sent_at is null and cancelled_at is null
     order by created_at
  loop
    insert into public.hr_message_recipient (message_id, employee_id)
    select m.id, r from public.f_resolve_audience(m.audience, m.employee_id) r
    on conflict (message_id, employee_id) do nothing;
    get diagnostics v_people = row_count;

    if v_people = 0 and not exists (
         select 1 from public.hr_message_recipient where message_id = m.id) then
      -- An audience nobody matches is a drafting error, not a delivery. Leave it
      -- unsent and report it rather than marking it done.
      v_skipped := v_skipped + 1;
      continue;
    end if;

    update public.hr_message_recipient
       set delivered_at = now()
     where message_id = m.id and delivered_at is null;
    get diagnostics v_batch = row_count;
    v_rows := v_rows + v_batch;

    update public.hr_message set sent_at = now() where id = m.id;
    v_msgs := v_msgs + 1;
  end loop;

  return jsonb_build_object('messages_sent', v_msgs, 'recipients', v_rows,
                            'skipped_no_audience', v_skipped);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_deliver_approved(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sent int := 0; v_skipped int := 0;
begin
  with ready as (
    select m.id, m.employee_id, m.subject, m.body
    from hr_message m
    where m.approved_by is not null
      and m.approved_at is not null
      and m.sent_at is null
      and m.cancelled_at is null
      and m.employee_id is not null      -- audience sends are not built yet
    order by m.approved_at
    limit greatest(p_limit, 0)
  ), put as (
    insert into messages (user_id, author, body)
    select r.employee_id, 'Human Resources',
           r.subject || E'\n\n' || r.body
    from ready r
    returning 1
  ), done as (
    update hr_message m set sent_at = now()
    where m.id in (select id from ready)
    returning 1
  )
  select count(*) into v_sent from done;

  /* Said out loud rather than silently left behind. An approved message to a
     whole department cannot be delivered yet, and a count that quietly excluded
     them would read as "everything sent". */
  select count(*) into v_skipped
  from hr_message
  where approved_by is not null and sent_at is null and cancelled_at is null
    and employee_id is null;

  return jsonb_build_object(
    'sent', v_sent,
    'waiting_on_audience_delivery', v_skipped,
    'note', case when v_skipped > 0
      then 'Approved messages addressed to a department or role are NOT sent - audience delivery is not built. They are approved and waiting, not lost.'
      else 'Nothing outstanding.' end,
    'at', now());
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_external_done(p_id uuid, p_external_id text, p_external_url text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.hr_external_task
     set status = case when p_error is null then 'pushed' else 'failed' end,
         external_id = coalesce(p_external_id, external_id),
         external_url = coalesce(p_external_url, external_url),
         pushed_at = case when p_error is null then now() else pushed_at end,
         error = p_error
   where id = p_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_external_next(p_limit integer DEFAULT 20)
 RETURNS SETOF hr_external_task
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  update public.hr_external_task t
     set status='claimed', attempts = coalesce(t.attempts,0)+1
   where t.id in (
     select id from public.hr_external_task
      where status in ('pending','failed') and coalesce(attempts,0) < 5
      order by created_at limit p_limit
      for update skip locked)
  returning t.*;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_queue_to_workspace(p_queue_id uuid, p_list_name text, p_due_on date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare q record; v_role text; v_id uuid;
begin
  select role::text into v_role from app_users where user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive','hr') then
    return jsonb_build_object('ok', false,
      'message', 'Only an owner, an executive or Human Resources can put an item into the workspace.');
  end if;

  select * into q from hr_review_queue where id = p_queue_id;
  if not found then
    return jsonb_build_object('ok', false, 'message', 'No such queue item.');
  end if;

  if q.status <> 'approved' or q.decided_by is null then
    return jsonb_build_object('ok', false,
      'message', 'That item has not been approved by a person. ClickUp is a shared workspace - a task there is visible to everyone, so it is a publication, not a note. Approve it first.',
      'status', q.status);
  end if;

  if exists (select 1 from hr_external_task t
             where t.queue_id = p_queue_id and t.status in ('pending','pushed')) then
    return jsonb_build_object('ok', false,
      'message', 'A task has already been raised for this item. Raising a second one splits the trail: two tasks, two comment threads, and no single place that says what was done.');
  end if;

  insert into hr_external_task (queue_id, target, list_hint, title, body, due_on, approved_by)
  values (p_queue_id, 'clickup', p_list_name,
          coalesce(q.headline, 'Human Resources item'),
          coalesce(q.edited_body, q.draft_body, q.rationale, ''),
          coalesce(p_due_on, q.defer_until::date),
          q.decided_by)
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id,
    'message', 'Queued for the workspace. It is pushed by hr-clickup-push, and until it succeeds it is visible in v_hr_delivery_backlog rather than silently pending.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_import_num(v text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when v is null or btrim(v) = '' then null
    -- thousands commas are stripped; "1,932.00" must never become two fields or 1
    when btrim(v) ~ '^-?[0-9,]+(\.[0-9]+)?$' then replace(btrim(v), ',', '')::numeric
    else null
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_import_pct(v text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when v is null or btrim(v) = '' then null
    when btrim(v) ~* '^(not tested|n/a|na|tbd|pending)$' then null
    when btrim(v) ~ '^-?[0-9]{1,3}(\.[0-9]+)?\s*%$' then replace(btrim(v), '%', '')::numeric
    when btrim(v) ~ '^-?[0-9,]+(\.[0-9]+)?$' then replace(btrim(v), ',', '')::numeric
    else null
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_import_tag(v text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when v is null or btrim(v) = '' then null
    when btrim(v) ~* '^(n/a|na|none|-)$' then null           -- ABSENT, not invalid
    when upper(btrim(v)) ~ '^1[A-Z0-9]{23}$' then upper(btrim(v))
    else null                                                 -- e.g. "IN CURE"
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_import_usdate(v text)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when v is null or btrim(v) = '' then null
    when btrim(v) ~ '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
     and split_part(btrim(v), '/', 1)::int between 1 and 12
     and split_part(btrim(v), '/', 2)::int between 1 and 31
    then to_date(btrim(v), 'FMMM/FMDD/YYYY')
    else null
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_inventory_reconciliation(p_from date, p_to date)
 RETURNS TABLE(line_no integer, section text, line_item text, pounds numeric, source text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
with inception as (select date '2023-01-01' d),
prod as (
  select coalesce(sum(f_to_pounds(coalesce((p.raw->>'CreatedQuantity')::numeric,0),
             coalesce(nullif(p.raw->>'UnitOfMeasureName',''),'Grams'))),0) lb,
         (p.raw->>'PackagedDate')::date d
  from metrc_packages p
  where nullif(p.raw->>'SourceHarvestNames','') is not null
    and nullif(p.raw->>'SourcePackageLabels','') is null
    and f_is_weight(coalesce(nullif(p.raw->>'UnitOfMeasureName',''),'Grams'))
  group by 2),
flows as (
  select
    (select coalesce(sum(lb),0) from prod where d between (select d from inception) and p_from-1)
   +(select coalesce(sum(pounds),0) from v_transfer_line where direction='INBOUND'
       and voided<>'True' and received_on between (select d from inception) and p_from-1)
   -(select coalesce(sum(pounds),0) from v_transfer_line where direction='OUTBOUND'
       and voided<>'True' and received_on between (select d from inception) and p_from-1)
   +(select coalesce(sum(f_to_pounds(quantity,uom)),0) from metrc_rpt_adjustments
       where quantity is not null and f_is_weight(uom)
         and adjusted_on between (select d from inception) and p_from-1)          as opening,
    (select coalesce(sum(lb),0) from prod where d between p_from and p_to)        as produced,
    (select coalesce(sum(packaged_lb),0) from metrc_rpt_harvest_moisture
       where finished_on between p_from and p_to)                                 as produced_hr,
    (select coalesce(sum(pounds),0) from v_transfer_line where direction='INBOUND'
       and voided<>'True' and received_on between p_from and p_to)                as purchased,
    (select coalesce(sum(pounds),0) from v_transfer_line where direction='OUTBOUND'
       and voided<>'True' and received_on between p_from and p_to)                as sold,
    (select coalesce(sum(pounds),0) from v_transfer_line where direction='INTERNAL'
       and voided<>'True' and received_on between p_from and p_to)                as internal,
    (select coalesce(sum(f_to_pounds(quantity,uom)),0) from metrc_rpt_adjustments
       where quantity is not null and f_is_weight(uom)
         and adjusted_on between p_from and p_to)                                 as waste),
live as (select p_to >= current_date - 7 as use_mirror),
snap as (select max(as_of_date) d from metrc_rpt_point_in_time where as_of_date <= p_to + 2),
snapcov as (select count(*) tags, string_agg(distinct licence,' + ') lic_list
  from metrc_rpt_point_in_time where as_of_date=(select d from snap) and record_type='Package'),
recon as (
  select coalesce(sum(greatest(b.lb,0)),0) lb, count(*) weighable
  from (select distinct upper(btrim(tag)) tag from metrc_rpt_point_in_time
        where as_of_date=(select d from snap) and record_type='Package') s
  join (select upper(btrim(package_tag)) tag, sum(lb_delta) lb
        from v_package_events where event_date <= p_to group by 1) b on b.tag=s.tag),
counted as (
  select case when (select use_mirror from live) then
           (select coalesce(sum(f_to_pounds(coalesce((raw->>'Quantity')::numeric,0),
                  coalesce(nullif(raw->>'UnitOfMeasureName',''),'Grams'))),0)
            from metrc_packages where not coalesce((raw->>'IsFinished')::boolean,false)
              and f_is_weight(coalesce(nullif(raw->>'UnitOfMeasureName',''),'Grams')))
         when (select d from snap) is null then null
         else (select lb from recon) end lb),
expected as (select (select opening+produced+purchased-sold+waste from flows) lb)
select 0,'OPENING','On hand at close of ' || to_char(p_from-1,'DD Mon YYYY'),
       round((select opening from flows)::numeric,1),
       'Accumulated from inception on the same five sources'
union all select 1,'IN','Produced from our own harvests', round((select produced from flows)::numeric,1),
       'Packages made directly off a harvest, dated on the package''s own PackagedDate'
union all select 2,'IN','Purchased in from third parties', round((select purchased from flows)::numeric,1),
       'Inbound manifests where the origin is NOT one of our licences'
union all select 3,'IN','TOTAL IN', round((select produced+purchased from flows)::numeric,1),''
union all select 4,'OUT','Sold / shipped out', round(-(select sold from flows)::numeric,1),
       'Outbound manifests where the destination is NOT one of our licences'
union all select 5,'OUT','Waste, destruction, corrections', round((select waste from flows)::numeric,1),
       'Metrc adjustment report, weight-denominated rows only'
union all select 6,'OUT','TOTAL OUT', round((select -sold+waste from flows)::numeric,1),''
union all select 7,'RESULT','Expected on hand at ' || to_char(p_to,'DD Mon YYYY'),
       round((select lb from expected)::numeric,1), 'Opening plus total in less total out'
union all select 8,'RESULT',
       case when (select lb from counted) is null then 'Actual on hand — NO SNAPSHOT AT THIS DATE'
            else 'Actual on hand, counted' end,
       round((select lb from counted)::numeric,1),
       case when (select lb from counted) is null
              then 'Metrc holds no Inventory Point in Time export at or before this date.'
            when (select use_mirror from live) then 'Every open package in the live Metrc package mirror'
            else 'Snapshot ' || (select d from snap) || ' covering licence(s) ' || (select lic_list from snapcov)
                 || '. ' || (select weighable from recon) || ' of ' || (select tags from snapcov)
                 || ' snapshot tags carry a ledger weight; the rest are counted as tags but not as pounds.' end
union all select 9,'RESULT',
       case when (select lb from counted) is null then 'VARIANCE — CANNOT BE COMPUTED'
            else 'VARIANCE (unexplained)' end,
       case when (select lb from counted) is null then null
            else round(((select lb from counted)-(select lb from expected))::numeric,1) end,
       'Expected NEGATIVE: manufacturing yield loss is real and Metrc never tags it'
union all select 10,'MEMO','Internal MC <-> MP transfers (excluded above)',
       round((select internal from flows)::numeric,1),
       'Same material moving between our own licences. Not a purchase, not a sale.'
union all select 11,'MEMO','Production per HARVEST REPORT (alternative basis)',
       round((select produced_hr from flows)::numeric,1),
       'metrc_rpt_harvest_moisture.packaged_lb dated on finished_on. Dating production '
       'by harvest CLOSURE rather than package creation drove FY2025 to a negative '
       'expected inventory, which is why line 1 is used instead.'
union all select 12,'MEMO','Difference between the two production bases',
       round((select produced - produced_hr from flows)::numeric,1),
       'Line 1 less line 11. Systematic, not a December/January timing effect: it is '
       'positive in every year. This is the gap previously reported as 485.1 lb for 2024.'
order by 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_inventory_rollforward(p_from date, p_to date, p_licence text DEFAULT NULL::text, p_ours_only boolean DEFAULT false)
 RETURNS TABLE(line_no integer, section text, line_item text, packages bigint, pounds numeric, sign text, basis text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
with ev as (
  select * from v_package_event_class e
  where (p_licence is null or e.licence = p_licence)
    and (not p_ours_only or e.is_ours)
),
opening as (select coalesce(sum(lb_delta),0) lb from ev where event_date <  p_from),
closing as (select coalesce(sum(lb_delta),0) lb from ev where event_date <= p_to),
win as (select * from ev where event_date between p_from and p_to),
agg as (select event_class, count(distinct package_tag) n, sum(lb_delta) lb
        from win group by 1),
v as (select event_class, n, lb from agg)
select 1, 'OPENING', 'On hand at close of ' || to_char(p_from - 1,'DD Mon YYYY'),
       null::bigint, round((select lb from opening)::numeric,1), '=',
       'Derived from every recorded event before the window opened'
union all
select 2,'ADDITIONS','Produced from our own harvests',n,round(lb::numeric,1),'+',
       'NEW MASS. Packaged directly off a harvest batch.' from v where event_class='PRODUCED_FROM_HARVEST'
union all
select 3,'ADDITIONS','Received in (purchases, returns, inbound)',n,round(lb::numeric,1),'+',
       'Inbound manifest leg where we are the destination licence' from v where event_class='RECEIVED'
union all
select 4,'ADDITIONS','Output of manufacturing (re-packaged)',n,round(lb::numeric,1),'+',
       'NOT new mass. Nets against line 7; counting it as inventory double-counts.'
       from v where event_class='CREATED_FROM_PACKAGE'
union all
select 5,'ADDITIONS','Created with no recorded source',n,round(lb::numeric,1),'+',
       'EXCEPTION: neither a harvest nor a parent package' from v where event_class='CREATED_NO_SOURCE'
union all
select 6,'REDUCTIONS','Shipped out on a manifest',n,round(lb::numeric,1),'-',
       'Outbound manifest leg where we are the origin licence' from v where event_class='SHIPPED'
union all
select 7,'REDUCTIONS','Consumed as manufacturing input',n,round(lb::numeric,1),'-',
       'Drawn down by a child package. Multi-parent splits PRO-RATA (assumption, not measurement).'
       from v where event_class='CONSUMED INTO CHILD'
union all
select 8,'REDUCTIONS','Adjustments: waste, destruction, corrections',n,round(lb::numeric,1),'+/-',
       'Signed exactly as Metrc recorded it' from v where event_class='ADJUSTED'
union all
select 9,'CLOSING','On hand at close of ' || to_char(p_to,'DD Mon YYYY'),
       null::bigint, round((select lb from closing)::numeric,1),'=',
       'Opening plus every movement inside the window'
union all
select 10,'DERIVED','Manufacturing process loss',null::bigint,
       round((coalesce((select -lb from v where event_class='CONSUMED INTO CHILD'),0)
            - coalesce((select  lb from v where event_class='CREATED_FROM_PACKAGE'),0))::numeric,1),'=',
       'Mass in less mass out of conversions. Metrc never tags this; derivable ONLY as a residual.'
order by 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_is_our_licence(p text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from licence_profile where licence = p);
$function$
;
CREATE OR REPLACE FUNCTION public.f_is_ours(p_license text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when coalesce(btrim(p_license), '') = '' then false
    /* Fast path: no delimiter, so there is nothing to split. This is almost every row. */
    when p_license !~ '[,;/|]' then exists (
      select 1 from public.company_licenses c
       where c.active and upper(btrim(c.license)) = upper(btrim(p_license)))
    /* Slow path only where a field genuinely carries more than one licence. */
    else exists (
      select 1
        from public.company_licenses c,
             lateral unnest(regexp_split_to_array(p_license, '[,;/|]+')) part
       where c.active and upper(btrim(part)) = upper(btrim(c.license)))
  end
$function$
;
CREATE OR REPLACE FUNCTION public.f_is_overridden(p_table text, p_row_key text, p_field text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from tg_overrides
                 where target_table = p_table and row_key = p_row_key
                   and field_name = p_field and active);
$function$
;
CREATE OR REPLACE FUNCTION public.f_is_summary_row(r jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from jsonb_each_text(r) e(k, v)
    where v ~* '^\s*(totals?|grand total|subtotal|sum)\s*:?\s*$');
$function$
;
CREATE OR REPLACE FUNCTION public.f_is_transporter(p_licence text)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(f_facility_type(p_licence) = 'Transporter', false)
$function$
;
CREATE OR REPLACE FUNCTION public.f_is_weight(uom text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select lower(coalesce(uom,'')) in ('g','grams','kg','kilograms','mg','oz','ounces','lb','lbs','pounds')
$function$
;
CREATE OR REPLACE FUNCTION public.f_item_documents(p_tag text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
select jsonb_build_object(
  'package_tag', p_tag,
  'bucket',      'metrc-documents',
  'how_to_link', 'supabase.storage.from(bucket).createSignedUrl(storage_path, ttl) at click time. The FILE is permanent - these records are kept and can be sent years later. Never store or cache a URL.',
  'coa', coalesce((
     select jsonb_agg(jsonb_build_object(
              'document_id',        x.metrc_id,
              'storage_path',       x.storage_path,
              'file_name',          'COA ' || p_tag || '.pdf',
              'inherited',          x.link_depth > 0,
              'certificate_on',     x.certificate_on,
              'lab',                x.lab,
              'cultivator',         x.client_name,
              'cultivator_license', x.client_license,
              'report_id',          x.lab_report_id,
              -- REGULATORY validity of the test result, not of the link
              'coa_valid_until',    x.valid_until,
              'coa_expired',        (x.valid_until is not null and x.valid_until < current_date))
            order by x.link_depth, x.metrc_id)
     from (
       select distinct on (d.metrc_id)
              d.metrc_id, d.storage_path, l.link_depth,
              nullif(split_part(l.link_basis, 'INHERITED from ', 2), '') as certificate_on,
              e.client_name, e.client_license, e.lab_report_id,
              (select max(r.lab_facility) from metrc_lab_results r
                where r.package_tag = d.package_tag) as lab,
              (select max((r.raw->>'ExpirationDateTime')::date) from metrc_lab_results r
                where r.package_tag = d.package_tag) as valid_until
       from v_document_package_link l
       join metrc_documents d on d.id = l.document_id
       left join coa_extract e on e.document_id = d.metrc_id::text
       where l.package_tag = p_tag and l.doc_type = 'coa'
       order by d.metrc_id, l.link_depth
     ) x), '[]'::jsonb),
  'manifests', coalesce((
     select jsonb_agg(jsonb_build_object(
              'manifest_number', y.manifest_number,
              'storage_path',    y.storage_path,
              'file_name',       'Manifest ' || y.manifest_number || '.pdf',
              'direction',       y.direction,
              'shipper',         y.shipper,
              'recipient',       y.recipient,
              'created',         y.created)
            order by y.created desc nulls last, y.manifest_number)
     from (
       select distinct on (d.manifest_number)
              d.manifest_number, d.storage_path, t.direction,
              t.raw->>'ShipperFacilityName'     as shipper,
              t.raw->>'RecipientFacilityName'   as recipient,   -- null on all outgoing
              (t.raw->>'CreatedDateTime')::date as created
       from v_document_package_link l
       join metrc_documents d on d.id = l.document_id
       left join metrc_transfers t on t.manifest_number = d.manifest_number
       where l.package_tag = p_tag and l.doc_type = 'manifest'
       order by d.manifest_number
     ) y), '[]'::jsonb)
);
$function$
;
CREATE OR REPLACE FUNCTION public.f_item_flag_badge(p_entity_type text, p_entity_key text)
 RETURNS TABLE(flags integer, worst_severity text, needs_a_person boolean)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select count(*)::int,
         case min(case f.severity when 'critical' then 1 when 'elevated' then 2 else 3 end)
              when 1 then 'critical' when 2 then 'elevated' when 3 then 'watch' else null end,
         coalesce(bool_or(f.severity in ('critical','elevated')), false)
  from v_item_flags f
  where f.entity_type = p_entity_type and f.entity_key = p_entity_key;
$function$
;
CREATE OR REPLACE FUNCTION public.f_item_flags(p_entity_type text, p_entity_key text)
 RETURNS TABLE(severity text, headline text, detail text, why text, what_to_do text, source text, source_ref text, raised_on date, context text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select f.severity, f.headline, f.detail, f.why, f.what_to_do,
         f.source, f.source_ref, f.raised_on, f.context
  from v_item_flags f
  where f.entity_type = p_entity_type and f.entity_key = p_entity_key
  order by case f.severity when 'critical' then 1 when 'elevated' then 2 else 3 end,
           f.raised_on desc;
$function$
;
CREATE OR REPLACE FUNCTION public.f_lab_value(p_tag text, p_prefix text)
 RETURNS TABLE(value numeric, test_name text, result_date date)
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  with direct as (
    select r.result as value, r.test_name, r.result_date
    from metrc_lab_results r
    where r.package_tag = p_tag
      and r.test_name ilike p_prefix || '%'
      and r.test_name not ilike '%DO NOT USE%'
      and r.result is not null
    order by (r.test_name ilike '%Retest%'), r.result_date desc nulls last
    limit 1
  ), summed as (
    -- only for terpenes, and only when no total line exists
    select round(sum(r.result), 3) as value,
           'Sum of ' || count(*) || ' individual terpenes on the certificate' as test_name,
           max(r.result_date) as result_date
    from metrc_lab_results r
    where p_prefix ilike 'Total Terpenes%'
      and r.package_tag = p_tag
      and r.result is not null
      and r.test_name not ilike '%DO NOT USE%'
      and r.test_name not ilike 'Total%'
      and (r.test_name ilike any (array[
            'Alpha-Bisabolol%','Alpha-Humulene%','Alpha-Pinene%','Alpha-Terpinene%',
            'Beta-Caryophyllene%','Beta-Myrcene%','Beta-Pinene%','Caryophyllene Oxide%',
            'Limonene%','Linalool%','Nerolidol%','Terpinolene%','Other Terpenes%',
            'Gamma-Terpinene%','Eucalyptol%','Camphene%','Geraniol%','Guaiol%',
            'Isopulegol%','p-Cymene%','3-Carene%','Ocimene%']))
    having count(*) > 0
  )
  select * from direct
  union all
  select * from summed where not exists (select 1 from direct)
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_lane_for_path(p text)
 RETURNS TABLE(agent text, display_name text, pattern text)
 LANGUAGE sql
 STABLE PARALLEL SAFE
AS $function$
  select l.agent, l.display_name, pat
  from public.agent_lane l, unnest(l.owns_paths) pat
  where p like pat
  order by length(pat) desc
$function$
;
CREATE OR REPLACE FUNCTION public.f_licence_in_set(p_licence text, p_set text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when p_licence is null or p_set is null then false
         else exists (
           select 1 from unnest(string_to_array(p_set, ',')) x
           where btrim(x) = btrim(p_licence))
         end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_login_id_parts(p_full_name text)
 RETURNS TABLE(surname text, first_i text, middle_i text)
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select
    upper(regexp_replace(split_part(p_full_name, ',', 1), '[^A-Za-z]', '', 'g')),
    upper(left(regexp_replace(split_part(btrim(split_part(p_full_name, ',', 2)), ' ', 1),
          '[^A-Za-z]', '', 'g'), 1)),
    upper(left(regexp_replace(coalesce(nullif(split_part(btrim(split_part(p_full_name, ',', 2)), ' ', 2), ''), ''),
          '[^A-Za-z]', '', 'g'), 1))
$function$
;
CREATE OR REPLACE FUNCTION public.f_material_origin(p_tag text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with recursive seed as (
  select tag, raw from metrc_packages where tag = p_tag
  order by license limit 1                       -- dedupe: one row per tag
),
walk as (
  select s.tag, s.raw, 0 as depth from seed s
  union
  select c.tag, c.raw, w.depth + 1
    from walk w
    join lateral (
      select trim(s) as src
      from unnest(string_to_array(coalesce(w.raw->>'SourcePackageLabels',''), ',')) s
      where trim(s) <> ''
    ) l on true
    join lateral (
      select tag, raw from metrc_packages m where m.tag = l.src order by m.license limit 1
    ) c on true
   where w.depth < 12
),
roots as (
  select w.raw,
         coalesce(nullif(w.raw->>'ReceivedFromFacilityLicenseNumber',''),
                  nullif(w.raw->>'ItemFromFacilityLicenseNumber','')) as origin_lic,
         coalesce(nullif(w.raw->>'ReceivedFromFacilityName',''),
                  nullif(w.raw->>'ItemFromFacilityName','')) as origin_name
    from walk w
   where nullif(w.raw->>'ReceivedFromManifestNumber','') is not null
      or coalesce(w.raw->>'SourcePackageLabels','') = ''
      or not exists (select 1 from metrc_packages c
                      where c.tag = any(string_to_array(replace(w.raw->>'SourcePackageLabels',' ',''), ',')))
)
select jsonb_build_object(
  'package_tag',       p_tag,
  'lineage_packages',  (select count(*) from walk),
  'max_depth',         (select max(depth) from walk),
  'origin_licences',   (select coalesce(jsonb_agg(distinct origin_lic) filter (where origin_lic is not null), '[]'::jsonb) from roots),
  'origin_names',      (select coalesce(jsonb_agg(distinct origin_name) filter (where origin_name is not null), '[]'::jsonb) from roots),
  'inbound_manifests', (select coalesce(jsonb_agg(distinct raw->>'ReceivedFromManifestNumber')
                                  filter (where nullif(raw->>'ReceivedFromManifestNumber','') is not null), '[]'::jsonb) from walk),
  'source_harvests',   (select coalesce(jsonb_agg(distinct raw->>'SourceHarvestNames')
                                  filter (where nullif(raw->>'SourceHarvestNames','') is not null), '[]'::jsonb) from walk),
  'all_ours',          (select bool_and(f_is_ours(origin_lic)) from roots where origin_lic is not null),
  'any_outside',       (select bool_or(not f_is_ours(origin_lic)) from roots where origin_lic is not null),
  'item_field_says',   (select raw->>'ItemFromFacilityLicenseNumber' from seed)
);
$function$
;
CREATE OR REPLACE FUNCTION public.f_matview_freshness()
 RETURNS TABLE(matview text, has_clock boolean, computed_at timestamp with time zone, age interval, scheduled_refresh text, verdict text)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_at timestamptz;
begin
  for r in
    with reach as (
      select j.jobname, j.schedule, j.command as txt from cron.job j where j.active
      union all
      select j.jobname, j.schedule, pg_get_functiondef(p.oid)
      from cron.job j
      join pg_proc p on j.command like '%'||p.proname||'%'
      join pg_namespace pn on pn.oid=p.pronamespace and pn.nspname='public'
      where j.active
    )
    select c.oid, c.relname,
           exists(select 1 from pg_attribute a
                  where a.attrelid=c.oid and a.attname='computed_at'
                    and a.attnum>0 and not a.attisdropped) as has_clock,
           (select string_agg(distinct x.jobname||' ['||x.schedule||']', ', ')
              from reach x
             where x.txt ~ ('refresh\s+materialized\s+view\s+(concurrently\s+)?(public\.)?'||c.relname||'\M')
           ) as sched
    from pg_class c
    join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relkind='m'
    order by c.relname
  loop
    v_at := null;
    if r.has_clock then
      execute format('select max(computed_at) from public.%I', r.relname) into v_at;
    end if;

    matview           := r.relname;
    has_clock         := r.has_clock;
    computed_at       := v_at;
    age               := case when v_at is null then null else now() - v_at end;
    scheduled_refresh := coalesce(r.sched, 'NONE');
    verdict := case
      when not r.has_clock and r.sched is null then 'NO CLOCK AND NO REFRESH'
      when not r.has_clock                      then 'AGE UNMEASURABLE - no computed_at'
      when r.sched is null                      then 'NO SCHEDULED REFRESH'
      else f_matview_freshness_verdict(v_at, now(), interval '30 minutes')
    end;
    return next;
  end loop;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_matview_freshness_verdict(p_computed_at timestamp with time zone, p_now timestamp with time zone, p_slo interval)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when p_computed_at is null                then 'NEVER COMPUTED'
    when p_computed_at > p_now + interval '1 minute' then 'CLOCK SKEW'
    when p_now - p_computed_at > p_slo * 12   then 'DEAD'
    when p_now - p_computed_at > p_slo        then 'STALE'
    else 'ok'
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_metric_slug(p_label text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE
AS $function$
declare v text; r record;
begin
  if p_label is null then return null; end if;
  v := lower(btrim(p_label));
  v := regexp_replace(v, '[-_/]+', ' ', 'g');
  v := regexp_replace(v, '[^a-z0-9 ]', '', 'g');
  v := regexp_replace(v, '\s+', ' ', 'g');
  for r in select phrase, canonical from metric_synonym order by length(phrase) desc loop
    v := replace(v, lower(r.phrase), lower(r.canonical));
  end loop;
  return regexp_replace(v, '\s+', '', 'g');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_my_employee_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select employee_id from public.app_users where user_id = auth.uid()
$function$
;
CREATE OR REPLACE FUNCTION public.f_my_notifications()
 RETURNS TABLE(source text, unread bigint, newest timestamp with time zone, what text)
 LANGUAGE sql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select 'inventory_alerts'::text, count(*)::bigint, max(i.last_seen),
         'Inventory alerts still open'::text
    from inventory_alerts i where i.resolved_at is null
  union all
  select 'critical_findings', count(*)::bigint, max(w.observed_at),
         'Critical findings not yet resolved'
    from watchdog_findings w where w.severity = 'critical'
  union all
  /* alert_outbox routes by role, not by person */
  select 'alert_outbox', count(*)::bigint, max(a.created_at),
         'Alerts raised for your role and not yet read'
    from alert_outbox a
    where a.read_at is null and a.resolved_at is null
      and (a.role is null or a.role = (select u.role::text from app_users u where u.user_id = auth.uid()))
  union all
  select 'messages', count(*)::bigint, max(m.created_at),
         'Messages addressed to you'
    from messages m where m.user_id = auth.uid()
$function$
;
CREATE OR REPLACE FUNCTION public.f_next_login_id(p_full_name text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p record; v_base text; v_try text; v_n int := 1;
begin
  select * into p from public.f_login_id_parts(p_full_name);
  if p.surname = '' or p.first_i = '' then
    raise exception 'Cannot derive a login ID from "%" — expected "Last, First M"', p_full_name;
  end if;

  v_base := p.first_i || p.middle_i || left(p.surname, 1);
  v_try  := v_base;
  while exists (select 1 from public.employees where login_id = v_try) loop
    v_n := v_n + 1;
    v_try := v_base || v_n::text;
  end loop;
  return v_try;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_offboarding_due()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.final_pay_due_on is null then
    new.final_pay_due_on := case when new.voluntary then null else new.last_day end;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_one_home_per_figure()
 RETURNS TABLE(figure text, canonical_table text, canonical_rows bigint, obsolete_table text, obsolete_rows bigint, verdict text)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n bigint; c bigint;
begin
  for r in
    select 'potency and terpenes'::text as fig, 'metrc_lab_results'::text as canon,
           'lab_result_values'::text as obsolete
    union all
    select 'certificates of analysis', 'metrc_documents', 'coa_documents'
  loop
    execute format('select count(*) from %I', r.canon) into c;
    execute format('select count(*) from %I', r.obsolete) into n;
    figure := r.fig; canonical_table := r.canon; canonical_rows := c;
    obsolete_table := r.obsolete; obsolete_rows := n;
    verdict := case
      when n > 0 then 'TWO HOMES - ' || r.obsolete || ' has been repopulated'
      when c = 0 then 'CANONICAL TABLE IS EMPTY'
      else 'ok' end;
    return next;
  end loop;
end $function$
;
