CREATE OR REPLACE FUNCTION public.tg_add_zone(p_name text, p_department text DEFAULT NULL::text, p_rooms text[] DEFAULT '{}'::text[], p_capacity integer DEFAULT NULL::integer, p_what_happens_here text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_key text; bad text;
begin
  if p_name is null or btrim(p_name) = '' then
    raise exception 'A zone needs a name people would actually say out loud.';
  end if;

  v_key := btrim(left(regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '_', 'g'), 40), '_-');
  if v_key !~ '^[a-z0-9_-]{2,40}$' then
    raise exception 'Could not make a usable key from "%". Try a name with letters in it.', p_name;
  end if;
  if exists (select 1 from zone where zone_key = v_key) then
    raise exception 'A zone called "%" already exists. Rename that one or choose another name.', p_name;
  end if;

  -- A room that is not in room_alias is almost always a typo, and a typo here recreates exactly
  -- the F1-versus-Flower-Room-#1 defect this registry exists to prevent.
  select string_agg(r, ', ') into bad
  from unnest(coalesce(p_rooms,'{}')) r
  where not exists (select 1 from room_alias a where a.metrc_name = r or a.our_name = r);
  if bad is not null then
    raise exception
      'Not a known room: %. Rooms must match room_alias (Metrc''s name or ours). '
      'Leave rooms empty if this zone is not a room.', bad;
  end if;

  insert into zone (zone_key, name, department, rooms, capacity, what_happens_here)
  values (v_key, btrim(p_name), nullif(btrim(coalesce(p_department,'')),''),
          coalesce(p_rooms,'{}'), p_capacity, nullif(btrim(coalesce(p_what_happens_here,'')),''));
  return v_key;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_agentmapper_approve(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u record; p jsonb; tbl text; k text; spec jsonb; ddl text; colsql text[] := '{}'; me text;
begin
  if not f_caller_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Only administrators can approve a mapping.');
  end if;
  me := coalesce(auth.uid()::text, 'system');
  select * into u from metrc_report_unmapped where id = p_id and state = 'proposed';
  if not found then return jsonb_build_object('ok', false, 'error', 'No proposal awaiting approval.'); end if;

  -- the structure existed; nothing checked it until now
  if u.proposed_by is not null and u.proposed_by = me then
    return jsonb_build_object('ok', false,
      'error', 'You proposed this mapping, so you cannot also approve it. A second administrator must '
            || 'review it. Four eyes is the point: the person who decided what a column means is the '
            || 'least able to notice they were wrong.');
  end if;

  p := u.proposal; tbl := p->>'target_table';
  for k, spec in select * from jsonb_each(p->'column_map') loop
    colsql := colsql || format('%I %s', k, case spec->>'type'
      when 'num' then 'numeric' when 'lb' then 'numeric'
      when 'date' then 'date'   when 'bool' then 'boolean' else 'text' end);
  end loop;
  ddl := format('create table if not exists %I (%s, licence text, source_row jsonb,
                   import_id uuid, imported_at timestamptz default now(), primary key (%s))',
    tbl, array_to_string(colsql, ', '),
    array_to_string((select array_agg(quote_ident(x))
                     from jsonb_array_elements_text(p->'key_cols') x), ', '));
  execute ddl;
  execute format('alter table %I enable row level security', tbl);
  execute format('drop policy if exists rpt_read on %I', tbl);
  execute format('create policy rpt_read on %I for select to authenticated using (is_finance_reader())', tbl);

  insert into metrc_report_types
    (report_key, title, signature_cols, target_table, key_cols, licence_scope, what_it_adds,
     api_covers_this, notes, upload_priority, cadence, menu_path, why_it_matters,
     required_licences, column_map)
  select p->>'report_key', coalesce(p->>'title', p->>'report_key'),
     array(select jsonb_array_elements_text(p->'signature_cols')), tbl,
     array(select jsonb_array_elements_text(p->'key_cols')),
     coalesce(p->>'licence_scope','both'), p->>'what_it_adds',
     coalesce((p->>'api_covers_this')::boolean, false),
     'Proposed by ' || coalesce(u.proposed_by,'?') || ', approved by ' || me || ' on ' || current_date,
     coalesce((p->>'upload_priority')::int, 50), coalesce(p->>'cadence','On demand'),
     p->>'menu_path', p->>'why_it_matters',
     coalesce(array(select jsonb_array_elements_text(p->'required_licences')),
              array['MC281714','MP281909']), p->'column_map'
  on conflict (report_key) do update set
     signature_cols=excluded.signature_cols, column_map=excluded.column_map,
     target_table=excluded.target_table, key_cols=excluded.key_cols;

  update metrc_report_unmapped set state='approved', decided_by=me, decided_at=now(), decision_note=p_note
  where id=p_id;
  update agent_findings set resolved_at=now(),
     resolution='Mapped and approved by a second administrator. ' || (p->>'report_key') || ' now imports.'
   where fingerprint = 'unmapped:' || u.signature and resolved_at is null;

  return jsonb_build_object('ok', true, 'report_key', p->>'report_key', 'target_table', tbl,
    'proposed_by', u.proposed_by, 'approved_by', me);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_agentmapper_propose(p_id uuid, p_proposal jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare bad text; u record;
begin
  if not f_caller_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Proposing a mapping is restricted to administrators.');
  end if;
  select * into u from metrc_report_unmapped where id = p_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'No such unmapped report.'); end if;
  if p_proposal->>'report_key' is null or p_proposal->>'target_table' is null
     or p_proposal->'signature_cols' is null or p_proposal->'key_cols' is null
     or p_proposal->'column_map' is null then
    return jsonb_build_object('ok', false,
      'error', 'Proposal needs report_key, title, target_table, signature_cols, key_cols and column_map.');
  end if;
  if p_proposal->>'target_table' !~ '^metrc_rpt_[a-z0-9_]+$' then
    return jsonb_build_object('ok', false, 'error', 'target_table must be metrc_rpt_<name>, lower case.');
  end if;
  select string_agg(k, ', ') into bad from jsonb_object_keys(p_proposal->'column_map') k
  where k !~ '^[a-z][a-z0-9_]*$';
  if bad is not null then return jsonb_build_object('ok', false, 'error', 'Invalid column names: '||bad); end if;
  select string_agg(x, ', ') into bad from jsonb_array_elements_text(p_proposal->'key_cols') x
  where not (p_proposal->'column_map' ? x);
  if bad is not null then
    return jsonb_build_object('ok', false, 'error', 'Key columns not in column_map: '||bad); end if;
  select string_agg(s, ', ') into bad from jsonb_array_elements_text(p_proposal->'signature_cols') s
  where not exists (select 1 from unnest(u.columns) c where lower(btrim(c)) = lower(btrim(s)));
  if bad is not null then
    return jsonb_build_object('ok', false,
      'error', 'signature_cols names columns not in the uploaded file: ' || bad
            || '. The file contained: ' || array_to_string(u.columns, ', ')); end if;
  select string_agg(spec->>'from', ', ') into bad
  from jsonb_each(p_proposal->'column_map') e(k, spec)
  where not exists (select 1 from unnest(u.columns) c where lower(btrim(c)) = lower(btrim(spec->>'from')));
  if bad is not null then
    return jsonb_build_object('ok', false,
      'error', 'column_map reads columns not in the uploaded file: ' || bad); end if;
  select string_agg(c, ', ') into bad from (
    select lower(btrim(c)) as c from unnest(u.columns) c group by 1 having count(*) > 1) d;
  if bad is not null then
    return jsonb_build_object('ok', false,
      'error', 'This file has repeated column headers (' || bad || '), meaning a grouped two-row '
            || 'header. It needs code, not a mapping. Escalate rather than approving a guess.'); end if;

  update metrc_report_unmapped
  set proposal = p_proposal, state = 'proposed',
      proposed_by = coalesce(auth.uid()::text, 'agent'), proposed_at = now()
  where id = p_id;
  return jsonb_build_object('ok', true, 'state', 'proposed',
    'note', 'Validated against the uploaded file. Awaiting approval BY A DIFFERENT ADMINISTRATOR.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_ai_allowance(p_user uuid)
 RETURNS TABLE(allowed boolean, reason text, used_today integer, daily_limit integer, used_month integer, monthly_limit integer, month_cost numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare s record; a record; ut int; um int; mc numeric;
begin
  select * into s from ai_settings where id = 1;
  select * into a from ai_user_access where user_id = p_user;
  select count(*), coalesce(sum(cost_usd),0) into um, mc from ai_usage_log
    where user_id = p_user and created_at >= date_trunc('month', now());
  select count(*) into ut from ai_usage_log where user_id = p_user and created_at >= current_date;
  daily_limit := coalesce(a.daily_call_limit, s.default_daily_calls);
  monthly_limit := coalesce(a.monthly_call_limit, s.default_monthly_calls);
  used_today := ut; used_month := um; month_cost := mc;
  if s.mode = 'disabled' then allowed := false; reason := 'Artificial intelligence features are switched off for the whole company.';
  elsif a.user_id is null or not a.enabled then allowed := false; reason := 'Your account is not enabled for artificial intelligence features - an owner or executive can enable it in Settings.';
  elsif ut >= daily_limit then allowed := false; reason := 'Daily limit of ' || daily_limit || ' reached. It resets at midnight.';
  elsif um >= monthly_limit then allowed := false; reason := 'Monthly limit of ' || monthly_limit || ' reached.';
  elsif (select coalesce(sum(cost_usd),0) from ai_usage_log where created_at >= date_trunc('month', now())) >= coalesce(s.hard_monthly_cost_cap_usd, 1e9)
    then allowed := false; reason := 'The company monthly cost cap has been reached.';
  else allowed := true; reason := 'Allowed'; end if;
  return next;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_ai_budget_ok()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select (select coalesce(paid_model_enabled,false) from ai_settings where id=1)
     and exists (select 1 from app_users u where u.user_id = auth.uid() and u.role in ('owner','executive'))
     and coalesce((select sum(cost_usd) from ai_usage_log where created_at >= date_trunc('month', now())), 0)
         < (select hard_monthly_cost_cap_usd from ai_settings where id=1);
$function$
;
CREATE OR REPLACE FUNCTION public.tg_ai_gate()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with s as (select * from ai_settings where id = 1),
       spend as (
         select coalesce(sum(cost_usd), 0) as used
         from ai_usage_log
         where created_at >= date_trunc('month', now())
       ),
       me as (select role::text as role from app_users where user_id = auth.uid())
  select case
    when not exists (select 1 from s) then jsonb_build_object(
      'allowed', false, 'reason', 'no_settings',
      'message', 'The assistant has no settings row, so nothing can tell me whether paid answers are switched on. An owner needs to open Settings and save the assistant options once.')

    when auth.uid() is null then jsonb_build_object(
      'allowed', false, 'reason', 'no_identity',
      'message', 'I could not tell who is asking, so I stopped rather than spend money for an unknown caller. Signing out and back in usually fixes it.')

    when not exists (select 1 from me) then jsonb_build_object(
      'allowed', false, 'reason', 'not_on_file',
      'message', 'You are signed in, but there is no record of you in the user list, so I cannot check whether you are allowed paid answers.')

    when (select role from me) not in ('owner','executive') then jsonb_build_object(
      'allowed', false, 'reason', 'not_permitted',
      'message', 'Free-form questions are limited to owners and executives. Every report, dashboard and suggestion button still works for you and costs nothing.',
      'your_role', (select role from me))

    when not coalesce((select paid_model_enabled from s), false) then jsonb_build_object(
      'allowed', false, 'reason', 'paid_model_off',
      'message', 'Paid answers are switched off in Settings. This is not a spending limit — the switch is simply off.')

    when (select used from spend) >= (select hard_monthly_cost_cap_usd from s) then jsonb_build_object(
      'allowed', false, 'reason', 'cap_reached',
      'message', format('The monthly cap really has been reached: $%s spent of a $%s cap. An owner can raise it in Settings.',
                        round((select used from spend), 2), (select hard_monthly_cost_cap_usd from s)),
      'spent_usd', round((select used from spend), 2),
      'cap_usd',   (select hard_monthly_cost_cap_usd from s))

    else jsonb_build_object(
      'allowed', true, 'reason', 'ok',
      'spent_usd', round((select used from spend), 2),
      'cap_usd',   (select hard_monthly_cost_cap_usd from s))
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_alert_action(p_alert_id bigint, p_action text, p_note text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text, p_assignee_employee_id uuid DEFAULT NULL::uuid, p_due_on date DEFAULT NULL::date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a alert_outbox; v_author text; v_no text; v_id uuid;
begin
  select * into a from alert_outbox where id = p_alert_id;
  if not found then raise exception 'Alert % does not exist.', p_alert_id; end if;
  select coalesce(display_name, auth.uid()::text, 'unknown') into v_author
    from app_users where user_id = auth.uid();
  v_author := coalesce(v_author, 'unknown');

  if p_action = 'acknowledge' then
    update alert_outbox set read_at = coalesce(read_at, now()) where id = p_alert_id;
    return 'acknowledged';

  elsif p_action = 'note' then
    insert into alert_note (alert_id, author, body) values (p_alert_id, v_author, p_note);
    return 'note added';

  elsif p_action = 'defer' then
    insert into alert_deferral (alert_key, alert_source, deferred_by, reason_code, reason_note, age_days_at_deferral)
    values ('alert:'||p_alert_id, a.source, v_author, p_reason_code, p_note, a.days_open);
    return 'deferred for today, on the record';

  elsif p_action = 'resolve' then
    if length(btrim(coalesce(p_note,''))) < 20 then
      raise exception 'Resolving needs at least 20 characters saying WHAT fixed it (reason_policy flag_fixed).';
    end if;
    update alert_outbox set resolved_at = now(), resolved_note = p_note where id = p_alert_id;
    return 'resolved';

  elsif p_action = 'assign' then
    select t.task_id, t.order_no into v_id, v_no from tg_assign_from_tile(
      coalesce(a.subject,'Alert '||p_alert_id), p_assignee_employee_id, p_due_on, a.severity,
      'alert', p_alert_id::text, null, null, null,
      coalesce(p_note, a.body), to_jsonb(a)) t;
    update alert_outbox set read_at = coalesce(read_at, now()) where id = p_alert_id;
    return 'order '||v_no||' issued';
  else
    raise exception 'Unknown action %. Valid: acknowledge, note, defer, resolve, assign.', p_action;
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_all_clear_falsifier(p_selftest_extra integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v         record;
  as_owner  jsonb;
  as_staff  jsonb;
  hazards   int := 0;
  examined  int := 0;
  offenders text[] := '{}';
begin
  for v in
    select c.relname
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind = 'v'
       and pg_get_viewdef(c.oid, true) ~* '\y(count|sum|avg|bool_and|bool_or)\s*\('
       and pg_get_viewdef(c.oid, true) !~* '\ygroup\s+by\y'
       and pg_get_viewdef(c.oid, true) ~* '=\s*0\y|\ycase\y'
       and pg_get_viewdef(c.oid, true) !~* '=\s*0\s+then'
     order by c.relname
  loop
    examined := examined + 1;

    begin
      execute format('select to_jsonb(t) from (select * from public.%I limit 1) t', v.relname)
        into as_owner;
    exception when others then continue;
    end;

    begin
      set local role authenticated;
      begin
        execute format('select to_jsonb(t) from (select * from public.%I limit 1) t', v.relname)
          into as_staff;
      exception when others then
        as_staff := null;
      end;
      reset role;
    exception when others then
      reset role;   /* never leave the session wearing a borrowed role */
      as_staff := null;
    end;

    if as_staff is not null and as_owner is not null and as_staff <> as_owner then
      hazards := hazards + 1;
      offenders := offenders || v.relname;
    end if;
  end loop;

  if p_selftest_extra is not null then
    hazards := hazards + greatest(p_selftest_extra, 0);
    offenders := offenders || format('SELF-TEST(+%s)', greatest(p_selftest_extra, 0));
  end if;

  insert into conformance_ledger
    (checker_key, subject_kind, subject_ref, verdict, numerator, denominator,
     the_arithmetic, drill, note)
  values
    ('detect.all_clear_falsifier', 'metric', 'views_that_reassure_when_blind',
     case when hazards = 0 then 'PASS' else 'FAIL' end,
     examined - hazards, examined,
     format('%s of %s ungrouped-aggregate views tell a signed-in user a DIFFERENT story than they '
            || 'tell the owner, while carrying no explicit zero-case to say they are blind. A view '
            || 'like this gets quieter as it gets worse. %s',
            hazards, examined,
            case when hazards = 0 then 'None found.'
                 else 'Found: ' || array_to_string(offenders, ', ') end),
     'Read the view as owner, then: set local role authenticated; select * from <view>; — if the '
     || 'answer changes and nothing in the output admits the caller is blind, that is the defect.',
     case when p_selftest_extra is not null then 'SELF-TEST: count inflated. Not a measurement.' end);

  return format('%s — %s hazard(s) of %s ungrouped-aggregate views examined%s',
                case when hazards = 0 then 'PASS' else 'FAIL' end, hazards, examined,
                case when hazards = 0 then '' else ': ' || array_to_string(offenders, ', ') end);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_allocation_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'denied' and coalesce(length(trim(new.decision_reason)), 0) < 15 then
    raise exception 'A denial needs a written reason of at least 15 characters so the requester knows why.';
  end if;
  if new.status in ('approved','denied') and old.status = 'pending' then
    new.decided_at := coalesce(new.decided_at, now());
    new.decided_by := coalesce(new.decided_by, auth.uid());
  end if;
  if new.status = 'approved' and new.approved_quantity is null then
    new.approved_quantity := new.quantity;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status in ('approved','denied') then
    if new.decider_name is null or length(trim(new.decider_name)) = 0 then
      raise exception 'An allocation decision must record who made it.';
    end if;
    if new.status = 'denied' and coalesce(length(trim(new.decision_reason)),0) < 20 then
      raise exception 'Denying an allocation needs a written reason of at least twenty characters.';
    end if;
    new.decided_at := coalesce(new.decided_at, now());
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_allocation_plan(p_grams numeric)
 RETURNS TABLE(rank integer, product_route text, product_family text, margin_per_input_gram numeric, gross_margin_pct numeric, units_open numeric, grams_needed_for_open_demand numeric, recommended_grams numeric, recommended_units numeric, projected_contribution numeric, basis text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare r record; remaining numeric := coalesce(p_grams, 0); i int := 0; take numeric;
begin
  for r in select * from v_route_margin loop
    exit when remaining <= 0;
    i := i + 1;
    take := least(remaining, nullif(r.grams_needed_for_open_demand, 0));
    if take is null then take := 0; end if;
    rank := i;
    product_route := r.product_route; product_family := r.product_family;
    margin_per_input_gram := r.margin_per_input_gram; gross_margin_pct := r.gross_margin_pct;
    units_open := r.units_open; grams_needed_for_open_demand := r.grams_needed_for_open_demand;
    recommended_grams := take;
    recommended_units := case when r.input_grams_per_unit > 0
      then floor(take * (r.yield_pct / 100.0) / r.input_grams_per_unit) else 0 end;
    projected_contribution := round((take * r.margin_per_input_gram)::numeric, 2);
    basis := case
      when take = 0 and r.units_open = 0 then 'No open demand recorded - nothing allocated'
      when take < r.grams_needed_for_open_demand then 'Supply ran out at this rank'
      else 'Full open demand covered' end;
    remaining := remaining - take;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_apply_naming_ladder(p_by text DEFAULT 'tg_apply_naming_ladder'::text)
 RETURNS TABLE(outcome text, discrepancies integer, corrections_raised integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_blend int := 0; v_confirm int := 0; v_wrong int := 0; v_corr int := 0;
  rec record;
begin
  ---------------------------------------------------------------- blends
  with x as (
    select d.discrepancy_key, lr.evidence, lr.contributors
    from discrepancy_register d
    cross join lateral f_strain_by_tag(substring(d.subject from '1A[0-9A-Z]{22}')) lr
    where d.resolved_at is null and d.class='strain' and lr.verdict like 'BLEND%'
  )
  update discrepancy_register d
  set resolved_at = now(), resolved_by = p_by,
      resolution_note = 'NOT A DISCREPANCY - BLEND. Rung 1, Metrc seed-to-sale: '||x.evidence
        ||'. Contributing strains: '||array_to_string(x.contributors, ', ')
        ||'. Metrc holds one strain field and this package has several, so neither the item '
        ||'name nor the strain field is wrong. Owner ruling 9 Aug 2026.'
  from x where x.discrepancy_key = d.discrepancy_key;
  get diagnostics v_blend = row_count;

  ------------------------------------------------- harvest confirms the strain field
  with x as (
    select d.discrepancy_key, lr.strain, lr.evidence
    from discrepancy_register d
    cross join lateral f_strain_by_tag(substring(d.subject from '1A[0-9A-Z]{22}')) lr
    where d.resolved_at is null and d.class='strain'
      and lr.strain is not null
      and lower(lr.strain) = lower(btrim(d.source_b_says))
  )
  update discrepancy_register d
  set resolved_at = now(), resolved_by = p_by,
      resolution_note = 'NOT A DISCREPANCY. Rung 1, Metrc seed-to-sale confirms the strain '
        ||'field as "'||x.strain||'" ('||x.evidence||'). The item name is a PRODUCT name, not '
        ||'a strain. Owner ruling 9 Aug 2026: identity is the tag, names come from Metrc '
        ||'seed-to-sale first.'
  from x where x.discrepancy_key = d.discrepancy_key;
  get diagnostics v_confirm = row_count;

  ------------------------------------------- harvest backs the item name: Metrc is wrong
  for rec in
    select btrim(regexp_replace(d.source_a_says,'^M\d+:\s*','')) as item_name,
           d.source_b_says as strain_field, lr.strain as true_strain, count(*)::int as packages
    from discrepancy_register d
    cross join lateral f_strain_by_tag(substring(d.subject from '1A[0-9A-Z]{22}')) lr
    where d.resolved_at is null and d.class='strain'
      and lr.strain is not null
      and lower(lr.strain) = lower(btrim(regexp_replace(d.source_a_says,'^M\d+:\s*','')))
    group by 1,2,3
  loop
    if not exists (select 1 from metrc_corrections c
                   where c.title = 'Strain field wrong in Metrc: '||rec.strain_field
                                   ||' should be '||rec.true_strain
                     and not c.fixed_in_metrc) then
      insert into metrc_corrections
        (title, what_is_wrong, why_it_matters, how_to_fix_in_metrc, packages_affected,
         raised_by, urgency, evidence_sql)
      values
        ('Strain field wrong in Metrc: '||rec.strain_field||' should be '||rec.true_strain,
         rec.packages||' packages carry the Metrc strain field "'||rec.strain_field||'" while '
           ||'the source harvest they came from is "'||rec.true_strain||'". Seed-to-sale is '
           ||'rung 1 of the naming ladder and outranks the strain field, so the strain field '
           ||'is the wrong one.',
         'Strain identity drives yield by strain, price by strain and the certificate chain. A '
           ||'package recorded under a strain it did not come from splits every per-strain '
           ||'figure across a name the plants never had. Correcting it only in our mirror would '
           ||'hide the fault from the state record (D2).',
         'In Metrc, correct the strain on these '||rec.packages||' packages to "'
           ||rec.true_strain||'". Where a package is finished and cannot be edited, record the '
           ||'correction against the harvest and note that historic packages cannot be re-tagged.',
         rec.packages::text, p_by,
         case when rec.packages >= 50 then 'high' else 'normal' end,
         'select d.subject, s.strain from discrepancy_register d cross join lateral '
           ||'f_strain_by_tag(substring(d.subject from ''1A[0-9A-Z]{22}'')) s '
           ||'where d.class=''strain'' and lower(s.strain) = lower('
           ||''''||replace(rec.true_strain,'''','''''')||''')');
      v_corr := v_corr + 1;
    end if;
  end loop;

  with x as (
    select d.discrepancy_key, lr.strain, lr.evidence
    from discrepancy_register d
    cross join lateral f_strain_by_tag(substring(d.subject from '1A[0-9A-Z]{22}')) lr
    where d.resolved_at is null and d.class='strain'
      and lr.strain is not null
      and lower(lr.strain) = lower(btrim(regexp_replace(d.source_a_says,'^M\d+:\s*','')))
  )
  update discrepancy_register d
  set resolved_at = now(), resolved_by = p_by,
      resolution_note = 'REAL - the Metrc STRAIN FIELD is wrong. Rung 1, seed-to-sale says "'
        ||x.strain||'" ('||x.evidence||'), which matches the item name, not the strain field. '
        ||'A Metrc correction has been raised to fix it AT SOURCE (D2). Cleared here only '
        ||'because the correction now carries it.'
  from x where x.discrepancy_key = d.discrepancy_key;
  get diagnostics v_wrong = row_count;

  return query
  select 'BLEND - no single strain exists'::text, v_blend, 0
  union all select 'seed-to-sale confirms the strain field; item name is a product name', v_confirm, 0
  union all select 'REAL - strain field wrong in Metrc, correction raised at source', v_wrong, v_corr
  union all select 'still open for a person (ladder could not answer)',
    (select count(*)::int from discrepancy_register where resolved_at is null and class='strain'), 0;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_apply_strain_rulings(p_by text DEFAULT 'tg_apply_strain_rulings'::text)
 RETURNS TABLE(pair_key text, ruling text, packages_closed integer, correction_raised boolean)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r        record;
  n        integer;
  raised   boolean;
begin
  for r in
    select * from strain_name_ruling
    where ruling <> 'not yet ruled'
      and exists (
        select 1 from discrepancy_register d
        where d.resolved_at is null and d.class = 'strain'
          and lower(btrim(d.source_a_says)) = lower(btrim(strain_name_ruling.item_name))
          and lower(btrim(d.source_b_says)) = lower(btrim(strain_name_ruling.strain_field)))
    order by packages desc
  loop
    raised := false;

    -- Metrc is the legal record. If the ruling says Metrc is wrong, the correction
    -- belongs there, with instructions, and it cannot be closed without a reference.
    if r.ruling in ('item name is wrong - correct it in Metrc',
                    'strain field is wrong - correct it in Metrc') then
      if not exists (select 1 from metrc_corrections c
                     where c.title = 'Strain naming: '||r.pair_key) then
        insert into metrc_corrections
          (title, what_is_wrong, why_it_matters, how_to_fix_in_metrc,
           packages_affected, raised_by, urgency, evidence_sql)
        values
          ('Strain naming: '||r.pair_key,
           'The Metrc item name says "'||r.item_name||'" while the Metrc strain field says "'
             ||r.strain_field||'" on '||r.packages||' packages. Ruled by '||coalesce(r.ruled_by,'?')
             ||': '||r.ruling||'.'||coalesce(' Note: '||r.note,''),
           'Strain identity drives yield by strain, pricing by strain and the certificate '
             ||'chain. Two names on one package means every per-strain figure is split across '
             ||'a name that does not exist. Correcting it only in our mirror would hide the '
             ||'fault from the state record.',
           case r.ruling
             when 'item name is wrong - correct it in Metrc'
               then 'In Metrc, edit the ITEM so its name matches the strain "'||r.strain_field
                    ||'". Items are edited under Admin > Items. Existing packages keep the old '
                    ||'item name until repackaged, so record which packages remain on the old name.'
             else 'In Metrc, correct the STRAIN on the affected packages to "'||r.item_name
                  ||'". Where the package is finished, record the correction against the harvest '
                  ||'and note that historic packages cannot be re-tagged.'
           end,
           r.packages::text, p_by,
           case when r.packages >= 100 then 'high' else 'normal' end,
           'select * from strain_name_ruling where pair_key = '''||replace(r.pair_key,'''','''''')||'''');
        raised := true;
      end if;
    end if;

    update discrepancy_register d
    set resolved_at = now(),
        resolved_by = coalesce(r.ruled_by, p_by),
        resolution_note = r.ruling
          ||' (ruled by '||coalesce(r.ruled_by,'?')||' on '
          ||coalesce(r.ruled_at::date::text,'?')||'; one ruling covering '||r.packages
          ||' packages on the pair '||r.pair_key||')'
          ||coalesce('. Note: '||r.note,'')
          ||case when raised then ' A Metrc correction was raised at source.' else '' end
    where d.resolved_at is null and d.class = 'strain'
      and lower(btrim(d.source_a_says)) = lower(btrim(r.item_name))
      and lower(btrim(d.source_b_says)) = lower(btrim(r.strain_field));
    get diagnostics n = row_count;

    -- close the routed finding alongside the discrepancy, with the ruling as the reason
    update finding_state s
    set state = 'closed',
        override_reason = 'Closed by owner ruling on the strain name pair '||r.pair_key
                          ||': '||r.ruling||'. One ruling, '||n||' packages. The ruling IS '
                          ||'the independent judgement - a second agent cannot second-guess '
                          ||'what is a business decision about naming.',
        override_by = coalesce(r.ruled_by, p_by),
        override_at = now(),
        changed_by  = p_by,
        note        = 'strain ruling applied'
    from discrepancy_register d
    where s.finding_key = 'disc:'||d.discrepancy_key
      and d.class = 'strain'
      and d.resolved_at is not null
      and lower(btrim(d.source_a_says)) = lower(btrim(r.item_name))
      and lower(btrim(d.source_b_says)) = lower(btrim(r.strain_field))
      and s.state <> 'closed';

    pair_key := r.pair_key; ruling := r.ruling;
    packages_closed := n; correction_raised := raised;
    return next;
  end loop;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_assertion_allowance_ratchet()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare x ratchet_exception%rowtype; k text;
begin
  if new.max_allowed > old.max_allowed then
    /* Same table, same shape, namespaced so it cannot collide with a
       ratchet_baseline metric of the same name. */
    k := 'data_assertion:' || new.assertion_key;

    select * into x from ratchet_exception
     where metric_key = k
       and from_baseline = old.max_allowed
       and to_baseline = new.max_allowed
       and consumed_at is null
     order by approved_at limit 1;

    if not found then
      raise exception
        'Assertion %: tolerated violations may not rise from % to %.',
        new.assertion_key, old.max_allowed, new.max_allowed
        using hint = 'This number records debt. It may fall as debt is paid and may never rise. '
                     'If new debt is genuinely unavoidable, that is the owner''s decision and it '
                     'is recorded as one: insert a ratchet_exception with metric_key '
                     '''data_assertion:<assertion_key>'' naming this exact rise, why it is '
                     'unavoidable, who approved it and the date it must fall by. There is no '
                     'other door, and disabling this trigger is not one.';
    end if;

    update ratchet_exception set consumed_at = now() where id = x.id;
    raise notice 'Assertion % allowance rose % -> % on exception #% approved by %, must fall by %.',
      new.assertion_key, old.max_allowed, new.max_allowed, x.id, x.approved_by, x.must_fall_by;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_assign_from_tile(p_title text, p_assignee_employee_id uuid, p_due_on date, p_priority text, p_source_view text, p_source_kpi text, p_source_value numeric, p_source_unit text, p_department text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_snapshot jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(task_id uuid, order_no text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_no text;
begin
  if not f_caller_is_admin() then
    raise exception 'Only admin-tier users may issue orders. Widening this to managers is a role-model decision for the owner.';
  end if;
  if coalesce(btrim(p_title),'') = '' then raise exception 'An order needs a title.'; end if;
  if p_assignee_employee_id is null then raise exception 'An order needs a named assignee - unassigned work is how 108 custody findings reached a week old.'; end if;

  v_no := tg_order_no();
  insert into tasks (title, description, status, priority, assignee_employee_id, due_on,
                     created_by, source_view, source_kpi, source_value, source_unit,
                     source_snapshot, department, order_no)
  values (p_title, p_description, 'open', coalesce(p_priority,'normal'), p_assignee_employee_id,
          p_due_on, auth.uid(), p_source_view, p_source_kpi, p_source_value, p_source_unit,
          coalesce(p_snapshot, jsonb_build_object('captured_at', now())), p_department, v_no)
  returning id into v_id;

  return query select v_id, v_no;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_audit_the_checks()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_missed int; v_problems int; v_run bigint; v_detail text;
begin
  select count(*) into v_missed from tg_verification_checks_sane_selftest() where not caught;

  if v_missed > 0 then
    insert into watchdog_runs default values returning id into v_run;
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run,'meta_check_blind','critical',
      'THE CHECK AUDITOR HAS GONE BLIND: ' || v_missed || ' of 5 self-test fixtures escaped detection',
      'tg_verification_checks_sane()','Whoever last edited the auditor','Since that edit',
      'This function certifies every other verification check as sound. If it stops catching, it '
      'returns a clean sheet while defective checks run unnoticed - which is how five of nineteen '
      'checks were found lying on 9 Aug 2026. A blind auditor is worse than none, because it '
      'manufactures confidence.',
      'Five deliberately broken checks are inserted, audited and removed. Each must be caught by '
      'its specific rule.',
      'Run: select * from tg_verification_checks_sane_selftest(); and repair whichever rule stopped firing.',
      v_missed || ' of 5 fixtures escaped', v_missed, 'settings','meta check auditor blind')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, record_count=excluded.record_count, run_id=excluded.run_id;
    return 'SELF-TEST FAILED: ' || v_missed || ' of 5 fixtures escaped. Audit not run.';
  end if;

  select count(*), string_agg(distinct check_key || ' (' || problem || ')', '; ')
    into v_problems, v_detail from tg_verification_checks_sane();

  if v_problems > 0 then
    insert into watchdog_runs default values returning id into v_run;
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run,'verification_checks_defective','elevated',
      v_problems || ' verification check(s) cannot be trusted: ' || left(coalesce(v_detail,''),400),
      'verification_checks','Whoever wrote the check','Since the check was written',
      'These are the checks that derive every fact two ways. A defective one either certifies a '
      'fault as fine or shouts permanently until people stop reading the board. On 9 Aug 2026 five '
      'of nineteen were defective and all three of the worst arrived in a single batch, written and '
      'scheduled and never verified.',
      'Each enabled check is audited for seven failure modes: cannot fail, incomplete, population '
      'mismatch, tolerance on an identity, source fails to run, never run, cannot pass.',
      'select * from tg_verification_checks_sane(); then fix the SQL, the tolerance or the severity.',
      v_problems || ' defective of ' || (select count(*) from verification_checks where enabled),
      v_problems,'settings','verification check defective meta')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  return 'self-test 5/5 passed; ' || v_problems || ' defective check(s) found';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_auditor_pass()
 RETURNS TABLE(checker text, subject text, verdict text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$#variable_conflict use_column

declare v_run uuid := gen_random_uuid();
begin
  -- ── DOCUMENTS: certificate on shipped material (rules C3, C3a) ──
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, pounds, the_arithmetic, drill, data_as_of)
  select v_run, 'detect.doc_completeness', 'C3a', 'metric', 'coa_on_shipped_packages',
         case when count(*) filter (where was_shipped and coa_count = 0) = 0
              then 'PASS' else 'FAIL' end,
         count(*) filter (where was_shipped and coa_count > 0),
         count(*) filter (where was_shipped),
         round(sum(pounds) filter (where was_shipped and coa_count = 0)::numeric, 1),
         count(*) filter (where was_shipped and coa_count > 0) || ' of ' ||
         count(*) filter (where was_shipped) || ' shipped packages have a certificate on file. ' ||
         count(*) filter (where was_shipped and coa_count = 0) ||
         ' do not. This means we cannot PRODUCE a certificate for them; it does not prove none ' ||
         'was issued (rule A3).',
         'v_item_documents', now()
  from v_item_documents;

  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, pounds, the_arithmetic, drill, data_as_of)
  select v_run, 'detect.doc_completeness', 'C3a', 'metric', 'manifest_on_shipped_packages',
         case when count(*) filter (where was_shipped and manifest_count = 0) = 0
              then 'PASS' else 'FAIL' end,
         count(*) filter (where was_shipped and manifest_count > 0),
         count(*) filter (where was_shipped),
         round(coalesce(sum(pounds) filter (where was_shipped and manifest_count = 0),0)::numeric,1),
         count(*) filter (where was_shipped and manifest_count > 0) || ' of ' ||
         count(*) filter (where was_shipped) || ' shipped packages have a manifest.',
         'v_item_documents', now()
  from v_item_documents;

  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, pounds, the_arithmetic, drill, data_as_of)
  select v_run, 'detect.doc_completeness', 'C3', 'metric', 'tested_before_shipped',
         case when count(*) filter (where was_shipped and not was_tested) = 0
              then 'PASS' else 'FAIL' end,
         count(*) filter (where was_shipped and was_tested),
         count(*) filter (where was_shipped),
         round(coalesce(sum(pounds) filter (where was_shipped and not was_tested),0)::numeric,1),
         count(*) filter (where was_shipped and not was_tested) ||
         ' package(s) were shipped having never been tested.',
         'v_item_documents', now()
  from v_item_documents;

  -- ── SECURITY: the class nothing was watching (rule E6) ──
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, data_as_of)
  select v_run, 'detect.security_posture', 'E6', 'metric', 'views_enforcing_rls',
         case when bad = 0 then 'PASS' else 'FAIL' end, total - bad, total,
         (total - bad) || ' of ' || total || ' views enforce row-level security. ' || bad ||
         ' run as the view owner and bypass every policy on their base tables.', now()
  from (select count(*) as total,
               count(*) filter (where coalesce((select option_value from pg_options_to_table(c.reloptions)
                                                where option_name='security_invoker'),'false') <> 'true') as bad
          from pg_class c join pg_namespace n on n.oid=c.relnamespace
         where n.nspname='public' and c.relkind='v') s;

  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, data_as_of)
  select v_run, 'detect.security_posture', 'E6', 'metric', 'matviews_not_readable_by_staff',
         case when exposed = 0 then 'PASS' else 'FAIL' end, total - exposed, total,
         exposed || ' of ' || total || ' materialized views are readable by every signed-in ' ||
         'user. Postgres cannot apply row-level security to a materialized view at all.', now()
  from (select count(*) as total,
               count(*) filter (where has_table_privilege('authenticated', c.oid, 'SELECT')) as exposed
          from pg_class c join pg_namespace n on n.oid=c.relnamespace
         where n.nspname='public' and c.relkind='m') s;

  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, data_as_of)
  select v_run, 'detect.security_posture', 'E6', 'metric', 'tables_rls_with_policy',
         case when naked = 0 then 'PASS' else 'FAIL' end, total - naked, total,
         naked || ' table(s) have row-level security enabled with NO policy at all, so nothing ' ||
         'can read them through the interface -- fail-closed, and invisible on screen.', now()
  from (select count(*) filter (where c.relrowsecurity) as total,
               count(*) filter (where c.relrowsecurity
                                 and not exists (select 1 from pg_policy p where p.polrelid=c.oid)) as naked
          from pg_class c join pg_namespace n on n.oid=c.relnamespace
         where n.nspname='public' and c.relkind='r') s;

  -- ── LAW 2: mirror freshness. A check over stale data is not a passing check. ──
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, data_as_of, the_arithmetic, drill)
  select v_run, 'detect.mirror_freshness', 'D1', 'mirror', t.tbl,
         case when t.last_sync > now() - interval '36 hours' then 'PASS' else 'FAIL' end,
         t.n, t.n, t.last_sync,
         t.tbl || ' last synced ' || t.last_sync || ' (' ||
         round(extract(epoch from (now() - t.last_sync))/3600.0, 1) || ' hours ago), ' ||
         t.n || ' rows. Every sync status reads "succeeded" regardless.',
         t.tbl
  from (select 'metrc_items / '||license as tbl, max(synced_at) as last_sync, count(*) as n
             from metrc_items group by license
        union all select 'metrc_strains / '||license,   max(synced_at), count(*) from metrc_strains   group by license
        union all select 'metrc_locations / '||license, max(synced_at), count(*) from metrc_locations group by license
        union all select 'metrc_packages / '||license,  max(synced_at), count(*) from metrc_packages  group by license) t
  where t.last_sync is not null;

  -- ── PROVE: persist the tile reconciliation, which never had a memory ──
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, data_as_of)
  select v_run, 'prove.reconcile_tiles', 'C2', 'metric', 'tiles_reconciled',
         case when r.bad = 0 then 'PASS' else 'FAIL' end, r.good, r.total,
         r.good || ' of ' || r.total || ' tiles reconcile to their drill. ' || r.bad ||
         ' disagree or cannot be verified without a declared drill column and aggregate.', now()
  from (select count(*) as total,
               count(*) filter (where verdict = 'RECONCILED') as good,
               count(*) filter (where verdict in ('FAIL','DISAGREES','REVIEW')) as bad
          from tg_reconcile_tiles()) r;

  -- ── PROVE: the two-source suite. Its own silence is the finding. ──
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, data_as_of)
  select v_run, 'prove.verification_suite', 'A4', 'metric', 'two_source_checks_agreeing',
         case when total = 0 then 'UNCHECKED'
              when disagreeing = 0 then 'PASS' else 'FAIL' end,
         total - disagreeing,
         nullif(total, 0),
         case when total = 0
              then 'No verification run has ever been recorded for the current check set.'
              else (total - disagreeing) || ' of ' || total ||
                   ' two-source checks agree within tolerance.' end,
         (select max(ran_at) from verification_runs)
  from (select count(*) as total,
               count(*) filter (where upper(verdict) <> 'AGREE') as disagreeing
          from (select distinct on (check_key) check_key, verdict
                  from verification_runs
                 order by check_key, ran_at desc) latest) v;

  -- ── LAW 3: coverage is itself a verdict, recorded so it can be trended. ──
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, data_as_of)
  select v_run, 'detect.security_posture', 'A3', 'metric', 'platform_coverage',
         case when never = 0 then 'PASS' else 'FAIL' end, total - never, total,
         (total - never) || ' of ' || total || ' subjects have ever been checked by anything. ' ||
         never || ' have never been examined -- green over an unexamined subject means "not looked at".',
         now()
  from (select count(*) as total, count(*) filter (where coverage = 'NEVER CHECKED') as never
          from v_conformance_coverage) c;

  return query
    select cl.checker_key, cl.subject_ref, cl.verdict,
           coalesce(cl.the_arithmetic, cl.note)
      from conformance_ledger cl
     where cl.run_id = v_run
     order by case cl.verdict when 'FAIL' then 1 when 'DISAGREE' then 2
                              when 'UNCHECKED' then 3 else 4 end, cl.subject_ref;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_backfill_sweep(p_by text DEFAULT 'cron:backfill-sweep'::text)
 RETURNS TABLE(job_key text, remaining integer, previous integer, verdict text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  w           record;
  v_now       integer;
  v_prev      integer;
  v_oldest    integer;
  v_oldest_at timestamptz;
  v_min_days  constant integer := 3;   -- the shortest history that can support a verdict
  v_verd      text;
begin
  for w in select * from backfill_watch where enabled order by job_key loop

    begin
      execute w.remaining_sql into v_now;
    exception when others then
      insert into agent_findings
        (agent, severity, headline, detail, scope, action, drill_to, fingerprint)
      values ('Metrc & Compliance','elevated',
              'Backfill '||w.job_key||' cannot be measured - its remaining-count query failed',
              'The query that counts what is left threw: '||left(sqlerrm,200)
              ||'. Until it runs we cannot tell a finished backfill from a dead one.',
              w.job_key, 'Fix backfill_watch.remaining_sql for '||w.job_key,
              'backfill_watch', 'backfill_uncountable:'||w.job_key)
      on conflict do nothing;
      continue;
    end;

    select r.remaining into v_prev from backfill_reading r
     where r.job_key = w.job_key order by r.read_at desc limit 1;

    select r.remaining, r.read_at into v_oldest, v_oldest_at
    from backfill_reading r
    where r.job_key = w.job_key and r.read_at > now() - interval '7 days'
    order by r.read_at asc limit 1;

    insert into backfill_reading(job_key, remaining, read_by)
    values (w.job_key, v_now, p_by);

    v_verd := case
      when v_now <= w.accepted_floor then 'COMPLETE'
      when v_prev is null            then 'FIRST READING'
      when v_now <  v_prev           then 'DRAINING'
      -- A stall verdict needs enough history to earn it.
      when v_oldest_at is null or v_oldest_at > now() - make_interval(days => v_min_days)
                                     then 'TOO SOON TO SAY'
      when v_now >= v_oldest         then 'STALLED'
      else 'FLAT'
    end;

    if v_verd = 'STALLED' then
      insert into agent_findings
        (agent, severity, headline, detail, metric, units, scope, action, drill_to, fingerprint)
      values ('Metrc & Compliance','elevated',
              'Backfill '||w.job_key||' has not reduced its backlog in seven days',
              'WHAT: '||w.what_it_drains||'. Remaining is '||v_now||', against '||v_oldest
              ||' recorded '||to_char(v_oldest_at,'DD Mon YYYY HH24:MI')
              ||', with an accepted floor of '||w.accepted_floor||'. '
              ||'WHY IT MATTERS: the job is running and achieving nothing, which looks '
              ||'identical to a finished job from outside. '
              ||'HOW DETECTED: tg_backfill_sweep, comparing readings at least '||v_min_days
              ||' days apart. '
              ||'SOLUTIONS: (1) fix whatever is blocking it; (2) if the remainder is '
              ||'legitimately undrainable, raise accepted_floor AND write the reason, which '
              ||'the table requires; (3) retire the job. '
              ||'RECOMMENDATION: (1) or (2). Never leave it flat and unexplained.',
              v_now, 'items left', w.job_key,
              'Unblock the backfill, or record an evidenced floor',
              'backfill_watch', 'backfill_stalled:'||w.job_key)
      on conflict do nothing;
    end if;

    if v_verd = 'COMPLETE' and coalesce(w.cadence_note,'') <> '' then
      insert into agent_findings
        (agent, severity, headline, detail, metric, units, scope, action, drill_to, fingerprint)
      values ('Metrc & Compliance','watch',
              'Backfill '||w.job_key||' has drained but still runs at its catch-up cadence',
              'WHAT: '||w.what_it_drains||'. Remaining is '||v_now||', at or below the accepted '
              ||'floor of '||w.accepted_floor||'. Cadence: '||w.cadence_note||'. '
              ||'WHY IT MATTERS: waste rather than breakage, but a job hammering a finished '
              ||'queue also hides the day it genuinely has work again. '
              ||'RECOMMENDATION: drop it to a maintenance cadence. Do not delete it.',
              v_now, 'items left', w.job_key,
              'Reduce the schedule to a maintenance cadence',
              'cron.job', 'backfill_overrunning:'||w.job_key)
      on conflict do nothing;
    end if;

    update agent_findings f
    set resolved_at = now(),
        resolution  = 'Remaining is '||v_now||' and the verdict is now '||v_verd
                      ||'. Stood down by '||p_by||'; re-derive with tg_backfill_sweep().'
    where f.fingerprint = 'backfill_stalled:'||w.job_key
      and f.resolved_at is null
      and v_verd in ('DRAINING','COMPLETE','TOO SOON TO SAY');

    job_key := w.job_key; remaining := v_now; previous := v_prev; verdict := v_verd;
    return next;
  end loop;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_backup_before_import(p_rows jsonb, p_report_key text, p_import uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t record; sql text; n int;
begin
  select * into t from metrc_report_types where report_key = p_report_key;
  if t.key_source_cols is null then return 0; end if;

  sql := format(
    'insert into metrc_import_backup (import_id, target_table, action, key_values, before_row)
     select %L, %L, ''updated'',
            jsonb_build_object(%s),
            to_jsonb(x)
       from %I x
      where exists (
        select 1 from jsonb_array_elements($1) r
         where %s = %s)',
    p_import, t.target_table,
    (select string_agg(format('%L, x.%I', k, k), ', ') from unnest(t.key_cols) k),
    t.target_table,
    (select string_agg(format('coalesce(x.%I::text,'''')', k), ' || ''|'' || ')
     from unnest(t.key_cols) k),
    (select string_agg(format('coalesce(r->>%L,'''')', s), ' || ''|'' || ')
     from unnest(t.key_source_cols) s));
  execute sql using p_rows;
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_block_forensic_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_code text; v_note text; v_appr text;
begin
  v_code := coalesce(current_setting('tg.forensic_delete_code', true), '');
  v_note := coalesce(current_setting('tg.forensic_delete_note', true), '');
  v_appr := coalesce(current_setting('tg.forensic_delete_approver', true), '');

  if v_code = '' and v_note = '' then
    raise exception '%', 'RULE H2: ' || tg_table_name ||
      ' is an append-only forensic record and cannot be deleted.' || chr(10) ||
      'It is evidence of what the business knew and when. Append a reversing row instead.' || chr(10) ||
      'If a uniqueness constraint genuinely requires removing duplicates, record the decision ' ||
      'in issue_decisions first, then set all three of:' || chr(10) ||
      '  set local tg.forensic_delete_code     = ''DUPLICATE_CONSTRAINT'';' || chr(10) ||
      '  set local tg.forensic_delete_note     = ''<at least 40 characters saying why>'';' || chr(10) ||
      '  set local tg.forensic_delete_approver = ''<who agreed>'';' || chr(10) ||
      'Valid codes are in Settings > Reason Codes (v_reason_settings).'
      using errcode = 'check_violation';
  end if;

  -- Validates the code, the note length and the second approver, or raises telling you why.
  perform f_check_reason('forensic_delete', v_code, v_note, null, v_appr);

  insert into audit_events (actor, entity, entity_id, action, old_value, reason)
  values (coalesce(current_setting('request.jwt.claim.email', true), session_user),
          tg_table_name, coalesce(to_jsonb(old)->>'id','?'), 'forensic_delete_allowed',
          to_jsonb(old), v_code || ' | ' || v_note || ' | approved by ' || v_appr);
  return old;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_block_view_drops()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
declare
  obj record;
  allowed text := current_setting('tg.allow_drop', true);
begin
  if allowed = 'yes' then
    return;                       -- explicitly permitted for this session
  end if;

  for obj in select * from pg_event_trigger_dropped_objects()
  loop
    if obj.schema_name = 'public'
       and obj.object_type in ('view','materialized view') then
      raise exception
        'BLOCKED: dropping % "%" is not allowed.',
        obj.object_type, obj.object_identity
        using hint =
          'Use CREATE OR REPLACE VIEW instead - it keeps every dependent view alive. '
          'Dropping a view cascades and has destroyed the dashboards three times. '
          'If you genuinely must drop it, run: set tg.allow_drop = ''yes''; first, '
          'then re-create every dependent view and CHECK EACH ONE RETURNS ROWS.',
        errcode = 'raise_exception';
    end if;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_call_function(p_path text, p_body jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare anon text; req bigint;
begin
  select value into anon from integration_secrets where name = 'SUPABASE_ANON_KEY';
  if anon is null then
    raise exception 'SUPABASE_ANON_KEY is not stored. Every scheduled call to an Edge '
      'Function needs it: the gateway checks a bearer token before the function''s own '
      'admin key is ever seen.';
  end if;
  select net.http_post(
    url := 'https://fxetuqjryttnypgepsru.supabase.co/functions/v1/' || p_path,
    headers := jsonb_build_object(
      'x-admin-key', (select value from integration_secrets where name = 'TG_ADMIN_KEY'),
      'Authorization', 'Bearer ' || anon,
      'Content-Type', 'application/json'),
    body := p_body) into req;
  return req;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_can_access_metrc_reports()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from app_users u
                  where u.user_id = auth.uid()
                    and u.role::text = any (array['owner','executive','cfo']));
$function$
;
CREATE OR REPLACE FUNCTION public.tg_can_use_ai()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from app_users u
                 where u.user_id = auth.uid() and u.role in ('owner','executive'));
$function$
;
CREATE OR REPLACE FUNCTION public.tg_canary()
 RETURNS TABLE(page text, category text, source text, status text, note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; has_rows boolean; started timestamptz; ms numeric;
begin
  for r in
    select label, nav_registry.category, table_ref
    from nav_registry
    where enabled and table_ref is not null
    order by nav_registry.category, label
  loop
    page := r.label; category := r.category; source := r.table_ref; note := null;

    if to_regclass('public.'||r.table_ref) is null then
      status := 'MISSING'; note := 'object does not exist - page renders blank';
      return next; continue;
    end if;

    started := clock_timestamp();
    begin
      set local statement_timeout = '2s';
      execute format('select exists(select 1 from %I limit 1)', r.table_ref) into has_rows;
      ms := extract(epoch from clock_timestamp() - started) * 1000;
      if not has_rows then
        status := 'EMPTY'; note := 'exists but returns no rows';
      elsif ms > 800 then
        status := 'SLOW';  note := round(ms)||' ms to return one row';
      else
        status := 'ok';
      end if;
    exception
      when query_canceled then
        status := 'SLOW'; note := 'over 2 seconds for a single row - page will hang';
      when others then
        status := 'ERROR'; note := left(sqlerrm,120);
    end;
    return next;
  end loop;
  reset statement_timeout;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_canary_record()
 RETURNS canary_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare row canary_runs;
begin
  with c as (select * from tg_canary())
  insert into canary_runs (pages, ok, empty, missing, errored, detail)
  select count(*),
         count(*) filter (where status='ok'),
         count(*) filter (where status='EMPTY'),
         count(*) filter (where status='MISSING'),
         count(*) filter (where status='ERROR'),
         coalesce(jsonb_agg(jsonb_build_object('page',page,'source',source,'status',status,'note',note))
                  filter (where status <> 'ok'), '[]'::jsonb)
  from c
  returning * into row;
  return row;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_capture_unmapped(p_columns text[], p_file_name text, p_licence text, p_sample jsonb, p_rows integer, p_closest text, p_missing text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sig text; rid uuid;
begin
  select md5(string_agg(lower(btrim(c)), '|' order by lower(btrim(c)))) into sig
  from unnest(p_columns) c;

  insert into metrc_report_unmapped
    (file_name, licence, columns, signature, sample_row, row_count, closest_report, closest_missing)
  values (p_file_name, p_licence, p_columns, sig, p_sample, p_rows, p_closest, p_missing)
  on conflict (signature) do update set
    last_seen = now(), times_seen = metrc_report_unmapped.times_seen + 1,
    file_name = coalesce(excluded.file_name, metrc_report_unmapped.file_name)
  returning id into rid;

  insert into agent_findings (agent, severity, headline, detail, scope, action, drill_to, fingerprint)
  values ('Metrc & Compliance', 'elevated',
    'Unrecognised Metrc report uploaded: ' || coalesce(p_file_name, '(no name)'),
    'A report was uploaded that matches no registered signature. Closest is '
      || coalesce(p_closest, 'nothing') || ', missing ' || coalesce(array_to_string(p_missing, ', '), '-')
      || '. Columns in the file: ' || array_to_string(p_columns, ', ')
      || '. Either the export was run with columns hidden, or this is a Metrc report the platform '
      || 'does not know yet. Propose a mapping on Settings > Metrc Report Imports.',
    'metrc_report_unmapped', 'Propose a mapping, then have an administrator approve it.',
    'metrc_report_imports', 'unmapped:' || sig)
  on conflict do nothing;

  return rid;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_challenge_metric(p_key text, p_challenge text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if length(coalesce(p_challenge,'')) < 10 then
    raise exception 'A challenge needs a written question of at least ten characters.';
  end if;
  insert into metric_challenges (metric_key, challenge) values (p_key, p_challenge) returning id into v_id;
  update metric_provenance set status='UNDER REVIEW', updated_at=now() where metric_key=p_key;
  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_check_agent_claims()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v numeric; n integer := 0;
begin
  for r in select * from agent_claims where proof_sql is not null loop
    begin execute r.proof_sql into v; exception when others then v := null; end;
    update agent_claims
       set live_value = v, checked_at = now(),
           status = case when v is null then 'UNVERIFIABLE'
                         when claimed_value is null then 'UNVERIFIABLE'
                         when abs(v - claimed_value) < 0.005 then 'CONFIRMED'
                         else 'REFUTED' end
     where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_check_brain_claims()
 RETURNS TABLE(claim_key text, brain_file text, written numeric, live numeric, drifted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v numeric; drift boolean;
begin
  for r in select * from brain_claims loop
    begin
      execute r.proof_sql into v;
    exception when others then
      v := null;
    end;
    drift := case
               when v is null or r.written_value is null then true
               when r.written_value = 0 then v <> 0
               else abs(v - r.written_value) / nullif(abs(r.written_value),0) * 100 > r.tolerance_pct
             end;
    update brain_claims
       set last_checked = now(), last_value = v, drifted = drift
     where brain_claims.claim_key = r.claim_key;

    if drift then
      insert into watchdog_findings (fingerprint, severity, what, where_it_is,
             who_is_accountable, why_it_matters, how_it_was_detected, what_to_do,
             the_arithmetic, record_count)
      values ('brain:stale-claim:' || r.claim_key, r.severity,
              'The brain states a figure the live system no longer supports: ' || r.claim_text,
              r.brain_file,
              'Agent D (brain owner)',
              'brain/AGENT_BRIEFING.md is printed VERBATIM to every agent by the '
              'SessionStart hook. A stale number there is not a documentation '
              'problem - it is wrong training that every agent trusts. Two claims '
              'written on 7 Aug 2026 were false within two hours.',
              'tg_check_brain_claims() re-ran the claim''s own proof query.',
              'Re-measure, correct the figure in ' || r.brain_file || ', and update '
              'written_value in brain_claims. Do NOT delete the claim to silence it.',
              'written ' || coalesce(r.written_value::text,'null') ||
              ' vs live ' || coalesce(v::text,'query failed'),
              1)
      on conflict do nothing;
    end if;

    claim_key := r.claim_key; brain_file := r.brain_file;
    written := r.written_value; live := v; drifted := drift;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_check_fixture_ratchet(p_by text DEFAULT 'cron:fixture-ratchet'::text)
 RETURNS TABLE(metric text, baseline integer, actual integer, verdict text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare b integer; a integer;
begin
  select r.baseline into b from ratchet_baseline r where r.metric_key='checkers_without_a_fixture';
  select count(*)::int into a from checker_registry where enabled and grandfathered;

  if a > b then
    insert into agent_findings
      (agent, severity, headline, detail, metric, units, scope, action, drill_to, fingerprint)
    values ('QA & Independent Verification','critical',
      'Unproven checkers rose from '||b||' to '||a||' - the ratchet has been breached',
      'WHAT: a checker was enabled without a fixture proving it can fail, and grandfathered '
      ||'instead. WHY IT MATTERS: every one of the seven defects recorded on 9 Aug 2026 was a '
      ||'FALSE ALARM at 4x to 15x, and each would have been caught by a fixture demanding the '
      ||'check stay quiet on a legitimate case. This number is the size of that risk and it is '
      ||'growing. HOW DETECTED: checker_registry against ratchet_baseline. '
      ||'RECOMMENDATION: write the fixture, or disable the checker. Do not raise the baseline.',
      a,'checkers','checker_registry',
      'Write the missing fixture or disable the checker',
      'checker_registry','fixture_ratchet_breached')
    on conflict do nothing;
  else
    update agent_findings set resolved_at = now(),
      resolution = 'Unproven checkers are at '||a||' against a baseline of '||b||'.'
    where fingerprint = 'fixture_ratchet_breached' and resolved_at is null;
  end if;

  -- pay down the debt: a baseline may always fall
  if a < b then
    update ratchet_baseline set baseline = a,
      note = coalesce(note,'')||' Lowered to '||a||' on '||current_date||' by '||p_by||'.'
    where metric_key = 'checkers_without_a_fixture';
  end if;

  return query select 'checkers_without_a_fixture'::text, b, a,
    case when a > b then 'BREACHED' when a < b then 'PAID DOWN' else 'holding' end;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_check_forensic_panel_freshness(p_by text DEFAULT 'cron:forensic-panel-freshness'::text, p_slo interval DEFAULT '00:30:00'::interval)
 RETURNS TABLE(matview text, computed_at timestamp with time zone, age interval, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_at   timestamptz;
  v_age  interval;
  v_verdict text;
  v_sev  text;
begin
  select max(m.computed_at) into v_at from mv_forensic_audit_panel m;
  v_age     := now() - v_at;
  v_verdict := f_matview_freshness_verdict(v_at, now(), p_slo);

  if v_verdict = 'ok' then
    update agent_findings
       set resolved_at = now(),
           resolution  = 'Panel refreshed '||coalesce(v_age::text,'?')||' ago, inside the '
                         ||p_slo::text||' SLO. Cleared by '||p_by||'.'
     where fingerprint = 'forensic_panel_stale' and resolved_at is null;
  else
    v_sev := case when v_verdict in ('DEAD','NEVER COMPUTED') then 'critical' else 'elevated' end;

    insert into agent_findings
      (agent, agent_key, severity, headline, detail, metric, units, scope, action, drill_to, fingerprint)
    values (
      'Watchdog & Silent Failures','lane:W', v_sev,
      'Forensic audit panel is '||v_verdict||' - last computed '
        ||coalesce(round(extract(epoch from v_age)/60)::text||' min ago','never'),
      'WHAT: mv_forensic_audit_panel backs the forensic tile on every Command Center page '
      ||'load. Its computed_at is '||coalesce(v_at::text,'NULL')||', which is '
      ||coalesce(v_age::text,'unmeasurable')||' old against an SLO of '||p_slo::text||'. '
      ||'WHY IT MATTERS: the tile keeps rendering numbers and gives no sign they have '
      ||'stopped moving. Command Center numbers once sat frozen for six days under a '
      ||'"Live from the records" header because the refresh JOB was watched and the '
      ||'VALUES were not. HOW DETECTED: mv_forensic_audit_panel.computed_at against now(), '
      ||'by '||p_by||'. RECOMMENDATION: check cron job refresh-forensic-panel in '
      ||'cron.job_run_details; a statement timeout there is the likely cause.',
      round(extract(epoch from v_age)/60), 'minutes stale',
      'mv_forensic_audit_panel',
      'Investigate cron job refresh-forensic-panel, then refresh the matview',
      'v_forensic_panel_freshness','forensic_panel_stale')
    on conflict do nothing;   -- af_open_fp: one OPEN finding per fingerprint; recurrence allowed after close
  end if;

  return query select 'mv_forensic_audit_panel'::text, v_at, v_age, v_verdict;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_check_role_clearance()
 RETURNS TABLE(result text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_n int; d text;
begin
  select count(*) into v_n from v_role_clearance_breaches;
  if v_n > 0 then
    select string_agg(distinct breach_type||': '||view_key||coalesce(' ('||role||')',''), '; ')
      into d from v_role_clearance_breaches;
    insert into watchdog_runs default values returning id into v_run;
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run,'role_clearance_breach','critical',
      v_n||' page(s) are visible to a role that should not see them',
      'nav_registry and nav_role_visibility',
      'Whoever added the page', 'Since the page was added or the denial removed',
      'useNav hides ONLY what is explicitly marked visible=false, so any unconfigured page is shown to everyone. Before this was configured a staff account could see 38 of the 39 sensitive pages - payroll, wages, valuation rates, cost inputs, cash and licences. Onboarding staff in that state would hand every one of them the margin and payroll data.',
      'Compared each role''s rank in app_roles against sensitive_page_policy.min_rank, reproducing useNav''s deny-list logic exactly.',
      'Add a sensitive_page_policy row for an unclassified page, or insert nav_role_visibility (view_key, role, visible=false) for the roles below its clearance.',
      d, v_n, 'menu_manager','role clearance visibility breach')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;
  return query select case when v_n=0 then 'PASS' else 'FAIL' end::text,
                      (v_n::text||' clearance breach(es)')::text;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_check_row_count(p_stated integer, p_supplied integer, p_mapped integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_stated is null then 'No count printed in the file - could not be checked.'
    when p_supplied <> p_stated then
      'FAILED: the file states ' || p_stated || ' records but ' || p_supplied
      || ' rows were read from it. The parser is losing or inventing rows.'
    when p_mapped < p_stated then
      'FAILED: the file states ' || p_stated || ' records, ' || p_supplied
      || ' were read, but only ' || p_mapped || ' were stored. '
      || (p_stated - p_mapped) || ' rows were dropped by the mapper.'
    else 'Passed: ' || p_mapped || ' stored against ' || p_stated || ' stated.' end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_check_site_deploy()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_site  text := 'https://twisted-growers-enterprise-os.netlify.app';
  v_req   bigint;
  p       record;
  r       record;
  prev    record;
  v_mig   timestamptz;
  v_grace numeric;
  v_lag   numeric;
  v_verdict text;
  v_fp    text;
  v_what  text;
  v_id    bigint;
  v_out   text := '';
begin
  /* PHASE B — collect answers for probes still waiting on pg_net. */
  for p in select * from site_deploy_probe
            where req_id is not null and status_code is null
              and fired_at > now() - interval '2 hours'
  loop
    select * into r from net._http_response where id = p.req_id;
    if found then
      update site_deploy_probe set
        status_code = coalesce(r.status_code, -1),
        note        = nullif(left(coalesce(r.error_msg,''),200),''),
        live_commit = substring(r.content from '<meta name="tg-build-commit" content="([^"]*)"'),
        built_at    = nullif(substring(r.content from '<meta name="tg-build-at" content="([^"]*)"'),'')::timestamptz
      where id = p.id;
    elsif p.fired_at < now() - interval '10 minutes' then
      update site_deploy_probe
         set status_code = -1, note = 'no response recorded by pg_net'
       where id = p.id;
    end if;
  end loop;

  /* THE FRESHNESS ANCHOR — the newest applied migration, parsed as UTC. */
  select max(make_timestamptz(substring(version,1,4)::int, substring(version,5,2)::int,
                              substring(version,7,2)::int, substring(version,9,2)::int,
                              substring(version,11,2)::int, substring(version,13,2)::numeric,
                              'UTC'))
    into v_mig
    from supabase_migrations.schema_migrations
   where version ~ '^[0-9]{14}';

  v_grace := coalesce(f_rule('site_deploy_lag_minutes'), 90);

  /* VERDICT on the newest completed probe. */
  select * into p from site_deploy_probe
   where status_code is not null
   order by fired_at desc limit 1;

  if found then
    if p.status_code <> 200 then
      select * into prev from site_deploy_probe
       where status_code is not null and id <> p.id
       order by fired_at desc limit 1;
      /* one failed fetch is a blip; two in a row is an outage */
      if found and prev.status_code <> 200 then v_verdict := 'DOWN'; else v_verdict := 'BLIP'; end if;
    elsif p.live_commit is null or p.built_at is null then
      v_verdict := 'NO_STAMP';
    else
      v_lag := extract(epoch from (v_mig - p.built_at)) / 60.0;
      v_verdict := case when v_lag > v_grace then 'STALE' else 'OK' end;
    end if;

    update site_deploy_probe
       set verdict = v_verdict, newest_migration = v_mig, lag_minutes = round(coalesce(v_lag,0),1)
     where id = p.id;

    v_fp := case v_verdict when 'DOWN' then 'site-deploy-down'
                           when 'STALE' then 'site-deploy-stale'
                           when 'NO_STAMP' then 'site-deploy-stale'
                           else null end;

    if v_fp is not null then
      if not exists (select 1 from watchdog_findings
                      where fingerprint = v_fp and cleared_at is null) then
        v_what := case when v_verdict = 'DOWN'
          then 'THE LIVE SITE IS NOT ANSWERING. Two consecutive probes failed (last HTTP ' || p.status_code || ').'
          else 'THE LIVE SITE IS NOT RUNNING CURRENT WORK. Its build ('
               || coalesce(to_char(p.built_at,'DD Mon HH24:MI'),'no stamp') || ', commit '
               || coalesce(left(p.live_commit,7),'unknown') || ') is '
               || round(coalesce(v_lag,0)) || ' minutes older than the newest applied migration ('
               || to_char(v_mig,'DD Mon HH24:MI') || '). Pushes are happening and deploys are not — the 18 Aug freeze pattern.'
          end;
        insert into watchdog_findings
          (fingerprint, severity, what, where_it_is, who_is_accountable, when_it_started,
           why_it_matters, how_it_was_detected, what_to_do, drill, search_text,
           record_count, solutions, guard_recommendation, evidence)
        values
          (v_fp, 'critical', v_what,
           'Netlify site twisted-growers-enterprise-os.netlify.app, deploys tab',
           'Agent I (Database COO) first; whoever pushed the breaking commit second',
           'First detected ' || to_char(now(),'DD Mon YYYY HH24:MI'),
           'Every fix committed after the freeze is invisible to every user. On 18 Aug 2026 this state lasted five hours, the owner was the detector, and his verdict was FIX PROPERLY.',
           'tg_check_site_deploy() — the database fetched the public site, read its vite build stamp, and compared it against the newest applied migration. Threshold: site_deploy_lag_minutes (owner rule, currently ' || v_grace || ').',
           'Open the Netlify deploy list, read the FIRST failed build''s gate banner (the runner names the failing gate at the bottom), fix that gate, push. Do not retry builds without reading the banner.',
           'agent_findings',
           'site deploy netlify stale down behind build failed freeze',
           1,
           array[
             'Read the failing gate named at the bottom of the Netlify build log and fix that exact thing.',
             'If the gate is edge-function-drift: deploy the changed function, re-pin its hash in tools/checks/edge-function-manifest.json, push.',
             'If no builds are triggering at all: the GitHub webhook died (12 Aug pattern) — retrigger with an empty commit and check Netlify build hooks.',
             'After the fix, confirm this finding clears itself on the next 10-minute probe — do not clear it by hand.'],
           'The site build must never be older than the newest migration by more than the owner-set threshold. This finding clears itself when the live stamp catches up.',
           jsonb_build_object('probe_id', p.id, 'live_commit', p.live_commit, 'built_at', p.built_at,
                              'newest_migration', v_mig, 'lag_minutes', round(coalesce(v_lag,0),1),
                              'status_code', p.status_code))
        returning id into v_id;
        perform f_alert_all_admins(v_id);
        v_out := v_out || 'RAISED ' || v_fp || ' finding ' || v_id || '. ';
      end if;
    elsif v_verdict = 'OK' then
      /* recovery: clear open deploy findings and resolve any queued-but-unsent alarms
         so a healed site never emails stale news at :45 */
      update watchdog_findings set cleared_at = now()
       where fingerprint in ('site-deploy-stale','site-deploy-down') and cleared_at is null;
      update alert_outbox
         set resolved_at = now(),
             resolved_note = 'Site recovered before this alert was sent — cleared by tg_check_site_deploy().'
       where source = 'guard' and source_ref in ('site-deploy-stale','site-deploy-down')
         and sent_at is null and resolved_at is null;
      v_out := v_out || 'verdict OK, lag ' || round(coalesce(v_lag,0),1) || ' min. ';
    else
      v_out := v_out || 'verdict ' || v_verdict || '. ';
    end if;
  end if;

  /* PHASE A — fire the next probe (answered on the next run). */
  select net.http_get(url => v_site || '/?deploycheck=' || extract(epoch from now())::bigint,
                      timeout_milliseconds => 8000)
    into v_req;
  insert into site_deploy_probe (req_id) values (v_req);

  delete from site_deploy_probe where fired_at < now() - interval '30 days';

  return coalesce(nullif(v_out,''), 'probe fired');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_check_tile_drill()
 RETURNS TABLE(contract_key text, page text, tile_label text, tile_value numeric, drill_value numeric, gap numeric, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; tv numeric; dv numeric; err text;
begin
  for c in select * from tile_drill_contract order by page, tile_label loop
    tv := null; dv := null; err := null;
    begin execute c.tile_sql  into tv; exception when others then err := 'tile SQL failed: '||sqlerrm; end;
    begin execute c.drill_sql into dv; exception when others then
      err := coalesce(err||' / ','')||'drill SQL failed: '||sqlerrm; end;

    contract_key := c.contract_key; page := c.page; tile_label := c.tile_label;
    tile_value := tv; drill_value := dv; gap := coalesce(tv,0) - coalesce(dv,0);

    verdict := case
      when err is not null                       then 'BROKEN — '||err
      when tv is null and dv is null             then 'BOTH EMPTY — the tile and its drill both return nothing'
      when tv is null or dv is null              then 'ONE SIDE EMPTY — a tile showing a figure whose drill returns nothing, or the reverse'
      when abs(tv - dv) <= c.tolerance           then 'AGREE'
      else 'DISAGREE — tile '||tv||' vs drill '||dv||', gap '||(tv-dv)
    end;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_close_stuck_sync_runs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_mins numeric; v_closed int;
begin
  v_mins := coalesce(f_rule('sync_run_stuck_after_mins'), 30);

  -- A run that starts and never finishes is invisible to every "did it fail?"
  -- check: it is not an error, so nothing counts it, and it is not ok, so nothing
  -- trusts it. It just sits open forever looking like work in progress. Ten plant
  -- syncs sat like that for two days. Same family as a status that only goes red
  -- on total failure - silence read as health.
  with hung as (
    update metrc_sync_runs
       set status = 'error',
           finished_at = now(),
           error = coalesce(error || ' · ', '')
                   || 'Never finished. Marked failed after ' || v_mins
                   || ' minutes still open, by tg_close_stuck_sync_runs.',
           note = coalesce(note || ' · ', '')
                  || 'Closed by the stuck-run sweep; the run itself never reported back.'
     where status = 'running' and finished_at is null
       and started_at < now() - make_interval(mins => v_mins::int)
     returning 1)
  select count(*) into v_closed from hung;

  return jsonb_build_object('ok', true, 'closed_as_failed', v_closed,
    'threshold_mins', v_mins,
    'note', case when v_closed = 0 then 'Nothing hung.'
                 else v_closed || ' run(s) had started and never reported back. They now read as failed rather than as still running.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_command_range(p_from date, p_to date)
 RETURNS TABLE(metric text, value numeric, unit text, basis text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select 'Harvests started', count(*)::numeric, 'harvests',
         'metrc_harvests.harvest_start within the window'
    from metrc_harvests where harvest_start between p_from and p_to
  union all
  select 'Wet weight harvested', round((sum(wet_weight)/453.59237)::numeric,1), 'lb',
         'metrc_harvests.wet_weight, grams converted, harvest_start within the window'
    from metrc_harvests where harvest_start between p_from and p_to
  union all
  select 'Packages created', count(*)::numeric, 'packages',
         'metrc_packages.packaged_on within the window, one row per tag'
    from (select distinct on (tag) tag, packaged_on from metrc_packages
           where tag is not null order by tag, synced_at desc) p
   where p.packaged_on between p_from and p_to
  union all
  select 'Sold to customers', round(coalesce(sum(pounds),0)::numeric,1), 'lb',
         'v_forensic_sold_by_tag, counts_as_sale only — internal moves, labs and transport legs excluded'
    from v_forensic_sold_by_tag
   where counts_as_sale and shipped_on between p_from and p_to
  union all
  select 'Invoiced', round(coalesce(sum(distinct_usd),0)::numeric,0), 'USD',
         'Apex invoice totals on manifests shipped in the window, counted once per invoice'
    from (select distinct invoice_number, max(total_usd) as distinct_usd
            from v_forensic_sold_by_tag
           where counts_as_sale and invoice_number is not null
             and shipped_on between p_from and p_to
           group by invoice_number) x
  union all
  select 'Lab samples sent', count(*)::numeric, 'samples',
         'v_lab_samples_out.sent_on within the window'
    from v_lab_samples_out where sent_on between p_from and p_to
  union all
  select 'Findings raised', count(*)::numeric, 'findings',
         'watchdog_findings.observed_at within the window'
    from watchdog_findings where observed_at::date between p_from and p_to
$function$
;
CREATE OR REPLACE FUNCTION public.tg_confirm_alert_emails()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ok int; v_failed int;
begin
  with answered as (
    update alert_outbox o
       set sent_at = case when r.status_code between 200 and 299 then coalesce(r.created, now()) end,
           send_error = case when r.status_code between 200 and 299 then null
                             else 'HTTP ' || r.status_code || ' ' ||
                                  left(coalesce(r.content, r.error_msg, 'no body'), 300) end
      from net._http_response r
     where r.id = o.send_request_id
       and o.dispatched_at is not null and o.sent_at is null
     returning (r.status_code between 200 and 299) as delivered)
  select count(*) filter (where delivered), count(*) filter (where not delivered)
    into v_ok, v_failed from answered;

  return jsonb_build_object('ok', true, 'confirmed_delivered', coalesce(v_ok,0),
    'failed', coalesce(v_failed,0),
    'note', 'A failed row keeps sent_at null and carries the provider''s reason in send_error, so it is visibly undelivered rather than quietly gone.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_coverage_check()
 RETURNS TABLE(week text, verdict text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_column
declare v_run uuid := gen_random_uuid(); v_reqs int;
begin
  select count(*) into v_reqs from zone_staffing_requirements
   where effective_to is null or effective_to >= current_date - 7;

  -- LAW 3. No requirement means unmeasurable, not satisfied.
  if v_reqs = 0 then
    insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
           verdict, numerator, denominator, the_arithmetic, drill, data_as_of)
    values (v_run, 'detect.coverage', 'A5', 'metric', 'departments_with_a_coverage_requirement',
            'UNCHECKED', 0, null,
            'No coverage requirement is set for any department, so short-staffing CANNOT be '
            || 'detected. ' || (select count(*) from departments) || ' departments exist. This is '
            || 'NOT the same as being fully staffed, and must never be presented as such.',
            'zone_staffing_requirements', now());
    return query
      select null::text, 'UNCHECKED'::text,
             'No coverage requirement set. ' || (select count(*)::text from departments)
             || ' departments exist and none can be judged.';
    return;
  end if;

  -- One row per week, so a bad week is not averaged away by a good one.
  insert into conformance_ledger (run_id, checker_key, policy_key, subject_kind, subject_ref,
         verdict, numerator, denominator, the_arithmetic, drill, data_as_of)
  select v_run, 'detect.coverage', 'A5', 'metric',
         'department_coverage_week_' || to_char(w.week_start, 'IYYY_IW'),
         case when w.short = 0 then 'PASS' else 'FAIL' end,
         w.total - w.short, w.total,
         (w.total - w.short) || ' of ' || w.total || ' departments covered in the week of '
         || w.week_start || '. ' ||
         case when w.short = 0 then 'None short.'
              else w.short || ' short: ' || w.who || '. Rota gap ' || w.head_days
                   || ' head-days.' end,
         'v_department_coverage_week', w.week_start::timestamptz
  from (
    select week_start,
           count(*)                                                   as total,
           count(*) filter (where verdict <> 'COVERED'
                              and verdict <> 'NO REQUIREMENT SET')     as short,
           coalesce(string_agg(department, ', ')
             filter (where verdict <> 'COVERED'
                       and verdict <> 'NO REQUIREMENT SET'), '')       as who,
           coalesce(sum(head_days_short_on_the_rota)
             filter (where head_days_short_on_the_rota > 0), 0)        as head_days
    from v_department_coverage_week
    group by week_start
  ) w;

  return query
    select cl.subject_ref, cl.verdict, cl.the_arithmetic
      from conformance_ledger cl
     where cl.run_id = v_run
     order by cl.subject_ref desc;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_create_dashboard(p_name text, p_template text DEFAULT NULL::text, p_key text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_key text; v_cats text[]; n int := 0; w record; v_first boolean;
begin
  if p_name is null or btrim(p_name) = '' then
    raise exception 'A dashboard needs a name — one you can find again in a list of six.';
  end if;

  v_key := coalesce(nullif(btrim(p_key),''),
                    left(regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '_', 'g'), 40));
  v_key := btrim(v_key, '_-');
  if v_key !~ '^[a-z0-9_-]{2,40}$' then
    raise exception 'Could not make a usable key from "%". Try a name with some letters in it.', p_name;
  end if;
  if exists (select 1 from user_dashboard where user_id = auth.uid() and dashboard_key = v_key) then
    raise exception 'You already have a dashboard called "%". Rename that one or pick another name.', p_name;
  end if;

  if p_template is not null then
    select categories into v_cats from dashboard_template
     where template_key = p_template and active;
    if v_cats is null then
      raise exception 'No template "%". Choose one from dashboard_template, or omit it for an empty grid.', p_template;
    end if;
  end if;

  select not exists (select 1 from user_dashboard where user_id = auth.uid()) into v_first;

  insert into user_dashboard (dashboard_key, name, purpose, from_template, is_default)
  values (v_key, btrim(p_name),
          (select purpose from dashboard_template where template_key = p_template),
          p_template, v_first);

  -- Seed the grid: 4 across, each 3 wide by 2 tall. Hot widgets first so the loudest thing is
  -- top-left, where the eye lands.
  if v_cats is not null then
    for w in
      select key, widget_kind from widget_catalog
       where enabled and category = any(v_cats)
       order by hot desc nulls last, category, label
    loop
      insert into dashboard_layout (page, widget_key, instance_id, x, y, w, h)
      values (v_key, w.key, 1, (n % 4) * 3, (n / 4) * 2, 3, 2);
      n := n + 1;
    end loop;
  end if;

  return v_key;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_custody_monitor()
 RETURNS TABLE(new_flags integer, resolved integer, open_total integer)
 LANGUAGE plpgsql
AS $function$
declare n int := 0; r int := 0; t int := 0;
begin
  insert into custody_alert_log (flag, severity, license, identifier, item, location, quantity, uom, detail, reference_date)
  select a.flag, a.severity, a.license, a.identifier, a.item, a.location, a.quantity, a.uom, a.detail, a.reference_date
  from v_custody_alerts a
  where not exists (
    select 1 from custody_alert_log l
    where l.flag = a.flag and l.identifier = a.identifier and l.resolved_at is null
  );
  get diagnostics n = row_count;
  update custody_alert_log l set resolved_at = now(), resolved_by = 'monitor',
    resolution_note = 'Condition no longer present in Metrc'
  where l.resolved_at is null
    and not exists (select 1 from v_custody_alerts a where a.flag = l.flag and a.identifier = l.identifier);
  get diagnostics r = row_count;
  select count(*) into t from custody_alert_log where resolved_at is null;
  new_flags := n; resolved := r; open_total := t; return next;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_dc_retire_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.body is distinct from old.body
     or new.author is distinct from old.author
     or new.author_role is distinct from old.author_role
     or new.page is distinct from old.page
     or new.section_key is distinct from old.section_key
     or new.written_at is distinct from old.written_at then
    raise exception
      'A published note is never edited - body, author and placement are immutable. Retire it '
      '(set retired_at and retired_by) and publish a new note. A signed opinion stays exactly '
      'as it was signed.';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_ddl_guard()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; problem text; unprotected text;
begin
  for r in select * from pg_event_trigger_ddl_commands() loop
    problem := null;

    if r.command_tag = 'CREATE TABLE' and r.object_type = 'table' then
      /* Warning only, deliberately: RLS cannot be enabled in the same statement as
         CREATE TABLE, so "fixing" it here would make correct work impossible. */
      if not exists (select 1 from pg_class c where c.oid = r.objid and c.relrowsecurity) then
        problem := 'Table created WITHOUT row-level security. Run: alter table '||r.object_identity
                || ' enable row level security; then add policies mirroring a sibling table.';
      end if;

    elsif r.command_tag = 'CREATE FUNCTION' and r.object_type = 'function' then
      if exists (select 1 from pg_proc p where p.oid = r.objid
                 and has_function_privilege('anon', p.oid, 'EXECUTE')) then
        execute format('revoke all on function %s from public, anon', r.objid::regprocedure);
        execute format('grant execute on function %s to authenticated', r.objid::regprocedure);
        problem := 'AUTO-FIXED: EXECUTE was granted to PUBLIC (the Postgres default), so anon '
                || 'could call it. Revoked from public and anon; granted to authenticated.';
      end if;
      if exists (select 1 from pg_proc p where p.oid=r.objid and p.prosecdef and p.proconfig is null) then
        execute format('alter function %s set search_path = public, pg_temp', r.objid::regprocedure);
        problem := coalesce(problem||' ALSO ','')
                || 'AUTO-FIXED: SECURITY DEFINER with no search_path — the privilege-escalation '
                || 'shape. Pinned to public, pg_temp.';
      end if;

    /* ── NEW 9 Aug 2026 · views ─────────────────────────────────────────────── */
    elsif r.command_tag = 'CREATE VIEW' and r.object_type = 'view' then
      if coalesce((select option_value from pg_class c,
                          pg_options_to_table(c.reloptions)
                   where c.oid = r.objid and option_name = 'security_invoker'), 'false')
         not in ('true','on') then

        /* Which base tables does it read, and does each carry a policy? A view over a
           table with no policy would go EMPTY the moment RLS applies. */
        select string_agg(distinct b.relname, ', ') into unprotected
        from pg_rewrite rw
        join pg_depend d on d.objid = rw.oid and d.classid = 'pg_rewrite'::regclass
        join pg_class b on b.oid = d.refobjid and b.relkind = 'r' and b.oid <> r.objid
        where rw.ev_class = r.objid
          and not exists (select 1 from pg_policy p where p.polrelid = b.oid);

        if unprotected is null then
          execute format('alter view %s set (security_invoker = true)', r.object_identity);
          problem := 'AUTO-FIXED: the view ran as its OWNER, so row-level security on its base '
                  || 'tables did NOT apply — every policy was bypassable by querying the view '
                  || 'instead of the table. Set security_invoker = true. Every base table already '
                  || 'has a policy, so this cannot have emptied anything.';
        else
          problem := 'NOT auto-fixed, and this is DEBT: the view bypasses row-level security, but '
                  || 'these base tables have NO policy at all — ' || unprotected || ' — so '
                  || 'enforcing RLS would return ZERO ROWS and look like a broken page. Add a '
                  || 'policy to those tables, then: alter view ' || r.object_identity
                  || ' set (security_invoker = true);';
        end if;
      end if;
    end if;

    if problem is not null then
      insert into ddl_guard_log (object_type, object_identity, command_tag, problem, actor)
      values (r.object_type, r.object_identity, r.command_tag, problem,
              coalesce(current_setting('request.jwt.claim.email', true), session_user));
      raise warning E'\n>>> TG DDL GUARD: %\n>>> %\n', r.object_identity, problem;
    end if;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_decide_issue(p_source text, p_item_id bigint, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not f_caller_is_admin() then
    raise exception 'Only the owner decides. An agent recording its own approval is not an approval.';
  end if;
  if p_decision not in ('approved','rejected','deferred') then
    raise exception 'Decision must be approved, rejected or deferred - got %.', p_decision;
  end if;
  if p_decision in ('rejected','deferred') and coalesce(btrim(p_note),'') = '' then
    raise exception 'A rejection or deferral needs a reason, or the same item returns next week.';
  end if;

  if p_source = 'correction' then
    if p_decision = 'deferred' then
      raise exception 'A correction proposal is approved or rejected, never deferred - a data defect left in limbo gets applied by accident later.';
    end if;
    update correction_proposal
       set status = p_decision, owner_note = p_note, decided_at = now()
     where id = p_item_id and status = 'proposed';
  elsif p_source = 'enhancement' then
    update page_enhancement
       set status = p_decision, owner_note = p_note, decided_at = now()
     where id = p_item_id and status = 'proposed';
  else
    raise exception 'Defects are not decided - they clear when the condition that raised them ends. Fix the cause, or challenge the finding.';
  end if;

  if not found then
    return 'Nothing to decide - item ' || p_item_id || ' was already decided or does not exist.';
  end if;
  return p_decision || ' — recorded ' || to_char(now(),'DD Mon YYYY HH24:MI');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_decide_item_flag(p_entity_type text, p_entity_key text, p_source text, p_source_ref text, p_decision text, p_reason text, p_decided_by text, p_note text DEFAULT NULL::text, p_review_on date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_review date := p_review_on; v_id bigint; v_found boolean;
begin
  if coalesce(btrim(p_decided_by),'') = '' then
    raise exception 'Who is deciding? A decision with no name attached is not a decision.';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 15 then
    raise exception 'A reason of at least 15 characters is required. "%" does not say why, and in six months nobody will remember.', coalesce(p_reason,'');
  end if;
  if p_decision not in ('fixed','ignored','not_an_issue','accepted_risk') then
    raise exception 'Unknown decision "%". Use fixed, ignored, not_an_issue or accepted_risk.', p_decision;
  end if;

  -- Checked against ALL flags, not just open ones, so a decision can be revised.
  select true into v_found from v_item_flags_all
   where entity_type = p_entity_type and entity_key = p_entity_key
     and source = p_source and source_ref = p_source_ref limit 1;
  if not found then
    raise exception 'No flag matches % / % / % / %. Nothing to decide.',
      p_entity_type, p_entity_key, p_source, p_source_ref;
  end if;

  if p_decision = 'ignored' and v_review is null then
    v_review := current_date + 30;
  end if;

  update item_flag_decision set superseded_at = now()
   where entity_type = p_entity_type and entity_key = p_entity_key
     and source = p_source and source_ref = p_source_ref and superseded_at is null;

  insert into item_flag_decision
    (entity_type, entity_key, source, source_ref, decision, reason, note, decided_by, review_on)
  values (p_entity_type, p_entity_key, p_source, p_source_ref, p_decision,
          btrim(p_reason), nullif(btrim(coalesce(p_note,'')),''), btrim(p_decided_by), v_review)
  returning id into v_id;

  return jsonb_build_object(
    'ok', true, 'decision_id', v_id, 'decision', p_decision, 'review_on', v_review,
    'note', case p_decision
      when 'fixed' then 'Recorded. The flag stays visible until the underlying data actually changes - if it is still here tomorrow, the fix did not work.'
      when 'ignored' then 'Hidden until ' || v_review || ', then it comes back. Ignoring is postponing, not closing.'
      else 'Recorded with your reason attached.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_deferral_needs_todays_reason()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare p record;
begin
  select * into p from reason_policy where action_key = 'flag_defer';

  if new.deferred_on > current_date then
    raise exception
      'Cannot defer % to a future date. A deferral covers ONE day and must be written on that '
      'day. Pre-silencing a flag for a week is the behaviour this control exists to stop.',
      new.alert_key;
  end if;

  if p.enforced then
    if p.require_code and coalesce(btrim(new.reason_code), '') = '' then
      raise exception 'Cannot defer %: a reason code is required.', new.alert_key;
    end if;
    if p.require_code and not exists (
         select 1 from reason_code_catalog c where c.code = new.reason_code) then
      raise exception
        'Cannot defer %: reason code "%" is not in reason_code_catalog. Free text cannot be '
        'counted or trended, which is why the vocabulary is controlled.', new.alert_key, new.reason_code;
    end if;
    if p.require_note and length(btrim(coalesce(new.reason_note, ''))) < coalesce(p.min_note_chars, 25) then
      raise exception
        'Cannot defer %: the reason must be at least % characters in your own words. You wrote %. '
        'Say what is actually blocking the correction.',
        new.alert_key, coalesce(p.min_note_chars, 25), length(btrim(coalesce(new.reason_note, '')));
    end if;
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_delete_dashboard(p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare was_default boolean;
begin
  select is_default into was_default from user_dashboard
   where user_id = auth.uid() and dashboard_key = p_key;
  if was_default is null then raise exception 'You have no dashboard "%".', p_key; end if;

  delete from dashboard_layout where user_id = auth.uid() and page = p_key;
  delete from user_dashboard  where user_id = auth.uid() and dashboard_key = p_key;

  -- Never leave the user with dashboards but no default — the platform would open to nothing.
  if was_default then
    update user_dashboard set is_default = true
     where user_id = auth.uid()
       and dashboard_key = (select dashboard_key from user_dashboard
                             where user_id = auth.uid() order by sort, name limit 1);
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_delivery_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare lanes int; agreed int; dissent text; guard_also_verified boolean;
begin
  if new.status <> 'approved' or old.status = 'approved' then return new; end if;

  select count(distinct lane), count(*) filter (where verdict = 'agree')
    into lanes, agreed
    from delivery_verification where delivery_id = new.id;

  if lanes < 3 then
    raise exception
      'Cannot approve "%": % of 3 lanes verified. All three of data, design and usability must '
      'report before the guard sees it.', new.page, lanes;
  end if;

  if agreed < 3 then
    select string_agg(lane||' ('||verifier||'): '||verdict||' — '||what_i_found, E'\n')
      into dissent from delivery_verification
     where delivery_id = new.id and verdict <> 'agree';
    raise exception
      'Cannot approve "%": the three verifiers are NOT unanimous. Unresolved:%s%s',
      new.page, E'\n', dissent;
  end if;

  if new.guard is null or length(btrim(coalesce(new.guard_note,''))) < 40 then
    raise exception
      'Cannot approve "%": a named guard must review all three lanes and record what they '
      'checked. An empty note is not a review.', new.page;
  end if;

  select exists(select 1 from delivery_verification
                 where delivery_id = new.id and verifier = new.guard)
    into guard_also_verified;
  if guard_also_verified then
    raise exception
      'Cannot approve "%": % verified one of the lanes and cannot also be the guard. The guard '
      'is the independent fourth pair of eyes, not a verifier signing their own work.',
      new.page, new.guard;
  end if;

  new.guard_at := now();
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_detect_report(p_columns text[])
 RETURNS TABLE(report_key text, title text, target_table text, matched integer, what_it_adds text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select t.report_key, t.title, t.target_table,
         (select count(*) from unnest(t.signature_cols) s
           where exists (select 1 from unnest(p_columns) c
                          where lower(btrim(replace(c, chr(10), ' '))) = lower(btrim(s))))::int as matched,
         t.what_it_adds
  from metrc_report_types t
  -- every signature column must be present, or it is not that report
  where (select count(*) from unnest(t.signature_cols) s
          where exists (select 1 from unnest(p_columns) c
                         where lower(btrim(replace(c, chr(10), ' '))) = lower(btrim(s))))
        = array_length(t.signature_cols, 1)
  order by array_length(t.signature_cols,1) desc
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_escalate_discrepancy(p_subject text, p_headline text, p_why_it_matters text, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare missing text; settled boolean; n_checked int;
begin
  if coalesce(btrim(p_by),'') = '' then
    raise exception 'Who is escalating? An unsigned escalation is not a finding.';
  end if;

  -- Has any source already answered it? Then it is not a discrepancy.
  select bool_or(settled_it), count(distinct source_key)
    into settled, n_checked
  from discrepancy_investigation where subject = p_subject;

  if n_checked is null or n_checked = 0 then
    raise exception 'Nothing has been investigated for "%". Record what each source '
      'showed in discrepancy_investigation first. The sources are listed in '
      'discrepancy_source, in the order to try them.', p_subject;
  end if;

  if settled then
    raise exception 'One of the sources already SETTLED "%". It is answered, not '
      'disputed - record the answer rather than escalating it.', p_subject;
  end if;

  -- Every mandatory rung must have been tried.
  select string_agg(d.source_name, ', ' order by d.rung) into missing
  from discrepancy_source d
  where d.mandatory
    and d.source_key not in (select i.source_key from discrepancy_investigation i
                             where i.subject = p_subject);

  if missing is not null then
    raise exception E'NOT EXHAUSTED. These sources have not been tried for "%":\n  %\n'
      'The owner sees a discrepancy only when every one of them has been asked and '
      'none could answer. A manifest sitting unread in storage settled a $6,772 '
      'question in two minutes after it had already been put on his list.',
      p_subject, missing;
  end if;

  insert into watchdog_findings
    (fingerprint, severity, what, where_it_is, who_is_accountable, why_it_matters,
     how_it_was_detected, what_to_do, the_arithmetic, search_text)
  values ('discrepancy_' || left(md5(p_subject), 16), 'elevated', p_headline,
          p_subject, p_by, p_why_it_matters,
          'Escalated through tg_escalate_discrepancy after every source in '
            || 'discrepancy_source was tried and none could settle it.',
          'A person must decide. Every automated source has been exhausted.',
          (select string_agg(d.source_name || ': ' || i.what_it_showed, E'\n' order by d.rung)
             from discrepancy_investigation i
             join discrepancy_source d on d.source_key = i.source_key
            where i.subject = p_subject),
          p_subject || ' ' || p_headline);

  return jsonb_build_object('ok', true, 'escalated', p_subject,
    'sources_exhausted', n_checked,
    'note', 'Raised with the full investigation trail attached, so the reader can see '
            'what was already ruled out rather than repeating it.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_escalate_unchallenged()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_overdue int; v_crit int; v_worst int; v_noarith int; v_run bigint; v_list text;
begin
  select count(*) filter (where standing <> 'within the window'),
         count(*) filter (where standing <> 'within the window' and severity = 'critical'),
         coalesce(max(hours_overdue) filter (where standing <> 'within the window'), 0),
         count(*) filter (where has_no_arithmetic)
    into v_overdue, v_crit, v_worst, v_noarith
  from v_challenge_overdue;

  select string_agg(what, '; ' order by hours_overdue desc)
    into v_list
  from (select what, hours_overdue from v_challenge_overdue
        where standing <> 'within the window' and severity = 'critical'
        order by hours_overdue desc limit 5) top5;

  if v_overdue = 0 then
    /* Resolve rather than leave a stale finding standing. */
    update watchdog_findings set severity = 'watch',
      what = 'Every finding has been challenged inside its window'
    where fingerprint = 'findings_unchallenged';
    return 'no findings overdue for challenge';
  end if;

  insert into watchdog_runs default values returning id into v_run;
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
    who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
    the_arithmetic, record_count, drill, search_text)
  values (v_run, 'findings_unchallenged',
    case when v_crit > 0 then 'critical' else 'elevated' end,
    v_overdue || ' finding(s) past their challenge window, ' || v_crit || ' of them critical'
      || case when v_list is not null then ' — worst: ' || left(v_list, 260) else '' end,
    'v_challenge_overdue',
    'The agent that raised the finding, and whoever owns the lane it touches',
    'The moment each finding was raised',
    'An unchallenged finding is a claim, not a fact. On 7 Aug 2026 FIVE separate conclusions '
    'were overturned within hours - "$399,000 of missing production" (the pulls ran late), '
    '"rooms are underfilled" (they were full; the count excluded fresh frozen), "2026 is behind '
    '2025" (an artifact of unfinished packaging - it is ~40% ahead), "yield rose 31%" (a '
    'packaging-ratio change), and strain price rankings (customer and timing explain 93%). '
    'EVERY CATCH WAS ACCIDENTAL. The Challenger exists to make it deliberate, and had never '
    'been run on a single finding.',
    'v_challenge_overdue applies an SLA per severity - critical 24h, elevated 72h, otherwise '
    '168h - and counts findings past it. The view has been correct and unread since it was built.',
    'Run the challenger agent over the criticals first. Record the verdict in metric_challenges: '
    'REFUTED with the alternative explanation, SURVIVES WITH LIMITS naming the scope and sample, '
    'or CANNOT BREAK IT listing which attacks were run. Never soften a REFUTED to be agreeable.',
    v_overdue || ' overdue, ' || v_crit || ' critical, worst ' || v_worst || ' hours past its window; '
      || v_noarith || ' finding(s) carry no arithmetic at all',
    v_overdue, 'settings', 'challenger unchallenged findings overdue')
  on conflict (fingerprint) where (fingerprint is not null) do update set
    severity = excluded.severity, what = excluded.what,
    the_arithmetic = excluded.the_arithmetic, record_count = excluded.record_count,
    run_id = excluded.run_id;

  return v_overdue || ' overdue (' || v_crit || ' critical), finding raised';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_finding_plan_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.disposition = 'ignored' and coalesce(length(trim(new.disposition_reason)),0) < 15 then
    raise exception 'Ignoring a finding needs a written reason of at least fifteen characters, so the decision is defensible later.';
  end if;
  if new.disposition <> coalesce(old.disposition, 'open') then
    new.decided_at := now();
    new.decided_by := coalesce(new.decided_by, auth.uid()::text);
  end if;
  new.updated_at := now();
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_forensic_audit(p_type text DEFAULT 'scheduled'::text)
 RETURNS TABLE(sections integer, metrics integer)
 LANGUAGE plpgsql
AS $function$
declare rid timestamptz := now(); m int := 0;
begin
  -- 1. SCHEDULE DISCIPLINE
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Schedule discipline', 'Pull and dry violations',
    count(*) filter (where rule_verdict like 'VIOLATION%'), 'events', 'Cultivation lead',
    case when count(*) filter (where rule_verdict like 'VIOLATION%') = 0 then 'CLEAN'
         else 'FAIL - late is never acceptable under the standing rule' end,
    coalesce(string_agg(distinct room || ' ' || coalesce(scheduled_date::text,''), '; ')
      filter (where rule_verdict like 'VIOLATION%'), 'none')
  from v_late_violations;
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Schedule discipline', 'Average days late',
    round(avg(days_off_schedule) filter (where rule_verdict like 'VIOLATION%')::numeric,1), 'days',
    'Cultivation lead',
    case when coalesce(avg(days_off_schedule) filter (where rule_verdict like 'VIOLATION%'),0) = 0 then 'CLEAN' else 'FAIL' end,
    'Zero is the only acceptable figure'
  from v_late_violations;

  -- 2. WEIGHT REPORTING (the honesty test)
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Weight reporting', 'Harvests with no weights recorded',
    count(*), 'harvests', 'Cultivation lead',
    case when count(*) = 0 then 'CLEAN' else 'FAIL - weights not reported' end,
    coalesce(string_agg(harvest, '; '), 'none')
  from v_harvest_lifecycle where verdict = 'MISSING WEIGHTS';

  -- 3. YIELD AND CONVERSION (the number they cannot argue with)
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Yield', 'Wet to saleable conversion, latest month',
    wet_to_saleable_pct, 'percent', 'Cultivation and post-harvest',
    case when wet_to_saleable_pct >= 28 then 'ACCEPTABLE'
         when wet_to_saleable_pct >= 22 then 'BELOW PAR' else 'FAIL' end,
    month || ': ' || saleable_lbs || ' saleable lb from ' || plants_harvested || ' plants, ' || grams_per_plant || ' g per plant'
  from v_true_cost_per_pound order by month_date desc limit 1;
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Yield', 'Best conversion on record',
    max(wet_to_saleable_pct), 'percent', 'Cultivation and post-harvest', 'BENCHMARK',
    'The gap between this and the latest month is the recoverable loss'
  from v_true_cost_per_pound;

  -- 4. GENUINE LOSS
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Loss', loss_type, dollars_at_target_cost, 'dollars', 'Cultivation and Quality',
    case when coalesce(dollars_at_target_cost,0) = 0 then 'CLEAN' else 'LOSS RECORDED' end,
    occurrences || ' occurrences, ' || pounds_affected || ' pounds'
  from v_real_loss_summary;

  -- 5. COMPLIANCE
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Compliance', flag, count(*), 'items', 'Quality and Compliance',
    case when count(*) = 0 then 'CLEAN' else 'EXPOSURE' end,
    coalesce(string_agg(distinct item, '; '), '')
  from v_custody_alerts group by flag;
  insert into forensic_audits (run_at, run_type, section, metric, value, value_text, unit, responsible, verdict, evidence)
  select rid, p_type, 'Compliance', 'Custody proof', location_known_pct, compliance_status, 'percent',
    'Whole operation', case when location_known_pct = 100 then 'CLEAN' else 'FAIL' end,
    items || ' tracked items, ' || items_without_location || ' unlocated'
  from v_custody_compliance where category = 'ALL TRACKED INVENTORY';

  -- 6. CAPITAL
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Capital', 'Items aging beyond policy', count(*), 'items', 'Inventory and Fulfilment',
    case when count(*) = 0 then 'CLEAN' else 'CASH TIED UP' end,
    'Oldest ' || coalesce(max(days_here)::text,'0') || ' days'
  from v_inventory_aging where severity in ('critical','elevated');
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Capital', 'Material without approved allocation', count(*), 'items',
    'Approver and department leads',
    case when count(*) = 0 then 'CLEAN' else 'NO AUTHORITY RECORDED' end,
    'Every material must carry an approved allocation before it moves'
  from v_awaiting_allocation;

  -- 7. PAYROLL AGAINST OUTPUT
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Payroll versus output', department || ' labour cost per saleable pound',
    labour_cost_per_saleable_pound_90d, 'dollars per pound', highest_paid_people,
    case when labour_cost_per_saleable_pound_90d is null then 'NOT MEASURABLE - load real pay rates'
         else 'MEASURED' end,
    headcount || ' people, ' || annual_loaded_cost || ' dollars annual loaded cost'
  from v_leadership_cost_vs_output where department ilike '%cultivation%';

  -- 8. DATA INTEGRITY - is the record itself trustworthy
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Data integrity', 'Hours since last Metrc sync',
    round(extract(epoch from (now() - max(started_at)))/3600, 1), 'hours', 'Platform',
    case when max(started_at) > now() - interval '2 hours' then 'CLEAN' else 'STALE' end,
    'Automatic sync runs every fifteen minutes'
  from metrc_sync_runs;
  insert into forensic_audits (run_at, run_type, section, metric, value, unit, responsible, verdict, evidence)
  select rid, p_type, 'Data integrity', 'Employees without a real pay rate loaded',
    count(*), 'people', 'Human Resources',
    case when count(*) = 0 then 'CLEAN' else 'BLOCKS COST ANALYSIS' end,
    'Cost per pound cannot be attributed without real rates'
  from employees e where e.terminated_on is null
    and not exists (select 1 from employee_rates r where r.employee_id = e.id);

  get diagnostics m = row_count;
  select count(*) into m from forensic_audits where run_at = rid;
  sections := (select count(distinct section) from forensic_audits where run_at = rid);
  metrics := m;
  return next;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_guard_findings_name_a_guard()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now int; v_base int; v_run bigint; v_worst text;
begin
  select count(*) into v_now
  from watchdog_findings
  where guard_recommendation is null and severity in ('critical','elevated');

  v_base := coalesce(f_rule('findings_without_guard_baseline'), 80)::int;

  /* The number improved. Lower the baseline so the gain is locked in and cannot be given
     back quietly - the same ratchet discipline the repository gates use. */
  if v_now < v_base then
    update conversion_factors
      set value = v_now, updated_at = now(),
          evidence_note = 'Ratcheted down automatically on ' || current_date
            || ' from ' || v_base || ' to ' || v_now || '. May fall, may never rise.'
    where key = 'findings_without_guard_baseline';
    v_base := v_now;
  end if;

  select string_agg(left(what, 70), '; ')
    into v_worst
  from (select what from watchdog_findings
        where guard_recommendation is null and severity = 'critical'
        order by observed_at limit 3) oldest;

  if v_now > v_base then
    insert into watchdog_runs default values returning id into v_run;
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text, guard_recommendation)
    values (v_run, 'findings_without_a_guard', 'elevated',
      v_now || ' serious findings name no guard, above the baseline of ' || v_base,
      'watchdog_findings.guard_recommendation',
      'The agent that raised each finding',
      'Since each finding was raised',
      'DATA_TRAPS_REGISTER section E calls this the worst trap in the register: a decision '
      'recorded is not a decision implemented. A finding with no guard is a problem that will '
      'happen again - proven three times already, when sales endpoints "permanently disabled" '
      'on 6 Aug were still firing 401s on 7 Aug.',
      'Counted findings at critical or elevated severity where guard_recommendation is null, '
      'against an owner-editable baseline that may fall and may never rise.',
      'On each finding, name what would stop it recurring - a check, a constraint, a hook, a '
      'config row - or write plainly that it is unguarded and why. Both are acceptable; silence '
      'is not.',
      v_now || ' unguarded of ' || (select count(*) from watchdog_findings
        where severity in ('critical','elevated')) || ' serious; baseline ' || v_base
        || case when v_worst is not null then '. Oldest criticals: ' || v_worst else '' end,
      v_now, 'settings', 'finding without guard recurrence meta trap',
      'This finding guards itself: tg_guard_findings_name_a_guard(), cron job '
      'guard-findings-named, ratcheting against findings_without_guard_baseline.')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity = excluded.severity, what = excluded.what,
      the_arithmetic = excluded.the_arithmetic, record_count = excluded.record_count,
      run_id = excluded.run_id;
    return v_now || ' unguarded, ABOVE baseline ' || v_base || ' - finding raised';
  end if;

  return v_now || ' serious findings unguarded (baseline ' || v_base || ', not worse)';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_guard_naming(p_by text DEFAULT 'cron:guard-naming'::text)
 RETURNS TABLE(guard text, hits integer, note text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer; s text;
begin
  select count(*) into n
  from discrepancy_register d
  cross join lateral f_strain_by_tag(
      substring(d.subject from '1A[0-9A-Z]{22}'), d.source_b_says) r
  where d.resolved_at is null and d.class = 'strain'
    and (r.verdict like 'BLEND%'
         or lower(coalesce(r.strain,'')) = lower(btrim(d.source_b_says)));
  guard := 'G-A/G-B false strain discrepancies'; hits := n;
  note := 'blends and product names wrongly raised'; return next;

  select count(*), string_agg(x.nm, ' | ')
    into n, s
  from (select distinct source_harvest as nm
        from metrc_rpt_package_transfers
        where coalesce(source_harvest,'') <> '' and source_harvest not like '%,%'
          and source_harvest like 'TG %') x
  where x.nm !~ ' - \d{8}'
     or btrim(substring(x.nm from '^(.*?)\s+-\s')) is null;
  if n > 0 then
    insert into agent_findings
      (agent, severity, headline, detail, metric, units, scope, action, drill_to, fingerprint)
    values ('Metrc & Compliance','elevated',
      n||' harvest names cannot be parsed for a strain or a date',
      'WHAT: '||left(coalesce(s,''),300)||'. The harvest name is rung 1 of the naming ladder; '
      ||'if the strain or date cannot be read, every package from it falls to a later rung. '
      ||'Room-suffix variants such as "F2 FF", "F4 H" and lower-case "f3" are LEGITIMATE and '
      ||'deliberately not flagged. This is HANDOFF defect D7.',
      n,'harvests','metrc harvests','Correct the harvest name in Metrc (D2)',
      'metrc_corrections','naming_unparseable_harvest')
    on conflict do nothing;
  end if;
  guard := 'G-C harvest name unparseable'; hits := n; note := left(coalesce(s,'none'),160); return next;

  select count(*), string_agg(x.nm, ', ') into n, s
  from (select distinct btrim(substring(source_harvest from '^(.*?)\s+-\s')) as nm
        from metrc_rpt_package_transfers
        where coalesce(source_harvest,'') <> '' and source_harvest not like '%,%'
          and source_harvest like 'TG %') x
  where x.nm is not null
    and not exists (select 1 from metrc_strains s2 where lower(btrim(s2.name)) = lower(x.nm));
  guard := 'G-D harvest names an unregistered strain'; hits := n;
  note := left(coalesce(s,'none'),160); return next;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_handoff_state_md()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s record;
  out text;
  verdict text;
begin
  select * into s from platform_state order by taken_at desc limit 1;
  if s is null then
    return '_No platform_state row exists yet. Run `select * from tg_nightly_platform_check();`_';
  end if;

  verdict := case
    when s.anon_relations > 0 or s.anon_functions > 0 or s.tables_without_rls > 0
      then '**SECURITY: FAILING.** Anonymous access or unprotected tables are present. Stop and fix before anything else.'
    when s.nav_broken > 0 or s.matviews_unpopulated > 0
      then '**DEGRADED.** Pages or materialized views are broken; figures may render empty rather than erroring.'
    else '**Security invariants hold.** Zero anon reach, zero tables without row-level security.'
  end;

  out :=
    '<!-- GENERATED: tg_handoff_state_md(). Do not hand-edit between these markers. -->' || E'\n' ||
    '_Measured ' || to_char(s.taken_at at time zone 'UTC', 'DD Mon YYYY HH24:MI') || ' UTC, direct from the live database._' || E'\n\n' ||
    verdict || E'\n\n' ||
    '| Measure | Value | Should be |' || E'\n' ||
    '|---|---:|---|' || E'\n' ||
    '| Base tables | ' || s.base_tables || ' | — |' || E'\n' ||
    '| Views | ' || s.views || ' | — |' || E'\n' ||
    '| Materialized views | ' || s.matviews || ' | — |' || E'\n' ||
    '| Matviews unpopulated | ' || s.matviews_unpopulated || ' | 0 |' || E'\n' ||
    '| Relations readable by anon | ' || s.anon_relations || ' | 0 |' || E'\n' ||
    '| Functions executable by anon | ' || s.anon_functions || ' | 0 |' || E'\n' ||
    '| Of those, functions that WRITE | ' || s.anon_writing_functions || ' | 0 |' || E'\n' ||
    '| Tables without row-level security | ' || s.tables_without_rls || ' | 0 |' || E'\n' ||
    '| SECURITY DEFINER with mutable search_path | ' || s.secdef_mutable_path || ' | 0 |' || E'\n' ||
    '| Menu entries enabled | ' || s.nav_enabled || ' | — |' || E'\n' ||
    '| Menu entries pointing nowhere | ' || s.nav_broken || ' | 0 |' || E'\n' ||
    '| Scheduled jobs | ' || s.cron_jobs || ' | — |' || E'\n' ||
    '| Jobs failing on their latest run | ' || s.cron_failing || ' | 0 |' || E'\n' ||
    '| Jobs that failed at least once in 24h | ' || coalesce(s.cron_failing_24h::text, 'not yet measured') || ' | 0 |' || E'\n' ||
    '| Tiles with no owner-set target | ' || s.tiles_without_target || ' of ' || s.tiles_total || ' | 0 |' || E'\n' ||
    '| **Questions waiting on the owner** | **' || s.open_questions_unanswered || '** | 0 |' || E'\n' ||
    '| Go-live items open | ' || s.golive_open || ' | 0 |' || E'\n' ||
    '| Staff without an account | ' || greatest(s.active_employees - s.app_users, 0) || ' | 0 |' || E'\n\n' ||
    '_Every figure above is read from `platform_state`, the append-only nightly self-check._' || E'\n' ||
    '_Regenerate with `node tools/gen-handoff.mjs`. Never retype these by hand: the numbers_' || E'\n' ||
    '_move daily, and a hand-written count in this file was once the opposite of the truth._' || E'\n' ||
    '<!-- END GENERATED -->';

  return out;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_harvest_timeline(p_match text)
 RETURNS TABLE(seq integer, occurred_on date, phase text, event text, detail text, quantity numeric, uom text, location text, status text, identifier text)
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return query
  -- 1. The plan
  select 1, p.harvest_date, 'Plan', 'Pull #' || p.pull_no || ' scheduled',
    'Room ' || p.flower_room || ' · ' || coalesce(p.cultivars,'') ||
      ' · planned ' || coalesce(p.original_total_plants,0) || ' plants',
    round(coalesce(p.proj_harvest_weight_lbs,0)::numeric,1), 'lb planned',
    p.flower_room, 'Planned', 'Pull #' || p.pull_no
  from harvest_pulls p
  where p_match ilike '%' || p.flower_room || '%' or coalesce(p.cultivars,'') ilike '%' || p_match || '%'
     or p.harvest_date::text = p_match
  union all
  -- 2. Takedown and the harvest record itself
  select 2, h.harvest_start, 'Harvest', 'Takedown recorded in Metrc',
    coalesce(h.raw->>'SourceStrainNames', h.name) || ' · ' || coalesce((h.raw->>'PlantCount'),'0') || ' plants',
    coalesce((h.raw->>'TotalWetWeight')::numeric,0), coalesce(h.raw->>'UnitOfWeightName','g'),
    coalesce(h.raw->>'DryingLocationName','(no room)'),
    case when h.raw->>'FinishedDate' is not null then 'Finished' else 'Open' end, h.name
  from metrc_harvests h where h.name ilike '%' || p_match || '%'
  union all
  -- 3. Where it sits now and how long it has been there
  select 3, current_date, 'Current', 'Live stage: ' || m.stage,
    'In ' || coalesce(m.room,'(no room)') || ' for ' || coalesce(m.days_since_takedown,0) || ' days'
      || case when m.waste_pct is not null then ' · waste ' || m.waste_pct || '%' else '' end
      || case when m.yield_pct is not null then ' · yield ' || m.yield_pct || '%' else '' end,
    coalesce(m.current_weight, m.wet_weight, 0), coalesce(m.uom,'g'),
    coalesce(m.room,'(no room)'), m.stage, m.harvest
  from v_harvest_stage_map m where m.harvest ilike '%' || p_match || '%'
  union all
  -- 4. Waste and destruction recorded against it
  select 4, h.harvest_start, 'Loss', 'Waste recorded',
    'Waste against ' || h.name, coalesce((h.raw->>'TotalWasteWeight')::numeric,0),
    coalesce(h.raw->>'UnitOfWeightName','g'), coalesce(h.raw->>'DryingLocationName','(no room)'),
    'Recorded loss', h.name
  from metrc_harvests h
  where h.name ilike '%' || p_match || '%' and coalesce((h.raw->>'TotalWasteWeight')::numeric,0) > 0
  union all
  -- 5. Every package produced from it
  select 5, pk.packaged_on, 'Package', 'Package created: ' || coalesce(pk.item_name,'(unnamed)'),
    'Tag ending ' || right(pk.tag, 8) || ' · ' || coalesce(pk.raw->>'ProductCategoryName',''),
    coalesce(pk.quantity,0), coalesce(pk.uom,'ea'), coalesce(pk.location,'(no location)'),
    coalesce(pk.lab_testing_state,'Not submitted'), pk.tag
  from metrc_packages pk
  where coalesce(pk.raw->>'SourceHarvestNames','') ilike '%' || p_match || '%'
  union all
  -- 6. Laboratory outcome per package
  select 6, pk.packaged_on, 'Laboratory', 'Laboratory state: ' || coalesce(pk.lab_testing_state,'Not submitted'),
    coalesce(pk.item_name,'(unnamed)') || ' · tag ending ' || right(pk.tag, 8),
    coalesce(pk.quantity,0), coalesce(pk.uom,'ea'), coalesce(pk.location,'(no location)'),
    coalesce(pk.lab_testing_state,'Not submitted'), pk.tag
  from metrc_packages pk
  where coalesce(pk.raw->>'SourceHarvestNames','') ilike '%' || p_match || '%'
    and coalesce(pk.lab_testing_state,'') not in ('','NotSubmitted')
  union all
  -- 7. Every manifest that moved a package from it
  select 7, t.created_on, 'Transfer', 'Manifest ' || t.manifest_number || ' (' || t.direction || ')',
    'To ' || coalesce(t.recipient,'(recipient not recorded)'),
    null::numeric, null::text, coalesce(t.shipper,''), t.direction, t.manifest_number
  from metrc_transfers t
  where exists (
    select 1 from metrc_packages pk
    where coalesce(pk.raw->>'SourceHarvestNames','') ilike '%' || p_match || '%'
      and t.raw::text like '%' || pk.tag || '%'
  )
  order by 2 nulls last, 1;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_import_period(p_cadence text, p_when timestamp with time zone)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_cadence like 'Monthly%'   then (date_trunc('month', p_when) - interval '1 month')::date
    when p_cadence like 'Quarterly%' then (date_trunc('quarter', p_when) - interval '3 months')::date
    when p_cadence like 'Yearly%'    then (date_trunc('year', p_when) - interval '1 year')::date
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_import_preview(p_rows jsonb, p_file_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cols text[]; det record; t record; sql text; n_total int; n_existing int;
begin
  if not f_caller_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Report uploads are restricted to administrators.');
  end if;
  if p_rows is null or jsonb_array_length(p_rows) = 0 then
    return jsonb_build_object('ok', false, 'error', 'No rows found in this file.');
  end if;
  select array_agg(k) into cols from jsonb_object_keys(p_rows -> 0) k;
  select * into det from tg_detect_report(cols);
  if det.report_key is null then
    return jsonb_build_object('ok', false, 'error', 'Not recognised.');
  end if;
  select * into t from metrc_report_types where report_key = det.report_key;
  n_total := jsonb_array_length(p_rows);
  if t.key_source_cols is null then
    return jsonb_build_object('ok', true, 'report', det.report_key, 'title', det.title,
      'rows_in_file', n_total, 'preview_available', false,
      'note', 'No key mapping recorded, so a preview cannot be built. The import still takes a full '
              || 'backup and can be undone.');
  end if;
  sql := format(
    'select count(*) from jsonb_array_elements($1) r
      where exists (select 1 from %I x where %s = %s)',
    t.target_table,
    (select string_agg(format('coalesce(x.%I::text,'''')', k), ' || ''|'' || ') from unnest(t.key_cols) k),
    (select string_agg(format('coalesce(r->>%L,'''')', s), ' || ''|'' || ') from unnest(t.key_source_cols) s));
  execute sql into n_existing using p_rows;
  return jsonb_build_object('ok', true, 'report', det.report_key, 'title', det.title,
    'target_table', det.target_table, 'rows_in_file', n_total, 'already_held', n_existing,
    'brand_new', n_total - n_existing, 'matched_on', t.key_source_cols,
    'note', case when n_existing = 0
      then 'Every row in this file is new. Nothing already held will be touched.'
      else n_existing || ' of ' || n_total || ' rows match records already held and will be updated in '
           || 'place. A full copy of every affected row is saved first, so the import can be undone.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_import_report(p_rows jsonb, p_licence text DEFAULT NULL::text, p_as_of date DEFAULT NULL::date, p_file_name text DEFAULT NULL::text, p_mode text DEFAULT 'new_only'::text, p_stated_total integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not f_caller_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Report uploads are restricted to administrators.');
  end if;
  return tg_import_report_do(p_rows, p_licence, p_as_of, p_file_name, p_mode, p_stated_total);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_import_report_do(p_rows jsonb, p_licence text DEFAULT NULL::text, p_as_of date DEFAULT NULL::date, p_file_name text DEFAULT NULL::text, p_mode text DEFAULT 'update'::text, p_stated_total integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cols text[]; det record; t record; n int := 0; imp uuid;
  backed_up int := 0; before_count bigint; after_count bigint; sql text;
  supplied int; check_result text; missing text[];
begin
  if p_mode not in ('update','new_only') then
    return jsonb_build_object('ok', false, 'error', 'Mode must be "update" or "new_only".');
  end if;
  if p_rows is null or jsonb_array_length(p_rows) = 0 then
    return jsonb_build_object('ok', false, 'error', 'No rows supplied.');
  end if;
  supplied := jsonb_array_length(p_rows);
  select array_agg(k) into cols from jsonb_object_keys(p_rows -> 0) k;
  select * into det from tg_detect_report(cols);
  if det.report_key is null then
    return jsonb_build_object('ok', false,
      'error', 'This file does not match any Metrc report we know. Columns seen: '
               || array_to_string(cols, ', '), 'columns', to_jsonb(cols));
  end if;
  select * into t from metrc_report_types where report_key = det.report_key;

  -- This export's column vocabulary. Metrc ships the same report under several
  -- column names: "Shipper Dollar Amount" and "Shipper Wholesale Price" are one
  -- figure, "Manifest" and "Manifest Number" another. Canonical names are ADDED
  -- alongside the originals, never replacing them, so source_row keeps the raw
  -- export intact as evidence. Everything downstream - the required-column check,
  -- the key, the mapper, the compare map - then speaks one vocabulary, and a new
  -- variant of a known report is a config row rather than a new mapper.
  if t.column_aliases is not null then
    select coalesce(jsonb_agg(
             r || coalesce((select jsonb_object_agg(a.canon, r ->> a.src)
                            from jsonb_each_text(t.column_aliases) a(canon, src)
                            where r ? a.src and not (r ? a.canon)), '{}'::jsonb)
           ), '[]'::jsonb)
      into p_rows
    from jsonb_array_elements(p_rows) r;
    select array_agg(k) into cols from jsonb_object_keys(p_rows -> 0) k;
  end if;

  -- RULE B1: a required column is a condition of import, not a warning after it.
  if t.required_cols is not null then
    select array_agg(rc) into missing
    from unnest(t.required_cols) rc
    where not exists (select 1 from unnest(cols) c where lower(btrim(c)) = lower(btrim(rc)));
    if missing is not null then
      return jsonb_build_object('ok', false, 'rejected', true,
        'missing_columns', to_jsonb(missing),
        'error', 'REJECTED - this export is missing ' || array_to_string(missing, ' and ') || '.  '
                 || coalesce(t.required_cols_message, 'Tick every column in Metrc and export again.'));
    end if;
  end if;

  insert into metrc_report_imports (report_type, license, file_name, row_count, mapped_to,
                                    imported_by, stated_total)
  values (det.report_key, p_licence, p_file_name, supplied, det.target_table,
          coalesce(auth.uid()::text, 'system'), p_stated_total)
  returning id into imp;

  backed_up := tg_backup_before_import(p_rows, det.report_key, imp);
  execute format('select count(*) from %I', t.target_table) into before_count;

  if p_mode = 'new_only' and t.key_source_cols is not null then
    sql := format(
      'select coalesce(jsonb_agg(r), ''[]''::jsonb) from jsonb_array_elements($1) r
        where not exists (select 1 from %I x where %s = %s)',
      t.target_table,
      (select string_agg(format('coalesce(x.%I::text,'''')', k), ' || ''|'' || ') from unnest(t.key_cols) k),
      (select string_agg(format('coalesce(r->>%L,'''')', s), ' || ''|'' || ') from unnest(t.key_source_cols) s));
    execute sql into p_rows using p_rows;
    if jsonb_array_length(p_rows) = 0 then
      update metrc_report_imports set rows_new=0, rows_changed=0,
             count_check='Nothing written - every row already held, mode was add-new-only.' where id=imp;
      return jsonb_build_object('ok', true, 'report', det.report_key, 'mode', p_mode,
        'rows_mapped', 0, 'import_id', imp,
        'note', 'Nothing written. Every row is already held and the mode was add new only.');
    end if;
  end if;

  -- A variant maps as whatever it declares itself equivalent to, so the dispatch
  -- must resolve maps_as here too. Matching on the literal key sent transfers_full
  -- down a branch that did not exist and mapped nothing.
  declare eff_key text := coalesce(t.maps_as, det.report_key);
  begin
    if eff_key = 'wholesale_transfers' then n := tg_map_wholesale(p_rows, p_licence, p_as_of, imp);
    elsif eff_key = 'test_batches' then n := tg_map_test_batches(p_rows, p_licence, p_as_of, imp);
    else n := tg_map_rest(p_rows, p_licence, p_as_of, imp, eff_key);
    end if;
  end;

  -- Rows in, no rows out, is a failure however cheerful the rest of the report
  -- looks. A file with no printed total cannot be caught by the count check, so
  -- a zero map would otherwise return ok with rows_stored = 0 and write nothing.
  if n = 0 and supplied > 0 then
    raise exception 'IMPORT REJECTED AND ROLLED BACK. % rows were read and detected as %, but none of them mapped into %.',
      supplied, det.report_key, t.target_table
      using hint = 'Nothing was written. The report is registered but its mapper matched no rows - check column_aliases and maps_as.';
  end if;

  execute format('select count(*) from %I', t.target_table) into after_count;
  check_result := tg_check_row_count(p_stated_total, supplied, n);

  -- MANDATORY: a shortfall is a failure. Undo it rather than leave a note.
  if check_result like 'FAILED%' then
    raise exception 'IMPORT REJECTED AND ROLLED BACK. %', check_result
      using hint = 'Nothing was written. Fix the export or the parser and try again.';
  end if;

  update metrc_report_imports
  set rows_new = (after_count - before_count)::int,
      rows_changed = greatest(n - (after_count - before_count)::int, 0),
      count_check = check_result
  where id = imp;

  return jsonb_build_object('ok', true, 'count_check', check_result,
    'stated_in_file', p_stated_total, 'rows_read', supplied, 'rows_stored', n,
    'report', det.report_key, 'title', det.title, 'target_table', det.target_table,
    'mode', p_mode, 'rows_added', (after_count - before_count)::int,
    'rows_updated', greatest(n - (after_count - before_count)::int, 0),
    'rows_backed_up', backed_up, 'import_id', imp, 'as_of', p_as_of);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_import_undo(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare imp record; t record; restored int := 0; removed int := 0; sql text;
begin
  if not exists (select 1 from app_users a where a.user_id = auth.uid()
                 and a.role::text in ('owner','executive','admin','ceo','cfo','coo')) then
    return jsonb_build_object('ok', false, 'error', 'Only administrators can undo an import.');
  end if;
  select * into imp from metrc_report_imports where id = p_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'No such import.'); end if;
  if imp.undone_at is not null then
    return jsonb_build_object('ok', false, 'error', 'That import was already undone on '
      || to_char(imp.undone_at, 'DD Mon YYYY HH24:MI') || '.');
  end if;
  select * into t from metrc_report_types where report_key = imp.report_type;
  if t.key_cols is null then
    return jsonb_build_object('ok', false, 'error', 'That report has no key mapping, so it cannot be undone.');
  end if;

  sql := format(
    'delete from %I x where x.import_id = %L
       and not exists (select 1 from metrc_import_backup b
                       where b.import_id = %L and b.target_table = %L and %s)',
    t.target_table, p_id, p_id, t.target_table,
    (select string_agg(format('coalesce(b.before_row->>%L,'''') = coalesce(x.%I::text,'''')', k, k), ' and ')
     from unnest(t.key_cols) k));
  execute sql;
  get diagnostics removed = row_count;

  sql := format(
    'insert into %I select (jsonb_populate_record(null::%I, b.before_row)).*
       from metrc_import_backup b where b.import_id = %L and b.target_table = %L
     on conflict (%s) do update set %s',
    t.target_table, t.target_table, p_id, t.target_table,
    (select string_agg(quote_ident(k), ', ') from unnest(t.key_cols) k),
    (select string_agg(format('%1$I = excluded.%1$I', a.attname), ', ')
     from pg_attribute a
     where a.attrelid = t.target_table::regclass and a.attnum > 0 and not a.attisdropped
       and not (a.attname = any (t.key_cols))));
  execute sql;
  get diagnostics restored = row_count;

  update metrc_report_imports
  set undone_at = now(), undone_by = coalesce(auth.uid()::text, 'system')
  where id = p_id;

  return jsonb_build_object('ok', true, 'rows_removed', removed, 'rows_restored', restored,
    'note', 'Put back. ' || removed || ' rows this import created were removed and '
            || restored || ' rows it changed were restored from the snapshot taken before it ran.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_intelligence_sweep()
 RETURNS TABLE(new_findings integer, open_total integer)
 LANGUAGE plpgsql
AS $function$
declare n int := 0; t int := 0; cpp numeric;
begin
  select cost_per_pound into cpp from cost_model where scope='cultivation' order by effective_from desc limit 1;
  with found as (
    select 'Schedule discipline' as agent, 'critical' as severity,
      'Pull or dry ran late in ' || coalesce(room,'a room') as headline,
      coalesce(detail,'') || ' - scheduled ' || scheduled_date || ', ' || rule_verdict as detail,
      days_off_schedule as metric, 'days late' as units,
      null::numeric as dollars, null::numeric as pounds,
      coalesce(room,'') as scope,
      'Late is a violation of the hard rule. Plan a weekend crew or a second shift rather than slipping the next date.' as action,
      'late_violations' as drill_to,
      'late:' || coalesce(room,'') || ':' || coalesce(scheduled_date::text,'') as fingerprint
    from v_late_violations where rule_verdict like 'VIOLATION%'
    union all
    select 'Loss and yield', case when waste_pct > 25 then 'critical' else 'elevated' end,
      scope_type || ' ' || scope || ' is wasting ' || waste_pct || ' percent',
      waste_lbs || ' pounds wasted across ' || harvests || ' harvests',
      waste_pct, 'percent waste', cost_of_waste, waste_lbs, scope,
      'Investigate this ' || lower(scope_type) || '. At ' || coalesce(cpp,0) || ' dollars per pound that waste has cost ' || cost_of_waste || ' dollars.',
      'loss_analysis', 'waste:' || scope_type || ':' || scope
    from v_cost_of_loss where waste_pct > 15
    union all
    select 'Room turnaround', 'critical', harvest || ' is blocking ' || room, drying_status,
      days_since_takedown, 'days since takedown', null, null, room,
      'This room cannot be replanted until drying finishes. Finish it or move the material.',
      'harvest_lifecycle', 'blocking:' || harvest
    from v_harvest_lifecycle where verdict = 'BLOCKING THE ROOM'
    union all
    select 'Weight reporting', 'elevated', 'Weights missing for ' || harvest, weights_status,
      days_since_takedown, 'days since takedown', null, null, room,
      'Cultivation must record the weights. Nothing downstream can be costed or allocated without them.',
      'harvest_lifecycle', 'weights:' || harvest
    from v_harvest_lifecycle where verdict = 'MISSING WEIGHTS'
    union all
    /* now carries weight and value - it always had quantity and uom */
    select 'Compliance watch', severity, flag || ' - ' || item, detail, quantity, uom,
      case when f_is_weight(uom)
           then round(f_to_pounds(quantity, uom) * (select rate from f_price_per_lb(item) limit 1), 2) end,
      case when f_is_weight(uom) then round(f_to_pounds(quantity, uom), 2) end,
      coalesce(location,''), 'Resolve this in Metrc. It is live compliance exposure.',
      'custody_alerts', 'custody:' || flag || ':' || identifier
    from v_custody_alerts
    union all
    select 'Cash velocity', severity, 'Aging stock: ' || item,
      action || ' - ' || days_here || ' days in ' || location, days_here, 'days',
      case when f_is_weight(uom)
           then round(f_to_pounds(quantity, uom) * (select rate from f_price_per_lb(category) limit 1), 2) end,
      case when f_is_weight(uom) then round(f_to_pounds(quantity, uom), 2) end,
      location,
      'Move it, sell it, or decide its disposition. Every day it sits is capital doing nothing.',
      'inventory_aging', 'aging:' || identifier || ':' || severity
    from v_inventory_aging where severity in ('critical','elevated')
    union all
    select 'Allocation control', 'elevated', 'No approved allocation: ' || item,
      approval_state || ' - ' || quantity || ' ' || uom || ' in ' || location,
      days_in_system, 'days in system',
      case when f_is_weight(uom)
           then round(f_to_pounds(quantity, uom) * (select rate from f_price_per_lb(material_class) limit 1), 2) end,
      case when f_is_weight(uom) then round(f_to_pounds(quantity, uom), 2) end,
      location,
      'Every material needs an approved allocation before it moves. Raise a request or approve the pending one.',
      'awaiting_allocation', 'alloc:' || identifier
    from v_awaiting_allocation where days_in_system > 30 and coalesce(allocation_status,'no request') = 'no request'
    union all
    select 'Schedule discipline', 'elevated',
      event_type || ' lands on a ' || falls_on || ' in ' || coalesce(room,'a room'),
      coalesce(detail,'') || ' on ' || event_date, days_away, 'days away', null, null, coalesce(room,''),
      'Plan a weekend crew or a second shift now. The date does not move.',
      'weekend_watch', 'weekend:' || event_type || ':' || event_date
    from v_weekend_watch where action like 'PLAN A WEEKEND%'
  ),
  deduped as (
    select distinct on (fingerprint) * from found
    order by fingerprint, case severity when 'critical' then 0 when 'elevated' then 1 else 2 end
  )
  insert into agent_findings (agent, severity, headline, detail, metric, units, dollars, pounds, scope, action, drill_to, fingerprint)
  select d.agent, d.severity, d.headline, d.detail, d.metric, d.units, d.dollars, d.pounds, d.scope, d.action, d.drill_to, d.fingerprint
  from deduped d
  where not exists (select 1 from agent_findings a where a.fingerprint = d.fingerprint and a.resolved_at is null);
  get diagnostics n = row_count;
  select count(*) into t from agent_findings where resolved_at is null;
  new_findings := n; open_total := t; return next;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_inventory_as_of(p_date date)
 RETURNS TABLE(license text, category text, item text, packages numeric, quantity_estimate numeric, uom text, cost_per_unit numeric, value_at_cost numeric, basis text, confidence text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare cpp numeric;
begin
  select cost_per_pound into cpp from cost_model where scope='cultivation' order by effective_from desc limit 1;
  return query
  select p.license,
    coalesce(nullif(p.raw->>'ProductCategoryName',''),'Uncategorised'),
    coalesce(p.item_name,'(unnamed)'),
    count(*)::numeric,
    round(sum(coalesce(nullif((p.raw->>'InitialQuantity')::numeric,0), p.quantity, 0))::numeric,1),
    coalesce(max(p.uom),'ea'),
    case when coalesce(max(p.uom),'') in ('g','Grams') then round((coalesce(cpp,0)/453.592)::numeric,4) end,
    case when coalesce(max(p.uom),'') in ('g','Grams')
      then round((sum(coalesce(nullif((p.raw->>'InitialQuantity')::numeric,0), p.quantity, 0)) / 453.592 * coalesce(cpp,0))::numeric,2) end,
    'Quantity the package was created with, valued at ' || coalesce(cpp,0)::text || ' dollars per pound to grow',
    'ESTIMATE - Metrc does not expose a historical snapshot here. For a filed return, export the Inventory Point-in-Time report from the Metrc Reports Control Panel for this date and import it on the Report Import page; that is the authoritative figure.'
  from metrc_packages p
  where p.packaged_on is not null and p.packaged_on <= p_date
    and (p.raw->>'ArchivedDate' is null or (p.raw->>'ArchivedDate')::date > p_date)
  group by p.license, coalesce(nullif(p.raw->>'ProductCategoryName',''),'Uncategorised'), coalesce(p.item_name,'(unnamed)')
  order by 8 desc nulls last;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_inventory_watch()
 RETURNS TABLE(open_alerts integer, auto_resolved integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res int := 0; v_open int := 0; v_cost numeric; v_start timestamptz := now();
begin
  select value into v_cost from conversion_factors where key='target_cost_per_lb';

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill, pounds, dollars)
  select 'limit:'||stream||coalesce(location,''), 'elevated', 'Inventory control',
    stream||' is '||lower(status),
    coalesce(on_hand_lb,0)||' lb on hand'||case when max_lb is not null then ' against a ceiling of '||max_lb||' lb' else '' end||
    case when max_age_days is not null then '. Oldest package '||oldest_days||' days against a limit of '||max_age_days else '' end,
    'Move it, sell it, process it, or raise the limit deliberately.', 'storage_limit_status',
    on_hand_lb, round(on_hand_lb*v_cost)
  from v_storage_limit_status
  where status in ('OVER THE STORAGE LIMIT','MATERIAL OLDER THAN THE LIMIT','APPROACHING THE LIMIT')
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    detail=excluded.detail, pounds=excluded.pounds, dollars=excluded.dollars, resolved_at=null;

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill, pounds, dollars)
  select 'ourfail:'||stream, 'critical', 'Quality',
    round(sum(pounds),1)||' lb of our own '||lower(stream)||' failed testing',
    sum(packages)||' packages we grew and packaged, then failed. Oldest '||max(oldest_days)||' days.',
    'Find the root cause, then decide remediate or destroy and record it in Metrc.',
    'failed_testing_by_origin', round(sum(pounds),1), round(sum(pounds)*v_cost)
  from v_stock_on_hand where lab_state='TestFailed' and origin='Grown by us' group by stream
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    headline=excluded.headline, detail=excluded.detail, pounds=excluded.pounds, dollars=excluded.dollars, resolved_at=null;

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill, pounds, dollars)
  select 'untested:'||stream, 'critical', 'Quality',
    round(sum(pounds),1)||' lb of '||lower(stream)||' never submitted for testing',
    sum(packages)||' packages, oldest '||max(oldest_days)||' days. Untested product cannot be sold.',
    'Submit it or record a disposition.', 'lab_results', round(sum(pounds),1), round(sum(pounds)*v_cost)
  from v_stock_on_hand where lab_state='NotSubmitted' group by stream having sum(pounds) > 1
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    headline=excluded.headline, detail=excluded.detail, pounds=excluded.pounds, dollars=excluded.dollars, resolved_at=null;

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill, pounds)
  select 'massbal:'||harvest, 'critical', 'Mass balance',
    'Harvest '||harvest||' does not reconcile', verdict,
    'Wet weight must equal packaged plus waste plus evaporated moisture. Find which figure is wrong and correct it in Metrc.',
    'moisture_accounting', abs(reconciliation_gap_lb)
  from v_moisture_accounting
  where finished is not null and abs(coalesce(reconciliation_gap_lb,0)) > greatest(2, wet_lb*0.02)
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    detail=excluded.detail, resolved_at=null;

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill)
  select 'tpsitting:'||supplier, 'elevated', 'Third party',
    count(*)||' purchased packages from '||supplier||' sitting untouched',
    'Oldest received '||max(days_since_received)||' days ago with nothing drawn from it.',
    'Process it or sell it. Purchased material sitting still is cash already spent.', 'third_party_lifecycle'
  from v_third_party_lifecycle where position like 'SITTING%' group by supplier
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    detail=excluded.detail, resolved_at=null;

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill)
  select 'labslow:'||coalesce(category,'unknown'), 'watch', 'Laboratory',
    'Laboratory turnaround on '||category||' is slow',
    'Average '||coalesce(avg_turnaround_days,0)||' days, worst '||slowest_turnaround_days||'. '||took_over_14_days||' packages took over 14 days.',
    'Chase the laboratory. Every day waiting is a day the product cannot be sold.', 'lab_turnaround_summary'
  from v_lab_turnaround_summary where coalesce(slowest_turnaround_days,0) > 14
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    detail=excluded.detail, resolved_at=null;

  insert into inventory_alerts (fingerprint, severity, area, headline, detail, what_to_do, drill, pounds)
  select 'question:'||question_key, 'elevated', 'Unanswered',
    'A question has been open '||days_open||' days with '||coalesce(exposure_lb,0)||' lb riding on it',
    question||' -- blocks: '||coalesce(what_is_blocked,'reporting'),
    'Answer it. Until it is answered the figures it feeds cannot be trusted.', 'open_questions', exposure_lb
  from v_open_questions where days_open > 3
  on conflict (fingerprint) do update set last_seen=now(), times_seen=inventory_alerts.times_seen+1,
    headline=excluded.headline, pounds=excluded.pounds, resolved_at=null;

  update inventory_alerts set resolved_at=now(), resolved_by='automatic',
    resolution_note='No longer detected on the sweep - the underlying problem is gone.'
   where resolved_at is null and last_seen < v_start;
  get diagnostics v_res = row_count;
  select count(*) into v_open from inventory_alerts where resolved_at is null;
  return query select v_open, v_res;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_log_client_error(p_view text, p_message text, p_stack text DEFAULT NULL::text, p_component text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_run bigint;
begin
  if coalesce(btrim(p_message),'') = '' then return; end if;

  insert into watchdog_runs (ran_at, ran_by, notes)
  values (now(), 'browser', 'client-side render error reported by the error boundary')
  returning id into v_run;

  insert into watchdog_findings
    (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
     why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, drill)
  values (
    v_run,
    'clienterror:'||coalesce(p_view,'unknown')||':'||left(coalesce(p_message,''),80),
    'critical',
    'The '||coalesce(p_view,'unknown')||' page crashed in the browser',
    'Front end · '||coalesce(p_view,'unknown'),
    'Whoever owns the front end',
    'A render exception blanks the section for whoever hit it. Without this record the '
      || 'only person who knows is the one person who cannot fix it.',
    'Caught by the React error boundary and reported from the browser.',
    'Open the page named above and reproduce it. The message and component stack are on this finding.',
    left(coalesce(p_message,''), 400),
    to_jsonb(jsonb_build_object(
      'view', p_view,
      'message', p_message,
      'component', left(coalesce(p_component,''), 2000),
      'stack', left(coalesce(p_stack,''), 2000))),
    coalesce(p_view,'tower'));
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_adjustments(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  insert into metrc_rpt_adjustments as t
    (package_tag, item, item_category, quantity, uom, reason, note,
     adjusted_on, packaged_on, adjusted_by, licence, as_of_date, line_no, source_row, import_id)
  select package_tag, item, item_category, quantity, uom, reason, note,
         adjusted_on, packaged_on, adjusted_by, p_licence, p_as_of,
         row_number() over (partition by package_tag, adjusted_on, reason, quantity
                            order by ord)::int,
         source_row, p_imp
  from (
    select r->>'Package' as package_tag, r->>'Item' as item, r->>'Item Category' as item_category,
           f_rpt_lb(r->>'Quantity') as quantity,
           case when (r->>'Quantity') ilike '%kg%' then 'kg' when (r->>'Quantity') ilike '%lb%' then 'lb'
                when (r->>'Quantity') ilike '%oz%' then 'oz' else 'g' end as uom,
           r->>'Reason' as reason, r->>'Note' as note,
           f_rpt_date(r->>'Adj. Date') as adjusted_on, f_rpt_date(r->>'Pack Date') as packaged_on,
           r->>'User' as adjusted_by, r as source_row, ord
    from jsonb_array_elements(p_rows) with ordinality e(r, ord)
    where nullif(r->>'Package','') is not null) s
  on conflict (package_tag, adjusted_on, reason, quantity, line_no) do update set
    note=excluded.note, adjusted_by=excluded.adjusted_by, as_of_date=excluded.as_of_date,
    source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_generic(p_report_key text, p_rows jsonb, p_licence text, p_import uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t record; k text; spec jsonb; cols text[] := '{}'; exprs text[] := '{}';
  upd text[] := '{}'; sql text; n int;
begin
  select target_table, column_map, key_cols into t
  from metrc_report_types where report_key = p_report_key;
  if t.column_map is null then
    raise exception 'Report % has no column map.', p_report_key;
  end if;

  for k, spec in select * from jsonb_each(t.column_map) loop
    cols := cols || quote_ident(k);
    exprs := exprs || case spec->>'type'
      when 'num'  then format('f_rpt_num(r->>%L)',  spec->>'from')
      when 'lb'   then format('f_rpt_lb(r->>%L)',   spec->>'from')
      when 'date' then format('f_rpt_date(r->>%L)', spec->>'from')
      when 'bool' then format('(lower(coalesce(r->>%L,'''')) in (''yes'',''true''))', spec->>'from')
      else format('r->>%L', spec->>'from') end;
    if not (k = any (t.key_cols)) then
      upd := upd || format('%1$I = excluded.%1$I', k);
    end if;
  end loop;

  upd := upd || array['source_row = excluded.source_row', 'import_id = excluded.import_id',
                      'imported_at = now()'];

  sql := format(
    'insert into %I (%s, licence, source_row, import_id) select %s, %L, r, %L
       from jsonb_array_elements($1) r
      where nullif(r->>%L, '''') is not null
      on conflict (%s) do update set %s',
    t.target_table,
    array_to_string(cols, ', '),
    array_to_string(exprs, ', '),
    p_licence, p_import,
    (t.column_map -> (t.key_cols)[1]) ->> 'from',
    array_to_string((select array_agg(quote_ident(x)) from unnest(t.key_cols) x), ', '),
    array_to_string(upd, ', '));

  execute sql using p_rows;
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_lab_results(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  insert into metrc_rpt_lab_results as t
    (package_tag, test_name, line_no, lab_licence, lab_facility, packaged_licence,
     packaged_facility, source_harvests, source_packages, item, category, lab_testing,
     test_date, overall_passed, passed, result, result_raw, lte_date, recorded_on, notes,
     licence, as_of_date, source_row, import_id)
  select package_tag, test_name,
         row_number() over (partition by package_tag, test_name order by ord)::int,
         lab_licence, lab_facility, packaged_licence, packaged_facility,
         source_harvests, source_packages, item, category, lab_testing,
         test_date, overall_passed, passed, result, result_raw, lte_date, recorded_on, notes,
         coalesce(packaged_licence, p_licence), p_as_of, source_row, p_imp
  from (
    select r->>'Package' as package_tag, r->>'Test Name' as test_name,
           r->>'Lab Lic. No.' as lab_licence, r->>'Lab Facility' as lab_facility,
           r->>'Packaged Lic. No.' as packaged_licence, r->>'Packaged Facility' as packaged_facility,
           r->>'Source Harvest Names' as source_harvests, r->>'Source Package Labels' as source_packages,
           r->>'Item' as item, r->>'Category' as category, r->>'Lab Testing' as lab_testing,
           f_rpt_date(r->>'Test Date') as test_date, r->>'Overall' as overall_passed,
           r->>'Passed' as passed, f_rpt_num(r->>'Result') as result, r->>'Result' as result_raw,
           f_rpt_date(r->>'LTE Date') as lte_date, f_rpt_date(r->>'Date') as recorded_on,
           r->>'Notes' as notes, r as source_row, ord
    from jsonb_array_elements(p_rows) with ordinality e(r, ord)
    where nullif(r->>'Package','') is not null and nullif(r->>'Test Name','') is not null) s
  on conflict (package_tag, test_name, line_no) do update set
    result=excluded.result, passed=excluded.passed, test_date=excluded.test_date,
    as_of_date=excluded.as_of_date, source_row=excluded.source_row,
    import_id=excluded.import_id, imported_at=now();
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_rest(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid, p_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text;
begin
  select coalesce(maps_as, p_key) into k from metrc_report_types where report_key = p_key;
  k := coalesce(k, p_key);
  if k = 'packages_adjustments' then return tg_map_adjustments(p_rows, p_licence, p_as_of, p_imp);
  elsif k = 'lab_results' then return tg_map_lab_results(p_rows, p_licence, p_as_of, p_imp);
  elsif k = 'transfer_manifests' then return tg_map_transfer_manifests(p_rows, p_licence, p_as_of, p_imp);
  end if;
  return tg_map_rest_v1(p_rows, p_licence, p_as_of, p_imp, k);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_rest_v1(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid, p_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int := 0;
begin
  if p_key = 'harvests_inactive' then
    insert into metrc_rpt_harvest_moisture as t
      (harvest_batch, strain, room, plants, wet_lb, waste_lb, packaged_lb,
       moisture_loss_lb, moisture_pct, lab_testing, finished_on, licence, as_of_date, source_row, import_id)
    select distinct on (r->>'Harvest Batch')
           r->>'Harvest Batch', r->>'Strain', r->>'Location', f_rpt_num(r->>'Plants'),
           f_rpt_lb(r->>'Wet Weight'), f_rpt_lb(r->>'Waste'), f_rpt_lb(r->>'Total Weight Packaged'),
           f_rpt_lb(r->>'Moisture Loss'),
           case when f_rpt_num(r->>'Wet Weight') > 0
                then round(100.0 * f_rpt_num(r->>'Moisture Loss') / f_rpt_num(r->>'Wet Weight'), 1) end,
           r->>'Lab Testing', f_rpt_date(r->>'Finished'), p_licence, p_as_of, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Harvest Batch','') is not null
    order by r->>'Harvest Batch'
    on conflict (harvest_batch) do update set
      wet_lb=excluded.wet_lb, waste_lb=excluded.waste_lb, packaged_lb=excluded.packaged_lb,
      moisture_loss_lb=excluded.moisture_loss_lb, moisture_pct=excluded.moisture_pct,
      finished_on=excluded.finished_on, as_of_date=excluded.as_of_date,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();

  elsif p_key = 'packages_transferred' then
    insert into metrc_rpt_package_transfers as t
      (manifest_number, package_tag, destination_licence, destination_facility, source_harvest,
       source_package, item, category, strain, shipped_qty, received_qty, gross_weight,
       shipper_wholesale_price, receiver_wholesale_price, status, received_on, licence,
       as_of_date, source_row, import_id)
    select distinct on (r->>'Manifest Number', r->>'Package')
           r->>'Manifest Number', r->>'Package', r->>'Destination License', r->>'Destination Facility',
           r->>'Source Harvest', r->>'Source Package', r->>'Item', r->>'Category', r->>'Item Strain',
           f_rpt_num(r->>'Shipped Quantity'), f_rpt_num(r->>'Received Quantity'),
           f_rpt_num(r->>'Gross Weight'),
           f_rpt_num(r->>'Shipper Wholesale Price'), f_rpt_num(r->>'Receiver Wholesale Price'),
           r->>'Status', f_rpt_date(r->>'Received Date'), p_licence, p_as_of, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Manifest Number','') is not null and nullif(r->>'Package','') is not null
    order by r->>'Manifest Number', r->>'Package'
    on conflict (manifest_number, package_tag) do update set
      shipper_wholesale_price=excluded.shipper_wholesale_price,
      receiver_wholesale_price=excluded.receiver_wholesale_price,
      shipped_qty=excluded.shipped_qty, received_qty=excluded.received_qty, as_of_date=excluded.as_of_date,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();

  elsif p_key = 'plants_waste' then
    insert into metrc_rpt_plant_waste as t
      (waste_number, waste_method, material_mixed, waste_qty, uom, reason,
       total_plants, waste_date, plant_batch, licence, as_of_date, source_row, import_id)
    select distinct on (r->>'Plant Waste Number')
           r->>'Plant Waste Number', r->>'Waste Method', r->>'Material Mixed',
           f_rpt_lb(r->>'Waste'), coalesce(nullif(r->>'Unit Of Measure',''),'g'), r->>'Reason',
           f_rpt_num(r->>'Total Plants'), f_rpt_date(r->>'Waste Date'), r->>'Plant Batch',
           p_licence, p_as_of, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Plant Waste Number','') is not null
    order by r->>'Plant Waste Number'
    on conflict (waste_number) do update set
      waste_qty=excluded.waste_qty, reason=excluded.reason, as_of_date=excluded.as_of_date,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();

  elsif p_key = 'plants_destroyed' then
    insert into metrc_rpt_plants_destroyed as t
      (plant_tag, plant_batch, tag_type, strain, location, phase, phase_date,
       plant_batch_date, phase_length, harvested, licence, as_of_date, source_row, import_id)
    select distinct on (r->>'Plant')
           r->>'Plant', r->>'Plant Batch', r->>'Tag Type', r->>'Strain', r->>'Location',
           r->>'Phase', f_rpt_date(r->>'Phase Date'), f_rpt_date(r->>'Plant Batch Date'),
           r->>'Phase Length', r->>'Harvested', p_licence, p_as_of, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Plant','') is not null
    order by r->>'Plant', f_rpt_date(r->>'Phase Date') desc nulls last
    on conflict (plant_tag) do update set
      phase=excluded.phase, phase_date=excluded.phase_date, as_of_date=excluded.as_of_date,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();

  elsif p_key = 'inventory_point_in_time' then
    if p_as_of is null then raise exception 'Inventory Point in Time needs its as-of date.'; end if;
    insert into metrc_rpt_point_in_time as t
      (as_of_date, tag, record_type, name, category, strain, location, sublocation,
       status_current, expiration_date, sell_by_date, use_by_date, licence, source_row, import_id)
    select distinct on (r->>'Tag Number')
           p_as_of, r->>'Tag Number', r->>'Type', r->>'Name', r->>'Category', r->>'Strain',
           r->>'Location', r->>'Sublocation', r->>'Status Current',
           f_rpt_date(r->>'Expiration Date'), f_rpt_date(r->>'Sell By Date'), f_rpt_date(r->>'Use By Date'),
           p_licence, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Tag Number','') is not null
    order by r->>'Tag Number'
    on conflict (as_of_date, tag) do update set
      status_current=excluded.status_current, location=excluded.location,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();

  elsif p_key = 'harvests' then
    insert into metrc_rpt_harvests as t
      (harvest_name, strain, room, plants, wet_lb, waste_lb, total_packaged_lb,
       package_count, current_weight_lb, lab_testing, on_hold, batch_date, finished_date,
       licence, as_of_date, source_row, import_id)
    select distinct on (r->>'Harvest Name')
           r->>'Harvest Name', r->>'Strains', r->>'Location', f_rpt_num(r->>'Plants'),
           f_rpt_lb(r->>'Wet Wgt.'), f_rpt_lb(r->>'Waste'), f_rpt_lb(r->>'Total Pkg''d'),
           f_rpt_num(r->>'Pkg''s'), f_rpt_lb(r->>'Weight'), r->>'Lab Testing', r->>'Hold',
           f_rpt_date(r->>'Batch Date'), f_rpt_date(r->>'Finished Date'), p_licence, p_as_of, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Harvest Name','') is not null
    order by r->>'Harvest Name'
    on conflict (harvest_name) do update set
      wet_lb=excluded.wet_lb, waste_lb=excluded.waste_lb,
      total_packaged_lb=excluded.total_packaged_lb, current_weight_lb=excluded.current_weight_lb,
      finished_date=excluded.finished_date, as_of_date=excluded.as_of_date,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();

  elsif p_key = 'packages_inventory' then
    insert into metrc_rpt_packages_inventory as t
      (package_tag, harvest, source_packages, item, category, location, quantity, uom,
       production_batch, lab_testing, packaged_on, licence, as_of_date, source_row, import_id)
    select distinct on (r->>'Package')
           r->>'Package', r->>'Harvest', r->>'Source Packages', r->>'Item', r->>'Category',
           r->>'Location', f_rpt_num(r->>'Quantity'), r->>'UoM',
           r->>'Prod. Batch No.', r->>'Lab Testing', f_rpt_date(r->>'Date'), p_licence, p_as_of, r, p_imp
    from jsonb_array_elements(p_rows) r
    where nullif(r->>'Package','') is not null
    order by r->>'Package'
    on conflict (package_tag) do update set
      quantity=excluded.quantity, location=excluded.location, lab_testing=excluded.lab_testing,
      as_of_date=excluded.as_of_date,
      source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();
  end if;

  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_test_batches(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; v text := chr(10);
begin
  insert into metrc_rpt_test_batches as t
    (harvest_batch, package_tag, test_batch_name, strain, created_on, lab_testing,
     finished_on, category, item_name, packaged_on, lab_test_stage, test_passed,
     test_date, licence, as_of_date, line_no, source_row, import_id)
  select harvest_batch, package_tag, test_batch_name, strain, created_on, lab_testing,
         finished_on, category, item_name, packaged_on, lab_test_stage, test_passed,
         test_date, p_licence, p_as_of,
         row_number() over (partition by package_tag, test_batch_name order by ord)::int,
         source_row, p_imp
  from (
    select nullif(r->>'Harvest Batch','') as harvest_batch, r->>'Package Tag' as package_tag,
           coalesce(nullif(r->>'Test Batch Name',''),'(none)') as test_batch_name,
           r->>'Strain' as strain,
           f_rpt_date(coalesce(r->>'Created Date', r->>('Created'||v||'Date'))) as created_on,
           coalesce(r->>'Lab Testing', r->>('Lab '||v||'Testing')) as lab_testing,
           f_rpt_date(r->>'Finished') as finished_on, r->>'Category' as category,
           r->>'Item Name' as item_name, f_rpt_date(r->>'Package Date') as packaged_on,
           r->>'Lab Test Stage' as lab_test_stage, r->>'Test Passed' as test_passed,
           f_rpt_date(r->>'Test Date') as test_date, r as source_row, ord
    from jsonb_array_elements(p_rows) with ordinality e(r, ord)
    where nullif(r->>'Package Tag','') is not null) s
  on conflict (package_tag, test_batch_name, line_no) do update set
    harvest_batch=coalesce(excluded.harvest_batch, t.harvest_batch),
    test_passed=excluded.test_passed, test_date=excluded.test_date, as_of_date=excluded.as_of_date,
    source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_transfer_manifests(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  insert into metrc_rpt_transfer_manifests as m
    (manifest_number, item_category, invoice_number, direction, transfer_type,
     origin_licence, origin_facility, origin_type,
     destination_licence, destination_facility, destination_type,
     packages, shipped_count, received_count, count_variance,
     shipped_weight, received_weight, weight_variance,
     created_on, received_on, voided, licence, as_of_date, source_row, import_id)
  select distinct on (r->>'Manifest', coalesce(r->>'Item Category',''))
         r->>'Manifest',
         coalesce(r->>'Item Category',''),
         coalesce(r->>'Inv. Nbr', r->>'Invoice Number'),
         -- Direction is derived from the licences, never from the file name.
         case when r->>'Origin Lic.' in ('MC281714','MP281909') then 'outbound'
              when r->>'Dest. Lic.'  in ('MC281714','MP281909') then 'inbound'
              when coalesce(r->>'Origin','') <> '' then 'inbound'
              else null end,
         r->>'Type',
         r->>'Origin Lic.', coalesce(r->>'Origin Facility', r->>'Origin'), r->>'Origin Type',
         r->>'Dest. Lic.', r->>'Destination Facility', r->>'Dest. Type',
         f_rpt_num(r->>'Packages'),
         f_rpt_num(r->>'Ship''d'), f_rpt_num(r->>'Rcv''d'), r->>'% Var',
         f_rpt_num(r->>'Ship''d (2)'), f_rpt_num(r->>'Rcv''d (2)'), r->>'% Var (2)',
         f_rpt_date(r->>'Created'), f_rpt_date(r->>'Received'),
         r->>'Voided', p_licence, p_as_of, r, p_imp
  from jsonb_array_elements(p_rows) r
  where nullif(r->>'Manifest','') is not null
  on conflict (manifest_number, item_category) do update set
    invoice_number = coalesce(excluded.invoice_number, m.invoice_number),
    direction = coalesce(excluded.direction, m.direction),
    transfer_type = coalesce(excluded.transfer_type, m.transfer_type),
    origin_licence = coalesce(excluded.origin_licence, m.origin_licence),
    origin_facility = coalesce(excluded.origin_facility, m.origin_facility),
    destination_licence = coalesce(excluded.destination_licence, m.destination_licence),
    destination_facility = coalesce(excluded.destination_facility, m.destination_facility),
    packages = coalesce(excluded.packages, m.packages),
    shipped_count = coalesce(excluded.shipped_count, m.shipped_count),
    received_count = coalesce(excluded.received_count, m.received_count),
    shipped_weight = coalesce(excluded.shipped_weight, m.shipped_weight),
    received_weight = coalesce(excluded.received_weight, m.received_weight),
    created_on = coalesce(excluded.created_on, m.created_on),
    received_on = coalesce(excluded.received_on, m.received_on),
    voided = coalesce(excluded.voided, m.voided),
    licence = coalesce(excluded.licence, m.licence),
    as_of_date = excluded.as_of_date, source_row = excluded.source_row,
    import_id = excluded.import_id, imported_at = now();
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_map_wholesale(p_rows jsonb, p_licence text, p_as_of date, p_imp uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  insert into metrc_rpt_wholesale as t
    (manifest_number, item, invoice_number, origin_licence, origin_facility,
     destination_licence, destination_facility, item_category, amount, receiver_amount,
     voided, created_on, received_on, licence, as_of_date, source_row, import_id)
  select distinct on (r->>'Manifest', coalesce(nullif(r->>'Item',''),'(no item)'))
         r->>'Manifest', coalesce(nullif(r->>'Item',''),'(no item)'), r->>'Inv. Nbr',
         r->>'Origin Lic.', r->>'Origin Facility', r->>'Dest. Lic.', r->>'Destination Facility',
         r->>'Item Category',
         coalesce(f_rpt_price(r->>'Amount','S'), f_rpt_num(r->>'Amount')),
         f_rpt_price(r->>'Amount','R'),
         lower(coalesce(r->>'Voided','')) = 'yes',
         f_rpt_date(r->>'Created'), f_rpt_date(r->>'Received'), p_licence, p_as_of, r, p_imp
  from jsonb_array_elements(p_rows) r
  where nullif(r->>'Manifest','') is not null
    -- a report footer carries "Totals:" where an item category belongs
    and coalesce(r->>'Item Category','') not ilike '%total%'
    and coalesce(r->>'Item','') not ilike '%total%'
  order by r->>'Manifest', coalesce(nullif(r->>'Item',''),'(no item)')
  on conflict (manifest_number, item) do update set
    amount=excluded.amount, receiver_amount=excluded.receiver_amount,
    invoice_number=excluded.invoice_number, as_of_date=excluded.as_of_date,
    source_row=excluded.source_row, import_id=excluded.import_id, imported_at=now();
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_mark_incomplete_nav()
 RETURNS TABLE(view_key text, label text, rows_found bigint)
 LANGUAGE plpgsql
AS $function$
declare r record; n bigint;
begin
  for r in select nr.view_key, nr.label, nr.table_ref from nav_registry nr where nr.table_ref is not null and nr.enabled loop
    begin
      execute format('select count(*) from %I', r.table_ref) into n;
    exception when others then n := 0; end;
    view_key := r.view_key; label := r.label; rows_found := n;
    if n = 0 then
      update nav_registry set milestone = coalesce(nullif(milestone,''), 'SOON') where nav_registry.view_key = r.view_key;
      return next;
    end if;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_materialize_recurring()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_created integer := 0;
begin
  with source as (
    select
      t.id,
      coalesce(t.recurrence_parent_id, t.id) as series_id,
      t.title,
      t.assignee_employee_id,
      t.priority,
      t.tags,
      t.space_id,
      t.recurrence,
      t.created_by,
      coalesce(t.due_on, current_date) as base_due_on,
      greatest(1, case
                    when t.recurrence ->> 'every_days' ~ '^[0-9]+$'
                      then (t.recurrence ->> 'every_days')::integer
                    else 7
                  end) as every_days
    from public.tasks t
    where t.recurrence is not null
      and t.status = 'done'
  ),
  eligible as (
    select distinct on (s.series_id)
      s.*,
      (s.base_due_on + (s.every_days || ' days')::interval)::date as next_due_on
    from source s
    where not exists (
      select 1
      from public.tasks sibling
      where coalesce(sibling.recurrence_parent_id, sibling.id) = s.series_id
        and sibling.id <> s.id
        and coalesce(sibling.due_on, current_date) > s.base_due_on
    )
    order by s.series_id, s.base_due_on desc, s.id
  ),
  inserted as (
    insert into public.tasks (
      title, status, priority, assignee_employee_id, tags, space_id,
      due_on, created_by, recurrence, recurrence_parent_id
    )
    select
      e.title, 'todo', e.priority, e.assignee_employee_id, e.tags, e.space_id,
      e.next_due_on, e.created_by, e.recurrence, e.series_id
    from eligible e
    returning 1
  )
  select count(*)::integer into v_created from inserted;

  return v_created;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_metrc_backfill_next()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w metrc_backfill_window; req bigint; inflight int;
begin
  -- Close out the window the last run belonged to, using that run's own outcome.
  update metrc_backfill_window b
     set status = case when r.status in ('ok','partial') then 'done' else 'failed' end,
         records = r.records, finished_at = r.finished_at,
         note = coalesce(r.error, 'closed from run '||r.id)
    from metrc_sync_runs r
   where b.sync_run_id = r.id and b.status = 'running' and r.finished_at is not null;

  select * into w from metrc_backfill_window
   where status = 'pending' and attempts < 3
   order by win_start limit 1;

  if not found then
    return 'nothing pending - backfill complete or exhausted';
  end if;

  -- Never overlap, and check the endpoint we are ACTUALLY about to fire. The previous
  -- version hardcoded 'plants%' and would have let a packages run overlap silently.
  select count(*) into inflight from metrc_sync_runs
   where status = 'running' and endpoint like w.endpoint||'%'
     and started_at > now() - interval '10 minutes';
  if inflight > 0 then
    return 'waiting - a '||w.endpoint||' sync is still in flight';
  end if;

  select tg_call_function(
    'metrc-sync?endpoints='||w.endpoint||'&license='||w.licence
    ||'&winStart='||to_char(w.win_start at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ||'&winEnd='  ||to_char(w.win_end   at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  ) into req;

  update metrc_backfill_window
     set status='running', attempted_at=now(), attempts=attempts+1,
         sync_run_id=(select max(id) from metrc_sync_runs where endpoint like w.endpoint||'%')
   where id=w.id;

  return format('fired %s %s %s to %s (request %s)', w.endpoint, w.licence,
                w.win_start::date, w.win_end::date, req);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_metrc_dispatch()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r metrc_scan_schedule; t time; sched timestamptz; fired text[] := '{}';
begin
  for r in select * from metrc_scan_schedule where enabled loop
    foreach t in array r.run_times loop
      sched := ((now() at time zone r.timezone)::date + t) at time zone r.timezone;
      if now() >= sched and (r.last_run_at is null or r.last_run_at < sched) then
        perform tg_metrc_fire(r, 'scheduled', null);
        fired := fired || r.job_name;
        exit;
      end if;
    end loop;
  end loop;
  return case when cardinality(fired)=0 then 'nothing due'
              else 'fired: ' || array_to_string(fired, ', ') end;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_metrc_fire(p_job metrc_scan_schedule, p_trigger text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare url text; lic text; allowed_eps text; skipped text[] := '{}';
        anon text; hdr jsonb;
begin
  -- FIXED 7 Aug 2026 (Agent D, live outage): every scheduled call to an Edge Function
  -- must carry Authorization: Bearer <anon>. The Supabase gateway checks a bearer token
  -- BEFORE the function's own x-admin-key is ever seen. metrc-sync was redeployed as v15
  -- at 11:31 UTC with verify_jwt=true; from that moment every dispatch from this function
  -- returned 401 UNAUTHORIZED_NO_AUTH_HEADER and produced no sync run, while
  -- metrc_scan_schedule.last_result still read 'dispatched'. Sync was dead ~5 hours and
  -- no check noticed, because nothing compares metrc_scan_log against metrc_sync_runs.
  -- Pattern copied verbatim from tg_call_function, which already did this correctly.
  select value into anon from integration_secrets where name = 'SUPABASE_ANON_KEY';
  if anon is null then
    raise exception 'SUPABASE_ANON_KEY is not stored in integration_secrets. Every '
      'scheduled Edge Function call needs it: the gateway checks a bearer token before '
      'the function''s own admin key is ever seen.';
  end if;

  hdr := jsonb_build_object(
           'x-admin-key', (select value from integration_secrets where name = 'TG_ADMIN_KEY'),
           'Authorization', 'Bearer ' || anon,
           'Content-Type', 'application/json');

  if p_job.job_name = 'deliveries' then
    perform net.http_post(
      url := 'https://fxetuqjryttnypgepsru.supabase.co/functions/v1/metrc-reference-sync?mode=deliveries&limit=60',
      headers := hdr, body := '{}'::jsonb, timeout_milliseconds := 300000);

  elsif p_job.job_name = 'lookups' then
    perform net.http_post(
      url := 'https://fxetuqjryttnypgepsru.supabase.co/functions/v1/metrc-reference-sync?mode=reference',
      headers := hdr, body := '{}'::jsonb, timeout_milliseconds := 300000);

  else
    -- One call per licence, carrying only the endpoints that licence can actually serve.
    -- Default is ALLOW: an endpoint is skipped only where a row explicitly says false,
    -- so a missing policy row can never silently stop a real sync.
    foreach lic in array array['MC281714','MP281909'] loop
      select string_agg(e, ',') into allowed_eps
      from unnest(string_to_array(p_job.endpoints, ',')) e
      where not exists (select 1 from metrc_endpoint_capability c
                        where c.licence = lic and c.endpoint = btrim(e) and not c.allowed);

      if allowed_eps is null then
        skipped := skipped || (lic || ': every endpoint in this job is unavailable to it');
        continue;
      end if;

      url := 'https://fxetuqjryttnypgepsru.supabase.co/functions/v1/metrc-sync?endpoints='
             || allowed_eps || '&license=' || lic;
      perform net.http_post(url := url, headers := hdr, body := '{}'::jsonb,
                            timeout_milliseconds := 300000);
    end loop;
  end if;

  update metrc_scan_schedule
     set last_run_at = now(),
         last_result = 'dispatched (' || p_trigger || ')'
           || case when cardinality(skipped) > 0
                   then ' — skipped ' || array_to_string(skipped, '; ') else '' end
   where id = p_job.id;

  insert into metrc_scan_log (job_name, trigger_type, triggered_by, outcome)
  values (p_job.job_name, p_trigger, p_actor, 'dispatched');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_metrc_nightly()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l record; eps text; sent int := 0; skipped text := '';
begin
  for l in select licence from licence_profile order by display_order loop
    eps := array_to_string(f_allowed_endpoints(l.licence), ',');
    if eps = '' then skipped := skipped || l.licence || ' '; continue; end if;
    perform tg_call_function('metrc-sync?full=1&license=' || l.licence || '&endpoints=' || eps);
    sent := sent + 1;
  end loop;
  insert into metrc_sync_runs (license, endpoint, records, status, finished_at, note)
  values ('both', 'nightly full (scoped)', sent, 'ok', now(),
          'Asked each licence only for endpoints it is licensed to answer. Skipped: '
          || coalesce(nullif(skipped,''), 'none'));
  return jsonb_build_object('ok', true, 'licences_synced', sent, 'skipped', skipped);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_metrc_scan_now(p_job_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r metrc_scan_schedule; v_role app_role; mins numeric; failed boolean;
begin
  select role into v_role from app_users where user_id = auth.uid();
  if v_role is null or v_role <> all (array['owner'::app_role,'executive'::app_role]) then
    return jsonb_build_object('ok', false,
      'error', 'Administrator access required. Scanning Metrc on demand is limited to owner and executive accounts.');
  end if;

  select * into r from metrc_scan_schedule where job_name = p_job_name;
  if not found then
    return jsonb_build_object('ok', false, 'error', format('No scan group named %L.', p_job_name));
  end if;
  if not r.enabled then
    return jsonb_build_object('ok', false,
      'error', format('The %s scan is switched off. Reason on record: %s', r.job_name, coalesce(r.description,'none given')));
  end if;

  -- did the previous run fail? a failure is always retryable
  select exists (select 1 from metrc_sync_runs s
                  where s.status <> 'ok' and s.started_at >= coalesce(r.last_run_at, now()-interval '1 day'))
    into failed;

  mins := extract(epoch from (now() - coalesce(r.last_run_at, now()-interval '999 days')))/60;
  if mins < r.min_gap_minutes and not failed then
    return jsonb_build_object('ok', false, 'throttled', true,
      'error', format('%s was pulled %s minutes ago. Metrc is not scanned again within %s minutes unless the last attempt failed.',
                      initcap(r.job_name), round(mins), r.min_gap_minutes),
      'last_pulled', r.last_run_at,
      'next_allowed', r.last_run_at + make_interval(mins => r.min_gap_minutes));
  end if;

  perform tg_metrc_fire(r, 'manual', auth.uid());
  return jsonb_build_object('ok', true,
    'message', format('%s scan started%s.', initcap(r.job_name),
                      case when failed then ' (previous attempt failed, so the wait was waived)' else '' end));
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_near_miss(p_columns text[])
 RETURNS TABLE(report_key text, title text, matched integer, needed integer, missing text[])
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select t.report_key, t.title,
    (select count(*)::int from unnest(t.signature_cols) s
      where exists (select 1 from unnest(p_columns) c where lower(btrim(c)) = lower(btrim(s)))),
    array_length(t.signature_cols,1),
    (select array_agg(s) from unnest(t.signature_cols) s
      where not exists (select 1 from unnest(p_columns) c where lower(btrim(c)) = lower(btrim(s))))
  from metrc_report_types t
  order by (select count(*) from unnest(t.signature_cols) s
             where exists (select 1 from unnest(p_columns) c where lower(btrim(c)) = lower(btrim(s))))::numeric
           / array_length(t.signature_cols,1) desc
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_nightly_integrity_check()
 RETURNS TABLE(check_name text, result text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_fail int; v_dis int; v_xdis int; d text;
begin
  insert into watchdog_runs default values returning id into v_run;

  select count(*) into v_fail from tg_reconcile_tiles() t where t.verdict = 'FAIL';
  select count(*) into v_dis  from tg_reconcile_tiles() t where t.verdict = 'DISAGREES';
  select count(*) into v_xdis from v_cross_source_reconciliation x where x.verdict like 'DISAGREES%';

  if v_fail > 0 then
    select string_agg(t.department||' / '||t.kpi, '; ') into d from tg_reconcile_tiles() t where t.verdict='FAIL';
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run,'tiles_with_no_evidence','critical',
      v_fail||' tile(s) claim a figure with no records behind it',
      'mv_department_dashboard','Whoever owns the tile','Since the tile was added',
      'Rule C1: a tile is a CLAIM and is worthless without the items behind it. Rule C2: a total that cannot be reconciled is a bug, not a rounding difference. A tile asserting a number that opens to nothing is the platform lying with confidence.',
      'The nightly integrity check counted rows in each tile''s drill relation.',
      'Either point the drill at the records that produce the number, or remove the tile until it can prove itself.',
      d, v_fail, 'settings','tile no evidence reconciliation')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  if v_dis > 0 then
    select string_agg(t.department||' / '||t.kpi||' ('||t.tile_value||' vs '||t.drill_rows||' rows)', '; ')
      into d from tg_reconcile_tiles() t where t.verdict='DISAGREES';
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run,'tiles_disagree_with_drill','elevated',
      v_dis||' countable tile(s) do not equal the row count behind them',
      'mv_department_dashboard','Whoever owns the tile','Since the tile or its drill last changed',
      'Either the drill is a superset needing a declared filter, or it points at the wrong records. On 7 Aug "Harvests dried too long" was CORRECT at 248 and drilled to 56 rows about pull scheduling - a different subject entirely.',
      'The nightly integrity check compared each countable tile to rows in its drill relation.',
      'Check which side is wrong before changing either. A mismatch is NOT proof the tile is wrong - in the one case investigated it was the drill that was misdirected.',
      d, v_dis, 'settings','tile drill disagrees')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  if v_xdis > 0 then
    select string_agg(x.fact||': '||x.overlap_a||' vs '||x.overlap_b, '; ')
      into d from v_cross_source_reconciliation x where x.verdict like 'DISAGREES%';
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run,'cross_source_disagreement','critical',
      v_xdis||' fact(s) have two different values in two independent sources',
      'v_cross_source_reconciliation','Whoever owns the source','Since one source last changed',
      'The same fact cannot have two values on the same population. One source is wrong and every figure derived from it is suspect.',
      'The nightly integrity check compared each fact across two sources, with units normalised first and the comparison restricted to the population both cover.',
      'Settle which source is authoritative and record it in source_precedence. Do NOT average them.',
      d, v_xdis, 'settings','cross source disagreement')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  return query
  select 'tiles with no evidence (rule C1)'::text, case when v_fail=0 then 'PASS' else 'FAIL' end::text, (v_fail::text||' tile(s)')::text
  union all
  select 'tiles disagreeing with their drill'::text, case when v_dis=0 then 'PASS' else 'REVIEW' end::text, (v_dis::text||' tile(s)')::text
  union all
  select 'cross-source value disagreements'::text, case when v_xdis=0 then 'PASS' else 'FAIL' end::text, (v_xdis::text||' fact(s)')::text;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_nightly_platform_check()
 RETURNS TABLE(invariant text, expected text, actual text, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run bigint;
  v_tables int; v_views int; v_mv int; v_mv_bad int; v_cron int; v_cron_bad int;
  v_cron_bad_24h int; v_cron_names text;
  v_nav int; v_nav_broken int; v_pol int; v_no_rls int;
  v_anon_rel int; v_anon_fn int; v_anon_wr int; v_mutable int;
  v_oq int; v_gl int; v_tiles int; v_no_target int; v_users int; v_emps int;
begin
  select count(*) into v_tables from pg_tables where schemaname='public';
  select count(*) into v_views  from pg_views  where schemaname='public';
  select count(*) into v_mv     from pg_matviews where schemaname='public';
  select count(*) into v_mv_bad from pg_matviews where schemaname='public' and not ispopulated;
  select count(*) into v_cron   from cron.job;

  /* CORRECTED 8 Aug 2026: only a genuinely FAILED latest run counts. This previously read
     d.status <> 'succeeded', which counted every job that happened to be mid-flight at the
     instant of the snapshot. The 06:40 run is exactly when the nightly jobs cluster, so it
     reported 8 jobs failing when none had failed. */
  select count(*) into v_cron_bad from cron.job j
    join (select jobid, max(start_time) mt from cron.job_run_details group by 1) l on l.jobid=j.jobid
    join cron.job_run_details d on d.jobid=j.jobid and d.start_time=l.mt
    where d.status = 'failed';

  /* ADDED 8 Aug 2026 — the worse half. The old check only ever inspected each job's LATEST
     run, so refresh-tower-inventory timing out on 7 of 48 runs read as healthy every time
     its most recent run happened to pass. */
  select count(distinct j.jobname), string_agg(distinct j.jobname, ', ')
    into v_cron_bad_24h, v_cron_names
  from cron.job j
  join cron.job_run_details d on d.jobid=j.jobid
  where d.status='failed' and d.start_time > now() - interval '24 hours';
  v_cron_bad_24h := coalesce(v_cron_bad_24h, 0);

  select count(*) into v_nav from nav_registry where enabled;
  select count(*) into v_nav_broken from nav_registry nr
    where nr.enabled and coalesce(nr.table_ref,'') <> ''
      and not exists (select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
                      where n.nspname='public' and c.relname=nr.table_ref and c.relkind in ('r','v','m'));
  select count(*) into v_pol from pg_policy p join pg_class c on c.oid=p.polrelid
    join pg_namespace n on n.oid=c.relnamespace and n.nspname='public';
  select count(*) into v_no_rls from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relkind='r' and not c.relrowsecurity;
  select count(*) into v_anon_rel from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relkind in ('r','v','m') and has_table_privilege('anon',c.oid,'SELECT');
  select count(*) into v_anon_fn from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and has_function_privilege('anon',p.oid,'EXECUTE')
      and not exists (select 1 from pg_depend d where d.objid=p.oid and d.classid='pg_proc'::regclass and d.deptype='e');
  select count(*) into v_anon_wr from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prosecdef and has_function_privilege('anon',p.oid,'EXECUTE')
      and not exists (select 1 from pg_depend d where d.objid=p.oid and d.classid='pg_proc'::regclass and d.deptype='e')
      and pg_get_functiondef(p.oid) ~* '(insert into|update |delete from|refresh materialized)';
  select count(*) into v_mutable from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prosecdef and p.proconfig is null
      and not exists (select 1 from pg_depend d where d.objid=p.oid and d.classid='pg_proc'::regclass and d.deptype='e');
  select count(*) into v_oq from open_questions where coalesce(answer,'') = '';
  select count(*) into v_gl from golive_items where coalesce(status::text,'') not in ('done','complete','closed');
  select count(*) into v_tiles from mv_department_dashboard;
  select greatest(v_tiles - (select count(*) from kpi_targets), 0) into v_no_target;
  select count(*) into v_users from app_users;
  select count(*) into v_emps from employees where status::text = 'active';

  insert into platform_state (base_tables, views, matviews, matviews_unpopulated, cron_jobs,
    cron_failing, cron_failing_24h, nav_enabled, nav_broken, policies, tables_without_rls,
    anon_relations, anon_functions, anon_writing_functions, secdef_mutable_path,
    open_questions_unanswered, golive_open, tiles_total, tiles_without_target, app_users,
    active_employees, notes)
  values (v_tables, v_views, v_mv, v_mv_bad, v_cron, v_cron_bad, v_cron_bad_24h, v_nav,
    v_nav_broken, v_pol, v_no_rls, v_anon_rel, v_anon_fn, v_anon_wr, v_mutable, v_oq, v_gl,
    v_tiles, v_no_target, v_users, v_emps, 'tg_nightly_platform_check');

  insert into watchdog_runs default values returning id into v_run;

  if v_anon_rel > 0 or v_anon_fn > 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run, 'anon_surface_reopened', 'critical',
      'Anonymous access has reopened: '||v_anon_rel||' relation(s) and '||v_anon_fn||' function(s) reachable without signing in',
      'The public schema, over the REST API', 'Whoever created the object, and the watchdog',
      'Since the object was created',
      'anon is every anonymous visitor - the publishable key ships in the JavaScript bundle, so anything anon can reach is effectively public. On 7 Aug 2026 this exposed customers, manifests and wholesale figures, and 33 functions that write.',
      'The nightly platform check counted objects anon holds SELECT or EXECUTE on, excluding extension-owned functions.',
      'Revoke from PUBLIC as well as anon - revoking from anon alone is a no-op while PUBLIC holds the privilege. Then run supabase/checks/anon_exposure.sql to confirm zero.',
      'anon relations '||v_anon_rel||', anon functions '||v_anon_fn||', of which writing '||v_anon_wr,
      v_anon_rel + v_anon_fn, 'settings', 'anon exposure security')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  if v_no_rls > 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run, 'tables_without_rls', 'critical',
      v_no_rls||' public table(s) have row-level security switched off',
      'The public schema', 'Whoever created the table', 'Since the table was created',
      'A table with RLS off is protected only by its privileges. New tables arrive with RLS off by default, so this happens by omission - on 7 Aug it left the flag-decision record open to forgery by any signed-in user.',
      'The nightly platform check counted tables where relrowsecurity is false.',
      'alter table <name> enable row level security, then mirror an existing sibling: read for authenticated, write for owner or executive.',
      v_no_rls||' table(s)', v_no_rls, 'settings', 'rls disabled security')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  if v_nav_broken > 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run, 'nav_points_at_missing_relation', 'elevated',
      v_nav_broken||' menu item(s) point at a view or table that does not exist',
      'nav_registry', 'Whoever dropped or renamed the relation', 'Since it was dropped or renamed',
      'The page renders empty rather than erroring, so it looks like there is no data when the page is broken. Laboratory Turnaround pointed at a view that never existed and was blank from the day it was built.',
      'The nightly platform check joined every enabled nav_registry.table_ref to pg_class.',
      'Repoint the entry at the real relation, or disable it until the view exists.',
      v_nav_broken||' of '||v_nav||' enabled entries', v_nav_broken, 'settings', 'nav broken missing view')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  /* ADDED 8 Aug 2026. The check recorded a cron number and raised nothing, so an
     intermittently failing job produced no finding and no owner ever saw it. */
  if v_cron_bad_24h > 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run, 'cron_jobs_failing', 'elevated',
      v_cron_bad_24h||' scheduled job(s) failed at least once in the last 24 hours: '||coalesce(v_cron_names,'unknown'),
      'cron.job_run_details', 'Whoever owns the job',
      'First failure inside the last 24 hours',
      'These jobs refresh dashboards, reconcile stock and record lab turnarounds. A job that fails intermittently leaves figures quietly stale rather than visibly broken, so nobody notices. refresh-tower-inventory timed out on 7 of 48 runs on 7-8 Aug 2026 and the old check called it healthy every time, because it only ever inspected the most recent run.',
      'Counted distinct jobs with a run of status failed inside 24 hours, rather than only the latest run of each job.',
      'Read the return_message on the failed runs. A statement timeout means the job needs its query optimised or its statement_timeout raised - not a retry.',
      v_cron_bad_24h||' job(s) failing intermittently; '||v_cron_bad||' currently failing on their latest run, of '||v_cron||' scheduled',
      v_cron_bad_24h, 'settings', 'cron job failing scheduled timeout')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity=excluded.severity, what=excluded.what, the_arithmetic=excluded.the_arithmetic,
      record_count=excluded.record_count, run_id=excluded.run_id;
  end if;

  return query
  select 'anon-readable relations','0',v_anon_rel::text, case when v_anon_rel=0 then 'PASS' else 'FAIL' end union all
  select 'anon-executable functions','0',v_anon_fn::text, case when v_anon_fn=0 then 'PASS' else 'FAIL' end union all
  select 'anon functions that WRITE','0',v_anon_wr::text, case when v_anon_wr=0 then 'PASS' else 'FAIL' end union all
  select 'tables without RLS','0',v_no_rls::text, case when v_no_rls=0 then 'PASS' else 'FAIL' end union all
  select 'SECDEF with mutable search_path','0',v_mutable::text, case when v_mutable=0 then 'PASS' else 'FAIL' end union all
  select 'nav entries pointing nowhere','0',v_nav_broken::text, case when v_nav_broken=0 then 'PASS' else 'FAIL' end union all
  select 'matviews unpopulated','0',v_mv_bad::text, case when v_mv_bad=0 then 'PASS' else 'FAIL' end union all
  select 'cron jobs failing right now','0',v_cron_bad::text, case when v_cron_bad=0 then 'PASS' else 'WATCH' end union all
  select 'cron jobs failing in last 24h','0',v_cron_bad_24h::text, case when v_cron_bad_24h=0 then 'PASS' else 'WATCH' end union all
  select 'tiles with no owner-set target','0',v_no_target::text, case when v_no_target=0 then 'PASS' else 'WATCH' end union all
  select 'unanswered owner questions','0',v_oq::text, case when v_oq=0 then 'PASS' else 'WATCH' end union all
  select 'staff without an account','0',greatest(v_emps-v_users,0)::text, case when v_emps-v_users<=0 then 'PASS' else 'WATCH' end;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_order_no()
 RETURNS text
 LANGUAGE sql
AS $function$ select 'TG-' || to_char(now(),'YYYY') || '-' || lpad(nextval('tg_order_seq')::text, 4, '0') $function$
;
CREATE OR REPLACE FUNCTION public.tg_override_raises_metrc_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tid uuid;
begin
  if new.metrc_sourced and new.active and new.metrc_task_id is null then
    insert into metrc_corrections
      (title, urgency, what_is_wrong, why_it_matters, how_to_fix_in_metrc,
       packages_affected, assigned_to, raised_by, first_seen)
    values (
      'OS override on '||new.target_table||' — '||new.field_name||' for '||new.row_key,
      'normal',
      'The OS now shows '||coalesce(new.new_value,'(blank)')||' for '||new.field_name
        ||' on '||new.row_key||'. Metrc still shows '||coalesce(new.old_value,'(blank)')||'. Reason given: '||new.reason,
      'Metrc is the legal record. Until it is corrected there, the state''s record and ours disagree, '
        ||'and any inspection reads Metrc.',
      'Locate '||new.row_key||' in Metrc and correct '||new.field_name||' to '||coalesce(new.new_value,'(blank)')
        ||'. If the record is finished or closed it must be reopened first. '
        ||'DO NOT clear this task until Metrc itself shows the corrected value.',
      new.row_key, 'Vincent', coalesce(new.set_by_name,'OS override'), current_date)
    returning id into tid;
    update tg_overrides set metrc_task_id = tid where id = new.id;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_pending_coa(p_limit integer DEFAULT 200)
 RETURNS TABLE(document_file_id text, package_tag text, license text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select distinct on (r.document_file_id)
         r.document_file_id::text, r.package_tag, r.license
  from metrc_lab_results r
  where r.document_file_id is not null
    and not exists (select 1 from metrc_documents d
                    where d.doc_type = 'coa'
                      and d.metrc_id = r.document_file_id::text
                      and d.storage_path is not null)
  order by r.document_file_id, r.package_tag
  limit p_limit;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_pending_manifest(p_limit integer DEFAULT 200)
 RETURNS TABLE(metrc_id text, manifest_number text, license text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select distinct on (t.raw->>'Id') t.raw->>'Id', t.manifest_number, t.license
  from metrc_transfers t
  where t.raw->>'Id' is not null
    and not exists (select 1 from metrc_documents d
                    where d.doc_type = 'manifest'
                      and d.metrc_id = t.raw->>'Id'
                      and d.storage_path is not null)
  order by t.raw->>'Id', t.manifest_number
  limit p_limit;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_period_narrative(p_from date, p_to date)
 RETURNS TABLE(page text, section_key text, narrative text, tone text, drill text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_days int := greatest((p_to - p_from) + 1, 1);
  v_prev_from date := p_from - v_days;
  v_prev_to   date := p_from - 1;
begin
  return query
  with cur as (
    select count(*) as harvests,
           count(*) filter (where not is_fresh_frozen and dry_days_to_first_package is not null) as scored,
           count(*) filter (where not is_fresh_frozen and dry_days_to_first_package > 14) as too_long,
           round(avg(dry_days_to_first_package) filter (where not is_fresh_frozen),1) as avg_days,
           count(*) filter (where is_fresh_frozen) as ff
    from mv_harvest_dry_stats where harvest_started_date between p_from and p_to
  ),
  prev as (
    select round(avg(dry_days_to_first_package) filter (where not is_fresh_frozen),1) as avg_days,
           count(*) filter (where not is_fresh_frozen and dry_days_to_first_package is not null) as scored
    from mv_harvest_dry_stats where harvest_started_date between v_prev_from and v_prev_to
  )
  select 'cultivation', 'harvests_period',
    case when c.harvests = 0 then
      format('No harvests were cut between %s and %s. The prior %s days had %s.',
             to_char(p_from,'DD Mon'), to_char(p_to,'DD Mon'), v_days, coalesce(p.scored,0))
    else
      format('%s harvests cut in this window (%s fresh-frozen). Of the %s dry harvests scored, %s blew the 14-day packaging window; the average was %s days%s.',
        c.harvests, c.ff, c.scored, c.too_long, coalesce(c.avg_days::text,'—'),
        case when p.avg_days is not null and c.avg_days is not null then
          format(' — %s than the prior %s days'' %s',
                 case when c.avg_days < p.avg_days then 'better' when c.avg_days > p.avg_days then 'worse' else 'level with' end,
                 v_days, p.avg_days)
        else '' end)
    end,
    case when c.too_long > 0 then 'bad' else 'good' end, 'dry_time_discipline'
  from cur c cross join prev p;

  return query
  with cur as (
    select count(*) filter (where observed_at::date between p_from and p_to) as raised,
           count(*) filter (where cleared_at::date  between p_from and p_to) as cleared
    from watchdog_findings
  ),
  prev as (
    select count(*) filter (where observed_at::date between v_prev_from and v_prev_to) as raised
    from watchdog_findings
  )
  select 'command', 'findings_period',
    format('%s findings raised and %s cleared in this window — the queue %s. The prior %s days raised %s. Every disagreement becomes a named finding within the hour, so a rising count means more found, not necessarily more broken.',
           c.raised, c.cleared,
           case when c.cleared > c.raised then 'shrank' when c.cleared < c.raised then 'grew' else 'held level' end,
           v_days, p.raised),
    case when c.cleared >= c.raised then 'good' else 'bad' end, 'finding_causes'
  from cur c cross join prev p;

  return query
  with pop as (
    select (p2.raw->>'ReceivedDateTime')::date as recv_on,
           f_to_pounds(coalesce(nullif(p2.raw->>'ReceivedQuantity','')::numeric, p2.quantity),
                       coalesce(nullif(p2.raw->>'ReceivedUnitOfMeasureAbbreviation',''), p2.uom)) as lb
    from metrc_packages p2
    where coalesce(p2.raw->>'ReceivedFromManifestNumber','') <> ''
      and coalesce(p2.raw->>'ItemFromFacilityLicenseNumber','') not in ('MC281714','MP281909','')
      and not exists (select 1 from counterparty_role cr
                       where cr.counts_as_purchase = false
                         and cr.facility_name = p2.raw->>'ReceivedFromFacilityName')
      and (p2.raw->>'ReceivedDateTime')::date between v_prev_from and p_to
  ),
  cur as (select count(*) as tags, round(sum(lb),1) as lb from pop where recv_on between p_from and p_to),
  prev as (select round(sum(lb),1) as lb from pop where recv_on between v_prev_from and v_prev_to)
  select 'finance', 'third_party_period',
    case when c.tags = 0 then
      format('No third-party material was received between %s and %s%s.',
             to_char(p_from,'DD Mon'), to_char(p_to,'DD Mon'),
             case when coalesce(p.lb,0) > 0 then format(' — the prior %s days brought in %s lb', v_days, p.lb) else '' end)
    else
      format('%s third-party packages received, %s lb%s. Cost basis remains declared transfer price, not cash evidence.',
             c.tags, c.lb,
             case when coalesce(p.lb,0) > 0 then format(' — against %s lb in the prior %s days', p.lb, v_days) else '' end)
    end,
    'info', 'third_party_forensic'
  from cur c cross join prev p;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_post_reconciliation(p_run uuid, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record; t record; run record;
  v_applied int := 0; v_kept int := 0; v_corrections int := 0; v_pending int;
  where_sql text; set_sql text; i int;
begin
  if coalesce(btrim(p_by),'') = '' then
    raise exception 'Who is posting? A posting with no name attached is not a decision.';
  end if;

  select * into run from import_reconciliation_run where id = p_run;
  if not found then raise exception 'No reconciliation run %.', p_run; end if;
  if run.posted_at is not null then
    raise exception 'Run % was already posted on % by %. Unpost it first.',
      p_run, run.posted_at::date, run.posted_by;
  end if;

  select * into t from metrc_report_types where report_key = run.report_key;

  for r in
    select * from import_reconciliation
     where run_id = p_run and outcome = 'differs'
       and decision in ('accept_file','keep_ours')
       and decided_at is not null and posted_at is null
  loop
    -- Rebuild the row's identity from its key. row_key is the key columns joined
    -- by '|', in the order the report type declares them.
    where_sql := '';
    for i in 1 .. coalesce(array_length(t.key_cols,1), 0) loop
      where_sql := where_sql || case when i > 1 then ' and ' else '' end
                || format('%I = %L', t.key_cols[i], split_part(r.row_key, '|', i));
    end loop;
    if where_sql = '' then
      raise exception 'Report % declares no key columns, so a row cannot be identified.', run.report_key;
    end if;

    if r.decision = 'accept_file' then
      -- Taking Metrc's figure. We are moving TOWARDS the state record, so this
      -- creates no divergence and needs no correction raised against Metrc.
      execute format('update %I set %I = %L where %s',
                     r.target_table, r.field_name, r.value_in_the_file, where_sql);
      insert into tg_overrides (target_table, row_key, field_name, old_value, new_value,
                                reason, set_by, set_by_name, metrc_sourced)
      values (r.target_table, r.row_key, r.field_name, r.value_we_hold, r.value_in_the_file,
              'Accepted from the ' || run.report_key || ' import of ' || coalesce(run.file_name,'(unnamed file)')
              || '. ' || coalesce(r.agent_reasoning, ''), auth.uid(), p_by, true);
      v_applied := v_applied + 1;

    else
      -- Keeping ours means DELIBERATELY holding a figure that Metrc contradicts.
      -- Rule D2: never correct a Metrc problem only in this platform. The override
      -- makes our value stick against future syncs; the correction makes sure the
      -- divergence is visible and cannot be forgotten. Both, or neither.
      insert into tg_overrides (target_table, row_key, field_name, old_value, new_value,
                                reason, set_by, set_by_name, metrc_sourced)
      values (r.target_table, r.row_key, r.field_name, r.value_in_the_file, r.value_we_hold,
              'Kept our figure against the ' || run.report_key || ' import. '
              || coalesce(r.agent_reasoning, ''), auth.uid(), p_by, false);

      insert into metrc_corrections
        (title, what_is_wrong, why_it_matters, how_to_fix_in_metrc, packages_affected,
         raised_on, raised_by, fixed_in_metrc, urgency, first_seen, last_verified)
      values (
        'Metrc and this platform hold different values for ' || r.field_name || ' on ' || r.row_key,
        'The ' || run.report_key || ' export says ' || coalesce(r.value_in_the_file,'(blank)')
          || '; this platform holds ' || coalesce(r.value_we_hold,'(blank)')
          || '. ' || p_by || ' reviewed it and chose to keep our figure.',
        'Metrc is the legal record. Holding a different value here without fixing it there means the two diverge permanently and silently, and only this row would ever show it.',
        'Check the record in Metrc against the evidence used to make this decision, and correct Metrc so the two agree.',
        r.row_key, current_date, p_by, false, 'normal', current_date, current_date);
      v_corrections := v_corrections + 1;
      v_kept := v_kept + 1;
    end if;

    update import_reconciliation set posted_at = now() where id = r.id;
  end loop;

  select count(*) into v_pending from import_reconciliation
   where run_id = p_run and outcome = 'differs'
      and (decision is null or decision = 'pending');

  -- The run closes only when nothing is left undecided. An issue must not clear
  -- itself, and a half-decided run that reads as posted would do exactly that.
  if v_pending = 0 then
    update import_reconciliation_run
       set posted_at = now(), posted_by = p_by,
           note = coalesce(note || ' · ', '') || 'Posted by ' || p_by || '.'
     where id = p_run;
  end if;

  return jsonb_build_object('ok', true,
    'accepted_from_file', v_applied, 'kept_ours', v_kept,
    'metrc_corrections_raised', v_corrections, 'still_undecided', v_pending,
    'run_closed', v_pending = 0,
    'note', case when v_pending > 0
      then v_pending || ' row(s) are still undecided, so the run stays open. It closes when every difference has been decided.'
      else 'Every difference was decided and the run is closed.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_probe_view_invoker(p_views text[], p_uid uuid, p_cap integer DEFAULT 5001)
 RETURNS TABLE(view_name text, owner_rows bigint, invoker_rows bigint, verdict text, note text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v text;
  v_owner bigint; v_invoker bigint; v_verdict text; v_note text;
begin
  foreach v in array p_views loop
    v_owner := null; v_invoker := null; v_note := null;
    begin
      execute format('select count(*) from (select 1 from public.%I limit %s) s', v, p_cap) into v_owner;
      begin
        execute format('alter view public.%I set (security_invoker = true)', v);
        perform set_config('request.jwt.claims',
                           json_build_object('sub', p_uid::text, 'role', 'authenticated')::text, true);
        execute 'set local role authenticated';
        execute format('select count(*) from (select 1 from public.%I limit %s) s', v, p_cap) into v_invoker;
        execute 'reset role';
        raise exception using errcode = 'P0999', message = 'measured — rolling the trial flip back';
      exception
        when sqlstate 'P0999' then null;
        when others then
          v_note := 'as-user query failed: ' || sqlerrm;
      end;
      if v_note is not null then v_verdict := 'ERROR';
      elsif v_invoker = v_owner then v_verdict := 'MEASURED_SAFE';
      else v_verdict := 'MEASURED_DIFFERS';
           v_note := format('owner sees %s, signed-in user would see %s', v_owner, v_invoker);
      end if;
    exception when others then
      v_verdict := 'ERROR';
      v_note := 'owner-mode count failed: ' || sqlerrm;
    end;
    insert into view_rls_flip_log (view_name, probe_uid, owner_rows, invoker_rows, row_cap, verdict, note)
    values (v, p_uid, v_owner, v_invoker, p_cap, v_verdict, v_note);
    view_name := v; owner_rows := v_owner; invoker_rows := v_invoker; verdict := v_verdict; note := v_note;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_proposal_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'applied' and old.status not in ('approved','applied') then
    raise exception
      'Proposal % cannot go straight to applied from %. The owner approves first - that is the '
      'whole point of this register. Set status = approved with owner_note, then apply.',
      new.id, old.status;
  end if;
  if new.status in ('approved','rejected') and old.status = 'proposed' then
    if not f_caller_is_admin() then
      raise exception 'Only the owner decides a correction proposal. Agent decisions are not decisions.';
    end if;
    new.decided_at := coalesce(new.decided_at, now());
  end if;
  if new.status = 'rejected' and coalesce(btrim(new.owner_note),'') = '' then
    raise exception 'A rejection needs a reason - the next agent must know why, or it will be proposed again.';
  end if;
  if new.status = 'applied' and coalesce(btrim(new.applied_migration),'') = '' then
    raise exception 'An applied proposal must name the migration that carried it. No unsourced changes.';
  end if;
  if new.status = 'applied' then new.applied_at := coalesce(new.applied_at, now()); end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_propose_schedule(p_from date DEFAULT CURRENT_DATE, p_to date DEFAULT (CURRENT_DATE + 180), p_max_new integer DEFAULT 2, p_variety_slots integer DEFAULT 2, p_by text DEFAULT 'schedule engine'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id bigint; r record; s record;
  goal numeric := f_rule_at('harvest_goal_lb');
  need numeric; used_new integer := 0; used_variety integer := 0;
  total numeric := 0; idx integer := 0;
begin
  insert into schedule_proposals (title, covers_from, covers_to, goal_lb, proposed_by, status, rationale)
  values ('Proposed schedule '||to_char(p_from,'DD Mon')||' to '||to_char(p_to,'DD Mon YYYY'),
          p_from, p_to, goal, p_by, 'draft',
          'Built from measured strain yield on closed harvests. Favours proven strains that clear the '
          ||'yield each room needs for a '||goal||' lb pull. New strains capped at '||p_max_new
          ||'; '||p_variety_slots||' slots reserved for lower yielders so the menu stays varied. '
          ||'Nothing here is applied - it is a draft for a person to accept, edit or reject.')
  returning id into v_id;

  for r in
    select pull_no, harvest_date, upper(flower_room) as room,
           coalesce(f_rule_at('room_capacity_'||lower(flower_room)), 1050) as capacity
    from harvest_plan_2026
    where harvest_date between p_from and p_to
    order by harvest_date
  loop
    idx := idx + 1;
    need := goal * 453.592 / r.capacity;          -- g/plant this room must deliver

    select * into s from v_strain_performance sp
    where sp.status <> 'retire'
      and sp.grams_per_plant is not null
      and (sp.confidence = 'proven' or sp.grams_per_plant >= need * 1.1)
      and sp.grams_per_plant >= need
      and not exists (                             -- no repeat in the same room last time
        select 1 from schedule_proposal_lines l
        where l.proposal_id = v_id and l.room = r.room
          and l.strain = sp.strain
          and l.pull_no > r.pull_no - 8)
      and (sp.confidence <> 'UNPROVEN — too few harvests to judge' or used_new < p_max_new)
    order by
      case when sp.status='favoured' then 0 when sp.status='keep_for_variety' then 2 else 1 end,
      sp.ranking_score desc, sp.grams_per_plant desc
    limit 1;

    if s.strain is null then
      insert into schedule_proposal_lines
        (proposal_id, pull_no, harvest_date, room, room_capacity, strain, strain_basis,
         expected_g_per_plant, expected_lb, vs_goal_lb, confidence)
      values (v_id, r.pull_no, r.harvest_date, r.room, r.capacity, null,
        'NO STRAIN CLEARS THE BAR — this room needs '||round(need,1)||' g per plant to reach '
        ||goal||' lb and nothing available reaches it. Either lower the goal for this pull or accept a shortfall.',
        null, null, null, 'none available');
    else
      if s.confidence = 'UNPROVEN — too few harvests to judge' then used_new := used_new + 1; end if;
      if s.status = 'keep_for_variety' then used_variety := used_variety + 1; end if;
      total := total + round(s.grams_per_plant * r.capacity / 453.592, 1);
      insert into schedule_proposal_lines
        (proposal_id, pull_no, harvest_date, room, room_capacity, strain, strain_basis,
         expected_g_per_plant, expected_lb, vs_goal_lb, confidence)
      values (v_id, r.pull_no, r.harvest_date, r.room, r.capacity, s.strain,
        s.strain||' averages '||s.grams_per_plant||' g per plant over '||s.harvests
          ||' harvests. This room needs '||round(need,1)||' g per plant for a '||goal||' lb pull.'
          ||case when s.status='favoured' then ' Marked favoured.'
                 when s.status='keep_for_variety' then ' Kept for variety.'
                 when s.confidence like 'UNPROVEN%' then ' NEW STRAIN — counts against the cap of '||p_max_new||'.'
                 else '' end,
        s.grams_per_plant, round(s.grams_per_plant * r.capacity / 453.592, 1),
        round(s.grams_per_plant * r.capacity / 453.592 - goal, 1), s.confidence);
    end if;
  end loop;

  update schedule_proposals set projected_lb = total where id = v_id;
  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_raise_item_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_resolved int; v_new int; v_escalated int;
begin
  with gone as (
    update alert_outbox o set resolved_at = now(),
           resolved_note = 'The flag is no longer open.'
    where o.resolved_at is null
      /* OWN WHAT YOU RAISED, NOTHING ELSE. Without this line every watchdog finding,
         feed alert and digest in the outbox is closed by this job within the hour. */
      and exists (select 1 from v_item_flags f2 where f2.source = o.source)
      and not exists (select 1 from v_item_flags f
                      where f.entity_type = o.entity_type and f.entity_key = o.entity_key
                        and f.source = o.source and f.source_ref = o.source_ref)
    returning 1)
  select count(*) into v_resolved from gone;

  with matched as (
    select distinct on (f.entity_type, f.entity_key, f.source, f.source_ref, r.role, c.channel)
           f.entity_type, f.entity_key, f.source, f.source_ref, f.severity,
           f.headline, f.detail, f.why, f.what_to_do, f.raised_on,
           r.role, r.remind_every_days, c.channel,
           (current_date - f.raised_on) as days_open
    from v_item_flags f
    join item_alert_route r
      on r.active
     and f_severity_rank(f.severity) <= f_severity_rank(r.severity)
     and (r.source is null or r.source = f.source)
    cross join lateral (values ('in_app', r.notify_in_app), ('email', r.notify_email)) c(channel, enabled)
    where c.enabled
    order by f.entity_type, f.entity_key, f.source, f.source_ref, r.role, c.channel,
             (r.source is null), f_severity_rank(r.severity), r.remind_every_days
  ), candidate as (
    select m.*,
           (select max(o.created_at) from alert_outbox o
             where o.entity_type=m.entity_type and o.entity_key=m.entity_key
               and o.source=m.source and o.source_ref=m.source_ref
               and o.role=m.role and o.channel=m.channel and o.resolved_at is null) as last_open_alert,
           (select count(*) from alert_outbox o
             where o.entity_type=m.entity_type and o.entity_key=m.entity_key
               and o.source=m.source and o.source_ref=m.source_ref
               and o.role=m.role and o.channel=m.channel) as sent_before
    from matched m
  ), inserted as (
    insert into alert_outbox (entity_type, entity_key, source, source_ref, severity, role,
                              channel, reminder_number, subject, body, raised_on, days_open)
    select d.entity_type, d.entity_key, d.source, d.source_ref, d.severity, d.role,
           d.channel, d.sent_before + 1,
           case when d.sent_before = 0 then upper(d.severity) || ': ' || d.headline
                when d.days_open = 0   then 'REOPENED: ' || d.headline
                else 'STILL OPEN (' || (d.sent_before + 1) || ' reminders, '
                     || d.days_open || ' days): ' || d.headline end,
           d.headline || E'\n\n' || d.detail
             || E'\n\nWhy it matters: ' || d.why
             || E'\n\nWhat to do: ' || d.what_to_do
             || E'\n\nItem: ' || d.entity_type || ' ' || d.entity_key
             || '   Raised: ' || d.raised_on || ' (' || d.days_open || ' days open)'
             || E'\nThis will keep coming back until someone records a decision - fix it, or say why not.',
           d.raised_on, d.days_open
    from candidate d
    where d.last_open_alert is null
       or d.last_open_alert < now() - make_interval(days => d.remind_every_days)
    returning 1)
  select count(*) into v_new from inserted;

  with esc as (
    insert into alert_outbox (entity_type, entity_key, source, source_ref, severity, role,
                              channel, escalated_from, reminder_number, subject, body,
                              raised_on, days_open)
    select distinct on (f.entity_type, f.entity_key, f.source, f.source_ref, r.escalate_to)
           f.entity_type, f.entity_key, f.source, f.source_ref, f.severity, r.escalate_to,
           'in_app', r.role, 1,
           'ESCALATED after ' || (current_date - f.raised_on) || ' days: ' || f.headline,
           'This was raised with ' || r.role || ' ' || (current_date - f.raised_on)
             || ' days ago and is still open.' || E'\n\n' || f.detail
             || E'\n\nWhat to do: ' || f.what_to_do
             || E'\n\nItem: ' || f.entity_type || ' ' || f.entity_key,
           f.raised_on, current_date - f.raised_on
    from v_item_flags f
    join item_alert_route r
      on r.active and f_severity_rank(f.severity) <= f_severity_rank(r.severity)
     and (r.source is null or r.source = f.source)
     and r.escalate_after_days is not null and r.escalate_to is not null
    where (current_date - f.raised_on) >= r.escalate_after_days
      and not exists (select 1 from alert_outbox o
                      where o.entity_type=f.entity_type and o.entity_key=f.entity_key
                        and o.source=f.source and o.source_ref=f.source_ref
                        and o.role=r.escalate_to and o.escalated_from = r.role
                        and o.resolved_at is null)
    returning 1)
  select count(*) into v_escalated from esc;

  return jsonb_build_object('ok', true, 'resolved', v_resolved,
                            'raised_or_reminded', v_new, 'escalated', v_escalated);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_raise_report_upload_findings(p_by text DEFAULT 'cron:report-upload-nag'::text)
 RETURNS TABLE(action text, report_key text, licence text, period_label text, days_late integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- 1. RAISE or refresh a finding for every required upload that has not arrived.
  return query
  with due as (
    select d.report_key, d.licence, d.period_label, d.title, d.cadence, d.menu_path,
           d.why_it_matters, d.what_it_adds, d.target_table, d.due_by,
           d.days_late::integer as days_late,
           case d.severity when 'critical' then 'critical'
                           when 'elevated' then 'elevated'
                           else 'watch' end as sev,
           'report_upload_overdue:'||d.report_key||':'||d.licence||':'||d.period_label as fp
    from v_report_upload_due d
    where not d.received and d.days_late > 0
  ),
  upsert as (
    insert into agent_findings
      (agent, severity, headline, detail, metric, units, scope, action, drill_to, fingerprint)
    select 'Metrc & Compliance', u.sev,
           u.title||' for '||u.licence||' ('||u.period_label||') is '||u.days_late||' days overdue',
           'WHO: whoever holds the Metrc login for '||u.licence||'. Raised by the report-upload nag. '
           || 'WHAT: the '||u.title||' export for '||u.period_label||' was due '||u.due_by
           || ' and has not been imported. Cadence: '||u.cadence||'. '
           || 'WHERE TO GET IT: Metrc > '||u.menu_path||', for licence '||u.licence||'. '
           || 'WHY IT MATTERS: '||coalesce(u.why_it_matters,'(not recorded)')||' '
           || 'WHAT IT ADDS: '||coalesce(u.what_it_adds,'(not recorded)')||' '
           || 'HOW DETECTED: v_report_upload_due, which compares the cadence against '
           || 'what actually landed in '||u.target_table||'. '
           || 'WHY THIS CANNOT BE AUTOMATED: the Metrc API does not serve this report. '
           || 'A person must export it. '
           || 'SOLUTIONS: (1) export and import it now; (2) if the cadence is wrong for this '
           || 'report, change the cadence row rather than ignoring the nag; (3) if the period '
           || 'genuinely has no data, import the empty file so the absence is on the record. '
           || 'RECOMMENDATION: (1). This finding will not clear until the file lands.',
           u.days_late, 'days', u.licence||' - '||u.period_label,
           'Export from Metrc > '||u.menu_path||' and import it',
           u.target_table, u.fp
    from due u
    where not exists (select 1 from agent_findings f
                      where f.fingerprint = u.fp and f.resolved_at is null)
    returning agent_findings.fingerprint
  )
  select 'raised'::text, d.report_key, d.licence, d.period_label, d.days_late
  from due d join upsert i on i.fingerprint = d.fp;

  -- 2. Stand the finding down once the file actually lands.
  --
  -- Deliberate judgement against rule H1, stated rather than hidden: H1 exists so a
  -- PERSON decides whether a problem is over. Here the condition is not a judgement -
  -- "the file arrived" is a mechanical fact, re-derivable from the import row, and the
  -- resolution below names that row. Requiring two agents to close a monthly upload nag
  -- would bury the real queue under clerical work. If the owner disagrees, delete this
  -- block and the findings will wait for a human.
  update agent_findings f
  set resolved_at = now(),
      resolution  = 'The file arrived: '||coalesce(d.file_name,'(no name)')||', '
                    ||coalesce(d.row_count,0)||' rows, imported '||coalesce(d.imported_at::text,'?')
                    ||'. Stood down automatically by '||p_by||' because the condition is a '
                    ||'mechanical fact, not a judgement. Re-derive with: select * from '
                    ||'v_report_upload_due where report_key='''||d.report_key
                    ||''' and licence='''||d.licence||'''.'
  from v_report_upload_due d
  where f.fingerprint = 'report_upload_overdue:'||d.report_key||':'||d.licence||':'||d.period_label
    and f.resolved_at is null
    and d.received;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_ratchet_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare x ratchet_exception%rowtype;
begin
  if tg_op = 'UPDATE' and new.baseline > old.baseline then
    select * into x from ratchet_exception
     where metric_key = new.metric_key
       and from_baseline = old.baseline
       and to_baseline = new.baseline
       and consumed_at is null
     order by approved_at limit 1;

    if not found then
      raise exception
        'Ratchet % may not rise: % -> %.', new.metric_key, old.baseline, new.baseline
        using hint = 'This number records debt. It may fall as debt is paid and may never rise. '
                     'If new debt is genuinely unavoidable, that is a decision for the owner, '
                     'recorded as such: insert a ratchet_exception naming this exact rise, why '
                     'it is unavoidable, who approved it, and the date it must fall by. There is '
                     'no other door, and disabling this trigger is not one.';
    end if;

    update ratchet_exception set consumed_at = now() where id = x.id;
    raise notice 'Ratchet % rose % -> % on exception #% approved by %, must fall by %.',
      new.metric_key, old.baseline, new.baseline, x.id, x.approved_by, x.must_fall_by;
  end if;
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_read_secret(p_key text)
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select value from app_secrets where key = p_key;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_read_user_key(p_user uuid)
 RETURNS TABLE(provider text, api_key text, local_url text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select own_key_provider, own_key,
         case when uses_local_model then local_model_url else null end
  from ai_user_access where user_id = p_user;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_reconcile_fields(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  run record; t record; fld text; spec jsonb; sql text;
  key_ours text; agreed int; differs int; needs int; summary text;
begin
  if not f_caller_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Restricted to administrators.');
  end if;
  select * into run from import_reconciliation_run where id = p_run;
  if not found then return jsonb_build_object('ok', false, 'error', 'No such reconciliation.'); end if;
  select * into t from metrc_report_types where report_key = run.report_key;
  if t.compare_map is null then
    return jsonb_build_object('ok', false,
      'error', 'No comparison map for ' || run.report_key || ', so fields cannot be compared. '
            || 'Add one to metrc_report_types.compare_map.');
  end if;

  key_ours := (select string_agg(format('coalesce(x.%I::text,'''')', k), ' || ''|'' || ')
               from unnest(t.key_cols) k);

  -- one pass per compared field: read what we hold, read what the file says,
  -- and let the agent decide which should stand.
  for fld, spec in select * from jsonb_each(t.compare_map)
  loop
    sql := format($f$
      insert into import_reconciliation (run_id, report_key, target_table, row_key, outcome,
        field_name, value_we_hold, value_in_the_file, row_from_file, file_as_of,
        difference, pct_difference, agent_recommendation, agent_reasoning, agent_confidence)
      select %1$L, %2$L, %3$L, ir.row_key,
             case when ours.v is not distinct from theirs.v then 'agreed' else 'differs' end,
             %4$L, ours.v, theirs.v, ir.row_from_file, ir.file_as_of,
             case when ours.n is not null and theirs.n is not null
                  then round(theirs.n - ours.n, 4) end,
             case when ours.n is not null and theirs.n is not null and ours.n <> 0
                  then round(100.0*(theirs.n - ours.n)/abs(ours.n), 2) end,
             rec.recommendation, rec.reasoning, rec.confidence
      from import_reconciliation ir
      join %3$I x on %5$s = ir.row_key
      cross join lateral (select x.%6$I::text as v,
                          case when x.%6$I::text ~ '^-?[0-9.]+$' then x.%6$I::numeric end as n) ours
      cross join lateral (select %7$s as v, %8$s as n) theirs
      cross join lateral (select * from f_reconcile_advice(%2$L, %4$L, ours.v, theirs.v,
                                        ours.n, theirs.n, ir.file_as_of)) rec
      where ir.run_id = %1$L and ir.outcome = 'differs' and ir.field_name is null $f$,
      p_run, run.report_key, run.target_table, fld, key_ours, fld,
      case spec->>'kind'
        when 'lb'    then format('f_rpt_lb(ir.row_from_file->>%L)::text', spec->>'from')
        when 'num'   then format('f_rpt_num(ir.row_from_file->>%L)::text', spec->>'from')
        when 'price' then format('coalesce(f_rpt_price(ir.row_from_file->>%L,''S''), f_rpt_num(ir.row_from_file->>%L))::text', spec->>'from', spec->>'from')
        when 'date'  then format('f_rpt_date(ir.row_from_file->>%L)::text', spec->>'from')
        else format('nullif(btrim(ir.row_from_file->>%L),'''')', spec->>'from') end,
      case spec->>'kind'
        when 'lb'    then format('f_rpt_lb(ir.row_from_file->>%L)', spec->>'from')
        when 'num'   then format('f_rpt_num(ir.row_from_file->>%L)', spec->>'from')
        when 'price' then format('coalesce(f_rpt_price(ir.row_from_file->>%L,''S''), f_rpt_num(ir.row_from_file->>%L))', spec->>'from', spec->>'from')
        else 'null::numeric' end);
    execute sql;
  end loop;

  -- the row-level "differs" placeholders have been replaced by field-level rows
  delete from import_reconciliation where run_id = p_run and outcome='differs' and field_name is null;

  select count(*) filter (where outcome='agreed'),
         count(*) filter (where outcome='differs'),
         count(*) filter (where outcome='differs' and agent_confidence='needs_a_person')
    into agreed, differs, needs
  from import_reconciliation where run_id = p_run and field_name is not null;

  summary := agreed || ' fields agree, ' || differs || ' differ. Of those, '
             || needs || ' need a person; the rest carry a recommendation.';
  update import_reconciliation_run set agreed=agreed, differs=differs, agent_summary=summary
  where id = p_run;

  return jsonb_build_object('ok', true, 'agreed', agreed, 'differs', differs,
    'needs_a_person', needs, 'summary', summary);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_reconcile_fields_do(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  run record; t record; fld text; spec jsonb; sql text;
  key_ours text; agreed int; differs int; needs int; summary text;
begin
  select * into run from import_reconciliation_run where id = p_run;
  if not found then return jsonb_build_object('ok', false, 'error', 'No such reconciliation.'); end if;
  select * into t from metrc_report_types where report_key = run.report_key;
  if t.compare_map is null then
    return jsonb_build_object('ok', false,
      'error', 'No comparison map for ' || run.report_key || ', so fields cannot be compared. '
            || 'Add one to metrc_report_types.compare_map.');
  end if;

  key_ours := (select string_agg(format('coalesce(x.%I::text,'''')', k), ' || ''|'' || ')
               from unnest(t.key_cols) k);

  -- one pass per compared field: read what we hold, read what the file says,
  -- and let the agent decide which should stand.
  for fld, spec in select * from jsonb_each(t.compare_map)
  loop
    sql := format($f$
      insert into import_reconciliation (run_id, report_key, target_table, row_key, outcome,
        field_name, value_we_hold, value_in_the_file, row_from_file, file_as_of,
        difference, pct_difference, agent_recommendation, agent_reasoning, agent_confidence)
      select %1$L, %2$L, %3$L, ir.row_key,
             case when ours.v is not distinct from theirs.v then 'agreed' else 'differs' end,
             %4$L, ours.v, theirs.v, ir.row_from_file, ir.file_as_of,
             case when ours.n is not null and theirs.n is not null
                  then round(theirs.n - ours.n, 4) end,
             case when ours.n is not null and theirs.n is not null and ours.n <> 0
                  then round(100.0*(theirs.n - ours.n)/abs(ours.n), 2) end,
             rec.recommendation, rec.reasoning, rec.confidence
      from import_reconciliation ir
      join %3$I x on %5$s = ir.row_key
      cross join lateral (select x.%6$I::text as v,
                          case when x.%6$I::text ~ '^-?[0-9.]+$' then x.%6$I::text::numeric end as n) ours
      cross join lateral (select %7$s as v, %8$s as n) theirs
      cross join lateral (select * from f_reconcile_advice(%2$L, %4$L, ours.v, theirs.v,
                                        ours.n, theirs.n, ir.file_as_of)) rec
      where ir.run_id = %1$L and ir.outcome = 'differs' and ir.field_name is null $f$,
      p_run, run.report_key, run.target_table, fld, key_ours, fld,
      case spec->>'kind'
        when 'lb'    then format('f_rpt_lb(ir.row_from_file->>%L)::text', spec->>'from')
        when 'num'   then format('f_rpt_num(ir.row_from_file->>%L)::text', spec->>'from')
        when 'price' then format('coalesce(f_rpt_price(ir.row_from_file->>%L,''S''), f_rpt_num(ir.row_from_file->>%L))::text', spec->>'from', spec->>'from')
        when 'date'  then format('f_rpt_date(ir.row_from_file->>%L)::text', spec->>'from')
        else format('nullif(btrim(ir.row_from_file->>%L),'''')', spec->>'from') end,
      case spec->>'kind'
        when 'lb'    then format('f_rpt_lb(ir.row_from_file->>%L)', spec->>'from')
        when 'num'   then format('f_rpt_num(ir.row_from_file->>%L)', spec->>'from')
        when 'price' then format('coalesce(f_rpt_price(ir.row_from_file->>%L,''S''), f_rpt_num(ir.row_from_file->>%L))', spec->>'from', spec->>'from')
        else 'null::numeric' end);
    execute sql;
  end loop;

  -- the row-level "differs" placeholders have been replaced by field-level rows
  delete from import_reconciliation where run_id = p_run and outcome='differs' and field_name is null;

  select count(*) filter (where outcome='agreed'),
         count(*) filter (where outcome='differs'),
         count(*) filter (where outcome='differs' and agent_confidence='needs_a_person')
    into agreed, differs, needs
  from import_reconciliation where run_id = p_run and field_name is not null;

  summary := agreed || ' fields agree, ' || differs || ' differ. Of those, '
             || needs || ' need a person; the rest carry a recommendation.';
  update import_reconciliation_run r
     set agreed = v.a, differs = v.b, agent_summary = v.c
    from (select agreed, differs, summary) v(a, b, c)
   where r.id = p_run;

  return jsonb_build_object('ok', true, 'agreed', agreed, 'differs', differs,
    'needs_a_person', needs, 'summary', summary);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_reconcile_report(p_rows jsonb, p_licence text DEFAULT NULL::text, p_as_of date DEFAULT NULL::date, p_file_name text DEFAULT NULL::text, p_stated_total integer DEFAULT NULL::integer, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cols text[]; det record; t record; run uuid; missing text[];
  key_ours text; key_file text; sql text; kept jsonb; outside int := 0;
  n_differs int; n_new int; n_outstanding int; n_fields int;
begin
  if not f_caller_is_admin() then
    return jsonb_build_object('ok', false, 'error', 'Restricted to administrators.');
  end if;
  if p_rows is null or jsonb_array_length(p_rows) = 0 then
    return jsonb_build_object('ok', false, 'error', 'No rows found in this file.');
  end if;

  select array_agg(k) into cols from jsonb_object_keys(p_rows -> 0) k;
  select * into det from tg_detect_report(cols);
  if det.report_key is null then
    return jsonb_build_object('ok', false, 'error', 'This file matches no report we know.');
  end if;
  select * into t from metrc_report_types where report_key = det.report_key;

  if t.required_cols is not null then
    select array_agg(rc) into missing from unnest(t.required_cols) rc
    where not exists (select 1 from unnest(cols) c where lower(btrim(c)) = lower(btrim(rc)));
    if missing is not null then
      return jsonb_build_object('ok', false, 'rejected', true,
        'error', 'REJECTED - missing ' || array_to_string(missing,' and ') || '.  '
                 || coalesce(t.required_cols_message,'Tick every column and export again.'));
    end if;
  end if;
  if t.key_source_cols is null then
    return jsonb_build_object('ok', false, 'error', 'No key mapping, so it cannot be reconciled.');
  end if;

  -- DATE WINDOW: a year-to-date file can be reconciled one month at a time.
  if (p_from is not null or p_to is not null) and t.date_source_col is not null then
    select coalesce(jsonb_agg(r), '[]'::jsonb) into kept
    from jsonb_array_elements(p_rows) r
    where (p_from is null or f_rpt_date(r->>t.date_source_col) >= p_from)
      and (p_to   is null or f_rpt_date(r->>t.date_source_col) <= p_to);
    outside := jsonb_array_length(p_rows) - jsonb_array_length(kept);
    p_rows := kept;
    if jsonb_array_length(p_rows) = 0 then
      return jsonb_build_object('ok', false,
        'error', 'No rows in this file fall between ' || coalesce(p_from::text,'the start')
                 || ' and ' || coalesce(p_to::text,'the end') || ', judged on its "'
                 || t.date_source_col || '" column. ' || outside || ' rows were outside the window.');
    end if;
  end if;

  insert into import_reconciliation_run (report_key, target_table, file_name, licence, as_of,
     rows_in_file, stated_total, count_check, filter_from, filter_to, rows_outside_the_window,
     agreed, differs, new_rows, outstanding)
  values (det.report_key, t.target_table, p_file_name, p_licence, p_as_of,
     jsonb_array_length(p_rows), p_stated_total,
     case when p_from is null and p_to is null
          then tg_check_row_count(p_stated_total, jsonb_array_length(p_rows) + outside,
                                  jsonb_array_length(p_rows) + outside)
          else 'Not checked against the file total - a date window was applied.' end,
     p_from, p_to, outside, 0,0,0,0)
  returning id into run;

  key_ours := (select string_agg(format('coalesce(x.%I::text,'''')', k), ' || ''|'' || ')
               from unnest(t.key_cols) k);
  key_file := (select string_agg(format('coalesce(r->>%L,'''')', s), ' || ''|'' || ')
               from unnest(t.key_source_cols) s);

  -- rows the file brings that we do not hold
  sql := format($f$
    insert into import_reconciliation (run_id, report_key, target_table, row_key, outcome,
                                       row_from_file, file_as_of)
    select %L, %L, %L, %s, 'new', r, %L
    from jsonb_array_elements($1) r
    where not exists (select 1 from %I x where %s = %s) $f$,
    run, det.report_key, t.target_table, key_file, p_as_of, t.target_table, key_ours, key_file);
  execute sql using p_rows;

  -- rows we hold that this file does not mention
  sql := format($f$
    insert into import_reconciliation (run_id, report_key, target_table, row_key, outcome, our_source)
    select %L, %L, %L, %s, 'outstanding',
           'held here, not present in this file - flagged, never deleted'
    from %I x
    where not exists (select 1 from jsonb_array_elements($1) r where %s = %s) $f$,
    run, det.report_key, t.target_table, key_ours, t.target_table, key_ours, key_file);
  execute sql using p_rows;

  select count(*) filter (where outcome='new'), count(*) filter (where outcome='outstanding')
    into n_new, n_outstanding from import_reconciliation where run_id = run;

  return jsonb_build_object('ok', true, 'run_id', run, 'report', det.report_key, 'title', det.title,
    'rows_reconciled', jsonb_array_length(p_rows), 'rows_outside_the_window', outside,
    'window', case when p_from is null and p_to is null then 'whole file'
                   else coalesce(p_from::text,'start') || ' to ' || coalesce(p_to::text,'end') end,
    'new', n_new, 'outstanding', n_outstanding,
    'note', 'NOTHING WRITTEN. Field-level comparison runs next - call tg_reconcile_fields.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_reconcile_tiles()
 RETURNS TABLE(department text, kpi text, tile_value text, unit text, drill_relation text, drill_rows text, verdict text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n bigint; v numeric;
begin
  for r in
    select m.department::text as dept, m.kpi::text as kpi, m.value as val, coalesce(m.unit,'')::text as un,
           m.drill::text as drill, n2.table_ref::text as rel
    from mv_department_dashboard m
    left join nav_registry n2 on n2.view_key = m.drill
    order by m.department, m.ord
  loop
    -- Rule C1: a tile without a drill is not finished and must not ship.
    if coalesce(r.drill,'') = '' then
      return query select r.dept, r.kpi, r.val::text, r.un, '(none)'::text, '-'::text,
        'FAIL'::text, 'No drill at all. Rule C1: a tile is a CLAIM and must open to the items behind it.'::text;
      continue;
    end if;

    if coalesce(r.rel,'') = '' or not exists (
         select 1 from pg_class c join pg_namespace ns on ns.oid=c.relnamespace
         where ns.nspname='public' and c.relname=r.rel and c.relkind in ('r','v','m')) then
      return query select r.dept, r.kpi, r.val::text, r.un, coalesce(r.rel,'(no table_ref)')::text, '-'::text,
        'UNVERIFIABLE'::text,
        'The drill goes to a screen, not a relation, so the number cannot be reconciled to rows.'::text;
      continue;
    end if;

    execute format('select count(*) from public.%I', r.rel) into n;
    v := r.val;

    -- The hard failure: the tile asserts something exists and the drill shows nothing.
    if v is not null and v <> 0 and n = 0 then
      return query select r.dept, r.kpi, r.val::text, r.un, r.rel, n::text,
        'FAIL'::text,
        'The tile claims a non-zero figure but its drill returns NO rows. Rule C2: a total that cannot be reconciled to items is a bug.'::text;
    elsif v is not null and v = 0 and n > 0 then
      return query select r.dept, r.kpi, r.val::text, r.un, r.rel, n::text,
        'REVIEW'::text,
        'The tile says zero while the drill holds rows. Either the tile filter is wrong or the drill is a superset.'::text;
    elsif r.un = '' and v = n then
      -- A countable tile whose value equals its row count is genuinely reconciled.
      return query select r.dept, r.kpi, r.val::text, r.un, r.rel, n::text,
        'RECONCILED'::text, 'Countable tile equals the row count behind it.'::text;
    elsif r.un = '' then
      return query select r.dept, r.kpi, r.val::text, r.un, r.rel, n::text,
        'DISAGREES'::text,
        'Countable tile does not equal its drill row count. Either the drill is a superset needing a declared filter, or the tile is wrong. Cannot be settled without a declared filter per metric.'::text;
    else
      return query select r.dept, r.kpi, r.val::text, r.un, r.rel, n::text,
        'NEEDS DECLARATION'::text,
        ('Tile is measured in '||r.un||', so a row count cannot verify it. Reconciliation needs a declared column and aggregate per metric.')::text;
    end if;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_record_schedule_variance(p_event_type text, p_room text, p_scheduled_date date, p_reason_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_accountable text DEFAULT NULL::text, p_corrective_action text DEFAULT NULL::text, p_resolved boolean DEFAULT NULL::boolean)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_actual date; v_cult text; v_needs_note boolean;
begin
  select sc.actual_date, sc.cultivars into v_actual, v_cult
  from v_schedule_compliance sc
  where sc.event_type = p_event_type and sc.room = p_room
    and sc.scheduled_date = p_scheduled_date
  limit 1;

  if p_reason_code is not null then
    select rc.requires_note into v_needs_note
    from reason_code_catalog rc where rc.code = p_reason_code and rc.active;
    if not found then
      raise exception
        'No active reason code "%". Pick one from reason_code_catalog — a free-text reason '
        'cannot be counted, and counting is the point.', p_reason_code;
    end if;
    if v_needs_note and length(btrim(coalesce(p_note,''))) < 10 then
      raise exception
        'Reason "%" needs a note saying what actually happened. It was chosen because the code '
        'alone does not explain it.', p_reason_code;
    end if;
  end if;

  insert into schedule_variance
    (event_type, room, cultivars, scheduled_date, actual_date, reason_code, note,
     accountable, corrective_action, resolved, recorded_by,
     resolved_by, resolved_at)
  values (p_event_type, p_room, v_cult, p_scheduled_date, v_actual, p_reason_code, p_note,
          p_accountable, p_corrective_action, coalesce(p_resolved,false),
          coalesce(current_app_role(),'unrecorded'),
          case when p_resolved then coalesce(current_app_role(),'unrecorded') end,
          case when p_resolved then now() end)
  on conflict (event_type, room, scheduled_date) do update
     set reason_code       = coalesce(excluded.reason_code, schedule_variance.reason_code),
         note              = coalesce(excluded.note, schedule_variance.note),
         accountable       = coalesce(excluded.accountable, schedule_variance.accountable),
         corrective_action = coalesce(excluded.corrective_action, schedule_variance.corrective_action),
         actual_date       = coalesce(excluded.actual_date, schedule_variance.actual_date),
         resolved          = coalesce(p_resolved, schedule_variance.resolved),
         resolved_by       = case when p_resolved then coalesce(current_app_role(),'unrecorded')
                                  else schedule_variance.resolved_by end,
         resolved_at       = case when p_resolved then now() else schedule_variance.resolved_at end,
         updated_by        = coalesce(current_app_role(),'unrecorded'),
         updated_at        = now()
  returning id into v_id;

  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_refresh_dashboards(p_by text DEFAULT 'cron'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_list   text[] := array[
    'mv_department_dashboard_base', 'mv_dept_dash_supplement', 'mv_global_management',
    'mv_harvest_dry_stats', 'mv_flow_stages', 'mv_room_board'];
  m        text;
  t0       timestamptz;
  v_ok     int := 0;
  v_fail   int := 0;
  v_failed text[] := '{}';
begin
  foreach m in array v_list loop
    t0 := clock_timestamp();
    begin
      execute format('refresh materialized view concurrently %I', m);
      insert into matview_refresh_run (matview, started_at, finished_at, ms, ok, run_by)
      values (m, t0, clock_timestamp(),
              round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int, true, p_by);
      v_ok := v_ok + 1;
    /* query_canceled EXPLICITLY. WHEN OTHERS does not include it, and a timeout is the
       only failure that has ever actually happened here. */
    exception when query_canceled or others then
      insert into matview_refresh_run (matview, started_at, finished_at, ms, ok, error, run_by)
      values (m, t0, clock_timestamp(),
              round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int,
              false, left(sqlerrm, 400), p_by);
      v_fail := v_fail + 1;
      v_failed := v_failed || m;
    end;
  end loop;

  return jsonb_build_object(
    'refreshed', v_ok, 'failed', v_fail, 'failed_views', v_failed,
    'note', case when v_fail = 0 then 'all views current'
                 else 'One or more views are STALE and the page must say so. '
                      || 'See matview_refresh_run for the error.' end);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_refresh_dashboards()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  refresh materialized view concurrently mv_department_dashboard_base;
  refresh materialized view concurrently mv_dept_dash_supplement;
  refresh materialized view concurrently mv_global_management;
  refresh materialized view concurrently mv_harvest_dry_stats;
  refresh materialized view concurrently mv_flow_stages;
  refresh materialized view concurrently mv_room_board;
  refresh materialized view concurrently mv_tag_evidence;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_refresh_harvest_links()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  refresh materialized view mv_package_harvest;
  refresh materialized view concurrently mv_harvest_pkg_rollup;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_refresh_reports()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
begin
  refresh materialized view concurrently mv_seed_to_sale;
  refresh materialized view concurrently mv_harvest_yields;
  refresh materialized view concurrently mv_strain_census;
  return 'refreshed';
exception when others then
  refresh materialized view mv_seed_to_sale;
  refresh materialized view mv_harvest_yields;
  refresh materialized view mv_strain_census;
  return 'refreshed (non-concurrent)';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_refresh_tag_evidence(p_by text DEFAULT 'cron'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t0 timestamptz := clock_timestamp();
begin
  /* No statement_timeout here. It cannot work from inside the running statement — the
     cron job sets it as its own statement before calling this. */
  begin
    refresh materialized view concurrently mv_tag_evidence;
    insert into matview_refresh_run (matview, started_at, finished_at, ms, ok, run_by)
    values ('mv_tag_evidence', t0, clock_timestamp(),
            round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int, true, p_by);
    return jsonb_build_object('ok', true,
      'ms', round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int);
  exception when query_canceled or others then
    insert into matview_refresh_run (matview, started_at, finished_at, ms, ok, error, run_by)
    values ('mv_tag_evidence', t0, clock_timestamp(),
            round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int,
            false, left(sqlerrm, 400), p_by);
    return jsonb_build_object('ok', false, 'error', left(sqlerrm, 300));
  end;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_refresh_tower()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin refresh materialized view concurrently mv_tower_counts;
exception when others then refresh materialized view mv_tower_counts; end $function$
;
CREATE OR REPLACE FUNCTION public.tg_reject_write_sql()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare bad text;
begin
  foreach bad in array array['insert','update','delete','drop','alter','truncate','grant',
                             'revoke','create','copy',';'] loop
    if position(bad in lower(new.tile_sql))  > 0
    or position(bad in lower(new.drill_sql)) > 0 then
      raise exception
        'tile_drill_contract accepts a bare SELECT only. "%" appeared in one of the expressions. '
        'This table is a measuring instrument, not a SQL runner.', bad;
    end if;
  end loop;
  if lower(ltrim(new.tile_sql))  not like 'select%'
  or lower(ltrim(new.drill_sql)) not like 'select%' then
    raise exception 'Both tile_sql and drill_sql must begin with SELECT.';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_rename_dashboard(p_key text, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if p_name is null or btrim(p_name) = '' then
    raise exception 'A dashboard needs a name.';
  end if;
  update user_dashboard set name = btrim(p_name)
   where user_id = auth.uid() and dashboard_key = p_key;
  if not found then raise exception 'You have no dashboard "%".', p_key; end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_rename_zone(p_key text, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if p_name is null or btrim(p_name) = '' then raise exception 'A zone needs a name.'; end if;
  update zone set name = btrim(p_name) where zone_key = p_key;
  if not found then raise exception 'No zone "%".', p_key; end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_report_as_of(p_stated date, p_rows jsonb, p_date_fields text[], p_uploaded timestamp with time zone)
 RETURNS TABLE(as_of date, source text)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare best date; f text; d date;
begin
  if p_stated is not null then
    return query select p_stated, 'stated by the person uploading'; return;
  end if;
  foreach f in array coalesce(p_date_fields, '{}')
  loop
    select max(f_rpt_date(r->>f)) into d from jsonb_array_elements(p_rows) r;
    if d is not null and (best is null or d > best) then best := d; end if;
  end loop;
  if best is not null then
    return query select best, 'latest event date inside the file'; return;
  end if;
  return query select p_uploaded::date, 'UPLOAD DATE - the file carried no date, so this is a guess';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_require_assertion_fixture()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not new.enabled then
    return new;                       -- a disabled assertion harms nobody
  end if;

  if coalesce(btrim(new.fixture_positive_schema),'') = '' then
    raise exception
      'Assertion % has no POSITIVE fixture. Name the schema holding a planted violation.',
      new.assertion_key
      using hint = 'The positive half is the only proof the assertion can fire at all. '
                   'Create a schema whose relations shadow production, plant the defect, '
                   'and set fixture_positive_schema.';
  end if;

  if coalesce(btrim(new.fixture_negative_schema),'') = '' then
    raise exception
      'Assertion % has no NEGATIVE fixture. Name the schema holding a legitimate case.',
      new.assertion_key
      using hint = 'A wrong label costs more than no label. All six defects in the 9 Aug '
                   'register would have been caught by the negative half alone.';
  end if;

  if coalesce(array_length(new.fixture_shadows,1),0) = 0 then
    raise exception
      'Assertion % names no shadowed relations, so a fixture could read production silently.',
      new.assertion_key
      using hint = 'List every relation the fixture schemas must provide in fixture_shadows.';
  end if;

  if coalesce(btrim(new.fixture_positive_case),'') = ''
     or coalesce(btrim(new.fixture_negative_case),'') = '' then
    raise exception
      'Assertion % must say in words what each half demonstrates.', new.assertion_key
      using hint = 'fixture_positive_case: the real violation it must fire on. '
                   'fixture_negative_case: the legitimate thing it must stay quiet on.';
  end if;

  if new.max_allowed > 0 and length(btrim(coalesce(new.allowance_reason,''))) < 25 then
    raise exception
      'Assertion % tolerates % violations without saying why.', new.assertion_key, new.max_allowed
      using hint = 'A non-zero allowance is recorded debt, not a shrug. Say what the tolerated '
                   'rows are and what would let the number fall.';
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_require_double_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ok       boolean;
  v_proposed boolean;
begin
  -- Terminal states: the finding is being declared over.
  if new.state in ('closed','not_a_problem') then

    if length(btrim(coalesce(new.override_reason,''))) >= 25 then
      if not f_caller_is_admin() then
        raise exception
          'Only an administrator may override the independent check on %.', new.finding_key
          using hint = 'Have a second agent verify the closure instead.';
      end if;
      new.override_by := coalesce(new.override_by, current_app_role());
      new.override_at := coalesce(new.override_at, now());
      return new;
    end if;

    select exists (
      select 1 from finding_closure c
      where c.finding_key = new.finding_key and c.verdict = 'agrees'
    ) into v_ok;

    if not v_ok then
      raise exception
        'Finding % cannot be closed: no independent second check agrees with the closure.',
        new.finding_key
        using hint = 'Insert a finding_closure row with your proof, then have a DIFFERENT '
                     'agent derive the same fact another way and set verdict = agrees. '
                     'An administrator may instead set override_reason (25 characters or more), '
                     'which closes it but records that nobody verified it.';
    end if;
  end if;

  -- Claiming a fix is weaker than closing, but it still may not be a bare assertion.
  if new.state in ('fixed_in_os','fixed_in_metrc') then
    select exists (
      select 1 from finding_closure c
      where c.finding_key = new.finding_key and c.verdict <> 'disagrees'
    ) into v_proposed;

    if not v_proposed and length(btrim(coalesce(new.override_reason,''))) < 25 then
      raise exception
        'Finding % cannot be marked % without a closure record carrying the proof.',
        new.finding_key, new.state
        using hint = 'Insert a finding_closure row stating the claim, how it was derived, '
                     'and the SQL that proves it.';
    end if;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_require_fixture()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not new.enabled then
    return new;   -- a disabled check harms nobody
  end if;

  if coalesce(new.fixture_proves_it_fails,false) then
    -- Claiming a fixture means naming it. "Yes we tested it" is not a test.
    if coalesce(btrim(new.fixture_selftest_fn),'') = '' then
      raise exception
        'Checker % claims a fixture but names no function to prove it.', new.checker_key
        using hint = 'Set fixture_selftest_fn to the function that demonstrates this check '
                     'FIRING on a real violation and STAYING QUIET on a legitimate case.';
    end if;
    /* ADDED 11 Aug 2026. The hint below has demanded a positive case since this trigger
       was written and the code never checked for one. The negative half stops a wrong
       label; the POSITIVE half is the only thing that records what the check is for --
       without it, nobody can tell a check that fires from a check that has quietly
       stopped firing, which is the exact state the SQL guard was in on 8 Aug when it
       passed twenty fixtures while DROP TABLE walked straight through. */
    if coalesce(btrim(new.fixture_positive_case),'') = '' then
      raise exception
        'Checker % has no positive case. Name the real violation it must fire on.',
        new.checker_key
        using hint = 'A check nobody has watched FAIL is a hypothesis. On 8 Aug 2026 the '
                     'SQL guard passed all twenty of its own fixtures while DROP TABLE '
                     'watchdog_findings walked straight through it.';
    end if;
    if coalesce(btrim(new.fixture_negative_case),'') = '' then
      raise exception
        'Checker % has no negative case. Name the legitimate thing it must NOT fire on.',
        new.checker_key
        using hint = 'Every defect recorded on 9 Aug 2026 was a false alarm - a check firing '
                     'on something legitimate. The negative case is the half that catches it.';
    end if;
    return new;
  end if;

  -- No fixture. Only allowed as recorded, reasoned debt.
  if new.grandfathered then
    if length(btrim(coalesce(new.grandfathered_reason,''))) < 25 then
      raise exception
        'Checker % is grandfathered without a reason.', new.checker_key
        using hint = 'Grandfathering is debt on the record, not a shrug. Say why it has no '
                     'fixture and what would be needed to write one.';
    end if;
    return new;
  end if;

  raise exception
    'Checker % cannot be enabled: nothing proves it can fail.', new.checker_key
    using hint = 'Write a fixture showing it FIRES on a real violation and STAYS QUIET on a '
                 'legitimate case, set fixture_selftest_fn, fixture_positive_case and '
                 'fixture_negative_case, then set fixture_proves_it_fails. A check nobody has '
                 'watched fail is a hypothesis, not a check. If it genuinely cannot be tested '
                 'yet, set grandfathered with 25 characters of reason - that is debt, and the '
                 'ratchet will not let the count rise.';
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_reset_layout(p_page text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  delete from dashboard_layout where user_id = auth.uid() and page = p_page;
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_resolve_challenge(p_id bigint, p_verdict text, p_finding text, p_changed text, p_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text;
begin
  if length(coalesce(p_finding,'')) < 20 then
    raise exception 'Resolving a challenge needs a written finding of at least twenty characters.';
  end if;
  update metric_challenges set verdict=p_verdict, agent_finding=p_finding, what_changed=p_changed,
    resolved_at=now(), resolved_by=p_by where id=p_id returning metric_key into v_key;
  update metric_provenance set
    status = case p_verdict when 'CONFIRMED CORRECT' then 'VERIFIED' when 'CORRECTED' then 'VERIFIED'
                            when 'WITHDRAWN' then 'WITHDRAWN' else 'DISPUTED' end,
    last_verified_at = now(), last_verified_by = p_by, updated_at = now()
  where metric_key = v_key;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_retire_zone(p_key text, p_why text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if p_why is null or length(btrim(p_why)) < 10 then
    raise exception 'Say why the zone is being retired — a future reader will need it.';
  end if;
  update zone set active = false, retired_at = now(), retired_why = btrim(p_why)
   where zone_key = p_key;
  if not found then raise exception 'No zone "%".', p_key; end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_review_import(p_import uuid DEFAULT NULL::uuid, p_reviewer text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare total int := 0; failed int := 0; f jsonb := '[]'::jsonb; r record;
        verdict text; who text; imp_report text; imp_by text; imp_check text;
begin
  who := coalesce(p_reviewer, auth.uid()::text, 'reviewer');
  if p_import is not null then
    select report_type, imported_by, count_check into imp_report, imp_by, imp_check
    from metrc_report_imports where id = p_import;
    if imp_report is null then return jsonb_build_object('ok', false, 'error', 'No such import.'); end if;
    if imp_by is not null and imp_by = who then
      return jsonb_build_object('ok', false,
        'error', 'The account that ran this import cannot also certify it. Review must come from '
              || 'a different agent or person.');
    end if;
  end if;

  for r in select * from tg_run_import_checks(null) loop
    total := total + 1;
    if not r.r_passed then
      failed := failed + 1;
      f := f || jsonb_build_object('check', r.r_check_key, 'title', r.r_title, 'level', r.r_level,
                                   'severity', r.r_severity, 'failures', r.r_failures,
                                   'examples', r.r_examples);
    end if;
  end loop;

  if imp_check like 'FAILED%' then
    failed := failed + 1;
    f := f || jsonb_build_object('check','rowcount',
                'title','Row count against the file''s own stated total',
                'level',1,'severity','critical','failures',1,'examples',to_jsonb(imp_check));
  end if;

  verdict := case when failed = 0 then 'certified'
    when exists (select 1 from jsonb_array_elements(f) e where e->>'severity'='critical') then 'rejected'
    else 'needs_a_person' end;

  insert into import_review (import_id, report_key, reviewed_by, checks_run, checks_failed,
                             verdict, findings, note)
  values (p_import, imp_report, who, total, failed, verdict, f,
    case verdict when 'certified' then 'Every check passed against the file, the mapping, the API and the scorecard.'
                 when 'rejected'  then 'A critical check failed. The figures must not be relied on until resolved.'
                 else 'Something needs a person to look at it.' end);

  if verdict <> 'certified' then
    insert into agent_findings (agent, severity, headline, detail, scope, action, drill_to, fingerprint)
    values ('QA & Independent Verification',
            case when verdict='rejected' then 'critical' else 'elevated' end,
            'Import review ' || verdict || ': ' || coalesce(imp_report,'all reports'),
            failed || ' of ' || total || ' checks failed. ' || f::text,
            'import_review','Open Metrc Report Imports and resolve before trusting the figures.',
            'metrc_report_imports','review:' || coalesce(p_import::text,'global'))
    on conflict do nothing;
  end if;

  return jsonb_build_object('ok', verdict='certified', 'verdict', verdict,
    'checks_run', total, 'checks_failed', failed, 'reviewed_by', who, 'findings', f);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_revise_harvest_schedule(p_room text, p_original_date date, p_new_date date, p_note text, p_reason_code text DEFAULT NULL::text, p_event_type text DEFAULT 'Pull'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_prev date; v_role text; v_needs_note boolean;
begin
  select u.role::text into v_role from app_users u where u.user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive','admin','manager') then
    raise exception
      'Changing a harvest date needs owner, executive, admin or manager. The original date is '
      'kept either way — adherence is always measured against the first commitment.'
      using errcode = '42501';
  end if;

  if length(btrim(coalesce(p_note,''))) < 10 then
    raise exception
      'Say what happened, in a sentence. A date change with no reason carries the same '
      'information as no date change, and seven late pulls already have no recorded cause.'
      using errcode = '22023';
  end if;

  if p_reason_code is not null then
    select rc.requires_note into v_needs_note
      from reason_code_catalog rc where rc.code = p_reason_code and rc.active;
    if not found then
      raise exception 'No active reason code "%". Pick one from reason_code_catalog.', p_reason_code;
    end if;
  end if;

  -- The latest known date for this room and original plan: the last revision, or the plan itself.
  select coalesce(
           (select r.new_date from schedule_revision r
             where r.room = p_room and r.original_date = p_original_date
               and r.superseded_by is null
             order by r.revised_at desc limit 1),
           p_original_date)
    into v_prev;

  if v_prev = p_new_date then
    raise exception 'That is already the planned date (%). Nothing to record.', v_prev;
  end if;

  insert into schedule_revision
    (event_type, room, original_date, previous_date, new_date, reason_code, note, revised_by)
  values (p_event_type, p_room, p_original_date, v_prev, p_new_date, p_reason_code,
          btrim(p_note), coalesce(v_role,'unrecorded'))
  returning id into v_id;

  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_root_cause_needs_a_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'resolved' then
    if coalesce(btrim(new.guard_that_prevents_recurrence), '') = '' or new.guard_kind is null then
      raise exception
        'Cannot resolve root cause %: no guard named. A fix without a guard is a pause - the same '
        'defect returns wearing a new tag. Name the verification check, checker, trigger, '
        'constraint, CI gate or hook that now prevents it, or set guard_kind = none_possible with '
        'an accepted_reason.', coalesce(new.pattern_key, new.id::text);
    end if;
    if coalesce(btrim(new.documented_where), '') = '' then
      raise exception
        'Cannot resolve root cause %: no documentation named. Point at something an agent reads at '
        'runtime - a brain file, a table or column comment, a conversion_factors row, a doctrine '
        'rule. Undocumented knowledge is relearned the expensive way.',
        coalesce(new.pattern_key, new.id::text);
    end if;
    if new.guard_kind = 'none_possible' and coalesce(btrim(new.accepted_reason), '') = '' then
      raise exception
        'Cannot resolve root cause %: guard_kind is none_possible with no accepted_reason. If '
        'nothing can prevent this, say why in writing so the next person does not assume it was '
        'an oversight.', coalesce(new.pattern_key, new.id::text);
    end if;
    if new.resolved_on is null then new.resolved_on := current_date; end if;
  end if;
  if new.status = 'accepted_no_fix' and coalesce(btrim(new.accepted_reason), '') = '' then
    raise exception 'Cannot accept root cause % without an accepted_reason.',
      coalesce(new.pattern_key, new.id::text);
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_route_findings(p_by text DEFAULT 'tg_route_findings'::text)
 RETURNS TABLE(source text, routed integer, to_catchall integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  with candidate as (
    -- pile 1: the unified findings spine
    select f.finding_key,
           f.source::text                       as src,
           coalesce(f.department,'')            as dept,
           coalesce(f.severity,'elevated')      as sev,
           coalesce(f.what,'')                  as headline
    from v_findings f
    where f.resolved_at is null
      and not coalesce(f.is_duplicate,false)
    union all
    -- pile 2: the discrepancy register, which the spine does not carry
    select 'disc:'||d.discrepancy_key,
           'discrepancy',
           coalesce(d.class,''),
           'elevated',
           coalesce(d.subject,'')
    from discrepancy_register d
    where d.resolved_at is null
  ),
  unrouted as (
    select c.* from candidate c
    where not exists (select 1 from finding_state s where s.finding_key = c.finding_key)
  ),
  picked as (
    select u.*,
           (select r.route_key from finding_route r
             where r.enabled
               and (r.applies_to = u.src or r.applies_to = '*')
               and (r.match_department is null or r.match_department = u.dept)
               and (r.match_pattern    is null or u.headline ~* r.match_pattern)
             order by r.priority, r.route_key
             limit 1) as route_key
    from unrouted u
  ),
  ins as (
    insert into finding_state
      (finding_key, state, source, owning_agent, route_key, due_by,
       routed_by, routed_at, changed_by, note)
    select p.finding_key, 'open', p.src, r.owning_agent, r.route_key,
           now() + make_interval(hours => case p.sev
                                            when 'critical' then r.hours_critical
                                            when 'watch'    then r.hours_watch
                                            else                 r.hours_elevated end),
           p_by, now(), p_by,
           'routed to '||r.owning_agent||' by rule '||r.route_key
    from picked p join finding_route r on r.route_key = p.route_key
    returning finding_state.source, finding_state.route_key
  )
  select i.source, count(*)::integer,
         count(*) filter (where i.route_key = 'catchall')::integer
  from ins i group by i.source;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_run_data_assertions(p_only text DEFAULT NULL::text, p_by text DEFAULT 'cron'::text)
 RETURNS TABLE(assertion_key text, violations integer, verdict text, detail text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a data_assertion%rowtype;
  v_n integer; v_sample jsonb; v_t0 timestamptz;
  v_verdict text; v_detail text; v_err text; v_stale boolean;
begin
  for a in select * from data_assertion d
            where d.enabled and (p_only is null or d.assertion_key = p_only)
            order by d.assertion_key
  loop
    v_t0 := clock_timestamp();
    v_err := null; v_n := null; v_sample := null;

    v_stale := a.fixture_proven_at is null
            or a.fixture_proven_at < now() - interval '7 days'
            or coalesce(a.fixture_last_result,'') <> 'both halves proved';

    begin
      select n, sample into v_n, v_sample from f_assertion_probe(a.violation_sql, null);
    exception when others then
      v_err := left(sqlerrm, 300);
    end;

    if v_err is not null then
      v_verdict := 'error';
      v_detail  := 'the assertion itself failed to run: ' || v_err;
    elsif v_stale then
      v_verdict := 'error';
      v_detail  := format(
        'found %s violation(s), but this assertion''s fixture was last proved %s. '
        'An unproven check reports nothing: a pass it has not earned is how '
        'tg_refresh_reports() returned "refreshed" through 13 statement timeouts.',
        v_n, coalesce(a.fixture_proven_at::text, 'NEVER'));
    elsif v_n > a.max_allowed then
      v_verdict := 'fail';
      v_detail  := format('%s violation(s), %s tolerated', v_n, a.max_allowed);
    else
      v_verdict := 'pass';
      v_detail  := format('%s violation(s), %s tolerated', v_n, a.max_allowed);
    end if;

    insert into data_assertion_run
      (assertion_key, ran_by, violations, max_allowed, verdict, duration_ms, evidence, error_text)
    values
      (a.assertion_key, p_by, v_n, a.max_allowed, v_verdict,
       (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, v_sample, v_err);

    if v_verdict in ('fail','error') then
      insert into watchdog_findings
        (fingerprint, severity, what, where_it_is, who_is_accountable, why_it_matters,
         how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count)
      values
        ('data_assertion:' || a.assertion_key,
         case when v_verdict = 'error' then 'critical' else a.severity end,
         a.title, a.domain,
         a.accountable_to,                      -- who FIXES it, not who owns the check
         a.why_it_matters,
         'data_assertion ' || a.assertion_key || ' — ' || a.what_it_proves,
         coalesce(v_err, v_detail), v_detail, v_sample, v_n);
    end if;

    assertion_key := a.assertion_key; violations := v_n;
    verdict := v_verdict; detail := v_detail;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_run_import_checks(p_only text DEFAULT NULL::text)
 RETURNS TABLE(r_check_key text, r_title text, r_level integer, r_severity text, r_failures integer, r_passed boolean, r_examples jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; n int; ex jsonb;
begin
  for c in select ic.* from import_check ic
           where ic.enabled and (p_only is null or ic.check_key = p_only)
           order by ic.level, ic.check_key
  loop
    begin
      execute format('select coalesce(jsonb_agg(x), ''[]''::jsonb)
                        from (select * from (%s) s limit 5) x', c.sql_expression) into ex;
      execute format('select count(*) from (%s) s', c.sql_expression) into n;
      insert into import_check_run (check_key, ran_by, failures, passed, examples)
      values (c.check_key, coalesce(auth.uid()::text,'system'), n, n = 0, ex);
      r_check_key := c.check_key; r_title := c.title; r_level := c.level;
      r_severity := c.severity; r_failures := n; r_passed := (n = 0); r_examples := ex;
      return next;
    exception when others then
      insert into import_check_run (check_key, ran_by, failures, passed, error)
      values (c.check_key, coalesce(auth.uid()::text,'system'), -1, false, sqlerrm);
      r_check_key := c.check_key; r_title := c.title; r_level := c.level;
      r_severity := 'critical'; r_failures := -1; r_passed := false;
      r_examples := jsonb_build_object('check_could_not_run', sqlerrm);
      return next;
    end;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_save_dashboard_layout(p_page text, p_widgets jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_dash uuid; v_n int;
begin
  if auth.uid() is null then
    raise exception 'A layout belongs to a person - no signed-in user, no layout.';
  end if;

  select id into v_dash from dashboards where owner = auth.uid() and page = p_page;
  if v_dash is null then
    insert into dashboards (owner, name, page, is_private)
    values (auth.uid(), p_page || ' layout', p_page, true)
    returning id into v_dash;
  end if;

  delete from dashboard_widgets where dashboard_id = v_dash;

  insert into dashboard_widgets (dashboard_id, widget_key, position, visible, span)
  select v_dash,
         w->>'widget_key',
         coalesce((w->>'position')::int, 0),
         coalesce((w->>'visible')::boolean, true),
         coalesce((w->>'span')::int, 1)
  from jsonb_array_elements(p_widgets) w
  where coalesce(w->>'widget_key','') <> '';

  get diagnostics v_n = row_count;
  return v_n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_save_finding(p_key text, p_source text, p_headline text, p_snapshot jsonb, p_disposition text DEFAULT 'saved_for_later'::text, p_plan text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_owner text DEFAULT NULL::text, p_due date DEFAULT NULL::date, p_dollars numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare fid uuid;
begin
  insert into finding_plans (finding_key, finding_source, headline, snapshot, plan, disposition,
    disposition_reason, owner_assigned, due_on, dollars, created_by)
  values (p_key, p_source, p_headline, p_snapshot, p_plan, p_disposition,
    p_reason, p_owner, p_due, p_dollars, auth.uid()::text)
  returning id into fid;
  -- putting it on the to-do list creates a real task
  if p_disposition = 'on_todo_list' then
    insert into tasks (title, description, status, priority, due_on, created_by)
    values (p_headline, coalesce(p_plan,'') || ' [from a Chief Executive finding]', 'todo',
      case when coalesce(p_dollars,0) > 100000 then 'P0' else 'P1' end, p_due, auth.uid());
  end if;
  return fid;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_save_layout(p_page text, p_widgets jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare n int; bad text;
begin
  if p_page is null or btrim(p_page) = '' then
    raise exception 'tg_save_layout needs a page name.';
  end if;
  if jsonb_typeof(p_widgets) <> 'array' then
    raise exception
      'tg_save_layout expects a JSON ARRAY of '
      '{widget_key,instance_id,x,y,w,h,visible,config,title_override}.';
  end if;

  select string_agg(distinct e->>'widget_key', ', ')
    into bad
    from jsonb_array_elements(p_widgets) e
   where not exists (select 1 from widget_catalog c where c.key = e->>'widget_key');
  if bad is not null then
    raise exception
      'Not in widget_catalog: %. A layout may only place widgets the catalogue defines — '
      'otherwise the saved screen references a tile nothing can render.', bad;
  end if;

  -- A singleton placed twice is a front-end bug. Fail loudly rather than silently keeping one.
  select string_agg(k, ', ') into bad from (
    select e->>'widget_key' as k
    from jsonb_array_elements(p_widgets) e
    join widget_catalog c on c.key = e->>'widget_key'
    where not c.multi_instance
    group by e->>'widget_key'
    having count(*) > 1
  ) dup;
  if bad is not null then
    raise exception
      'Placed more than once but not multi_instance: %. Either the catalogue should allow copies, '
      'or the canvas should not have offered a second one.', bad;
  end if;

  delete from dashboard_layout where user_id = auth.uid() and page = p_page;

  insert into dashboard_layout
    (user_id, page, widget_key, instance_id, x, y, w, h, visible, config, title_override)
  select auth.uid(), p_page,
         e->>'widget_key',
         coalesce((e->>'instance_id')::int, 1),
         coalesce((e->>'x')::int, 0),
         coalesce((e->>'y')::int, 0),
         coalesce((e->>'w')::int, 3),
         coalesce((e->>'h')::int, 2),
         coalesce((e->>'visible')::boolean, true),
         coalesce(e->'config', '{}'::jsonb),
         nullif(e->>'title_override','')
  from jsonb_array_elements(p_widgets) e;

  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_secret_forget(p_key text, p_drop_registration boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_key text := upper(btrim(coalesce(p_key, '')));
begin
  if not exists (select 1 from app_users u
                  where u.user_id = auth.uid() and u.role in ('owner', 'executive')) then
    raise exception 'Only an owner or an executive can remove a key.' using errcode = '42501';
  end if;

  if p_drop_registration then
    delete from app_secrets where key = v_key;
  else
    update app_secrets
       set value = '', value_is_set = false, value_last4 = null, value_set_at = null,
           updated_by = auth.uid(), updated_at = now()
     where key = v_key;
  end if;

  insert into audit_events (actor, entity, entity_id, action, new_value)
  values (auth.uid(), 'app_secrets', v_key,
          case when p_drop_registration then 'deregistered' else 'cleared' end,
          jsonb_build_object('set', false));
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_secret_register(p_key text, p_label text, p_help text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_key text := upper(btrim(coalesce(p_key, '')));
begin
  if not exists (select 1 from app_users u
                  where u.user_id = auth.uid() and u.role in ('owner', 'executive')) then
    raise exception 'Only an owner or an executive can register a key.' using errcode = '42501';
  end if;
  if v_key = '' then
    raise exception 'A key needs a name.' using errcode = '22023';
  end if;

  insert into app_secrets (key, value, value_is_set, label, help, updated_by, updated_at)
  values (v_key, '', false, nullif(btrim(coalesce(p_label, '')), ''),
          nullif(btrim(coalesce(p_help, '')), ''), auth.uid(), now())
  on conflict (key) do update
     set label = coalesce(nullif(btrim(coalesce(p_label, '')), ''), app_secrets.label),
         help  = coalesce(nullif(btrim(coalesce(p_help,  '')), ''), app_secrets.help);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_assertion_coverage(p_by text DEFAULT 'selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a numeric; b numeric;
begin
  -- POSITIVE half: an assertion nobody tests must make the check FIRE.
  with asrt(assertion) as (values ('fx-covered'::text), ('fx-orphan'::text)),
       ctl(assertion, control_key) as (values ('fx-covered'::text, 'some-check'::text))
  select (select count(*) from asrt),
         (select count(distinct c.assertion) from ctl c where c.control_key is not null) into a, b;
  return query select 'FIRES when an assertion has no control'::text, (a <> b),
                      format('%s assertions, %s guarded - %s', a, b,
                             case when a <> b then 'disagrees, correct' else 'stayed quiet, BROKEN' end);

  -- NEGATIVE half: every assertion guarded, the check must STAY QUIET.
  with asrt(assertion) as (values ('fx-a'::text), ('fx-b'::text)),
       ctl(assertion, control_key) as (values ('fx-a'::text, 'check-1'::text), ('fx-b'::text, 'check-2'::text))
  select (select count(*) from asrt),
         (select count(distinct c.assertion) from ctl c where c.control_key is not null) into a, b;
  return query select 'QUIET when every assertion has a control'::text, (a = b),
                      format('%s assertions, %s guarded - %s', a, b,
                             case when a = b then 'agrees, correct' else 'fired anyway, BROKEN' end);

  select (select count(*) from audit_assertion),
         (select count(*) from (select a2.assertion from audit_assertion a2
                                  join examination_standard e on e.assertion = a2.assertion
                                 where e.control_key is not null group by a2.assertion) x) into a, b;
  return query select 'live position (informational, not a pass condition)'::text, true,
                      format('%s assertions, %s guarded, %s with NO control at all', a, b, a - b);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_backfill_sweep(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  k text := 'selftest:backfill';
  j text := 'selftest:backfill-fresh';
  v text;
  n integer;
begin
  create temp table if not exists _bf(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _bf;

  delete from agent_findings where fingerprint in
    ('backfill_stalled:'||k,'backfill_uncountable:'||k,'backfill_overrunning:'||k,
     'backfill_stalled:'||j,'backfill_uncountable:'||j,'backfill_overrunning:'||j);
  delete from backfill_watch where job_key in (k, j, k||':nofloorreason');

  -- CASE 1-3: a backlog genuinely flat for eight days
  insert into backfill_watch(job_key, what_it_drains, remaining_sql, accepted_floor)
  values (k, 'a self-test backlog that deliberately never drains', 'select 5', 0);
  insert into backfill_reading(job_key, remaining, read_at, read_by)
  values (k, 5, now() - interval '8 days', p_by), (k, 5, now() - interval '4 days', p_by);

  select s.verdict into v from tg_backfill_sweep(p_by) s where s.job_key = k;
  insert into _bf values ('a backlog flat for eight days reads STALLED','STALLED',coalesce(v,'(none)'), v='STALLED');

  select count(*) into n from agent_findings where fingerprint='backfill_stalled:'||k and resolved_at is null;
  insert into _bf values ('STALLED raises a finding','1 finding', n||' findings', n=1);

  update backfill_watch set remaining_sql='select 1' where job_key=k;
  select s.verdict into v from tg_backfill_sweep(p_by) s where s.job_key = k;
  select count(*) into n from agent_findings where fingerprint='backfill_stalled:'||k and resolved_at is null;
  insert into _bf values ('once it drains the finding stands down','DRAINING and 0 open',
                          coalesce(v,'?')||' and '||n||' open', v='DRAINING' and n=0);

  -- CASE 4: THE REGRESSION. Two equal readings minutes apart are NOT a seven-day stall.
  -- This is the defect that shipped on 9 Aug 2026 and was fixed the same hour: a verdict
  -- about seven days of history being drawn from minutes of it.
  insert into backfill_watch(job_key, what_it_drains, remaining_sql, accepted_floor)
  values (j, 'a self-test backlog with no history behind it yet', 'select 4', 0);
  perform tg_backfill_sweep(p_by);                       -- first reading
  select s.verdict into v from tg_backfill_sweep(p_by) s where s.job_key = j;   -- second, seconds later
  select count(*) into n from agent_findings where fingerprint='backfill_stalled:'||j and resolved_at is null;
  insert into _bf values ('two equal readings minutes apart are NOT a stall',
                          'TOO SOON TO SAY and 0 findings',
                          coalesce(v,'?')||' and '||n||' findings',
                          v='TOO SOON TO SAY' and n=0);

  -- CASE 5: a floor above zero without evidence is refused
  begin
    insert into backfill_watch(job_key, what_it_drains, remaining_sql, accepted_floor)
    values (k||':nofloorreason','a self-test backlog with an unexplained floor','select 9', 9);
    insert into _bf values ('an unexplained floor is refused','refused','ALLOWED IT',false);
  exception when others then
    insert into _bf values ('an unexplained floor is refused','refused',left(sqlerrm,55),true);
  end;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'backfill_sweep', s.case_name, s.expected, s.actual, s.passed, p_by from _bf s;

  delete from agent_findings where fingerprint in
    ('backfill_stalled:'||k,'backfill_uncountable:'||k,'backfill_overrunning:'||k,
     'backfill_stalled:'||j,'backfill_uncountable:'||j,'backfill_overrunning:'||j);
  delete from backfill_watch where job_key in (k, j, k||':nofloorreason');

  return query select s.case_name, s.passed, s.actual from _bf s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_data_assertion_gate(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text := 'selftest:assertion-gate'; xid bigint;
begin
  create temp table if not exists _ag(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _ag;
  delete from data_assertion where assertion_key like k || '%';
  delete from ratchet_exception where metric_key like 'data_assertion:' || k || '%';

  begin
    insert into data_assertion (assertion_key,title,domain,violation_sql,what_it_proves,
                                why_it_matters,accountable_to,fixture_negative_schema,
                                fixture_shadows,fixture_positive_case,fixture_negative_case)
    values (k,'no positive half','selftest','select 1 as subject, 2 as detail','x','y','nobody',
            'tg_fx_neg_gencol',array['metrc_harvests'],'pos','neg');
    insert into _ag values ('enabled with no POSITIVE fixture','refused','ALLOWED IT',false);
  exception when others then
    insert into _ag values ('enabled with no POSITIVE fixture','refused',left(sqlerrm,60),true);
  end;

  begin
    insert into data_assertion (assertion_key,title,domain,violation_sql,what_it_proves,
                                why_it_matters,accountable_to,fixture_positive_schema,
                                fixture_shadows,fixture_positive_case,fixture_negative_case)
    values (k||':noneg','no negative half','selftest','select 1 as subject, 2 as detail','x','y',
            'nobody','tg_fx_pos_gencol',array['metrc_harvests'],'pos','neg');
    insert into _ag values ('enabled with no NEGATIVE fixture','refused','ALLOWED IT',false);
  exception when others then
    insert into _ag values ('enabled with no NEGATIVE fixture','refused',left(sqlerrm,60),true);
  end;

  begin
    insert into data_assertion (assertion_key,title,domain,violation_sql,what_it_proves,
                                why_it_matters,accountable_to,fixture_positive_schema,
                                fixture_negative_schema,fixture_positive_case,fixture_negative_case)
    values (k||':noshadow','names no shadows','selftest','select 1 as subject, 2 as detail','x','y',
            'nobody','tg_fx_pos_gencol','tg_fx_neg_gencol','pos','neg');
    insert into _ag values ('names no shadowed relations','refused','ALLOWED IT',false);
  exception when others then
    insert into _ag values ('names no shadowed relations','refused',left(sqlerrm,60),true);
  end;

  begin
    insert into data_assertion (assertion_key,title,domain,violation_sql,what_it_proves,
                                why_it_matters,accountable_to,fixture_positive_schema,
                                fixture_negative_schema,fixture_shadows,
                                fixture_positive_case,fixture_negative_case,max_allowed)
    values (k||':debt','tolerates debt silently','selftest','select 1 as subject, 2 as detail','x','y',
            'nobody','tg_fx_pos_gencol','tg_fx_neg_gencol',array['metrc_harvests'],'pos','neg',5);
    insert into _ag values ('tolerates violations with no reason','refused','ALLOWED IT',false);
  exception when others then
    insert into _ag values ('tolerates violations with no reason','refused',left(sqlerrm,60),true);
  end;

  begin
    insert into data_assertion (assertion_key,title,domain,violation_sql,what_it_proves,
                                why_it_matters,accountable_to,fixture_positive_schema,
                                fixture_negative_schema,fixture_shadows,
                                fixture_positive_case,fixture_negative_case)
    values (k||':good','both halves named','selftest','select 1 as subject, 2 as detail','x','y',
            'nobody','tg_fx_pos_gencol','tg_fx_neg_gencol',array['metrc_harvests'],'pos','neg');
    insert into _ag values ('a fully evidenced assertion is ALLOWED','allowed','allowed',true);
  exception when others then
    insert into _ag values ('a fully evidenced assertion is ALLOWED','allowed',
                            'REFUSED: '||left(sqlerrm,45),false);
  end;

  begin
    insert into data_assertion (assertion_key,title,domain,violation_sql,what_it_proves,
                                why_it_matters,accountable_to,enabled,max_allowed,allowance_reason)
    values (k||':off','switched off','selftest','select 1 as subject, 2 as detail','x','y',
            'nobody',false,5,'a throwaway selftest row carrying debt so the ratchet can be exercised');
    insert into _ag values ('a disabled assertion needs no fixture','allowed','allowed',true);
  exception when others then
    insert into _ag values ('a disabled assertion needs no fixture','allowed',
                            'REFUSED: '||left(sqlerrm,45),false);
  end;

  begin
    update data_assertion set max_allowed = 4 where assertion_key = k||':off';
    insert into _ag values ('the violation allowance may FALL','allowed','5 -> 4 allowed',true);
  exception when others then
    insert into _ag values ('the violation allowance may FALL','allowed',
                            'REFUSED: '||left(sqlerrm,45),false);
  end;

  begin
    update data_assertion set max_allowed = 9 where assertion_key = k||':off';
    insert into _ag values ('the violation allowance may not RISE','refused','ALLOWED IT',false);
  exception when others then
    insert into _ag values ('the violation allowance may not RISE','refused',left(sqlerrm,60),true);
  end;

  /* The reason below is long ON PURPOSE: ratchet_exception constrains it, because a
     rise in recorded debt without a real explanation is how a ratchet quietly stops
     meaning anything. The first draft of this selftest wrote one line and was refused
     by that constraint — the guard was right and the test was wrong. */
  insert into ratchet_exception (metric_key, from_baseline, to_baseline, why, approved_by, must_fall_by)
  values ('data_assertion:'||k||':off', 4, 9,
          'Self-test of the recorded-decision door on the assertion allowance ratchet. This row '
          'is created and deleted inside tg_selftest_data_assertion_gate and never describes real '
          'debt; it exists so the platform can prove the only sanctioned way to raise a ratchet '
          'still works, and that a consumed exception cannot be used twice.',
          'tg_selftest', current_date + 1)
  returning id into xid;
  begin
    update data_assertion set max_allowed = 9 where assertion_key = k||':off';
    insert into _ag values ('a recorded owner decision opens the door','allowed','allowed',true);
  exception when others then
    insert into _ag values ('a recorded owner decision opens the door','allowed',
                            'REFUSED: '||left(sqlerrm,45),false);
  end;

  begin
    update data_assertion set max_allowed = 4 where assertion_key = k||':off';
    update data_assertion set max_allowed = 9 where assertion_key = k||':off';
    insert into _ag values ('a consumed exception cannot be reused','refused','ALLOWED IT',false);
  exception when others then
    insert into _ag values ('a consumed exception cannot be reused','refused',left(sqlerrm,60),true);
  end;

  insert into guard_selftest (guard_key, case_name, expected, actual, passed, ran_by)
  select 'data_assertion_gate', s.case_name, s.expected, s.actual, s.passed, p_by from _ag s;

  delete from data_assertion where assertion_key like k || '%';
  delete from ratchet_exception where metric_key like 'data_assertion:' || k || '%';
  return query select s.case_name, s.passed, s.actual from _ag s;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_double_check(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  k text := 'selftest:double-check';
  r record;
  function_result text;
begin
  create temp table if not exists _st(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _st;

  -- clean slate
  delete from finding_closure where finding_key = k;
  delete from finding_state   where finding_key = k;

  insert into finding_state(finding_key, state, source, changed_by, note)
  values (k, 'open', 'selftest', p_by, 'self-test row, deleted at the end of this function');

  -- 1. bare closure must be refused
  begin
    update finding_state set state='closed', note='trying to close with no proof at all', changed_by=p_by
    where finding_key=k;
    insert into _st values ('closing with no closure record','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('closing with no closure record','refused',left(sqlerrm,60),true);
  end;

  insert into finding_closure(finding_key, proposed_by, claim, how_derived, proof_sql)
  values (k,'agent-alpha',
          'the self-test finding is no longer true and can be closed',
          'counted the underlying rows and found none remaining',
          'select count(*) from finding_state where finding_key = ''selftest:double-check''');

  -- 2. proposed but unverified must still be refused
  begin
    update finding_state set state='closed', note='proposed but nobody has checked it', changed_by=p_by
    where finding_key=k;
    insert into _st values ('closing on a proposal nobody verified','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('closing on a proposal nobody verified','refused',left(sqlerrm,60),true);
  end;

  -- 3. the same agent cannot second its own work
  begin
    update finding_closure set second_by='agent-alpha', second_at=now(),
           second_how_derived='I checked my own work again and it still looks right',
           second_proof_sql='select 1 -- a different query', verdict='agrees'
    where finding_key=k;
    insert into _st values ('agent seconds its own closure','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('agent seconds its own closure','refused',left(sqlerrm,60),true);
  end;

  -- 4. re-running the first agent's query is not an independent derivation
  begin
    update finding_closure set second_by='agent-beta', second_at=now(),
           second_how_derived='ran exactly the same query the first agent ran',
           second_proof_sql='select count(*) from finding_state where finding_key = ''selftest:double-check''',
           verdict='agrees'
    where finding_key=k;
    insert into _st values ('second agent re-runs the same SQL','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('second agent re-runs the same SQL','refused',left(sqlerrm,60),true);
  end;

  -- 5. a genuine independent check, by someone else, another way
  begin
    update finding_closure set second_by='agent-beta', second_at=now(),
           second_how_derived='derived it from the history table instead of the state table',
           second_proof_sql='select count(*) from finding_state_history where finding_key = ''selftest:double-check''',
           second_value=0, verdict='agrees'
    where finding_key=k;
    update finding_state set state='closed', note='independently verified by agent-beta', changed_by=p_by
    where finding_key=k;
    select state into function_result from finding_state where finding_key=k;
    insert into _st values ('independently verified closure','allowed',coalesce(function_result,'(gone)'),
                            function_result = 'closed');
  exception when others then
    insert into _st values ('independently verified closure','allowed','REFUSED: '||left(sqlerrm,50),false);
  end;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'double_check_on_closure', s.case_name, s.expected, s.actual, s.passed, p_by from _st s;

  delete from finding_closure where finding_key = k;
  delete from finding_state   where finding_key = k;

  return query select s.case_name, s.passed, s.actual from _st s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_examination_readiness(p_by text DEFAULT 'selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a numeric; b numeric;
begin
  -- POSITIVE half: a test with no evidence source must make the check FIRE.
  with fixture(test_key, where_it_lives) as (
    values ('fx-sourced', 'metrc_packages'::text), ('fx-unsourced', null::text))
  select count(*), count(*) filter (where where_it_lives is not null) into a, b from fixture;
  return query select 'FIRES when a test has no evidence source'::text, (a <> b),
                      format('%s tests, %s producible - %s', a, b,
                             case when a <> b then 'disagrees, correct' else 'stayed quiet, BROKEN' end);

  -- NEGATIVE half: every test sourced, the check must STAY QUIET.
  with fixture(test_key, where_it_lives) as (
    values ('fx-a', 'metrc_packages'::text), ('fx-b', 'coa_extract'::text))
  select count(*), count(*) filter (where where_it_lives is not null) into a, b from fixture;
  return query select 'QUIET when every test has an evidence source'::text, (a = b),
                      format('%s tests, %s producible - %s', a, b,
                             case when a = b then 'agrees, correct' else 'fired anyway, BROKEN' end);

  -- The live position, reported rather than scored.
  select count(*), count(*) filter (where where_it_lives is not null) into a, b from examination_standard;
  return query select 'live position (informational, not a pass condition)'::text, true,
                      format('%s examination tests, %s producible, %s CANNOT BE PRODUCED', a, b, a - b);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_fixture_gate(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text := 'selftest:fixture-gate'; ok boolean; b integer;
begin
  create temp table if not exists _fg(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _fg;
  delete from checker_registry where checker_key like k||'%';

  -- 1. enabled with nothing proving it → refused
  begin
    insert into checker_registry(checker_key,title,tier,runs_where,enabled,fixture_proves_it_fails)
    values (k,'a self-test checker with no fixture at all','detect','nowhere',true,false);
    insert into _fg values ('enabled with no fixture','refused','ALLOWED IT',false);
  exception when others then
    insert into _fg values ('enabled with no fixture','refused',left(sqlerrm,55),true);
  end;

  -- 2. claiming a fixture but naming none → refused
  begin
    insert into checker_registry(checker_key,title,tier,runs_where,enabled,fixture_proves_it_fails)
    values (k||':claims','a self-test checker that claims proof it cannot name','detect','nowhere',true,true);
    insert into _fg values ('claims a fixture but names none','refused','ALLOWED IT',false);
  exception when others then
    insert into _fg values ('claims a fixture but names none','refused',left(sqlerrm,55),true);
  end;

  -- 3. positive case only, no negative case → refused. THIS is the one that matters:
  --    all seven recorded defects were false alarms, which only a negative case catches.
  begin
    insert into checker_registry(checker_key,title,tier,runs_where,enabled,
                                 fixture_proves_it_fails,fixture_selftest_fn,fixture_positive_case)
    values (k||':nonneg','a self-test checker proving only that it fires','detect','nowhere',
            true,true,'some_fn','it fires when the thing is wrong');
    insert into _fg values ('no negative case','refused','ALLOWED IT',false);
  exception when others then
    insert into _fg values ('no negative case','refused',left(sqlerrm,55),true);
  end;

  -- 4. grandfathered with no reason → refused
  begin
    insert into checker_registry(checker_key,title,tier,runs_where,enabled,
                                 fixture_proves_it_fails,grandfathered)
    values (k||':nogf','a self-test checker grandfathered with a shrug','detect','nowhere',
            true,false,true);
    insert into _fg values ('grandfathered with no reason','refused','ALLOWED IT',false);
  exception when others then
    insert into _fg values ('grandfathered with no reason','refused',left(sqlerrm,55),true);
  end;

  -- 5. NEGATIVE CASE: a properly evidenced checker must be ALLOWED. A gate that blocks
  --    honest work gets switched off, and a switched-off gate is worse than none.
  begin
    insert into checker_registry(checker_key,title,tier,runs_where,enabled,
                                 fixture_proves_it_fails,fixture_selftest_fn,
                                 fixture_positive_case,fixture_negative_case)
    values (k||':good','a self-test checker with both halves','detect','nowhere',true,true,
            'tg_selftest_fixture_gate','it fires on a real violation',
            'it stays quiet on a legitimate case');
    select true into ok;
    insert into _fg values ('a properly evidenced checker is ALLOWED','allowed','allowed',true);
  exception when others then
    insert into _fg values ('a properly evidenced checker is ALLOWED','allowed',
                            'REFUSED: '||left(sqlerrm,45),false);
  end;

  -- 6. NEGATIVE CASE: a DISABLED checker needs no fixture and must be allowed.
  begin
    insert into checker_registry(checker_key,title,tier,runs_where,enabled,fixture_proves_it_fails)
    values (k||':off','a self-test checker that is switched off','detect','nowhere',false,false);
    insert into _fg values ('a disabled checker needs no fixture','allowed','allowed',true);
  exception when others then
    insert into _fg values ('a disabled checker needs no fixture','allowed',
                            'REFUSED: '||left(sqlerrm,45),false);
  end;

  -- 7. the ratchet may not rise
  select baseline into b from ratchet_baseline where metric_key='checkers_without_a_fixture';
  begin
    update ratchet_baseline set baseline = b + 1 where metric_key='checkers_without_a_fixture';
    insert into _fg values ('the debt ratchet may not rise','refused','ALLOWED IT',false);
  exception when others then
    insert into _fg values ('the debt ratchet may not rise','refused',left(sqlerrm,55),true);
  end;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'fixture_gate', s.case_name, s.expected, s.actual, s.passed, p_by from _fg s;

  delete from checker_registry where checker_key like k||'%';
  return query select s.case_name, s.passed, s.actual from _fg s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_forensic_panel_freshness()
 RETURNS TABLE(case_no integer, half text, case_name text, expected text, actual text, passed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  n_after   int;
  n_open    int;
  v_test_id uuid;
begin
  ---------------------------------------------------------------------------
  -- POSITIVE HALF: the check must FIRE.
  ---------------------------------------------------------------------------
  return query select 1, 'positive', 'clock 90 min old against a 30 min SLO', 'STALE',
    f_matview_freshness_verdict(now()-interval '90 minutes', now(), interval '30 minutes'),
    f_matview_freshness_verdict(now()-interval '90 minutes', now(), interval '30 minutes') = 'STALE';

  return query select 2, 'positive', 'clock 8 h old - refresh is not merely late, it is dead', 'DEAD',
    f_matview_freshness_verdict(now()-interval '8 hours', now(), interval '30 minutes'),
    f_matview_freshness_verdict(now()-interval '8 hours', now(), interval '30 minutes') = 'DEAD';

  return query select 3, 'positive', 'matview never computed at all', 'NEVER COMPUTED',
    f_matview_freshness_verdict(null, now(), interval '30 minutes'),
    f_matview_freshness_verdict(null, now(), interval '30 minutes') = 'NEVER COMPUTED';

  return query select 4, 'positive', 'computed_at in the future - a broken clock is not freshness', 'CLOCK SKEW',
    f_matview_freshness_verdict(now()+interval '10 minutes', now(), interval '30 minutes'),
    f_matview_freshness_verdict(now()+interval '10 minutes', now(), interval '30 minutes') = 'CLOCK SKEW';

  ---------------------------------------------------------------------------
  -- NEGATIVE HALF: the check must STAY QUIET.
  ---------------------------------------------------------------------------
  return query select 5, 'negative', 'refreshed 5 min ago - the normal healthy state', 'ok',
    f_matview_freshness_verdict(now()-interval '5 minutes', now(), interval '30 minutes'),
    f_matview_freshness_verdict(now()-interval '5 minutes', now(), interval '30 minutes') = 'ok';

  return query select 6, 'negative', 'BOUNDARY 29 min 59 s - one second inside the SLO must not fire', 'ok',
    f_matview_freshness_verdict(now()-interval '29 minutes 59 seconds', now(), interval '30 minutes'),
    f_matview_freshness_verdict(now()-interval '29 minutes 59 seconds', now(), interval '30 minutes') = 'ok';

  return query select 7, 'negative', 'BOUNDARY exactly 30 min - not yet OVER the SLO', 'ok',
    f_matview_freshness_verdict(now()-interval '30 minutes', now(), interval '30 minutes'),
    f_matview_freshness_verdict(now()-interval '30 minutes', now(), interval '30 minutes') = 'ok';

  ---------------------------------------------------------------------------
  -- WIRING: does the checker actually WRITE and actually CLEAR?
  ---------------------------------------------------------------------------
  select count(*) into n_open from agent_findings
   where fingerprint='forensic_panel_stale' and resolved_at is null;

  if n_open > 0 then
    return query select 8, 'positive','end to end: forced breach files a finding',
      'SKIPPED','a real forensic_panel_stale finding is already open', true;
    return query select 9, 'positive','end to end: recovery clears the finding',
      'SKIPPED','a real forensic_panel_stale finding is already open', true;
    return query select 10,'negative','end to end: healthy SLO files nothing',
      'SKIPPED','a real forensic_panel_stale finding is already open', true;
    return;
  end if;

  -- 8. POSITIVE end to end. SLO of zero => any positive age breaches. Deterministic.
  perform tg_check_forensic_panel_freshness('selftest', interval '0');
  select count(*) into n_after from agent_findings
   where fingerprint='forensic_panel_stale' and resolved_at is null;
  return query select 8, 'positive','end to end: forced breach files a finding',
    '1 open finding', n_after||' open finding(s)', n_after = 1;

  -- capture the row THIS run created, so cleanup is exact rather than time-guessed
  select f.id into v_test_id from agent_findings f
   where f.fingerprint='forensic_panel_stale' and f.resolved_at is null
   order by f.detected_at desc limit 1;

  -- 9. POSITIVE end to end: recovery must CLEAR it.
  perform tg_check_forensic_panel_freshness('selftest', interval '10 years');
  select count(*) into n_after from agent_findings
   where fingerprint='forensic_panel_stale' and resolved_at is null;
  return query select 9, 'positive','end to end: recovery clears the finding',
    '0 open findings', n_after||' open finding(s)', n_after = 0;

  -- 10. NEGATIVE end to end: a healthy panel must file NOTHING.
  perform tg_check_forensic_panel_freshness('selftest', interval '10 years');
  select count(*) into n_after from agent_findings
   where fingerprint='forensic_panel_stale' and resolved_at is null;
  return query select 10,'negative','end to end: healthy SLO files nothing',
    '0 open findings', n_after||' open finding(s)', n_after = 0;

  -- put it back, exactly
  if v_test_id is not null then
    delete from agent_findings where id = v_test_id;
  end if;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_report_upload_nag(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_before integer;
  v_after  integer;
  v_second integer;
  r        record;
  v_fp     text;
  v_state  text;
begin
  create temp table if not exists _rn(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _rn;

  -- 1. IDEMPOTENCY: a second run must raise nothing new.
  select count(*) into v_before from agent_findings
   where fingerprint like 'report_upload_overdue:%' and resolved_at is null;
  perform tg_raise_report_upload_findings(p_by);
  select count(*) into v_after from agent_findings
   where fingerprint like 'report_upload_overdue:%' and resolved_at is null;
  insert into _rn values ('re-running raises no duplicates', 'no change',
                          v_before||' -> '||v_after, v_before = v_after);

  -- 2. COVERAGE: every overdue row in the view has an open finding.
  select count(*) into v_second
  from v_report_upload_due d
  where not d.received and d.days_late > 0
    and not exists (
      select 1 from agent_findings f
      where f.fingerprint = 'report_upload_overdue:'||d.report_key||':'||d.licence||':'||d.period_label
        and f.resolved_at is null);
  insert into _rn values ('every overdue upload has an open finding', '0 uncovered',
                          v_second||' uncovered', v_second = 0);

  -- 3. STAND-DOWN: plant a finding against an upload that HAS been received and
  --    prove the next run closes it. Uses a real received row, not a mock.
  select d.report_key, d.licence, d.period_label into r
  from v_report_upload_due d where d.received limit 1;

  if r.report_key is null then
    insert into _rn values ('a received upload stands the finding down',
                            'tested', 'SKIPPED - no received row to test against', false);
  else
    v_fp := 'report_upload_overdue:'||r.report_key||':'||r.licence||':'||r.period_label;
    delete from agent_findings where fingerprint = v_fp and detail like '%SELF-TEST%';
    insert into agent_findings
      (agent, severity, headline, detail, scope, action, drill_to, fingerprint)
    values ('Metrc & Compliance','watch',
            'SELF-TEST row for the report-upload stand-down path',
            'SELF-TEST. Planted against an upload that has already been received, to prove '
            || 'the nag stands down. Removed at the end of this function.',
            r.licence, 'none - self test', 'none', v_fp);

    perform tg_raise_report_upload_findings(p_by);

    select case when resolved_at is null then 'STILL OPEN' else 'resolved' end into v_state
    from agent_findings where fingerprint = v_fp and detail like '%SELF-TEST%';

    insert into _rn values ('a received upload stands the finding down', 'resolved',
                            coalesce(v_state,'(row vanished)'), coalesce(v_state,'') = 'resolved');

    delete from agent_findings where fingerprint = v_fp and detail like '%SELF-TEST%';
  end if;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'report_upload_nag', s.case_name, s.expected, s.actual, s.passed, p_by from _rn s;

  return query select s.case_name, s.passed, s.actual from _rn s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_strain_stripper()
 RETURNS TABLE(half text, case_in text, expected text, got text, passed boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record;
begin
  ------------------------------------------------------------------- positive
  for r in
    select * from (values
      ('TG Banana Mango seeds',                    'TG Banana Mango'),
      ('Spritzer Crude',                           'Spritzer'),
      ('Apple Fritter Live Bubble Hash',           'Apple Fritter'),
      ('Purple Taxi Live Badder Pre-Fill',         'Purple Taxi'),
      ('TG Chimera Fresh Frozen',                  'TG Chimera'),
      ('Blue Dream Live',                          'Blue Dream'),
      ('Kerosene Berry Terpenes',                  'Kerosene Berry'),
      ('Fatso High Terpene Extract',               'Fatso'),
      ('Gelly Muffin Crude Bulk Oil',              'Gelly Muffin'),
      ('Bananaconda-trim',                         'Bananaconda'),
      ('Lemon Drop Live Badder PreFill',           'Lemon Drop'),
      ('Marshmallow OG Live Crude',                'Marshmallow OG'),
      ('Alien Cherry Mint Live Hash Rosin Pre-Fill','Alien Cherry Mint')
    ) v(a,b)
  loop
    half := 'positive - must strip'; case_in := r.a; expected := r.b;
    got := f_strip_product_form(r.a); passed := (got is not distinct from r.b);
    return next;
  end loop;

  ------------------------------------------------- negative, hand-picked cases
  -- "Bubble Gum" is the one that matters: it contains a form word and must
  -- survive a stripper that removes "Bubble Hash".
  for r in
    select * from (values
      ('Bubble Gum'), ('Mango'), ('Italian Ice'), ('Red Velvet'), ('Crostata'),
      ('King Louis XIII'), ('Super Boof'), ('TG Gush Mintz'), ('Sour Strawberry'),
      ('Cookies and Cream'), ('Strawberry Muffin'), ('Espresso'), ('Grape Ape')
    ) v(a)
  loop
    half := 'negative - must NOT change'; case_in := r.a; expected := r.a;
    got := f_strip_product_form(r.a); passed := (got is not distinct from r.a);
    return next;
  end loop;

  --------------------------------------- negative, derived from the live register
  -- The strongest half, because it is not a list somebody imagined: NO name in
  -- the Metrc strain register may be altered. If a form word ever collides with
  -- a real strain, this fires without anyone having thought of that strain.
  for r in
    select s.name from metrc_strains s
    where f_strip_product_form(s.name) is distinct from btrim(s.name)
    limit 25
  loop
    half := 'negative - registered strain must survive'; case_in := r.name;
    expected := btrim(r.name); got := f_strip_product_form(r.name);
    passed := false; return next;
  end loop;

  if not found then null; end if;
  -- an all-clear row, so "no output" can never be mistaken for "all passed"
  -- (rule K1 question 5: silence must be distinguishable from success)
  half := 'negative - registered strain must survive';
  case_in := format('all %s registered strain names', (select count(*) from metrc_strains));
  expected := 'unchanged by the stripper';
  got := format('%s altered',
          (select count(*) from metrc_strains s
            where f_strip_product_form(s.name) is distinct from btrim(s.name)));
  passed := not exists (select 1 from metrc_strains s
            where f_strip_product_form(s.name) is distinct from btrim(s.name));
  return next;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_yesno()
 RETURNS TABLE(half text, case_in text, expected text, got text, passed boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v boolean;
begin
  -- positive: both encodings, both directions, and the casing/padding seen live
  for r in select * from (values
      ('True','t'),('Yes','t'),('yes','t'),('  TRUE ','t'),('Pass','t'),('1','t'),
      ('False','f'),('No','f'),('no','f'),('FALSE','f'),('Fail','f'),('0','f')
    ) v(a,b)
  loop
    half := 'positive - must decode'; case_in := r.a; expected := r.b;
    v := f_yesno(r.a); got := case when v then 't' when not v then 'f' else 'null' end;
    passed := (got = r.b); return next;
  end loop;

  -- negative: anything it was never taught must come back NULL, never false.
  -- Guessing false on an unknown is how a failed test becomes a pass.
  for r in select * from (values ('maybe'),('N/A'),('pending'),(''),('  '),('Not Tested')) v(a)
  loop
    half := 'negative - unknown must be NULL, not false'; case_in := quote_literal(r.a);
    expected := 'null'; v := f_yesno(r.a);
    got := case when v is null then 'null' when v then 't' else 'f' end;
    passed := (v is null); return next;
  end loop;

  half := 'negative - unknown must be NULL, not false'; case_in := 'NULL input';
  expected := 'null'; v := f_yesno(null);
  got := case when v is null then 'null' when v then 't' else 'f' end;
  passed := (v is null); return next;

  -- derived: every value actually present in the live column must decode.
  -- If a future import introduces a third encoding, this fires on its own.
  for r in
    select distinct overall_passed a from metrc_rpt_lab_results
    where overall_passed is not null and f_yesno(overall_passed) is null
  loop
    half := 'derived - every live value must decode'; case_in := r.a;
    expected := 'decodes'; got := 'NULL - unrecognised encoding'; passed := false;
    return next;
  end loop;

  half := 'derived - every live value must decode';
  case_in := format('%s distinct values live in overall_passed',
              (select count(distinct overall_passed) from metrc_rpt_lab_results));
  expected := 'all decode';
  got := format('%s undecodable',
          (select count(distinct overall_passed) from metrc_rpt_lab_results
            where overall_passed is not null and f_yesno(overall_passed) is null));
  passed := not exists (select 1 from metrc_rpt_lab_results
            where overall_passed is not null and f_yesno(overall_passed) is null);
  return next;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_send_alert_emails(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; v_enabled boolean; v_fn text; v_addresses int; v_queued int; v_dispatched int := 0;
begin
  select value into cfg from configurations where key = 'alert_email';
  v_enabled := coalesce((cfg->>'enabled')::boolean, false);
  v_fn      := nullif(btrim(coalesce(cfg->>'send_function','')), '');

  select count(*) into v_queued from alert_outbox
   where channel='email' and sent_at is null and dispatched_at is null
     and resolved_at is null and email_suppressed_at is null;

  /* The INTERNAL view. Reading the gated one here is the bug this migration fixes. */
  select count(*) into v_addresses from v_alert_email_recipients_internal;

  if not v_enabled then
    return jsonb_build_object('ok', true, 'dispatched', 0, 'queued', v_queued,
      'state', 'email_not_configured', 'why', cfg->>'why_off', 'to_turn_on', cfg->>'to_turn_on');
  end if;
  if v_fn is null then
    return jsonb_build_object('ok', false, 'dispatched', 0, 'queued', v_queued,
      'state', 'enabled_but_no_send_function',
      'why', 'alert_email.enabled is true but send_function is not set, so there is nothing to call.');
  end if;
  if v_addresses = 0 then
    return jsonb_build_object('ok', false, 'dispatched', 0, 'queued', v_queued,
      'state', 'enabled_but_no_addresses',
      'why', 'No active recipient has an email address. Add rows to alert_recipient.');
  end if;

  with to_send as (
    select o.id, o.subject, o.body, o.severity, r.email, r.full_name
    from alert_outbox o
    join v_alert_email_recipients_internal r on r.role = o.role
    where o.channel='email' and o.sent_at is null and o.dispatched_at is null
      and o.resolved_at is null and o.email_suppressed_at is null
    order by case o.severity when 'critical' then 1 when 'elevated' then 2 else 3 end, o.created_at
    limit p_limit
  ), called as (
    select t.id, tg_call_function(v_fn, jsonb_build_object(
             'to', t.email, 'name', t.full_name, 'subject', t.subject,
             'body', t.body, 'severity', t.severity)) as request_id
    from to_send t
  ), stamped as (
    update alert_outbox o
       set dispatched_at = now(), send_request_id = c.request_id
      from called c where c.id = o.id
      returning 1)
  select count(*) into v_dispatched from stamped;

  return jsonb_build_object('ok', true, 'dispatched', v_dispatched,
    'queued_before', v_queued, 'addresses', v_addresses,
    'state', 'dispatched - not yet confirmed delivered',
    'next', 'tg_confirm_alert_emails() marks them sent only when the provider answers 2xx.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sentinel_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; r record; n integer := 0; problems text := '';
begin
  insert into watchdog_runs default values returning id into v_run;

  for r in select * from f_sentinel_check() where verdict <> 'ok' loop
    n := n + 1;
    problems := problems || r.label || ' (' || r.verdict ||
      case when r.silent_minutes is not null
           then ', silent ' || r.silent_minutes || 'm of ' || r.allowed_minutes || 'm allowed'
           else '' end || '); ';
  end loop;

  if n > 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run, 'sentinel_source_silent', 'critical',
      n || ' monitored source(s) have STOPPED SPEAKING: ' || rtrim(problems, '; '),
      'sentinel_expectation vs the live run tables', 'Whoever owns the silent job',
      'Since the source last reported',
      'Silence is the failure every other check misses. A dead job reports nothing, and nothing looks exactly like nothing wrong - the Metrc sync was dead for 7 hours 16 minutes on 7 Aug 2026 while every dashboard reported success. This is the only check that treats absence of news as news.',
      'Compared each source''s most recent run against its owner-set max_silence_minutes in sentinel_expectation.',
      'Find why the job stopped. Do NOT simply restart it and close this - a job that died once with no alarm will die again. Record the cause in issue_decisions.',
      rtrim(problems, '; '), n, 'settings', 'sentinel silent dead job heartbeat')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity = excluded.severity, what = excluded.what,
      the_arithmetic = excluded.the_arithmetic, record_count = excluded.record_count,
      run_id = excluded.run_id;
  end if;

  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_default_dashboard(p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from user_dashboard where user_id = auth.uid() and dashboard_key = p_key)
    then raise exception 'You have no dashboard "%".', p_key; end if;
  update user_dashboard set is_default = false where user_id = auth.uid() and is_default;
  update user_dashboard set is_default = true  where user_id = auth.uid() and dashboard_key = p_key;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_my_key(p_provider text, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into ai_user_access (user_id, own_key_provider, own_key, enabled, updated_at)
  values (auth.uid(), nullif(p_provider,''), nullif(p_key,''), true, now())
  on conflict (user_id) do update
    set own_key_provider = nullif(p_provider,''), own_key = nullif(p_key,''), updated_at = now();
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_secret(p_key text, p_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_key text := upper(btrim(coalesce(p_key, '')));
        v_val text := btrim(coalesce(p_value, ''));
begin
  if not exists (select 1 from app_users u
                  where u.user_id = auth.uid() and u.role in ('owner', 'executive')) then
    raise exception 'Only an owner or an executive can set a key.' using errcode = '42501';
  end if;
  if v_key = '' then
    raise exception 'A key needs a name.' using errcode = '22023';
  end if;
  if v_val = '' then
    raise exception 'Nothing was pasted. To remove a key use the Remove button, which says so.'
      using errcode = '22023';
  end if;

  insert into app_secrets (key, value, value_is_set, value_last4, value_set_at, updated_by, updated_at)
  values (v_key, v_val, true,
          case when length(v_val) >= 12 then right(v_val, 4) end,
          now(), auth.uid(), now())
  on conflict (key) do update
     set value = excluded.value, value_is_set = true,
         value_last4 = excluded.value_last4, value_set_at = now(),
         updated_by = auth.uid(), updated_at = now();

  insert into audit_events (actor, entity, entity_id, action, new_value)
  values (auth.uid(), 'app_secrets', v_key, 'set', jsonb_build_object('set', true));
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_sync_system()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.system is null or new.system = 'metrc' then
    select m.system into new.system from sync_system_map m
     where new.endpoint = m.endpoint_pattern
        or new.endpoint like m.endpoint_pattern || '%';
    if new.system is null then new.system := 'metrc'; end if;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_shift_schedule_after_disruption(p_room text, p_from_date date, p_shift_days integer, p_note text, p_reason_code text DEFAULT NULL::text, p_cascade boolean DEFAULT true)
 RETURNS TABLE(room text, was date, now_planned date, revision_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_role text; v_first bigint; d record; v_prev date; v_id bigint;
begin
  select u.role::text into v_role from app_users u where u.user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive','admin','manager') then
    raise exception 'Shifting a schedule after a disruption needs owner, executive, admin or manager.'
      using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_note,''))) < 10 then
    raise exception
      'Say what happened. This resets what every downstream pull is measured against, so the reason '
      'is the only thing separating it from moving the goalposts.' using errcode = '22023';
  end if;
  if p_shift_days = 0 then
    raise exception 'A shift of zero days changes nothing.';
  end if;

  for d in
    select distinct hs.harvest_date, hs.flower_room
      from harvest_schedule hs
     where hs.flower_room = p_room
       and hs.harvest_date >= p_from_date
       and (p_cascade or hs.harvest_date = p_from_date)
     order by hs.harvest_date
  loop
    select coalesce(
             (select r.new_date from schedule_revision r
               where r.room = d.flower_room and r.original_date = d.harvest_date
                 and r.superseded_by is null
               order by r.revised_at desc limit 1),
             d.harvest_date)
      into v_prev;

    insert into schedule_revision
      (event_type, room, original_date, previous_date, new_date, reason_code, note,
       revised_by, resets_baseline, disruption_ref)
    values ('Pull', d.flower_room, d.harvest_date, v_prev, v_prev + p_shift_days, p_reason_code,
            btrim(p_note) || case when d.harvest_date <> p_from_date
                                  then ' [shifted by the disruption of ' || p_from_date || ']'
                                  else '' end,
            coalesce(v_role,'unrecorded'), true, v_first)
    returning id into v_id;

    if v_first is null then
      v_first := v_id;
      update schedule_revision set disruption_ref = v_id where id = v_id;
    end if;

    room := d.flower_room; was := v_prev; now_planned := v_prev + p_shift_days;
    revision_id := v_id;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_snapshot_dashboards()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  refresh materialized view concurrently mv_department_dashboard_base;
  refresh materialized view mv_forensic_sales;
  refresh materialized view concurrently mv_tag_certificate;
  refresh materialized view concurrently mv_tag_harvest_link;
  refresh materialized view concurrently mv_harvest_certificate;
  insert into dashboard_snapshots (taken_on, department, kpi, value, unit)
  select current_date, department, kpi, value, unit from mv_department_dashboard
  on conflict (taken_on, department, kpi) do update set value = excluded.value;
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_snapshot_inventory(p_day date DEFAULT NULL::date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := coalesce(p_day, (now() at time zone 'America/New_York')::date); n int;
begin
  delete from inventory_snapshot where taken_on = d;   -- re-runnable for today only
  insert into inventory_snapshot
    (taken_on, license, tag, item_name, category, strain, quantity, uom, pounds,
     location, lab_state, packaged_on, origin, stock_status, source_state)
  select d, p.license, p.tag, p.item_name,
         p.raw #>> '{Item,ProductCategoryName}', p.raw #>> '{Item,StrainName}',
         p.quantity, p.uom,
         case when f_is_weight(p.uom) then f_to_pounds(p.quantity, p.uom) end,
         p.location, p.lab_testing_state, p.packaged_on,
         case when coalesce(p.raw->>'ItemFromFacilityLicenseNumber','')
                   = any (array['MC281714','MP281909']) then 'Grown by us' else 'Bought in' end,
         f_stock_status(p.source_state, p.finished), p.source_state
  from metrc_packages p
  where p.source_state <> 'inactive';   -- what was actually held that day
  get diagnostics n = row_count;
  return d::text || ': ' || n::text || ' packages recorded';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_snapshot_tile_drill(p_by text DEFAULT 'cron'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t0 timestamptz := clock_timestamp(); v_n int; v_bad int;
begin
  delete from tile_drill_result;
  insert into tile_drill_result (contract_key, page, tile_label, tile_value, drill_value,
                                 gap, verdict, computed_at, computed_ms)
  select contract_key, page, tile_label, tile_value, drill_value, gap, verdict, now(),
         round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int
    from tg_check_tile_drill();

  select count(*), count(*) filter (where verdict <> 'AGREE') into v_n, v_bad
    from tile_drill_result;

  return jsonb_build_object('contracts', v_n, 'disagree', v_bad, 'by', p_by,
    'ms', round(extract(epoch from (clock_timestamp() - t0)) * 1000)::int);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_stamp_facility_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid()::text, new.updated_by);
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_stamp_import_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.period_start is null then
    select tg_import_period(t.cadence, new.imported_at) into new.period_start
    from metrc_report_types t where t.report_key = new.report_type;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sweep_discrepancies()
 RETURNS TABLE(out_class text, out_found integer, out_newly_raised integer, out_resolved integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_new int; v_res int;
begin
  create temp table _raw on commit drop as
  select 'strain'::text as class,
         'strain:' || d.package_tag || ':' || d.manifest_number as discrepancy_key,
         'Package ' || d.package_tag || ' on manifest ' || d.manifest_number as subject,
         'Metrc item name'::text as source_a, d.item_name_says as source_a_says,
         'Metrc strain field'::text as source_b, d.strain_column_says as source_b_says,
         'COA — the certificate names the strain that was tested'::text as resolved_by_doc,
         (select dc.storage_path from metrc_documents dc
           where dc.package_tag = d.package_tag and dc.doc_type ilike '%coa%' limit 1) as document_link
  from v_strain_conflicts d
  union all
  select 'ownership', 'ownership:' || o.tag,
         'Package ' || o.tag || ' — ' || left(o.item_name, 50),
         'Platform item field', case when o.platform_says_ours then 'ours' else 'third party' end,
         'Package lineage in Metrc',
         case when o.lineage_says_ours then 'ours'
              else 'third party — ' || coalesce(o.origins->>0,'origin not named') end,
         'Inbound manifest — it names who shipped it to us',
         (select dm.storage_path from metrc_documents dm
           where dm.manifest_number = (o.arrived_on->>0) and dm.doc_type ilike '%manifest%' limit 1)
  from v_ownership_misattribution o where o.verdict <> 'agrees'
  union all
  select 'missing_contents', 'contents:' || g.manifest_number,
         'Manifest ' || g.manifest_number || ' ' || g.direction || ' — '
           || coalesce(g.recipient, g.shipper, 'counterparty not named'),
         'Metrc transfer record', coalesce(g.packages_metrc_says::text,'?') || ' packages on board',
         'Package line export', '0 lines held',
         'Manifest PDF — it lists every package on the shipment',
         g.manifest_document
  from v_manifest_line_gaps g
  union all
  -- NEW: the verification framework's own disagreements.
  select 'verification', 'verify:' || v.check_key,
         v.title || ' — ' || round(l.pct_apart, 2) || '% apart',
         v.source_a_label, l.value_a::text,
         v.source_b_label, l.value_b::text,
         coalesce(v.what_it_proves, 'Two derivations of the same fact disagree.'),
         null
  from verification_checks v
  join lateral (
    select value_a, value_b, pct_apart, verdict
    from verification_runs r where r.check_key = v.check_key
    order by r.ran_at desc limit 1
  ) l on true
  where l.verdict ilike '%disagree%';

  create temp table _cur on commit drop as
  select distinct on (discrepancy_key) * from _raw order by discrepancy_key, document_link nulls last;

  insert into discrepancy_register as r
    (discrepancy_key, class, subject, source_a, source_a_says, source_b, source_b_says,
     resolved_by_doc, document_link, first_seen, last_seen)
  select c.discrepancy_key, c.class, c.subject, c.source_a, c.source_a_says,
         c.source_b, c.source_b_says, c.resolved_by_doc, c.document_link, now(), now()
  from _cur c
  on conflict (discrepancy_key) do update
    set last_seen = now(),
        document_link = coalesce(excluded.document_link, r.document_link),
        source_a_says = excluded.source_a_says,
        source_b_says = excluded.source_b_says,
        subject       = excluded.subject,
        resolved_at = null,
        resolution_note = case when r.resolved_at is not null
          then 'Reopened ' || to_char(now(),'DD Mon HH24:MI') || ' — it disagreed again. Previous note: '
            || coalesce(r.resolution_note,'(none)') else r.resolution_note end;
  get diagnostics v_new = row_count;

  update discrepancy_register r
     set resolved_at = now(), resolved_by = coalesce(r.resolved_by,'sweep'),
         resolution_note = coalesce(r.resolution_note,
           'The sources agree again as at ' || to_char(now(),'DD Mon YYYY HH24:MI')
           || '. Recorded, not deleted — this is the audit trail of what was wrong and when.')
   where r.resolved_at is null
     and not exists (select 1 from _cur c2 where c2.discrepancy_key = r.discrepancy_key);
  get diagnostics v_res = row_count;

  return query select c3.class::text, count(*)::int, v_new, v_res from _cur c3 group by c3.class;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sweep_unknowns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v int := 0;
begin
  insert into suppliers (origin_license, supplier_name, first_received)
  select p.raw->>'ItemFromFacilityLicenseNumber', min(nullif(p.raw->>'ReceivedFromFacilityName','')), min(p.packaged_on)
  from metrc_packages p
  where coalesce(p.raw->>'ItemFromFacilityLicenseNumber','') <> ''
  group by 1
  on conflict (origin_license) do nothing;

  update suppliers set bought_as='our own licence', set_by='system', set_at=now()
  where origin_license in ('MC281714','MP281909') and bought_as='not yet set';

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked, exposure_lb)
  select 'supplier_intent:'||s.origin_license, 'Purchasing',
    'What do we buy from '||coalesce(s.supplier_name,'licence '||s.origin_license)||'? Sound material, failed material bought at a discount to remediate, or biomass for extraction?',
    'Until this is answered the platform cannot tell a supplier quality problem from a deliberate discounted purchase, so it will not count either as a loss and every cost figure on that material is unreliable.',
    'Loss reporting and cost per pound on '||coalesce(s.supplier_name, s.origin_license),
    (select round(sum(pounds),1) from v_stock_on_hand v where v.origin_license = s.origin_license)
  from suppliers s where s.bought_as = 'not yet set'
  on conflict (question_key) do update set last_seen=now(), exposure_lb=excluded.exposure_lb;

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked, exposure_lb)
  select 'supplier_unnamed:'||v.origin_license, 'Purchasing',
    'Who is licence '||v.origin_license||'? We hold material from them with no supplier name recorded.',
    'We cannot raise a quality issue, negotiate, or account for material when we do not know who sold it to us.',
    'Supplier accountability', round(sum(v.pounds),1)
  from v_stock_on_hand v
  where v.origin <> 'Grown by us' and coalesce(v.supplier,'') in ('','(supplier not recorded)')
  group by v.origin_license
  on conflict (question_key) do update set last_seen=now(), exposure_lb=excluded.exposure_lb;

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked)
  select 'factor:'||c.key, 'Measurement',
    'What is the real value for "'||c.label||'"? It is on a default of '||c.value||' '||coalesce(c.unit,'')||'.',
    c.what_it_means, 'Every figure calculated from this factor'
  from conversion_factors c where c.set_by like 'default%'
  on conflict (question_key) do update set last_seen=now();

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked, exposure_lb)
  select 'limit:'||l.stream, 'Inventory control',
    'What is the maximum '||l.stream||' we should ever hold, in pounds?',
    'Without a ceiling nothing can warn us we are over-stocked or holding material too long.',
    'Over-stock alerting on '||l.stream,
    (select round(sum(pounds),1) from v_stock_on_hand v where v.stream = l.stream)
  from storage_limits l where l.max_lb is null
  on conflict (question_key) do update set last_seen=now(), exposure_lb=excluded.exposure_lb;

  update open_questions q set status='answered', answered_at=now()
  where q.status='open' and (
    (q.question_key like 'supplier_intent:%' and exists (select 1 from suppliers s where 'supplier_intent:'||s.origin_license=q.question_key and s.bought_as<>'not yet set'))
    or (q.question_key like 'factor:%' and exists (select 1 from conversion_factors c where 'factor:'||c.key=q.question_key and c.set_by not like 'default%'))
    or (q.question_key like 'limit:%' and exists (select 1 from storage_limits l where 'limit:'||l.stream=q.question_key and l.max_lb is not null))
  );

  select count(*) into v from open_questions where status='open';
  return v;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sync_review()
 RETURNS TABLE(raised text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rec record; v_run_id bigint;
begin
  insert into watchdog_runs (ran_at, ran_by, notes)
  values (now(), 'tg_sync_review', 'automated review of sync health')
  returning id into v_run_id;

  for rec in
    select endpoint, license, count(*) att,
           count(*) filter (where status='error') err,
           max(left(error,160)) last_err
    from metrc_sync_runs
    where started_at > now() - interval '24 hours'
    group by 1,2
    having count(*) filter (where status='error')::numeric / nullif(count(*),0) > 0.2
  loop
    insert into watchdog_findings
      (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
       when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic)
    values (v_run_id, 'sync-failing:'||rec.endpoint||':'||coalesce(rec.license,'-'),
      case when rec.err = rec.att then 'critical' else 'elevated' end,
      'Sync "'||rec.endpoint||'" is failing on licence '||coalesce(rec.license,'?'),
      'Metrc sync · '||rec.endpoint, 'Vincent',
      (select min(started_at)::text from metrc_sync_runs m
        where m.endpoint=rec.endpoint and m.status='error'),
      case when rec.err = rec.att
        then 'Every single run failed. Whatever this endpoint feeds is stale or empty, and no page will say so.'
        else 'Partial failure means the data is incomplete in ways nothing else will reveal.' end,
      'Reviewed metrc_sync_runs over the last 24 hours and compared errors to attempts.',
      case when rec.last_err ilike '%401%'
        then 'Metrc is refusing the credentials. Check the API key is authorised for this licence AND this endpoint - Metrc permissions are per endpoint, not just per licence.'
        else 'Read the error text and fix the cause. Do not disable the sync - a disabled sync is a silent one.' end,
      rec.err||' of '||rec.att||' runs failed in 24 hours = '
        ||round(100.0*rec.err/rec.att)||' percent. Last error: '||coalesce(rec.last_err,'none'))
    on conflict do nothing;
    raised := 'sync failing'; detail := rec.endpoint||' / '||coalesce(rec.license,'-'); return next;
  end loop;

  for rec in
    select display_name, status, agent_key from v_agent_health
    where status in ('OVERDUE','NEVER RAN') and enabled
  loop
    insert into watchdog_findings
      (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
       why_it_matters, how_it_was_detected, what_to_do)
    values (v_run_id, 'agent-silent:'||rec.agent_key,
      case when rec.status='NEVER RAN' then 'critical' else 'elevated' end,
      rec.display_name||' — '||rec.status,
      'Agent registry · '||rec.agent_key, 'Vincent',
      'An agent that has stopped looks exactly like an agent with nothing to report. Silence is the failure we cannot see.',
      'Compared each agent''s last run against the interval declared in agent_registry.',
      'Find out whether it is broken or was switched off deliberately. If deliberate, disable it in agent_registry so it stops reporting as overdue.')
    on conflict do nothing;
    raised := rec.status; detail := rec.display_name; return next;
  end loop;

  for rec in
    select endpoint, license, count(*) n from metrc_sync_runs
    where started_at > now() - interval '24 hours'
      and status='ok' and coalesce(records,0)=0
    group by 1,2 having count(*) >= 5
  loop
    insert into watchdog_findings
      (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
       why_it_matters, how_it_was_detected, what_to_do)
    values (v_run_id, 'sync-empty:'||rec.endpoint||':'||coalesce(rec.license,'-'), 'watch',
      'Sync "'||rec.endpoint||'" reports success but returns no records',
      'Metrc sync · '||rec.endpoint, 'Vincent',
      'A sync that succeeds with nothing in it reads as healthy on every dashboard. It may be correct - or it may be pointed at the wrong window.',
      'Counted runs in the last 24 hours with status ok and zero records.',
      'Confirm there genuinely is nothing new. If there should be, check the date window and the licence.')
    on conflict do nothing;
    raised := 'sync empty'; detail := rec.endpoint; return next;
  end loop;

  update watchdog_runs w
     set findings_raised = (select count(*) from watchdog_findings f where f.run_id = v_run_id)
   where w.id = v_run_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_task_create(p_title text, p_assignee uuid DEFAULT NULL::uuid, p_due_on date DEFAULT NULL::date, p_priority text DEFAULT 'normal'::text, p_list_id uuid DEFAULT NULL::uuid, p_space_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_source_view text DEFAULT NULL::text, p_source_kpi text DEFAULT NULL::text, p_source_value numeric DEFAULT NULL::numeric, p_source_unit text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_title is null or btrim(p_title) = '' then
    raise exception 'A task needs a title somebody could act on.';
  end if;

  insert into tasks (title, description, status, priority, assignee_employee_id, due_on,
                     list_id, space_id, created_by,
                     source_view, source_kpi, source_value, source_unit, source_snapshot)
  values (btrim(p_title), nullif(btrim(coalesce(p_description,'')),''), 'open',
          coalesce(nullif(btrim(coalesce(p_priority,'')),''),'normal'),
          p_assignee, p_due_on, p_list_id, p_space_id, auth.uid(),
          p_source_view, p_source_kpi, p_source_value, p_source_unit,
          case when p_source_kpi is not null
               then jsonb_build_object('kpi', p_source_kpi, 'value', p_source_value,
                                       'unit', p_source_unit, 'captured_at', now())
          end)
  returning id into v_id;

  insert into task_activity (task_id, what, new_value) values (v_id, 'created', btrim(p_title));
  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_task_from_dashboard(p_title text, p_description text, p_department text, p_kpi text, p_value numeric, p_unit text, p_drill text, p_assignee bigint, p_due date, p_priority text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if coalesce(length(trim(p_title)),0) < 5 then
    raise exception 'A task needs a title of at least five characters.';
  end if;
  insert into tasks (title, description, status, priority, assignee_employee_id, due_on,
                     department, source_view, source_kpi, source_value, source_unit,
                     source_snapshot, created_by)
  values (p_title, p_description, 'open', coalesce(p_priority,'normal'), p_assignee, p_due,
          p_department, p_drill, p_kpi, p_value, p_unit,
          jsonb_build_object('kpi',p_kpi,'value',p_value,'unit',p_unit,'department',p_department,
                             'captured_at', now(), 'drill', p_drill),
          auth.uid())
  returning id into v_id;
  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$
;
CREATE OR REPLACE FUNCTION public.tg_trace(p_term text)
 RETURNS TABLE(event_date date, phase text, event text, subject text, identifier text, quantity numeric, uom text, location text, status text, counterparty text, document_link text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$                               -- call it sees the same chain
begin
  return query
  select pl.planted_on, '1 Plant', 'Plant tagged in ' || coalesce(pl.room,'(no room)'),
    coalesce(pl.strain,'(no strain)'), pl.tag, 1::numeric, 'plant', pl.room,
    case pl.source_state when 'inactive' then 'Harvested or retired' else initcap(pl.source_state) end,
    null::text, null::text
  from metrc_plants pl
  where pl.tag ilike '%'||p_term||'%' or pl.strain ilike '%'||p_term||'%' or pl.room ilike '%'||p_term||'%'
  union all
  select pb.planted_on, '1 Plant', 'Batch started: ' || pb.name, coalesce(pb.strain,'(no strain)'), pb.name,
    coalesce(pb.count,0)::numeric, 'plants', 'Propagation', initcap(coalesce(pb.source_state,'')), null, null
  from metrc_plant_batches pb
  where pb.name ilike '%'||p_term||'%' or pb.strain ilike '%'||p_term||'%'
  union all
  select h.harvest_start, '2 Harvest', 'Takedown: ' || h.name,
    coalesce(h.raw->>'SourceStrainNames', h.name), h.name,
    coalesce((h.raw->>'TotalWetWeight')::numeric,0), coalesce(h.raw->>'UnitOfWeightName','g'),
    coalesce(h.raw->>'DryingLocationName','(no room)'),
    coalesce((h.raw->>'PlantCount'),'0') || ' plants harvested', null, null
  from metrc_harvests h
  where h.name ilike '%'||p_term||'%' or coalesce(h.raw->>'SourceStrainNames','') ilike '%'||p_term||'%'
     or coalesce(h.raw->>'DryingLocationName','') ilike '%'||p_term||'%'
  union all
  select h.harvest_start, '3 Loss', 'Waste recorded against ' || h.name,
    coalesce(h.raw->>'SourceStrainNames', h.name), h.name,
    coalesce((h.raw->>'TotalWasteWeight')::numeric,0), coalesce(h.raw->>'UnitOfWeightName','g'),
    coalesce(h.raw->>'DryingLocationName','(no room)'), 'Waste', null, null
  from metrc_harvests h
  where (h.name ilike '%'||p_term||'%' or coalesce(h.raw->>'SourceStrainNames','') ilike '%'||p_term||'%')
    and coalesce((h.raw->>'TotalWasteWeight')::numeric,0) > 0
  union all
  select p.packaged_on, '4 Package', 'Package created: ' || coalesce(p.item_name,'(unnamed)'),
    coalesce(nullif(p.raw->>'SourceHarvestNames',''),'(no source harvest)'), p.tag,
    coalesce(p.quantity,0), coalesce(p.uom,'ea'), coalesce(p.location,'(no location)'),
    case when (p.raw->>'IsOnHold')::boolean then 'ON HOLD'
         when p.source_state='intransit' then 'In transit'
         when p.source_state='inactive' then 'Closed or sold'
         else coalesce(p.lab_testing_state,'In inventory') end,
    null, null
  from metrc_packages p
  where p.tag ilike '%'||p_term||'%' or coalesce(p.item_name,'') ilike '%'||p_term||'%'
     or coalesce(p.raw->>'SourceHarvestNames','') ilike '%'||p_term||'%'
     or coalesce(p.location,'') ilike '%'||p_term||'%'
  union all
  -- BOUGHT IN: where it came from, taken off the inbound manifest. For third-party
  -- material this IS the origin - the grow record sits with the supplier.
  select (p.raw->>'ReceivedDateTime')::date, '2 Harvest',
    'Bought in from ' || coalesce(nullif(p.raw->>'ItemFromFacilityName',''),
                                  nullif(p.raw->>'ReceivedFromFacilityName',''),'(supplier not named)'),
    'Origin is the supplier, not our grow. Certificate and manifest below are its history.',
    coalesce(nullif(p.raw->>'ReceivedFromManifestNumber',''), p.tag),
    coalesce(p.quantity,0), coalesce(p.uom,'ea'), coalesce(p.location,''),
    'BOUGHT IN under licence ' || coalesce(p.raw->>'ItemFromFacilityLicenseNumber','(not recorded)'),
    coalesce(nullif(p.raw->>'ItemFromFacilityName',''), nullif(p.raw->>'ReceivedFromFacilityName','')),
    md.download_url
  from metrc_packages p
  left join lateral (select * from metrc_documents m where m.doc_type='manifest'
      and m.manifest_number = nullif(p.raw->>'ReceivedFromManifestNumber','') limit 1) md on true
  where (p.tag ilike '%'||p_term||'%')
    and coalesce(p.raw->>'ItemFromFacilityLicenseNumber','') <> all (array['MC281714','MP281909'])
  union all
  -- TEST SCORES: the headline numbers, not every analyte
  select r.result_date, '5 Laboratory', 'RESULT — ' || r.test_name,
    coalesce(r.lab_facility,'(laboratory not recorded)'), r.package_tag,
    r.result, coalesce(nullif(r.units,''),'%'), coalesce(r.lab_facility,''),
    case when r.passed is true then 'Passed' when r.passed is false then 'FAILED' else 'Recorded' end,
    r.lab_facility,
    (select d.download_url from metrc_documents d
      where d.doc_type='coa' and d.metrc_id = r.document_file_id and d.download_url is not null limit 1)
  from metrc_lab_results r
  where r.package_tag ilike '%'||p_term||'%'
    and (r.test_name ilike 'Total THC%' or r.test_name ilike 'Total CBD%'
         or r.test_name ilike 'Total Terpenes%' or r.test_name ilike 'Total Cannabinoids%')
    and r.test_name not ilike '%Retest%'
  union all
  -- CERTIFICATE on file, as its own event with the download
  select d.fetched_at::date, '5 Laboratory', 'Certificate of Analysis on file',
    coalesce(lr.lab_facility,'(laboratory not recorded)'), d.package_tag,
    null::numeric, '', coalesce(lr.lab_facility,''),
    'Click Open to download, print or send', lr.lab_facility, d.download_url
  from metrc_documents d
  left join lateral (select * from metrc_lab_results r2 where r2.document_file_id = d.metrc_id limit 1) lr on true
  where d.doc_type='coa' and d.download_url is not null and d.package_tag ilike '%'||p_term||'%'
  union all
  -- MANIFESTS, in and out. Outgoing is the sale.
  select t.created_on, '6 Transfer',
    case when t.direction='outgoing' then 'SOLD — manifest ' || t.manifest_number
         else 'Received on manifest ' || t.manifest_number end,
    coalesce(t.recipient, t.shipper, '(counterparty not recorded)'), t.manifest_number,
    coalesce((t.raw->>'PackageCount')::numeric,0), 'packages',
    coalesce(t.shipper,''),
    case when t.direction='outgoing'
         then 'Sold to ' || coalesce(t.recipient,'(customer not recorded)')
              || coalesce(' · invoice ' || nullif(t.raw->'_delivery'->>'InvoiceNumber',''),'')
         else initcap(t.direction) end,
    coalesce(t.recipient, t.shipper),
    coalesce(md2.download_url,
             case when t.raw->>'Id' is not null
                  then 'https://ma.metrc.com/reports/transfers/'||(t.raw->>'Id')||'/manifest' end)
  from metrc_transfers t
  left join lateral (select * from metrc_documents m2 where m2.doc_type='manifest'
      and m2.manifest_number = t.manifest_number and m2.download_url is not null limit 1) md2 on true
  where t.manifest_number ilike '%'||p_term||'%'
     or coalesce(t.recipient,'') ilike '%'||p_term||'%' or coalesce(t.shipper,'') ilike '%'||p_term||'%'
     or exists (select 1 from metrc_packages p3
                where (p3.tag ilike '%'||p_term||'%' or coalesce(p3.raw->>'SourceHarvestNames','') ilike '%'||p_term||'%')
                  and t.raw::text like '%'||p3.tag||'%')
     or exists (select 1 from metrc_packages p4
                where p4.tag ilike '%'||p_term||'%'
                  and nullif(p4.raw->>'ReceivedFromManifestNumber','') = t.manifest_number)
  union all
  select a.created_at::date, '7 Allocation', 'Requested by ' || coalesce(a.requester_name,'someone') || ': ' || a.material_name,
    a.material_name, 'Request #' || a.request_no, a.quantity, a.uom, a.destination,
    upper(a.status) || case when a.decider_name is not null then ' by ' || a.decider_name else '' end
      || case when a.decision_reason is not null then ' - ' || a.decision_reason else '' end,
    a.decider_name, null
  from allocation_requests a
  where a.material_name ilike '%'||p_term||'%' or coalesce(a.source_ref,'') ilike '%'||p_term||'%'
     or coalesce(a.strain,'') ilike '%'||p_term||'%'
  order by 1 nulls last, 2;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_track_finding_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  insert into finding_state_history (finding_key, from_state, to_state, note, changed_by)
  values (new.finding_key, case when tg_op='UPDATE' then old.state end,
          new.state, new.note, new.changed_by);
  new.changed_at := now();
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_track_rule_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'UPDATE' and new.value is not distinct from old.value then
    return new;                       -- wording changed, not the number
  end if;
  update conversion_factor_history
     set valid_to = now(), superseded_by = coalesce(new.set_by,'unknown')
   where key = new.key and valid_to is null;
  insert into conversion_factor_history
    (key, value, unit, set_by, where_it_came_from, valid_from)
  values (new.key, new.value, new.unit, new.set_by, new.where_it_came_from, now());
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_transfers_missing_licence(p_limit integer DEFAULT 100)
 RETURNS TABLE(license text, manifest_number text, direction text, recipient text, raw jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.license, t.manifest_number, t.direction, t.recipient, t.raw
  from metrc_transfers t
  where coalesce(t.raw->'_delivery'->>'RecipientFacilityLicenseNumber',
                 t.raw->>'RecipientFacilityLicenseNumber') is null
  order by t.manifest_number
  limit p_limit;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_unpost_reconciliation(p_run uuid, p_by text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare run record; t record; r record; v_reversed int := 0; v_withdrawn int := 0;
        where_sql text; i int;
begin
  if coalesce(btrim(p_by),'') = '' then
    raise exception 'Who is unposting? A reversal with no name attached is not a decision.';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 15 then
    raise exception 'A reason of at least 15 characters is required to unpost. Reversing a posted reconciliation without saying why leaves the next reader guessing.';
  end if;

  select * into run from import_reconciliation_run where id = p_run;
  if not found then raise exception 'No reconciliation run %.', p_run; end if;
  if run.posted_at is null and not exists (
       select 1 from import_reconciliation where run_id = p_run and posted_at is not null) then
    raise exception 'Run % has nothing posted to reverse.', p_run;
  end if;

  select * into t from metrc_report_types where report_key = run.report_key;

  for r in select * from import_reconciliation where run_id = p_run and posted_at is not null loop
    where_sql := '';
    for i in 1 .. coalesce(array_length(t.key_cols,1), 0) loop
      where_sql := where_sql || case when i > 1 then ' and ' else '' end
                || format('%I = %L', t.key_cols[i], split_part(r.row_key, '|', i));
    end loop;

    -- Put the value back to what we held before the posting. Only rows that were
    -- actually changed need restoring; a keep_ours posting never altered the data.
    if r.decision = 'accept_file' then
      execute format('update %I set %I = %L where %s',
                     r.target_table, r.field_name, r.value_we_hold, where_sql);
    end if;

    -- Overrides are WITHDRAWN, not deleted. The record that a decision was once
    -- made, and then reversed, is itself worth keeping (rule H2).
    update tg_overrides
       set active = false, withdrawn_at = now(), withdrawn_by = auth.uid()
     where target_table = r.target_table and row_key = r.row_key
       and field_name = r.field_name and active;
    get diagnostics i = row_count;
    v_withdrawn := v_withdrawn + i;

    update import_reconciliation set posted_at = null where id = r.id;
    v_reversed := v_reversed + 1;
  end loop;

  -- Any correction raised by the posting stays open. It records a real divergence
  -- that was observed; unposting does not un-observe it.
  update import_reconciliation_run
     set unposted_at = now(), unposted_by = p_by, posted_at = null, posted_by = null,
         note = coalesce(note || ' · ', '') || 'Unposted by ' || p_by || ': ' || btrim(p_reason)
   where id = p_run;

  return jsonb_build_object('ok', true, 'rows_reversed', v_reversed,
    'overrides_withdrawn', v_withdrawn,
    'note', 'Values restored and overrides withdrawn. Any metrc_corrections raised by the posting stay open - the divergence was real when it was seen, and unposting does not undo that.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verification_checks_sane()
 RETURNS TABLE(check_key text, problem text, severity text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_a numeric; v_b numeric;
  v_norm_a text; v_norm_b text;
  v_agrees int; v_runs int;
  v_err text;
begin
  create temp table if not exists _sane(check_key text, problem text, severity text, detail text)
    on commit drop;
  delete from _sane;

  for r in select * from verification_checks where enabled loop

    /* Normalise whitespace and case so formatting differences do not hide an identical pair. */
    v_norm_a := lower(regexp_replace(coalesce(r.source_a_sql,''), '\s+', ' ', 'g'));
    v_norm_b := lower(regexp_replace(coalesce(r.source_b_sql,''), '\s+', ' ', 'g'));

    /* S1 - CANNOT FAIL. Two identical sources always agree. Rule C0b, exactly. */
    if v_norm_a = v_norm_b and v_norm_a <> '' then
      insert into _sane values (r.check_key, 'CANNOT FAIL',
        'critical', 'Both sources run identical SQL, so the check always agrees and proves nothing.');
    end if;

    /* S2 - COMPLETENESS. A check nobody can interpret cannot be acted on (rule A3). */
    if coalesce(r.what_it_proves,'') = '' or coalesce(r.title,'') = '' or coalesce(r.owner,'') = '' then
      insert into _sane values (r.check_key, 'INCOMPLETE',
        'elevated', 'Missing title, what_it_proves or owner. A finding with no owner is a finding nobody closes.');
    end if;

    /* S3 - POPULATION MISMATCH. THE ERROR THIS PROJECT KEEPS MAKING.
       One side aggregates a quantity, the other counts rows. That is how
       lab-samples-shipped-vs-held reported 4,148%: sum(PackageCount) over manifests
       against count(*) of samples. Two populations, one comparison. */
    if (v_norm_a like '%sum(%' and v_norm_b like '%count(%' and v_norm_b not like '%sum(%')
    or (v_norm_b like '%sum(%' and v_norm_a like '%count(%' and v_norm_a not like '%sum(%') then
      insert into _sane values (r.check_key, 'POPULATION MISMATCH',
        'critical', 'One side SUMS a quantity and the other COUNTS rows. These are different populations '
          || 'unless every row carries exactly one unit. This is the error that produced a false 4,148% gap.');
    end if;

    /* S4 - TOLERANCE ON AN IDENTITY. "every", "exactly", "unique", "never" are absolutes.
       A percentage tolerance on one lets a real fault read green, as it did on 7 duplicate tags. */
    if coalesce(r.tolerance_pct,0) > 0
       and (lower(r.title) ~ '(exactly|unique|every|never|no )'
         or lower(coalesce(r.what_it_proves,'')) ~ 'tolerance 0') then
      insert into _sane values (r.check_key, 'TOLERANCE ON AN IDENTITY',
        'critical', 'Title or description states an absolute, but tolerance is ' || r.tolerance_pct
          || '%. An identity invariant is binary; a percentage lets a real fault read green.');
    end if;

    /* S5 - DOES IT ACTUALLY RUN? Both sides are executed. A check that errors is not a check,
       and until now nothing noticed - it would simply never write a run row. */
    begin
      execute r.source_a_sql into v_a;
    exception when others then
      v_err := sqlerrm;
      insert into _sane values (r.check_key, 'SOURCE A FAILS TO RUN', 'critical', left(v_err,180));
      v_a := null;
    end;
    begin
      execute r.source_b_sql into v_b;
    exception when others then
      v_err := sqlerrm;
      insert into _sane values (r.check_key, 'SOURCE B FAILS TO RUN', 'critical', left(v_err,180));
      v_b := null;
    end;

    /* S6 - NEVER RUN. Enabled, scheduled, and no run row has ever been written. */
    select count(*) into v_runs from verification_runs vr where vr.check_key = r.check_key;
    if v_runs = 0 then
      insert into _sane values (r.check_key, 'NEVER RUN',
        'elevated', 'Enabled but has never produced a run. A check that does not run enforces nothing.');
    end if;

    /* S7 - CANNOT PASS. Disagreed on every run and never once agreed. Either it is broken, or it
       is a standing fact that belongs at 'watch' severity where it will not read as a regression.
       Ten runs is enough to distinguish a persistent condition from a bad week. */
    if v_runs >= coalesce(f_rule('check_cannot_pass_min_runs'), 10)::int then
      select count(*) into v_agrees from verification_runs vr
        where vr.check_key = r.check_key and vr.verdict = 'agree';
      if v_agrees = 0 and r.severity in ('critical','elevated') then
        insert into _sane values (r.check_key, 'CANNOT PASS',
          'elevated', 'Has never agreed in ' || v_runs || ' runs while marked ' || r.severity
            || '. A permanent red teaches people to ignore the board. Fix it, or demote it to watch '
            || 'and say in what_it_proves that disagreement is expected.');
      end if;
    end if;

  end loop;

  return query select s.check_key, s.problem, s.severity, s.detail from _sane s
    order by case s.severity when 'critical' then 0 else 1 end, s.check_key;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verification_checks_sane_selftest()
 RETURNS TABLE(fixture text, expected_problem text, caught boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  fx constant text[][] := array[
    ['_fx_cannot_fail',  'CANNOT FAIL'],
    ['_fx_population',   'POPULATION MISMATCH'],
    ['_fx_tolerance',    'TOLERANCE ON AN IDENTITY'],
    ['_fx_broken_sql',   'SOURCE A FAILS TO RUN'],
    ['_fx_incomplete',   'INCOMPLETE']
  ];
  i int;
begin
  /* Inserted and removed inside this function. verification_checks is configuration, not a
     forensic table, so this leaves no permanent trace and violates no immutability rule (H2). */
  insert into verification_checks
   (check_key,title,what_it_proves,source_a_label,source_a_sql,source_b_label,source_b_sql,
    tolerance_pct,severity,owner,enabled,added_on)
  values
   ('_fx_cannot_fail','Fixture: identical sources','Both sides run the same SQL.',
     'A','select 1::numeric','B','select  1::NUMERIC',0,'elevated','fixture',true,current_date),
   ('_fx_population','Fixture: sum against count','One side sums, the other counts.',
     'A','select sum(1)::numeric','B','select count(*)::numeric from metrc_packages',0,'elevated','fixture',true,current_date),
   ('_fx_tolerance','Fixture: every package is unique exactly','Absolute wording, percentage tolerance.',
     'A','select 1::numeric','B','select 2::numeric',5,'elevated','fixture',true,current_date),
   ('_fx_broken_sql','Fixture: source does not run','Source A references nothing.',
     'A','select count(*)::numeric from table_that_does_not_exist','B','select 1::numeric',0,'elevated','fixture',true,current_date),
   ('_fx_incomplete','','','A','select 1::numeric','B','select 2::numeric',0,'elevated','',true,current_date)
  on conflict (check_key) do nothing;

  create temp table if not exists _fxres(k text, p text) on commit drop;
  delete from _fxres;
  insert into _fxres select s.check_key, s.problem from tg_verification_checks_sane() s
    where s.check_key like '\_fx\_%';

  delete from verification_checks where check_key like '\_fx\_%';

  for i in 1 .. array_length(fx,1) loop
    fixture := fx[i][1];
    expected_problem := fx[i][2];
    caught := exists (select 1 from _fxres r where r.k = fx[i][1] and r.p = fx[i][2]);
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verification_escalate()
 RETURNS TABLE(check_key text, action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_streak_start timestamptz; v_open boolean;
begin
  for r in
    select c.check_key, c.title, c.what_it_proves, c.severity, c.owner,
           c.tolerance_pct, c.measures_a_process, c.in_flight_rule,
           coalesce(c.settles_within, interval '0') as settles_within,
           c.source_a_label, c.source_b_label,
           lr.value_a, lr.value_b, lr.pct_apart, lr.verdict, lr.ran_at
      from verification_checks c
      join lateral (select * from verification_runs vr
                     where vr.check_key = c.check_key
                     order by vr.ran_at desc limit 1) lr on true
     where c.enabled
  loop
    -- Start of the CURRENT consecutive non-agreeing streak: the first disagreement after the
    -- last time this check agreed. A check that has never agreed streaks from its first run.
    select min(vr.ran_at) into v_streak_start
      from verification_runs vr
     where vr.check_key = r.check_key
       and upper(vr.verdict) <> 'AGREE'
       and vr.ran_at > coalesce((select max(a.ran_at) from verification_runs a
                                  where a.check_key = r.check_key and upper(a.verdict) = 'AGREE'),
                                '-infinity'::timestamptz);

    v_open := upper(r.verdict) <> 'AGREE'
              and (not coalesce(r.measures_a_process, false)
                   or now() - coalesce(v_streak_start, r.ran_at) > r.settles_within);

    if v_open then
      insert into watchdog_findings (
        fingerprint, severity, what, where_it_is, who_is_accountable, when_it_started,
        why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, record_count,
        search_text, cleared_at)
      values (
        'verify:' || r.check_key,
        r.severity,
        format('Verification check "%s" disagrees. %s says %s; %s says %s.',
               r.check_key, r.source_a_label, r.value_a, r.source_b_label, r.value_b),
        'verification_checks / verification_runs, check_key = ' || r.check_key,
        coalesce(nullif(r.owner, ''), 'Agent W'),
        v_streak_start,
        coalesce(nullif(r.what_it_proves, ''),
                 'Two independent derivations of the same figure do not match, so at least one is wrong.'),
        'tg_verify() ran the two SQL sources this check declares and compared them. '
        || 'tg_verification_escalate() raised this because the disagreement outlived its settling window.',
        'Derive both sides by hand and decide which one is wrong, then fix that source. '
        || 'Never widen tolerance_pct to make the check pass - that hides the defect instead of '
        || 'removing it. If the check itself is wrong, log it in check_defect and correct the check.',
        format('%s vs %s, %s%% apart against a tolerance of %s%%',
               r.value_a, r.value_b, round(coalesce(r.pct_apart, 0), 2), r.tolerance_pct),
        round(abs(coalesce(r.value_a, 0) - coalesce(r.value_b, 0)))::bigint,
        r.check_key || ' ' || coalesce(r.title, '') || ' verification disagreement',
        null)
      on conflict (fingerprint) where fingerprint is not null do update set
        severity        = excluded.severity,
        what            = excluded.what,
        the_arithmetic  = excluded.the_arithmetic,
        record_count    = excluded.record_count,
        when_it_started = excluded.when_it_started,
        observed_at     = now(),
        cleared_at      = null;
      return query select r.check_key, 'raised'::text;
    else
      update watchdog_findings
         set cleared_at = now()
       where fingerprint = 'verify:' || r.check_key and cleared_at is null;
      if found then
        return query select r.check_key, 'cleared'::text;
      end if;
    end if;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verify()
 RETURNS TABLE(check_key text, verdict text, value_a numeric, value_b numeric, pct_apart numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; a numeric; b numeric; diff numeric; pct numeric; v text; msg text; v_run bigint;
        t record;
begin
  insert into watchdog_runs (ran_at, ran_by, notes)
  values (now(), 'tg_verify', 'independent verification: two derivations per fact, plus every tile against its own drill')
  returning id into v_run;

  for c in select * from verification_checks where enabled order by check_key loop
    a := null; b := null; msg := null;
    begin
      execute c.source_a_sql into a;
      execute c.source_b_sql into b;
      diff := coalesce(a,0) - coalesce(b,0);
      pct  := case when coalesce(b,0)=0 and coalesce(a,0)=0 then 0
                   when coalesce(b,0)=0 then 100
                   else abs(diff)/abs(b)*100 end;
      v := case when pct <= c.tolerance_pct then 'agree' else 'DISAGREE' end;
    exception when others then
      v := 'error'; msg := left(sqlerrm,160); pct := null; diff := null;
    end;

    insert into verification_runs (check_key, value_a, value_b, difference, pct_apart, verdict, note)
    values (c.check_key, a, b, diff, pct, v, msg);

    if v <> 'agree' then
      insert into watchdog_findings
        (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
         why_it_matters, how_it_was_detected, what_to_do, the_arithmetic)
      values (v_run, 'verify:'||c.check_key,
        case when v='error' then 'elevated' else c.severity end,
        case when v='error' then c.title||' — the check itself failed to run'
             else c.title||' — the two sources disagree' end,
        'Verification · '||c.check_key, c.owner, c.what_it_proves,
        'Derived the same fact two independent ways and compared. '||c.source_a_label||' against '||c.source_b_label||'.',
        case when v='error'
          then 'The verification could not run: '||coalesce(msg,'?')||'. A check that cannot run proves nothing.'
          else 'Find out which source is right before anyone quotes either figure. Do not average them.' end,
        case when v='error' then 'check errored: '||coalesce(msg,'?')
             else c.source_a_label||' = '||coalesce(a::text,'null')||' · '
                  ||c.source_b_label||' = '||coalesce(b::text,'null')||' · apart by '
                  ||round(coalesce(pct,0),2)||'% (tolerance '||c.tolerance_pct||'%). '
                  ||'This is a reconciliation gap, NOT money at risk - it carries no dollar figure by design.' end)
      on conflict do nothing;
    end if;

    tg_verify.check_key := c.check_key; tg_verify.verdict := v;
    tg_verify.value_a := a; tg_verify.value_b := b;
    tg_verify.pct_apart := round(coalesce(pct,0),2);
    return next;
  end loop;

  -- ── EVERY TILE AGAINST ITS OWN DRILL — by CALLING the one definition ──────────
  -- Not a second copy of the logic. tg_check_tile_drill() owns the comparison and the
  -- verdict wording; v_tile_drill_status reads the same function, so the sweep and the
  -- screen cannot drift apart.
  for t in select * from tg_check_tile_drill() loop
    insert into verification_runs (check_key, value_a, value_b, difference, pct_apart, verdict, note)
    values ('tile:'||t.contract_key, t.tile_value, t.drill_value, t.gap,
            case when coalesce(t.drill_value,0) = 0 then null
                 else round(abs(coalesce(t.gap,0))/abs(t.drill_value)*100, 2) end,
            case when t.verdict like 'AGREE%' then 'agree'
                 when t.verdict like 'BROKEN%' then 'error' else 'DISAGREE' end,
            t.verdict);

    if t.verdict not like 'AGREE%' then
      insert into watchdog_findings
        (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
         why_it_matters, how_it_was_detected, what_to_do, the_arithmetic)
      values (v_run, 'tile:'||t.contract_key,
        case when t.verdict like 'BROKEN%' then 'elevated' else 'critical' end,
        t.page||' · '||t.tile_label||' — '||t.verdict,
        t.page||' · '||t.tile_label, 'Agent I',
        'A figure a manager can open to, that opens to something else, is worse than no figure: '
        'the drill is what makes a number checkable, and a wrong number that opens to a confident '
        'explanation of itself stops the reader looking.',
        'Ran the SQL behind the tile and, independently, the SQL that re-derives it by summing the '
        'rows the drill opens. NOTE: the drill side is the contract''s WRITTEN CLAIM about the '
        'drill, not a reading of the shipped page — see drill.published_target_matches_the_contract.',
        'Establish which side is right before the figure is quoted. Do not adjust the tolerance to '
        'make it agree.',
        'tile = '||coalesce(t.tile_value::text,'null')||' · drill = '
          ||coalesce(t.drill_value::text,'null')||' · gap '||coalesce(t.gap::text,'?'))
      on conflict do nothing;
    end if;

    tg_verify.check_key := 'tile:'||t.contract_key;
    tg_verify.verdict := case when t.verdict like 'AGREE%' then 'agree'
                              when t.verdict like 'BROKEN%' then 'error' else 'DISAGREE' end;
    tg_verify.value_a := t.tile_value; tg_verify.value_b := t.drill_value;
    tg_verify.pct_apart := case when coalesce(t.drill_value,0) = 0 then null
                                else round(abs(coalesce(t.gap,0))/abs(t.drill_value)*100, 2) end;
    return next;
  end loop;

  update watchdog_runs w set findings_raised =
    (select count(*) from watchdog_findings f where f.run_id = v_run) where w.id = v_run;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verify_import_group(p_imports uuid[], p_stated integer, p_stored integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare verdict text;
begin
  verdict := tg_check_row_count(p_stated, p_stored, p_stored);
  update metrc_report_imports
  set stated_total = p_stated, count_check = verdict
  where id = any (p_imports);
  return jsonb_build_object('ok', verdict not like 'FAILED%', 'count_check', verdict,
    'chunks', array_length(p_imports,1), 'stated', p_stated, 'stored', p_stored);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_view_rls_ratchet(p_selftest_worse_by integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base int; v_raw int; v_declared int; v_net int; v_total int;
  v_verdict text; v_note text;
begin
  select baseline into v_base from ratchet_baseline where metric_key = 'views_bypassing_rls';
  if v_base is null then raise exception 'no baseline recorded for views_bypassing_rls'; end if;

  select count(*) filter (where bypassing),
         count(*) filter (where bypassing and declared),
         count(*)
    into v_raw, v_declared, v_total
    from (
      select coalesce((select option_value from pg_options_to_table(c.reloptions)
                        where option_name = 'security_invoker'), 'false') <> 'true' as bypassing,
             exists (select 1 from rls_intent i where i.table_name = c.relname)      as declared
        from pg_class c join pg_namespace n on n.oid = c.relnamespace
       where n.nspname = 'public' and c.relkind = 'v'
    ) s;

  v_net := v_raw - v_declared;

  /* Failing path, upward only, so it can never manufacture a pass. */
  if p_selftest_worse_by is not null then
    v_net := v_net + greatest(p_selftest_worse_by, 0);
    v_note := format('SELF-TEST: net inflated by %s. Not a measurement.', greatest(p_selftest_worse_by, 0));
  end if;

  if v_net > v_base then
    v_verdict := 'FAIL';
  else
    v_verdict := 'PASS';
    if v_net < v_base and p_selftest_worse_by is null then
      update ratchet_baseline
         set baseline = v_net, set_on = current_date,
             note = note || format(' Ratchet tightened from %s to %s on %s.', v_base, v_net, current_date)
       where metric_key = 'views_bypassing_rls';
    end if;
  end if;

  insert into conformance_ledger
    (checker_key, subject_kind, subject_ref, verdict, numerator, denominator,
     the_arithmetic, drill, note)
  values
    ('detect.view_rls_ratchet', 'metric', 'views_bypassing_rls', v_verdict,
     v_total - v_net, v_total,
     format('%s of %s views enforce row-level security. %s run as the view owner, of which %s are '
            || 'REGISTERED exemptions in rls_intent that guard themselves in the view body — so %s '
            || 'is the figure that must not rise. Baseline %s.',
            v_total - v_raw, v_total, v_raw, v_declared, v_net, v_base),
     'select c.relname, (select reason from rls_intent i where i.table_name = c.relname) as declared_reason from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=''public'' and c.relkind=''v'' and coalesce((select option_value from pg_options_to_table(c.reloptions) where option_name=''security_invoker''),''false'') <> ''true''',
     v_note);

  return format('%s — %s bypassing raw, %s declared, %s net, baseline %s',
                v_verdict, v_raw, v_declared, v_net, v_base);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_watchdog_forensic()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_run bigint; v_start timestamptz := clock_timestamp(); v_cost numeric;
  v_raised int := 0; v_lb numeric := 0; v_usd numeric := 0;
begin
  select value into v_cost from conversion_factors where key='target_cost_per_lb';
  insert into watchdog_runs (ran_by) values ('scheduled sweep') returning id into v_run;

  -- ── Never submitted for testing ──────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, pounds, dollars, drill, search_text)
  select v_run, 'untested:'||s.stream, 'critical',
    round(sum(s.pounds),1)||' lb of '||lower(s.stream)||' has never been submitted for laboratory testing',
    string_agg(distinct s.location||' ('||s.license||')', '; '),
    'Quality and Compliance',
    'Oldest package was created '||max(s.oldest_packaged)::text||', '||max(s.oldest_days)||' days ago',
    'Untested product cannot legally be sold. It is capital that cannot move and an inspection exposure.',
    'Swept every package in Metrc where LabTestingState is NotSubmitted and quantity is above zero.',
    'Submit it for testing, or record a disposition against it in Metrc.',
    sum(s.packages)||' packages x '||round(sum(s.pounds),1)||' lb x $'||v_cost||' per lb = $'||round(sum(s.pounds)*v_cost),
    jsonb_agg(jsonb_build_object('stream',s.stream,'license',s.license,'location',s.location,
      'packages',s.packages,'pounds',s.pounds,'oldest_days',s.oldest_days,'oldest_packaged',s.oldest_packaged)),
    sum(s.packages)::int, round(sum(s.pounds),1), round(sum(s.pounds)*v_cost), 'lab_results',
    'never submitted testing untested '||s.stream||' '||string_agg(distinct s.location,' ')||' '||string_agg(distinct s.license,' ')
  from v_stock_on_hand s where s.lab_state='NotSubmitted' group by s.stream having sum(s.pounds) > 0.5;

  -- ── Our own material that failed ─────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, pounds, dollars, drill, search_text)
  select v_run, 'ourfail:'||s.stream, 'critical',
    round(sum(s.pounds),1)||' lb of '||lower(s.stream)||' we grew ourselves failed laboratory testing',
    string_agg(distinct s.location||' ('||s.license||')', '; '),
    'Cultivation and Quality',
    'Oldest failed package '||max(s.oldest_days)||' days old, created '||max(s.oldest_packaged)::text,
    'We grew it, packaged it and it failed. This is a genuine loss and a process failure to trace back to a room, a dry time or a handling step.',
    'Swept every package where LabTestingState is TestFailed and the originating licence is one of ours.',
    'Find the root cause, then decide remediate or destroy and record the disposition in Metrc.',
    sum(s.packages)||' packages x '||round(sum(s.pounds),1)||' lb x $'||v_cost||' = $'||round(sum(s.pounds)*v_cost),
    jsonb_agg(jsonb_build_object('stream',s.stream,'location',s.location,'strains',s.strains,
      'packages',s.packages,'pounds',s.pounds,'oldest_days',s.oldest_days)),
    sum(s.packages)::int, round(sum(s.pounds),1), round(sum(s.pounds)*v_cost), 'failed_testing_by_origin',
    'failed testing our own '||s.stream||' '||string_agg(distinct s.location,' ')
  from v_stock_on_hand s where s.lab_state='TestFailed' and s.origin='Grown by us' group by s.stream;

  -- ── Harvests that do not reconcile ───────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, pounds, drill, search_text)
  select v_run, 'massbal:'||m.harvest, 'critical',
    'Harvest '||m.harvest||' does not reconcile - '||abs(m.reconciliation_gap_lb)||' lb unexplained',
    m.room, 'Cultivation - whoever recorded the weights',
    'Harvest cut '||m.harvest_start::text||coalesce(', closed '||m.finished::text,''),
    'Wet weight must equal packaged plus recorded waste plus evaporated moisture. A gap means a weight was entered wrong or product left without being recorded.',
    'Compared wet minus packaged minus waste against the current weight Metrc holds independently, flagging any gap over two percent.',
    'Find which of the four figures is wrong and correct it in Metrc.',
    m.the_arithmetic, to_jsonb(m), 1, abs(m.reconciliation_gap_lb), 'moisture_accounting',
    'mass balance reconcile '||m.harvest||' '||m.room||' '||coalesce(m.strain,'')
  from v_moisture_accounting m
  where m.finished is not null and abs(coalesce(m.reconciliation_gap_lb,0)) > greatest(2, m.wet_lb*0.02);

  -- ── Storage limits breached ──────────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, pounds, dollars, drill, search_text)
  select v_run, 'limit:'||l.stream, 'elevated',
    l.stream||' is '||lower(l.status),
    coalesce(l.location,'all locations'), 'Vincent - limits are his to set and enforce',
    'Oldest package '||l.oldest_days||' days old',
    'Without a ceiling nothing warns us we are over-stocked or holding material past its useful life. Capital sits and quality falls.',
    'Compared live pounds on hand and oldest package age against the ceilings set on the Storage Limits page.',
    'Move it, sell it, process it, or raise the limit deliberately and record who decided.',
    coalesce(l.on_hand_lb,0)||' lb on hand'||coalesce(' against a '||l.max_lb||' lb ceiling','')||
      coalesce(', oldest '||l.oldest_days||' days against a '||l.max_age_days||' day limit',''),
    to_jsonb(l), l.on_hand_lb, round(l.on_hand_lb*v_cost), 'storage_limit_status',
    'storage limit '||l.stream||' '||l.status
  from v_storage_limit_status l
  where l.status in ('OVER THE STORAGE LIMIT','MATERIAL OLDER THAN THE LIMIT','APPROACHING THE LIMIT');

  -- ── Purchased material sitting untouched ─────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, evidence, record_count, drill, search_text)
  select v_run, 'tpsitting:'||t.supplier, 'elevated',
    count(*)||' purchased packages from '||t.supplier||' received and never drawn from',
    string_agg(distinct t.location, '; '), 'Purchasing and Manufacturing',
    'Oldest received '||max(t.received_on)::text||', '||max(t.days_since_received)||' days ago',
    'Purchased material sitting still is cash already spent and not yet earned back, and it ages while it waits.',
    'Traced every purchased package from its inbound manifest and checked whether any quantity has been drawn.',
    'Process it or sell it, or explain why it is being held.',
    jsonb_agg(jsonb_build_object('tag',t.tag,'item',t.item_name,'received_on',t.received_on,
      'qty',t.qty_received,'remaining',t.qty_remaining,'days',t.days_since_received)),
    count(*)::int, 'third_party_lifecycle',
    'third party sitting untouched '||t.supplier
  from v_third_party_lifecycle t where t.position like 'SITTING%' group by t.supplier;

  -- ── Laboratory turnaround ────────────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, drill, search_text)
  select v_run, 'labslow:'||coalesce(t.category,'unknown'), 'watch',
    'Laboratory turnaround on '||t.category||' reached '||t.slowest_turnaround_days||' days',
    'External laboratory', 'Quality - whoever manages the laboratory relationship',
    'Measured across '||t.packages||' packages on record',
    'Every day waiting on a result is a day the product cannot be sold. Slow turnaround is working capital sitting idle.',
    'Measured the gap between the date each package was submitted and the date its result was recorded in Metrc.',
    'Chase the laboratory, and consider a second laboratory for overflow.',
    'average '||coalesce(t.avg_turnaround_days,0)||' days, worst '||t.slowest_turnaround_days||', '||t.took_over_14_days||' over 14 days',
    to_jsonb(t), t.packages, 'lab_turnaround_summary',
    'laboratory turnaround slow '||t.category
  from v_lab_turnaround_summary t where coalesce(t.slowest_turnaround_days,0) > 14;

  -- ── Questions left unanswered ────────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, evidence, pounds, dollars, drill, search_text)
  select v_run, 'question:'||q.question_key, 'elevated',
    'Unanswered '||q.days_open||' days: '||q.question,
    q.area, 'Vinny or Vincent', 'First raised '||q.first_raised::text,
    coalesce(q.why_it_matters,'Blocks reporting'), 'Raised automatically when the platform found a fact nobody had recorded.',
    'Answer it. Until then every figure it feeds is unreliable.',
    to_jsonb(q), q.exposure_lb, q.exposure_dollars, 'open_questions',
    'unanswered question '||q.area||' '||q.question
  from v_open_questions q where q.days_open > 3;

  select count(*), coalesce(sum(pounds),0), coalesce(sum(dollars),0)
    into v_raised, v_lb, v_usd
  from watchdog_findings where run_id = v_run;

  update watchdog_runs
     set duration_ms = extract(milliseconds from (clock_timestamp() - v_start))::int,
         findings_raised = v_raised, total_pounds_flagged = v_lb, total_dollars_flagged = v_usd
   where id = v_run;

  perform tg_inventory_watch();
  return v_run;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_watchdog_search(q text)
 RETURNS SETOF v_watchdog_log
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from v_watchdog_log
  where to_tsvector('english', coalesce(search_text,'')||' '||what||' '||coalesce(where_it_is,'')||' '||coalesce(who_is_accountable,''))
        @@ plainto_tsquery('english', q)
     or what ilike '%'||q||'%' or coalesce(where_it_is,'') ilike '%'||q||'%'
     or coalesce(evidence::text,'') ilike '%'||q||'%'
  order by observed_at desc;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_watchdog_upsert_by_fingerprint()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare existing_id bigint;
begin
  if new.fingerprint is null then
    return new;                      -- no identity, treat as a new finding
  end if;

  select id into existing_id
  from watchdog_findings
  where fingerprint = new.fingerprint
  limit 1;

  if existing_id is null then
    return new;                      -- genuinely new
  end if;

  /* Seen before. Refresh it in place, keeping when_it_started and the original
     observed_at as the first sighting. Never create a second row. */
  update watchdog_findings w set
    observed_at        = greatest(w.observed_at, coalesce(new.observed_at, now())),
    severity           = coalesce(new.severity, w.severity),
    what               = coalesce(new.what, w.what),
    where_it_is        = coalesce(new.where_it_is, w.where_it_is),
    who_is_accountable = coalesce(new.who_is_accountable, w.who_is_accountable),
    why_it_matters     = coalesce(new.why_it_matters, w.why_it_matters),
    how_it_was_detected= coalesce(new.how_it_was_detected, w.how_it_was_detected),
    what_to_do         = coalesce(new.what_to_do, w.what_to_do),
    the_arithmetic     = coalesce(new.the_arithmetic, w.the_arithmetic),
    evidence           = coalesce(new.evidence, w.evidence),
    record_count       = coalesce(new.record_count, w.record_count),
    pounds             = coalesce(new.pounds, w.pounds),
    dollars            = coalesce(new.dollars, w.dollars),
    drill              = coalesce(new.drill, w.drill),
    run_id             = coalesce(new.run_id, w.run_id)
  where w.id = existing_id;

  return null;                       -- swallow the insert; the update stands
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_automap_on_import()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from sheet_column_map where source_id = new.source_id and role='package_tag') then
    perform f_automap_tag_column(new.source_id);
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_cost_input_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op='UPDATE' and new.value is distinct from old.value then
    insert into cost_input_history(key, old_value, new_value, changed_by)
    values (new.key, old.value, new.value, new.updated_by);
    new.updated_at := now();
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_metrc_correction_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.fixed_in_metrc and not old.fixed_in_metrc then
    if new.fixed_by is null or length(trim(new.fixed_by)) < 2 then
      raise exception 'Name who fixed it in Metrc before closing this.';
    end if;
    if new.verification_note is null or length(trim(new.verification_note)) < 20 then
      raise exception 'Record what was actually done in Metrc — the manifest number, support ticket or adjustment reference — in at least twenty characters. This cannot be closed on a tick alone.';
    end if;
    new.fixed_on := coalesce(new.fixed_on, current_date);
  end if;
  if old.fixed_in_metrc and not new.fixed_in_metrc then
    raise exception 'A correction that was verified as fixed in Metrc cannot be quietly reopened. Raise a new correction instead.';
  end if;
  return new;
end $function$
;

-- ==========================================================================
-- VIEWS — created in dependency order
-- ==========================================================================

create materialized view if not exists public.mv_harvest_certificate as
 WITH tag_harvest AS (
         SELECT upper(btrim(p.raw ->> 'Label'::text)) AS tag,
            btrim(h.name) AS harvest
           FROM metrc_packages p
             JOIN LATERAL unnest(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ', '::text)) h(name) ON true
          WHERE NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL AND NULLIF(btrim(h.name), ''::text) IS NOT NULL
        UNION
         SELECT upper(btrim(t.package_tag)) AS upper,
            btrim(h.name) AS btrim
           FROM metrc_rpt_package_transfers t
             JOIN LATERAL unnest(string_to_array(t.source_harvest, ', '::text)) h(name) ON true
          WHERE NULLIF(btrim(t.source_harvest), ''::text) IS NOT NULL AND NULLIF(btrim(h.name), ''::text) IS NOT NULL
        ), cert AS (
         SELECT s.tag,
            min(s.rank) AS rank,
            min(s.kind) AS kind,
            max(s.report_date) AS report_date
           FROM ( SELECT upper(btrim(coa_extract.package_tag)) AS tag,
                    1 AS rank,
                    'PARSED COA DOCUMENT'::text AS kind,
                    coa_extract.report_date
                   FROM coa_extract
                  WHERE coa_extract.package_tag IS NOT NULL
                UNION ALL
                 SELECT upper(btrim(metrc_documents.package_tag)) AS upper,
                    2,
                    'COA FILE HELD, NOT YET PARSED'::text,
                    metrc_documents.fetched_at::text AS fetched_at
                   FROM metrc_documents
                  WHERE metrc_documents.doc_type = 'coa'::text AND metrc_documents.package_tag IS NOT NULL
                UNION ALL
                 SELECT upper(btrim(metrc_lab_results.package_tag)) AS upper,
                    3,
                    'METRC LAB RESULT (API)'::text,
                    max(metrc_lab_results.result_date)::text AS max
                   FROM metrc_lab_results
                  WHERE metrc_lab_results.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(metrc_lab_results.package_tag)))
                UNION ALL
                 SELECT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper,
                    4,
                    'METRC LAB RESULT (report export)'::text,
                    max(metrc_rpt_lab_results.test_date)::text AS max
                   FROM metrc_rpt_lab_results
                  WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(metrc_rpt_lab_results.package_tag)))) s
          GROUP BY s.tag
        )
 SELECT DISTINCT ON (th.harvest) th.harvest,
    c.tag AS certified_via_tag,
    c.kind AS certificate_source,
    c.report_date,
    c.rank
   FROM tag_harvest th
     JOIN cert c ON c.tag = th.tag
  ORDER BY th.harvest, c.rank;
create materialized view if not exists public.mv_package_documents as
 SELECT tag AS package_tag,
    license,
    ( SELECT count(*) AS count
           FROM metrc_documents d
          WHERE d.doc_type = 'coa'::text AND d.package_tag = p.tag AND d.storage_path IS NOT NULL) AS coa_count,
    ( SELECT count(DISTINCT r.document_file_id) AS count
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag AND r.document_file_id IS NOT NULL) AS coa_expected,
    ( SELECT count(*) AS count
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag) AS lab_result_rows,
    ( SELECT max(r.lab_facility) AS max
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag) AS lab,
    ( SELECT max(r.result_date) AS max
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag) AS tested_on,
    lab_testing_state
   FROM metrc_packages p;
create materialized view if not exists public.mv_package_harvest as
 SELECT DISTINCT btrim(hn.hn) AS harvest_name,
    p.id AS package_id,
    p.quantity,
    p.packaged_on,
    p.raw ->> 'LabTestingState'::text AS lab_state,
    p.raw #>> '{Item,ProductCategoryName}'::text[] AS category
   FROM metrc_packages p
     CROSS JOIN LATERAL unnest(string_to_array(COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text)) hn(hn)
  WHERE btrim(hn.hn) <> ''::text;
create materialized view if not exists public.mv_package_origin as
 SELECT DISTINCT ON (tag) tag,
    f_material_origin(tag) AS origin,
    now() AS computed_at
   FROM metrc_packages p
  ORDER BY tag, license;
create materialized view if not exists public.mv_tag_certificate as
 WITH RECURSIVE edges AS (
         SELECT upper(btrim(c.raw ->> 'Label'::text)) AS child,
            upper(btrim(pt.tag)) AS parent
           FROM metrc_packages c
             JOIN LATERAL unnest(string_to_array(c.raw ->> 'SourcePackageLabels'::text, ', '::text)) pt(tag) ON true
          WHERE NULLIF(c.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL AND NULLIF(btrim(pt.tag), ''::text) IS NOT NULL
        UNION
         SELECT upper(btrim(t.package_tag)) AS upper,
            upper(btrim(t.source_package)) AS upper
           FROM metrc_rpt_package_transfers t
          WHERE NULLIF(btrim(t.source_package), ''::text) IS NOT NULL AND upper(btrim(t.source_package)) <> upper(btrim(t.package_tag))
        ), cert AS (
         SELECT s.tag,
            min(s.rank) AS rank,
            min(s.document_id) FILTER (WHERE s.document_id IS NOT NULL) AS document_id,
            min(s.kind) AS kind,
            max(s.report_date) AS report_date,
            max(s.total_thc) AS total_thc
           FROM ( SELECT upper(btrim(coa_extract.package_tag)) AS tag,
                    1 AS rank,
                    coa_extract.document_id,
                    'PARSED COA DOCUMENT'::text AS kind,
                    coa_extract.report_date,
                    coa_extract.total_thc::text AS total_thc
                   FROM coa_extract
                  WHERE coa_extract.package_tag IS NOT NULL
                UNION ALL
                 SELECT upper(btrim(d.package_tag)) AS upper,
                    2,
                    d.id::text AS id,
                    'COA FILE HELD, NOT YET PARSED'::text,
                    d.tested_on_txt,
                    NULL::text
                   FROM ( SELECT metrc_documents.package_tag,
                            metrc_documents.id,
                            metrc_documents.fetched_at::text AS tested_on_txt
                           FROM metrc_documents
                          WHERE metrc_documents.doc_type = 'coa'::text AND metrc_documents.package_tag IS NOT NULL) d
                UNION ALL
                 SELECT upper(btrim(metrc_lab_results.package_tag)) AS upper,
                    3,
                    NULL::text,
                    'METRC LAB RESULT (API)'::text,
                    max(metrc_lab_results.result_date)::text AS max,
                    NULL::text
                   FROM metrc_lab_results
                  WHERE metrc_lab_results.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(metrc_lab_results.package_tag)))
                UNION ALL
                 SELECT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper,
                    4,
                    NULL::text,
                    'METRC LAB RESULT (report export)'::text,
                    max(metrc_rpt_lab_results.test_date)::text AS max,
                    NULL::text
                   FROM metrc_rpt_lab_results
                  WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(metrc_rpt_lab_results.package_tag)))) s
          GROUP BY s.tag
        ), universe AS (
         SELECT DISTINCT upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag
           FROM metrc_packages
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_package_transfers.package_tag)) AS upper
           FROM metrc_rpt_package_transfers
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_point_in_time.tag)) AS upper
           FROM metrc_rpt_point_in_time
          WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_packages_inventory.package_tag)) AS upper
           FROM metrc_rpt_packages_inventory
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper
           FROM metrc_rpt_lab_results
          WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
        UNION
         SELECT DISTINCT upper(btrim(metrc_lab_results.package_tag)) AS upper
           FROM metrc_lab_results
          WHERE metrc_lab_results.package_tag IS NOT NULL
        UNION
         SELECT DISTINCT upper(btrim(coa_extract.package_tag)) AS upper
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_adjustments.package_tag)) AS upper
           FROM metrc_rpt_adjustments
          WHERE metrc_rpt_adjustments.package_tag IS NOT NULL
        ), walk AS (
         SELECT u_1.tag,
            u_1.tag AS node,
            0 AS hops
           FROM universe u_1
        UNION ALL
         SELECT w.tag,
            e.parent,
            w.hops + 1
           FROM walk w
             JOIN edges e ON e.child = w.node
          WHERE w.hops < 8 AND NOT (EXISTS ( SELECT 1
                   FROM cert c
                  WHERE c.tag = w.node))
        ), best AS (
         SELECT DISTINCT ON (w.tag) w.tag,
            w.node AS found_on_tag,
            w.hops,
            c.document_id,
            c.kind,
            c.report_date,
            c.total_thc
           FROM walk w
             JOIN cert c ON c.tag = w.node
          ORDER BY w.tag, w.hops, c.rank
        )
 SELECT u.tag,
    b.found_on_tag AS certificate_on_tag,
    b.hops AS certificate_hops,
    b.document_id AS certificate_document,
    b.kind AS certificate_source,
    b.report_date AS certificate_date,
    b.total_thc AS certificate_total_thc,
        CASE
            WHEN b.tag IS NULL THEN 'NOT IMPORTED — certificate exists but we have not pulled it'::text
            WHEN b.hops = 0 THEN 'ON THE TAG ITSELF'::text
            ELSE ('INHERITED — '::text || b.hops) || ' hop(s) up the lineage'::text
        END AS certificate_basis
   FROM universe u
     LEFT JOIN best b ON b.tag = u.tag;
create materialized view if not exists public.mv_tag_coa_lineage as
 WITH RECURSIVE edges AS (
         SELECT upper(btrim(c.raw ->> 'Label'::text)) AS child,
            upper(btrim(pt.tag)) AS parent
           FROM metrc_packages c
             JOIN LATERAL unnest(string_to_array(c.raw ->> 'SourcePackageLabels'::text, ', '::text)) pt(tag) ON true
          WHERE NULLIF(c.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL AND NULLIF(btrim(pt.tag), ''::text) IS NOT NULL
        UNION
         SELECT upper(btrim(t.package_tag)) AS upper,
            upper(btrim(t.source_package)) AS upper
           FROM metrc_rpt_package_transfers t
          WHERE NULLIF(btrim(t.source_package), ''::text) IS NOT NULL AND upper(btrim(t.source_package)) <> upper(btrim(t.package_tag))
        ), coa_tag AS (
         SELECT upper(btrim(coa_extract.package_tag)) AS tag,
            min(coa_extract.document_id) AS document_id,
            max(coa_extract.report_date) AS report_date,
            max(coa_extract.total_thc) AS total_thc,
            max(coa_extract.sample_id) AS sample_id
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL
          GROUP BY (upper(btrim(coa_extract.package_tag)))
        ), universe AS (
         SELECT DISTINCT upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag
           FROM metrc_packages
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_package_transfers.package_tag)) AS upper
           FROM metrc_rpt_package_transfers
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_point_in_time.tag)) AS upper
           FROM metrc_rpt_point_in_time
          WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_packages_inventory.package_tag)) AS upper
           FROM metrc_rpt_packages_inventory
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper
           FROM metrc_rpt_lab_results
          WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
        UNION
         SELECT DISTINCT upper(btrim(coa_extract.package_tag)) AS upper
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL
        UNION
         SELECT DISTINCT upper(btrim(metrc_rpt_adjustments.package_tag)) AS upper
           FROM metrc_rpt_adjustments
          WHERE metrc_rpt_adjustments.package_tag IS NOT NULL
        ), walk AS (
         SELECT u_1.tag,
            u_1.tag AS node,
            0 AS hops
           FROM universe u_1
        UNION ALL
         SELECT w.tag,
            e.parent,
            w.hops + 1
           FROM walk w
             JOIN edges e ON e.child = w.node
          WHERE w.hops < 8 AND NOT (EXISTS ( SELECT 1
                   FROM coa_tag c
                  WHERE c.tag = w.node))
        ), best AS (
         SELECT DISTINCT ON (w.tag) w.tag,
            w.node AS coa_tag,
            w.hops,
            c.document_id,
            c.report_date,
            c.total_thc,
            c.sample_id
           FROM walk w
             JOIN coa_tag c ON c.tag = w.node
          ORDER BY w.tag, w.hops, c.document_id
        )
 SELECT u.tag,
    b.coa_tag AS coa_found_on_tag,
    b.hops AS coa_hops,
    b.document_id AS coa_document,
    b.report_date AS coa_report_date,
    b.total_thc AS coa_total_thc,
    b.sample_id AS coa_sample_id,
        CASE
            WHEN b.tag IS NULL THEN 'NO COA ANYWHERE IN LINEAGE'::text
            WHEN b.hops = 0 THEN 'COA ON THE TAG ITSELF'::text
            ELSE ('COA INHERITED — '::text || b.hops) || ' hop(s) up the lineage'::text
        END AS coa_basis
   FROM universe u
     LEFT JOIN best b ON b.tag = u.tag;
create materialized view if not exists public.mv_tag_evidence as
 WITH pkg AS (
         SELECT DISTINCT ON (p_1.tag) p_1.tag,
            p_1.item_name,
            p_1.lab_testing_state,
            p_1.raw
           FROM metrc_packages p_1
          ORDER BY p_1.tag, (p_1.source_state = 'active'::text AND NOT COALESCE(p_1.finished, false)) DESC, (p_1.raw ->> 'LastModified'::text) DESC NULLS LAST
        ), lineage AS (
         WITH RECURSIVE walk AS (
                 SELECT k.tag,
                    k.tag AS ancestor,
                    0 AS generation
                   FROM pkg k
                UNION ALL
                 SELECT w.tag,
                    upper(btrim(x.lbl)) AS upper,
                    w.generation + 1
                   FROM walk w
                     JOIN pkg pp ON pp.tag = w.ancestor,
                    LATERAL unnest(string_to_array(COALESCE(pp.raw ->> 'SourcePackageLabels'::text, ''::text), ','::text)) x(lbl)
                  WHERE w.generation < 5 AND btrim(x.lbl) <> ''::text
                )
         SELECT walk.tag,
            walk.ancestor,
            walk.generation
           FROM walk
        ), best AS (
         SELECT l.tag,
            min(l.generation) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM coa_extract c
                  WHERE c.package_tag = l.ancestor))) AS coa_generation
           FROM lineage l
          GROUP BY l.tag
        )
 SELECT p.tag,
    p.item_name,
    p.lab_testing_state,
        CASE
            WHEN dc.package_tag IS NOT NULL THEN 'direct'::text
            WHEN b.coa_generation IS NOT NULL THEN 'inherited'::text
            WHEN lr.package_tag IS NOT NULL THEN 'lab result only'::text
            ELSE 'none'::text
        END AS evidence_source,
    COALESCE(dc.lab_report_id, ic.lab_report_id) AS certificate_id,
    COALESCE(dc.report_date, ic.report_date) AS certificate_date,
    COALESCE(dc.total_thc, ic.total_thc) AS total_thc,
    anc.ancestor_tag AS certificate_inherited_from,
    COALESCE(cd.storage_path, lr.coa_link) AS certificate_document,
    lr.result_date AS lab_result_date,
    lr.lab_facility AS lab_name,
    mt.manifest_number,
    md.storage_path AS manifest_document,
        CASE
            WHEN dc.package_tag IS NOT NULL THEN NULL::text
            WHEN b.coa_generation IS NOT NULL THEN NULL::text
            WHEN lr.package_tag IS NOT NULL THEN (('Tested — Metrc holds a lab result'::text || COALESCE(' dated '::text || to_char(lr.result_date::timestamp with time zone, 'DD Mon YYYY'::text), ''::text)) || COALESCE(' from '::text || lr.lab_facility, ''::text)) || ', but no certificate document is linked to this tag. The test happened; the paperwork is not attached.'::text
            WHEN p.lab_testing_state = 'NotSubmitted'::text THEN 'Never submitted for testing. No certificate because there was no test — this material cannot be sold until it is submitted.'::text
            WHEN COALESCE(p.raw ->> 'SourcePackageLabels'::text, ''::text) = ''::text THEN 'No certificate, no lab result, and no parent package to inherit from. This tag has no testing evidence of any kind anywhere in the platform.'::text
            ELSE ('No certificate on this tag and none on up to five generations of parents. Lab state is '::text || COALESCE(p.lab_testing_state, 'unknown'::text)) || '.'::text
        END AS why_no_certificate,
        CASE
            WHEN mt.manifest_number IS NULL THEN 'No inbound manifest line for this tag in the transfer report. Either it was produced here — check the parent packages — or the transfer report has not been imported for that period.'::text
            ELSE NULL::text
        END AS why_no_manifest
   FROM pkg p
     LEFT JOIN best b ON b.tag = p.tag
     LEFT JOIN LATERAL ( SELECT c.lab_report_id,
            c.report_date,
            c.total_thc,
            c.package_tag
           FROM coa_extract c
          WHERE c.package_tag = p.tag
          ORDER BY c.report_date DESC NULLS LAST
         LIMIT 1) dc ON true
     LEFT JOIN LATERAL ( SELECT l.ancestor AS ancestor_tag
           FROM lineage l
          WHERE l.tag = p.tag AND l.generation = b.coa_generation AND (EXISTS ( SELECT 1
                   FROM coa_extract c
                  WHERE c.package_tag = l.ancestor))
         LIMIT 1) anc ON true
     LEFT JOIN LATERAL ( SELECT c.lab_report_id,
            c.report_date,
            c.total_thc
           FROM coa_extract c
          WHERE c.package_tag = anc.ancestor_tag
          ORDER BY c.report_date DESC NULLS LAST
         LIMIT 1) ic ON true
     LEFT JOIN LATERAL ( SELECT d.storage_path
           FROM metrc_documents d
          WHERE d.package_tag = COALESCE(dc.package_tag, anc.ancestor_tag) AND d.doc_type ~~* '%coa%'::text
         LIMIT 1) cd ON true
     LEFT JOIN LATERAL ( SELECT l2.package_tag,
            l2.result_date,
            l2.lab_facility,
            l2.coa_link
           FROM metrc_lab_results l2
          WHERE l2.package_tag = p.tag
          ORDER BY l2.result_date DESC NULLS LAST
         LIMIT 1) lr ON true
     LEFT JOIN LATERAL ( SELECT t.manifest_number
           FROM metrc_rpt_package_transfers t
          WHERE t.package_tag = p.tag
          ORDER BY t.as_of_date DESC NULLS LAST
         LIMIT 1) mt ON true
     LEFT JOIN LATERAL ( SELECT d2.storage_path
           FROM metrc_documents d2
          WHERE d2.manifest_number = mt.manifest_number AND d2.doc_type ~~* '%manifest%'::text
         LIMIT 1) md ON true;
create materialized view if not exists public.mv_tag_harvest_link as
 SELECT upper(btrim(p.raw ->> 'Label'::text)) AS tag,
    btrim(h.name) AS harvest
   FROM metrc_packages p
     JOIN LATERAL unnest(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ', '::text)) h(name) ON true
  WHERE NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL AND NULLIF(btrim(h.name), ''::text) IS NOT NULL
UNION
 SELECT upper(btrim(t.package_tag)) AS tag,
    btrim(h.name) AS harvest
   FROM metrc_rpt_package_transfers t
     JOIN LATERAL unnest(string_to_array(t.source_harvest, ', '::text)) h(name) ON true
  WHERE NULLIF(btrim(t.source_harvest), ''::text) IS NOT NULL AND NULLIF(btrim(h.name), ''::text) IS NOT NULL;
create or replace view public.v_accepted_debt as
 SELECT x.metric_key,
    x.from_baseline,
    x.to_baseline,
    x.to_baseline - x.from_baseline AS rose_by,
    b.baseline AS baseline_now,
    x.why,
    x.approved_by,
    x.approved_at,
    x.must_fall_by,
    CURRENT_DATE > x.must_fall_by AND b.baseline >= x.to_baseline AS overdue,
        CASE
            WHEN x.consumed_at IS NULL THEN 'approved, not yet applied'::text
            WHEN CURRENT_DATE > x.must_fall_by AND b.baseline >= x.to_baseline THEN 'OVERDUE — accepted as temporary and never paid back'::text
            WHEN b.baseline < x.to_baseline THEN 'paid down since'::text
            ELSE 'accepted, within its deadline'::text
        END AS state
   FROM ratchet_exception x
     LEFT JOIN ratchet_baseline b ON b.metric_key = x.metric_key
  ORDER BY x.approved_at DESC;
create or replace view public.v_access_preview as
 SELECT r.role,
    r.rank,
    pc.category,
    pc.is_shared,
    count(*) FILTER (WHERE COALESCE(sp.min_rank, 0) <= r.rank) AS pages_they_would_see,
    count(*) FILTER (WHERE COALESCE(sp.min_rank, 0) > r.rank) AS pages_rank_blocks,
    count(*) AS pages_in_category
   FROM app_roles r
     CROSS JOIN page_category_policy pc
     JOIN nav_registry nr ON nr.category = pc.category AND nr.enabled
     LEFT JOIN sensitive_page_policy sp ON sp.view_key = nr.view_key
  WHERE (r.role IN ( SELECT unnest(enum_range(NULL::app_role))::text AS unnest))
  GROUP BY r.role, r.rank, pc.category, pc.is_shared
  ORDER BY r.rank DESC, pc.category;
create or replace view public.v_admin_permissions as
 SELECT r.role AS role_key,
    r.label AS role_label,
    r.rank,
    r.built_in,
    p.category AS permission_group,
    NULLIF(replace(p.category, 'Area: '::text, ''::text), p.category) AS business_area,
    p.action AS permission_key,
    p.label AS permission_label,
    p.description,
    COALESCE(rp.allowed, false) AS granted,
    rp.role IS NOT NULL AS explicitly_set,
    ( SELECT count(*) AS count
           FROM nav_role_visibility v
          WHERE v.role = r.role AND v.visible) AS pages_this_role_can_open,
    'Toggle with: insert into role_permissions(role,action,allowed) values (...) on conflict (role,action) do update set allowed = excluded.allowed. Built-in roles should be COPIED to a new role rather than edited.'::text AS how_to_change,
    'PERMISSION is what you may DO. PAGE VISIBILITY is what you may SEE. Both are required - a role holding view_finance with no page grant gets a menu missing the page it needs.'::text AS note
   FROM app_roles r
     CROSS JOIN permission_catalog p
     LEFT JOIN role_permissions rp ON rp.role = r.role AND rp.action = p.action;
create or replace view public.v_admin_settings as
 SELECT 'fiscal_year_start_month'::text AS setting_key,
    'Fiscal year starts in'::text AS label,
    'Company'::text AS section,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fiscal_year_start_month'::text), '1'::text) AS current_value,
    to_char(to_date(COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fiscal_year_start_month'::text), '1'::text), 'MM'::text)::timestamp with time zone, 'FMMonth'::text) AS shows_as,
    'number 1-12'::text AS value_type,
    '1 (January)'::text AS default_value,
    f_fiscal_year_start()::text AS takes_effect_as,
    'Every fiscal preset on the platform: This Fiscal Year, This Fiscal Year-to-date and Last Fiscal Year. Changing it changes what those three mean on all 518 report pages at once.'::text AS what_it_affects,
    'QuickBooks holds this under Account and Settings > Advanced. It is a company fact, not a code constant - never hardcode it.'::text AS note
UNION ALL
 SELECT 'default_date_preset'::text AS setting_key,
    'Default date range'::text AS label,
    'Reports'::text AS section,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'default_date_preset'::text), 'this_month_td'::text) AS current_value,
    COALESCE(( SELECT p.label
           FROM date_range_presets p
          WHERE p.preset_key = (( SELECT configurations.value #>> '{}'::text[]
                   FROM configurations
                  WHERE configurations.key = 'default_date_preset'::text))), 'This Month-to-date'::text) AS shows_as,
    'one of date_range_presets.preset_key'::text AS value_type,
    'this_month_td (This Month-to-date)'::text AS default_value,
    COALESCE(( SELECT p.label
           FROM date_range_presets p
          WHERE p.preset_key = (( SELECT configurations.value #>> '{}'::text[]
                   FROM configurations
                  WHERE configurations.key = 'default_date_preset'::text))), 'This Month-to-date'::text) AS takes_effect_as,
    'What a report opens on when neither the user nor the page has set anything. Users still override it per page or globally; this is only the floor.'::text AS what_it_affects,
    'The QuickBooks convention for activity reports. Snapshot pages - stock on hand, ageing, registries - stay on Today, because applying a RANGE to a balance changes what the number means.'::text AS note
UNION ALL
 SELECT 'fresh_frozen_wet_to_dry'::text AS setting_key,
    'Fresh frozen wet-to-dry ratio'::text AS label,
    'Cultivation'::text AS section,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fresh_frozen_wet_to_dry'::text), '4.5'::text) AS current_value,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fresh_frozen_wet_to_dry'::text), '4.5'::text) AS shows_as,
    'number'::text AS value_type,
    '4.5'::text AS default_value,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fresh_frozen_wet_to_dry'::text), '4.5'::text) AS takes_effect_as,
    'Every dry-equivalent figure. 603.9 lb of fresh frozen becomes 134.2 lb at 4.5. Measured across our own 380 harvests it is 4.17; the briefing says 5.03.'::text AS what_it_affects,
    'The three sources disagree and the owner has not ruled. Report the ratio used alongside any dry-equivalent figure.'::text AS note;
create or replace view public.v_agent_agreement as
 WITH by_subject AS (
         SELECT agent_claims.subject,
            count(*) AS claims,
            count(DISTINCT agent_claims.agent) AS agents,
            count(DISTINCT agent_claims.claimed_value) AS distinct_values,
            min(agent_claims.claimed_value) AS lowest,
            max(agent_claims.claimed_value) AS highest,
            max(agent_claims.live_value) AS live_now,
            string_agg(DISTINCT (agent_claims.agent || ' says '::text) || COALESCE(agent_claims.claimed_value::text, agent_claims.claimed_text, '?'::text), '  |  '::text ORDER BY ((agent_claims.agent || ' says '::text) || COALESCE(agent_claims.claimed_value::text, agent_claims.claimed_text, '?'::text))) AS positions,
            string_agg(DISTINCT agent_claims.status, ', '::text) AS verdicts
           FROM agent_claims
          GROUP BY agent_claims.subject
        )
 SELECT subject,
    agents,
    claims,
    positions,
    lowest,
    highest,
        CASE
            WHEN highest IS NOT NULL AND lowest IS NOT NULL AND lowest <> 0::numeric THEN round(abs(highest - lowest) / abs(lowest) * 100::numeric, 1)
            ELSE NULL::numeric
        END AS pct_apart,
    live_now,
    verdicts,
        CASE
            WHEN agents < 2 THEN 'UNCORROBORATED - only one agent has looked at this'::text
            WHEN distinct_values <= 1 THEN 'AGREED - every agent reached the same number'::text
            ELSE ((('DISAGREE - '::text || distinct_values) || ' different answers from '::text) || agents) || ' agents'::text
        END AS agreement,
        CASE
            WHEN distinct_values > 1 THEN 'THE ISSUE: agents disagree on the same question. Report BOTH figures with both methods. Never average, never pick silently - the disagreement IS the finding.'::text
            ELSE NULL::text
        END AS what_is_wrong
   FROM by_subject;
create or replace view public.v_agent_health as
 WITH sync_ev AS (
         SELECT
                CASE
                    WHEN metrc_sync_runs.endpoint ~~* 'transfers%'::text THEN 'sync:transfers'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'packages%'::text THEN 'sync:packages'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'harvests%'::text OR metrc_sync_runs.endpoint ~~* 'plants%'::text OR metrc_sync_runs.endpoint ~~* 'plantbatches%'::text THEN 'sync:cultivation'::text
                    WHEN metrc_sync_runs.endpoint = ANY (ARRAY['items'::text, 'strains'::text, 'locations'::text]) THEN 'sync:reference'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'sales%'::text THEN 'sync:sales'::text
                    ELSE NULL::text
                END AS agent_key,
            max(metrc_sync_runs.started_at) AS last_run,
            count(*) FILTER (WHERE metrc_sync_runs.started_at > (now() - '24:00:00'::interval)) AS runs_24h,
            count(*) FILTER (WHERE metrc_sync_runs.status = 'error'::text AND metrc_sync_runs.started_at > (now() - '24:00:00'::interval)) AS errors_24h,
            sum(metrc_sync_runs.records) FILTER (WHERE metrc_sync_runs.status = 'ok'::text AND metrc_sync_runs.started_at > (now() - '24:00:00'::interval)) AS records_24h,
            max(metrc_sync_runs.error) FILTER (WHERE metrc_sync_runs.status = 'error'::text) AS last_error
           FROM metrc_sync_runs
          GROUP BY (
                CASE
                    WHEN metrc_sync_runs.endpoint ~~* 'transfers%'::text THEN 'sync:transfers'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'packages%'::text THEN 'sync:packages'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'harvests%'::text OR metrc_sync_runs.endpoint ~~* 'plants%'::text OR metrc_sync_runs.endpoint ~~* 'plantbatches%'::text THEN 'sync:cultivation'::text
                    WHEN metrc_sync_runs.endpoint = ANY (ARRAY['items'::text, 'strains'::text, 'locations'::text]) THEN 'sync:reference'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'sales%'::text THEN 'sync:sales'::text
                    ELSE NULL::text
                END)
        ), watch_ev AS (
         SELECT
                CASE agent_findings.agent
                    WHEN 'Allocation control'::text THEN 'watch:allocation'::text
                    WHEN 'Cash velocity'::text THEN 'watch:cash'::text
                    WHEN 'Compliance watch'::text THEN 'watch:compliance'::text
                    WHEN 'Room turnaround'::text THEN 'watch:room'::text
                    WHEN 'Schedule discipline'::text THEN 'watch:schedule'::text
                    WHEN 'Loss and yield'::text THEN 'watch:loss'::text
                    ELSE 'watch:sales'::text
                END AS agent_key,
            max(agent_findings.detected_at) AS last_run,
            count(*) AS produced
           FROM agent_findings
          GROUP BY (
                CASE agent_findings.agent
                    WHEN 'Allocation control'::text THEN 'watch:allocation'::text
                    WHEN 'Cash velocity'::text THEN 'watch:cash'::text
                    WHEN 'Compliance watch'::text THEN 'watch:compliance'::text
                    WHEN 'Room turnaround'::text THEN 'watch:room'::text
                    WHEN 'Schedule discipline'::text THEN 'watch:schedule'::text
                    WHEN 'Loss and yield'::text THEN 'watch:loss'::text
                    ELSE 'watch:sales'::text
                END)
        UNION ALL
         SELECT 'watch:watchdog'::text,
            max(watchdog_runs.ran_at) AS max,
            count(*) AS count
           FROM watchdog_runs
        UNION ALL
         SELECT 'watch:custody'::text,
            max(custody_alert_log.captured_at) AS max,
            count(*) AS count
           FROM custody_alert_log
        UNION ALL
         SELECT 'watch:inventory'::text,
            max(inventory_alerts.last_seen) AS max,
            count(*) AS count
           FROM inventory_alerts
        UNION ALL
         SELECT 'maint:canary'::text,
            max(canary_runs.ran_at) AS max,
            count(*) AS count
           FROM canary_runs
        ), ev AS (
         SELECT sync_ev.agent_key,
            sync_ev.last_run,
            sync_ev.runs_24h,
            sync_ev.errors_24h,
            sync_ev.records_24h,
            sync_ev.last_error,
            NULL::bigint AS produced
           FROM sync_ev
          WHERE sync_ev.agent_key IS NOT NULL
        UNION ALL
         SELECT watch_ev.agent_key,
            watch_ev.last_run,
            NULL::bigint,
            NULL::bigint,
            NULL::bigint,
            NULL::text,
            watch_ev.produced
           FROM watch_ev
        )
 SELECT r.agent_key,
    r.display_name,
    r.kind,
    r.what_it_watches,
    r.why_it_matters,
    r.owner,
    r.expected_every_mins,
    r.verified_by,
    r.enabled,
    e.last_run,
    round(EXTRACT(epoch FROM now() - e.last_run) / 60::numeric)::integer AS minutes_since_run,
    e.runs_24h,
    e.errors_24h,
    e.records_24h,
    e.produced,
    "left"(COALESCE(e.last_error, ''::text), 140) AS last_error,
        CASE
            WHEN NOT r.enabled THEN 'off'::text
            WHEN e.last_run IS NULL THEN 'NEVER RAN'::text
            WHEN r.expected_every_mins IS NOT NULL AND e.last_run < (now() - make_interval(mins => r.expected_every_mins * 2)) THEN 'OVERDUE'::text
            WHEN COALESCE(e.runs_24h, 0::bigint) > 0 AND (e.errors_24h::numeric / e.runs_24h::numeric) > 0.2 THEN 'FAILING'::text
            ELSE 'ok'::text
        END AS status,
        CASE
            WHEN e.last_run IS NULL THEN 'Registered but has never produced anything. Either it has never run or it writes somewhere we are not looking.'::text
            WHEN r.expected_every_mins IS NOT NULL AND e.last_run < (now() - make_interval(mins => r.expected_every_mins * 2)) THEN ((('Expected every '::text || r.expected_every_mins) || ' minutes. Last ran '::text) || round(EXTRACT(epoch FROM now() - e.last_run) / 3600::numeric)) || ' hours ago. Silence here is not good news.'::text
            WHEN COALESCE(e.runs_24h, 0::bigint) > 0 AND (e.errors_24h::numeric / e.runs_24h::numeric) > 0.2 THEN ((e.errors_24h || ' of '::text) || e.runs_24h) || ' runs failed in 24 hours.'::text
            ELSE NULL::text
        END AS note
   FROM agent_registry r
     LEFT JOIN ev e ON e.agent_key = r.agent_key;
create or replace view public.v_agentmapper_queue as
 SELECT id,
    first_seen,
    last_seen,
    times_seen,
    file_name,
    licence,
    row_count,
    columns,
    closest_report,
    closest_missing,
    state,
    proposal ->> 'report_key'::text AS proposed_key,
    proposal ->> 'title'::text AS proposed_title,
    proposal ->> 'target_table'::text AS proposed_table,
    proposal ->> 'what_it_adds'::text AS proposed_what_it_adds,
    jsonb_array_length(COALESCE(proposal -> 'signature_cols'::text, '[]'::jsonb)) AS proposed_signature_count,
    ( SELECT count(*) AS count
           FROM jsonb_object_keys(COALESCE(metrc_report_unmapped.proposal -> 'column_map'::text, '{}'::jsonb)) jsonb_object_keys(jsonb_object_keys)) AS proposed_column_count,
    proposal,
    proposed_by,
    proposed_at,
    decided_by,
    decided_at,
    decision_note,
        CASE state
            WHEN 'new'::text THEN 'Waiting for the Metrc & Compliance agent to propose a mapping'::text
            WHEN 'proposed'::text THEN 'Ready for an administrator to approve'::text
            WHEN 'approved'::text THEN 'Mapped - re-upload the file and it will import'::text
            ELSE 'Rejected'::text
        END AS what_happens_next
   FROM metrc_report_unmapped
  ORDER BY (
        CASE state
            WHEN 'proposed'::text THEN 1
            WHEN 'new'::text THEN 2
            ELSE 3
        END), last_seen DESC;
create or replace view public.v_ai_access_status as
 SELECT user_id,
    display_name,
    enabled,
    daily_call_limit,
    monthly_call_limit,
        CASE
            WHEN uses_local_model THEN 'Own local model - costs the company nothing'::text
            WHEN COALESCE(own_key, ''::text) <> ''::text THEN ('Own '::text || COALESCE(own_key_provider, 'provider'::text)) || ' key - bills to them, costs the company nothing'::text
            ELSE 'Company allowance - billed to the company'::text
        END AS how_they_are_billed,
        CASE
            WHEN COALESCE(own_key, ''::text) = ''::text THEN NULL::text
            ELSE ("left"(own_key, 7) || '…'::text) || "right"(own_key, 4)
        END AS key_masked,
    ( SELECT count(*) AS count
           FROM ai_usage_log l
          WHERE l.user_id = a.user_id AND l.created_at >= date_trunc('month'::text, now()) AND l.answered_by = 'model'::text) AS model_calls_this_month,
    ( SELECT round(COALESCE(sum(l.cost_usd), 0::numeric), 4) AS round
           FROM ai_usage_log l
          WHERE l.user_id = a.user_id AND l.created_at >= date_trunc('month'::text, now())) AS cost_this_month_usd,
    updated_at
   FROM ai_user_access a
  ORDER BY display_name;
create or replace view public.v_ai_cost_position as
 SELECT
        CASE
            WHEN ( SELECT ai_settings.paid_model_enabled
               FROM ai_settings
              WHERE ai_settings.id = 1) THEN 'PAID MODEL IS ON'::text
            ELSE 'PAID MODEL IS OFF - the platform costs nothing to run'::text
        END AS status,
    ( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1) AS monthly_cap_usd,
    ( SELECT round(COALESCE(sum(ai_usage_log.cost_usd), 0::numeric), 2) AS round
           FROM ai_usage_log
          WHERE ai_usage_log.created_at >= date_trunc('month'::text, now())) AS spent_this_month_usd,
    ( SELECT count(*) AS count
           FROM ai_usage_log
          WHERE ai_usage_log.created_at >= date_trunc('month'::text, now()) AND ai_usage_log.answered_by = 'model'::text) AS paid_calls_this_month,
    'Every page, report, dashboard, drill-down, scheduled sweep and suggestion button is a database query. Those cost nothing and are not affected by this setting.'::text AS what_is_always_free,
    'Only a free-form typed question can ever cost money, and only while the paid model is switched on and under the cap.'::text AS what_could_ever_cost;
create or replace view public.v_ai_spend as
 SELECT to_char(date_trunc('month'::text, created_at), 'YYYY-MM'::text) AS month,
    count(*) AS calls,
    count(*) FILTER (WHERE answered_by = 'database'::text) AS answered_free_by_database,
    count(*) FILTER (WHERE answered_by = 'model'::text) AS answered_by_model,
    sum(input_tokens) AS input_tokens,
    sum(output_tokens) AS output_tokens,
    round(sum(cost_usd), 2) AS cost_usd,
    round(avg(cost_usd) FILTER (WHERE answered_by = 'model'::text), 4) AS avg_cost_per_model_call,
    ( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1) AS monthly_cap_usd,
    round((( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1)) - sum(cost_usd), 2) AS cap_remaining_usd
   FROM ai_usage_log
  GROUP BY (to_char(date_trunc('month'::text, created_at), 'YYYY-MM'::text))
  ORDER BY (to_char(date_trunc('month'::text, created_at), 'YYYY-MM'::text)) DESC;
create or replace view public.v_ai_spend_today as
 SELECT count(*) AS calls_today,
    count(*) FILTER (WHERE answered_by = 'database'::text) AS free_today,
    round(COALESCE(sum(cost_usd), 0::numeric), 4) AS cost_today,
    ( SELECT round(COALESCE(sum(ai_usage_log_1.cost_usd), 0::numeric), 2) AS round
           FROM ai_usage_log ai_usage_log_1
          WHERE ai_usage_log_1.created_at >= date_trunc('month'::text, now())) AS cost_this_month,
    ( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1) AS cap
   FROM ai_usage_log
  WHERE created_at >= date_trunc('day'::text, now());
create or replace view public.v_ai_usage_summary as
 SELECT COALESCE(u.display_name, u.user_id::text) AS person,
    count(*) FILTER (WHERE l.created_at >= CURRENT_DATE) AS calls_today,
    count(*) FILTER (WHERE l.created_at >= date_trunc('month'::text, now())) AS calls_this_month,
    round(COALESCE(sum(l.cost_usd) FILTER (WHERE l.created_at >= date_trunc('month'::text, now())), 0::numeric), 2) AS cost_this_month,
    COALESCE(a.daily_call_limit, ( SELECT ai_settings.default_daily_calls
           FROM ai_settings
          WHERE ai_settings.id = 1)) AS daily_limit,
    COALESCE(a.monthly_call_limit, ( SELECT ai_settings.default_monthly_calls
           FROM ai_settings
          WHERE ai_settings.id = 1)) AS monthly_limit,
    a.enabled,
    a.allowed_features
   FROM ai_usage_log l
     RIGHT JOIN ai_user_access a ON a.user_id = l.user_id
     LEFT JOIN ai_user_access u ON u.user_id = a.user_id
  GROUP BY (COALESCE(u.display_name, u.user_id::text)), a.daily_call_limit, a.monthly_call_limit, a.enabled, a.allowed_features;
create or replace view public.v_alert_center as
 SELECT a.id,
    a.severity,
    a.source,
    a.subject,
    a.raised_on,
    a.days_open,
    a.reminder_number,
    a.read_at,
    a.resolved_at,
    a.resolved_note,
    d.days_deferred,
    d.latest_reason,
    n.note_count,
    n.latest_note,
    n.latest_note_author,
    t.order_no AS ticket,
    t.status AS ticket_status,
    t.due_on AS ticket_due,
    e.full_name AS ticket_assignee,
    concat_ws(' → '::text, 'Raised '::text || to_char(a.raised_on::timestamp with time zone, 'DD Mon'::text),
        CASE
            WHEN a.read_at IS NOT NULL THEN 'Acknowledged'::text
            ELSE NULL::text
        END,
        CASE
            WHEN COALESCE(d.days_deferred, 0::bigint) > 0 THEN 'Deferred ×'::text || d.days_deferred
            ELSE NULL::text
        END,
        CASE
            WHEN t.order_no IS NOT NULL THEN (('Order '::text || t.order_no) || ' → '::text) || COALESCE(e.full_name, '?'::text)
            ELSE NULL::text
        END,
        CASE
            WHEN a.resolved_at IS NOT NULL THEN 'Resolved '::text || to_char(a.resolved_at, 'DD Mon'::text)
            ELSE NULL::text
        END) AS custody_line,
        CASE
            WHEN a.resolved_at IS NOT NULL THEN 'CLOSED'::text
            WHEN t.order_no IS NOT NULL AND (COALESCE(t.status, 'open'::text) <> ALL (ARRAY['done'::text, 'completed'::text])) THEN 'IN PROGRESS — order '::text || t.order_no
            WHEN COALESCE(d.deferred_today, false) THEN 'DEFERRED — today''s reason on record'::text
            WHEN a.read_at IS NULL THEN 'ACKNOWLEDGE'::text
            ELSE 'DECIDE — assign it, resolve it, or defer it with today''s reason'::text
        END AS next_required_move
   FROM alert_outbox a
     LEFT JOIN LATERAL ( SELECT count(*) AS days_deferred,
            bool_or(alert_deferral.deferred_on = CURRENT_DATE) AS deferred_today,
            (array_agg(alert_deferral.reason_note ORDER BY alert_deferral.deferred_on DESC))[1] AS latest_reason
           FROM alert_deferral
          WHERE alert_deferral.alert_key = ('alert:'::text || a.id)) d ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS note_count,
            (array_agg(alert_note.body ORDER BY alert_note.created_at DESC))[1] AS latest_note,
            (array_agg(alert_note.author ORDER BY alert_note.created_at DESC))[1] AS latest_note_author
           FROM alert_note
          WHERE alert_note.alert_id = a.id) n ON true
     LEFT JOIN LATERAL ( SELECT tasks.order_no,
            tasks.status,
            tasks.due_on,
            tasks.assignee_employee_id
           FROM tasks
          WHERE tasks.source_view = 'alert'::text AND tasks.source_kpi = a.id::text
          ORDER BY tasks.created_at DESC
         LIMIT 1) t ON true
     LEFT JOIN LATERAL ( SELECT emp.full_name
           FROM employees emp
          WHERE emp.id = t.assignee_employee_id) e ON true;
create or replace view public.v_alert_email_recipients as
 SELECT r.role,
    r.full_name,
    r.email,
    'alert_recipient'::text AS from_where,
    r.is_platform_user
   FROM alert_recipient r
  WHERE r.active AND COALESCE(btrim(r.email), ''::text) <> ''::text AND f_role_can('admin_settings'::text)
UNION ALL
 SELECT COALESCE(u.role::text, 'member'::text) AS role,
    COALESCE(u.display_name, au.email::text) AS full_name,
    au.email::text AS email,
    'auth.users (platform login)'::text AS from_where,
    true AS is_platform_user
   FROM auth.users au
     LEFT JOIN app_users u ON u.user_id = au.id
  WHERE au.email IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM alert_recipient r
          WHERE lower(btrim(r.email)) = lower(au.email::text))) AND f_role_can('admin_settings'::text);
create or replace view public.v_alert_email_recipients_internal as
 SELECT r.role,
    r.full_name,
    r.email,
    'alert_recipient'::text AS from_where,
    r.is_platform_user
   FROM alert_recipient r
  WHERE r.active AND COALESCE(btrim(r.email), ''::text) <> ''::text
UNION
 SELECT COALESCE(u.role::text, 'member'::text) AS role,
    COALESCE(u.display_name, au.email::text) AS full_name,
    au.email::text AS email,
    'auth.users (platform login)'::text AS from_where,
    true AS is_platform_user
   FROM auth.users au
     LEFT JOIN app_users u ON u.user_id = au.id
  WHERE au.email IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM alert_recipient r
          WHERE lower(btrim(r.email)) = lower(au.email::text)));
create or replace view public.v_alert_email_status as
 SELECT ( SELECT (configurations.value ->> 'enabled'::text)::boolean AS bool
           FROM configurations
          WHERE configurations.key = 'alert_email'::text) AS email_enabled,
    ( SELECT configurations.value ->> 'provider'::text
           FROM configurations
          WHERE configurations.key = 'alert_email'::text) AS provider,
    ( SELECT count(*) AS count
           FROM alert_outbox
          WHERE alert_outbox.channel = 'email'::text AND alert_outbox.sent_at IS NULL AND alert_outbox.resolved_at IS NULL) AS queued_unsent,
    f_alert_recipient_count()::bigint AS addresses_on_file,
    ( SELECT count(DISTINCT item_alert_route.role) AS count
           FROM item_alert_route
          WHERE item_alert_route.notify_email AND item_alert_route.active) AS roles_wanting_email,
        CASE
            WHEN NOT COALESCE(( SELECT (configurations.value ->> 'enabled'::text)::boolean AS bool
               FROM configurations
              WHERE configurations.key = 'alert_email'::text), false) THEN ('EMAIL NOT CONFIGURED - '::text || (( SELECT count(*) AS count
               FROM alert_outbox
              WHERE alert_outbox.channel = 'email'::text AND alert_outbox.sent_at IS NULL AND alert_outbox.resolved_at IS NULL))) || ' alerts queued and holding. They are not lost and they are not sent.'::text
            WHEN f_alert_recipient_count() = 0 THEN 'EMAIL ON BUT NOBODY TO SEND TO - no addresses on file.'::text
            ELSE ((('Email is on. '::text || (( SELECT count(*) AS count
               FROM alert_outbox
              WHERE alert_outbox.channel = 'email'::text AND alert_outbox.sent_at IS NULL AND alert_outbox.resolved_at IS NULL))) || ' waiting to go to '::text) || f_alert_recipient_count()) || ' addresses.'::text
        END AS status;
create or replace view public.v_all_sync_runs as
 SELECT 'Metrc / Sheets / ClickUp'::text AS system,
    COALESCE(r.endpoint, '?'::text) AS endpoint,
    COALESCE(r.license, '-'::text) AS license,
    r.status,
    r.records,
    r.started_at,
    r.finished_at,
    "left"(r.error, 400) AS error
   FROM metrc_sync_runs r
UNION ALL
 SELECT 'Apex Trading'::text AS system,
    a.entity AS endpoint,
    '-'::text AS license,
    a.status,
    COALESCE(a.rows_written, a.rows_seen) AS records,
    a.started_at,
    a.finished_at,
    "left"(a.error, 400) AS error
   FROM apex_sync_run a;
create or replace view public.v_allocation_queue as
 SELECT id,
    request_no,
    status,
    requester_name,
    requester_department,
    decider_name,
    decided_at,
    decision_reason,
    material_name,
    strain,
    stream,
    source_kind,
    source_ref,
    quantity,
    uom,
    pounds,
    destination,
    purpose,
    needed_by,
    priority,
    created_at,
    CURRENT_DATE - created_at::date AS days_waiting,
        CASE
            WHEN status = 'pending'::text AND needed_by IS NOT NULL AND needed_by < CURRENT_DATE THEN 'PAST ITS NEEDED-BY DATE and still not decided'::text
            WHEN status = 'pending'::text AND (CURRENT_DATE - created_at::date) > 7 THEN 'WAITING OVER A WEEK - this material cannot move until it is decided'::text
            WHEN status = 'pending'::text THEN 'Awaiting Vincent'::text
            WHEN status = 'approved'::text THEN (('Approved by '::text || COALESCE(decider_name, '?'::text)) || ' on '::text) || COALESCE(decided_at::date::text, '?'::text)
            WHEN status = 'denied'::text THEN 'Denied - '::text || COALESCE(decision_reason, 'no reason recorded'::text)
            ELSE status
        END AS "position"
   FROM allocation_requests r
  ORDER BY (
        CASE status
            WHEN 'pending'::text THEN 0
            ELSE 1
        END), (
        CASE
            WHEN needed_by IS NOT NULL AND needed_by < CURRENT_DATE THEN 0
            ELSE 1
        END), created_at;
create or replace view public.v_apex_entity_status as
 WITH counts AS (
         SELECT apex_raw.entity,
            count(*) AS rows_stored,
            max(apex_raw.fetched_at) AS newest_row
           FROM apex_raw
          GROUP BY apex_raw.entity
        ), lastrun AS (
         SELECT DISTINCT ON (apex_sync_run.entity) apex_sync_run.entity,
            apex_sync_run.status,
            apex_sync_run.started_at,
            apex_sync_run.rows_written,
            apex_sync_run.error
           FROM apex_sync_run
          ORDER BY apex_sync_run.entity, apex_sync_run.started_at DESC
        )
 SELECT e.entity,
    e.kind,
    e.endpoint,
    e.api_version,
    e.required,
    e.supports_delta,
    e.min_interval_minutes,
    w.last_success_at,
    w.consecutive_errors,
    COALESCE(c.rows_stored, 0::bigint) AS rows_stored,
    c.newest_row,
    r.status AS last_status,
    r.started_at AS last_attempt,
    r.rows_written AS last_rows,
    "left"(r.error, 300) AS last_error,
        CASE
            WHEN w.last_success_at IS NULL THEN true
            ELSE (EXTRACT(epoch FROM now() - w.last_success_at) / 60::numeric) >= e.min_interval_minutes::numeric
        END AS due,
        CASE
            WHEN w.last_success_at IS NULL THEN 'never pulled'::text
            ELSE GREATEST(0::numeric, e.min_interval_minutes::numeric - floor(EXTRACT(epoch FROM now() - w.last_success_at) / 60::numeric))::integer || ' min until due'::text
        END AS due_text
   FROM apex_entity e
     LEFT JOIN apex_watermark w ON w.entity = e.entity
     LEFT JOIN counts c ON c.entity = e.entity
     LEFT JOIN lastrun r ON r.entity = e.entity;
create or replace view public.v_apex_field_coverage as
 WITH seen AS (
         SELECT r.entity,
            k.key AS apex_key,
            count(*) AS payloads_carrying_it,
            max(r.fetched_at) AS last_seen
           FROM apex_raw r,
            LATERAL jsonb_object_keys(r.payload) k(key)
          GROUP BY r.entity, k.key
        ), totals AS (
         SELECT apex_raw.entity,
            count(*) AS payloads
           FROM apex_raw
          GROUP BY apex_raw.entity
        )
 SELECT s.entity,
    s.apex_key,
    s.payloads_carrying_it,
    t.payloads AS payloads_for_entity,
    round(100.0 * s.payloads_carrying_it::numeric / NULLIF(t.payloads, 0)::numeric, 1) AS pct_of_payloads,
    s.last_seen,
    COALESCE(m.disposition, 'UNDECIDED'::text) AS disposition,
    m.target_table,
    m.target_column,
    m.why,
    m.decided_by
   FROM seen s
     JOIN totals t ON t.entity = s.entity
     LEFT JOIN apex_field_map m ON m.entity = s.entity AND m.apex_key = s.apex_key;
create or replace view public.v_apex_order_metrc_link as
 WITH apex AS (
         SELECT r.apex_id AS apex_order_id,
            btrim(r.payload ->> 'invoice_number'::text) AS invoice_number,
            NULLIF(regexp_replace(r.payload ->> 'invoice_number'::text, '\D'::text, ''::text, 'g'::text), ''::text) AS invoice_digits,
            NULLIF(r.payload ->> 'order_date'::text, ''::text)::date AS order_date,
            NULLIF(r.payload ->> 'delivery_date'::text, ''::text)::date AS delivery_date,
            NULLIF(btrim(r.payload ->> 'buyer_state_license'::text), ''::text) AS buyer_state_license,
            NULLIF(r.payload ->> 'buyer_id'::text, ''::text) AS apex_buyer_id,
            round(NULLIF(r.payload ->> 'total_raw'::text, ''::text)::numeric / (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'apex_money_raw_minor_units'::text)), 2) AS total_dollars,
            (r.payload ->> 'cancelled'::text) <> ALL (ARRAY[''::text, '0'::text, 'false'::text]) AS cancelled,
            jsonb_array_length(COALESCE(r.payload -> 'items'::text, '[]'::jsonb)) AS line_count,
            NULLIF(btrim(r.payload ->> 'split_from_order_id'::text), ''::text) AS split_from_order_id
           FROM apex_raw r
          WHERE r.entity = 'shipping-orders'::text
        ), dupes AS (
         SELECT apex.invoice_digits
           FROM apex
          WHERE apex.invoice_digits IS NOT NULL
          GROUP BY apex.invoice_digits
         HAVING count(DISTINCT apex.apex_order_id) > 1
        ), bridge AS (
         SELECT NULLIF(regexp_replace(w.invoice_number, '\D'::text, ''::text, 'g'::text), ''::text) AS invoice_digits,
            count(DISTINCT w.manifest_number) AS metrc_manifests,
            count(*) AS metrc_wholesale_rows,
            count(*) FILTER (WHERE w.voided) AS voided_rows,
            min(w.created_on) AS first_metrc_date,
            max(w.created_on) AS last_metrc_date,
            string_agg(DISTINCT w.destination_licence, ', '::text) AS metrc_destination_licences
           FROM metrc_rpt_wholesale w
          WHERE NULLIF(btrim(w.invoice_number), ''::text) IS NOT NULL
          GROUP BY (NULLIF(regexp_replace(w.invoice_number, '\D'::text, ''::text, 'g'::text), ''::text))
        ), tags AS (
         SELECT NULLIF(regexp_replace(w.invoice_number, '\D'::text, ''::text, 'g'::text), ''::text) AS invoice_digits,
            count(DISTINCT pt.package_tag) AS package_tags
           FROM metrc_rpt_wholesale w
             JOIN metrc_rpt_package_transfers pt ON pt.manifest_number = w.manifest_number
          WHERE NULLIF(btrim(w.invoice_number), ''::text) IS NOT NULL
          GROUP BY (NULLIF(regexp_replace(w.invoice_number, '\D'::text, ''::text, 'g'::text), ''::text))
        )
 SELECT a.apex_order_id,
    a.invoice_number,
    a.invoice_digits,
    a.order_date,
    a.delivery_date,
    a.buyer_state_license,
    a.apex_buyer_id,
    a.total_dollars,
    a.cancelled,
    a.line_count,
    a.split_from_order_id,
    b.metrc_manifests,
    b.metrc_wholesale_rows,
    b.voided_rows,
    b.metrc_destination_licences,
    b.first_metrc_date,
    b.last_metrc_date,
    COALESCE(t.package_tags, 0::bigint) AS package_tags,
    d.invoice_digits IS NOT NULL AS invoice_number_is_ambiguous,
        CASE
            WHEN a.invoice_digits IS NULL THEN 'NO INVOICE NUMBER'::text
            WHEN d.invoice_digits IS NOT NULL THEN 'AMBIGUOUS INVOICE NUMBER'::text
            WHEN b.invoice_digits IS NOT NULL THEN 'MATCHED'::text
            WHEN a.cancelled THEN 'EXPLAINED — cancelled'::text
            WHEN a.line_count = 0 THEN 'EXPLAINED — no line items'::text
            WHEN COALESCE(a.total_dollars, 0::numeric) = 0::numeric THEN 'EXPLAINED — zero value'::text
            ELSE 'APEX ONLY — UNEXPLAINED'::text
        END AS link_status,
        CASE
            WHEN b.invoice_digits IS NOT NULL THEN 'invoice number, digits normalised (Apex "TWISTE-1737" = Metrc "1737"). '::text || 'Operator-entered free text on the Metrc side, so a mistype breaks it.'::text
            ELSE NULL::text
        END AS match_basis
   FROM apex a
     LEFT JOIN bridge b ON b.invoice_digits = a.invoice_digits
     LEFT JOIN tags t ON t.invoice_digits = a.invoice_digits
     LEFT JOIN dupes d ON d.invoice_digits = a.invoice_digits;
create or replace view public.v_assertion_coverage as
 WITH tests AS (
         SELECT a.assertion,
            a.plain_english,
            a.no_materiality_floor,
            count(e.test_key) AS examination_tests,
            count(e.test_key) FILTER (WHERE e.where_it_lives IS NULL) AS cannot_produce,
            count(DISTINCT e.control_key) AS named_controls
           FROM audit_assertion a
             LEFT JOIN examination_standard e ON e.assertion = a.assertion
          GROUP BY a.assertion, a.plain_english, a.no_materiality_floor
        )
 SELECT assertion,
    plain_english,
    no_materiality_floor,
    examination_tests,
    cannot_produce,
    named_controls,
        CASE
            WHEN examination_tests = 0 THEN 'NO TEST AT ALL — assertion is unexamined'::text
            WHEN named_controls = 0 THEN 'TESTED BUT UNGUARDED — no automated control'::text
            WHEN cannot_produce > 0 THEN ('PARTLY UNPRODUCIBLE — '::text || cannot_produce) || ' test(s) have no evidence source'::text
            ELSE 'COVERED'::text
        END AS coverage_verdict
   FROM tests t
  ORDER BY (named_controls = 0) DESC, cannot_produce DESC, assertion;
create or replace view public.v_auditor_heartbeat as
 SELECT c.checker_key,
    c.title,
    c.tier,
    c.runs_where,
    c.expected_interval,
    c.enabled,
    l.last_run,
        CASE
            WHEN l.last_run IS NULL THEN NULL::interval
            ELSE now() - l.last_run
        END AS since_last_run,
    c.fixture_proves_it_fails,
        CASE
            WHEN NOT c.enabled THEN 'DISABLED'::text
            WHEN l.last_run IS NULL THEN 'NEVER REPORTED'::text
            WHEN c.expected_interval IS NULL THEN 'ON DEMAND'::text
            WHEN (now() - l.last_run) > (c.expected_interval * 2::double precision) THEN 'DARK'::text
            WHEN (now() - l.last_run) > c.expected_interval THEN 'LATE'::text
            ELSE 'ALIVE'::text
        END AS heartbeat,
        CASE
            WHEN l.last_run IS NULL AND c.enabled THEN ((('Registered and enabled, but has never written a verdict to conformance_ledger. '::text || 'That may mean it never ran, OR that it runs and reports elsewhere — page-canary '::text) || 'writes to canary_runs, the watchdog to watchdog_findings, and both ran today. '::text) || 'Either way its result is invisible to the coverage map, so a green platform '::text) || 'cannot be told apart from an unwatched one.'::text
            WHEN NOT c.fixture_proves_it_fails THEN ('Has reported, but nobody has ever seen it FAIL on a deliberate fixture. Unproven '::text || 'checks can be vacuous — the schema baseline gate printed PASS for a day while '::text) || 'production drifted 16 tables, because it only read a clock.'::text
            ELSE NULL::text
        END AS why_it_matters
   FROM checker_registry c
     LEFT JOIN ( SELECT conformance_ledger.checker_key,
            max(conformance_ledger.ran_at) AS last_run
           FROM conformance_ledger
          GROUP BY conformance_ledger.checker_key) l ON l.checker_key = c.checker_key;
create or replace view public.v_basis_claim_audit as
 SELECT c.relname AS relation,
    a.attname AS column_name,
    b.claim,
    b.required_factor,
    pg_get_viewdef(c.oid, true) ~* b.proof_pattern AS honours_the_claim,
        CASE
            WHEN pg_get_viewdef(c.oid, true) ~* b.proof_pattern THEN 'ok'::text
            ELSE ('CLAIMS '::text || upper(b.claim)) || ' BUT DOES NOT APPLY IT'::text
        END AS verdict,
    b.what_it_means,
    b.how_to_correct
   FROM pg_class c
     JOIN pg_namespace n ON n.oid = c.relnamespace
     JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
     JOIN basis_claim b ON b.active AND a.attname ~* b.name_pattern
  WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"]));
create or replace view public.v_bridge_performance as
 WITH j AS (
         SELECT date_trunc('hour'::text, ai_bridge_jobs.created_at) AS hour,
            ai_bridge_jobs.status,
            ai_bridge_jobs.seconds,
            EXTRACT(epoch FROM ai_bridge_jobs.claimed_at - ai_bridge_jobs.created_at) AS waited_to_start
           FROM ai_bridge_jobs
          WHERE ai_bridge_jobs.created_at > (now() - '7 days'::interval)
        )
 SELECT hour,
    count(*) AS questions,
    count(*) FILTER (WHERE status = 'done'::text) AS answered,
    count(*) FILTER (WHERE status = 'error'::text) AS failed,
    count(*) FILTER (WHERE status = 'running'::text) AS still_running,
    round(avg(seconds) FILTER (WHERE status = 'done'::text))::integer AS avg_seconds,
    round(percentile_cont(0.50::double precision) WITHIN GROUP (ORDER BY (seconds::double precision)) FILTER (WHERE status = 'done'::text))::integer AS p50_seconds,
    round(percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (seconds::double precision)) FILTER (WHERE status = 'done'::text))::integer AS p95_seconds,
    max(seconds) FILTER (WHERE status = 'done'::text) AS slowest_seconds,
    round(avg(waited_to_start))::integer AS avg_queue_wait_seconds
   FROM j
  GROUP BY hour
  ORDER BY hour DESC;
create or replace view public.v_bridge_status as
 SELECT machine,
    last_seen,
    version,
    (now() - last_seen) < '00:01:30'::interval AS online,
    round(EXTRACT(epoch FROM now() - last_seen))::integer AS seconds_since,
    (last_seen AT TIME ZONE 'America/New_York'::text) AS last_seen_et,
        CASE
            WHEN (now() - last_seen) < '00:01:30'::interval THEN 'Answering on '::text || machine
            WHEN (now() - last_seen) < '01:00:00'::interval THEN (('Stopped '::text || round(EXTRACT(epoch FROM now() - last_seen) / 60::numeric)) || ' minutes ago on '::text) || machine
            ELSE (('Last reported in '::text || to_char((last_seen AT TIME ZONE 'America/New_York'::text), 'DD Mon HH24:MI'::text)) || ' on '::text) || machine
        END AS verdict,
    ( SELECT count(*) AS count
           FROM ai_bridge_jobs j
          WHERE j.status = 'pending'::text) AS waiting,
    ( SELECT count(*) AS count
           FROM ai_bridge_jobs j
          WHERE j.status = 'running'::text) AS in_progress
   FROM ai_bridge_heartbeat h;
create or replace view public.v_business_rules as
 SELECT key,
    label,
    value,
    unit,
    what_it_means,
    where_it_came_from,
    set_by,
    updated_at::date AS set_on,
    ( SELECT count(*) AS count
           FROM information_schema.views v
          WHERE v.table_schema::name = 'public'::name AND pg_get_viewdef(quote_ident(v.table_name::text)::regclass::oid, true) ~~* (('%'::text || c.key) || '%'::text)) AS places_using_it,
        CASE
            WHEN set_by ~~ 'default%'::text THEN 'NOT YET SET BY ANYONE — this is a default. Every figure derived from it is an estimate.'::text
            ELSE ((('Set by '::text || set_by) || ' on '::text) || to_char(updated_at, 'DD Mon YYYY'::text)) || '.'::text
        END AS standing
   FROM conversion_factors c
  ORDER BY key;
create or replace view public.v_c3a_document_coverage as
 WITH pages AS (
         SELECT n.view_key,
            n.label,
            n.category,
            n.subcategory,
            n.table_ref
           FROM nav_registry n
          WHERE n.enabled AND n.table_ref IS NOT NULL
        ), cols AS (
         SELECT p.view_key,
            p.label,
            p.category,
            p.subcategory,
            p.table_ref,
            bool_or(c.column_name::name = ANY (ARRAY['package_tag'::name, 'tag'::name])) AS is_item_level,
            bool_or(c.column_name::name ~~* '%certificate%'::text OR c.column_name::name ~~* '%coa%'::text) AS has_certificate,
            bool_or(c.column_name::name ~~* '%manifest%'::text) AS has_manifest
           FROM pages p
             JOIN information_schema.columns c ON c.table_schema::name = 'public'::name AND c.table_name::name = p.table_ref
          GROUP BY p.view_key, p.label, p.category, p.subcategory, p.table_ref
        )
 SELECT view_key,
    label,
    category,
    subcategory,
    table_ref,
    has_certificate,
    has_manifest,
        CASE
            WHEN has_certificate AND has_manifest THEN 'COMPLIES'::text
            WHEN has_certificate THEN 'BREACH — certificate only, no manifest'::text
            WHEN has_manifest THEN 'BREACH — manifest only, no certificate'::text
            ELSE 'BREACH — neither document reachable from the row'::text
        END AS c3a,
        CASE
            WHEN has_certificate AND has_manifest THEN NULL::text
            ELSE ('C3a: an item row must carry both documents, openable from the row. '::text || 'Where one is absent the row states WHICH reason — never a blank, never a dash. '::text) || 'f_package_documents(tag) already returns both with a signed link; reuse it, do not rebuild it.'::text
        END AS what_to_do
   FROM cols
  WHERE is_item_level;
create or replace view public.v_catalogue_items as
 SELECT license AS licence,
    f_operation(license) AS operation,
    metrc_id,
    name AS item,
    category,
    unit_of_measure,
    strain,
    f_uom_label(unit_of_measure) AS unit_label,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE p.license = i.license AND p.item_name = i.name) AS packages_using_it,
    synced_at,
    concat_ws(' '::text, name, COALESCE(category, ''::text), COALESCE(strain, ''::text), license, f_operation(license), raw ->> 'ProductCategoryType'::text, NULLIF(raw ->> 'Description'::text, ''::text), NULLIF(raw ->> 'ItemBrandName'::text, ''::text)) AS search_text,
    'M'::text || lpad(metrc_id::text, 11, '0'::text) AS item_number,
    regexp_replace(name, '^M\d+:\s*'::text, ''::text) AS item_name,
    raw ->> 'ProductCategoryType'::text AS item_type,
    raw ->> 'QuantityType'::text AS quantity_type,
    raw ->> 'DefaultLabTestingState'::text AS default_lab_testing_state,
    raw ->> 'ApprovalStatus'::text AS approval,
    NULLIF(raw ->> 'ApprovalStatusDateTime'::text, ''::text)::timestamp with time zone AS approval_date,
    NULLIF(raw ->> 'CreatedDateTime'::text, ''::text)::timestamp with time zone AS created_date,
    NULLIF(raw ->> 'ItemBrandName'::text, ''::text) AS item_brand_name,
    NULLIF(raw ->> 'IsUsed'::text, ''::text)::boolean AS in_use,
    NULLIF(raw ->> 'UnitThcPercent'::text, ''::text)::numeric AS unit_thc_percent,
    NULLIF(raw ->> 'UnitThcContent'::text, ''::text)::numeric AS unit_thc_content,
    NULLIF(raw ->> 'UnitThcContentUnitOfMeasureName'::text, ''::text) AS unit_thc_content_uom,
    NULLIF(raw ->> 'UnitThcContentDose'::text, ''::text)::numeric AS unit_thc_content_dose,
    NULLIF(raw ->> 'UnitThcAPercent'::text, ''::text)::numeric AS unit_thca_percent,
    NULLIF(raw ->> 'UnitThcAContent'::text, ''::text)::numeric AS unit_thca_content,
    NULLIF(raw ->> 'UnitCbdPercent'::text, ''::text)::numeric AS unit_cbd_percent,
    NULLIF(raw ->> 'UnitCbdContent'::text, ''::text)::numeric AS unit_cbd_content,
    NULLIF(raw ->> 'UnitCbdContentUnitOfMeasureName'::text, ''::text) AS unit_cbd_content_uom,
    NULLIF(raw ->> 'UnitCbdContentDose'::text, ''::text)::numeric AS unit_cbd_content_dose,
    NULLIF(raw ->> 'UnitCbdAPercent'::text, ''::text)::numeric AS unit_cbda_percent,
    NULLIF(raw ->> 'UnitCbdAContent'::text, ''::text)::numeric AS unit_cbda_content,
    NULLIF(raw ->> 'UnitVolume'::text, ''::text)::numeric AS unit_volume,
    NULLIF(raw ->> 'UnitVolumeUnitOfMeasureName'::text, ''::text) AS unit_volume_uom,
    NULLIF(raw ->> 'UnitWeight'::text, ''::text)::numeric AS unit_weight,
    NULLIF(raw ->> 'UnitWeightUnitOfMeasureName'::text, ''::text) AS unit_weight_uom,
    NULLIF(raw ->> 'UnitQuantity'::text, ''::text)::numeric AS unit_quantity,
    NULLIF(raw ->> 'UnitQuantityUnitOfMeasureName'::text, ''::text) AS unit_quantity_uom,
    NULLIF(raw ->> 'NumberOfDoses'::text, ''::text)::numeric AS number_of_doses,
    NULLIF(raw ->> 'ServingSize'::text, ''::text) AS serving_size,
    NULLIF(raw ->> 'IsExpirationDateRequired'::text, ''::text)::boolean AS expiration_date_required,
    NULLIF(raw ->> 'IsSellByDateRequired'::text, ''::text)::boolean AS sell_by_date_required,
    NULLIF(raw ->> 'IsUseByDateRequired'::text, ''::text)::boolean AS use_by_date_required,
    NULLIF(raw ->> 'HasExpirationDate'::text, ''::text)::boolean AS has_expiration_date,
    NULLIF(raw ->> 'HasSellByDate'::text, ''::text)::boolean AS has_sell_by_date,
    NULLIF(raw ->> 'HasUseByDate'::text, ''::text)::boolean AS has_use_by_date,
    NULLIF(raw ->> 'Description'::text, ''::text) AS description,
    NULLIF(raw ->> 'PublicIngredients'::text, ''::text) AS public_ingredients,
    NULLIF(raw ->> 'AdministrationMethod'::text, ''::text) AS administration_method,
    NULLIF(raw ->> 'Allergens'::text, ''::text) AS allergens,
    NULLIF(raw ->> 'ProcessingJobCategoryName'::text, ''::text) AS processing_job_category,
    NULLIF(raw ->> 'ProcessingJobTypeName'::text, ''::text) AS processing_job_type,
    NULLIF(raw ->> 'LabTestBatchNames'::text, ''::text) AS lab_test_batch_names,
    NULLIF(raw ->> 'StrainId'::text, ''::text)::bigint AS strain_metrc_id,
        CASE
            WHEN jsonb_typeof(raw -> 'ProductImages'::text) = 'array'::text THEN jsonb_array_length(raw -> 'ProductImages'::text)
            ELSE 0
        END AS product_images,
        CASE
            WHEN jsonb_typeof(raw -> 'LabelImages'::text) = 'array'::text THEN jsonb_array_length(raw -> 'LabelImages'::text)
            ELSE 0
        END AS label_images,
        CASE
            WHEN jsonb_typeof(raw -> 'PackagingImages'::text) = 'array'::text THEN jsonb_array_length(raw -> 'PackagingImages'::text)
            ELSE 0
        END AS packaging_images
   FROM metrc_items i;
create or replace view public.v_catalogue_locations as
 SELECT license AS licence,
    f_operation(license) AS operation,
    metrc_id,
    name AS location,
    location_type,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE p.license = l.license AND p.location = l.name) AS packages_here,
    ( SELECT count(*) AS count
           FROM metrc_plants p
          WHERE p.license = l.license AND p.room = l.name) AS plants_here,
    synced_at,
    concat_ws(' '::text, name, COALESCE(location_type, ''::text), license, f_operation(license)) AS search_text,
    NULLIF(raw ->> 'LocationTypeId'::text, ''::text)::bigint AS location_type_metrc_id,
    NULLIF(raw ->> 'ForPlantBatches'::text, ''::text)::boolean AS can_hold_plant_batches,
    NULLIF(raw ->> 'ForPlants'::text, ''::text)::boolean AS can_hold_plants,
    NULLIF(raw ->> 'ForHarvests'::text, ''::text)::boolean AS can_hold_harvests,
    NULLIF(raw ->> 'ForPackages'::text, ''::text)::boolean AS can_hold_packages
   FROM metrc_locations l;
create or replace view public.v_catalogue_strains as
 SELECT license AS licence,
    f_operation(license) AS operation,
    metrc_id,
    name AS strain,
    testing_status,
    thc_level,
    cbd_level,
    ( SELECT count(*) AS count
           FROM metrc_items i
          WHERE i.license = s.license AND i.strain = s.name) AS items_using_it,
    ( SELECT count(*) AS count
           FROM metrc_plants p
          WHERE p.license = s.license AND p.strain = s.name) AS plants,
    synced_at,
    concat_ws(' '::text, name, license, f_operation(license), NULLIF(raw ->> 'Genetics'::text, ''::text)) AS search_text,
    NULLIF(raw ->> 'Genetics'::text, ''::text) AS genetics,
    NULLIF(raw ->> 'IndicaPercentage'::text, ''::text)::numeric AS indica_percent,
    NULLIF(raw ->> 'SativaPercentage'::text, ''::text)::numeric AS sativa_percent,
    NULLIF(raw ->> 'IsUsed'::text, ''::text)::boolean AS in_use
   FROM metrc_strains s;
create or replace view public.v_ceo_recommendations as
 SELECT severity,
    agent,
    headline,
    detail,
    scope,
    COALESCE(dollars, 0::numeric) AS dollars_at_stake,
    action AS recommended_action,
    drill_to,
    detected_at
   FROM agent_findings
  WHERE resolved_at IS NULL
  ORDER BY (COALESCE(dollars, 0::numeric)) DESC, (
        CASE severity
            WHEN 'critical'::text THEN 0
            WHEN 'elevated'::text THEN 1
            ELSE 2
        END), detected_at DESC;
create or replace view public.v_check_trust as
 SELECT COALESCE(d.check_key, c.checker_key) AS check_key,
    c.title,
    c.enabled,
    COALESCE(c.fixture_proves_it_fails, false) AS proven_it_can_fail,
    count(d.id) FILTER (WHERE d.fixed_at IS NULL) AS open_defects,
    count(d.id) FILTER (WHERE d.fixed_at IS NOT NULL) AS fixed_defects,
    max(d.found_at) FILTER (WHERE d.fixed_at IS NULL) AS newest_open_defect,
        CASE
            WHEN count(d.id) FILTER (WHERE d.fixed_at IS NULL) > 0 THEN 'UNTRUSTED - known defect, read its output with the defect in hand'::text
            WHEN NOT COALESCE(c.fixture_proves_it_fails, false) THEN 'UNPROVEN - nobody has ever watched this check fail, so nobody knows it can'::text
            ELSE 'trusted'::text
        END AS trust
   FROM checker_registry c
     FULL JOIN check_defect d ON d.check_key = c.checker_key
  GROUP BY (COALESCE(d.check_key, c.checker_key)), c.title, c.enabled, c.fixture_proves_it_fails;
create or replace view public.v_checks_missing_in_flight as
 SELECT check_key,
    title,
    severity,
    tolerance_pct,
    measures_a_process,
    settles_within,
        CASE
            WHEN measures_a_process AND settles_within IS NULL THEN 'PROCESS CHECK WITH NO SETTLING PERIOD - counts in-flight work as failed'::text
            WHEN measures_a_process AND tolerance_pct = 0::numeric AND settles_within IS NULL THEN 'ZERO TOLERANCE on a metric that cannot reach zero while anything is in flight'::text
            ELSE 'declared'::text
        END AS state,
    in_flight_rule
   FROM verification_checks
  WHERE measures_a_process
  ORDER BY (settles_within IS NULL) DESC, check_key;
create or replace view public.v_client_fees_due as
 SELECT f.client_key,
    mc.client_name,
    f.fee_type,
    f.amount_usd,
    f.period,
    f.direction,
    f.effective_from,
    f.effective_to,
    f.effective_to IS NULL OR f.effective_to >= CURRENT_DATE AS in_force,
        CASE f.period
            WHEN 'monthly'::text THEN f.amount_usd * 12::numeric
            WHEN 'weekly'::text THEN f.amount_usd * 52::numeric
            WHEN 'quarterly'::text THEN f.amount_usd * 4::numeric
            WHEN 'annual'::text THEN f.amount_usd
            ELSE NULL::numeric
        END AS annualised_usd,
        CASE
            WHEN f.period = ANY (ARRAY['one_off'::text, 'per_unit'::text]) THEN ('Not annualised — a '::text || f.period) || ' charge has no yearly run rate.'::text
            ELSE NULL::text
        END AS why_no_annual,
    GREATEST(0, (date_part('year'::text, age(CURRENT_DATE::timestamp with time zone, f.effective_from::timestamp with time zone)) * 12::double precision + date_part('month'::text, age(CURRENT_DATE::timestamp with time zone, f.effective_from::timestamp with time zone)))::integer) AS months_elapsed,
    f.note
   FROM client_fee f
     JOIN manufacturing_client mc ON mc.client_key = f.client_key
  ORDER BY mc.client_name, f.effective_from DESC;
create or replace view public.v_clock_readiness as
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    e.login_id,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    e.hours_basis,
    e.requires_clock_in,
    e.clock_exempt_reason,
    e.pin_hash IS NOT NULL AS has_pin,
    e.badge_code IS NOT NULL AS has_badge,
        CASE
            WHEN NOT e.requires_clock_in THEN 'not on a clock'::text
            WHEN e.pin_hash IS NULL AND e.badge_code IS NULL THEN 'CANNOT CLOCK IN'::text
            WHEN e.pin_hash IS NULL THEN 'badge only'::text
            ELSE 'ready'::text
        END AS readiness
   FROM employees e
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE e.status::text = 'active'::text;
create or replace view public.v_coa_document_kind as
 SELECT document_id,
    package_tag,
    characters,
        CASE
            WHEN total_thc IS NOT NULL THEN 'potency - read'::text
            WHEN total_cbd IS NOT NULL OR total_terpenes IS NOT NULL OR total_cannabinoids IS NOT NULL THEN 'potency - partly read'::text
            WHEN microbiology IS NOT NULL OR mycotoxins IS NOT NULL OR heavy_metals IS NOT NULL OR pesticides IS NOT NULL OR solvents IS NOT NULL OR pathogens IS NOT NULL OR water_activity IS NOT NULL THEN 'safety screen - no potency expected'::text
            WHEN COALESCE(characters, 0) = 0 THEN 'no text extracted'::text
            ELSE 'unclassified - needs a person'::text
        END AS document_kind,
    total_thc,
    parse_error
   FROM coa_extract c;
create or replace view public.v_column_semantics as
 SELECT means,
    array_agg(column_name ORDER BY column_name) AS column_names
   FROM column_semantics
  GROUP BY means;
create or replace view public.v_conformance_coverage as
 WITH subjects AS (
         SELECT 'table'::text AS subject_kind,
            c_1.relname AS subject_ref
           FROM pg_class c_1
             JOIN pg_namespace n ON n.oid = c_1.relnamespace
          WHERE n.nspname = 'public'::name AND c_1.relkind = 'r'::"char"
        UNION ALL
         SELECT 'view'::text,
            c_1.relname
           FROM pg_class c_1
             JOIN pg_namespace n ON n.oid = c_1.relnamespace
          WHERE n.nspname = 'public'::name AND (c_1.relkind = ANY (ARRAY['v'::"char", 'm'::"char"]))
        UNION ALL
         SELECT 'metric'::text,
            metric_registry.metric_key
           FROM metric_registry
          WHERE metric_registry.active
        UNION ALL
         SELECT 'policy'::text,
            policy_registry.policy_key
           FROM policy_registry
          WHERE policy_registry.active
        ), checked AS (
         SELECT conformance_ledger.subject_kind,
            conformance_ledger.subject_ref,
            max(conformance_ledger.ran_at) AS last_verdict_at,
            count(*) AS verdicts,
            count(*) FILTER (WHERE conformance_ledger.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AS open_problems
           FROM conformance_ledger
          GROUP BY conformance_ledger.subject_kind, conformance_ledger.subject_ref
        )
 SELECT s.subject_kind,
    s.subject_ref,
    COALESCE(c.verdicts, 0::bigint) AS verdicts,
    c.last_verdict_at,
    COALESCE(c.open_problems, 0::bigint) AS open_problems,
        CASE
            WHEN c.subject_ref IS NULL THEN 'NEVER CHECKED'::text
            ELSE 'covered'::text
        END AS coverage
   FROM subjects s
     LEFT JOIN checked c ON c.subject_kind = s.subject_kind AND c.subject_ref = s.subject_ref;
create or replace view public.v_control_tower as
 SELECT 'late_or_at_risk_orders'::text AS metric,
    count(*)::numeric AS value
   FROM sales_orders
  WHERE (sales_orders.status = ANY (ARRAY['open'::text, 'confirmed'::text])) AND sales_orders.promised_ship_on < CURRENT_DATE
UNION ALL
 SELECT 'unconfirmed_open_orders'::text AS metric,
    count(*) AS value
   FROM sales_orders
  WHERE sales_orders.status = 'open'::text
UNION ALL
 SELECT 'testing_overdue'::text AS metric,
    count(*) AS value
   FROM test_requests
  WHERE (test_requests.status = ANY (ARRAY['planned'::test_status, 'submitted'::test_status, 'at_lab'::test_status])) AND test_requests.submit_due_on < CURRENT_DATE
UNION ALL
 SELECT 'lots_rts_missing_coa'::text AS metric,
    count(*) AS value
   FROM lots
  WHERE lots.status = 'ready_to_ship'::lot_status AND lots.coa_id IS NULL
UNION ALL
 SELECT 'lots_expired_sellable'::text AS metric,
    count(*) AS value
   FROM lots
  WHERE lots.expires_on < CURRENT_DATE AND (lots.status = ANY (ARRAY['ready_to_ship'::lot_status, 'packaging'::lot_status, 'packaging_queue'::lot_status]))
UNION ALL
 SELECT 'pending_allocations'::text AS metric,
    count(*) AS value
   FROM allocations
  WHERE allocations.approval = 'pending'::approval_status
UNION ALL
 SELECT 'blocked_work_orders'::text AS metric,
    count(*) AS value
   FROM work_orders w
  WHERE (w.status = ANY (ARRAY['ready'::wo_status, 'released'::wo_status])) AND NOT (EXISTS ( SELECT 1
           FROM allocations a
          WHERE a.work_order_id = w.id AND a.release = 'released'::release_status))
UNION ALL
 SELECT 'harvest_mass_balance_exceptions'::text AS metric,
    count(*) AS value
   FROM harvest_grades
  WHERE harvest_grades.dry_input_g > 0::numeric AND abs(harvest_grades.variance_g) > 0.01
UNION ALL
 SELECT 'licenses_expiring_60d'::text AS metric,
    count(*) AS value
   FROM licenses
  WHERE licenses.status = 'active'::text AND licenses.expires_on <= (CURRENT_DATE + 60)
UNION ALL
 SELECT 'open_p0_actions'::text AS metric,
    count(*) AS value
   FROM actions_register
  WHERE actions_register.priority = 'P0'::text AND actions_register.status <> 'complete'::text
UNION ALL
 SELECT 'metrc_reconciliation_open'::text AS metric,
    count(*) AS value
   FROM reconciliation_exceptions
  WHERE reconciliation_exceptions.status = 'open'::text
UNION ALL
 SELECT 'days_since_cash_update'::text AS metric,
    COALESCE(EXTRACT(day FROM now() - (( SELECT max(cash_snapshots.as_of)::timestamp with time zone AS max
           FROM cash_snapshots))), 999::numeric) AS value;
create or replace view public.v_cost_of_goods as
 WITH i AS (
         SELECT cost_inputs.key,
            cost_inputs.value
           FROM cost_inputs
        ), v AS (
         SELECT ( SELECT i.value
                   FROM i
                  WHERE i.key = 'run_size_g'::text) AS run_g,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'trim_cost_per_lb'::text) AS trim_lb,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'extraction_labor'::text) AS ext_lab,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'solvent_cost'::text) AS solvent,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'proc_labor_badder'::text) AS lab_badder,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'proc_labor_diamonds'::text) AS lab_diamond,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'crude_yield_pct'::text) AS crude_pct,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'diamond_yield_pct'::text) AS dia_pct,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'liquid_diamond_factor'::text) AS ld_f,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'ld_extra_cost'::text) AS ld_extra,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_packaging'::text) AS b_pack,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_fill_1g'::text) AS b_fill1,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_fill_35g'::text) AS b_fill35,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_package'::text) AS b_lab,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_rd_test'::text) AS b_rd,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_compliance'::text) AS b_comp,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_terp_05'::text) AS t05,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_terp_10'::text) AS t10,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_hardware'::text) AS v_hw,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_packaging'::text) AS v_pack,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_fill'::text) AS v_fill,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_package'::text) AS v_lab,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_compliance'::text) AS v_comp
        ), calc AS (
         SELECT v.run_g,
            v.trim_lb,
            v.ext_lab,
            v.solvent,
            v.lab_badder,
            v.lab_diamond,
            v.crude_pct,
            v.dia_pct,
            v.ld_f,
            v.ld_extra,
            v.b_pack,
            v.b_fill1,
            v.b_fill35,
            v.b_lab,
            v.b_rd,
            v.b_comp,
            v.t05,
            v.t10,
            v.v_hw,
            v.v_pack,
            v.v_fill,
            v.v_lab,
            v.v_comp,
            v.trim_lb / 454::numeric AS trim_g,
            v.run_g * (v.trim_lb / 454::numeric) AS batch_cost,
            v.crude_pct * v.run_g AS crude_g
           FROM v
        ), c2 AS (
         SELECT calc.run_g,
            calc.trim_lb,
            calc.ext_lab,
            calc.solvent,
            calc.lab_badder,
            calc.lab_diamond,
            calc.crude_pct,
            calc.dia_pct,
            calc.ld_f,
            calc.ld_extra,
            calc.b_pack,
            calc.b_fill1,
            calc.b_fill35,
            calc.b_lab,
            calc.b_rd,
            calc.b_comp,
            calc.t05,
            calc.t10,
            calc.v_hw,
            calc.v_pack,
            calc.v_fill,
            calc.v_lab,
            calc.v_comp,
            calc.trim_g,
            calc.batch_cost,
            calc.crude_g,
            (calc.batch_cost + calc.ext_lab + calc.solvent) / NULLIF(calc.crude_g, 0::numeric) AS crude_cost_g,
            calc.crude_g * calc.dia_pct AS diamond_g,
            calc.crude_g * (1::numeric - calc.dia_pct) AS rem_crude_g
           FROM calc
        ), c3 AS (
         SELECT c2.run_g,
            c2.trim_lb,
            c2.ext_lab,
            c2.solvent,
            c2.lab_badder,
            c2.lab_diamond,
            c2.crude_pct,
            c2.dia_pct,
            c2.ld_f,
            c2.ld_extra,
            c2.b_pack,
            c2.b_fill1,
            c2.b_fill35,
            c2.b_lab,
            c2.b_rd,
            c2.b_comp,
            c2.t05,
            c2.t10,
            c2.v_hw,
            c2.v_pack,
            c2.v_fill,
            c2.v_lab,
            c2.v_comp,
            c2.trim_g,
            c2.batch_cost,
            c2.crude_g,
            c2.crude_cost_g,
            c2.diamond_g,
            c2.rem_crude_g,
            (c2.diamond_g * c2.crude_cost_g + c2.lab_diamond) / NULLIF(c2.diamond_g, 0::numeric) AS diamond_per_g,
            (c2.diamond_g * c2.crude_cost_g + c2.lab_diamond + c2.ld_extra) / NULLIF(c2.diamond_g * c2.ld_f, 0::numeric) AS ld_per_g,
            (c2.rem_crude_g * c2.crude_cost_g + c2.lab_badder) / NULLIF(c2.rem_crude_g, 0::numeric) AS crude_per_g
           FROM c2
        )
 SELECT round(crude_cost_g, 4) AS crude_cost_per_gram,
    round(crude_per_g, 4) AS badder_crude_per_gram,
    round(crude_per_g * 454::numeric) AS badder_crude_per_pound,
    round(diamond_per_g, 4) AS diamond_per_gram,
    round(ld_per_g, 4) AS liquid_diamond_per_gram,
    round(ld_per_g * 454::numeric) AS liquid_diamond_per_pound,
    round(crude_per_g * 1::numeric + b_pack + b_fill1 + b_lab + b_rd + b_comp, 2) AS badder_1g_unit_cost,
    round(crude_per_g * 3.5 + b_pack + b_fill35 + b_lab + b_rd + b_comp, 2) AS badder_35g_unit_cost,
    round(ld_per_g / 2::numeric + t05 + v_hw + v_pack + v_fill + v_lab + v_comp, 2) AS vape_05g_unit_cost,
    round(ld_per_g + t10 + v_hw + v_pack + v_fill + v_lab + v_comp, 2) AS vape_10g_unit_cost,
    round(batch_cost, 2) AS batch_cost,
    round(crude_g, 1) AS crude_grams_per_batch,
    'Every figure recomputes from the Production Cost Calculator inputs. Change a cost there and '::text || 'these change, and so does the value of every package of this type on the platform.'::text AS note
   FROM c3;
create or replace view public.v_cron_health as
 SELECT jobname,
    schedule,
    active,
    runs_24h,
    failed_24h,
    failure_pct_24h,
    last_run_et,
    last_success_et,
    hours_since_success,
    verdict,
    rank,
    last_error,
    log_covers_hours,
    scheduled_since_et
   FROM ( WITH hist AS (
                 SELECT round(EXTRACT(epoch FROM now() - min(job_run_details.start_time)) / 3600.0, 1) AS log_hours
                   FROM cron.job_run_details
                ), born AS (
                 SELECT j_1.jobid,
                    ( SELECT to_timestamp(min(m.version), 'YYYYMMDDHH24MISS'::text) AS to_timestamp
                           FROM supabase_migrations.schema_migrations m
                          WHERE m.statements::text ~~ (('%'::text || j_1.jobname) || '%'::text) AND m.statements::text ~~* '%cron.schedule%'::text) AS created_at
                   FROM cron.job j_1
                ), runs AS (
                 SELECT j_1.jobid,
                    j_1.jobname,
                    j_1.schedule,
                    j_1.active,
                    count(d.runid) FILTER (WHERE d.start_time > (now() - '24:00:00'::interval)) AS runs_24h,
                    count(d.runid) FILTER (WHERE d.start_time > (now() - '24:00:00'::interval) AND d.status <> 'succeeded'::text) AS failed_24h,
                    count(d.runid) AS runs_ever,
                    max(d.start_time) AS last_start,
                    max(d.start_time) FILTER (WHERE d.status = 'succeeded'::text) AS last_success,
                    (array_agg(d.return_message ORDER BY d.start_time DESC) FILTER (WHERE d.status <> 'succeeded'::text))[1] AS last_error
                   FROM cron.job j_1
                     LEFT JOIN cron.job_run_details d ON d.jobid = j_1.jobid
                  GROUP BY j_1.jobid, j_1.jobname, j_1.schedule, j_1.active
                ), j AS (
                 SELECT r.jobid,
                    r.jobname,
                    r.schedule,
                    r.active,
                    r.runs_24h,
                    r.failed_24h,
                    r.runs_ever,
                    r.last_start,
                    r.last_success,
                    r.last_error,
                    b.created_at,
                    round(EXTRACT(epoch FROM now() - b.created_at) / 3600.0, 1) AS age_hours
                   FROM runs r
                     LEFT JOIN born b ON b.jobid = r.jobid
                )
         SELECT j.jobname,
            j.schedule,
            j.active,
            j.runs_24h,
            j.failed_24h,
                CASE
                    WHEN j.runs_24h = 0 THEN NULL::numeric
                    ELSE round(100.0 * j.failed_24h::numeric / j.runs_24h::numeric, 1)
                END AS failure_pct_24h,
            (j.last_start AT TIME ZONE 'America/New_York'::text) AS last_run_et,
            (j.last_success AT TIME ZONE 'America/New_York'::text) AS last_success_et,
                CASE
                    WHEN j.last_success IS NULL THEN NULL::numeric
                    ELSE round(EXTRACT(epoch FROM now() - j.last_success) / 3600.0, 1)
                END AS hours_since_success,
                CASE
                    WHEN NOT j.active THEN 'TURNED OFF'::text
                    WHEN j.runs_ever = 0 AND j.age_hours IS NOT NULL AND j.age_hours < 24::numeric AND j.schedule !~ '^\*/'::text THEN ('TOO NEW TO JUDGE — created '::text || j.age_hours) || ' hours ago and has not come round yet. First run is still ahead of it.'::text
                    WHEN j.runs_ever = 0 AND j.schedule ~ '\* \* [0-7]$'::text THEN ('NOT DUE YET — runs weekly, and no run of it falls inside the '::text || h.log_hours) || ' hours of history held'::text
                    WHEN j.runs_ever = 0 AND j.schedule ~ '^\*/'::text THEN ('NEVER RUN — it repeats through the day, so it has had many chances in the '::text || h.log_hours) || ' hours of history held. Nothing is purging the log.'::text
                    WHEN j.runs_ever = 0 AND h.log_hours >= 48::numeric THEN ((('NEVER RUN — daily, scheduled since '::text || COALESCE(to_char(j.created_at, 'DD Mon'::text), 'a date nobody recorded'::text)) || ', and at least two of its times fall inside the '::text) || h.log_hours) || ' hours of history held'::text
                    WHEN j.runs_ever = 0 THEN ('NEVER RUN — but the log only covers '::text || h.log_hours) || ' hours, so it may simply not have come round yet'::text
                    WHEN j.last_success IS NULL THEN 'NEVER SUCCEEDED — every attempt has failed'::text
                    WHEN j.failed_24h = 0 THEN 'HEALTHY'::text
                    WHEN j.failed_24h = j.runs_24h THEN 'FAILING EVERY RUN'::text
                    ELSE ((('FAILING INTERMITTENTLY — '::text || j.failed_24h) || ' of '::text) || j.runs_24h) || ' runs in 24h'::text
                END AS verdict,
                CASE
                    WHEN NOT j.active THEN 6
                    WHEN j.last_success IS NULL AND j.last_start IS NOT NULL THEN 1
                    WHEN j.failed_24h = j.runs_24h AND j.runs_24h > 0 THEN 1
                    WHEN j.runs_ever = 0 AND j.age_hours IS NOT NULL AND j.age_hours < 24::numeric AND j.schedule !~ '^\*/'::text THEN 5
                    WHEN j.runs_ever = 0 AND j.schedule ~ '\* \* [0-7]$'::text THEN 5
                    WHEN j.runs_ever = 0 AND (j.schedule ~ '^\*/'::text OR h.log_hours >= 48::numeric) THEN 2
                    WHEN j.runs_ever = 0 THEN 4
                    WHEN j.failed_24h > 0 THEN 3
                    ELSE 5
                END AS rank,
            "left"(COALESCE(j.last_error, ''::text), 300) AS last_error,
            h.log_hours AS log_covers_hours,
            (j.created_at AT TIME ZONE 'America/New_York'::text) AS scheduled_since_et
           FROM j
             CROSS JOIN hist h) guarded_body
  WHERE ( SELECT is_executive() AS is_executive);
create or replace view public.v_cross_license_tags as
 SELECT tag,
    count(*) AS active_rows,
    array_agg(DISTINCT license ORDER BY license) AS licenses,
    round(sum(f_to_pounds(quantity, uom)), 2) AS total_lb_across_licenses,
    max(raw ->> 'LastModified'::text) AS freshest_last_modified
   FROM metrc_packages p
  WHERE (source_state = ANY (ARRAY['active'::text, 'intransit'::text])) AND NOT COALESCE(finished, false)
  GROUP BY tag
 HAVING count(DISTINCT license) > 1;
create or replace view public.v_cross_source_reconciliation as
 WITH asof AS (
         SELECT COALESCE(max(r.as_of_date), CURRENT_DATE) AS d
           FROM metrc_rpt_harvests r
        ), api_asof AS (
         SELECT h.name,
            h.wet_weight,
            h.package_count,
            h.source_state
           FROM metrc_harvests h
             CROSS JOIN asof
          WHERE h.harvest_start <= asof.d
        ), revenue AS (
         SELECT 'Wholesale revenue'::text AS fact,
            'dollars'::text AS unit,
            'metrc_rpt_wholesale.amount'::text AS source_a,
            'metrc_rpt_package_transfers.shipper_wholesale_price'::text AS source_b,
            ( SELECT round(sum(w.amount)) AS round
                   FROM metrc_rpt_wholesale w
                  WHERE NOT COALESCE(w.voided, false) AND (w.manifest_number IN ( SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers))) AS overlap_a,
            ( SELECT round(sum(t.shipper_wholesale_price)) AS round
                   FROM metrc_rpt_package_transfers t
                  WHERE (t.manifest_number IN ( SELECT w2.manifest_number
                           FROM metrc_rpt_wholesale w2
                          WHERE NOT COALESCE(w2.voided, false)))) AS overlap_b,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_rpt_wholesale.manifest_number
                           FROM metrc_rpt_wholesale
                        EXCEPT
                         SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers) x) AS only_in_a,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers
                        EXCEPT
                         SELECT metrc_rpt_wholesale.manifest_number
                           FROM metrc_rpt_wholesale) y) AS only_in_b,
            ( SELECT round(sum(w.amount)) AS round
                   FROM metrc_rpt_wholesale w
                  WHERE NOT COALESCE(w.voided, false) AND NOT (w.manifest_number IN ( SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers))) AS value_not_covered,
            0::bigint AS after_export
        ), harvest_wet AS (
         SELECT 'Harvest wet weight'::text AS text,
            'lb'::text AS text,
            'metrc_harvests.wet_weight (grams, API, as at the export date)'::text AS text,
            'metrc_rpt_harvests.wet_lb (pounds, report)'::text AS text,
            round((( SELECT sum(a.wet_weight) AS sum
                   FROM api_asof a)) / 453.592, 1) AS round,
            round(( SELECT sum(r.wet_lb) AS sum
                   FROM metrc_rpt_harvests r), 1) AS round,
            ( SELECT count(*) AS count
                   FROM ( SELECT a.name
                           FROM api_asof a
                        EXCEPT
                         SELECT r.harvest_name
                           FROM metrc_rpt_harvests r) x) AS count,
            ( SELECT count(*) AS count
                   FROM ( SELECT r.harvest_name
                           FROM metrc_rpt_harvests r
                        EXCEPT
                         SELECT h.name
                           FROM metrc_harvests h) y) AS count,
            NULL::numeric AS "numeric",
            ( SELECT count(*) AS count
                   FROM metrc_harvests h
                     CROSS JOIN asof
                  WHERE h.harvest_start > asof.d) AS count
        ), harvest_pkgs AS (
         SELECT 'Harvest package count'::text AS text,
            'packages'::text AS text,
            'metrc_harvests.package_count (API, live)'::text AS text,
            'metrc_rpt_harvests.package_count (report, point in time)'::text AS text,
            ( SELECT sum(a.package_count) AS sum
                   FROM api_asof a
                     JOIN metrc_rpt_harvests r ON r.harvest_name = a.name) AS sum,
            ( SELECT round(sum(r.package_count)) AS round
                   FROM api_asof a
                     JOIN metrc_rpt_harvests r ON r.harvest_name = a.name) AS round,
            0::bigint AS int8,
            0::bigint AS int8,
            NULL::numeric AS "numeric",
            ( SELECT count(*) AS count
                   FROM metrc_harvests h
                     JOIN metrc_rpt_harvests r ON r.harvest_name = h.name
                  WHERE COALESCE(h.package_count, 0)::numeric <> COALESCE(r.package_count, 0::numeric) AND h.source_state <> 'active'::text) AS count
        ), harvest_rows AS (
         SELECT 'Harvests held'::text AS text,
            'harvests'::text AS text,
            'metrc_harvests (API, as at the export date)'::text AS text,
            'metrc_rpt_harvests (report)'::text AS text,
            ( SELECT count(*) AS count
                   FROM api_asof) AS count,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_harvests) AS count,
            ( SELECT count(*) AS count
                   FROM ( SELECT a.name
                           FROM api_asof a
                        EXCEPT
                         SELECT r.harvest_name
                           FROM metrc_rpt_harvests r) x) AS count,
            ( SELECT count(*) AS count
                   FROM ( SELECT r.harvest_name
                           FROM metrc_rpt_harvests r
                        EXCEPT
                         SELECT h.name
                           FROM metrc_harvests h) y) AS count,
            NULL::numeric AS "numeric",
            ( SELECT count(*) AS count
                   FROM metrc_harvests h
                     CROSS JOIN asof
                  WHERE h.harvest_start > asof.d) AS count
        ), all_facts AS (
         SELECT revenue.fact,
            revenue.unit,
            revenue.source_a,
            revenue.source_b,
            revenue.overlap_a,
            revenue.overlap_b,
            revenue.only_in_a,
            revenue.only_in_b,
            revenue.value_not_covered,
            revenue.after_export
           FROM revenue
        UNION ALL
         SELECT hw.f,
            hw.u,
            hw.sa,
            hw.sb,
            hw.oa,
            hw.ob,
            hw.oia,
            hw.oib,
            hw.vnc,
            hw.ae
           FROM harvest_wet hw(f, u, sa, sb, oa, ob, oia, oib, vnc, ae)
        UNION ALL
         SELECT hp.f,
            hp.u,
            hp.sa,
            hp.sb,
            hp.oa,
            hp.ob,
            hp.oia,
            hp.oib,
            hp.vnc,
            hp.ae
           FROM harvest_pkgs hp(f, u, sa, sb, oa, ob, oia, oib, vnc, ae)
        UNION ALL
         SELECT hr.f,
            hr.u,
            hr.sa,
            hr.sb,
            hr.oa,
            hr.ob,
            hr.oia,
            hr.oib,
            hr.vnc,
            hr.ae
           FROM harvest_rows hr(f, u, sa, sb, oa, ob, oia, oib, vnc, ae)
        )
 SELECT fact,
    unit,
    source_a,
    source_b,
    overlap_a,
    overlap_b,
    overlap_b - overlap_a AS value_difference,
        CASE
            WHEN overlap_a IS NULL OR overlap_a = 0::numeric THEN NULL::numeric
            ELSE round(100.0 * (overlap_b - overlap_a) / abs(overlap_a), 3)
        END AS value_pct,
    only_in_a,
    only_in_b,
    value_not_covered,
        CASE
            WHEN overlap_a IS NULL OR overlap_b IS NULL THEN 'CANNOT COMPARE'::text
            WHEN overlap_a = overlap_b AND COALESCE(only_in_a, 0::bigint) = 0 AND COALESCE(only_in_b, 0::bigint) = 0 THEN 'RECONCILED — identical on the same population'::text ||
            CASE
                WHEN after_export > 0 THEN (', compared at the export date. '::text || after_export) || ' newer rows exist in the API; that is lag, not a defect.'::text
                ELSE ''::text
            END
            WHEN abs(overlap_b - overlap_a) < 1::numeric THEN 'RECONCILED — agree to within rounding'::text
            WHEN fact = 'Harvest package count'::text AND after_export = 0 THEN (('ATTRIBUTE MOVED SINCE EXPORT — every harvest that differs is still OPEN and '::text || 'package_count rises as it is packaged out. A photograph cannot match a live '::text) || 'count on an unfinished harvest. Expected. It becomes a bug the day a FINISHED '::text) || 'harvest differs.'::text
            WHEN overlap_a = overlap_b THEN 'VALUES AGREE — but the sources cover different populations, see only_in_a / only_in_b'::text
            ELSE 'DISAGREES — survives time-alignment, so this is a real value difference. Investigate.'::text
        END AS verdict
   FROM all_facts
  ORDER BY fact;
create or replace view public.v_customer_history as
 SELECT customer,
    customer_license,
    manifests,
    packages_bought,
    first_order,
    last_order,
    days_since_last_order,
    unconfirmed_manifests,
    license,
    first_order AS first_order_date
   FROM ( SELECT COALESCE(metrc_transfers.recipient, '(not recorded)'::text) AS customer,
            metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text AS customer_license,
            count(*)::numeric AS manifests,
            sum(COALESCE((metrc_transfers.raw ->> 'PackageCount'::text)::numeric, 0::numeric)) AS packages_bought,
            min(metrc_transfers.created_on) AS first_order,
            max(metrc_transfers.created_on) AS last_order,
            (CURRENT_DATE - max(metrc_transfers.created_on))::numeric AS days_since_last_order,
            count(*) FILTER (WHERE (metrc_transfers.raw ->> 'ReceivedDateTime'::text) IS NULL)::numeric AS unconfirmed_manifests,
            metrc_transfers.license
           FROM metrc_transfers
          WHERE metrc_transfers.direction = 'outgoing'::text
          GROUP BY (COALESCE(metrc_transfers.recipient, '(not recorded)'::text)), (metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text), metrc_transfers.license
          ORDER BY (sum(COALESCE((metrc_transfers.raw ->> 'PackageCount'::text)::numeric, 0::numeric))) DESC) q;
create or replace view public.v_customer_manifests as
 SELECT t.created_on AS shipped_on,
    t.manifest_number,
    t.recipient AS customer,
    COALESCE(t.raw ->> 'RecipientFacilityLicenseNumber'::text, (t.raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text) AS customer_license,
    COALESCE((t.raw ->> 'PackageCount'::text)::numeric, ((t.raw -> '_delivery'::text) ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages,
    COALESCE((t.raw ->> 'ReceivedPackageCount'::text)::numeric, ((t.raw -> '_delivery'::text) ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric) AS packages_received,
    COALESCE(t.raw ->> 'ReceivedDateTime'::text, (t.raw -> '_delivery'::text) ->> 'ReceivedDateTime'::text)::date AS received_on,
        CASE
            WHEN COALESCE(t.raw ->> 'ReceivedDateTime'::text, (t.raw -> '_delivery'::text) ->> 'ReceivedDateTime'::text) IS NOT NULL THEN 'Delivered and confirmed'::text
            WHEN t.created_on < (CURRENT_DATE - 3) THEN 'NOT CONFIRMED RECEIVED'::text
            ELSE 'In transit'::text
        END AS delivery_status,
    COALESCE(t.raw ->> 'TransporterFacilityName'::text, (t.raw -> '_delivery'::text) ->> 'TransporterFacilityName'::text) AS transporter,
    COALESCE(t.raw ->> 'DriverName'::text, (t.raw -> '_delivery'::text) ->> 'DriverName'::text) AS driver,
    COALESCE(t.raw ->> 'VehicleLicensePlateNumber'::text, (t.raw -> '_delivery'::text) ->> 'VehicleLicensePlateNumber'::text) AS vehicle_plate,
    COALESCE(doc.stored_path, doc.any_url,
        CASE
            WHEN COALESCE(t.raw ->> 'Id'::text, (t.raw -> '_delivery'::text) ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || COALESCE(t.raw ->> 'Id'::text, (t.raw -> '_delivery'::text) ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END) AS manifest_download,
    COALESCE(pk.tags_on_manifest, 0::bigint) AS packages_matched,
    pk.products AS products_on_manifest,
    coa.links AS certificate_of_analysis_links,
    COALESCE(coa.tags_with_result, 0::bigint) AS packages_with_certificate,
    t.license,
    COALESCE(doc.copies_held, 0::bigint) AS manifest_copy_held,
        CASE
            WHEN doc.stored_path IS NOT NULL THEN 'Held here - download, print or send'::text
            WHEN doc.any_url IS NOT NULL THEN 'Metrc link only - expires, no copy held'::text
            ELSE 'Not downloaded yet - pulls overnight'::text
        END AS document_status
   FROM metrc_transfers t
     LEFT JOIN LATERAL ( SELECT count(DISTINCT r.package_tag) AS tags_on_manifest,
            string_agg(DISTINCT NULLIF(r.item, ''::text), ' · '::text) AS products
           FROM metrc_rpt_package_transfers r
          WHERE r.manifest_number = t.manifest_number) pk ON true
     LEFT JOIN LATERAL ( SELECT string_agg(DISTINCT d.download_url, ' | '::text) AS links,
            count(DISTINCT d.package_tag) AS tags_with_result
           FROM metrc_documents d
          WHERE d.doc_type = 'coa'::text AND d.download_url IS NOT NULL AND (d.package_tag IN ( SELECT r2.package_tag
                   FROM metrc_rpt_package_transfers r2
                  WHERE r2.manifest_number = t.manifest_number))) coa ON true
     LEFT JOIN LATERAL ( SELECT max(d.storage_path) AS stored_path,
            max(d.download_url) AS any_url,
            count(*) FILTER (WHERE d.storage_path IS NOT NULL) AS copies_held
           FROM metrc_documents d
          WHERE d.doc_type = 'manifest'::text AND d.manifest_number = t.manifest_number) doc ON true
  WHERE t.direction = 'outgoing'::text
  ORDER BY t.created_on DESC NULLS LAST;
create or replace view public.v_dashboard_tasks as
 SELECT t.id,
    t.title,
    t.description,
    t.status,
    t.priority,
    e.full_name AS assigned_to,
    d.name AS assignee_department,
    t.department AS raised_from,
    t.source_kpi,
    t.source_value,
    t.source_unit,
    t.source_view AS drill,
    t.due_on,
    t.due_on - CURRENT_DATE AS days_until_due,
        CASE
            WHEN t.due_on < CURRENT_DATE AND t.status <> 'done'::text THEN ('OVERDUE by '::text || (CURRENT_DATE - t.due_on)) || ' days'::text
            WHEN t.status = 'done'::text THEN 'Done '::text || COALESCE(t.completed_at::date::text, ''::text)
            WHEN t.due_on IS NULL THEN 'No due date set'::text
            ELSE ('Due in '::text || (t.due_on - CURRENT_DATE)) || ' days'::text
        END AS "position",
    t.created_at::date AS raised_on,
    CURRENT_DATE - t.created_at::date AS days_open,
    t.source_snapshot
   FROM tasks t
     LEFT JOIN employees e ON e.id = t.assignee_employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE t.source_kpi IS NOT NULL
  ORDER BY (
        CASE t.status
            WHEN 'open'::text THEN 0
            ELSE 1
        END), t.due_on;
create or replace view public.v_dashboard_templates as
 SELECT template_key,
    name,
    purpose,
    categories,
    ( SELECT count(*) AS count
           FROM widget_catalog c
          WHERE c.enabled AND (c.category = ANY (t.categories))) AS widgets_it_would_add,
    ( SELECT string_agg(DISTINCT c.category, ', '::text ORDER BY c.category) AS string_agg
           FROM widget_catalog c
          WHERE c.enabled AND (c.category = ANY (t.categories))) AS covers
   FROM dashboard_template t
  WHERE active
  ORDER BY sort;
create or replace view public.v_dashboard_trend as
 SELECT department,
    kpi,
    array_agg(value ORDER BY taken_on) AS series,
    array_agg(taken_on ORDER BY taken_on) AS days,
    count(*) AS points,
    (array_agg(value ORDER BY taken_on DESC))[1] AS latest,
    (array_agg(value ORDER BY taken_on DESC))[2] AS previous
   FROM dashboard_snapshots
  WHERE taken_on >= (CURRENT_DATE - 30)
  GROUP BY department, kpi;
create or replace view public.v_data_inventory as
 SELECT 'metrc_plants'::text AS table_name,
    'Plants - live, by room and phase'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_plants) AS rows_held,
    ( SELECT max(metrc_plants.synced_at)::date AS max
           FROM metrc_plants) AS freshest
UNION ALL
 SELECT 'metrc_packages'::text AS table_name,
    'Packages with tag, quantity, room, lab state'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_packages) AS rows_held,
    ( SELECT max(metrc_packages.synced_at)::date AS max
           FROM metrc_packages) AS freshest
UNION ALL
 SELECT 'metrc_rpt_lab_results'::text AS table_name,
    'Lab results per analyte, with lab licence'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_lab_results) AS rows_held,
    ( SELECT max(metrc_rpt_lab_results.imported_at)::date AS max
           FROM metrc_rpt_lab_results) AS freshest
UNION ALL
 SELECT 'metrc_rpt_package_transfers'::text AS table_name,
    'Every package on every manifest'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_package_transfers) AS rows_held,
    ( SELECT max(metrc_rpt_package_transfers.imported_at)::date AS max
           FROM metrc_rpt_package_transfers) AS freshest
UNION ALL
 SELECT 'metrc_rpt_transfer_manifests'::text AS table_name,
    'Manifest headers, both directions'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_transfer_manifests) AS rows_held,
    ( SELECT max(metrc_rpt_transfer_manifests.imported_at)::date AS max
           FROM metrc_rpt_transfer_manifests) AS freshest
UNION ALL
 SELECT 'metrc_rpt_point_in_time'::text AS table_name,
    'Dated location snapshots - the location history'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_point_in_time) AS rows_held,
    ( SELECT max(metrc_rpt_point_in_time.imported_at)::date AS max
           FROM metrc_rpt_point_in_time) AS freshest
UNION ALL
 SELECT 'metrc_rpt_wholesale'::text AS table_name,
    'Wholesale transfers'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_wholesale) AS rows_held,
    ( SELECT max(metrc_rpt_wholesale.imported_at)::date AS max
           FROM metrc_rpt_wholesale) AS freshest
UNION ALL
 SELECT 'metrc_rpt_adjustments'::text AS table_name,
    'Package adjustments'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_adjustments) AS rows_held,
    ( SELECT max(metrc_rpt_adjustments.imported_at)::date AS max
           FROM metrc_rpt_adjustments) AS freshest
UNION ALL
 SELECT 'metrc_rpt_plant_waste'::text AS table_name,
    'Plant waste'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_plant_waste) AS rows_held,
    ( SELECT max(metrc_rpt_plant_waste.imported_at)::date AS max
           FROM metrc_rpt_plant_waste) AS freshest
UNION ALL
 SELECT 'metrc_rpt_plants_destroyed'::text AS table_name,
    'Plants destroyed'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_plants_destroyed) AS rows_held,
    ( SELECT max(metrc_rpt_plants_destroyed.imported_at)::date AS max
           FROM metrc_rpt_plants_destroyed) AS freshest
UNION ALL
 SELECT 'metrc_rpt_harvests'::text AS table_name,
    'Harvest records'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_harvests) AS rows_held,
    ( SELECT max(metrc_rpt_harvests.imported_at)::date AS max
           FROM metrc_rpt_harvests) AS freshest
UNION ALL
 SELECT 'metrc_rpt_harvest_moisture'::text AS table_name,
    'Moisture loss - the ONLY source; the API has no moisture field'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_rpt_harvest_moisture) AS rows_held,
    ( SELECT max(metrc_rpt_harvest_moisture.imported_at)::date AS max
           FROM metrc_rpt_harvest_moisture) AS freshest
UNION ALL
 SELECT 'metrc_items'::text AS table_name,
    'Metrc item catalogue'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_items) AS rows_held,
    NULL::date AS freshest
UNION ALL
 SELECT 'metrc_strains'::text AS table_name,
    'Registered strains'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_strains) AS rows_held,
    NULL::date AS freshest
UNION ALL
 SELECT 'metrc_locations'::text AS table_name,
    'Rooms and locations'::text AS holds,
    ( SELECT count(*) AS count
           FROM metrc_locations) AS rows_held,
