           FROM third_party_material) AS freshest
UNION ALL
 SELECT 'tag_event'::text AS table_name,
    'SEED-TO-SALE LEDGER - dwell, custody, testing, location'::text AS holds,
    ( SELECT count(*) AS count
           FROM tag_event) AS rows_held,
    ( SELECT max(tag_event.created_at)::date AS max
           FROM tag_event) AS freshest;
create or replace view public.v_db_change_status as
 SELECT change_ref,
    max(domain) AS domain,
    max(proposed_by) AS proposed_by,
    count(*) FILTER (WHERE verdict = 'approved'::text AND reviewer IS DISTINCT FROM proposed_by) AS approvals,
    count(*) FILTER (WHERE verdict = 'rejected'::text) AS rejections,
    count(*) FILTER (WHERE verdict = 'needs_work'::text) AS needs_work,
        CASE
            WHEN count(*) FILTER (WHERE verdict = 'rejected'::text) > 0 THEN 'REJECTED'::text
            WHEN count(*) FILTER (WHERE verdict = 'approved'::text AND reviewer IS DISTINCT FROM proposed_by) >= 3 THEN 'APPROVED'::text
            ELSE ('AWAITING REVIEW - '::text || ((3 - count(*) FILTER (WHERE verdict = 'approved'::text AND reviewer IS DISTINCT FROM proposed_by))::text)) || ' of 3 still needed'::text
        END AS status
   FROM db_change_review c
  GROUP BY change_ref;
create or replace view public.v_deferral_pressure as
 SELECT alert_key,
    alert_source,
    count(*) AS days_deferred,
    min(deferred_on) AS first_deferred,
    max(deferred_on) AS last_deferred,
    CURRENT_DATE - max(deferred_on) AS days_since_last_reason,
    max(age_days_at_deferral) AS age_days,
    count(DISTINCT deferred_by) AS people_involved,
    count(DISTINCT reason_note) AS distinct_reasons_given,
    (array_agg(reason_code ORDER BY deferred_on DESC))[1] AS latest_reason_code,
    (array_agg(reason_note ORDER BY deferred_on DESC))[1] AS latest_reason,
        CASE
            WHEN count(*) >= 14 THEN 'CHRONIC — deferred a fortnight; this is a decision not to fix, and it should be taken openly'::text
            WHEN count(*) >= 7 THEN 'REPEATED — a week of deferrals'::text
            WHEN count(DISTINCT reason_note) = 1 AND count(*) >= 3 THEN ('SAME REASON REPEATED — if the blocker has not changed in '::text || count(*)) || ' days, escalate the blocker'::text
            ELSE 'ACTIVE'::text
        END AS verdict
   FROM alert_deferral d
  GROUP BY alert_key, alert_source
  ORDER BY (count(*)) DESC;
create or replace view public.v_delivery_board as
 SELECT d.id,
    d.page,
    d.built_by,
    d.summary,
    d.status,
    d.submitted_at,
    count(v.id) AS lanes_reported,
    count(*) FILTER (WHERE v.verdict = 'agree'::text) AS lanes_agreeing,
    string_agg(((((v.lane || ': '::text) || v.verdict) || ' ('::text) || v.verifier) || ')'::text, ' · '::text ORDER BY v.lane) AS lane_detail,
    string_agg(v.lane, ', '::text) FILTER (WHERE v.verdict <> 'agree'::text) AS lanes_blocking,
    d.guard,
    d.guard_at,
        CASE
            WHEN d.status = 'approved'::text THEN 'APPROVED'::text
            WHEN count(v.id) < 3 THEN ('WAITING — '::text || (3 - count(v.id))) || ' lane(s) not yet verified'::text
            WHEN count(*) FILTER (WHERE v.verdict <> 'agree'::text) > 0 THEN 'BLOCKED — verifiers disagree'::text
            WHEN d.guard IS NULL THEN 'READY FOR GUARD'::text
            ELSE 'READY'::text
        END AS gate_state
   FROM delivery d
     LEFT JOIN delivery_verification v ON v.delivery_id = d.id
  GROUP BY d.id;
create or replace view public.v_department_coverage_week as
 WITH span AS (
         SELECT LEAST(COALESCE(( SELECT min(zone_staffing_requirements.effective_from) AS min
                   FROM zone_staffing_requirements), CURRENT_DATE), COALESCE(( SELECT min(employee_schedules.work_date) AS min
                   FROM employee_schedules), CURRENT_DATE), COALESCE(( SELECT min(time_entries.work_date) AS min
                   FROM time_entries), CURRENT_DATE)) AS from_date,
            GREATEST(COALESCE(( SELECT max(COALESCE(zone_staffing_requirements.effective_to, CURRENT_DATE + 28)) AS max
                   FROM zone_staffing_requirements), CURRENT_DATE), COALESCE(( SELECT max(employee_schedules.work_date) AS max
                   FROM employee_schedules), CURRENT_DATE), COALESCE(( SELECT max(time_entries.work_date) AS max
                   FROM time_entries), CURRENT_DATE)) AS to_date
        ), days AS (
         SELECT d_1.d::date AS work_date
           FROM span,
            LATERAL generate_series(span.from_date::timestamp with time zone, span.to_date::timestamp with time zone, '1 day'::interval) d_1(d)
          WHERE (EXISTS ( SELECT 1
                   FROM zone_staffing_requirements))
        ), required AS (
         SELECT dy.work_date,
            COALESCE(r.department_id, z.department_id) AS department_id,
            sum(r.headcount_required) AS heads_required,
            sum(r.headcount_required::numeric * r.hours_per_head) AS hours_required,
            string_agg(DISTINCT r.driver, ', '::text) AS drivers
           FROM days dy
             JOIN zone_staffing_requirements r ON r.effective_from <= dy.work_date AND (r.effective_to IS NULL OR r.effective_to >= dy.work_date) AND (r.weekday IS NULL OR r.weekday = EXTRACT(dow FROM dy.work_date)::integer)
             LEFT JOIN zones z ON z.id = r.zone_id
          WHERE COALESCE(r.department_id, z.department_id) IS NOT NULL
          GROUP BY dy.work_date, (COALESCE(r.department_id, z.department_id))
        ), scheduled AS (
         SELECT s.work_date,
            s.department_id,
            count(DISTINCT s.employee_id) AS heads_scheduled,
            sum(EXTRACT(epoch FROM s.planned_end - s.planned_start) / 3600.0) AS hours_scheduled
           FROM employee_schedules s
          WHERE s.department_id IS NOT NULL AND COALESCE(s.status, 'planned'::text) <> 'cancelled'::text
          GROUP BY s.work_date, s.department_id
        ), actual AS (
         SELECT t.work_date,
            e.primary_department_id AS department_id,
            count(DISTINCT t.employee_id) AS heads_actual,
            sum(COALESCE(t.productive_hours, 0::numeric)) AS hours_actual
           FROM time_entries t
             JOIN employees e ON e.id = t.employee_id
          WHERE e.primary_department_id IS NOT NULL
          GROUP BY t.work_date, e.primary_department_id
        )
 SELECT date_trunc('week'::text, COALESCE(rq.work_date, sc.work_date, ac.work_date)::timestamp with time zone)::date AS week_start,
    d.id AS department_id,
    d.name AS department,
    count(*) FILTER (WHERE rq.heads_required IS NOT NULL) AS days_with_a_requirement,
    sum(COALESCE(rq.heads_required, 0::bigint)) AS heads_required,
    sum(COALESCE(sc.heads_scheduled, 0::bigint)) AS heads_scheduled,
    sum(COALESCE(ac.heads_actual, 0::bigint)) AS heads_actual,
    round(sum(COALESCE(rq.hours_required, 0::numeric)), 1) AS hours_required,
    round(sum(COALESCE(sc.hours_scheduled, 0::numeric)), 1) AS hours_scheduled,
    round(sum(COALESCE(ac.hours_actual, 0::numeric)), 1) AS hours_actual,
    sum(COALESCE(rq.heads_required, 0::bigint) - COALESCE(sc.heads_scheduled, 0::bigint)) AS head_days_short_on_the_rota,
    round(sum(COALESCE(rq.hours_required, 0::numeric) - COALESCE(ac.hours_actual, 0::numeric)), 1) AS hours_short_actually_worked,
    string_agg(DISTINCT rq.drivers, ', '::text) AS set_by,
        CASE
            WHEN sum(COALESCE(rq.heads_required, 0::bigint)) = 0::numeric THEN 'NO REQUIREMENT SET'::text
            WHEN sum(COALESCE(sc.heads_scheduled, 0::bigint)) < sum(COALESCE(rq.heads_required, 0::bigint)) THEN 'SHORT ON THE ROTA'::text
            WHEN sum(COALESCE(ac.heads_actual, 0::bigint)) < sum(COALESCE(rq.heads_required, 0::bigint)) THEN 'ROTA FULL BUT DID NOT TURN UP'::text
            ELSE 'COVERED'::text
        END AS verdict,
        CASE
            WHEN sum(COALESCE(rq.heads_required, 0::bigint)) = 0::numeric THEN 'No coverage requirement exists for this department in this week, so short-staffing '::text || 'CANNOT be detected. This is not the same as being fully staffed.'::text
            ELSE NULL::text
        END AS why_it_cannot_be_judged
   FROM departments d
     LEFT JOIN required rq ON rq.department_id = d.id
     LEFT JOIN scheduled sc ON sc.department_id = d.id AND sc.work_date = rq.work_date
     LEFT JOIN actual ac ON ac.department_id = d.id AND ac.work_date = COALESCE(rq.work_date, sc.work_date)
  WHERE COALESCE(rq.work_date, sc.work_date, ac.work_date) IS NOT NULL
  GROUP BY (date_trunc('week'::text, COALESCE(rq.work_date, sc.work_date, ac.work_date)::timestamp with time zone)::date), d.id, d.name
  ORDER BY (date_trunc('week'::text, COALESCE(rq.work_date, sc.work_date, ac.work_date)::timestamp with time zone)::date) DESC, d.name;
create or replace view public.v_department_labour as
 WITH punch AS (
         SELECT t.employee_id,
            t.work_date,
            s.department_id,
            btrim(s.zone) AS zone,
            s.shift_template_id,
            st.name AS shift,
            EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0 AS hours,
            t.late_minutes,
            t.early_minutes,
            r.rate,
            COALESCE(r.ot_multiplier, 1.5) AS otm,
            COALESCE(r.burden_pct, 0::numeric) AS burden
           FROM time_entries t
             LEFT JOIN employee_schedules s ON s.employee_id = t.employee_id AND s.work_date = t.work_date
             LEFT JOIN shift_templates st ON st.id = s.shift_template_id
             LEFT JOIN LATERAL ( SELECT r2.id,
                    r2.employee_id,
                    r2.basis,
                    r2.rate,
                    r2.ot_multiplier,
                    r2.burden_pct,
                    r2.effective_from,
                    r2.effective_to,
                    r2.approved_by,
                    r2.note,
                    r2.effective_from_date
                   FROM employee_rates r2
                  WHERE r2.employee_id = t.employee_id AND r2.effective_from <= t.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= t.work_date)
                  ORDER BY r2.effective_from DESC
                 LIMIT 1) r ON true
          WHERE t.clock_in IS NOT NULL AND t.clock_out IS NOT NULL
        )
 SELECT d.id AS department_id,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    p.work_date,
    date_trunc('week'::text, p.work_date::timestamp with time zone)::date AS week_start,
    date_trunc('month'::text, p.work_date::timestamp with time zone)::date AS month_start,
    COALESCE(p.shift, 'Unscheduled'::text) AS shift,
    p.zone,
    count(DISTINCT p.employee_id) AS heads,
    round(sum(p.hours), 2) AS hours,
    round(avg(p.hours), 2) AS avg_hours_per_head,
    round(sum(LEAST(p.hours, 8::numeric)), 2) AS straight_hours,
    round(sum(GREATEST(p.hours - 8::numeric, 0::numeric)), 2) AS ot_hours,
    round(sum(LEAST(p.hours, 8::numeric) * p.rate * (1::numeric + p.burden)), 2) AS straight_cost_loaded,
    round(sum(GREATEST(p.hours - 8::numeric, 0::numeric) * p.rate * p.otm * (1::numeric + p.burden)), 2) AS ot_cost_loaded,
    round(sum((LEAST(p.hours, 8::numeric) + GREATEST(p.hours - 8::numeric, 0::numeric) * p.otm) * p.rate * (1::numeric + p.burden)), 2) AS total_cost_loaded,
    round(sum((LEAST(p.hours, 8::numeric) + GREATEST(p.hours - 8::numeric, 0::numeric) * p.otm) * p.rate * (1::numeric + p.burden)) / NULLIF(sum(p.hours), 0::numeric), 2) AS cost_per_hour,
    count(*) FILTER (WHERE COALESCE(p.late_minutes, 0) > 0) AS late_punches,
    round(avg(NULLIF(p.late_minutes, 0)), 1) AS avg_late_minutes,
    count(*) FILTER (WHERE COALESCE(p.early_minutes, 0) > (( SELECT attendance_policy.early_punch_minutes
           FROM attendance_policy
         LIMIT 1))) AS early_punches_over_window
   FROM punch p
     LEFT JOIN departments d ON d.id = p.department_id
  GROUP BY d.id, d.name, p.work_date, p.shift, p.zone;
create or replace view public.v_department_task_kpis as
 SELECT COALESCE(tasks.department, 'Command'::text) AS dept,
    90 AS ord,
    'Open tasks from this dashboard'::text AS kpi,
    count(*) FILTER (WHERE tasks.status <> 'done'::text)::numeric AS value,
    'tasks'::text AS unit,
        CASE
            WHEN count(*) FILTER (WHERE tasks.status <> 'done'::text) > 0 THEN 'warn'::text
            ELSE 'good'::text
        END AS tone,
    'dashboard_tasks'::text AS drill,
    'raised from a tile here'::text AS sub
   FROM tasks
  WHERE tasks.source_kpi IS NOT NULL
  GROUP BY (COALESCE(tasks.department, 'Command'::text))
UNION ALL
 SELECT COALESCE(tasks.department, 'Command'::text) AS dept,
    91 AS ord,
    'Tasks overdue'::text AS kpi,
    count(*) FILTER (WHERE tasks.due_on < CURRENT_DATE AND tasks.status <> 'done'::text)::numeric AS value,
    'tasks'::text AS unit,
        CASE
            WHEN count(*) FILTER (WHERE tasks.due_on < CURRENT_DATE AND tasks.status <> 'done'::text) > 0 THEN 'bad'::text
            ELSE 'good'::text
        END AS tone,
    'dashboard_tasks'::text AS drill,
    'past their due date'::text AS sub
   FROM tasks
  WHERE tasks.source_kpi IS NOT NULL
  GROUP BY (COALESCE(tasks.department, 'Command'::text));
create or replace view public.v_destruction_ledger as
 SELECT 'Harvest waste'::text AS channel,
    h.license AS licence,
    (h.raw ->> 'HarvestStartDate'::text)::date AS occurred_on,
    h.raw ->> 'Name'::text AS reference,
    'Waste recorded when the plants were cut'::text AS reason,
    f_to_pounds((h.raw ->> 'TotalWasteWeight'::text)::numeric, 'Grams'::text) AS lb
   FROM metrc_harvests h
  WHERE COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) > 0::numeric
UNION ALL
 SELECT 'Package adjustment'::text AS channel,
    a.licence,
    a.adjusted_on AS occurred_on,
    a.package_tag AS reference,
    COALESCE(NULLIF(a.reason, ''::text), '(no reason given)'::text) AS reason,
    abs(f_to_pounds(a.quantity, a.uom)) AS lb
   FROM metrc_rpt_adjustments a
  WHERE a.quantity < 0::numeric
UNION ALL
 SELECT 'Plant waste'::text AS channel,
    w.licence,
    w.waste_date AS occurred_on,
    COALESCE(w.plant_batch, w.waste_number) AS reference,
    COALESCE(NULLIF(w.reason, ''::text), '(no reason given)'::text) AS reason,
    f_to_pounds(w.waste_qty, w.uom) AS lb
   FROM metrc_rpt_plant_waste w;
create or replace view public.v_disagreement_triage as
 SELECT r.check_key,
    c.severity,
    c.owner,
    c.title,
    r.value_a,
    r.value_b,
    round(r.pct_apart, 1) AS pct_apart,
        CASE
            WHEN c.check_key ~~ 'metric-no-new%'::text OR c.check_key ~~ 'glossary-no-new%'::text OR c.check_key ~~ '%ceiling%'::text THEN 'self_inflicted_ratchet'::text
            WHEN c.check_key ~~ 'examination-%'::text OR c.check_key ~~ 'label-%'::text OR c.check_key = 'manifest-pdf-coverage'::text THEN 'coverage_gap_by_design'::text
            WHEN c.check_key = 'anon-cannot-read'::text OR c.check_key ~~ 'anon-%'::text THEN 'security_posture'::text
            WHEN c.check_key = 'plants-metrc-vs-plan'::text THEN 'business_variance_not_data'::text
            WHEN COALESCE(c.measures_a_process, false) THEN 'process_in_flight'::text
            ELSE 'real_data_discrepancy'::text
        END AS suggested_class,
    ( SELECT d.first_question
           FROM disagreement_class d
          WHERE d.class_key =
                CASE
                    WHEN c.check_key ~~ 'metric-no-new%'::text OR c.check_key ~~ 'glossary-no-new%'::text OR c.check_key ~~ '%ceiling%'::text THEN 'self_inflicted_ratchet'::text
                    WHEN c.check_key ~~ 'examination-%'::text OR c.check_key ~~ 'label-%'::text OR c.check_key = 'manifest-pdf-coverage'::text THEN 'coverage_gap_by_design'::text
                    WHEN c.check_key = 'anon-cannot-read'::text OR c.check_key ~~ 'anon-%'::text THEN 'security_posture'::text
                    WHEN c.check_key = 'plants-metrc-vs-plan'::text THEN 'business_variance_not_data'::text
                    WHEN COALESCE(c.measures_a_process, false) THEN 'process_in_flight'::text
                    ELSE 'real_data_discrepancy'::text
                END) AS ask_this_first,
    ( SELECT d.the_wrong_fix
           FROM disagreement_class d
          WHERE d.class_key =
                CASE
                    WHEN c.check_key ~~ 'metric-no-new%'::text OR c.check_key ~~ 'glossary-no-new%'::text OR c.check_key ~~ '%ceiling%'::text THEN 'self_inflicted_ratchet'::text
                    WHEN c.check_key ~~ 'examination-%'::text OR c.check_key ~~ 'label-%'::text OR c.check_key = 'manifest-pdf-coverage'::text THEN 'coverage_gap_by_design'::text
                    WHEN c.check_key = 'anon-cannot-read'::text OR c.check_key ~~ 'anon-%'::text THEN 'security_posture'::text
                    WHEN c.check_key = 'plants-metrc-vs-plan'::text THEN 'business_variance_not_data'::text
                    WHEN COALESCE(c.measures_a_process, false) THEN 'process_in_flight'::text
                    ELSE 'real_data_discrepancy'::text
                END) AS do_not_do_this
   FROM ( SELECT DISTINCT ON (verification_runs.check_key) verification_runs.id,
            verification_runs.ran_at,
            verification_runs.check_key,
            verification_runs.value_a,
            verification_runs.value_b,
            verification_runs.difference,
            verification_runs.pct_apart,
            verification_runs.verdict,
            verification_runs.note
           FROM verification_runs
          ORDER BY verification_runs.check_key, verification_runs.ran_at DESC) r
     JOIN verification_checks c ON c.check_key = r.check_key
  WHERE upper(r.verdict) <> 'AGREE'::text
  ORDER BY (
        CASE c.severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), (abs(COALESCE(r.pct_apart, 0::numeric))) DESC;
create or replace view public.v_discrepancy_clock as
 WITH routed AS (
         SELECT r.discrepancy_key,
            r.class,
            r.subject,
            r.source_a,
            r.source_a_says,
            r.source_b,
            r.source_b_says,
            r.resolved_by_doc,
            r.document_link,
            r.first_seen,
            r.last_seen,
            r.resolved_at,
            r.resolved_by,
            r.resolution_note,
            r.assigned_to,
            r.assigned_at,
                CASE r.class
                    WHEN 'strain'::text THEN 'Compliance'::text
                    WHEN 'ownership'::text THEN 'Inventory'::text
                    WHEN 'missing_contents'::text THEN 'Compliance'::text
                    WHEN 'verification'::text THEN 'Unassigned'::text
                    ELSE NULL::text
                END AS dept
           FROM discrepancy_register r
        )
 SELECT d.discrepancy_key,
    d.class,
        CASE d.class
            WHEN 'strain'::text THEN 'Strain — the item name and the strain field disagree'::text
            WHEN 'ownership'::text THEN 'Ownership — the platform and the package lineage disagree'::text
            WHEN 'missing_contents'::text THEN 'Contents — a shipment moved with no record of what was on it'::text
            WHEN 'verification'::text THEN 'Verification — two derivations of the same fact disagree'::text
            ELSE d.class
        END AS what_disagrees,
    d.subject,
    d.source_a,
    d.source_a_says,
    d.source_b,
    d.source_b_says,
    d.resolved_by_doc,
    d.document_link,
        CASE
            WHEN d.document_link IS NOT NULL THEN 'The document is on file — open it and the answer is there.'::text
            WHEN d.class = 'verification'::text THEN 'No document settles this. Both numbers come from our own records; the query behind each is on the check.'::text
            ELSE 'The document that settles this has not been fetched from Metrc yet.'::text
        END AS can_it_be_settled_now,
    (d.first_seen AT TIME ZONE 'America/New_York'::text) AS tracking_started,
    CURRENT_DATE - d.first_seen::date AS days_tracked,
    d.assigned_to,
    (d.resolved_at AT TIME ZONE 'America/New_York'::text) AS resolved_at,
        CASE
            WHEN d.resolved_at IS NOT NULL THEN 'RESOLVED'::text
            WHEN (CURRENT_DATE - d.first_seen::date) > 7 THEN 'BREACH — past the one-week rule'::text
            WHEN (CURRENT_DATE - d.first_seen::date) >= 5 THEN ('DUE — '::text || (7 - (CURRENT_DATE - d.first_seen::date))) || ' days left'::text
            ELSE 'within the week'::text
        END AS clock,
        CASE
            WHEN d.resolved_at IS NOT NULL THEN 5
            WHEN (CURRENT_DATE - d.first_seen::date) > 7 THEN 1
            WHEN d.class = 'verification'::text THEN 2
            WHEN (CURRENT_DATE - d.first_seen::date) >= 5 THEN 3
            ELSE 4
        END AS rank,
        CASE
            WHEN o.owner_name IS NULL AND d.assigned_to IS NULL AND d.resolved_at IS NULL THEN 'NOBODY IS ASSIGNED and no department owner is on file.'::text
            WHEN d.assigned_to IS NULL AND d.resolved_at IS NULL THEN ('Falls to the department owner by default — nobody has taken it personally. Every '::text || 'department in finding_owners currently resolves to the same person, so this is one '::text) || 'person holding all of it, not a routed workload.'::text
            ELSE NULL::text
        END AS ownership_gap,
    d.dept AS department,
    COALESCE(d.assigned_to, o.owner_name) AS accountable,
    o.escalates_to
   FROM routed d
     LEFT JOIN finding_owners o ON o.department = d.dept;
create or replace view public.v_discrepancy_readiness as
 SELECT subject,
    count(*) FILTER (WHERE settled_it) AS sources_that_settled_it,
    ( SELECT count(*) AS count
           FROM discrepancy_source
          WHERE discrepancy_source.mandatory) AS rungs_required,
    count(DISTINCT source_key) AS rungs_checked,
    ( SELECT string_agg(d.source_name, ', '::text ORDER BY d.rung) AS string_agg
           FROM discrepancy_source d
          WHERE d.mandatory AND NOT (d.source_key IN ( SELECT i.source_key
                   FROM discrepancy_investigation i
                  WHERE i.subject = s.subject))) AS not_yet_tried,
    bool_or(settled_it) AS already_answered
   FROM discrepancy_investigation s
  GROUP BY subject;
create or replace view public.v_document_compliance as
 SELECT d.id AS document_id,
    d.title,
    d.kind,
    d.version,
    d.requires_signature,
    e.id AS employee_id,
    e.employee_code,
    e.full_name,
    dep.name AS department,
    a.due_on,
    ack.signed_at,
    ack.read_at,
    ack.signature_name,
    ( SELECT count(*) AS count
           FROM hr_document_sections s
          WHERE s.document_id = d.id) AS sections,
    ( SELECT count(*) AS count
           FROM hr_document_progress p
             JOIN hr_document_sections s2 ON s2.id = p.section_id
          WHERE s2.document_id = d.id AND p.employee_id = e.id) AS sections_read,
        CASE
            WHEN ack.signed_at IS NOT NULL THEN 'signed'::text
            WHEN ack.read_at IS NOT NULL THEN 'read, not signed'::text
            WHEN (EXISTS ( SELECT 1
               FROM hr_document_progress p2
                 JOIN hr_document_sections s3 ON s3.id = p2.section_id
              WHERE s3.document_id = d.id AND p2.employee_id = e.id)) THEN 'in progress'::text
            WHEN a.due_on IS NOT NULL AND a.due_on < CURRENT_DATE THEN 'overdue'::text
            ELSE 'not started'::text
        END AS state
   FROM hr_documents d
     JOIN hr_document_assignments a ON a.document_id = d.id
     JOIN employees e ON a.employee_id = e.id OR a.role_id IS NOT NULL AND (e.primary_role_id = a.role_id OR e.secondary_role_id = a.role_id) OR a.department_id IS NOT NULL AND (e.primary_department_id = a.department_id OR e.secondary_department_id = a.department_id)
     LEFT JOIN departments dep ON dep.id = e.primary_department_id
     LEFT JOIN hr_document_acknowledgements ack ON ack.document_id = d.id AND ack.employee_id = e.id AND ack.document_version = d.version
  WHERE d.retired_at IS NULL AND e.status::text = 'active'::text;
create or replace view public.v_duplicate_audit as
 SELECT table_name,
    key_columns,
    dup_groups,
    extra_rows,
    unique_indexes
   FROM f_duplicate_audit() f_duplicate_audit(table_name, key_columns, dup_groups, extra_rows, unique_indexes);
create or replace view public.v_employee_capacity as
 SELECT e.employee_code,
    e.full_name,
    COALESCE(rc.name, '—'::text) AS "position",
    COALESCE(d.name, '—'::text) AS department,
        CASE
            WHEN s.days IS NULL THEN 'Company default'::text
            ELSE 'Custom'::text
        END AS schedule_source,
    COALESCE(s.days, ( SELECT jsonb_array_length(configurations.value -> 'workweek'::text) AS jsonb_array_length
           FROM configurations
          WHERE configurations.key = 'workspace_work_schedule'::text)) AS days_per_week,
    round(COALESCE(s.weekly_hours, ( SELECT (configurations.value ->> 'weekly_capacity_hours'::text)::numeric AS "numeric"
           FROM configurations
          WHERE configurations.key = 'workspace_work_schedule'::text)), 1) AS weekly_capacity_hours,
    e.weekly_target_hours AS payroll_target_hours,
    e.status
   FROM employees e
     LEFT JOIN ( SELECT employee_work_schedules.employee_id,
            count(*)::integer AS days,
            sum(EXTRACT(epoch FROM employee_work_schedules.end_time - employee_work_schedules.start_time) / 3600.0) AS weekly_hours
           FROM employee_work_schedules
          GROUP BY employee_work_schedules.employee_id) s ON s.employee_id = e.id
     LEFT JOIN roles_catalog rc ON rc.id = e.primary_role_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE e.terminated_on IS NULL
  ORDER BY e.full_name;
create or replace view public.v_enhancements_for_owner as
 SELECT page,
    section,
    kind,
    impact,
    effort,
    observation,
    recommendation,
    why_it_matters,
    raised_by,
    raised_at,
    status,
    owner_note,
        CASE
            WHEN impact = 'high'::text AND effort = 'small'::text THEN 1
            WHEN impact = 'high'::text AND effort = 'medium'::text THEN 2
            WHEN impact = 'medium'::text AND effort = 'small'::text THEN 3
            WHEN impact = 'high'::text THEN 4
            WHEN impact = 'medium'::text THEN 5
            ELSE 6
        END AS work_order
   FROM page_enhancement
  WHERE status = 'proposed'::text
  ORDER BY (
        CASE
            WHEN impact = 'high'::text AND effort = 'small'::text THEN 1
            WHEN impact = 'high'::text AND effort = 'medium'::text THEN 2
            WHEN impact = 'medium'::text AND effort = 'small'::text THEN 3
            WHEN impact = 'high'::text THEN 4
            WHEN impact = 'medium'::text THEN 5
            ELSE 6
        END), page, section;
create or replace view public.v_entity_note_active as
 SELECT id,
    entity_type,
    entity_key,
    note_kind,
    note,
    applies_from,
    applies_to,
    author,
    created_at
   FROM entity_note
  WHERE superseded_at IS NULL;
create or replace view public.v_examination_readiness as
 SELECT e.test_key,
    e.authority,
    e.area,
    e.severity,
    e.the_question,
    e.evidence_required,
    e.where_it_lives,
    e.consequence,
    e.citation,
    e.citation_status,
    e.control_key,
        CASE
            WHEN e.where_it_lives IS NULL THEN 'CANNOT PRODUCE — nothing in the platform holds this'::text
            WHEN e.control_key IS NULL THEN 'PRODUCIBLE BUT UNGUARDED — no automated check keeps it true'::text
            WHEN c.check_key IS NULL THEN 'CONTROL NAMED BUT MISSING — control_key does not resolve'::text
            WHEN NOT c.enabled THEN 'CONTROL DISABLED'::text
            WHEN upper(COALESCE(r.verdict, ''::text)) = 'AGREE'::text THEN 'GUARDED AND PASSING'::text
            WHEN r.verdict IS NULL THEN 'CONTROL NEVER RUN'::text
            ELSE 'CONTROL FAILING'::text
        END AS readiness,
    r.verdict AS last_verdict,
    r.ran_at AS last_checked
   FROM examination_standard e
     LEFT JOIN verification_checks c ON c.check_key = e.control_key
     LEFT JOIN LATERAL ( SELECT vr.id,
            vr.ran_at,
            vr.check_key,
            vr.value_a,
            vr.value_b,
            vr.difference,
            vr.pct_apart,
            vr.verdict,
            vr.note
           FROM verification_runs vr
          WHERE vr.check_key = e.control_key
          ORDER BY vr.ran_at DESC
         LIMIT 1) r ON true;
create or replace view public.v_failed_product_lineage as
 WITH failed AS (
         SELECT p.raw ->> 'Label'::text AS failed_tag,
            p.license AS licence,
            p.raw #>> '{Item,Name}'::text[] AS failed_item,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS failed_category,
            NULLIF(p.raw ->> 'LocationName'::text, ''::text) AS room,
            (p.raw ->> 'PackagedDate'::text)::date AS failed_packaged_on,
            CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date) AS days_held,
            COALESCE((p.raw ->> 'IsOnHold'::text)::boolean, false) AS on_hold,
            round(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 2) AS remaining_lb,
            NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvests,
            string_to_array(NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text), ', '::text) AS src
           FROM metrc_packages p
          WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND (p.raw ->> 'LabTestingState'::text) ~~* '%fail%'::text
        )
 SELECT f.failed_tag,
    f.licence,
    f.failed_item,
    f.failed_category,
    f.room,
    f.failed_packaged_on,
    f.days_held,
    f.on_hold,
    f.remaining_lb,
    f.source_harvests,
    btrim(s.src_tag) AS source_tag,
    sp.raw #>> '{Item,Name}'::text[] AS source_item,
    f_strain_from_item(sp.raw #>> '{Item,Name}'::text[]) AS source_strain,
    NULLIF(sp.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
    (sp.raw ->> 'PackagedDate'::text)::date AS source_packaged_on,
    NULLIF(sp.raw ->> 'LocationName'::text, ''::text) AS source_room,
    sp.raw ->> 'LabTestingState'::text AS source_lab_state,
    round(f_to_pounds(COALESCE((sp.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(sp.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 2) AS source_created_lb,
        CASE
            WHEN sp.raw IS NULL THEN '(source package not in our mirror)'::text
            WHEN NULLIF(sp.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) IS NULL THEN 'OURS — made here'::text
            WHEN f_is_ours(sp.raw ->> 'ReceivedFromFacilityLicenseNumber'::text) THEN 'OURS — our other licence'::text
            ELSE 'THIRD PARTY — '::text || COALESCE(NULLIF(sp.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '?'::text)
        END AS source_ownership,
    COALESCE(NULLIF(sp.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '—'::text) AS source_supplier
   FROM failed f
     LEFT JOIN LATERAL unnest(COALESCE(f.src, ARRAY[]::text[])) s(src_tag) ON true
     LEFT JOIN metrc_packages sp ON (sp.raw ->> 'Label'::text) = btrim(s.src_tag);
create or replace view public.v_fg_metrc_check as
 WITH fg AS (
         SELECT product_inventory.id,
            product_inventory.category,
            product_inventory.current_status,
            product_inventory.production_batch,
            product_inventory.strain_flavor,
            NULLIF(regexp_replace(COALESCE(product_inventory.final_metrc_tag, product_inventory.bulk_metrc_tag), '\.0$'::text, ''::text), 'N/A'::text) AS tag_short,
            product_inventory.total_packaged,
            product_inventory.total_filled
           FROM product_inventory
        ), matched AS (
         SELECT f_1.id,
            count(m.id) AS metrc_matches,
            min(m.tag) AS metrc_tag,
            sum(m.quantity) AS metrc_quantity,
            min(m.uom) AS metrc_uom,
            min(m.lab_testing_state) AS lab_testing_state,
            bool_or(m.finished) AS metrc_finished
           FROM fg f_1
             LEFT JOIN metrc_packages m ON f_1.tag_short ~ '^[0-9]+$'::text AND m.tag ~~ ('%'::text || f_1.tag_short)
          GROUP BY f_1.id
        )
 SELECT f.category,
    f.current_status,
    f.production_batch,
    f.strain_flavor,
    f.tag_short AS sheet_tag,
    ma.metrc_matches,
    ma.metrc_tag,
    ma.metrc_quantity,
    ma.metrc_uom,
    ma.lab_testing_state,
    ma.metrc_finished,
    f.total_packaged,
    f.total_filled,
        CASE
            WHEN f.tag_short IS NULL OR f.tag_short !~ '^[0-9]+$'::text THEN 'NO TAG ON SHEET'::text
            WHEN ma.metrc_matches = 0 THEN 'TAG NOT IN SYNCED METRC'::text
            WHEN ma.metrc_matches > 1 THEN ('AMBIGUOUS - '::text || ma.metrc_matches) || ' METRC MATCHES'::text
            WHEN ma.metrc_finished THEN 'METRC SAYS FINISHED - SHEET STILL LISTS IT'::text
            ELSE 'MATCHED'::text
        END AS check_result
   FROM fg f
     JOIN matched ma ON ma.id = f.id
  ORDER BY (
        CASE
            WHEN ma.metrc_matches = 0 THEN 0
            WHEN ma.metrc_finished THEN 1
            ELSE 2
        END), f.category;
create or replace view public.v_field_help_lookup as
 SELECT page,
    section,
    field,
    plain_english,
    how_to_read,
    where_it_comes_from,
    the_arithmetic,
    watch_out_for,
    is_derived,
    watch_out_for IS NOT NULL AS has_a_named_trap
   FROM field_help
  ORDER BY page, section, field;
create or replace view public.v_finding_accountability as
 SELECT disposition,
    findings,
    dollars,
    past_due,
    oldest,
    newest,
    oldest AS oldest_date
   FROM ( SELECT finding_plans.disposition,
            count(*) AS findings,
            round(sum(COALESCE(finding_plans.dollars, 0::numeric)), 0) AS dollars,
            count(*) FILTER (WHERE finding_plans.due_on < CURRENT_DATE AND (finding_plans.disposition <> ALL (ARRAY['resolved'::text, 'ignored'::text]))) AS past_due,
            min(finding_plans.created_at)::date AS oldest,
            max(finding_plans.created_at)::date AS newest
           FROM finding_plans
          GROUP BY finding_plans.disposition
          ORDER BY (round(sum(COALESCE(finding_plans.dollars, 0::numeric)), 0)) DESC NULLS LAST) q;
create or replace view public.v_finding_alert_ready as
 SELECT id,
    fingerprint,
    severity,
    what,
    observed_at,
    who_is_accountable IS NOT NULL AND btrim(who_is_accountable) <> ''::text AS has_who,
    what IS NOT NULL AND btrim(what) <> ''::text AS has_what,
    when_it_started IS NOT NULL AND btrim(when_it_started) <> ''::text AS has_when,
    where_it_is IS NOT NULL AND btrim(where_it_is) <> ''::text AS has_where,
    why_it_matters IS NOT NULL AND btrim(why_it_matters) <> ''::text AS has_why,
    how_it_was_detected IS NOT NULL AND btrim(how_it_was_detected) <> ''::text AS has_how,
    solutions IS NOT NULL AND array_length(solutions, 1) >= 1 AS has_solutions,
    guard_recommendation IS NOT NULL AND btrim(guard_recommendation) <> ''::text AS has_recommendation,
    array_remove(ARRAY[
        CASE
            WHEN who_is_accountable IS NULL OR btrim(who_is_accountable) = ''::text THEN 'who'::text
            ELSE NULL::text
        END,
        CASE
            WHEN what IS NULL OR btrim(what) = ''::text THEN 'what'::text
            ELSE NULL::text
        END,
        CASE
            WHEN when_it_started IS NULL OR btrim(when_it_started) = ''::text THEN 'when'::text
            ELSE NULL::text
        END,
        CASE
            WHEN where_it_is IS NULL OR btrim(where_it_is) = ''::text THEN 'where'::text
            ELSE NULL::text
        END,
        CASE
            WHEN why_it_matters IS NULL OR btrim(why_it_matters) = ''::text THEN 'why'::text
            ELSE NULL::text
        END,
        CASE
            WHEN how_it_was_detected IS NULL OR btrim(how_it_was_detected) = ''::text THEN 'how'::text
            ELSE NULL::text
        END,
        CASE
            WHEN solutions IS NULL OR array_length(solutions, 1) IS NULL THEN 'solutions'::text
            ELSE NULL::text
        END,
        CASE
            WHEN guard_recommendation IS NULL OR btrim(guard_recommendation) = ''::text THEN 'recommendation'::text
            ELSE NULL::text
        END], NULL::text) AS missing,
        CASE
            WHEN who_is_accountable IS NULL OR btrim(who_is_accountable) = ''::text OR what IS NULL OR btrim(what) = ''::text OR when_it_started IS NULL OR btrim(when_it_started) = ''::text OR where_it_is IS NULL OR btrim(where_it_is) = ''::text OR why_it_matters IS NULL OR btrim(why_it_matters) = ''::text OR how_it_was_detected IS NULL OR btrim(how_it_was_detected) = ''::text OR solutions IS NULL OR array_length(solutions, 1) IS NULL OR guard_recommendation IS NULL OR btrim(guard_recommendation) = ''::text THEN false
            ELSE true
        END AS ready_to_send
   FROM watchdog_findings f;
create or replace view public.v_finding_history as
 SELECT created_at::date AS raised_on,
    finding_source,
    headline,
    disposition,
    disposition_reason,
    plan,
    owner_assigned,
    due_on,
    dollars,
    decided_by,
    decided_at::date AS decided_on,
        CASE disposition
            WHEN 'resolved'::text THEN 'Closed - '::text || COALESCE(disposition_reason, 'resolved'::text)
            WHEN 'ignored'::text THEN 'Deliberately ignored - '::text || COALESCE(disposition_reason, 'no reason recorded'::text)
            WHEN 'on_todo_list'::text THEN 'On the to-do list'::text ||
            CASE
                WHEN due_on IS NOT NULL THEN ', due '::text || due_on
                ELSE ''::text
            END
            WHEN 'saved_for_later'::text THEN 'Saved for later review'::text
            WHEN 'planned'::text THEN 'Plan written'::text ||
            CASE
                WHEN owner_assigned IS NOT NULL THEN ', assigned to '::text || owner_assigned
                ELSE ''::text
            END
            WHEN 'shared'::text THEN 'Shared with the team'::text
            ELSE 'Open, no decision recorded'::text
        END AS status_in_plain_english,
    snapshot,
    finding_key,
    id
   FROM finding_plans fp
  ORDER BY created_at DESC;
create or replace view public.v_findings as
 WITH raw AS (
         SELECT 'agent:'::text || f.id::text AS finding_key,
            'agent'::text AS source,
            COALESCE(NULLIF(f.agent, ''::text), 'Unassigned'::text) AS department,
            f.severity,
            f.headline AS what,
            f.scope AS where_it_is,
            NULL::text AS who_is_accountable,
            f.detail AS why_it_matters,
            f.action AS what_to_do,
            NULL::text AS the_arithmetic,
            NULL::text AS how_it_was_detected,
            NULL::text AS when_it_started,
                CASE
                    WHEN f.metric IS NOT NULL THEN (f.metric::text || ' '::text) || COALESCE(f.units, ''::text)
                    ELSE NULL::text
                END AS evidence,
            NULL::integer AS record_count,
            f.pounds,
            f.dollars,
            f.detected_at AS first_raised,
            f.detected_at AS last_seen,
            1 AS times_seen,
            f.resolved_at,
            f.resolution AS resolution_note,
            f.fingerprint,
            'agent:'::text || COALESCE(f.agent, '?'::text) AS pattern_key,
            f.drill_to AS drill
           FROM agent_findings f
        UNION ALL
         SELECT 'watchdog:'::text || w.id::text,
            'watchdog'::text AS text,
            'Unassigned'::text AS text,
            w.severity,
            w.what,
            w.where_it_is,
            w.who_is_accountable,
            w.why_it_matters,
            w.what_to_do,
            w.the_arithmetic,
            w.how_it_was_detected,
            w.when_it_started,
            w.evidence::text AS evidence,
            w.record_count,
            w.pounds,
            w.dollars,
            w.observed_at,
            w.observed_at,
            1,
            w.cleared_at,
            NULL::text AS text,
            w.fingerprint,
            'watchdog:'::text || "left"(COALESCE(w.how_it_was_detected, '?'::text), 80),
            w.drill
           FROM watchdog_findings w
        UNION ALL
         SELECT 'custody:'::text || c.id::text,
            'custody'::text AS text,
            'Compliance'::text AS text,
            c.severity,
            c.flag,
            concat_ws(' · '::text, NULLIF(c.item, ''::text), NULLIF(c.location, ''::text), NULLIF(c.identifier, ''::text)) AS concat_ws,
            NULL::text AS text,
            c.detail,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
                CASE
                    WHEN c.quantity IS NOT NULL THEN (c.quantity::text || ' '::text) || COALESCE(c.uom, ''::text)
                    ELSE NULL::text
                END AS "case",
            NULL::integer AS int4,
                CASE
                    WHEN lower(COALESCE(c.uom, ''::text)) = ANY (ARRAY['lb'::text, 'lbs'::text, 'pound'::text, 'pounds'::text]) THEN c.quantity
                    ELSE NULL::numeric
                END AS "case",
            NULL::numeric AS "numeric",
            COALESCE(c.reference_date::timestamp with time zone, c.captured_at) AS "coalesce",
            c.captured_at,
            1,
            c.resolved_at,
            c.resolution_note,
            NULL::text AS text,
            'custody:'::text || COALESCE(c.flag, '?'::text),
            NULL::text AS text
           FROM custody_alert_log c
        UNION ALL
         SELECT 'inventory:'::text || i.id::text,
            'inventory'::text AS text,
            COALESCE(NULLIF(i.area, ''::text), 'Inventory'::text) AS "coalesce",
            i.severity,
            i.headline,
            i.area,
            NULL::text AS text,
            i.detail,
            i.what_to_do,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            NULL::integer AS int4,
            i.pounds,
            i.dollars,
            i.first_raised,
            i.last_seen,
            COALESCE(i.times_seen, 1) AS "coalesce",
            i.resolved_at,
            i.resolution_note,
            i.fingerprint,
            'inventory:'::text || COALESCE(i.area, '?'::text),
            i.drill
           FROM inventory_alerts i
        ), marked AS (
         SELECT r.finding_key,
            r.source,
            r.department,
            r.severity,
            r.what,
            r.where_it_is,
            r.who_is_accountable,
            r.why_it_matters,
            r.what_to_do,
            r.the_arithmetic,
            r.how_it_was_detected,
            r.when_it_started,
            r.evidence,
            r.record_count,
            r.pounds,
            r.dollars,
            r.first_raised,
            r.last_seen,
            r.times_seen,
            r.resolved_at,
            r.resolution_note,
            r.fingerprint,
            r.pattern_key,
            r.drill,
                CASE
                    WHEN r.dollars IS NOT NULL AND r.pounds IS NOT NULL THEN (((r.severity || '|'::text) || r.dollars::text) || '|'::text) || r.pounds::text
                    ELSE NULL::text
                END AS merge_key
           FROM raw r
        ), ranked AS (
         SELECT m.finding_key,
            m.source,
            m.department,
            m.severity,
            m.what,
            m.where_it_is,
            m.who_is_accountable,
            m.why_it_matters,
            m.what_to_do,
            m.the_arithmetic,
            m.how_it_was_detected,
            m.when_it_started,
            m.evidence,
            m.record_count,
            m.pounds,
            m.dollars,
            m.first_raised,
            m.last_seen,
            m.times_seen,
            m.resolved_at,
            m.resolution_note,
            m.fingerprint,
            m.pattern_key,
            m.drill,
            m.merge_key,
                CASE
                    WHEN m.merge_key IS NULL THEN m.finding_key
                    WHEN min(m.source) OVER (PARTITION BY m.merge_key) = max(m.source) OVER (PARTITION BY m.merge_key) THEN m.finding_key
                    ELSE first_value(m.finding_key) OVER (PARTITION BY m.merge_key ORDER BY m.first_raised, m.finding_key)
                END AS canon
           FROM marked m
        )
 SELECT finding_key,
    source,
    department,
    severity,
    what,
    where_it_is,
    who_is_accountable,
    why_it_matters,
    what_to_do,
    the_arithmetic,
    how_it_was_detected,
    when_it_started,
    evidence,
    record_count,
    pounds,
    dollars,
    first_raised,
    last_seen,
    times_seen,
    resolved_at,
    resolution_note,
    fingerprint,
    pattern_key,
    drill,
        CASE
            WHEN resolved_at IS NULL THEN 'open'::text
            ELSE 'resolved'::text
        END AS state,
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            WHEN 'watch'::text THEN 3
            ELSE 4
        END AS severity_rank,
    count(*) FILTER (WHERE first_raised >= (now() - '6 mons'::interval)) OVER (PARTITION BY pattern_key) AS occurrences_6mo,
        CASE severity
            WHEN 'critical'::text THEN 1
            ELSE 2
        END AS priority_band,
    canon AS canonical_key,
    canon <> finding_key AS is_duplicate,
        CASE
            WHEN canon <> finding_key THEN canon
            ELSE NULL::text
        END AS duplicate_of
   FROM ranked k;
create or replace view public.v_finished_goods_metrc_reconciliation as
 WITH fg AS (
         SELECT p.final_metrc_tag AS tag,
            p.source_sheet,
            p.source_row,
            p.category,
            p.strain_flavor,
            p.production_batch,
            p.current_status,
            p.size_value,
            p.cases_available,
            p.coa_link,
            p.expiration_date,
            COALESCE(p.total_packaged, p.total_units_packaged) AS sheet_units,
            p.total_gram_equivalent AS sheet_gram_equiv,
            p.bulk_metrc_tag,
            p.prefill_metrc_tag
           FROM product_inventory p
          WHERE p.still_in_sheet AND p.final_metrc_tag IS NOT NULL
        ), m AS (
         SELECT metrc_packages.tag,
            sum(metrc_packages.quantity) AS metrc_qty,
            min(metrc_packages.uom) AS metrc_uom,
            count(*) AS mirror_rows,
            string_agg(DISTINCT metrc_packages.license, ', '::text ORDER BY metrc_packages.license) AS licences,
            bool_or(metrc_packages.finished) AS any_finished,
            string_agg(DISTINCT metrc_packages.item_name, ' | '::text) AS metrc_item,
            max(metrc_packages.lab_testing_state) AS lab_testing_state
           FROM metrc_packages
          GROUP BY metrc_packages.tag
        ), tr AS (
         SELECT metrc_rpt_package_transfers.package_tag AS tag,
            count(*) AS transfer_lines,
            string_agg(DISTINCT metrc_rpt_package_transfers.manifest_number, ', '::text) AS manifests,
            max(metrc_rpt_package_transfers.received_on) AS last_received_on,
            string_agg(DISTINCT metrc_rpt_package_transfers.destination_facility, ', '::text) AS destinations,
            string_agg(DISTINCT metrc_rpt_package_transfers.item, ' | '::text) AS manifest_item
           FROM metrc_rpt_package_transfers
          GROUP BY metrc_rpt_package_transfers.package_tag
        )
 SELECT fg.tag,
    fg.source_sheet,
    fg.source_row,
    fg.category,
    fg.strain_flavor,
    fg.production_batch,
    fg.current_status,
    fg.cases_available,
    fg.coa_link,
    fg.expiration_date,
    fg.bulk_metrc_tag,
    fg.prefill_metrc_tag,
    fg.sheet_units,
    fg.size_value,
    fg.sheet_gram_equiv,
    m.metrc_qty,
    m.metrc_uom,
    m.licences,
    m.any_finished,
    m.metrc_item,
    m.lab_testing_state,
    tr.transfer_lines,
    tr.manifests,
    tr.last_received_on,
    tr.destinations,
    tr.manifest_item,
        CASE
            WHEN m.tag IS NOT NULL THEN 'in_mirror'::text
            WHEN tr.tag IS NOT NULL THEN 'not_in_mirror_but_manifested'::text
            ELSE 'not_in_mirror_and_no_manifest'::text
        END AS existence,
        CASE
            WHEN m.tag IS NULL THEN NULL::text
            WHEN m.metrc_uom = 'ea'::text AND fg.sheet_units IS NOT NULL AND fg.sheet_units = m.metrc_qty THEN 'agree'::text
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_units IS NOT NULL AND fg.size_value IS NOT NULL AND abs(fg.sheet_units * fg.size_value - m.metrc_qty) <= 0.01 THEN 'agree'::text
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_gram_equiv IS NOT NULL AND abs(fg.sheet_gram_equiv - m.metrc_qty) <= 0.01 THEN 'agree'::text
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_units IS NOT NULL AND abs(fg.sheet_units - m.metrc_qty) <= 0.01 THEN 'agree'::text
            WHEN fg.sheet_units IS NULL AND fg.sheet_gram_equiv IS NULL THEN 'no_sheet_quantity'::text
            ELSE 'differs'::text
        END AS quantity,
        CASE
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_units IS NOT NULL AND fg.size_value IS NOT NULL THEN fg.sheet_units * fg.size_value
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_gram_equiv IS NOT NULL THEN fg.sheet_gram_equiv
            ELSE fg.sheet_units
        END AS sheet_comparable,
        CASE
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_units IS NOT NULL AND fg.size_value IS NOT NULL THEN 'units x size (g)'::text
            WHEN m.metrc_uom = 'g'::text AND fg.sheet_gram_equiv IS NOT NULL THEN 'total gram equivalent (g)'::text
            WHEN m.metrc_uom = 'ea'::text THEN 'units (ea)'::text
            ELSE 'units (basis unstated)'::text
        END AS comparison_basis,
        CASE
            WHEN m.tag IS NULL AND tr.tag IS NULL THEN NULL::text
            WHEN fg.strain_flavor IS NULL THEN NULL::text
            WHEN f_strain_fold(COALESCE(m.metrc_item, tr.manifest_item)) ~~ (('%'::text || f_strain_fold(fg.strain_flavor)) || '%'::text) THEN 'strain_matches'::text
            ELSE 'STRAIN DOES NOT MATCH THE TAG'::text
        END AS identity_check
   FROM fg
     LEFT JOIN m ON m.tag = fg.tag
     LEFT JOIN tr ON tr.tag = fg.tag;
create or replace view public.v_flow_in_transit as
 SELECT p.tag,
    p.item_name AS item,
    round(f_to_pounds(p.quantity, p.uom), 2) AS lb,
    p.quantity,
    p.uom,
        CASE
            WHEN COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) = ANY (ARRAY['MC281714'::text, 'MP281909'::text]) THEN 'Ours'::text
            ELSE 'Third-party'::text
        END AS origin,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'license '::text || COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, '?'::text)) AS made_by,
    p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS made_by_license,
    (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
    CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date) AS days_since_packaged,
    p.location AS last_known_location,
    p.lab_testing_state AS lab_state,
    c.lab_report_id AS coa_report_id,
    c.total_thc AS coa_total_thc,
    c.report_date AS coa_report_date,
    d.storage_path AS coa_document,
    m.manifest_number,
    md.storage_path AS manifest_document,
    p.raw ->> 'SourcePackageLabels'::text AS parent_tags
   FROM metrc_packages p
     LEFT JOIN LATERAL ( SELECT ce.lab_report_id,
            ce.total_thc,
            ce.report_date
           FROM coa_extract ce
          WHERE ce.package_tag = p.tag
          ORDER BY ce.report_date DESC NULLS LAST
         LIMIT 1) c ON true
     LEFT JOIN LATERAL ( SELECT dd.storage_path
           FROM metrc_documents dd
          WHERE dd.package_tag = p.tag AND dd.doc_type ~~* '%coa%'::text
         LIMIT 1) d ON true
     LEFT JOIN LATERAL ( SELECT t.manifest_number
           FROM metrc_rpt_package_transfers t
          WHERE t.package_tag = p.tag
          ORDER BY t.as_of_date DESC NULLS LAST
         LIMIT 1) m ON true
     LEFT JOIN LATERAL ( SELECT dm.storage_path
           FROM metrc_documents dm
          WHERE dm.manifest_number = m.manifest_number AND dm.doc_type ~~* '%manifest%'::text
         LIMIT 1) md ON true
  WHERE p.source_state = 'intransit'::text AND NOT COALESCE(p.finished, false);
create or replace view public.v_forensic_audit_history as
 SELECT run_at::date AS audit_date,
    run_type,
    count(*) FILTER (WHERE verdict = ANY (ARRAY['FAIL'::text, 'EXPOSURE'::text])) AS failures,
    count(*) FILTER (WHERE verdict = 'CLEAN'::text) AS clean,
    count(*) AS metrics_checked,
    round(sum(value) FILTER (WHERE unit = 'dollars'::text), 0) AS dollars_identified,
    string_agg(DISTINCT section, ', '::text) FILTER (WHERE verdict = ANY (ARRAY['FAIL'::text, 'EXPOSURE'::text])) AS failing_sections
   FROM forensic_audits
  GROUP BY (run_at::date), run_type
  ORDER BY (run_at::date) DESC;
create or replace view public.v_forensic_audit_latest as
 WITH runs AS (
         SELECT DISTINCT forensic_audits.run_at
           FROM forensic_audits
          ORDER BY forensic_audits.run_at DESC
         LIMIT 2
        ), cur AS (
         SELECT forensic_audits.id,
            forensic_audits.run_at,
            forensic_audits.run_type,
            forensic_audits.section,
            forensic_audits.metric,
            forensic_audits.value,
            forensic_audits.value_text,
            forensic_audits.unit,
            forensic_audits.responsible,
            forensic_audits.verdict,
            forensic_audits.evidence
           FROM forensic_audits
          WHERE forensic_audits.run_at = (( SELECT max(runs.run_at) AS max
                   FROM runs))
        ), prev AS (
         SELECT forensic_audits.id,
            forensic_audits.run_at,
            forensic_audits.run_type,
            forensic_audits.section,
            forensic_audits.metric,
            forensic_audits.value,
            forensic_audits.value_text,
            forensic_audits.unit,
            forensic_audits.responsible,
            forensic_audits.verdict,
            forensic_audits.evidence
           FROM forensic_audits
          WHERE forensic_audits.run_at = (( SELECT min(runs.run_at) AS min
                   FROM runs)) AND (( SELECT count(*) AS count
                   FROM runs)) > 1
        )
 SELECT c.section,
    c.metric,
    c.value,
    c.value_text,
    c.unit,
    c.responsible,
    c.verdict,
    c.evidence,
    p.value AS previous_value,
        CASE
            WHEN p.value IS NULL THEN 'first audit'::text
            WHEN c.value IS NULL THEN '—'::text
            WHEN c.value < p.value THEN 'improved by '::text || round(p.value - c.value, 1)
            WHEN c.value > p.value THEN 'WORSE by '::text || round(c.value - p.value, 1)
            ELSE 'unchanged'::text
        END AS movement,
    c.run_at
   FROM cur c
     LEFT JOIN prev p ON p.section = c.section AND p.metric = c.metric
  ORDER BY (
        CASE c.verdict
            WHEN 'FAIL'::text THEN 0
            WHEN 'EXPOSURE'::text THEN 1
            WHEN 'BELOW PAR'::text THEN 2
            WHEN 'CASH TIED UP'::text THEN 3
            WHEN 'NO AUTHORITY RECORDED'::text THEN 4
            ELSE 9
        END), c.section, c.metric;
create or replace view public.v_forensic_onhand_by_location as
 SELECT COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(NO ROOM RECORDED)'::text) AS room,
    COALESCE(r.role, 'unmapped'::text) AS room_role,
    p.license AS licence,
    COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, ''::text), '(uncategorised)'::text) AS category,
    f_product_line((p.raw -> 'Item'::text) ->> 'Name'::text, (p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, NULL::text) AS product_line,
    f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), p.license)) AS is_ours,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text) AS grown_or_processed_by,
    count(*) AS packages,
    round(sum(
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN f_to_pounds(COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))
            ELSE 0::numeric
        END), 3) AS pounds
   FROM metrc_packages p
     LEFT JOIN room_roles r ON upper(btrim(r.room_name)) = upper(btrim(p.raw ->> 'LocationName'::text))
  WHERE NOT COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) AND COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric
  GROUP BY (COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(NO ROOM RECORDED)'::text)), (COALESCE(r.role, 'unmapped'::text)), p.license, (COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, ''::text), '(uncategorised)'::text)), (f_product_line((p.raw -> 'Item'::text) ->> 'Name'::text, (p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, NULL::text)), (f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), p.license))), (COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text));
create or replace view public.v_forensic_room_census as
 SELECT 'GROWING'::text AS stage,
    COALESCE(NULLIF(pl.room, ''::text), '(NO ROOM RECORDED)'::text) AS room,
    COALESCE(rr.role, 'unmapped'::text) AS room_role,
    pl.license AS licence,
    pl.phase AS detail,
    pl.strain,
    count(*)::numeric AS plant_count,
    0::numeric AS wet_lb,
    0::numeric AS packaged_lb,
    true AS is_ours,
    'Twisted Growers LLC'::text AS grown_or_processed_by,
    0::numeric AS units
   FROM metrc_plants pl
     LEFT JOIN room_roles rr ON upper(btrim(rr.room_name)) = upper(btrim(pl.room))
  GROUP BY 'GROWING'::text, (COALESCE(NULLIF(pl.room, ''::text), '(NO ROOM RECORDED)'::text)), (COALESCE(rr.role, 'unmapped'::text)), pl.license, pl.phase, pl.strain
UNION ALL
 SELECT 'DRYING / CURING'::text AS stage,
    COALESCE(NULLIF(hm.room, ''::text), '(NO ROOM RECORDED)'::text) AS room,
    COALESCE(rr.role, 'unmapped'::text) AS room_role,
    hm.licence,
    'Harvest '::text || hm.harvest_batch AS detail,
    hm.strain,
    COALESCE(sum(hm.plants), 0::numeric) AS plant_count,
    COALESCE(sum(hm.wet_lb), 0::numeric) AS wet_lb,
    0 AS packaged_lb,
    true AS is_ours,
    'Twisted Growers LLC'::text AS grown_or_processed_by,
    0 AS units
   FROM metrc_rpt_harvest_moisture hm
     LEFT JOIN room_roles rr ON upper(btrim(rr.room_name)) = upper(btrim(hm.room))
  WHERE hm.finished_on IS NULL
  GROUP BY 'DRYING / CURING'::text, (COALESCE(NULLIF(hm.room, ''::text), '(NO ROOM RECORDED)'::text)), (COALESCE(rr.role, 'unmapped'::text)), hm.licence, ('Harvest '::text || hm.harvest_batch), hm.strain
UNION ALL
 SELECT 'PACKAGED'::text AS stage,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(NO ROOM RECORDED)'::text) AS room,
    COALESCE(rr.role, 'unmapped'::text) AS room_role,
    p.license AS licence,
    COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, ''::text), '(uncategorised)'::text) AS detail,
    COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'StrainName'::text, ''::text), f_strain_from_item((p.raw -> 'Item'::text) ->> 'Name'::text)) AS strain,
    0 AS plant_count,
    0 AS wet_lb,
    sum(
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN f_to_pounds(COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))
            ELSE 0::numeric
        END) AS packaged_lb,
    f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), p.license)) AS is_ours,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text) AS grown_or_processed_by,
    sum(
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN 0::numeric
            ELSE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric)
        END) AS units
   FROM metrc_packages p
     LEFT JOIN room_roles rr ON upper(btrim(rr.room_name)) = upper(btrim(p.raw ->> 'LocationName'::text))
  WHERE NOT COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) AND COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric
  GROUP BY 'PACKAGED'::text, (COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(NO ROOM RECORDED)'::text)), (COALESCE(rr.role, 'unmapped'::text)), p.license, (COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, ''::text), '(uncategorised)'::text)), (COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'StrainName'::text, ''::text), f_strain_from_item((p.raw -> 'Item'::text) ->> 'Name'::text))), (f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), p.license))), (COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text));
create or replace view public.v_forensic_sales as
 SELECT (o.payload ->> 'order_date'::text)::date AS order_date,
    o.payload ->> 'invoice_number'::text AS invoice_number,
    NULLIF(o.payload ->> 'manifest_number'::text, ''::text) AS manifest_number,
    (o.payload -> 'buyer'::text) ->> 'name'::text AS buyer,
    o.payload ->> 'buyer_state_license'::text AS buyer_licence,
    ((o.payload -> 'order_status'::text) -> 'parent_status'::text) ->> 'name'::text AS order_status,
    COALESCE((o.payload ->> 'cancelled'::text)::boolean, false) AS cancelled,
    o.payload ->> 'payment_status'::text AS payment_status,
    COALESCE((o.payload ->> 'total_raw'::text)::numeric, 0::numeric) / 100.0 AS total_usd,
    COALESCE((o.payload ->> 'subtotal_raw'::text)::numeric, 0::numeric) / 100.0 AS subtotal_usd,
    COALESCE((o.payload ->> 'total_payments_raw'::text)::numeric, 0::numeric) / 100.0 AS paid_usd,
    it.value ->> 'product_name'::text AS product_name,
    (it.value -> 'product_category'::text) ->> 'name'::text AS apex_category,
    f_product_line(it.value ->> 'product_name'::text, (it.value -> 'product_category'::text) ->> 'name'::text, NULL::text) AS product_line,
    (it.value -> 'cultivar'::text) ->> 'name'::text AS strain,
    (it.value -> 'operation'::text) ->> 'state_license'::text AS selling_licence,
    NULLIF(it.value ->> 'metrc_package_label'::text, ''::text) AS metrc_tag,
    COALESCE((it.value ->> 'order_quantity'::text)::numeric, 0::numeric) AS qty,
    (it.value -> 'order_unit_measurement'::text) ->> 'name'::text AS qty_uom,
    COALESCE((it.value ->> 'units_per_case'::text)::numeric, 1::numeric) AS units_per_case,
    COALESCE((it.value ->> 'order_price_raw'::text)::numeric, 0::numeric) / 100.0 AS line_price_usd,
    (o.payload ->> 'id'::text)::bigint AS order_id,
    (it.value ->> 'id'::text)::bigint AS line_id
   FROM apex_raw o
     LEFT JOIN LATERAL jsonb_array_elements(COALESCE(o.payload -> 'items'::text, '[]'::jsonb)) it(value) ON true
  WHERE o.entity = 'shipping-orders'::text;
create or replace view public.v_full_accountability as
 WITH harvested AS (
         SELECT to_char(metrc_harvests.harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, metrc_harvests.harvest_start::timestamp with time zone)::date AS month_date,
            metrc_harvests.license,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS packaged_g,
            sum(COALESCE((metrc_harvests.raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants,
            count(*) AS harvests
           FROM metrc_harvests
          WHERE metrc_harvests.harvest_start IS NOT NULL
          GROUP BY (to_char(metrc_harvests.harvest_start::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, metrc_harvests.harvest_start::timestamp with time zone)::date), metrc_harvests.license
        ), made AS (
         SELECT to_char(metrc_packages.packaged_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
            metrc_packages.license,
            count(*) AS packages_made,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%flower%'::text) AS flower_pkgs,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%concentrate%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%rosin%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%hash%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%distillate%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%crude%'::text) AS concentrate_pkgs,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%vape%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%cart%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%vape%'::text) AS vape_pkgs,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%pre-roll%'::text OR COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%preroll%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%preroll%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%pre-roll%'::text) AS preroll_pkgs,
            sum(COALESCE((metrc_packages.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric)) AS produced_qty,
            sum(COALESCE(metrc_packages.quantity, 0::numeric)) FILTER (WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AS still_on_hand,
            sum(COALESCE(metrc_packages.quantity, 0::numeric)) FILTER (WHERE metrc_packages.source_state = 'intransit'::text) AS in_transit_qty,
            sum(COALESCE((metrc_packages.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric)) FILTER (WHERE metrc_packages.source_state = 'inactive'::text) AS closed_or_sold_qty,
            sum(COALESCE(metrc_packages.quantity, 0::numeric)) FILTER (WHERE metrc_packages.lab_testing_state = 'TestFailed'::text) AS failed_qty,
            sum(GREATEST(COALESCE((metrc_packages.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) - COALESCE(metrc_packages.quantity, 0::numeric), 0::numeric)) FILTER (WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AS unexplained_reduction
           FROM metrc_packages
          WHERE metrc_packages.packaged_on IS NOT NULL
          GROUP BY (to_char(metrc_packages.packaged_on::timestamp with time zone, 'YYYY-MM'::text)), metrc_packages.license
        ), sold AS (
         SELECT to_char(metrc_transfers.created_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
            metrc_transfers.license,
            count(*) AS manifests_out,
            sum(COALESCE((metrc_transfers.raw ->> 'PackageCount'::text)::numeric, 0::numeric)) AS packages_shipped,
            count(*) FILTER (WHERE (metrc_transfers.raw ->> 'ReceivedDateTime'::text) IS NULL) AS manifests_unconfirmed
           FROM metrc_transfers
          WHERE metrc_transfers.direction = 'outgoing'::text AND metrc_transfers.created_on IS NOT NULL
          GROUP BY (to_char(metrc_transfers.created_on::timestamp with time zone, 'YYYY-MM'::text)), metrc_transfers.license
        )
 SELECT COALESCE(h.month, m.month, s.month) AS month,
    COALESCE(h.license, m.license, s.license) AS license,
    h.harvests,
    h.plants AS plants_harvested,
    round(h.wet_g / 453.592, 1) AS harvested_wet_lbs,
    round(h.waste_g / 453.592, 1) AS waste_lbs,
        CASE
            WHEN h.wet_g > 0::numeric THEN round(100.0 * h.waste_g / h.wet_g, 1)
            ELSE NULL::numeric
        END AS waste_pct,
    round(h.packaged_g / 453.592, 1) AS packaged_from_harvest_lbs,
    m.packages_made,
    m.flower_pkgs AS flower,
    m.concentrate_pkgs AS concentrates,
    m.vape_pkgs AS vapes,
    m.preroll_pkgs AS prerolls,
    round(m.produced_qty, 1) AS produced_qty,
    round(m.still_on_hand, 1) AS in_stock_qty,
    round(m.in_transit_qty, 1) AS in_transit_qty,
    round(m.closed_or_sold_qty, 1) AS sold_or_closed_qty,
    round(m.failed_qty, 1) AS failed_testing_qty,
    round(COALESCE(m.unexplained_reduction, 0::numeric), 1) AS unaccounted_qty,
    s.manifests_out,
    s.packages_shipped,
    s.manifests_unconfirmed,
        CASE
            WHEN COALESCE(m.unexplained_reduction, 0::numeric) > 0::numeric THEN ('DISCREPANCY - '::text || round(m.unexplained_reduction, 1)) || ' reduced with no recorded reason'::text
            WHEN COALESCE(s.manifests_unconfirmed, 0::bigint) > 0 THEN ('SHIPMENTS UNCONFIRMED - '::text || s.manifests_unconfirmed) || ' manifest(s) not confirmed received'::text
            WHEN COALESCE(m.failed_qty, 0::numeric) > 0::numeric THEN 'FAILED TESTING on hand - decide destruction or remediation'::text
            WHEN h.wet_g > 0::numeric AND (COALESCE(h.waste_g, 0::numeric) / NULLIF(h.wet_g, 0::numeric)) > 0.15 THEN 'HIGH WASTE - above 15 percent of wet weight'::text
            ELSE 'Accounted for'::text
        END AS accountability_status
   FROM harvested h
     FULL JOIN made m ON m.month = h.month AND m.license = h.license
     FULL JOIN sold s ON s.month = COALESCE(h.month, m.month) AND s.license = COALESCE(h.license, m.license)
  WHERE COALESCE(h.month, m.month, s.month) IS NOT NULL
  ORDER BY (COALESCE(h.month, m.month, s.month)) DESC, (COALESCE(h.license, m.license, s.license));
create or replace view public.v_hardcoded_thresholds as
 WITH defs AS (
         SELECT c.relname::text AS object_name,
                CASE c.relkind
                    WHEN 'v'::"char" THEN 'view'::text
                    WHEN 'm'::"char" THEN 'matview'::text
                    ELSE NULL::text
                END AS object_type,
            pg_get_viewdef(c.oid, true) AS body
           FROM pg_class c
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"]))
        UNION ALL
         SELECT p.proname::text AS proname,
            'function'::text,
            pg_get_functiondef(p.oid) AS pg_get_functiondef
           FROM pg_proc p
             JOIN pg_namespace n ON n.oid = p.pronamespace
          WHERE n.nspname = 'public'::name AND p.prokind = 'f'::"char" AND NOT (EXISTS ( SELECT 1
                   FROM pg_depend d_1
                  WHERE d_1.objid = p.oid AND d_1.classid = 'pg_proc'::regclass::oid AND d_1.deptype = 'e'::"char"))
        )
 SELECT d.object_name,
    d.object_type,
    m.column_pattern AS compared_column,
    m.rule_key AS owner_set_rule,
    r.value AS rule_says,
    ((regexp_match(d.body, m.column_pattern || '\s*([<>=]{1,2})\s*([0-9]+(\.[0-9]+)?)'::text))[1] || ' '::text) || (regexp_match(d.body, m.column_pattern || '\s*([<>=]{1,2})\s*([0-9]+(\.[0-9]+)?)'::text))[2] AS hardcoded_as,
    m.why
   FROM defs d
     JOIN threshold_column_map m ON d.body ~ (m.column_pattern || '\s*[<>=]{1,2}\s*[0-9]'::text)
     JOIN conversion_factors r ON r.key = m.rule_key
  WHERE NOT d.body ~* (('f_rule\s*\(\s*'''::text || m.rule_key) || ''''::text) AND d.object_name <> 'v_hardcoded_thresholds'::text
  ORDER BY d.object_type, d.object_name;
create or replace view public.v_harvest_benchmark_note as
 SELECT 'Wet to packaged'::text AS measure,
    '20 to 25 percent'::text AS published_norm,
    'Fresh cannabis is 75-80 percent water. A 4:1 to 5:1 wet:dry ratio is the standard commercial expectation.'::text AS why,
    'Any month above about 30 percent means the wet weight was recorded low, not that yield was high.'::text AS how_to_read
UNION ALL
 SELECT 'Grams per square foot of canopy'::text AS measure,
    '35 g/sq ft start-up, 50 to 70 g/sq ft established'::text AS published_norm,
    'This is the benchmark commercial cultivators actually use, because it is independent of how many plants you put under the light.'::text AS why,
    'Grams per plant is NOT a valid benchmark - it is set by plant density and veg time, not by grower skill.'::text AS how_to_read
UNION ALL
 SELECT 'Plant density'::text AS measure,
    '0.65 to 1.0 flowering plants per square foot'::text AS published_norm,
    'Published bench-production range for indoor and greenhouse.'::text AS why,
    'At this density, 50 g/sq ft works out to roughly 50 to 75 grams per plant - not 130.'::text AS how_to_read;
create or replace view public.v_harvest_cycle_compliance as
 WITH d AS (
         SELECT DISTINCT metrc_harvests.flower_room,
            metrc_harvests.harvest_start
           FROM metrc_harvests
          WHERE metrc_harvests.flower_room IS NOT NULL AND metrc_harvests.harvest_start IS NOT NULL
        ), marked AS (
         SELECT d.flower_room,
            d.harvest_start,
                CASE
                    WHEN (d.harvest_start - lag(d.harvest_start) OVER (PARTITION BY d.flower_room ORDER BY d.harvest_start)) <= f_rule('pull_event_span_days'::text)::integer THEN 0
                    ELSE 1
                END AS starts_new_event
           FROM d
        ), evented AS (
         SELECT marked.flower_room,
            marked.harvest_start,
            sum(marked.starts_new_event) OVER (PARTITION BY marked.flower_room ORDER BY marked.harvest_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS event_no
           FROM marked
        ), pulls AS (
         SELECT evented.flower_room,
            evented.event_no,
            min(evented.harvest_start) AS pull_start,
            max(evented.harvest_start) AS pull_end,
            count(*)::integer AS days_recording
           FROM evented
          GROUP BY evented.flower_room, evented.event_no
        ), cycled AS (
         SELECT p.flower_room,
            p.event_no,
            p.pull_start,
            p.pull_end,
            p.days_recording,
            lag(p.pull_start) OVER (PARTITION BY p.flower_room ORDER BY p.pull_start) AS previous_pull_start,
            p.pull_start - lag(p.pull_start) OVER (PARTITION BY p.flower_room ORDER BY p.pull_start) AS cycle_days
           FROM pulls p
        )
 SELECT flower_room,
    'Cultivation'::text AS department,
    event_no,
    pull_start,
    pull_end,
    days_recording,
    previous_pull_start,
    cycle_days,
    f_rule('room_cycle_days'::text)::integer AS target_days,
        CASE
            WHEN cycle_days IS NULL THEN NULL::integer
            ELSE cycle_days - f_rule('room_cycle_days'::text)::integer
        END AS variance_days,
        CASE
            WHEN cycle_days IS NULL THEN 'FIRST PULL ON RECORD — no previous cycle to measure'::text
            WHEN cycle_days <= f_rule('room_cycle_days'::text)::integer THEN 'ON TARGET'::text
            ELSE ('OVER BY '::text || ((cycle_days - f_rule('room_cycle_days'::text)::integer)::text)) || ' DAYS'::text
        END AS cycle_status,
    cycle_days IS NOT NULL AND cycle_days > f_rule('room_cycle_days'::text)::integer AS breaches_rule,
        CASE
            WHEN cycle_days IS NULL THEN 'no previous pull in Metrc for this room'::text
            ELSE ((((((previous_pull_start::text || ' → '::text) || pull_start::text) || ' = '::text) || cycle_days::text) || ' days against a '::text) || f_rule('room_cycle_days'::text)::integer::text) || '-day rule'::text
        END AS the_arithmetic
   FROM cycled c;
create or replace view public.v_harvest_enforcement as
 SELECT pull_no,
    harvest_date,
    flower_room,
    room_cycle_no,
    room_cycle_days,
    facility_days_since_last_pull AS facility_gap_days,
        CASE
            WHEN harvest_date < CURRENT_DATE THEN 'past'::text
            WHEN harvest_date <= (CURRENT_DATE + f_rule('pull_interval_days'::text)::integer) THEN 'upcoming'::text
            ELSE 'scheduled'::text
        END AS horizon,
    room_cycle_days IS NOT NULL AND room_cycle_days <> f_rule('room_cycle_days'::text) AS cycle_violation,
    facility_days_since_last_pull IS NOT NULL AND (facility_days_since_last_pull < (f_rule('pull_interval_days'::text) - COALESCE(f_rule('weekend_pull_shift_days'::text), 2::numeric)) OR facility_days_since_last_pull > (f_rule('pull_interval_days'::text) + COALESCE(f_rule('weekend_pull_shift_days'::text), 2::numeric))) AS cadence_violation,
    (EXISTS ( SELECT 1
           FROM harvest_weights w
          WHERE w.harvest_date = p.harvest_date AND w.flower_room = p.flower_room)) AS weights_reported,
    harvest_date < CURRENT_DATE AND NOT (EXISTS ( SELECT 1
           FROM harvest_weights w
          WHERE w.harvest_date = p.harvest_date AND w.flower_room = p.flower_room)) AS overdue_reporting,
    (EXISTS ( SELECT 1
           FROM harvest_pulls p2
          WHERE p2.harvest_date = p.harvest_date AND p2.id <> p.id)) AS same_day_overlap,
    day2_replant_date,
    dry_start,
    dry_day_14,
    cultivars
   FROM harvest_pulls p
  ORDER BY harvest_date;
create or replace view public.v_harvest_mass_balance as
 SELECT harvest_date,
    flower_room,
    cultivar,
    actual_wet_lb,
    actual_dry_input_lb,
    grade_a_lb,
    grade_b_lb,
    grade_c_smalls_lb,
    trim_lb,
    fresh_frozen_dry_eq_lb,
    extraction_only_lb,
    samples_retain_lb,
    waste_destruction_lb,
    round(COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric) + COALESCE(waste_destruction_lb, 0::numeric), 3) AS total_accounted_lb,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(actual_dry_input_lb - (COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric) + COALESCE(waste_destruction_lb, 0::numeric)), 3)
            ELSE NULL::numeric
        END AS unaccounted_variance_lb,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * (COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric) + COALESCE(waste_destruction_lb, 0::numeric)) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS mass_balance_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * (COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric)) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS saleable_yield_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(grade_a_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS grade_a_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(grade_b_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS grade_b_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(grade_c_smalls_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS grade_c_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(trim_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS trim_pct,
        CASE
            WHEN COALESCE(canopy_sqft, 0::numeric) > 0::numeric AND COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(actual_dry_input_lb * 453.592 / canopy_sqft, 1)
            ELSE NULL::numeric
        END AS actual_g_sqft,
    metrc_harvest_batch,
    qa_release_status,
    status,
    entered_by,
    verified_by,
    verified_date
   FROM harvest_weights
  ORDER BY harvest_date DESC;
create or replace view public.v_harvest_pull_link as
 WITH h AS (
         SELECT mh.id,
            mh.name,
            mh.harvest_start,
            mh.wet_weight,
            mh.waste_weight,
            mh.package_count,
            "substring"(mh.name, '(\d{8})'::text) AS name_date_token,
            mh.flower_room AS room_actual,
            f_harvest_is_fresh_frozen(mh.name) AS is_fresh_frozen
           FROM metrc_harvests mh
        )
 SELECT h.id AS harvest_id,
    h.name AS harvest_name,
    h.harvest_start AS takedown_date,
    h.room_actual,
    p.flower_room AS room_planned,
    h.is_fresh_frozen,
    p.pull_no,
    p.harvest_date AS pull_planned_date,
    h.harvest_start - p.harvest_date AS days_from_planned_pull,
    p.planned_plants,
    p.projected_flower_after_ff_lb,
    h.wet_weight,
    h.package_count,
        CASE
            WHEN p.pull_no IS NOT NULL AND h.room_actual IS NULL THEN 'Linked on date. Room unknown - the name carries no room, which is true of all 2024 harvests, before the naming convention existed.'::text
            WHEN p.pull_no IS NOT NULL AND h.room_actual IS DISTINCT FROM p.flower_room THEN ((('Linked on date. ROOM DRIFTED - the plan expected '::text || p.flower_room) || ', the harvest came out of '::text) || h.room_actual) || '. This link is by DATE ONLY and is therefore not evidence of adherence; v_schedule_compliance keys on the room and is the answer for that.'::text
            WHEN p.pull_no IS NOT NULL THEN 'Linked on date, and the room agrees with the plan.'::text
            WHEN h.harvest_start < '2026-01-01'::date THEN 'Not linked - harvest_plan_2026 covers 2026 only. This harvest predates the plan and no pull exists to attach it to.'::text
            WHEN h.harvest_start > (( SELECT max(harvest_plan_2026.harvest_date) AS max
               FROM harvest_plan_2026)) THEN 'Not linked - takedown is after the last planned pull of 2026.'::text
            ELSE ('NOT LINKED - no planned pull within the '::text || COALESCE(f_rule('pull_link_window_days'::text)::text, '?'::text)) || '-day matching window. Investigate: either a pull happened off-calendar, or the takedown date is wrong.'::text
        END AS link_note,
        CASE
            WHEN h.name_date_token IS NULL THEN 'Name carries no readable 8-digit date'::text
            WHEN to_date(h.name_date_token, 'YYYYMMDD'::text) <> h.harvest_start THEN ((('Name says '::text || h.name_date_token) || ', Metrc says '::text) || h.harvest_start) || ' - Metrc wins'::text
            ELSE NULL::text
        END AS name_date_disagreement
   FROM h
     LEFT JOIN LATERAL ( SELECT p2.pull_no,
            p2.harvest_date,
            p2.flower_room,
            p2.planned_plants,
            p2.projected_flower_after_ff_lb
           FROM harvest_plan_2026 p2
          WHERE abs(h.harvest_start - p2.harvest_date)::numeric <= COALESCE(f_rule('pull_link_window_days'::text), 7::numeric)
          ORDER BY (abs(h.harvest_start - p2.harvest_date)), p2.pull_no
         LIMIT 1) p ON true;
create or replace view public.v_harvest_reconciliation as
 WITH plan AS (
         SELECT harvest_schedule.harvest_date,
            harvest_schedule.flower_room,
            count(*) AS planned_cultivars,
            sum(harvest_schedule.plants) AS planned_plants,
            round(sum(harvest_schedule.projected_weight_lbs), 1) AS planned_lbs,
            round(sum(harvest_schedule.fresh_frozen_lbs), 1) AS planned_ff_lbs
           FROM harvest_schedule
          GROUP BY harvest_schedule.harvest_date, harvest_schedule.flower_room
        ), actual AS (
         SELECT metrc_harvests.harvest_start AS harvest_date,
            count(*) AS metrc_harvests,
            round(sum(metrc_harvests.wet_weight) / 453.592, 1) AS metrc_wet_lbs,
            round(sum(metrc_harvests.waste_weight) / 453.592, 1) AS metrc_waste_lbs,
            sum(metrc_harvests.package_count) AS metrc_packages,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS metrc_packaged_lbs,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalRestoredWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS metrc_restored_lbs
           FROM metrc_harvests
          GROUP BY metrc_harvests.harvest_start
        )
 SELECT COALESCE(p.harvest_date, a.harvest_date) AS harvest_date,
    p.flower_room,
    p.planned_cultivars,
    p.planned_plants,
    p.planned_lbs,
    p.planned_ff_lbs,
    a.metrc_harvests,
    a.metrc_wet_lbs,
    a.metrc_waste_lbs,
    a.metrc_packaged_lbs,
    a.metrc_packages,
        CASE
            WHEN p.harvest_date IS NOT NULL AND a.harvest_date IS NULL AND p.harvest_date < CURRENT_DATE THEN 'MISSING IN METRC'::text
            WHEN p.harvest_date IS NOT NULL AND a.harvest_date IS NULL THEN 'SCHEDULED'::text
            WHEN p.harvest_date IS NULL THEN 'IN METRC, NOT PLANNED'::text
            WHEN a.metrc_wet_lbs IS NOT NULL AND p.planned_lbs > 0::numeric THEN ('RECONCILED '::text || round(100.0 * a.metrc_wet_lbs / p.planned_lbs)) || '% of plan'::text
            ELSE 'RECONCILED'::text
        END AS reconciliation,
        CASE
            WHEN a.metrc_wet_lbs IS NOT NULL AND p.planned_lbs > 0::numeric THEN round(a.metrc_wet_lbs - p.planned_lbs, 1)
            ELSE NULL::numeric
        END AS variance_lbs
   FROM plan p
     FULL JOIN actual a ON a.harvest_date = p.harvest_date
  ORDER BY (COALESCE(p.harvest_date, a.harvest_date)) DESC;
create or replace view public.v_harvest_report as
 SELECT name AS harvest,
    harvest_start AS cut_date,
    flower_room AS room,
    COALESCE(NULLIF(raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
    (raw ->> 'PlantCount'::text)::integer AS plants,
    round(wet_weight / 453.592, 1) AS wet_lb,
    round(((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592, 1) AS packaged_lb,
    round(((raw ->> 'TotalPackagedWeight'::text)::numeric) / NULLIF((raw ->> 'PlantCount'::text)::integer, 0)::numeric, 1) AS grams_per_plant,
    f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone) AS goal_lb,
    round(((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592 - f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone), 1) AS vs_goal_lb,
        CASE
            WHEN (raw ->> 'FinishedDate'::text) IS NULL THEN 'STILL OPEN — cannot be judged yet'::text
            WHEN f_harvest_is_fresh_frozen(name) OR COALESCE(raw ->> 'DryingLocationName'::text, ''::text) ~~* '%freezer%'::text THEN 'Fresh frozen — not judged against the dried flower goal'::text
            WHEN (((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592) >= f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone) THEN 'MET the goal'::text
            ELSE ('SHORT by '::text || round(f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone) - ((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592, 1)) || ' lb'::text
        END AS verdict,
    (raw ->> 'FinishedDate'::text)::date AS closed_on,
    COALESCE(raw ->> 'DryingLocationName'::text, '(not recorded)'::text) AS dried_in
   FROM metrc_harvests h
  WHERE wet_weight > 0::numeric;
create or replace view public.v_harvest_stage_map as
 SELECT license,
    harvest,
    harvest_type,
    room,
    sub_room,
    strains,
    plants,
    harvest_start,
    finished_on,
    stage,
    days_since_takedown,
    wet_weight,
    current_weight,
    waste_weight,
    packaged_weight,
    restored_weight,
    waste_pct,
    yield_pct,
    uom,
    packages_created,
    lab_state,
    packages_traced,
    source_state,
    f_stock_status(source_state, NULL::boolean) AS stock_status
   FROM ( SELECT h.license,
            h.name AS harvest,
            h.raw ->> 'HarvestType'::text AS harvest_type,
            h.raw ->> 'DryingLocationName'::text AS room,
            h.raw ->> 'DryingSublocationName'::text AS sub_room,
            h.raw ->> 'SourceStrainNames'::text AS strains,
            (h.raw ->> 'PlantCount'::text)::numeric AS plants,
            h.harvest_start,
            (h.raw ->> 'FinishedDate'::text)::date AS finished_on,
                CASE
                    WHEN (h.raw ->> 'ArchivedDate'::text) IS NOT NULL THEN 'Archived'::text
                    WHEN (h.raw ->> 'IsOnHold'::text)::boolean THEN 'ON HOLD'::text
                    WHEN (h.raw ->> 'IsOnInvestigation'::text)::boolean THEN 'UNDER INVESTIGATION'::text
                    WHEN (h.raw ->> 'FinishedDate'::text) IS NOT NULL THEN 'Finished'::text
                    WHEN COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) > 0::numeric THEN 'Packaging'::text
                    WHEN h.harvest_start IS NOT NULL AND h.harvest_start > (CURRENT_DATE - 10) THEN ('Drying (day '::text || ((CURRENT_DATE - h.harvest_start)::text)) || ' of 10-14)'::text
                    WHEN h.harvest_start IS NOT NULL THEN 'Curing / Trim'::text
                    ELSE 'Recorded'::text
                END AS stage,
                CASE
                    WHEN h.harvest_start IS NOT NULL THEN CURRENT_DATE - h.harvest_start
                    ELSE NULL::integer
                END AS days_since_takedown,
            (h.raw ->> 'TotalWetWeight'::text)::numeric AS wet_weight,
            (h.raw ->> 'CurrentWeight'::text)::numeric AS current_weight,
            (h.raw ->> 'TotalWasteWeight'::text)::numeric AS waste_weight,
            (h.raw ->> 'TotalPackagedWeight'::text)::numeric AS packaged_weight,
            (h.raw ->> 'TotalRestoredWeight'::text)::numeric AS restored_weight,
                CASE
                    WHEN COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric), 1)
                    ELSE NULL::numeric
                END AS waste_pct,
                CASE
                    WHEN COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric), 1)
                    ELSE NULL::numeric
                END AS yield_pct,
            h.raw ->> 'UnitOfWeightName'::text AS uom,
            (h.raw ->> 'PackageCount'::text)::numeric AS packages_created,
            h.raw ->> 'LabTestingState'::text AS lab_state,
            ( SELECT count(*) AS count
                   FROM metrc_packages p
                  WHERE p.license = h.license AND (p.raw ->> 'SourceHarvestNames'::text) ~~ (('%'::text || h.name) || '%'::text)) AS packages_traced,
            h.source_state
           FROM metrc_harvests h) q;
create or replace view public.v_harvest_takedown as
 WITH gap AS (
         SELECT COALESCE(( SELECT harvest_alert_rules.threshold
                   FROM harvest_alert_rules
                  WHERE harvest_alert_rules.rule_key = 'takedown_cluster_gap_days'::text AND harvest_alert_rules.active), 7::numeric)::integer AS d
        ), floor_plants AS (
         SELECT COALESCE(( SELECT harvest_alert_rules.threshold
                   FROM harvest_alert_rules
                  WHERE harvest_alert_rules.rule_key = 'takedown_min_plants'::text AND harvest_alert_rules.active), 100::numeric) AS p
        ), dates AS (
         SELECT DISTINCT metrc_harvests.flower_room,
            metrc_harvests.harvest_start
           FROM metrc_harvests
          WHERE metrc_harvests.flower_room IS NOT NULL AND metrc_harvests.harvest_start IS NOT NULL
        ), edges AS (
         SELECT d.flower_room,
            d.harvest_start,
                CASE
                    WHEN (d.harvest_start - lag(d.harvest_start) OVER (PARTITION BY d.flower_room ORDER BY d.harvest_start)) <= (( SELECT gap.d
                       FROM gap)) THEN 0
                    ELSE 1
                END AS is_new_event
           FROM dates d
        ), grouped AS (
         SELECT edges.flower_room,
            edges.harvest_start,
            sum(edges.is_new_event) OVER (PARTITION BY edges.flower_room ORDER BY edges.harvest_start) AS event_no
           FROM edges
        ), ev AS (
         SELECT grouped.flower_room,
            min(grouped.harvest_start) AS takedown_start,
            max(grouped.harvest_start) AS takedown_end
           FROM grouped
          GROUP BY grouped.flower_room, grouped.event_no
        )
 SELECT ev.flower_room,
    row_number() OVER (PARTITION BY ev.flower_room ORDER BY ev.takedown_start) AS takedown_seq_all_time,
    ev.takedown_start,
    ev.takedown_end,
    ev.takedown_end - ev.takedown_start + 1 AS takedown_days,
    count(h.id) AS harvest_records,
    count(h.id) FILTER (WHERE f_harvest_is_fresh_frozen(h.name)) AS fresh_frozen_records,
    round(sum(COALESCE(h.wet_weight, 0::numeric)) / 453.592, 1) AS wet_lb,
    string_agg(DISTINCT h.name, ', '::text) AS harvests,
    COALESCE(sum((h.raw ->> 'PlantCount'::text)::numeric), 0::numeric) AS plants,
    COALESCE(sum((h.raw ->> 'PlantCount'::text)::numeric), 0::numeric) >= (( SELECT floor_plants.p
           FROM floor_plants)) AS is_material
   FROM ev
     JOIN metrc_harvests h ON h.flower_room = ev.flower_room AND h.harvest_start >= ev.takedown_start AND h.harvest_start <= ev.takedown_end
  GROUP BY ev.flower_room, ev.takedown_start, ev.takedown_end;
create or replace view public.v_harvest_water_and_yield as
 SELECT m.harvest_batch AS harvest,
    m.strain,
    m.room,
    m.finished_on,
    m.licence,
    m.plants,
    round(m.wet_lb, 1) AS wet_in_lb,
    round(m.waste_lb, 1) AS waste_lb,
    round(m.moisture_loss_lb, 1) AS water_lost_lb,
    round(m.packaged_lb, 1) AS dry_yield_lb,
    round(m.moisture_pct, 1) AS water_pct,
    round(m.wet_lb - COALESCE(m.waste_lb, 0::numeric) - COALESCE(m.moisture_loss_lb, 0::numeric) - COALESCE(m.packaged_lb, 0::numeric), 2) AS balance_lb,
        CASE
            WHEN abs(m.wet_lb - COALESCE(m.waste_lb, 0::numeric) - COALESCE(m.moisture_loss_lb, 0::numeric) - COALESCE(m.packaged_lb, 0::numeric)) <= 0.5 THEN 'balances'::text
            ELSE 'DOES NOT BALANCE'::text
        END AS balance_check,
        CASE
            WHEN COALESCE(m.plants, 0::numeric) > 0::numeric THEN round(m.packaged_lb * 453.592 / m.plants, 1)
            ELSE NULL::numeric
        END AS dry_g_per_plant,
        CASE
            WHEN COALESCE(m.plants, 0::numeric) = 0::numeric THEN 'no plant count - yield cannot be judged'::text
            WHEN (m.packaged_lb * 453.592 / m.plants) >= 70.6 THEN 'at or above the 70.6 g target'::text
            WHEN (m.packaged_lb * 453.592 / m.plants) >= 50::numeric THEN 'below target but plausible'::text
            WHEN (m.packaged_lb * 453.592 / m.plants) >= 25::numeric THEN 'HALF TARGET OR WORSE'::text
            ELSE 'UNDER 25 g PER PLANT - unaccounted'::text
        END AS yield_verdict,
        CASE
            WHEN COALESCE(m.moisture_loss_lb, 0::numeric) = 0::numeric THEN 'fresh frozen - packaged wet, never dried, so zero water is CORRECT'::text
            ELSE 'dried'::text
        END AS drying_kind,
    (((((((((((m.harvest_batch || ': '::text) || round(m.wet_lb, 1)) || ' lb in wet. '::text) || round(COALESCE(m.waste_lb, 0::numeric), 1)) || ' lb waste, '::text) || round(COALESCE(m.moisture_loss_lb, 0::numeric), 1)) || ' lb water evaporated, '::text) || round(COALESCE(m.packaged_lb, 0::numeric), 1)) || ' lb packaged dry'::text) ||
        CASE
            WHEN COALESCE(m.plants, 0::numeric) > 0::numeric THEN (((' from '::text || m.plants) || ' plants = '::text) || round(m.packaged_lb * 453.592 / m.plants, 1)) || ' g per plant'::text
            ELSE ''::text
        END) || '. '::text) ||
        CASE
            WHEN abs(m.wet_lb - COALESCE(m.waste_lb, 0::numeric) - COALESCE(m.moisture_loss_lb, 0::numeric) - COALESCE(m.packaged_lb, 0::numeric)) <= 0.5 THEN 'Every pound accounted for.'::text
            ELSE ('WARNING: '::text || round(abs(m.wet_lb - COALESCE(m.waste_lb, 0::numeric) - COALESCE(m.moisture_loss_lb, 0::numeric) - COALESCE(m.packaged_lb, 0::numeric)), 1)) || ' lb unaccounted.'::text
        END AS in_plain_english,
    'CLOSED'::text AS harvest_state,
    NULL::numeric AS still_on_harvest_lb,
    'Metrc Harvests-Inactive report - the only source of moisture loss'::text AS measured_from
   FROM metrc_rpt_harvest_moisture m
UNION ALL
 SELECT h.name AS harvest,
    NULLIF(h.raw ->> 'SourceStrainNames'::text, ''::text) AS strain,
    h.raw ->> 'DryingLocationName'::text AS room,
    NULL::date AS finished_on,
    h.license AS licence,
    (h.raw ->> 'PlantCount'::text)::numeric AS plants,
    round(((h.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592, 1) AS wet_in_lb,
    round(((h.raw ->> 'TotalWasteWeight'::text)::numeric) / 453.592, 1) AS waste_lb,
    NULL::numeric AS water_lost_lb,
    round(((h.raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592, 1) AS dry_yield_lb,
    NULL::numeric AS water_pct,
    NULL::numeric AS balance_lb,
    'still open - cannot balance until the harvest is finished'::text AS balance_check,
        CASE
            WHEN COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric) > 0::numeric THEN round(((h.raw ->> 'TotalPackagedWeight'::text)::numeric) / ((h.raw ->> 'PlantCount'::text)::numeric), 1)
            ELSE NULL::numeric
        END AS dry_g_per_plant,
    'still open - yield is not final'::text AS yield_verdict,
    'still drying - moisture is only recorded when the harvest is finished'::text AS drying_kind,
    ((((((((((h.name || ': '::text) || round(((h.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592, 1)) || ' lb in wet, harvest STILL OPEN. '::text) || round(((h.raw ->> 'TotalWasteWeight'::text)::numeric) / 453.592, 1)) || ' lb waste and '::text) || round(((h.raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592, 1)) || ' lb packaged so far, with '::text) || round(((h.raw ->> 'CurrentWeight'::text)::numeric) / 453.592, 1)) || ' lb still on the harvest. That remaining weight is material still drying, NOT a '::text) || 'measured water loss - Metrc only records moisture when the harvest is finished, so '::text) || 'the water column is deliberately blank rather than zero.'::text AS in_plain_english,
    'OPEN'::text AS harvest_state,
    round(((h.raw ->> 'CurrentWeight'::text)::numeric) / 453.592, 1) AS still_on_harvest_lb,
    'Metrc API - the moisture report only covers finished harvests'::text AS measured_from
   FROM metrc_harvests h
  WHERE NOT (EXISTS ( SELECT 1
           FROM metrc_rpt_harvest_moisture m2
          WHERE m2.harvest_batch = h.name));
create or replace view public.v_house_rules as
 SELECT 'OWNER RULING'::text AS source,
    cf.key AS rule_key,
    cf.label AS rule,
    cf.what_it_means,
    NULL::text AS never_do_this,
    cf.where_it_came_from AS authority,
    COALESCE(cf.evidence_status, 'set'::text) AS standing
   FROM conversion_factors cf
  WHERE cf.unit = 'rule'::text
UNION ALL
 SELECT '280E DOCTRINE'::text AS source,
    d.rule_key,
    d.headline AS rule,
    (d.the_rule || '

AGENTS MUST: '::text) || COALESCE(d.agents_must, '—'::text) AS what_it_means,
    d.agents_must_never AS never_do_this,
    d.authority,
    COALESCE(d.authority_status, 'binding'::text) AS standing
   FROM tax_280e_doctrine d
UNION ALL
 SELECT 'AUDIT ASSERTION'::text AS source,
    a.assertion AS rule_key,
    a.assertion AS rule,
    a.plain_english AS what_it_means,
    a.what_failure_looks_like_here AS never_do_this,
    'Audit assertions framework — '::text || COALESCE(a.who_cares, ''::text) AS authority,
        CASE
            WHEN a.no_materiality_floor THEN 'binding — NO materiality floor'::text
            ELSE 'binding'::text
        END AS standing
   FROM audit_assertion a
UNION ALL
 SELECT 'DISAGREEMENT CLASS'::text AS source,
    c.class_key AS rule_key,
    c.headline AS rule,
    (((c.what_it_looks_like || '

FIRST QUESTION: '::text) || COALESCE(c.first_question, '—'::text)) || '
CORRECT FIX: '::text) || COALESCE(c.correct_fix, '—'::text) AS what_it_means,
    c.the_wrong_fix AS never_do_this,
    'Disagreement triage taxonomy'::text AS authority,
    'binding'::text AS standing
   FROM disagreement_class c
UNION ALL
 SELECT 'ROOT CAUSE — NEVER REPEAT'::text AS source,
    r.pattern_key AS rule_key,
    r.the_symptom AS rule,
    r.the_root_cause AS what_it_means,
    r.why_it_happened AS never_do_this,
    COALESCE(r.guard_that_prevents_recurrence, 'NO GUARD YET'::text) AS authority,
    COALESCE(r.status, 'open'::text) AS standing
   FROM root_cause_ledger r;
create or replace view public.v_hr_activity as
 SELECT 'punch_in'::text AS kind,
    t.clock_in AS at,
    t.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    ('Clocked in via '::text || COALESCE(t.source, 'unknown'::text)) ||
        CASE
            WHEN COALESCE(t.late_minutes, 0) > 0 THEN (' — '::text || t.late_minutes) || ' min late'::text
            ELSE ''::text
        END AS detail,
        CASE
            WHEN COALESCE(t.late_minutes, 0) > 0 THEN 'warn'::text
            ELSE 'ok'::text
        END AS tone,
    t.id::text AS ref
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE t.clock_in IS NOT NULL
UNION ALL
 SELECT 'punch_out'::text AS kind,
    t.clock_out AS at,
    t.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    ('Clocked out — '::text || round(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0, 2)) || ' h worked'::text AS detail,
    'ok'::text AS tone,
    t.id::text AS ref
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE t.clock_out IS NOT NULL
UNION ALL
 SELECT 'callout'::text AS kind,
    c.called_at AS at,
    c.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    ('Called out — '::text || c.reason_code) ||
        CASE
            WHEN c.meets_notice THEN ' (proper notice)'::text
            ELSE ' (short notice)'::text
        END AS detail,
        CASE
            WHEN c.meets_notice THEN 'warn'::text
            ELSE 'bad'::text
        END AS tone,
    c.id::text AS ref
   FROM callouts c
     JOIN employees e ON e.id = c.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
UNION ALL
 SELECT 'occurrence'::text AS kind,
    o.created_at AS at,
    o.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    (((o.kind || ' — '::text) || o.points) || ' points'::text) || COALESCE(' · '::text || o.reason_code, ''::text) AS detail,
    'bad'::text AS tone,
    o.id::text AS ref
   FROM attendance_occurrences o
     JOIN employees e ON e.id = o.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
UNION ALL
 SELECT 'claim'::text AS kind,
    sc.claimed_at AS at,
    sc.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    'Claimed an open shift'::text ||
        CASE
            WHEN sc.would_be_overtime THEN ' — would be overtime'::text
            ELSE ''::text
        END AS detail,
        CASE
            WHEN sc.would_be_overtime THEN 'warn'::text
            ELSE 'ok'::text
        END AS tone,
    sc.id::text AS ref
   FROM shift_claims sc
     JOIN employees e ON e.id = sc.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
UNION ALL
 SELECT 'schedule_posted'::text AS kind,
    sd.posted_at AS at,
    NULL::uuid AS employee_id,
    COALESCE(u.email, 'a manager'::character varying) AS full_name,
    COALESCE(dd.name, 'All'::text) AS department,
    ((((('Posted '::text || sd.title) || ' ('::text) || sd.covers_from) || ' to '::text) || sd.covers_to) || ')'::text AS detail,
    'ok'::text AS tone,
    sd.id::text AS ref
   FROM schedule_drafts sd
     LEFT JOIN departments dd ON dd.id = sd.department_id
     LEFT JOIN auth.users u ON u.id = sd.posted_by
  WHERE sd.posted_at IS NOT NULL
UNION ALL
 SELECT 'document_signed'::text AS kind,
    a.signed_at AS at,
    a.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    (('Signed '::text || doc.title) || ' v'::text) || a.document_version AS detail,
    'ok'::text AS tone,
    a.id::text AS ref
   FROM hr_document_acknowledgements a
     JOIN employees e ON e.id = a.employee_id
     JOIN hr_documents doc ON doc.id = a.document_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE a.signed_at IS NOT NULL
UNION ALL
 SELECT 'incident'::text AS kind,
    i.reported_at AS at,
    i.involved_employee AS employee_id,
    COALESCE(e.full_name, '—'::text) AS full_name,
    '—'::text AS department,
    ((upper(i.kind) || ' — '::text) || i.severity) ||
        CASE
            WHEN i.osha_recordable THEN ' · OSHA recordable'::text
            ELSE ''::text
        END AS detail,
        CASE
            WHEN i.severity = ANY (ARRAY['high'::text, 'critical'::text]) THEN 'bad'::text
            ELSE 'warn'::text
        END AS tone,
    i.id::text AS ref
   FROM hr_incidents i
     LEFT JOIN employees e ON e.id = i.involved_employee;
create or replace view public.v_hr_delivery_backlog as
 SELECT 'message'::text AS what,
    m.id::text AS id,
    m.subject AS title,
    m.approved_at,
    NULL::text AS error,
        CASE
            WHEN m.employee_id IS NULL THEN 'waiting: audience delivery not built'::text
            ELSE 'waiting to send'::text
        END AS standing
   FROM hr_message m
  WHERE m.approved_at IS NOT NULL AND m.sent_at IS NULL AND m.cancelled_at IS NULL
UNION ALL
 SELECT 'workspace task'::text AS what,
    t.id::text AS id,
    t.title,
    t.created_at AS approved_at,
    t.error,
        CASE t.status
            WHEN 'failed'::text THEN 'failed - '::text || COALESCE(t.error, 'no reason recorded'::text)
            ELSE 'waiting to push'::text
        END AS standing
   FROM hr_external_task t
  WHERE t.status = ANY (ARRAY['pending'::text, 'failed'::text])
  ORDER BY 4;
create or replace view public.v_hr_delivery_open as
 SELECT m.id,
    m.kind,
    m.subject,
    m.audience,
    m.approved_at,
    COALESCE(e.full_name, m.audience, 'unspecified'::text) AS intended,
    ( SELECT count(*) AS count
           FROM hr_message_recipient r
          WHERE r.message_id = m.id) AS recipients,
    ( SELECT count(*) AS count
           FROM hr_message_recipient r
          WHERE r.message_id = m.id AND r.delivered_at IS NOT NULL) AS delivered,
    ( SELECT count(*) AS count
           FROM hr_message_recipient r
          WHERE r.message_id = m.id AND r.read_at IS NOT NULL) AS read_count,
        CASE
            WHEN m.sent_at IS NOT NULL THEN 'sent'::text
            WHEN m.approved_at IS NULL THEN 'awaiting approval'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM f_resolve_audience(m.audience, m.employee_id) f_resolve_audience(f_resolve_audience))) THEN 'AUDIENCE MATCHES NOBODY'::text
            ELSE 'approved, waiting to send'::text
        END AS state
   FROM hr_message m
     LEFT JOIN employees e ON e.id = m.employee_id
  WHERE m.cancelled_at IS NULL;
create or replace view public.v_hr_document_standing as
 SELECT d.id AS document_id,
    d.title,
    d.kind,
    d.version,
    d.requires_signature,
    a.employee_id,
    a.due_on,
    ack.signed_at IS NOT NULL AS signed,
    ack.signed_at,
    ( SELECT count(*) AS count
           FROM hr_document_sections s
          WHERE s.document_id = d.id) AS sections,
    ( SELECT count(DISTINCT p.section_id) AS count
           FROM hr_document_progress p
          WHERE p.document_id = d.id AND p.employee_id = a.employee_id) AS sections_read,
        CASE
            WHEN ack.signed_at IS NOT NULL THEN 'done'::text
            WHEN a.due_on IS NOT NULL AND a.due_on < CURRENT_DATE THEN 'overdue'::text
            WHEN (( SELECT count(DISTINCT p.section_id) AS count
               FROM hr_document_progress p
              WHERE p.document_id = d.id AND p.employee_id = a.employee_id)) = 0 THEN 'not started'::text
            ELSE 'in progress'::text
        END AS standing
   FROM hr_documents d
     JOIN hr_document_assignments a ON a.document_id = d.id
     LEFT JOIN hr_document_acknowledgements ack ON ack.document_id = d.id AND ack.employee_id = a.employee_id AND ack.document_version = d.version
  WHERE d.retired_at IS NULL;
create or replace view public.v_hr_waiting_on_a_person as
 SELECT id,
    created_at,
    agent,
    kind,
    severity,
    agent_confidence,
    employee_id,
    headline,
    policy_basis,
    draft_body IS NOT NULL AS has_a_draft,
    defer_until,
        CASE
            WHEN severity = 'urgent'::text THEN 'Decide today'::text
            WHEN kind ~~* '%write%up%'::text OR kind ~~* '%discipl%'::text THEN 'Read every line - this becomes part of an employment record'::text
            WHEN agent_confidence = 'unsure'::text THEN 'The agent is not sure. Check it before approving.'::text
            ELSE 'Routine - but still a decision'::text
        END AS how_to_treat_it
   FROM hr_review_queue q
  WHERE status = 'waiting'::text AND (defer_until IS NULL OR defer_until <= now())
  ORDER BY (
        CASE severity
            WHEN 'urgent'::text THEN 0
            WHEN 'elevated'::text THEN 1
            ELSE 2
        END), (
        CASE
            WHEN agent_confidence = 'unsure'::text THEN 0
            ELSE 1
        END), created_at;
create or replace view public.v_import_outliers as
 WITH tot AS (
         SELECT 'wholesale_transfers'::text AS report,
            sum(metrc_rpt_wholesale.amount) AS total,
            count(*) AS rows
           FROM metrc_rpt_wholesale
          WHERE NOT metrc_rpt_wholesale.voided
        UNION ALL
         SELECT 'packages_transferred'::text,
            sum(metrc_rpt_package_transfers.shipper_wholesale_price) AS sum,
            count(*) AS count
           FROM metrc_rpt_package_transfers
          WHERE metrc_rpt_package_transfers.shipper_wholesale_price IS NOT NULL
        )
 SELECT 'wholesale_transfers'::text AS report,
    w.manifest_number AS reference,
    w.item AS detail,
    w.amount AS value,
    t.total,
    round(100.0 * w.amount / NULLIF(t.total, 0::numeric), 2) AS pct_of_total,
    'A single line carrying more than a twentieth of the total is usually a report footer that '::text || 'was read as a transaction, not a real sale.'::text AS why_it_matters
   FROM metrc_rpt_wholesale w
     CROSS JOIN ( SELECT tot.total
           FROM tot
          WHERE tot.report = 'wholesale_transfers'::text) t
  WHERE NOT w.voided AND w.amount > (0.05 * t.total)
UNION ALL
 SELECT 'packages_transferred'::text AS report,
    p.manifest_number AS reference,
    p.item AS detail,
    p.shipper_wholesale_price AS value,
    t.total,
    round(100.0 * p.shipper_wholesale_price / NULLIF(t.total, 0::numeric), 2) AS pct_of_total,
    'A single package priced above a twentieth of all wholesale value needs a second look.'::text AS why_it_matters
   FROM metrc_rpt_package_transfers p
     CROSS JOIN ( SELECT tot.total
           FROM tot
          WHERE tot.report = 'packages_transferred'::text) t
  WHERE p.shipper_wholesale_price > (0.05 * t.total)
  ORDER BY 6 DESC;
create or replace view public.v_intelligence_briefing as
 WITH ranked AS (
         SELECT f.id,
            f.run_id,
            f.observed_at,
            f.fingerprint,
            f.severity,
            f.what,
            f.where_it_is,
            f.who_is_accountable,
            f.when_it_started,
            f.why_it_matters,
            f.how_it_was_detected,
            f.what_to_do,
            f.the_arithmetic,
            f.evidence,
            f.record_count,
            f.pounds,
            f.dollars,
            f.drill,
            f.search_text,
            row_number() OVER (PARTITION BY f.fingerprint ORDER BY f.observed_at DESC) AS rn,
            min(f.observed_at) OVER (PARTITION BY f.fingerprint)::date AS first_found_on,
            count(*) OVER (PARTITION BY f.fingerprint) AS times_found
           FROM watchdog_findings f
        )
 SELECT severity,
    what AS finding,
    where_it_is,
    who_is_accountable,
    when_it_started,
    why_it_matters,
    how_it_was_detected,
    what_to_do,
    the_arithmetic,
    record_count AS records_affected,
    pounds,
    dollars,
    drill,
    observed_at::date AS found_on,
    first_found_on,
    times_found,
    CURRENT_DATE - first_found_on AS days_open,
    NULLIF((regexp_match((((COALESCE(when_it_started, ''::text) || ' '::text) || COALESCE(what, ''::text)) || ' '::text) || COALESCE(the_arithmetic, ''::text), '(\d+)\s*days?'::text))[1], ''::text)::integer AS material_oldest_days,
        CASE
            WHEN times_found = 1 AND (CURRENT_DATE - first_found_on) = 0 THEN (('First sweep to record this finding was '::text || to_char(first_found_on::timestamp with time zone, 'DD Mon YYYY'::text)) || ', so there is no earlier history to compare against yet. The age shown is the age '::text) || 'of the material itself, not of the finding.'::text
            ELSE ((('Raised '::text || to_char(first_found_on::timestamp with time zone, 'DD Mon YYYY'::text)) || ' and confirmed on '::text) || times_found) || ' sweeps since.'::text
        END AS history_note,
    evidence
   FROM ranked
  WHERE rn = 1 AND observed_at > (now() - '48:00:00'::interval)
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), (COALESCE(dollars, 0::numeric)) DESC;
create or replace view public.v_inventory_alert_history as
 SELECT severity,
    area,
    headline,
    detail,
    pounds,
    dollars,
    raised,
    resolved,
    days_to_resolve,
    resolved_by,
    resolution_note,
    times_seen,
    raised AS raised_date
   FROM ( SELECT inventory_alerts.severity,
            inventory_alerts.area,
            inventory_alerts.headline,
            inventory_alerts.detail,
            inventory_alerts.pounds,
            inventory_alerts.dollars,
            inventory_alerts.first_raised::date AS raised,
            inventory_alerts.resolved_at::date AS resolved,
            inventory_alerts.resolved_at::date - inventory_alerts.first_raised::date AS days_to_resolve,
            COALESCE(inventory_alerts.resolved_by, 'still open'::text) AS resolved_by,
            inventory_alerts.resolution_note,
            inventory_alerts.times_seen
           FROM inventory_alerts
          ORDER BY inventory_alerts.first_raised DESC) q;
create or replace view public.v_inventory_alerts as
 SELECT severity,
    area,
    headline,
    detail,
    what_to_do,
    drill,
    pounds,
    dollars,
    days_open,
    times_seen,
    raised,
    material_oldest_days,
    raised AS raised_date
   FROM ( SELECT inventory_alerts.severity,
            inventory_alerts.area,
            inventory_alerts.headline,
            inventory_alerts.detail,
            inventory_alerts.what_to_do,
            inventory_alerts.drill,
            inventory_alerts.pounds,
            inventory_alerts.dollars,
            CURRENT_DATE - inventory_alerts.first_raised::date AS days_open,
            inventory_alerts.times_seen,
            inventory_alerts.first_raised::date AS raised,
            NULLIF((regexp_match((COALESCE(inventory_alerts.detail, ''::text) || ' '::text) || COALESCE(inventory_alerts.headline, ''::text), '(\d+)\s*days?'::text))[1], ''::text)::integer AS material_oldest_days
           FROM inventory_alerts
          WHERE inventory_alerts.resolved_at IS NULL
          ORDER BY (
                CASE inventory_alerts.severity
                    WHEN 'critical'::text THEN 1
                    WHEN 'elevated'::text THEN 2
                    ELSE 3
                END), (COALESCE(inventory_alerts.dollars, 0::numeric)) DESC) q;
create or replace view public.v_inventory_position_by_room as
 SELECT p.license AS licence,
    COALESCE(NULLIF(btrim(p.raw ->> 'LocationName'::text), ''::text), '(no room)'::text) AS room,
    r.role,
    r.stage,
    r.is_drying,
    r.confirmed_by IS NOT NULL AS room_role_confirmed,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    count(*) AS tags,
    round(sum(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))) FILTER (WHERE f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))), 1) AS lb,
    sum((p.raw ->> 'Quantity'::text)::numeric) FILTER (WHERE NOT f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))) AS units,
    count(*) FILTER (WHERE (p.raw ->> 'LabTestingState'::text) = 'TestPassed'::text) AS lab_passed,
    count(*) FILTER (WHERE NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL) AS tags_naming_a_harvest,
    count(*) FILTER (WHERE NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) IS NOT NULL AND NOT f_is_ours(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text)) AS tags_bought_in,
    min((p.raw ->> 'PackagedDate'::text)::date) AS oldest_tag,
    max((p.raw ->> 'PackagedDate'::text)::date) AS newest_tag
   FROM metrc_packages p
     LEFT JOIN room_roles r ON r.room_name = NULLIF(btrim(p.raw ->> 'LocationName'::text), ''::text)
  WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false
  GROUP BY p.license, (COALESCE(NULLIF(btrim(p.raw ->> 'LocationName'::text), ''::text), '(no room)'::text)), r.role, r.stage, r.is_drying, (r.confirmed_by IS NOT NULL), (COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text));
create or replace view public.v_inventory_reconciliation as
 WITH base AS (
         SELECT p.license,
            COALESCE(p.item_name, '(unnamed item)'::text) AS item,
            p.source_state,
            p.lab_testing_state,
            COALESCE(p.quantity, 0::numeric) AS qty,
            COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, COALESCE(p.quantity, 0::numeric)) AS initial_qty,
            (p.raw ->> 'IsOnHold'::text)::boolean AS on_hold,
            p.raw ->> 'ArchivedDate'::text AS archived
           FROM ( SELECT DISTINCT ON (d.tag) d.id,
                    d.license,
                    d.tag,
                    d.item_name,
                    d.quantity,
                    d.uom,
                    d.location,
                    d.packaged_on,
                    d.lab_testing_state,
                    d.finished,
                    d.raw,
                    d.synced_at,
                    d.source_state,
                    d.provenance,
                    d.report_as_of
                   FROM metrc_packages d
                  ORDER BY d.tag, (COALESCE(d.quantity, 0::numeric) > 0::numeric AND NOT COALESCE((d.raw ->> 'IsFinished'::text)::boolean, false)) DESC, (d.source_state = 'active'::text) DESC NULLS LAST, d.synced_at DESC NULLS LAST) p
        )
 SELECT license,
    item,
    round(sum(initial_qty), 1) AS packaged_originally,
    round(sum(qty) FILTER (WHERE source_state = 'active'::text AND NOT COALESCE(on_hold, false) AND lab_testing_state IS DISTINCT FROM 'TestFailed'::text), 1) AS in_stock_sellable,
    round(sum(qty) FILTER (WHERE (COALESCE(on_hold, false) OR source_state = 'onhold'::text) AND source_state <> 'inactive'::text AND source_state <> 'intransit'::text AND lab_testing_state IS DISTINCT FROM 'TestFailed'::text), 1) AS on_hold,
    round(sum(qty) FILTER (WHERE source_state = 'intransit'::text), 1) AS in_transit,
    round(sum(initial_qty) FILTER (WHERE source_state = 'inactive'::text), 1) AS closed_or_sold,
    round(sum(qty) FILTER (WHERE lab_testing_state = 'TestFailed'::text AND source_state <> 'inactive'::text AND source_state <> 'intransit'::text), 1) AS failed_testing_held,
    round(sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])), 1) AS reduced_without_reason,
        CASE
            WHEN sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])) > 0::numeric THEN ('UNACCOUNTED - '::text || round(sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])), 1)) || ' reduced with no recorded reason'::text
            WHEN sum(qty) FILTER (WHERE lab_testing_state = 'TestFailed'::text AND source_state <> 'inactive'::text AND source_state <> 'intransit'::text) > 0::numeric THEN 'FAILED TESTING still on hand - decide destruction or remediation'::text
            WHEN sum(qty) FILTER (WHERE COALESCE(on_hold, false)) > 0::numeric THEN 'Quantity on hold in Metrc'::text
            ELSE 'Reconciled'::text
        END AS reconciliation_status
   FROM base
  GROUP BY license, item
  ORDER BY (
        CASE
            WHEN sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])) > 0::numeric THEN 0
            ELSE 1
        END), (sum(qty) FILTER (WHERE source_state = 'active'::text)) DESC NULLS LAST;
create or replace view public.v_inventory_room_proof as
 WITH held AS (
         SELECT p.tag,
            p.license,
            NULLIF(btrim(p.raw ->> 'LocationName'::text), ''::text) AS room,
            NULLIF(btrim(p.raw ->> 'SublocationName'::text), ''::text) AS sublocation,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, p.raw ->> 'UnitOfMeasureAbbreviation'::text) AS lb,
            (p.raw ->> 'Quantity'::text)::numeric AS qty,
            p.raw ->> 'UnitOfMeasureAbbreviation'::text AS uom
           FROM metrc_packages p
          WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false
        ), shared_names AS (
         SELECT metrc_locations.name
           FROM metrc_locations
          GROUP BY metrc_locations.name
         HAVING count(DISTINCT metrc_locations.license) > 1
        )
 SELECT h.tag,
    h.room,
    h.sublocation,
    h.category,
    round(h.lb, 2) AS lb,
    h.qty,
    h.uom,
        CASE
            WHEN h.room IS NULL THEN 'FAILS J7 - NO ROOM RECORDED. We hold this and cannot say where it is. Massachusetts law requires Metrc to carry the current room for every tagged package, so this is a recording failure or unaccounted material.'::text
            WHEN loc.metrc_id IS NULL THEN ((('FAILS J7 - room "'::text || h.room) || '" is not listed in metrc_locations for licence '::text) || COALESCE(h.license, '?'::text)) || '. The package names a room Metrc does not hold under that licence, so its location cannot be confirmed against the state record.'::text
            WHEN sn.name IS NOT NULL THEN ((((((('ROOM CONFIRMED - '::text || h.room) || ', '::text) || COALESCE(initcap(cl.kind), h.license)) || ' department ('::text) || h.license) || '), Metrc id '::text) || loc.metrc_id) || '. THIS NAME EXISTS IN BOTH DEPARTMENTS and is two physically different rooms. Never show or total it without the department.'::text
            WHEN h.sublocation IS NULL THEN ((((((('ROOM CONFIRMED - '::text || h.room) || ', '::text) || COALESCE(initcap(cl.kind), h.license)) || ' department ('::text) || h.license) || '), Metrc id '::text) || loc.metrc_id) || '. No sublocation recorded: the room is known, the shelf is not. A physical count needs the shelf (A3).'::text
            ELSE 'PASSES J7 - room and shelf both confirmed against Metrc.'::text
        END AS room_proof,
    h.room IS NULL OR loc.metrc_id IS NULL AS fails_j7,
    sn.name IS NOT NULL AS ambiguous_room,
    h.license,
    (h.room || ' — '::text) || COALESCE(initcap(cl.kind), 'licence '::text || COALESCE(h.license, 'unknown'::text)) AS room_qualified,
    loc.metrc_id AS room_metrc_id,
    cl.kind AS department,
    cl.label AS licence_label
   FROM held h
     LEFT JOIN metrc_locations loc ON loc.name = h.room AND loc.license = h.license
     LEFT JOIN shared_names sn ON sn.name = h.room
     LEFT JOIN company_licenses cl ON cl.license = h.license;
create or replace view public.v_inventory_summary as
 SELECT c.sheet_name AS product_line,
    p.strain_flavor AS product,
    p.production_batch AS batch,
    p.size_g AS size,
    p.current_status,
    COALESCE(p.total_packaged, p.total_units, 0::numeric) AS ending_units,
    round(COALESCE(p.total_packaged, p.total_units, 0::numeric) / NULLIF(COALESCE(p.case_size, c.units_per_case), 0::numeric), 1) AS ending_cases,
        CASE
            WHEN COALESCE(p.total_packaged, p.total_units, 0::numeric) < c.threshold_units THEN 'LOW'::text
            ELSE NULL::text
        END AS low_flag,
        CASE
            WHEN p.expiration_date IS NOT NULL AND p.expiration_date < (CURRENT_DATE + 30) THEN 'EXP <30d'::text
            ELSE NULL::text
        END AS expiry_flag,
    round((COALESCE(p.total_bulk, 0::numeric) + COALESCE(p.total_filled, 0::numeric)) / NULLIF(c.units_per_case, 0::numeric), 1) AS possible_cases,
    p.expiration_date,
    p.category
   FROM product_inventory p
     JOIN inventory_config c ON p.category = ANY (c.categories);
create or replace view public.v_inventory_valuation as
 SELECT license,
    category,
    item,
    packages,
    quantity_estimate,
    uom,
    cost_per_unit,
    value_at_cost,
    basis,
    confidence
   FROM tg_inventory_as_of(CURRENT_DATE) tg_inventory_as_of(license, category, item, packages, quantity_estimate, uom, cost_per_unit, value_at_cost, basis, confidence);
create or replace view public.v_inventory_value as
 WITH sums AS (
         SELECT
                CASE
                    WHEN product_inventory.category = 'solventless'::text THEN 'Solventless'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text AND lower(COALESCE(product_inventory.product_description, ''::text)) ~~ '%cured%'::text THEN 'Hydrocarbon - Cured Badder'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text THEN 'Hydrocarbon - Live Badder'::text
                    WHEN product_inventory.category = ANY (ARRAY['raw_preroll_1g'::text, 'raw_preroll_05g'::text]) THEN 'Raw Pre-rolls'::text
                    WHEN product_inventory.category = 'infused_preroll'::text THEN 'Infused Pre-rolls'::text
                    WHEN product_inventory.category = 'economy_infused'::text THEN 'Economy infused'::text
                    WHEN product_inventory.category = ANY (ARRAY['economy_raw_1g'::text, 'economy_raw_05g'::text]) THEN 'Economy Raw'::text
                    WHEN product_inventory.category = 'vaporizer'::text THEN 'Vapes'::text
                    ELSE NULL::text
                END AS level_label,
            sum(COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) AS units,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date > (CURRENT_DATE - 90) THEN 1
                    ELSE 0
                END::numeric) AS units_0_90,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date <= (CURRENT_DATE - 90) AND product_inventory.creation_date > (CURRENT_DATE - 180) THEN 1
                    ELSE 0
                END::numeric) AS units_91_180,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date <= (CURRENT_DATE - 180) AND product_inventory.creation_date > (CURRENT_DATE - 270) THEN 1
                    ELSE 0
                END::numeric) AS units_181_270,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date <= (CURRENT_DATE - 270) THEN 1
                    ELSE 0
                END::numeric) AS units_271_plus
           FROM product_inventory
          GROUP BY (
                CASE
                    WHEN product_inventory.category = 'solventless'::text THEN 'Solventless'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text AND lower(COALESCE(product_inventory.product_description, ''::text)) ~~ '%cured%'::text THEN 'Hydrocarbon - Cured Badder'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text THEN 'Hydrocarbon - Live Badder'::text
                    WHEN product_inventory.category = ANY (ARRAY['raw_preroll_1g'::text, 'raw_preroll_05g'::text]) THEN 'Raw Pre-rolls'::text
                    WHEN product_inventory.category = 'infused_preroll'::text THEN 'Infused Pre-rolls'::text
                    WHEN product_inventory.category = 'economy_infused'::text THEN 'Economy infused'::text
                    WHEN product_inventory.category = ANY (ARRAY['economy_raw_1g'::text, 'economy_raw_05g'::text]) THEN 'Economy Raw'::text
                    WHEN product_inventory.category = 'vaporizer'::text THEN 'Vapes'::text
                    ELSE NULL::text
                END)
        )
 SELECT v.level_label AS inventory_level,
    v.value_per_unit,
    round(COALESCE(s.units, 0::numeric) * v.value_per_unit, 2) AS inventory_value,
    round(COALESCE(s.units_0_90, 0::numeric) * v.value_per_unit, 2) AS value_0_90_days,
    round(COALESCE(s.units_91_180, 0::numeric) * v.value_per_unit, 2) AS value_91_180_days,
    round(COALESCE(s.units_181_270, 0::numeric) * v.value_per_unit, 2) AS value_181_270_days,
    round(COALESCE(s.units_271_plus, 0::numeric) * v.value_per_unit, 2) AS value_271_plus_days,
    v.formula_note
   FROM inventory_values v
     LEFT JOIN sums s ON s.level_label = v.level_label;
create or replace view public.v_invoice_manifest_match as
 WITH inv AS (
         SELECT a.payload ->> 'invoice_number'::text AS invoice,
            (a.payload -> 'buyer'::text) ->> 'name'::text AS buyer,
            upper(btrim(a.payload ->> 'buyer_state_license'::text)) AS buyer_licence,
            (a.payload ->> 'order_date'::text)::date AS order_date,
            (a.payload ->> 'delivery_date'::text)::date AS delivery_date,
            COALESCE((a.payload ->> 'delivery_date'::text)::date, (a.payload ->> 'order_date'::text)::date) AS ship_date,
            round(COALESCE((a.payload ->> 'total_raw'::text)::numeric, 0::numeric) / 100.0, 2) AS total_usd,
            round(COALESCE((a.payload ->> 'total_payments_raw'::text)::numeric, 0::numeric) / 100.0, 2) AS collected_usd,
            a.payload ->> 'payment_status'::text AS payment_status
           FROM apex_raw a
          WHERE a.entity = 'shipping-orders'::text AND NOT ((a.payload ->> 'cancelled'::text)::boolean)
        ), mf AS (
         SELECT t.manifest_number,
            upper(btrim(t.destination_licence)) AS dest_licence,
            max(t.destination_facility) AS dest_facility,
            min(t.received_on) AS manifest_date,
            round(sum(t.shipped_lb), 2) AS manifest_lb,
            count(*) AS manifest_lines,
            string_agg(DISTINCT t.category, ' | '::text) AS categories
           FROM metrc_rpt_package_transfers t
          WHERE NOT f_is_ours(COALESCE(t.destination_licence, ''::text)) AND COALESCE(t.destination_licence, ''::text) !~* '^(MT|IL)'::text
          GROUP BY t.manifest_number, (upper(btrim(t.destination_licence)))
        )
 SELECT i.invoice,
    i.buyer,
    i.buyer_licence,
    i.order_date,
    i.delivery_date,
    i.total_usd,
    i.collected_usd,
    i.payment_status,
    m.manifest_number,
    m.dest_facility,
    m.manifest_date,
    m.manifest_lb,
    m.manifest_lines,
    m.categories,
    m.manifest_date - i.ship_date AS days_between,
        CASE
            WHEN m.manifest_number IS NOT NULL THEN 'MATCHED on buyer licence + date window'::text
            WHEN i.buyer_licence IS NULL THEN 'NO MATCH — the Apex order records no buyer licence'::text
            WHEN EXTRACT(year FROM i.ship_date) = 2024::numeric THEN 'NO MATCH — 2024 shipped via the Eagle Eyes warehouse; the final leg is on THEIR licence'::text
            ELSE 'NO MATCH — no manifest to this licence within the window'::text
        END AS match_verdict
   FROM inv i
     LEFT JOIN mf m ON m.dest_licence = i.buyer_licence AND m.manifest_date >= (i.ship_date - 10) AND m.manifest_date <= (i.ship_date + 30);
create or replace view public.v_issue_unconfirmed_manifests as
 SELECT manifest_number,
    created_on AS shipped_on,
    CURRENT_DATE - created_on AS days_unconfirmed,
    recipient AS customer,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages,
    raw ->> 'TransporterFacilityName'::text AS transporter,
        CASE
            WHEN (raw ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || (raw ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END AS manifest_link,
    'THE ISSUE: this outbound manifest was never confirmed received. The chain of custody is open on the state record.'::text AS what_is_wrong,
    'Contact the receiving facility and have them confirm receipt in Metrc, or void and reissue.'::text AS what_to_do,
    license
   FROM metrc_transfers t
  WHERE direction = 'outgoing'::text AND (raw ->> 'ReceivedDateTime'::text) IS NULL AND created_on < (CURRENT_DATE - 3)
  ORDER BY (CURRENT_DATE - created_on) DESC;
create or replace view public.v_issue_yield_by_harvest as
 WITH avgc AS (
         SELECT avg(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS company_avg
           FROM metrc_harvests
          WHERE COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric
        )
 SELECT h.name AS harvest,
    COALESCE(h.raw ->> 'SourceStrainNames'::text, 'not recorded'::text) AS strain,
    COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
    h.harvest_start AS harvest_date,
    (h.raw ->> 'FinishedDate'::text)::date AS finished_date,
        CASE
            WHEN (h.raw ->> 'FinishedDate'::text) IS NOT NULL THEN ((h.raw ->> 'FinishedDate'::text)::date) - h.harvest_start
            ELSE NULL::integer
        END AS dry_days,
    CURRENT_DATE - h.harvest_start AS days_since_harvest,
    COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants,
    round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS wet_lbs,
    round(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS saleable_lbs,
    round(COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS waste_lbs,
    round(100.0 * COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric), 1) AS conversion_pct,
    round(100.0 * (( SELECT avgc_1.company_avg
           FROM avgc avgc_1)), 1) AS company_average_pct,
    ( SELECT industry_benchmarks.average
           FROM industry_benchmarks
          WHERE industry_benchmarks.metric = 'Wet to saleable conversion'::text) AS industry_average_pct,
    round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 * ((( SELECT avgc_1.company_avg
           FROM avgc avgc_1)) - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1) AS pounds_short_of_company_average,
    round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 * ((( SELECT avgc_1.company_avg
           FROM avgc avgc_1)) - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_short,
    h.raw ->> 'LabTestingState'::text AS laboratory_state,
    h.license,
    ((('THE ISSUE: this harvest converted '::text || round(100.0 * COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric), 1)) || ' percent against a company average of '::text) || round(100.0 * (( SELECT avgc_1.company_avg
           FROM avgc avgc_1)), 1)) || ' percent.'::text AS what_is_wrong,
    'Check dry days and trim practice for this harvest against a high performing one in the same room.'::text AS what_to_do
   FROM metrc_harvests h,
    avgc
  WHERE COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) > 0::numeric AND (COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric)) < (0.75 * avgc.company_avg)
  ORDER BY (round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 * ((( SELECT avgc_1.company_avg
           FROM avgc avgc_1)) - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_lab_sample_link as
 SELECT r.package_tag AS sample_tag,
    r.source_packages AS source_tag,
    p.tag IS NOT NULL AS source_in_package_book,
    p.item_name AS source_item,
    r.item AS sample_item,
    r.category,
    r.lab_facility AS laboratory,
    r.lab_licence,
    r.test_date,
    r.test_name,
    r.result,
    f_yesno(r.passed) AS analyte_passed,
    f_yesno(r.overall_passed) AS sample_passed,
    r.overall_passed AS sample_passed_as_filed,
    r.source_harvests,
        CASE
            WHEN COALESCE(r.source_harvests, ''::text) = ''::text THEN NULL::text
            WHEN r.source_harvests ~~ '%,%'::text THEN 'BLEND'::text
            ELSE btrim("substring"(r.source_harvests, '^(.*?)\s+-\s'::text))
        END AS strain_or_blend,
    r.source_harvests ~~ '%,%'::text AS is_blend,
    (EXISTS ( SELECT 1
           FROM coa_extract c
          WHERE c.package_tag = r.source_packages)) AS source_has_coa,
    (EXISTS ( SELECT 1
           FROM metrc_lab_results m
          WHERE m.package_tag = r.source_packages)) AS also_in_api_sync,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM metrc_lab_results m
              WHERE m.package_tag = r.source_packages)) THEN 'Metrc Lab Results report, corroborated by the API sync'::text
            ELSE 'Metrc Lab Results report ONLY - the API sync never returned this package'::text
        END AS provenance,
    r.as_of_date AS import_as_of,
    r.imported_at
   FROM metrc_rpt_lab_results r
     LEFT JOIN metrc_packages p ON p.tag = r.source_packages
  WHERE COALESCE(r.source_packages, ''::text) <> ''::text;
create or replace view public.v_lab_samples_out as
 SELECT destination_facility AS laboratory,
    destination_licence AS laboratory_licence,
    manifest_number,
    received_on AS sent_on,
    package_tag,
    item,
    category,
    strain,
    round(COALESCE(shipped_lb, 0::numeric), 4) AS lb,
    shipped_qty,
    shipped_uom,
    status,
    COALESCE(NULLIF(btrim(source_row ->> 'Origin Facility'::text), ''::text), licence) AS sent_by,
    NULLIF(btrim(source_row ->> 'Created by User'::text), ''::text) AS sent_by_user,
    NULLIF(btrim(source_row ->> 'Received by User'::text), ''::text) AS received_by_user,
    (EXISTS ( SELECT 1
           FROM metrc_rpt_lab_results r
          WHERE r.package_tag = t.package_tag)) AS has_a_lab_result,
    ( SELECT max(r.test_date) AS max
           FROM metrc_rpt_lab_results r
          WHERE r.package_tag = t.package_tag) AS last_result_on,
    ( SELECT max(r.lab_facility) AS max
           FROM metrc_rpt_lab_results r
          WHERE r.package_tag = t.package_tag) AS result_from_lab
   FROM metrc_rpt_package_transfers t
  WHERE upper(btrim(COALESCE(destination_licence, ''::text))) ~~ 'IL%'::text;
create or replace view public.v_lab_turnaround_report as
 SELECT date_trunc('month'::text, went_out_on::timestamp with time zone)::date AS month,
    category,
    count(*) AS samples,
    round(avg(days_out), 2) AS avg_days,
    percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (days_out::double precision)) AS median_days,
    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (days_out::double precision)) AS p95_days,
    max(days_out) AS worst_days,
    count(*) FILTER (WHERE breached) AS over_the_limit,
    round(100.0 * count(*) FILTER (WHERE breached)::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_over_limit,
    f_rule('lab_turnaround_max_days'::text) AS limit_days
   FROM lab_turnaround_log
  WHERE went_out_on IS NOT NULL
  GROUP BY (date_trunc('month'::text, went_out_on::timestamp with time zone)::date), category
  ORDER BY (date_trunc('month'::text, went_out_on::timestamp with time zone)::date) DESC, category;
create or replace view public.v_lab_turnaround_summary as
 SELECT COALESCE(NULLIF(category, ''::text), 'Not recorded'::text) AS category,
    count(*) AS packages,
    round(avg(days_out) FILTER (WHERE days_out IS NOT NULL), 1) AS avg_turnaround_days,
    max(days_out) AS slowest_turnaround_days,
    min(days_out) AS fastest_turnaround_days,
    count(*) FILTER (WHERE days_out > 14) AS took_over_14_days,
    count(*) FILTER (WHERE came_back_on IS NULL) AS still_out,
    round(sum(pounds), 1) AS pounds,
    min(went_out_on) AS first_sample_on,
    max(came_back_on) AS last_return_on
   FROM lab_turnaround_log
  WHERE went_out_on IS NOT NULL
  GROUP BY (COALESCE(NULLIF(category, ''::text), 'Not recorded'::text));
create or replace view public.v_labour_forecast as
 WITH pol AS (
         SELECT attendance_policy.shift_hours_gross
           FROM attendance_policy
         LIMIT 1
        ), plan AS (
         SELECT s.employee_id,
            s.work_date,
            date_trunc('week'::text, s.work_date::timestamp with time zone)::date AS week_start,
            COALESCE(d.name, 'Unassigned'::text) AS department,
            COALESCE(btrim(s.zone), 'No zone'::text) AS zone,
            EXTRACT(epoch FROM s.planned_end - s.planned_start) / 3600.0 - COALESCE(bw.minutes, 0)::numeric / 60.0 AS planned_hours,
            e.hours_basis,
            r.rate,
            COALESCE(r.burden_pct, 0::numeric) AS burden
           FROM employee_schedules s
             JOIN employees e ON e.id = s.employee_id
             LEFT JOIN departments d ON d.id = COALESCE(s.department_id, e.primary_department_id)
             LEFT JOIN break_windows bw ON bw.active AND (bw.department_id IS NULL OR bw.department_id = s.department_id)
             LEFT JOIN LATERAL ( SELECT r2.id,
                    r2.employee_id,
                    r2.basis,
                    r2.rate,
                    r2.ot_multiplier,
                    r2.burden_pct,
                    r2.effective_from,
                    r2.effective_to,
                    r2.approved_by,
                    r2.note,
                    r2.effective_from_date
                   FROM employee_rates r2
                  WHERE r2.employee_id = s.employee_id AND r2.effective_from <= s.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= s.work_date)
                  ORDER BY r2.effective_from DESC
                 LIMIT 1) r ON true
          WHERE s.planned_start IS NOT NULL AND s.planned_end IS NOT NULL
        )
 SELECT department,
    zone,
    work_date,
    week_start,
    count(DISTINCT employee_id) AS heads_planned,
    round(sum(planned_hours), 2) AS hours_planned,
    round(sum(planned_hours) / NULLIF(( SELECT pol.shift_hours_gross
           FROM pol), 0::numeric), 2) AS shifts_planned,
    round(sum(planned_hours * rate * (1::numeric + burden)), 2) AS cost_planned_loaded,
    round(sum(planned_hours * rate * (1::numeric + burden)) / NULLIF(sum(planned_hours), 0::numeric), 2) AS planned_cost_per_hour
   FROM plan
  GROUP BY department, zone, work_date, week_start;
create or replace view public.v_legal_entity as
 WITH seen AS (
         SELECT COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '(none)'::text) AS licence,
            COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(none)'::text) AS name_seen,
            count(*) AS tags,
            sum(
                CASE
                    WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))
                    ELSE NULL::numeric
                END) AS lb
           FROM metrc_packages p
          WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric
          GROUP BY (COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '(none)'::text)), (COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(none)'::text))
        )
 SELECT licence AS entity_licence,
    string_agg(DISTINCT name_seen, ' | '::text) AS names_seen,
    count(DISTINCT name_seen) AS spellings,
        CASE
            WHEN licence ~~ 'MC%'::text THEN 'Cultivator'::text
            WHEN licence ~~ 'MP%'::text THEN 'Product Manufacturer'::text
            WHEN licence ~~ 'MR%'::text OR licence ~~ 'MRN%'::text THEN 'Retailer'::text
            WHEN licence ~~ 'MT%'::text THEN 'Transporter'::text
            WHEN licence ~~ 'MB%'::text THEN 'Microbusiness'::text
            WHEN licence ~~ 'IL%'::text THEN 'Independent Laboratory'::text
            WHEN licence ~~ 'RMD%'::text THEN 'Registered Medical Dispensary'::text
            ELSE 'other'::text
        END AS licence_type,
    f_is_ours(licence) AS is_ours,
    sum(tags) AS tags_on_hand,
    round(sum(lb), 2) AS lb_on_hand,
    ( SELECT count(DISTINCT t.licence) - 1
           FROM seen t
          WHERE (t.name_seen IN ( SELECT u.name_seen
                   FROM seen u
                  WHERE u.licence = s.licence))) AS sibling_licences_same_name
   FROM seen s
  GROUP BY licence;
create or replace view public.v_licence_directory as
 SELECT licence,
    name,
    sources,
    seen
   FROM ( SELECT z.licence,
            z.name,
            count(*) AS seen,
            string_agg(DISTINCT z.src, ', '::text) AS sources,
            row_number() OVER (PARTITION BY z.licence ORDER BY (count(*)) DESC) AS rn
           FROM ( SELECT metrc_transfers.raw ->> 'ShipperFacilityLicenseNumber'::text AS licence,
                    metrc_transfers.raw ->> 'ShipperFacilityName'::text AS name,
                    'transfer shipper'::text AS src
                   FROM metrc_transfers
                  WHERE NULLIF(metrc_transfers.raw ->> 'ShipperFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text,
                    metrc_transfers.raw ->> 'RecipientFacilityName'::text,
                    'transfer recipient'::text
                   FROM metrc_transfers
                  WHERE NULLIF(metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT metrc_packages.raw ->> 'ItemFromFacilityLicenseNumber'::text,
                    metrc_packages.raw ->> 'ItemFromFacilityName'::text,
                    'package item origin'::text
                   FROM metrc_packages
                  WHERE NULLIF(metrc_packages.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT metrc_packages.raw ->> 'ReceivedFromFacilityLicenseNumber'::text,
                    metrc_packages.raw ->> 'ReceivedFromFacilityName'::text,
                    'package received from'::text
                   FROM metrc_packages
                  WHERE NULLIF(metrc_packages.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT coa_extract.client_license,
                    coa_extract.client_name,
                    'certificate client'::text
                   FROM coa_extract
                  WHERE coa_extract.client_license IS NOT NULL AND coa_extract.client_name IS NOT NULL) z
          WHERE z.name IS NOT NULL AND z.name <> ''::text
          GROUP BY z.licence, z.name) d
  WHERE rn = 1;
create or replace view public.v_lifecycle_open as
 SELECT p.id,
    p.employee_id,
    e.employee_code,
    e.full_name,
    p.phase,
    s.ordinal,
    s.title,
    s.detail,
    s.owner_role,
    s.is_legal,
    s.blocks_start,
    s.blocks_close,
    p.due_on,
    p.due_on IS NOT NULL AND p.due_on < CURRENT_DATE AS overdue,
    CURRENT_DATE - p.due_on AS days_overdue
   FROM lifecycle_progress p
     JOIN lifecycle_steps s ON s.id = p.step_id
     JOIN employees e ON e.id = p.employee_id
  WHERE p.done_at IS NULL AND p.na_reason IS NULL
  ORDER BY s.is_legal DESC, p.due_on, s.ordinal;
create or replace view public.v_location_notes as
 SELECT l.metrc_id AS metrc_location_id,
    l.license,
    l.name AS location,
    l.location_type,
    count(n.id) AS note_count,
    max(n.created_at) AS last_note_at,
    COALESCE(jsonb_agg(jsonb_build_object('id', n.id, 'note', n.note, 'category', n.category, 'author', COALESCE(n.author_name, 'not recorded'::text), 'written_at', n.created_at, 'renamed_since',
        CASE
            WHEN n.location_name_when_written IS DISTINCT FROM l.name THEN n.location_name_when_written
            ELSE NULL::text
        END) ORDER BY n.created_at DESC) FILTER (WHERE n.id IS NOT NULL), '[]'::jsonb) AS notes
   FROM metrc_locations l
     LEFT JOIN location_note n ON n.metrc_location_id = l.metrc_id
  GROUP BY l.metrc_id, l.license, l.name, l.location_type;
create or replace view public.v_location_notes_orphaned as
 SELECT id,
    metrc_location_id,
    license,
    location_name_when_written AS location_as_written,
    note,
    category,
    author_name,
    created_at,
    'This location is no longer served by Metrc for this licence. The note is kept.'::text AS why_here
   FROM location_note n
  WHERE NOT (EXISTS ( SELECT 1
           FROM metrc_locations l
          WHERE l.metrc_id = n.metrc_location_id));
create or replace view public.v_loop_health as
 SELECT jobname,
    schedule,
    active,
    succeeded_7d,
    failed_7d,
    last_success,
    usual_seconds,
    running_for_seconds,
    verdict,
    usual_gap_seconds,
    last_failure,
    runs_only_in_a_window
   FROM ( WITH recent AS (
                 SELECT d.jobid,
                    d.status,
                    d.start_time,
                    d.end_time,
                    EXTRACT(epoch FROM d.end_time - d.start_time) AS secs
                   FROM cron.job_run_details d
                  WHERE d.start_time > (now() - '7 days'::interval)
                ), gaps AS (
                 SELECT recent.jobid,
                    EXTRACT(epoch FROM recent.start_time - lag(recent.start_time) OVER (PARTITION BY recent.jobid ORDER BY recent.start_time)) AS gap
                   FROM recent
                  WHERE recent.status = 'succeeded'::text
                ), cadence AS (
                 SELECT gaps.jobid,
                    percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (gaps.gap::double precision)) AS usual_gap
                   FROM gaps
                  WHERE gaps.gap IS NOT NULL
                  GROUP BY gaps.jobid
                ), norm AS (
                 SELECT recent.jobid,
                    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (recent.secs::double precision)) FILTER (WHERE recent.secs IS NOT NULL) AS p95_secs,
                    count(*) FILTER (WHERE recent.status = 'succeeded'::text) AS ok_7d,
                    count(*) FILTER (WHERE recent.status = 'failed'::text) AS failed_7d,
                    max(recent.start_time) FILTER (WHERE recent.status = 'succeeded'::text) AS last_success,
                    max(recent.start_time) FILTER (WHERE recent.status = 'failed'::text) AS last_failure
                   FROM recent
                  GROUP BY recent.jobid
                ), live AS (
                 SELECT recent.jobid,
                    min(recent.start_time) AS running_since
                   FROM recent
                  WHERE recent.status = 'running'::text AND recent.end_time IS NULL
                  GROUP BY recent.jobid
                ), shape AS (
                 SELECT j_1.jobid,
                    split_part(j_1.schedule, ' '::text, 2) !~ '^([*]|[*]/[0-9]+)$'::text AS runs_in_a_window
                   FROM cron.job j_1
                )
         SELECT j.jobname,
            j.schedule,
            j.active,
            COALESCE(n.ok_7d, 0::bigint) AS succeeded_7d,
            COALESCE(n.failed_7d, 0::bigint) AS failed_7d,
            n.last_success,
            round(n.p95_secs)::integer AS usual_seconds,
            round(EXTRACT(epoch FROM now() - l.running_since))::integer AS running_for_seconds,
                CASE
                    WHEN NOT j.active THEN 'switched off'::text
                    WHEN COALESCE(n.ok_7d, 0::bigint) = 0 AND COALESCE(n.failed_7d, 0::bigint) = 0 THEN 'has not run at all in 7 days'::text
                    WHEN COALESCE(n.ok_7d, 0::bigint) = 0 THEN 'NEVER SUCCEEDED - every run failed'::text
                    WHEN l.running_since IS NOT NULL AND n.p95_secs IS NOT NULL AND EXTRACT(epoch FROM now() - l.running_since)::double precision > GREATEST(n.p95_secs * 4::double precision, 300::double precision) THEN 'HUNG - running far longer than it ever normally takes'::text
                    WHEN n.last_failure IS NOT NULL AND n.last_failure > n.last_success THEN 'FAILING - its most recent run failed'::text
                    WHEN c.usual_gap IS NOT NULL AND NOT COALESCE(s.runs_in_a_window, false) AND n.last_success < (now() - make_interval(secs => c.usual_gap * 2.5::double precision)) THEN 'LATE - overdue against its own normal interval'::text
                    WHEN COALESCE(n.failed_7d, 0::bigint) > 0 THEN 'recovered - failed earlier, succeeding now'::text
                    ELSE 'healthy'::text
                END AS verdict,
            round(c.usual_gap)::integer AS usual_gap_seconds,
            n.last_failure,
            COALESCE(s.runs_in_a_window, false) AS runs_only_in_a_window
           FROM cron.job j
             LEFT JOIN norm n ON n.jobid = j.jobid
             LEFT JOIN cadence c ON c.jobid = j.jobid
             LEFT JOIN live l ON l.jobid = j.jobid
             LEFT JOIN shape s ON s.jobid = j.jobid
          ORDER BY (
                CASE
                    WHEN NOT j.active THEN 5
                    WHEN COALESCE(n.ok_7d, 0::bigint) = 0 THEN 0
                    WHEN n.last_failure IS NOT NULL AND n.last_failure > n.last_success THEN 1
                    WHEN COALESCE(n.failed_7d, 0::bigint) > 0 THEN 3
                    ELSE 4
                END), j.jobname) guarded_body
  WHERE ( SELECT is_executive() AS is_executive);
create or replace view public.v_loss_ledger as
 SELECT h.license,
    'Harvest waste'::text AS loss_type,
    h.name AS record,
    h.harvest_start AS occurred_on,
    h.raw ->> 'DryingLocationName'::text AS room,
    (h.raw ->> 'TotalWasteWeight'::text)::numeric AS amount,
    h.raw ->> 'UnitOfWeightName'::text AS uom,
    COALESCE(h.raw ->> 'HarvestType'::text, 'Harvest waste'::text) AS reason_code,
    h.raw ->> 'SourceStrainNames'::text AS detail
   FROM metrc_harvests h
  WHERE COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) > 0::numeric
UNION ALL
 SELECT p.license,
    'Package adjustment'::text AS loss_type,
    p.tag AS record,
    p.packaged_on AS occurred_on,
    p.location AS room,
    abs(COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) - COALESCE(p.quantity, 0::numeric)) AS amount,
    p.uom,
    COALESCE(p.raw ->> 'ArchivedDate'::text, 'Quantity change'::text) AS reason_code,
    p.item_name AS detail
   FROM metrc_packages p
  WHERE COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) > COALESCE(p.quantity, 0::numeric)
UNION ALL
 SELECT p.license,
    'Failed testing'::text AS loss_type,
    p.tag AS record,
    p.packaged_on AS occurred_on,
    p.location AS room,
    p.quantity AS amount,
    p.uom,
    'Laboratory test failed'::text AS reason_code,
    p.item_name AS detail
   FROM metrc_packages p
  WHERE p.lab_testing_state = 'TestFailed'::text;
create or replace view public.v_loss_ranking as
 SELECT scope_type,
    scope,
    harvests,
    wet_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    verdict
   FROM ( SELECT 'Room'::text AS scope_type,
            COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS scope,
            count(*)::numeric AS harvests,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS wet_lbs,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS waste_lbs,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS waste_pct,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS yield_pct,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric AND (100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric))) > 15::numeric THEN 'ABOVE ACCEPTABLE'::text
                    ELSE 'Within range'::text
                END AS verdict
           FROM metrc_harvests
          GROUP BY (COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, '(no room)'::text))
        UNION ALL
         SELECT 'Strain'::text,
            COALESCE(metrc_harvests.raw ->> 'SourceStrainNames'::text, '(not recorded)'::text) AS "coalesce",
            count(*)::numeric AS count,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS "case",
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS "case",
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric AND (100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric))) > 15::numeric THEN 'ABOVE ACCEPTABLE'::text
                    ELSE 'Within range'::text
                END AS "case"
           FROM metrc_harvests
          GROUP BY (COALESCE(metrc_harvests.raw ->> 'SourceStrainNames'::text, '(not recorded)'::text))) x
  WHERE wet_lbs > 0::numeric
  ORDER BY waste_pct DESC NULLS LAST;
create or replace view public.v_manifest_ledger as
 WITH per_manifest AS (
         SELECT metrc_transfers.manifest_number,
            min(metrc_transfers.created_on) AS created_on,
            array_agg(DISTINCT metrc_transfers.license ORDER BY metrc_transfers.license) AS licences,
            array_agg(DISTINCT metrc_transfers.direction ORDER BY metrc_transfers.direction) AS directions,
            (array_agg(metrc_transfers.shipper ORDER BY metrc_transfers.direction))[1] AS shipper,
            (array_agg(metrc_transfers.recipient ORDER BY (metrc_transfers.recipient IS NULL), metrc_transfers.direction))[1] AS recipient,
            count(*) AS row_count,
            (array_agg(metrc_transfers.raw ORDER BY (metrc_transfers.recipient IS NULL), metrc_transfers.direction))[1] AS raw
           FROM metrc_transfers
          GROUP BY metrc_transfers.manifest_number
        ), dest AS (
         SELECT pt.manifest_number,
            max(pt.destination_licence) AS destination_licence
           FROM metrc_rpt_package_transfers pt
          WHERE pt.destination_licence IS NOT NULL
          GROUP BY pt.manifest_number
        ), typed AS (
         SELECT m.manifest_number,
            m.created_on,
            m.licences,
            m.directions,
            m.shipper,
            m.recipient,
            m.row_count,
            m.raw,
            d.destination_licence,
            f_facility_type(d.destination_licence) AS destination_type,
            COALESCE(f_is_transporter(d.destination_licence), false) AS to_transporter,
            COALESCE(m.raw ->> 'ShipmentTypeName'::text, (m.raw -> '_delivery'::text) ->> 'ShipmentTypeName'::text) AS shipment_type,
            COALESCE(m.shipper, ''::text) ~~* '%twisted%'::text AS we_shipped,
            COALESCE(m.recipient, ''::text) ~~* '%twisted%'::text AS we_received
           FROM per_manifest m
             LEFT JOIN dest d ON d.manifest_number = m.manifest_number
        )
 SELECT manifest_number,
    created_on,
    licences,
    directions,
    shipper,
    recipient,
    row_count,
    shipment_type,
        CASE
            WHEN array_length(licences, 1) > 1 OR we_shipped AND we_received THEN 'Internal move'::text
            WHEN we_received AND NOT we_shipped THEN 'Inbound - bought in'::text
            WHEN shipment_type ~~* '%lab%'::text THEN 'Laboratory sample'::text
            WHEN shipment_type ~~* '%vendor sample%'::text THEN 'Vendor sample'::text
            WHEN shipment_type ~~* '%patient%'::text THEN 'Patient supply'::text
            WHEN to_transporter THEN 'Storage/transport movement'::text
            ELSE 'Customer sale'::text
        END AS movement,
        CASE
            WHEN array_length(licences, 1) > 1 THEN 'Both'::text
            ELSE f_operation(licences[1])
        END AS operation,
    licences[1] AS licence,
    array_length(licences, 1) = 1 AND NOT we_received AND COALESCE(shipment_type, ''::text) !~~* '%lab%'::text AND COALESCE(shipment_type, ''::text) !~~* '%vendor sample%'::text AND COALESCE(shipment_type, ''::text) !~~* '%patient%'::text AND NOT to_transporter AS is_customer_sale,
    we_received AND NOT we_shipped AS is_inbound_purchase,
    ( SELECT count(*) AS count
           FROM metrc_documents d
          WHERE d.manifest_number = t.manifest_number AND d.storage_path IS NOT NULL) AS documents,
    raw,
    (((((((manifest_number || ' '::text) || COALESCE(recipient, ''::text)) || ' '::text) || COALESCE(shipper, ''::text)) || ' '::text) || array_to_string(licences, ' '::text)) || ' '::text) || COALESCE(shipment_type, ''::text) AS search_text,
    destination_licence,
    destination_type,
    to_transporter
   FROM typed t;
create or replace view public.v_manifest_line_gaps as
 SELECT t.manifest_number,
    t.direction,
    t.created_on AS shipped_on,
    t.shipper,
    t.recipient,
    f_facility_type(COALESCE(t.raw ->> 'RecipientFacilityLicenseNumber'::text, t.raw ->> 'ShipperFacilityLicenseNumber'::text)) AS counterparty_type,
    COALESCE((t.raw ->> 'PackageCount'::text)::integer, 0) AS packages_metrc_says,
    0 AS package_lines_we_hold,
    d.storage_path AS manifest_document,
        CASE
            WHEN d.storage_path IS NOT NULL THEN (('ANSWERABLE — the manifest PDF is on file. Nothing has parsed it. '::text || 'Run manifest-parse against this manifest and the '::text) || COALESCE(t.raw ->> 'PackageCount'::text, '?'::text)) || ' package lines can be recovered.'::text
            WHEN d.fetch_error IS NOT NULL THEN 'DOCUMENT FAILED TO DOWNLOAD — '::text || "left"(d.fetch_error, 120)
            WHEN d.id IS NOT NULL THEN 'Document row exists but no file was ever stored.'::text
            ELSE 'NO DOCUMENT AND NO LINES — this shipment has no record of its contents anywhere.'::text
        END AS where_the_answer_is,
        CASE
            WHEN t.direction = 'outgoing'::text THEN 1
            ELSE 2
        END AS rank
   FROM metrc_transfers t
     LEFT JOIN metrc_documents d ON d.manifest_number = t.manifest_number AND d.doc_type ~~* '%manifest%'::text
  WHERE NOT (EXISTS ( SELECT 1
           FROM metrc_rpt_package_transfers r
          WHERE r.manifest_number = t.manifest_number));
create or replace view public.v_manifest_reconciliation as
 WITH man AS (
         SELECT DISTINCT ON (metrc_rpt_transfer_manifests.manifest_number) metrc_rpt_transfer_manifests.manifest_number,
            metrc_rpt_transfer_manifests.created_on,
            metrc_rpt_transfer_manifests.received_on,
            metrc_rpt_transfer_manifests.destination_licence,
            metrc_rpt_transfer_manifests.destination_facility
           FROM metrc_rpt_transfer_manifests
          WHERE metrc_rpt_transfer_manifests.direction = 'outbound'::text
          ORDER BY metrc_rpt_transfer_manifests.manifest_number, metrc_rpt_transfer_manifests.created_on
        ), kind AS (
         SELECT m.manifest_number,
            m.created_on,
            m.received_on,
            m.destination_licence,
            m.destination_facility,
                CASE
                    WHEN m.destination_licence IS NULL THEN 'UNKNOWN DESTINATION'::text
                    WHEN f_is_ours(m.destination_licence) THEN 'INTERNAL TRANSFER'::text
                    WHEN "left"(m.destination_licence, 2) = 'IL'::text THEN 'LABORATORY SAMPLE'::text
                    WHEN "left"(m.destination_licence, 2) = 'MX'::text THEN 'TRANSPORTER'::text
                    ELSE 'SALE'::text
                END AS destination_kind
           FROM man m
        ), money AS (
         SELECT w.manifest_number,
            round(sum(w.amount) FILTER (WHERE NOT w.voided AND w.amount >= 1.00), 2) AS declared,
            count(*) FILTER (WHERE NOT w.voided AND w.amount >= 1.00) AS money_lines,
            count(*) FILTER (WHERE w.voided) AS voided_lines,
            count(*) FILTER (WHERE w.amount < 1.00) AS placeholder_lines,
            max(NULLIF(btrim(w.invoice_number), ''::text)) AS invoice_number
           FROM metrc_rpt_wholesale w
          GROUP BY w.manifest_number
        ), pkgs AS (
         SELECT metrc_rpt_package_transfers.manifest_number,
            count(DISTINCT metrc_rpt_package_transfers.package_tag) AS package_tags
           FROM metrc_rpt_package_transfers
          GROUP BY metrc_rpt_package_transfers.manifest_number
        ), apex AS (
         SELECT regexp_replace(apex_raw.payload ->> 'invoice_number'::text, '\D'::text, ''::text, 'g'::text) AS d,
            min(NULLIF(apex_raw.payload ->> 'order_date'::text, ''::text)::date) AS apex_order_date,
            min(NULLIF(apex_raw.payload ->> 'delivery_date'::text, ''::text)::date) AS apex_delivery_date,
            round(sum((apex_raw.payload ->> 'subtotal_raw'::text)::numeric) / 100::numeric, 2) AS apex_value,
            count(*) AS apex_orders,
            string_agg(DISTINCT btrim(apex_raw.payload ->> 'invoice_number'::text), ', '::text) AS apex_invoices
           FROM apex_raw
          WHERE apex_raw.entity = 'shipping-orders'::text AND ((apex_raw.payload ->> 'cancelled'::text) = ANY (ARRAY[''::text, '0'::text, 'false'::text])) AND jsonb_array_length(COALESCE(apex_raw.payload -> 'items'::text, '[]'::jsonb)) > 0
          GROUP BY (regexp_replace(apex_raw.payload ->> 'invoice_number'::text, '\D'::text, ''::text, 'g'::text))
        )
 SELECT k.manifest_number,
    k.created_on AS metrc_date,
    k.received_on AS metrc_received,
    k.destination_licence,
    k.destination_facility,
    k.destination_kind,
    mo.invoice_number AS metrc_invoice_number,
    mo.declared AS metrc_declared,
    mo.money_lines,
    mo.voided_lines,
    mo.placeholder_lines,
    COALESCE(p.package_tags, 0::bigint) AS package_tags,
    a.apex_invoices,
    a.apex_order_date,
    a.apex_delivery_date,
    a.apex_value,
    a.apex_orders,
    COALESCE(a.apex_delivery_date, a.apex_order_date) - k.created_on AS date_gap_days,
    round(a.apex_value - mo.declared, 2) AS value_gap,
        CASE
            WHEN k.destination_kind <> 'SALE'::text THEN 'NOT A SALE — '::text || k.destination_kind
            WHEN k.created_on < '2025-01-30'::date THEN 'BEFORE THE KEY EXISTED — Metrc carried no invoice number until 2025-01-30'::text
            WHEN mo.invoice_number IS NULL THEN 'NO INVOICE NUMBER on the Metrc record'::text
            WHEN a.d IS NULL THEN 'NO APEX ORDER for this invoice number'::text
            WHEN mo.declared IS NULL THEN 'NO METRC VALUE — Apex order matched but the manifest has no priced line'::text
            WHEN abs(a.apex_value - mo.declared) <= (( SELECT conversion_factors.value
               FROM conversion_factors
              WHERE conversion_factors.key = 'apex_metrc_rounding_tolerance_usd'::text)) THEN 'RECONCILED'::text
            WHEN a.apex_value > mo.declared THEN 'VALUE DIFFERS — Apex sold more than Metrc declares'::text
            ELSE 'VALUE DIFFERS — Metrc declares more than Apex sold'::text
        END AS status
   FROM kind k
     LEFT JOIN money mo ON mo.manifest_number = k.manifest_number
     LEFT JOIN pkgs p ON p.manifest_number = k.manifest_number
     LEFT JOIN apex a ON a.d = regexp_replace(COALESCE(mo.invoice_number, ''::text), '\D'::text, ''::text, 'g'::text) AND mo.invoice_number IS NOT NULL;
create or replace view public.v_manifest_unparsed as
 SELECT metrc_id,
    storage_path,
    manifest_number
   FROM metrc_documents d
  WHERE doc_type = 'manifest'::text AND storage_path IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM manifest_extract m
          WHERE m.manifest_number = d.manifest_number))
  ORDER BY manifest_number;
create or replace view public.v_material_aging as
 SELECT lot_code,
    supplier,
    material_type,
    strain_description,
    purchase_date,
    received_date,
    uom,
    purchased_qty,
    unit_cost,
    round(COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric), 2) AS total_landed_cost,
        CASE
            WHEN COALESCE(purchased_qty, 0::numeric) > 0::numeric THEN round((COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)) / purchased_qty, 4)
            ELSE NULL::numeric
        END AS landed_cost_per_uom,
    allocated_qty,
    GREATEST(COALESCE(purchased_qty, 0::numeric) - COALESCE(allocated_qty, 0::numeric), 0::numeric) AS available_qty,
    work_order,
    allocation_date,
        CASE
            WHEN purchase_date IS NOT NULL AND allocation_date IS NOT NULL THEN allocation_date - purchase_date
            ELSE NULL::integer
        END AS days_to_allocation,
        CASE
            WHEN purchase_date IS NOT NULL AND fg_release_date IS NOT NULL THEN fg_release_date - purchase_date
            ELSE NULL::integer
        END AS days_purchase_to_release,
        CASE
            WHEN purchase_date IS NOT NULL AND cash_collected_date IS NOT NULL THEN cash_collected_date - purchase_date
            ELSE NULL::integer
        END AS days_purchase_to_cash,
    revenue_from_lot,
        CASE
            WHEN COALESCE(revenue_from_lot, 0::numeric) > 0::numeric THEN round(revenue_from_lot - (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)), 2)
            ELSE NULL::numeric
        END AS gross_return,
        CASE
            WHEN COALESCE(revenue_from_lot, 0::numeric) > 0::numeric AND (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)) > 0::numeric THEN round(100.0 * (revenue_from_lot - (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric))) / (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)), 1)
            ELSE NULL::numeric
        END AS roi_pct,
        CASE
            WHEN purchase_date IS NOT NULL THEN CURRENT_DATE - purchase_date
            ELSE NULL::integer
        END AS aging_days,
        CASE
            WHEN GREATEST(COALESCE(purchased_qty, 0::numeric) - COALESCE(allocated_qty, 0::numeric), 0::numeric) > 0::numeric AND purchase_date IS NOT NULL AND (CURRENT_DATE - purchase_date) > COALESCE(( SELECT (configurations.value ->> 'days'::text)::integer AS int4
               FROM configurations
              WHERE configurations.key = 'material_aging_alert_days'::text), 30) THEN 'CAPITAL TIED UP'::text
            ELSE 'OK'::text
        END AS aging_alert,
    status
   FROM material_purchases m
  ORDER BY purchase_date DESC NULLS LAST;
create or replace view public.v_material_requirement as
 WITH y AS (
         SELECT production_yield_standard.key,
            production_yield_standard.value
           FROM production_yield_standard
        ), l AS (
         SELECT (o.payload ->> 'order_date'::text)::date AS order_date,
            o.payload ->> 'invoice_number'::text AS invoice_number,
            (o.payload -> 'buyer'::text) ->> 'name'::text AS buyer,
            (it.value -> 'brand'::text) ->> 'name'::text AS brand,
            (it.value -> 'product_category'::text) ->> 'name'::text AS apex_category,
            it.value ->> 'product_name'::text AS product_name,
            (it.value -> 'cultivar'::text) ->> 'name'::text AS strain,
                CASE
                    WHEN ((it.value -> 'order_unit_measurement'::text) ->> 'name'::text) = 'Case'::text THEN COALESCE((it.value ->> 'order_quantity'::text)::numeric, 0::numeric) * COALESCE(NULLIF(it.value ->> 'units_per_case'::text, ''::text)::numeric, 1::numeric)
                    ELSE COALESCE((it.value ->> 'order_quantity'::text)::numeric, 0::numeric)
                END AS units,
            NULLIF(it.value ->> 'gram_per_preroll'::text, ''::text)::numeric AS g_per_preroll,
            NULLIF(it.value ->> 'unit_size'::text, ''::text)::numeric AS unit_size_g,
            "substring"(it.value ->> 'product_name'::text, '([0-9]+\.?[0-9]*)\s*[gG]\y'::text)::numeric AS pack_g,
            (it.value -> 'product_type'::text) ->> 'name'::text AS ptype,
            COALESCE((it.value ->> 'order_price_raw'::text)::numeric, 0::numeric) / 100.0 / NULLIF(COALESCE(NULLIF(it.value ->> 'units_per_case'::text, ''::text)::numeric, 1::numeric), 0::numeric) AS price_per_unit
           FROM apex_raw o
             JOIN LATERAL jsonb_array_elements(COALESCE(o.payload -> 'items'::text, '[]'::jsonb)) it(value) ON true
          WHERE o.entity = 'shipping-orders'::text AND NOT COALESCE((o.payload ->> 'cancelled'::text)::boolean, false)
        ), t AS (
         SELECT l.order_date,
            l.invoice_number,
            l.buyer,
            l.brand,
            l.apex_category,
            l.product_name,
            l.strain,
            l.units,
            l.g_per_preroll,
            l.unit_size_g,
            l.pack_g,
            l.ptype,
            l.price_per_unit,
            COALESCE(bt.tier, 'OTHER'::text) AS tier,
            bt.material AS tier_material,
            fm.flower_pct,
            fm.trim_pct,
            fm.set_by AS formulation_set_by
           FROM l
             LEFT JOIN product_brand_tier bt ON bt.brand = l.brand
             LEFT JOIN LATERAL f_preroll_formulation(l.brand, l.order_date) fm(flower_pct, trim_pct, set_by) ON true
        )
 SELECT order_date,
    invoice_number,
    buyer,
    brand,
    tier,
    tier_material,
    apex_category,
    product_name,
    strain,
    units,
    price_per_unit,
    round(
        CASE
            WHEN apex_category = 'Preroll'::text AND tier = 'PREMIUM'::text THEN units * COALESCE(g_per_preroll, ( SELECT y.value
               FROM y
              WHERE y.key = 'preroll_premium_grams'::text)) * (( SELECT y.value
               FROM y
              WHERE y.key = 'preroll_premium_flower_pct'::text))
            WHEN apex_category = 'Preroll'::text AND flower_pct IS NOT NULL THEN units * COALESCE(g_per_preroll, 1::numeric) * flower_pct
            WHEN apex_category = 'Prepack'::text THEN units * pack_g
            ELSE NULL::numeric
        END / 453.59237, 3) AS flower_lb,
    round(
        CASE
            WHEN apex_category = 'Preroll'::text AND tier <> 'PREMIUM'::text AND trim_pct IS NOT NULL THEN units * COALESCE(g_per_preroll, 1::numeric) * trim_pct
            ELSE NULL::numeric
        END / 453.59237, 3) AS trim_lb,
    round(
        CASE
            WHEN apex_category = ANY (ARRAY['Cartridge'::text, 'Extract'::text]) THEN units * unit_size_g
            ELSE NULL::numeric
        END / 453.59237, 3) AS concentrate_lb,
        CASE
            WHEN apex_category = 'Preroll'::text AND tier = 'PREMIUM'::text THEN 'Pure flower, 1 g, no formulation'::text
            WHEN apex_category = 'Preroll'::text AND flower_pct IS NOT NULL THEN (((('Formulation '::text || round(flower_pct * 100::numeric)) || '/'::text) || round(trim_pct * 100::numeric)) || ' flower:trim in force on the order date — '::text) || formulation_set_by
            WHEN apex_category = 'Preroll'::text THEN 'FORMULATION NOT SET for this brand'::text
            WHEN apex_category = 'Prepack'::text AND pack_g IS NOT NULL THEN ('Our own packaged flower (A Bud), '::text || pack_g) || ' g per unit'::text
            WHEN apex_category = 'Prepack'::text THEN 'PACK SIZE NOT IN THE PRODUCT NAME — not defaulted'::text
            WHEN apex_category = ANY (ARRAY['Cartridge'::text, 'Extract'::text]) THEN 'Finished oil weight. Input material NOT added — that would double-dip.'::text
            WHEN apex_category = 'Flower'::text THEN 'Sold by the pound; no conversion'::text
            ELSE 'No material model for this category'::text
        END AS basis,
    ptype AS product_type,
    pack_g AS pack_size_g
   FROM t;
create or replace view public.v_material_sourcing as
 WITH base AS (
         SELECT p.license AS licence,
            p.raw ->> 'Label'::text AS tag,
            NULLIF(btrim(p.raw ->> 'LocationName'::text), ''::text) AS room,
            COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
            NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS from_facility,
            NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) AS from_licence,
            (p.raw ->> 'ReceivedDateTime'::text)::timestamp with time zone AS received_at,
            (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
            f_to_pounds(COALESCE((p.raw ->> 'ReceivedQuantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) AS lb_received,
                CASE
                    WHEN COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false THEN f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))
                    ELSE 0::numeric
                END AS lb_on_hand
           FROM metrc_packages p
        )
 SELECT
        CASE
            WHEN from_licence IS NULL THEN 'OURS — grown here'::text
            WHEN f_is_ours(from_licence) THEN 'OURS — moved between our own licences'::text
            ELSE 'THIRD PARTY — bought in'::text
        END AS ownership,
    COALESCE(from_facility, 'Twisted Growers LLC'::text) AS counterparty,
    COALESCE(from_licence, '—'::text) AS counterparty_licence,
    licence,
    category,
    EXTRACT(year FROM COALESCE(received_at::date, packaged_on))::integer AS yr,
    count(*) AS tags,
    round(sum(lb_received), 1) AS lb_received,
    round(sum(lb_on_hand), 1) AS lb_still_on_hand
   FROM base
  GROUP BY (
        CASE
            WHEN from_licence IS NULL THEN 'OURS — grown here'::text
            WHEN f_is_ours(from_licence) THEN 'OURS — moved between our own licences'::text
            ELSE 'THIRD PARTY — bought in'::text
        END), (COALESCE(from_facility, 'Twisted Growers LLC'::text)), (COALESCE(from_licence, '—'::text)), licence, category, (EXTRACT(year FROM COALESCE(received_at::date, packaged_on))::integer);
create or replace view public.v_matview_freshness as
 SELECT matview,
    has_clock,
    computed_at,
    age,
    scheduled_refresh,
    verdict
   FROM f_matview_freshness() f_matview_freshness(matview, has_clock, computed_at, age, scheduled_refresh, verdict);
create or replace view public.v_metrc_corrections_open as
 SELECT title,
    what_is_wrong,
    why_it_matters,
    how_to_fix_in_metrc,
    packages_affected,
    pounds,
    assigned_to,
    raised_on,
    raised_by,
    CURRENT_DATE - raised_on AS days_open,
    ((((('OPEN IN METRC. This does not clear itself and cannot be closed from this platform. It stays '::text || 'here until the correction is made in Metrc and someone records who did it, when, and what '::text) || 'was done. Raised '::text) || raised_on) || ', '::text) || (CURRENT_DATE - raised_on)) || ' days ago.'::text AS standing
   FROM metrc_corrections
  WHERE NOT fixed_in_metrc
  ORDER BY pounds DESC NULLS LAST;
create or replace view public.v_metrc_credential_risk as
 SELECT full_name,
    metrc_agent_badge AS badge,
    badge_expires,
    badge_expires - CURRENT_DATE AS days_until_expiry,
    status AS our_roster_says,
    metrc_license_status AS metrc_says,
        CASE
            WHEN badge_expires IS NULL AND status = 'active'::employment_status THEN 'ACTIVE STAFF WITH NO BADGE RECORDED - cannot prove they may legally handle product'::text
            WHEN badge_expires < CURRENT_DATE THEN ('EXPIRED '::text || (CURRENT_DATE - badge_expires)) || ' days ago'::text
            WHEN badge_expires <= (CURRENT_DATE + 14) AND status = 'active'::employment_status THEN ('EXPIRES IN '::text || (badge_expires - CURRENT_DATE)) || ' DAYS - active staff, renew now'::text
            WHEN badge_expires <= (CURRENT_DATE + 14) THEN ('EXPIRES IN '::text || (badge_expires - CURRENT_DATE)) || ' DAYS'::text
            ELSE 'ok'::text
        END AS badge_standing,
        CASE
            WHEN status = 'inactive'::employment_status AND metrc_license_status = 'Active'::text THEN 'DISAGREEMENT - we say they left, Metrc says their licence is Active. Either a former employee holds live credentials, or the roster is wrong.'::text
            WHEN status = 'active'::employment_status AND metrc_license_status IS DISTINCT FROM 'Active'::text THEN 'DISAGREEMENT - we say they work here, Metrc does not show an active licence. They may not legally handle product.'::text
            ELSE 'agrees'::text
        END AS roster_vs_metrc
   FROM employees e
  WHERE badge_expires IS NOT NULL OR status = 'active'::employment_status OR status = 'inactive'::employment_status AND metrc_license_status = 'Active'::text
  ORDER BY (
        CASE
            WHEN badge_expires < CURRENT_DATE THEN 0
            WHEN badge_expires <= (CURRENT_DATE + 14) THEN 1
            WHEN status = 'inactive'::employment_status AND metrc_license_status = 'Active'::text THEN 2
            ELSE 3
        END), badge_expires;
create or replace view public.v_metrc_facility_names as
 SELECT COALESCE((raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text, raw ->> 'RecipientFacilityLicenseNumber'::text) AS facility_licence,
    COALESCE((raw -> '_delivery'::text) ->> 'RecipientFacilityName'::text, recipient) AS name_seen,
    created_on,
    manifest_number
   FROM metrc_transfers t
  WHERE COALESCE((raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text, raw ->> 'RecipientFacilityLicenseNumber'::text) IS NOT NULL;
create or replace view public.v_metrc_lab_status as
 SELECT license,
    COALESCE(lab_testing_state, '—'::text) AS lab_testing_state,
    count(*) AS packages,
    round(sum(quantity), 2) AS total_qty,
    count(DISTINCT item_name) AS items
   FROM metrc_packages
  GROUP BY license, lab_testing_state
  ORDER BY license, (count(*)) DESC;
create or replace view public.v_metrc_package_inventory as
 SELECT license,
    item,
    location,
    packages,
    total_qty,
    uom,
    lab_state,
    finished_pkgs,
    oldest,
    newest,
    oldest AS oldest_date
   FROM ( SELECT metrc_packages.license,
            COALESCE(metrc_packages.item_name, '—'::text) AS item,
            COALESCE(metrc_packages.location, '—'::text) AS location,
            count(*) AS packages,
            round(sum(metrc_packages.quantity), 2) AS total_qty,
            min(metrc_packages.uom) AS uom,
            COALESCE(metrc_packages.lab_testing_state, '—'::text) AS lab_state,
            count(*) FILTER (WHERE metrc_packages.finished) AS finished_pkgs,
            min(metrc_packages.packaged_on) AS oldest,
            max(metrc_packages.packaged_on) AS newest
           FROM metrc_packages
          GROUP BY metrc_packages.license, metrc_packages.item_name, metrc_packages.location, metrc_packages.lab_testing_state
          ORDER BY metrc_packages.license, (round(sum(metrc_packages.quantity), 2)) DESC NULLS LAST) q;
create or replace view public.v_metrc_plant_census as
 SELECT license,
    room,
    phase,
    plants,
    strains,
    strain_breakdown,
    oldest_planting,
    newest_planting,
    oldest_days_in_room,
    oldest_planting AS oldest_planting_date
   FROM ( SELECT p.license,
            p.room,
                CASE p.source_state
                    WHEN 'vegetative'::text THEN 'Vegetative'::text
                    WHEN 'flowering'::text THEN 'Flowering'::text
                    WHEN 'onhold'::text THEN 'On hold'::text
                    ELSE 'Harvested or retired'::text
                END AS phase,
            count(*)::numeric AS plants,
            count(DISTINCT p.strain)::numeric AS strains,
            ( SELECT string_agg(x.line, ' · '::text ORDER BY x.n DESC) AS string_agg
                   FROM ( SELECT ((p2.strain || ' ('::text) || count(*)) || ')'::text AS line,
                            count(*) AS n
                           FROM metrc_plants p2
                          WHERE p2.license = p.license AND p2.room = p.room AND p2.source_state = p.source_state
                          GROUP BY p2.strain) x) AS strain_breakdown,
            min(p.planted_on) AS oldest_planting,
            max(p.planted_on) AS newest_planting,
            max(CURRENT_DATE - p.planted_on)::numeric AS oldest_days_in_room
           FROM metrc_plants p
          WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])
          GROUP BY p.license, p.room, p.source_state
          ORDER BY (count(*)::numeric) DESC) q;
create or replace view public.v_metrc_scan_settings as
 SELECT job_name,
    display_name,
    endpoints,
    enabled,
    run_times,
    timezone,
    min_gap_minutes,
    what_it_pulls,
    why_it_matters,
    when_to_pull_now,
    calls_per_scan,
    cardinality(run_times) AS scans_per_day,
    calls_per_scan * cardinality(run_times) AS calls_per_day,
    last_run_at,
    last_result,
    ( SELECT min((((now() AT TIME ZONE s.timezone)::date + t.t) AT TIME ZONE s.timezone)) AS min
           FROM unnest(s.run_times) t(t)
          WHERE (((now() AT TIME ZONE s.timezone)::date + t.t) AT TIME ZONE s.timezone) > now()) AS next_run_at,
        CASE
            WHEN last_run_at IS NULL THEN 'Never run'::text
            WHEN (now() - last_run_at) < make_interval(mins => min_gap_minutes) THEN ('Pulled recently - manual scan is held for '::text || (min_gap_minutes::numeric - EXTRACT(epoch FROM now() - last_run_at) / 60::numeric)::integer) || ' more minutes'::text
            ELSE 'Ready - can be pulled now'::text
        END AS manual_scan_state,
    sort_order
   FROM metrc_scan_schedule s;
create or replace view public.v_metrc_seed_to_sale as
 SELECT strain,
    plants_growing_now,
    plants_harvested,
    harvest_events,
    wet_weight_lbs,
    waste_lbs,
    waste_pct,
    packaged_lbs,
    yield_pct,
    packages_made,
    manufactured_into,
    on_hand_now,
    sitting_in,
    packages_passed_testing,
    packages_failed_testing,
    packages_shipped_out,
    still_in_rooms,
    last_harvest,
    last_harvest AS last_harvest_date
   FROM ( WITH harv AS (
                 SELECT COALESCE(h_1.raw ->> 'SourceStrainNames'::text, 'Unassigned'::text) AS strain,
                    count(*) AS harvests,
                    sum(COALESCE((h_1.raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants_harvested,
                    sum(COALESCE((h_1.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
                    sum(COALESCE((h_1.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g,
                    sum(COALESCE((h_1.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS packaged_g,
                    string_agg(DISTINCT COALESCE(h_1.raw ->> 'DryingLocationName'::text, ''::text), ', '::text) FILTER (WHERE (h_1.raw ->> 'FinishedDate'::text) IS NULL) AS rooms_now,
                    max(h_1.harvest_start) AS last_harvest
                   FROM metrc_harvests h_1
                  GROUP BY (COALESCE(h_1.raw ->> 'SourceStrainNames'::text, 'Unassigned'::text))
                ), pk AS (
                 SELECT COALESCE(NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), '(no source)'::text) AS src,
                    p.tag,
                    p.item_name,
                    p.quantity,
                    p.uom,
                    p.location,
                    p.lab_testing_state,
                    p.source_state,
                    COALESCE(p.raw ->> 'ProductCategoryName'::text, ''::text) AS product_category
                   FROM metrc_packages p
                ), live AS (
                 SELECT x.strain,
                    sum(x.plants) AS plants_live
                   FROM ( SELECT COALESCE(metrc_plants.strain, 'Unassigned'::text) AS strain,
                            count(*) AS plants
                           FROM metrc_plants
                          WHERE metrc_plants.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])
                          GROUP BY (COALESCE(metrc_plants.strain, 'Unassigned'::text))) x
                  GROUP BY x.strain
                )
         SELECT h.strain,
            COALESCE(l.plants_live, 0::numeric) AS plants_growing_now,
            h.plants_harvested,
            h.harvests AS harvest_events,
            round(h.wet_g / 453.592, 1) AS wet_weight_lbs,
            round(h.waste_g / 453.592, 1) AS waste_lbs,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100.0 * h.waste_g / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS waste_pct,
            round(h.packaged_g / 453.592, 1) AS packaged_lbs,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100.0 * h.packaged_g / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS yield_pct,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text)) AS packages_made,
            ( SELECT string_agg(DISTINCT pk.product_category, ', '::text) AS string_agg
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.product_category <> ''::text) AS manufactured_into,
            ( SELECT round(sum(COALESCE(pk.quantity, 0::numeric)), 1) AS round
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND (pk.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS on_hand_now,
            ( SELECT string_agg(DISTINCT pk.location, ', '::text) AS string_agg
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND (pk.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND pk.location IS NOT NULL) AS sitting_in,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.lab_testing_state = 'TestPassed'::text) AS packages_passed_testing,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.lab_testing_state = 'TestFailed'::text) AS packages_failed_testing,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.source_state = 'intransit'::text) AS packages_shipped_out,
            NULLIF(h.rooms_now, ''::text) AS still_in_rooms,
            h.last_harvest
           FROM harv h
             LEFT JOIN live l ON l.strain = h.strain
          WHERE h.strain <> 'Unassigned'::text
          ORDER BY h.wet_g DESC NULLS LAST) q;
create or replace view public.v_metrc_strain_census as
 SELECT license,
    strain,
    live_plants_now,
    vegetative_now,
    flowering_now,
    on_hold_now,
    harvested_or_retired,
    total_plants_all_time,
    rooms_now,
    in_rooms,
    first_planted,
    last_planted,
    harvest_events,
    lifetime_wet_lbs,
    lifetime_packaged_lbs,
    first_planted AS first_planted_date
   FROM ( WITH base AS (
                 SELECT p.license,
                    COALESCE(p.strain, 'not recorded'::text) AS strain,
                    count(*) FILTER (WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))::numeric AS live_plants_now,
                    count(*) FILTER (WHERE p.source_state = 'vegetative'::text)::numeric AS vegetative_now,
                    count(*) FILTER (WHERE p.source_state = 'flowering'::text)::numeric AS flowering_now,
                    count(*) FILTER (WHERE p.source_state = 'onhold'::text)::numeric AS on_hold_now,
                    count(*) FILTER (WHERE p.source_state = 'inactive'::text)::numeric AS harvested_or_retired,
                    count(*)::numeric AS total_plants_all_time,
                    count(DISTINCT p.room) FILTER (WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))::numeric AS rooms_now,
                    string_agg(DISTINCT p.room, ', '::text) FILTER (WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])) AS in_rooms,
                    min(p.planted_on) AS first_planted,
                    max(p.planted_on) AS last_planted
                   FROM metrc_plants p
                  GROUP BY p.license, (COALESCE(p.strain, 'not recorded'::text))
                )
         SELECT b.license,
            b.strain,
            b.live_plants_now,
            b.vegetative_now,
            b.flowering_now,
            b.on_hold_now,
            b.harvested_or_retired,
            b.total_plants_all_time,
            b.rooms_now,
            b.in_rooms,
            b.first_planted,
            b.last_planted,
            ( SELECT count(*) AS count
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || b.strain) || '%'::text)) AS harvest_events,
            ( SELECT round(sum(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || b.strain) || '%'::text)) AS lifetime_wet_lbs,
            ( SELECT round(sum(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || b.strain) || '%'::text)) AS lifetime_packaged_lbs
           FROM base b
          ORDER BY b.live_plants_now DESC, b.total_plants_all_time DESC) q;
create or replace view public.v_metrc_transfer_ledger as
 SELECT manifest_number,
    direction,
    created_on,
    (raw ->> 'ReceivedDateTime'::text)::date AS received_on,
    shipper,
    recipient,
    raw ->> 'RecipientFacilityLicenseNumber'::text AS recipient_license,
    raw ->> 'ShipperFacilityLicenseNumber'::text AS shipper_license,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages,
    COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric) AS packages_received,
    raw ->> 'TransporterFacilityName'::text AS transporter,
    raw ->> 'DriverName'::text AS driver,
    raw ->> 'VehicleMake'::text AS vehicle_make,
    raw ->> 'VehicleLicensePlateNumber'::text AS vehicle_plate,
    (raw ->> 'EstimatedDepartureDateTime'::text)::timestamp with time zone AS departed,
    (raw ->> 'EstimatedArrivalDateTime'::text)::timestamp with time zone AS arrival_estimate,
    raw ->> 'ShipmentTypeName'::text AS shipment_type,
        CASE
            WHEN (raw ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || (raw ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END AS manifest_link,
    raw ->> 'Id'::text AS metrc_transfer_id,
    license
   FROM metrc_transfers t
  ORDER BY created_on DESC NULLS LAST;
create or replace view public.v_metrc_vs_os as
 WITH x AS (
         SELECT 'Packages - Inventory'::text AS metrc_report,
            'metrc_rpt_packages_inventory'::text AS report_table,
            'metrc_packages (API sync)'::text AS os_source,
            (( SELECT count(*) AS count
                   FROM metrc_rpt_packages_inventory))::numeric AS report_rows,
            (( SELECT count(DISTINCT metrc_packages.tag) AS count
                   FROM metrc_packages
                  WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])))::numeric AS os_rows,
            'The export is a point-in-time snapshot; the API holds live state. A large gap means the export is stale.'::text AS note
        UNION ALL
         SELECT 'Harvests'::text,
            'metrc_rpt_harvests'::text,
            'metrc_harvests (API sync)'::text,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_harvests) AS count,
            ( SELECT count(*) AS count
                   FROM metrc_harvests) AS count,
            'Must match exactly. Both describe the same harvest population.'::text
        UNION ALL
         SELECT 'Lab Results'::text,
            'metrc_rpt_lab_results'::text,
            'metrc_lab_results (API sync)'::text,
            ( SELECT count(DISTINCT metrc_rpt_lab_results.package_tag) AS count
                   FROM metrc_rpt_lab_results) AS count,
            ( SELECT count(DISTINCT metrc_lab_results.package_tag) AS count
                   FROM metrc_lab_results) AS count,
            'Compared on DISTINCT PACKAGES, not rows - the API holds one row per analyte, the export one per test.'::text
        UNION ALL
         SELECT 'Transfers - Manifests'::text,
            'metrc_rpt_transfer_manifests'::text,
            'metrc_transfers (API sync)'::text,
            ( SELECT count(DISTINCT metrc_rpt_transfer_manifests.manifest_number) AS count
                   FROM metrc_rpt_transfer_manifests) AS count,
            ( SELECT count(DISTINCT metrc_transfers.manifest_number) AS count
                   FROM metrc_transfers) AS count,
            'Every manifest in the API must appear in the export. 49 do not - 42 live incoming covering 277 packages.'::text
        UNION ALL
         SELECT 'Packages - Transferred'::text,
            'metrc_rpt_package_transfers'::text,
            'manifests carrying package lines'::text,
            ( SELECT count(DISTINCT metrc_rpt_package_transfers.manifest_number) AS count
                   FROM metrc_rpt_package_transfers) AS count,
            ( SELECT count(DISTINCT metrc_transfers.manifest_number) AS count
                   FROM metrc_transfers) AS count,
            'This export is the ONLY link between a package and its manifest. Anything it omits loses its custody evidence.'::text
        UNION ALL
         SELECT 'Wholesale Transfers'::text,
            'metrc_rpt_wholesale'::text,
            'metrc_rpt_package_transfers (the other export)'::text,
            ( SELECT count(DISTINCT metrc_rpt_wholesale.manifest_number) AS count
                   FROM metrc_rpt_wholesale) AS count,
            ( SELECT count(DISTINCT metrc_rpt_package_transfers.manifest_number) AS count
                   FROM metrc_rpt_package_transfers) AS count,
            'Two Metrc reports describing the same movements. They differ by $72,828 in value - one is incomplete.'::text
        UNION ALL
         SELECT 'Adjustments'::text,
            'metrc_rpt_adjustments'::text,
            'packages with an adjustment'::text,
            ( SELECT count(DISTINCT metrc_rpt_adjustments.package_tag) AS count
                   FROM metrc_rpt_adjustments) AS count,
            ( SELECT count(DISTINCT metrc_packages.tag) AS count
                   FROM metrc_packages
                  WHERE ((metrc_packages.raw ->> 'CreatedQuantity'::text)::numeric) <> metrc_packages.quantity) AS count,
            'Packages whose quantity changed after creation should appear in the adjustments export.'::text
        UNION ALL
         SELECT 'Harvest Moisture'::text,
            'metrc_rpt_harvest_moisture'::text,
            'metrc_harvests (API sync)'::text,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_harvest_moisture) AS count,
            ( SELECT count(*) AS count
                   FROM metrc_harvests) AS count,
            'Moisture is recorded per harvest. A gap means harvests with no moisture entry.'::text
        UNION ALL
         SELECT 'Test Batches'::text,
            'metrc_rpt_test_batches'::text,
            'distinct lab test batches'::text,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_test_batches) AS count,
            ( SELECT count(DISTINCT metrc_lab_results.raw ->> 'LabTestResultId'::text) AS count
                   FROM metrc_lab_results) AS count,
            'Each test batch should correspond to a lab result set.'::text
        )
 SELECT metrc_report,
    report_table,
    os_source,
    report_rows,
    os_rows,
    report_rows - os_rows AS difference,
        CASE
            WHEN os_rows > 0::numeric THEN round(abs(report_rows - os_rows) / os_rows * 100::numeric, 2)
            ELSE NULL::numeric
        END AS pct_apart,
        CASE
            WHEN report_rows = os_rows THEN 'AGREE'::text
            WHEN report_rows = 0::numeric THEN 'REPORT NOT IMPORTED'::text
            ELSE 'DISCREPANCY'::text
        END AS verdict,
    note,
    'THE ISSUE: a Metrc report export and the Metrc API describe the same facts. Where they differ one is incomplete, and neither figure may be quoted until it is known which.'::text AS what_is_wrong,
    'Re-pull the export for the affected licence and date range, then re-compare. Never reconcile by preferring the larger number.'::text AS what_to_do
   FROM x;
create or replace view public.v_metric_conformance as
 WITH pound_views AS (
         SELECT c.relname AS surface,
            c.relkind
           FROM pg_class c
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"])) AND pg_get_viewdef(c.oid) ~~* '%f_to_pounds%'::text
        )
 SELECT p.surface,
        CASE p.relkind
            WHEN 'm'::"char" THEN 'matview'::text
            ELSE 'view'::text
        END AS surface_kind,
    u.metric_key IS NOT NULL AS is_registered,
    COALESCE(u.conforms, false) AS uses_canonical_definition,
    u.metric_key,
        CASE
            WHEN u.metric_key IS NULL THEN 'UNREGISTERED — defines pounds with no entry in the metric registry'::text
            WHEN NOT COALESCE(u.conforms, false) THEN 'REGISTERED BUT NOT CONFORMING — has its own copy of the definition'::text
            ELSE 'CONFORMS'::text
        END AS verdict
   FROM pound_views p
     LEFT JOIN metric_usage u ON u.surface = p.surface
  ORDER BY (u.metric_key IS NULL) DESC, p.surface;
create or replace view public.v_metric_registry_gaps as
 SELECT 'Metrics registered'::text AS measure,
    count(*)::text AS value,
    'One definition each. Every one has a drill - rule C1 is enforced by NOT NULL.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active
UNION ALL
 SELECT 'Needing a declared drill filter'::text AS measure,
    (count(*)::text || ' of '::text) || (( SELECT count(*)::text AS count
           FROM metric_registry metric_registry_1
          WHERE metric_registry_1.active)) AS value,
    'Until declared, the tile cannot be reconciled to its rows automatically. This is the number that justifies the registry.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active AND metric_registry.drill_filter IS NULL
UNION ALL
 SELECT 'Needing a declared target'::text AS measure,
    (count(*)::text || ' of '::text) || (( SELECT count(*)::text AS count
           FROM metric_registry metric_registry_1
          WHERE metric_registry_1.active)) AS value,
    'Without a target the tile cannot turn red on breach, and a movement cannot be judged good or bad. Owner-set - never guessed.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active AND metric_registry.target_rule_key IS NULL
UNION ALL
 SELECT 'Needing a roll-up parent'::text AS measure,
    (count(*)::text || ' of '::text) || (( SELECT count(*)::text AS count
           FROM metric_registry metric_registry_1
          WHERE metric_registry_1.active)) AS value,
    'Until declared, the CEO and Tower boards compute their own version instead of deriving from departments.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active AND metric_registry.rolls_up_to_metric IS NULL
UNION ALL
 SELECT 'DUPLICATED across departments'::text AS measure,
    ( SELECT count(*)::text AS count
           FROM ( SELECT metric_registry.label
                   FROM metric_registry
                  WHERE metric_registry.active
                  GROUP BY metric_registry.label
                 HAVING count(*) > 1) d) AS value,
    'The same fact registered under more than one department, each maintained by repetition rather than derivation. If one changes and the other does not, they diverge silently - this is what rolls_up_to_metric replaces.'::text AS note;
create or replace view public.v_migration_history as
 SELECT version,
    name,
        CASE
            WHEN version ~ '^\d{14}$'::text THEN (to_timestamp(version, 'YYYYMMDDHH24MISS'::text) AT TIME ZONE 'UTC'::text)
            ELSE NULL::timestamp without time zone
        END AS applied_at
   FROM supabase_migrations.schema_migrations m;
create or replace view public.v_moisture_accounting as
 SELECT harvest,
    strain,
    room,
    harvest_start,
    finished,
    plants,
    stream,
    wet_lb,
    packaged_lb,
    recorded_waste_lb,
    moisture_lb,
    metrc_current_weight_lb,
    reconciliation_gap_lb,
    moisture_pct_of_wet,
    conversion_pct,
    the_arithmetic,
    verdict,
    harvest_start AS harvest_start_date
   FROM ( WITH h AS (
                 SELECT metrc_harvests.name AS harvest,
                    metrc_harvests.harvest_start,
                    (metrc_harvests.raw ->> 'FinishedDate'::text)::date AS finished,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text), '(not recorded)'::text) AS room,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
                    (metrc_harvests.raw ->> 'PlantCount'::text)::integer AS plants,
                    metrc_harvests.wet_weight AS wet_g,
                    metrc_harvests.waste_weight AS waste_g,
                    (metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric AS pkg_g,
                    (metrc_harvests.raw ->> 'CurrentWeight'::text)::numeric AS current_g,
                    metrc_harvests.name ~~* '%FF%'::text OR COALESCE(NULLIF(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text), ''::text) ~~* '%freezer%'::text AS fresh_frozen
                   FROM metrc_harvests
                )
         SELECT h.harvest,
            h.strain,
            h.room,
            h.harvest_start,
            h.finished,
            h.plants,
                CASE
                    WHEN h.fresh_frozen THEN 'Fresh frozen'::text
                    ELSE 'Dried flower'::text
                END AS stream,
            round(h.wet_g / 453.592, 2) AS wet_lb,
            round(h.pkg_g / 453.592, 2) AS packaged_lb,
            round(h.waste_g / 453.592, 2) AS recorded_waste_lb,
            round((h.wet_g - h.pkg_g - h.waste_g) / 453.592, 2) AS moisture_lb,
            round(h.current_g / 453.592, 2) AS metrc_current_weight_lb,
            round((h.wet_g - h.pkg_g - h.waste_g - h.current_g) / 453.592, 2) AS reconciliation_gap_lb,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS moisture_pct_of_wet,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100::numeric * h.pkg_g / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS conversion_pct,
            ((((((round(h.wet_g / 453.592, 2) || ' lb wet = '::text) || round(h.pkg_g / 453.592, 2)) || ' packaged + '::text) || round(h.waste_g / 453.592, 2)) || ' waste + '::text) || round((h.wet_g - h.pkg_g - h.waste_g) / 453.592, 2)) || ' evaporated'::text AS the_arithmetic,
                CASE
                    WHEN h.fresh_frozen THEN 'FRESH FROZEN - packaged at field moisture, so almost no water leaves. Never judge this against a dried-flower conversion.'::text
                    WHEN h.wet_g = 0::numeric THEN 'NO WET WEIGHT RECORDED - cannot be reconciled.'::text
                    WHEN abs(h.wet_g - h.pkg_g - h.waste_g - h.current_g) > (h.wet_g * 0.02) THEN ('DOES NOT RECONCILE - Metrc current weight disagrees by '::text || round(abs(h.wet_g - h.pkg_g - h.waste_g - h.current_g) / 453.592, 2)) || ' lb. Investigate.'::text
                    WHEN (100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g) >= 70::numeric AND (100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g) <= 82::numeric THEN ('NORMAL - '::text || round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)) || ' percent moisture loss, inside the expected 70 to 82 percent.'::text
                    WHEN (100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g) > 82::numeric THEN ('MOISTURE LOSS HIGH at '::text || round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)) || ' percent. Over-dried, or packaged weight recorded low.'::text
                    ELSE ('MOISTURE LOSS LOW at '::text || round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)) || ' percent. Wet weight probably recorded too low at takedown.'::text
                END AS verdict
           FROM h) q;
create or replace view public.v_money_provenance as
 WITH money_cols AS (
         SELECT c.table_name AS view_name,
            c.column_name
           FROM information_schema.columns c
          WHERE c.table_schema::name = 'public'::name AND c.table_name::name ~~ 'v\_%'::text AND (c.column_name::name ~~* '%dollar%'::text OR c.column_name::name ~~* '%value_at%'::text OR c.column_name::name ~~* '%cost_per%'::text OR c.column_name::name ~~* '%_value%'::text OR c.column_name::name ~~* 'value'::text OR c.column_name::name ~~* '%revenue%'::text OR c.column_name::name ~~* '%price%'::text)
        ), defs AS (
         SELECT m.view_name,
            m.column_name,
            pg_get_viewdef(quote_ident(m.view_name::text)::regclass::oid, true) AS body
           FROM money_cols m
        )
 SELECT view_name,
    column_name,
        CASE
            WHEN body ~~* '%f_rate_for%'::text THEN 'Valuation Rates, per stream'::text
            WHEN body ~~* '%target_cost_per_lb%'::text THEN 'Central fallback: conversion_factors.target_cost_per_lb'::text
            WHEN body ~~* '%inventory_values%'::text THEN 'Inventory Values sheet: value per unit'::text
            WHEN body ~~* '%cost_model%'::text THEN 'Cost Model: cost per pound'::text
            WHEN body ~~* '%employee_rates%'::text OR body ~~* '%payroll%'::text THEN 'Payroll: employee rates'::text
            WHEN body ~~* '%unit_cost%'::text OR body ~~* '%landed_cost%'::text THEN 'Purchase records: landed cost'::text
            WHEN body ~~* '%ai_%'::text THEN 'Artificial intelligence usage records'::text
            ELSE 'NOT TRACED — this figure is not derived from any known rate table'::text
        END AS rate_source,
        CASE
            WHEN body ~~* '%f_rate_for%'::text THEN 'Correct — uses the per stream rate and any batch override.'::text
            WHEN body ~~* '%target_cost_per_lb%'::text THEN 'Uses one flat number for every stream. Accurate only where the streams really are worth the same.'::text
            WHEN body ~~* '%ai_%'::text OR body ~~* '%payroll%'::text OR body ~~* '%employee_rates%'::text OR body ~~* '%landed_cost%'::text OR body ~~* '%unit_cost%'::text THEN 'Correct — this is a recorded cost, not an estimated rate.'::text
            ELSE 'Cannot be explained from the definition. Treat this figure as unproven.'::text
        END AS verdict
   FROM defs d
  ORDER BY (
        CASE
            WHEN body ~~* '%f_rate_for%'::text THEN 3
            WHEN body ~~* '%target_cost_per_lb%'::text THEN 2
            ELSE 1
        END), view_name, column_name;
create or replace view public.v_monthly_yield as
 WITH h AS (
         SELECT to_char(date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone), 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone)::date AS month_date,
            count(*) AS harvests,
            sum((metrc_harvests.raw ->> 'PlantCount'::text)::numeric) AS plants,
            sum((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592 AS wet_lb,
            sum((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric) / 453.592 AS waste_lb,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592 AS packaged_lb,
            sum(COALESCE((metrc_harvests.raw ->> 'CurrentWeight'::text)::numeric, 0::numeric)) / 453.592 AS still_on_harvest_lb
           FROM metrc_harvests
          WHERE COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start) IS NOT NULL
          GROUP BY (to_char(date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone), 'YYYY-MM'::text)), (date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone)::date)
        ), cat AS (
         SELECT to_char(date_trunc('month'::text, p.packaged_on::timestamp with time zone), 'YYYY-MM'::text) AS month,
            sum(f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom))) FILTER (WHERE (p.raw #>> '{Item,ProductCategoryName}'::text[]) = 'Buds'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL) AS flower_lb,
            sum(f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom))) FILTER (WHERE (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~ 'Shake/Trim%'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL) AS trim_lb,
            sum(f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom))) FILTER (WHERE (p.raw #>> '{Item,ProductCategoryName}'::text[]) = 'Fresh Frozen Flower'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL) AS fresh_frozen_lb
           FROM metrc_packages p
          WHERE p.packaged_on IS NOT NULL
          GROUP BY (to_char(date_trunc('month'::text, p.packaged_on::timestamp with time zone), 'YYYY-MM'::text))
        )
 SELECT h.month,
    h.month_date,
    h.harvests,
    round(h.plants) AS plants,
    round(h.wet_lb, 1) AS wet_lb,
    round(h.waste_lb, 1) AS waste_lb,
    round(h.packaged_lb, 1) AS packaged_lb,
    round(h.still_on_harvest_lb, 1) AS still_on_harvest_lb,
    round(COALESCE(c.flower_lb, 0::numeric), 1) AS dried_flower_lb,
    round(COALESCE(c.trim_lb, 0::numeric), 1) AS trim_lb,
    round(COALESCE(c.fresh_frozen_lb, 0::numeric), 1) AS fresh_frozen_lb,
    380::numeric AS target_lb,
    round(COALESCE(c.flower_lb, 0::numeric) - 380::numeric, 1) AS flower_vs_target_lb,
        CASE
            WHEN COALESCE(c.flower_lb, 0::numeric) >= 380::numeric THEN 'MET'::text
            ELSE 'BELOW TARGET'::text
        END AS target_status,
        CASE
            WHEN h.wet_lb > 0::numeric THEN round(100.0 * COALESCE(c.flower_lb, 0::numeric) / h.wet_lb, 1)
            ELSE NULL::numeric
        END AS flower_pct_of_wet,
    ((('Dried flower, trim and fresh frozen count only packages made DIRECTLY from a '::text || 'harvest - a package repackaged from another package still carries the harvest '::text) || 'name and would be counted twice. Metrc records no split by category on the '::text) || 'harvest itself, so packaged_lb is its authoritative total and the three '::text) || 'categories are directional.'::text AS how_this_is_counted
   FROM h
     LEFT JOIN cat c ON c.month = h.month;
create or replace view public.v_my_alerts as
 SELECT id,
    role,
    severity,
    channel,
    subject,
    body,
    entity_type,
    entity_key,
    source,
    source_ref,
    reminder_number,
    escalated_from,
    raised_on,
    days_open,
    created_at,
    read_at,
    sent_at,
    send_error,
    read_at IS NULL AS unread
   FROM alert_outbox o
  WHERE resolved_at IS NULL AND channel = 'in_app'::text
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), created_at DESC;
create or replace view public.v_my_dashboard_layout as
 SELECT d.page,
    w.widget_key,
    w."position",
    w.visible,
    w.span
   FROM dashboards d
     JOIN dashboard_widgets w ON w.dashboard_id = d.id
  WHERE d.owner = auth.uid()
  ORDER BY d.page, w."position";
create or replace view public.v_my_dashboards as
 SELECT d.dashboard_key,
    d.name,
    d.purpose,
    d.is_default,
    d.sort,
    d.from_template,
    d.created_at,
    count(l.widget_key) AS widgets,
    count(l.widget_key) FILTER (WHERE NOT l.visible) AS hidden,
    max(l.updated_at) AS last_arranged
   FROM user_dashboard d
     LEFT JOIN dashboard_layout l ON l.user_id = d.user_id AND l.page = d.dashboard_key
  WHERE d.user_id = auth.uid()
  GROUP BY d.dashboard_key, d.name, d.purpose, d.is_default, d.sort, d.from_template, d.created_at
  ORDER BY d.is_default DESC, d.sort, d.name;
create or replace view public.v_my_layout as
 SELECT c.key AS widget_key,
    l.page,
    COALESCE(l.title_override, c.label) AS label,
    c.category,
    c.icon,
    c.table_ref AS source,
    c.drill,
    c.format,
    c.hot,
    c.enabled AS widget_enabled,
    l.x,
    l.y,
    l.w,
    l.h,
    l.visible,
    true AS personalised,
    l.updated_at AS arranged_at,
    l.instance_id,
    c.widget_kind,
    c.multi_instance,
    c.options_schema,
    l.config,
    c.label AS catalogue_label
   FROM widget_catalog c
     JOIN dashboard_layout l ON l.widget_key = c.key AND l.user_id = auth.uid()
  WHERE c.enabled;
create or replace view public.v_nav_broken_pages as
 SELECT n.id,
    n.category,
    n.subcategory,
    n.label,
    COALESCE(NULLIF(btrim(n.table_ref), ''::text), NULLIF(btrim(n.view_key), ''::text)) AS points_at,
    'Report page whose relation does not exist - opening it errors. Fix the reference or disable the entry.'::text AS why_it_matters
   FROM nav_registry n
     LEFT JOIN pg_class c ON c.relname = COALESCE(NULLIF(btrim(n.table_ref), ''::text), NULLIF(btrim(n.view_key), ''::text)) AND c.relnamespace = 'public'::regnamespace::oid AND (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char"]))
  WHERE n.enabled AND COALESCE(n.page_kind, 'report'::text) = 'report'::text AND COALESCE(NULLIF(btrim(n.table_ref), ''::text), NULLIF(btrim(n.view_key), ''::text)) IS NOT NULL AND c.oid IS NULL;
create or replace view public.v_offboarding_open as
 SELECT o.id,
    e.employee_code,
    e.full_name,
    o.kind,
    o.voluntary,
    o.last_day,
    o.final_pay_due_on,
    o.final_pay_paid_on IS NULL AND o.final_pay_due_on IS NOT NULL AND o.final_pay_due_on <= CURRENT_DATE AS final_pay_overdue,
    o.ccc_deactivated_on IS NULL AS ccc_still_active,
    e.metrc_agent_badge,
    e.badge_expires,
    NOT o.badge_returned OR NOT o.keys_returned OR NOT o.equipment_returned AS property_outstanding,
    o.system_access_revoked_on IS NULL AS access_still_live,
    o.status
   FROM offboarding o
     JOIN employees e ON e.id = o.employee_id
  WHERE o.status <> 'complete'::text;
create or replace view public.v_on_the_floor as
 SELECT t.id AS time_entry_id,
    e.id AS employee_id,
    e.employee_code,
    e.full_name,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    COALESCE(btrim(s.zone), 'No zone'::text) AS zone,
    st.name AS shift,
    t.clock_in,
    t.work_date,
    t.source,
    t.late_minutes,
    t.early_minutes,
    pd.label AS device,
    round(EXTRACT(epoch FROM now() - t.clock_in) / 3600.0, 2) AS hours_so_far,
    s.work_date + s.planned_start AS planned_start,
    s.work_date + s.planned_end AS planned_end,
    round(EXTRACT(epoch FROM s.work_date + s.planned_end - now()::timestamp without time zone) / 3600.0, 2) AS hours_left_scheduled,
    r.rate,
    round(EXTRACT(epoch FROM now() - t.clock_in) / 3600.0 * r.rate * (1::numeric + COALESCE(r.burden_pct, 0::numeric)), 2) AS cost_so_far_loaded,
    bw.name AS break_window,
    bw.starts_at AS break_from,
    bw.ends_at AS break_to,
    now()::time without time zone >= bw.starts_at AND now()::time without time zone <= bw.ends_at AS on_break_now,
    e.badge_expires,
    e.badge_expires IS NOT NULL AND e.badge_expires < CURRENT_DATE AS licence_lapsed
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     LEFT JOIN employee_schedules s ON s.employee_id = t.employee_id AND s.work_date = t.work_date
     LEFT JOIN shift_templates st ON st.id = s.shift_template_id
     LEFT JOIN departments d ON d.id = COALESCE(s.department_id, e.primary_department_id)
     LEFT JOIN punch_devices pd ON pd.id = t.device_id
     LEFT JOIN break_windows bw ON bw.active AND (bw.department_id IS NULL OR bw.department_id = COALESCE(s.department_id, e.primary_department_id))
     LEFT JOIN LATERAL ( SELECT r2.id,
            r2.employee_id,
            r2.basis,
            r2.rate,
            r2.ot_multiplier,
            r2.burden_pct,
            r2.effective_from,
            r2.effective_to,
            r2.approved_by,
            r2.note,
            r2.effective_from_date
           FROM employee_rates r2
          WHERE r2.employee_id = t.employee_id AND r2.effective_from <= t.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= t.work_date)
          ORDER BY r2.effective_from DESC
         LIMIT 1) r ON true
  WHERE t.clock_in IS NOT NULL AND t.clock_out IS NULL;
create or replace view public.v_onhand_by_room_stage as
 SELECT p.license AS licence,
        CASE
            WHEN p.license = 'MC281714'::text THEN 'CULTIVATION'::text
            WHEN p.license = 'MP281909'::text THEN 'MANUFACTURING'::text
            ELSE p.license
        END AS department,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS room,
    COALESCE(r.stage, 'UNMAPPED — room has no registered role'::text) AS stage,
    COALESCE(r.role, 'not registered in room_roles'::text) AS room_role,
    r.room_name IS NOT NULL AS room_registered,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS ownership,
    count(*) AS tags,
    round(sum(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))) FILTER (WHERE f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))), 2) AS lb,
    sum((p.raw ->> 'Quantity'::text)::numeric) FILTER (WHERE NOT f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))) AS units,
    count(*) FILTER (WHERE (p.raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'RetestPassed'::text])) AS tested_ok,
    count(*) FILTER (WHERE (p.raw ->> 'LabTestingState'::text) ~~* '%fail%'::text) AS failed,
    count(*) FILTER (WHERE NOT (EXISTS ( SELECT 1
           FROM coa_extract c
          WHERE c.package_tag = (p.raw ->> 'Label'::text)))) AS no_coa
   FROM ( SELECT DISTINCT ON (mp.tag) mp.id,
            mp.license,
            mp.tag,
            mp.item_name,
            mp.quantity,
            mp.uom,
            mp.location,
            mp.packaged_on,
            mp.lab_testing_state,
            mp.finished,
            mp.raw,
            mp.synced_at,
            mp.source_state,
            mp.provenance,
            mp.report_as_of
           FROM metrc_packages mp
          WHERE COALESCE((mp.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((mp.raw ->> 'IsFinished'::text)::boolean, false) = false
          ORDER BY mp.tag, (mp.source_state = 'active'::text) DESC NULLS LAST, mp.synced_at DESC NULLS LAST) p
     LEFT JOIN room_roles r ON r.room_name = NULLIF(p.raw ->> 'LocationName'::text, ''::text)
  WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false
  GROUP BY p.license, (
        CASE
            WHEN p.license = 'MC281714'::text THEN 'CULTIVATION'::text
            WHEN p.license = 'MP281909'::text THEN 'MANUFACTURING'::text
            ELSE p.license
        END), (COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text)), (COALESCE(r.stage, 'UNMAPPED — room has no registered role'::text)), (COALESCE(r.role, 'not registered in room_roles'::text)), (r.room_name IS NOT NULL), (COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text)), (
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END);
create or replace view public.v_open_issues as
 WITH latest AS (
         SELECT DISTINCT ON (f.fingerprint) f.id,
            f.run_id,
            f.observed_at,
            f.fingerprint,
            f.severity,
            f.what,
            f.where_it_is,
            f.who_is_accountable,
            f.when_it_started,
            f.why_it_matters,
            f.how_it_was_detected,
            f.what_to_do,
            f.the_arithmetic,
            f.evidence,
            f.record_count,
            f.pounds,
            f.dollars,
            f.drill,
            f.search_text,
            ( SELECT count(*) AS count
                   FROM watchdog_findings x
                  WHERE x.fingerprint = f.fingerprint) AS times_seen,
            ( SELECT min(x.observed_at) AS min
                   FROM watchdog_findings x
                  WHERE x.fingerprint = f.fingerprint) AS first_seen
           FROM watchdog_findings f
          ORDER BY f.fingerprint, f.observed_at DESC
        )
 SELECT l.fingerprint AS issue_key,
    l.severity,
    l.what AS issue,
    l.where_it_is,
    l.who_is_accountable,
    l.when_it_started,
    l.why_it_matters,
    l.what_to_do,
    l.the_arithmetic,
    l.record_count,
    l.pounds,
    l.dollars,
    l.first_seen::date AS first_seen_on,
    l.observed_at::date AS last_seen_on,
    l.times_seen,
    d.decision,
    d.reason AS decision_reason,
    d.decided_by,
    d.decided_at,
    d.review_on,
        CASE
            WHEN d.decision IS NULL THEN 'A DECISION IS REQUIRED'::text
            WHEN d.decision = 'fix'::text THEN (('Being fixed — '::text || COALESCE(d.decided_by, 'someone'::text)) || ', '::text) || d.decided_at::date
            WHEN d.decision = 'leave'::text THEN (('Left as is — '::text || COALESCE(d.decided_by, 'someone'::text)) || ', '::text) || d.decided_at::date
            WHEN d.decision = 'ignore'::text THEN ((('Ignored — '::text || COALESCE(d.decided_by, 'someone'::text)) || ', '::text) || d.decided_at::date) || '. Ignoring is a decision, not a deletion, so it still appears here.'::text
            WHEN d.decision = 'reset'::text THEN 'Reset — awaiting a fresh decision'::text
            ELSE d.decision
        END AS decision_state,
    d.decision IS NULL AS needs_a_decision,
    l.drill,
    l.evidence,
    l.search_text
   FROM latest l
     LEFT JOIN LATERAL ( SELECT x.id,
            x.issue_key,
            x.issue_title,
            x.decision,
            x.reason,
            x.decided_by,
            x.decided_at,
            x.outstanding_when_decided,
            x.detail_when_decided,
            x.review_on,
            x.superseded
           FROM issue_decisions x
          WHERE NOT COALESCE(x.superseded, false) AND (x.issue_key = l.fingerprint OR l.fingerprint ~~ (x.issue_key || '%'::text))
          ORDER BY x.decided_at DESC
         LIMIT 1) d ON true;
create or replace view public.v_open_questions as
 SELECT area,
    question,
    why_it_matters,
    what_is_blocked,
    exposure_lb,
    exposure_dollars,
    days_open,
    first_raised,
    urgency,
    question_key,
    first_raised AS first_raised_date
   FROM ( SELECT open_questions.area,
            open_questions.question,
            open_questions.why_it_matters,
            open_questions.what_is_blocked,
            open_questions.exposure_lb,
            round(open_questions.exposure_lb * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS exposure_dollars,
            CURRENT_DATE - open_questions.first_seen::date AS days_open,
            open_questions.first_seen::date AS first_raised,
                CASE
                    WHEN (CURRENT_DATE - open_questions.first_seen::date) > 30 THEN 'OPEN OVER A MONTH'::text
                    WHEN COALESCE(open_questions.exposure_lb, 0::numeric) > 100::numeric THEN 'HIGH EXPOSURE'::text
                    ELSE 'Open'::text
                END AS urgency,
            open_questions.question_key
           FROM open_questions
          WHERE open_questions.status = 'open'::text
          ORDER BY (COALESCE(open_questions.exposure_lb, 0::numeric)) DESC, open_questions.first_seen) q;
create or replace view public.v_ot_watch as
 WITH pol AS (
         SELECT attendance_policy.ot_weekly_threshold,
            attendance_policy.approaching_ot_within
           FROM attendance_policy
         LIMIT 1
        ), wk AS (
         SELECT t.employee_id,
            date_trunc('week'::text, t.work_date::timestamp with time zone)::date AS week_start,
            sum(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) AS worked_hours
           FROM time_entries t
          WHERE t.clock_in IS NOT NULL AND t.clock_out IS NOT NULL
          GROUP BY t.employee_id, (date_trunc('week'::text, t.work_date::timestamp with time zone)::date)
        )
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    d.name AS department,
    wk.week_start,
    round(wk.worked_hours, 2) AS worked_hours,
    COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold)::numeric AS target_hours,
        CASE
            WHEN e.hours_basis = 'shift'::text THEN round(GREATEST(wk.worked_hours - pol.ot_weekly_threshold, 0::numeric), 2)
            ELSE 0::numeric
        END AS ot_hours,
        CASE
            WHEN e.hours_basis = 'shift'::text THEN round(GREATEST(wk.worked_hours - pol.ot_weekly_threshold, 0::numeric) * r.rate * COALESCE(r.ot_multiplier, 1.5) * (1::numeric + COALESCE(r.burden_pct, 0::numeric)), 2)
            ELSE 0::numeric
        END AS ot_cost_loaded,
        CASE
            WHEN e.hours_basis <> 'shift'::text THEN 'salaried'::text
            WHEN wk.worked_hours > pol.ot_weekly_threshold THEN 'over'::text
            WHEN wk.worked_hours >= (pol.ot_weekly_threshold - pol.approaching_ot_within) THEN 'approaching'::text
            ELSE 'clear'::text
        END AS ot_flag,
    e.hours_basis,
    pol.ot_weekly_threshold::numeric AS ot_threshold
   FROM wk
     CROSS JOIN pol
     JOIN employees e ON e.id = wk.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
     LEFT JOIN LATERAL ( SELECT r2.id,
            r2.employee_id,
            r2.basis,
            r2.rate,
            r2.ot_multiplier,
            r2.burden_pct,
            r2.effective_from,
            r2.effective_to,
            r2.approved_by,
            r2.note,
            r2.effective_from_date
           FROM employee_rates r2
          WHERE r2.employee_id = e.id AND r2.effective_from <= wk.week_start AND (r2.effective_to IS NULL OR r2.effective_to >= wk.week_start)
          ORDER BY r2.effective_from DESC
         LIMIT 1) r ON true;
create or replace view public.v_override_divergence as
 SELECT target_table,
    row_key,
    field_name,
    new_value AS what_we_corrected_it_to,
    old_value AS what_it_was,
    reason,
    set_by_name,
    set_at::date AS corrected_on,
    CURRENT_DATE - set_at::date AS days_standing,
        CASE
            WHEN metrc_sourced THEN 'Corrected in Metrc as well - the record agrees'::text
            ELSE 'CORRECTED HERE ONLY. Metrc is the legal record and still says something else. '::text || 'Until it is fixed in Metrc, an inspector reading Metrc sees the old value.'::text
        END AS standing,
    metrc_sourced AS fixed_in_metrc_too
   FROM tg_overrides o
  WHERE active
  ORDER BY metrc_sourced, set_at;
create or replace view public.v_overrides_active as
 SELECT o.id,
    o.target_table,
    o.row_key,
    o.field_name,
    o.old_value AS metrc_says,
    o.new_value AS we_say,
    o.reason,
    COALESCE(o.set_by_name, '—'::text) AS set_by,
    o.set_at::date AS set_on,
    o.metrc_sourced,
        CASE
            WHEN o.metrc_task_id IS NULL THEN 'not a Metrc field'::text
            WHEN mc.fixed_in_metrc THEN 'fixed in Metrc'::text
            ELSE 'AWAITING FIX IN METRC'::text
        END AS metrc_status
   FROM tg_overrides o
     LEFT JOIN metrc_corrections mc ON mc.id = o.metrc_task_id
  WHERE o.active
  ORDER BY o.set_at DESC;
create or replace view public.v_owner_issue_queue as
 SELECT 'correction'::text AS source,
    cp.id AS item_id,
    cp.raised_at::date AS date_found,
    cp.raised_by,
    cp.severity,
    cp.domain,
    cp.target_object AS where_it_is,
    cp.the_issue AS what_is_wrong,
    cp.the_proposal AS what_is_proposed,
    cp.why_this_is_the_fix AS why_it_works,
    cp.how_it_never_repeats AS how_it_stays_fixed,
    cp.risk_if_wrong,
    cp.rows_affected,
    cp.pounds_affected,
    cp.dollars_affected,
    cp.status,
    cp.status = 'proposed'::text AS needs_your_decision,
    cp.decided_at::date AS date_decided,
    COALESCE(cp.verified_at, cp.applied_at)::date AS date_resolved,
    cp.owner_note
   FROM correction_proposal cp
UNION ALL
 SELECT 'enhancement'::text AS source,
    pe.id AS item_id,
    pe.raised_at::date AS date_found,
    pe.raised_by,
        CASE pe.impact
            WHEN 'high'::text THEN 'elevated'::text
            ELSE 'watch'::text
        END AS severity,
    pe.page AS domain,
    (pe.page || ' — '::text) || pe.section AS where_it_is,
    pe.observation AS what_is_wrong,
    pe.recommendation AS what_is_proposed,
    pe.why_it_matters AS why_it_works,
    'Enhancement, not a defect — nothing breaks if this is never done. Effort: '::text || pe.effort AS how_it_stays_fixed,
    'None. This improves something that already works.'::text AS risk_if_wrong,
    NULL::bigint AS rows_affected,
    NULL::numeric AS pounds_affected,
    NULL::numeric AS dollars_affected,
    pe.status,
    pe.status = 'proposed'::text AS needs_your_decision,
    pe.decided_at::date AS date_decided,
    NULL::date AS date_resolved,
    pe.owner_note
   FROM page_enhancement pe
UNION ALL
 SELECT 'defect'::text AS source,
    wf.id AS item_id,
    wf.observed_at::date AS date_found,
    COALESCE(wf.who_is_accountable, 'platform'::text) AS raised_by,
    wf.severity,
    COALESCE(wf.where_it_is, '—'::text) AS domain,
    COALESCE(wf.where_it_is, '—'::text) AS where_it_is,
    wf.what AS what_is_wrong,
    COALESCE(wf.what_to_do, '—'::text) AS what_is_proposed,
    COALESCE(wf.why_it_matters, '—'::text) AS why_it_works,
    COALESCE(wf.guard_recommendation, 'No guard proposed yet — ask for one before closing this, or it recurs.'::text) AS how_it_stays_fixed,
    NULL::text AS risk_if_wrong,
    wf.record_count AS rows_affected,
    wf.pounds AS pounds_affected,
    wf.dollars AS dollars_affected,
        CASE
            WHEN wf.cleared_at IS NOT NULL THEN 'resolved'::text
            ELSE 'open'::text
        END AS status,
    false AS needs_your_decision,
    NULL::date AS date_decided,
    wf.cleared_at::date AS date_resolved,
    wf.challenge_notes AS owner_note
   FROM watchdog_findings wf
  WHERE wf.cleared_at IS NULL OR wf.cleared_at > (now() - '30 days'::interval);
create or replace view public.v_package_events as
 WITH pkg AS (
         SELECT p.raw ->> 'Label'::text AS tag,
            p.license AS lic,
            (p.raw ->> 'PackagedDate'::text)::date AS packaged_on
           FROM metrc_packages p
        ), xfer AS (
         SELECT t.package_tag,
            t.received_on,
            t.shipped_lb,
            t.manifest_number,
            COALESCE(NULLIF(t.source_row ->> 'Origin Lic.'::text, ''::text), t.licence) AS origin_lic,
            COALESCE(NULLIF(t.source_row ->> 'Dest. Lic.'::text, ''::text), t.destination_licence) AS dest_lic,
            t.destination_facility,
            t.source_row ->> 'Origin Facility'::text AS origin_facility
           FROM metrc_rpt_package_transfers t
          WHERE t.shipped_lb IS NOT NULL AND t.shipped_lb <> 0::numeric
        )
 SELECT p.raw ->> 'Label'::text AS package_tag,
    (p.raw ->> 'PackagedDate'::text)::date AS event_date,
    'CREATED'::text AS event,
    f_to_pounds(COALESCE((p.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) AS lb_delta,
    p.license AS licence,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS room,
    NULL::text AS counterparty
   FROM metrc_packages p
  WHERE f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) AND COALESCE((p.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric) > 0::numeric
UNION ALL
 SELECT x.package_tag,
    x.received_on AS event_date,
    'SHIPPED'::text AS event,
    - abs(x.shipped_lb) AS lb_delta,
    k.lic AS licence,
    NULL::text AS room,
    COALESCE(x.destination_facility, x.dest_lic) AS counterparty
   FROM xfer x
     JOIN pkg k ON k.tag = x.package_tag
  WHERE upper(btrim(x.origin_lic)) = upper(btrim(k.lic))
UNION ALL
 SELECT x.package_tag,
    x.received_on AS event_date,
    'RECEIVED'::text AS event,
    abs(x.shipped_lb) AS lb_delta,
    k.lic AS licence,
    NULL::text AS room,
    COALESCE(x.origin_facility, x.origin_lic) AS counterparty
   FROM xfer x
     JOIN pkg k ON k.tag = x.package_tag
  WHERE upper(btrim(x.dest_lic)) = upper(btrim(k.lic)) AND upper(btrim(COALESCE(x.origin_lic, ''::text))) <> upper(btrim(k.lic)) AND x.received_on > k.packaged_on
UNION ALL
 SELECT a.package_tag,
    a.adjusted_on AS event_date,
    'ADJUSTED'::text AS event,
    f_to_pounds(a.quantity, a.uom) AS lb_delta,
    a.licence,
    NULL::text AS room,
    a.reason AS counterparty
   FROM metrc_rpt_adjustments a
  WHERE a.quantity IS NOT NULL AND a.quantity <> 0::numeric
UNION ALL
 SELECT btrim(parent.tag) AS package_tag,
    (c.raw ->> 'PackagedDate'::text)::date AS event_date,
    'CONSUMED INTO CHILD'::text AS event,
    - (f_to_pounds(COALESCE((c.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(c.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) / GREATEST(array_length(string_to_array(c.raw ->> 'SourcePackageLabels'::text, ', '::text), 1), 1)::numeric) AS lb_delta,
    c.license AS licence,
    NULL::text AS room,
    c.raw ->> 'Label'::text AS counterparty
   FROM metrc_packages c,
    LATERAL unnest(string_to_array(c.raw ->> 'SourcePackageLabels'::text, ', '::text)) parent(tag)
  WHERE NULLIF(c.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL AND f_is_weight(COALESCE(NULLIF(c.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) AND COALESCE((c.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric) > 0::numeric;
create or replace view public.v_packages_missing_coa as
 SELECT license AS licence,
    raw ->> 'Label'::text AS package_tag,
    raw #>> '{Item,Name}'::text[] AS item,
    f_strain_from_item(raw #>> '{Item,Name}'::text[]) AS strain,
    COALESCE(NULLIF(raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    NULLIF(raw ->> 'LocationName'::text, ''::text) AS room,
    (raw ->> 'PackagedDate'::text)::date AS packaged_on,
    EXTRACT(year FROM (raw ->> 'PackagedDate'::text)::date)::integer AS yr,
    CURRENT_DATE - ((raw ->> 'PackagedDate'::text)::date) AS days_old,
    raw ->> 'LabTestingState'::text AS metrc_lab_state,
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN round(f_to_pounds((raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3)
            ELSE NULL::numeric
        END AS lb,
        CASE
            WHEN NOT f_is_weight(COALESCE(NULLIF(raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN (raw ->> 'Quantity'::text)::numeric
            ELSE NULL::numeric
        END AS units,
    NULLIF(raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
    NULLIF(raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
    (raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'RetestPassed'::text]) AS metrc_says_passed_but_no_coa,
        CASE
            WHEN (raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'RetestPassed'::text]) THEN 'TESTED PER METRC, NO CERTIFICATE ON FILE — fetch the document'::text
            WHEN (raw ->> 'LabTestingState'::text) = 'SubmittedForTesting'::text THEN 'at the laboratory now — no result yet'::text
            WHEN (raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN 'never submitted for testing'::text
            ELSE COALESCE(raw ->> 'LabTestingState'::text, '(no state)'::text)
        END AS verdict
   FROM metrc_packages p
  WHERE COALESCE((raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((raw ->> 'IsFinished'::text)::boolean, false) = false AND NOT (EXISTS ( SELECT 1
           FROM coa_extract c
          WHERE c.package_tag = (p.raw ->> 'Label'::text)));
create or replace view public.v_page_design_queue as
 SELECT module,
    category,
    subcategory,
    label,
    table_ref,
    page_kind,
    archetype,
        CASE
            WHEN archetype IS NULL THEN 'NEEDS A DESIGN DECISION'::text
            ELSE 'assigned'::text
        END AS state
   FROM nav_registry n
  WHERE enabled
  ORDER BY (archetype IS NOT NULL), module, subcategory NULLS FIRST, label;
create or replace view public.v_page_drilldown_coverage as
 WITH surfaces AS (
         SELECT n.view_key,
            n.label,
            n.category,
            n.subcategory,
            n.surface,
            n.table_ref,
            n.admin_only
           FROM nav_registry n
          WHERE n.enabled AND n.table_ref IS NOT NULL
        ), cols AS (
         SELECT s.view_key,
            s.label,
            s.category,
            s.subcategory,
            s.surface,
            s.table_ref,
            s.admin_only,
            array_agg(lower(a.attname::text) ORDER BY a.attnum) AS columns
           FROM surfaces s
             JOIN pg_class c ON c.relname = s.table_ref AND (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char", 'f'::"char", 'p'::"char"]))
             JOIN pg_namespace ns ON ns.oid = c.relnamespace AND ns.nspname = 'public'::name
             JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
          GROUP BY s.view_key, s.label, s.category, s.subcategory, s.surface, s.table_ref, s.admin_only
        )
 SELECT view_key,
    label,
    category,
    subcategory,
    table_ref,
    admin_only,
    columns && ARRAY['package_tag'::text, 'tag'::text, 'package'::text, 'package_label'::text] AS reaches_package,
    columns && ARRAY['manifest_number'::text, 'manifest'::text, 'inbound_manifest'::text] AS reaches_manifest,
    columns && ARRAY['harvest'::text, 'harvest_name'::text, 'harvest_batch'::text, 'source_harvest'::text] AS reaches_harvest,
    columns && ARRAY['licence'::text, 'license'::text] AS carries_licence,
    columns && ARRAY['search_text'::text] AS has_search_text,
        CASE
            WHEN columns && ARRAY['package_tag'::text, 'tag'::text, 'package'::text, 'package_label'::text] THEN 'Package - full documents'::text
            WHEN columns && ARRAY['manifest_number'::text, 'manifest'::text, 'inbound_manifest'::text] THEN 'Manifest only'::text
            WHEN columns && ARRAY['harvest'::text, 'harvest_name'::text, 'harvest_batch'::text, 'source_harvest'::text] THEN 'Harvest - documents via its packages'::text
            ELSE 'No document key'::text
        END AS document_reach
   FROM cols;
create or replace view public.v_page_filter_coverage as
 WITH cols AS (
         SELECT c_1.oid,
            a.attname,
            format_type(a.atttypid, a.atttypmod) AS typ
           FROM pg_class c_1
             JOIN pg_attribute a ON a.attrelid = c_1.oid
          WHERE a.attnum > 0 AND NOT a.attisdropped
        )
 SELECT n.category,
    n.subcategory,
    n.label,
    n.surface,
    n.view_key,
    n.table_ref,
        CASE c.relkind
            WHEN 'r'::"char" THEN 'table'::text
            WHEN 'm'::"char" THEN 'materialized view'::text
            ELSE 'view'::text
        END AS source_kind,
    (EXISTS ( SELECT 1
           FROM cols x
          WHERE x.oid = c.oid AND x.typ ~~ 'text%'::text AND x.attname <> 'raw'::name)) AS has_search,
    (EXISTS ( SELECT 1
           FROM cols x
          WHERE x.oid = c.oid AND x.attname ~ '(_date|_on$|_on_|_at$|^date|^month|period)'::text)) AS has_date_filter,
    (EXISTS ( SELECT 1
           FROM cols x
          WHERE x.oid = c.oid AND (x.typ ~~ 'date%'::text OR x.typ ~~ 'timestamp%'::text))) AS has_a_date_column,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM cols x
              WHERE x.oid = c.oid AND x.attname ~ '(_date|_on$|_on_|_at$|^date|^month|period)'::text)) THEN 'Date filter available'::text
            WHEN (EXISTS ( SELECT 1
               FROM cols x
              WHERE x.oid = c.oid AND (x.typ ~~ 'date%'::text OR x.typ ~~ 'timestamp%'::text))) THEN 'FIXABLE: holds a date column but not named so the filter can find it. Append an alias ending _date.'::text
            ELSE 'No date filter: this page holds no date at all. For configuration, reference and rate '::text || 'tables that is correct. For anything else a meaningful date needs choosing.'::text
        END AS date_filter_status
   FROM nav_registry n
     JOIN pg_class c ON c.oid = to_regclass('public.'::text || n.table_ref)::oid
  WHERE n.enabled AND n.table_ref IS NOT NULL AND n.table_ref <> ''::text;
create or replace view public.v_page_wiring as
 WITH pages AS (
         SELECT n.view_key,
            n.label,
            n.category,
            n.subcategory,
            n.report_group,
            n.table_ref,
            n.page_kind,
            c_1.oid AS obj_oid,
                CASE c_1.relkind
                    WHEN 'r'::"char" THEN 'table'::text
                    WHEN 'v'::"char" THEN 'view'::text
                    WHEN 'm'::"char" THEN 'materialized view'::text
                    WHEN 'p'::"char" THEN 'partitioned table'::text
                    ELSE NULL::text
                END AS object_kind
           FROM nav_registry n
             LEFT JOIN pg_class c_1 ON c_1.relname = n.table_ref AND c_1.relnamespace = 'public'::regnamespace::oid AND (c_1.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char", 'p'::"char"]))
          WHERE n.enabled
        ), cols AS (
         SELECT p_1.view_key,
            count(*) FILTER (WHERE a.attnum > 0 AND NOT a.attisdropped) AS fields,
            count(*) FILTER (WHERE a.attnum > 0 AND NOT a.attisdropped AND (t.typname = ANY (ARRAY['date'::name, 'timestamp'::name, 'timestamptz'::name]))) AS date_columns
           FROM pages p_1
             LEFT JOIN pg_attribute a ON a.attrelid = p_1.obj_oid
             LEFT JOIN pg_type t ON t.oid = a.atttypid
          GROUP BY p_1.view_key
        )
 SELECT p.view_key,
    p.label,
    p.category,
    p.subcategory,
    p.report_group,
    p.table_ref,
    p.object_kind,
    COALESCE(c.fields, 0::bigint) AS fields,
    ( SELECT count(*) AS count
           FROM nav_role_visibility v
          WHERE v.view_key = p.view_key AND v.visible) AS roles_who_can_see,
    (EXISTS ( SELECT 1
           FROM report_registry r
          WHERE r.fact_view = p.table_ref)) AS in_report_registry,
    COALESCE(c.date_columns, 0::bigint) AS date_columns,
    ( SELECT count(*) AS count
           FROM brain_claims b
          WHERE b.covers_object = p.table_ref) AS claims_proving_it,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM nav_role_visibility v
              WHERE v.view_key = p.view_key AND v.visible)) = 0 THEN 'INVISIBLE - no role can open this page'::text
            WHEN p.page_kind = 'application'::text THEN 'WIRED - application screen, no table_ref by design'::text
            WHEN p.table_ref IS NULL THEN 'NO TARGET - a report page must name a table or view'::text
            WHEN p.object_kind IS NULL THEN 'BROKEN - points at an object that does not exist'::text
            WHEN COALESCE(c.fields, 0::bigint) = 0 THEN 'BROKEN - target has no columns'::text
            ELSE 'WIRED'::text
        END AS wiring,
    'THE ISSUE: a page that points at nothing, has no columns, or that no role can open is a dead link that LOOKS like coverage.'::text AS what_is_wrong,
    'Fix the table_ref, grant visibility, or disable the page. Never leave a dead page enabled - in the menu it is indistinguishable from a working one.'::text AS what_to_do,
    COALESCE(c.date_columns, 0::bigint) = 0 AND p.page_kind = 'report'::text AS no_date_range_possible,
    p.page_kind
   FROM pages p
     LEFT JOIN cols c ON c.view_key = p.view_key;
create or replace view public.v_pay_rate_confidence as
 SELECT count(*) AS rates_on_file,
    count(*) FILTER (WHERE provisional) AS provisional,
    count(*) FILTER (WHERE NOT provisional) AS approved,
    round(100.0 * count(*) FILTER (WHERE provisional)::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_provisional,
    count(*) > 0 AND count(*) FILTER (WHERE provisional) = 0 AS safe_to_quote,
        CASE
            WHEN count(*) = 0 THEN ('NO RATES ARE VISIBLE TO YOU. Either none are on file, or your account is not '::text || 'cleared to read compensation. This is NOT an all-clear — nothing here says any '::text) || 'rate has been approved, and no payroll or margin figure should be quoted from it.'::text
            WHEN count(*) FILTER (WHERE provisional) = 0 THEN 'Every rate has been approved by a person. Payroll figures can be quoted.'::text
            ELSE ((((('ESTIMATE ONLY. '::text || count(*) FILTER (WHERE provisional)) || ' of '::text) || count(*)) || ' rates are placeholders nobody has approved. Any payroll, labour cost or margin '::text) || 'figure built on these is an estimate and must be presented as one. Human '::text) || 'Resources replaces them during onboarding.'::text
        END AS how_to_present_it
   FROM employee_rates;
create or replace view public.v_payroll_forecast as
 SELECT e.employee_code,
    e.full_name,
    COALESCE(rc.name, '—'::text) AS "position",
    TRIM(BOTH ' +'::text FROM COALESCE(d.name, ''::text) ||
        CASE
            WHEN d2.name IS NOT NULL THEN ' + '::text || d2.name
            ELSE ''::text
        END) AS departments,
    r.basis,
    r.rate,
    COALESCE(e.weekly_target_hours, 40::numeric) AS planned_hours,
    round(b.base, 2) AS base_weekly_cost,
    round(b.base * (1::numeric + r.burden_pct), 2) AS loaded_weekly_cost,
    round(b.base * (1::numeric + r.burden_pct) * 52::numeric, 0) AS annualized_loaded_cost
   FROM employees e
     JOIN LATERAL ( SELECT r_1.id,
            r_1.employee_id,
            r_1.basis,
            r_1.rate,
            r_1.ot_multiplier,
            r_1.burden_pct,
            r_1.effective_from,
            r_1.effective_to,
            r_1.approved_by,
            r_1.note
           FROM employee_rates r_1
          WHERE r_1.employee_id = e.id AND r_1.effective_from <= CURRENT_DATE AND (r_1.effective_to IS NULL OR r_1.effective_to >= CURRENT_DATE)
          ORDER BY r_1.effective_from DESC
         LIMIT 1) r ON true
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN r.basis = 'weekly_salary'::pay_basis THEN r.rate
                    ELSE LEAST(COALESCE(e.weekly_target_hours, 40::numeric), 40::numeric) * r.rate + GREATEST(COALESCE(e.weekly_target_hours, 40::numeric) - 40::numeric, 0::numeric) * r.rate * r.ot_multiplier
                END AS base) b
     LEFT JOIN roles_catalog rc ON rc.id = e.primary_role_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
     LEFT JOIN departments d2 ON d2.id = e.secondary_department_id
  WHERE e.terminated_on IS NULL;
create or replace view public.v_payroll_journal as
 SELECT r.id AS pay_run_id,
    r.run_no,
    p.pay_date,
    COALESCE(l.cost_class, d.cost_class, 'G_AND_A'::text) AS cost_class,
    cc.cogs,
    cc.irc_280e_deductible,
    COALESCE(d.name, 'Unassigned'::text) AS department,
        CASE
            WHEN l.earning_code IS NOT NULL THEN 'debit'::text
            ELSE 'credit'::text
        END AS side,
    COALESCE(l.earning_code, l.deduction_code) AS code,
    COALESCE(l.gl_account, m.gl_code, m.qbo_account_name) AS gl_account,
    sum(l.amount) AS amount
   FROM pay_run_lines l
     JOIN pay_runs r ON r.id = l.pay_run_id
     JOIN pay_periods p ON p.id = r.pay_period_id
     LEFT JOIN departments d ON d.id = l.department_id
     LEFT JOIN cost_classes cc ON cc.code = COALESCE(l.cost_class, d.cost_class, 'G_AND_A'::text)
     LEFT JOIN qbo_account_map m ON m.purpose =
        CASE COALESCE(l.cost_class, d.cost_class, 'G_AND_A'::text)
            WHEN 'DIRECT_PROD'::text THEN 'wages_direct_production'::text
            WHEN 'INDIRECT_PROD'::text THEN 'wages_indirect_production'::text
            WHEN 'SELLING'::text THEN 'wages_selling'::text
            ELSE 'wages_g_and_a'::text
        END
  WHERE r.status = ANY (ARRAY['approved'::text, 'paid'::text])
  GROUP BY r.id, r.run_no, p.pay_date, l.cost_class, d.cost_class, cc.cogs, cc.irc_280e_deductible, d.name, l.earning_code, l.deduction_code, l.gl_account, m.gl_code, m.qbo_account_name;
create or replace view public.v_payroll_week as
 SELECT e.id AS employee_id,
    e.full_name,
    date_trunc('week'::text, t.work_date::timestamp with time zone)::date AS week_start,
    sum(t.productive_hours) AS hours,
    r.basis,
    r.rate,
    r.ot_multiplier,
    r.burden_pct,
        CASE
            WHEN r.basis = 'weekly_salary'::pay_basis THEN r.rate
            ELSE LEAST(sum(t.productive_hours), 40::numeric) * r.rate + GREATEST(sum(t.productive_hours) - 40::numeric, 0::numeric) * r.rate * r.ot_multiplier
        END * (1::numeric + r.burden_pct) AS loaded_weekly_cost
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     JOIN employee_rates r ON r.employee_id = e.id AND t.work_date >= r.effective_from AND (r.effective_to IS NULL OR t.work_date <= r.effective_to)
  GROUP BY e.id, e.full_name, (date_trunc('week'::text, t.work_date::timestamp with time zone)), r.basis, r.rate, r.ot_multiplier, r.burden_pct;
create or replace view public.v_payroll_ytd as
 SELECT l.employee_id,
    e.employee_code,
    e.full_name,
    EXTRACT(year FROM p.pay_date)::integer AS tax_year,
    sum(l.amount) FILTER (WHERE l.earning_code IS NOT NULL) AS gross_ytd,
    sum(l.amount) FILTER (WHERE l.earning_code IS NOT NULL AND l.taxable) AS taxable_ytd,
    sum(l.amount) FILTER (WHERE l.deduction_code IS NOT NULL) AS deductions_ytd,
    sum(l.hours) FILTER (WHERE l.earning_code = 'REG'::text) AS regular_hours_ytd,
    sum(l.hours) FILTER (WHERE l.earning_code = 'OT'::text) AS ot_hours_ytd,
    sum(l.amount) FILTER (WHERE l.earning_code IS NOT NULL) - COALESCE(sum(l.amount) FILTER (WHERE l.deduction_code IS NOT NULL), 0::numeric) AS net_ytd
   FROM pay_run_lines l
     JOIN pay_runs r ON r.id = l.pay_run_id AND (r.status = ANY (ARRAY['approved'::text, 'paid'::text]))
     JOIN pay_periods p ON p.id = r.pay_period_id
     JOIN employees e ON e.id = l.employee_id
  GROUP BY l.employee_id, e.employee_code, e.full_name, (EXTRACT(year FROM p.pay_date));
create or replace view public.v_pipeline_run_status as
 SELECT id,
    pipeline,
    brand,
    sku,
    category,
    material_name,
    quantity,
    uom,
    source_kind,
    source_ref,
    started,
    current_stage,
    stages_done,
    stages_total,
    hours_in_current_stage,
    total_hours_elapsed,
    stage_target_hours,
    stage_overdue,
    completed,
    finished_good_lot,
    started AS started_date
   FROM ( SELECT r.id,
            p.name AS pipeline,
            r.brand,
            r.sku,
            r.category,
            r.material_name,
            r.quantity,
            r.uom,
            r.source_kind,
            r.source_ref,
            r.started_at::date AS started,
            s.name AS current_stage,
            ( SELECT count(*) AS count
                   FROM pipeline_stage_events e
                  WHERE e.run_id = r.id AND e.exited_at IS NOT NULL) AS stages_done,
            ( SELECT count(*) AS count
                   FROM pipeline_stages ps
                  WHERE ps.pipeline_id = r.pipeline_id) AS stages_total,
            round(EXTRACT(epoch FROM now() - COALESCE(( SELECT max(e.entered_at) AS max
                   FROM pipeline_stage_events e
                  WHERE e.run_id = r.id AND e.exited_at IS NULL), r.started_at)) / 3600::numeric, 1) AS hours_in_current_stage,
            round(EXTRACT(epoch FROM COALESCE(r.completed_at, now()) - r.started_at) / 3600::numeric, 1) AS total_hours_elapsed,
            s.target_hours AS stage_target_hours,
            r.completed_at IS NULL AND s.target_hours IS NOT NULL AND (EXTRACT(epoch FROM now() - COALESCE(( SELECT max(e.entered_at) AS max
                   FROM pipeline_stage_events e
                  WHERE e.run_id = r.id AND e.exited_at IS NULL), r.started_at)) / 3600::numeric) > s.target_hours AS stage_overdue,
            r.completed_at IS NOT NULL AS completed,
            r.finished_good_lot
           FROM pipeline_runs r
             JOIN pipelines p ON p.id = r.pipeline_id
             LEFT JOIN pipeline_stages s ON s.id = r.current_stage_id
          ORDER BY r.started_at DESC) q;
create or replace view public.v_pipeline_stage_aging as
 SELECT p.name AS pipeline,
    ps.stage_no,
    ps.name AS stage,
    ps.target_hours,
    count(e.id) AS times_entered,
    round(avg(EXTRACT(epoch FROM COALESCE(e.exited_at, now()) - e.entered_at) / 3600::numeric), 1) AS avg_hours,
    round(max(EXTRACT(epoch FROM COALESCE(e.exited_at, now()) - e.entered_at) / 3600::numeric), 1) AS max_hours
   FROM pipeline_stages ps
     JOIN pipelines p ON p.id = ps.pipeline_id
     LEFT JOIN pipeline_stage_events e ON e.stage_id = ps.id
  GROUP BY p.name, ps.stage_no, ps.name, ps.target_hours
  ORDER BY p.name, ps.stage_no;
create or replace view public.v_plan_room_floor as
 SELECT flower_room,
    min(harvest_date) AS first_planned_pull,
    COALESCE(( SELECT harvest_alert_rules.threshold
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.rule_key = 'plan_match_floor_days'::text AND harvest_alert_rules.active), 3::numeric)::integer AS floor_days,
    min(harvest_date) - COALESCE(( SELECT harvest_alert_rules.threshold
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.rule_key = 'plan_match_floor_days'::text AND harvest_alert_rules.active), 3::numeric)::integer AS floor_date
   FROM harvest_pulls p
  WHERE flower_room IS NOT NULL
  GROUP BY flower_room;
create or replace view public.v_plant_census as
 WITH rpt_day AS (
         SELECT max(metrc_rpt_point_in_time.as_of_date) AS d
           FROM metrc_rpt_point_in_time
        ), report AS (
         SELECT p.tag,
            p.location AS room,
            p.status_current AS phase,
            NULLIF(p.strain, ''::text) AS strain
           FROM metrc_rpt_point_in_time p,
            rpt_day
          WHERE p.as_of_date = rpt_day.d AND p.record_type = 'Plant'::text AND (p.status_current = ANY (ARRAY['Flowering'::text, 'Vegetative'::text]))
        ), api AS (
         SELECT p.tag,
            COALESCE(NULLIF(p.room, ''::text), p.raw ->> 'LocationName'::text) AS room,
            initcap(p.source_state) AS phase,
            NULLIF(p.strain, ''::text) AS strain,
            p.synced_at
           FROM metrc_plants p
          WHERE p.source_state = ANY (ARRAY['flowering'::text, 'vegetative'::text])
        )
 SELECT COALESCE(a.tag, r.tag) AS tag,
    COALESCE(a.room, r.room) AS room,
    COALESCE(a.phase, r.phase) AS phase,
    COALESCE(a.strain, r.strain) AS strain,
        CASE
            WHEN a.tag IS NOT NULL AND r.tag IS NOT NULL THEN 'both'::text
            WHEN a.tag IS NULL THEN 'metrc report only'::text
            ELSE 'metrc api only'::text
        END AS source,
    a.tag IS NOT NULL AS in_api_mirror,
    r.tag IS NOT NULL AS in_metrc_report,
    a.synced_at AS api_synced_at,
    ( SELECT rpt_day.d
           FROM rpt_day) AS report_as_of,
    CURRENT_DATE - (( SELECT rpt_day.d
           FROM rpt_day)) AS report_age_days,
        CASE
            WHEN a.tag IS NOT NULL AND r.tag IS NOT NULL THEN 'Both of Metrc''s paths agree this plant is standing.'::text
            WHEN a.tag IS NULL THEN 'Metrc''s own point-in-time report holds this plant; the API sync has never returned it. Real plant, missing mirror - do not read its absence from metrc_plants as an absence from the room.'::text
            ELSE ('The API returned this plant and the report predates it by '::text || (CURRENT_DATE - (( SELECT rpt_day.d
               FROM rpt_day)))) || ' days. Expected for anything that moved since the export.'::text
        END AS provenance_note,
        CASE
            WHEN a.room IS NOT NULL AND r.room IS NOT NULL AND a.room IS DISTINCT FROM r.room THEN (('ROOM DISAGREEMENT - api says '::text || a.room) || ', report says '::text) || r.room
            ELSE NULL::text
        END AS room_disagreement
   FROM api a
     FULL JOIN report r ON r.tag = a.tag;
create or replace view public.v_plant_history as
 SELECT license,
    date_trunc('month'::text, planted_on::timestamp with time zone)::date AS month_date,
    to_char(planted_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
    count(*)::numeric AS plants_planted,
    count(DISTINCT strain)::numeric AS strains_planted,
    string_agg(DISTINCT strain, ', '::text) AS strains,
    count(*) FILTER (WHERE source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))::numeric AS still_alive,
    count(*) FILTER (WHERE source_state = 'inactive'::text)::numeric AS harvested_or_retired
   FROM metrc_plants
  WHERE planted_on IS NOT NULL
  GROUP BY license, (date_trunc('month'::text, planted_on::timestamp with time zone)), (to_char(planted_on::timestamp with time zone, 'YYYY-MM'::text))
  ORDER BY (date_trunc('month'::text, planted_on::timestamp with time zone)::date) DESC;
create or replace view public.v_plant_loss_by_batch as
 SELECT 'destroyed plant'::text AS kind,
    d.plant_batch,
    d.strain,
    d.location,
    d.phase AS phase_when_destroyed,
    d.destroyed_on AS happened_on,
    count(*)::numeric AS plants,
    NULL::numeric AS weight_qty,
    NULL::text AS uom,
    COALESCE(max(d.destroyed_note), 'no reason recorded in Metrc'::text) AS reason,
    d.licence,
    'Metrc records this against the PLANT BATCH, not a harvest. It cannot be attributed to a '::text || 'harvest without inventing a link.'::text AS attribution_note
   FROM metrc_rpt_plants_destroyed d
  WHERE d.destroyed_on IS NOT NULL
  GROUP BY d.plant_batch, d.strain, d.location, d.phase, d.destroyed_on, d.licence
UNION ALL
 SELECT 'plant waste'::text AS kind,
    w.plant_batch,
    NULL::text AS strain,
    NULL::text AS location,
    NULL::text AS phase_when_destroyed,
    w.waste_date AS happened_on,
    w.total_plants AS plants,
    w.waste_qty AS weight_qty,
    w.uom,
    COALESCE(w.reason, 'no reason recorded in Metrc'::text) ||
        CASE
            WHEN w.waste_method IS NOT NULL THEN (' ('::text || w.waste_method) || ')'::text
            ELSE ''::text
        END AS reason,
    w.licence,
    'Metrc records this against the PLANT BATCH, not a harvest. Harvest-stage waste is separate '::text || 'and appears as waste_lb in v_harvest_water_and_yield.'::text AS attribution_note
   FROM metrc_rpt_plant_waste w;
create or replace view public.v_plant_mirror_balance as
 WITH rpt_day AS (
         SELECT max(metrc_rpt_point_in_time.as_of_date) AS d
           FROM metrc_rpt_point_in_time
        ), rpt AS (
         SELECT p.location AS room,
            count(*) AS metrc_report_plants
           FROM metrc_rpt_point_in_time p,
            rpt_day
          WHERE p.as_of_date = rpt_day.d AND p.status_current = 'Flowering'::text
          GROUP BY p.location
        ), mirror AS (
         SELECT COALESCE(p.raw ->> 'LocationName'::text, '(no location on the record)'::text) AS room,
            count(*) AS our_mirror_plants,
            max(p.synced_at) AS last_synced
           FROM metrc_plants p
          WHERE p.source_state = 'flowering'::text
          GROUP BY (COALESCE(p.raw ->> 'LocationName'::text, '(no location on the record)'::text))
        )
 SELECT COALESCE(r.room, m.room) AS room,
    COALESCE(r.metrc_report_plants, 0::bigint) AS metrc_report_plants,
    COALESCE(m.our_mirror_plants, 0::bigint) AS our_mirror_plants,
    COALESCE(m.our_mirror_plants, 0::bigint) - COALESCE(r.metrc_report_plants, 0::bigint) AS gap,
    ( SELECT rpt_day.d
           FROM rpt_day) AS report_as_of,
    CURRENT_DATE - (( SELECT rpt_day.d
           FROM rpt_day)) AS report_age_days,
    m.last_synced,
        CASE
            WHEN COALESCE(m.our_mirror_plants, 0::bigint) = COALESCE(r.metrc_report_plants, 0::bigint) THEN 'BALANCED'::text
            WHEN COALESCE(m.our_mirror_plants, 0::bigint) = 0 THEN (('THE MIRROR HOLDS NONE OF THIS ROOM. Metrc reports '::text || r.metrc_report_plants) || ' plants standing here. Do NOT read this room as empty - read it as unsynced. '::text) || 'This exact state was escalated as an operational emergency on 13 Aug 2026 and the room was full.'::text
            WHEN COALESCE(m.our_mirror_plants, 0::bigint) < COALESCE(r.metrc_report_plants, 0::bigint) THEN ('MIRROR SHORT by '::text || (r.metrc_report_plants - m.our_mirror_plants)) || ' plants. The sync has not fetched them; they are not missing from the facility.'::text
            ELSE ('MIRROR OVER by '::text || (m.our_mirror_plants - r.metrc_report_plants)) || ' plants - the mirror holds plants the report does not. Either the report is older than a takedown, or a tag was not retired.'::text
        END AS verdict,
        CASE
            WHEN (CURRENT_DATE - (( SELECT rpt_day.d
               FROM rpt_day))) > 2 THEN ('The report side is '::text || (CURRENT_DATE - (( SELECT rpt_day.d
               FROM rpt_day)))) || ' days old, so a small gap may simply be movement since. A gap the size of a whole room is not.'::text
            ELSE NULL::text
        END AS staleness_note
   FROM rpt r
     FULL JOIN mirror m ON m.room = r.room
  WHERE COALESCE(r.room, m.room) ~~* 'Flower Room%'::text;
create or replace view public.v_policy_conformance as
 WITH corrected AS (
         SELECT l.id,
            l.ran_at,
            l.run_id,
            l.checker_key,
            l.policy_key,
            l.subject_kind,
            l.subject_ref,
            l.verdict,
            l.numerator,
            l.denominator,
            l.value_a,
            l.value_b,
            l.pct_apart,
            l.data_as_of,
            l.pounds,
            l.dollars,
            l.the_arithmetic,
            l.drill,
            l.evidence,
            l.note,
                CASE
                    WHEN c.checker_key IS NOT NULL THEN c.right_policy_key
                    ELSE l.policy_key
                END AS effective_policy_key
           FROM conformance_ledger l
             LEFT JOIN ledger_label_correction c ON c.checker_key = l.checker_key AND c.subject_ref = l.subject_ref AND c.wrong_policy_key = l.policy_key
        ), claimed AS (
         SELECT DISTINCT unnest(c.policy_keys) AS policy_key
           FROM checker_registry c
          WHERE c.enabled
        ), latest AS (
         SELECT DISTINCT ON (corrected.effective_policy_key) corrected.effective_policy_key AS policy_key,
            corrected.verdict AS latest_verdict,
            corrected.ran_at AS last_verdict_at
           FROM corrected
          WHERE corrected.effective_policy_key IS NOT NULL
          ORDER BY corrected.effective_policy_key, corrected.ran_at DESC, corrected.id DESC
        ), history AS (
         SELECT corrected.effective_policy_key AS policy_key,
            count(*) AS verdicts,
            count(*) FILTER (WHERE corrected.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AS failures
           FROM corrected
          WHERE corrected.effective_policy_key IS NOT NULL
          GROUP BY corrected.effective_policy_key
        )
 SELECT p.policy_key,
    p.section,
    p.title,
    p.severity,
    p.enforced AS repo_has_an_enforcer,
    cl.policy_key IS NOT NULL AS a_checker_claims_it,
    h.verdicts,
    lt.last_verdict_at,
    h.failures,
        CASE
            WHEN lt.latest_verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text]) THEN 'FAILING NOW'::text
            WHEN lt.policy_key IS NOT NULL THEN 'PASSING'::text
            WHEN cl.policy_key IS NOT NULL THEN 'CLAIMED BUT SILENT'::text
            WHEN p.enforced THEN 'ENFORCED IN REPO, NOT REPORTING'::text
            ELSE 'MEMORY ONLY'::text
        END AS state,
        CASE
            WHEN lt.policy_key IS NOT NULL THEN NULL::text
            WHEN cl.policy_key IS NOT NULL THEN 'A checker names this policy but has never written a verdict for it. The check may '::text || 'run and report nowhere, which looks identical to not running.'::text
            WHEN p.enforced THEN 'The repository enforces this at build or hook time, so it is not unguarded -- but '::text || 'nothing in the database can confirm it, and CI verdicts are not recorded here.'::text
            ELSE 'No gate, no hook, no cron. This rule holds only while somebody remembers it.'::text
        END AS read_this_first,
    lt.latest_verdict,
    h.failures > 0 AND (lt.latest_verdict <> ALL (ARRAY['FAIL'::text, 'DISAGREE'::text])) AS failed_before_now_passing
   FROM policy_registry p
     LEFT JOIN claimed cl ON cl.policy_key = p.policy_key
     LEFT JOIN latest lt ON lt.policy_key = p.policy_key
     LEFT JOIN history h ON h.policy_key = p.policy_key
  WHERE p.active;
create or replace view public.v_potency_analytes as
 SELECT package_tag,
    item,
    f_strain_from_item(item) AS strain,
    f_product_line(item, category, test_name) AS product_line,
    packaged_licence AS licence,
    lab_facility AS lab,
    test_date,
    EXTRACT(year FROM test_date)::integer AS yr,
    to_char(test_date::timestamp with time zone, 'YYYY-MM'::text) AS month,
    EXTRACT(quarter FROM test_date)::integer AS quarter,
    test_name,
    upper(regexp_replace(test_name, '\s*\((%|mg/g|ppm|ppb|CFU/g|AW)\).*$'::text, ''::text)) AS analyte,
        CASE
            WHEN test_name ~~* '%mg/g%'::text THEN 'mg/g'::text
            ELSE '%'::text
        END AS raw_unit,
    result AS raw_value,
        CASE
            WHEN test_name ~~* '%mg/g%'::text THEN round(result / 10.0, 3)
            ELSE round(result, 3)
        END AS pct,
    overall_passed,
    source_harvests
   FROM metrc_rpt_lab_results r
  WHERE f_is_ours(packaged_licence) AND result IS NOT NULL AND test_name ~* '^(Total THC|Total CBD|THCA|THCa|THCV|THCVA|CBD|CBDA|CBDV|CBG|CBGA|CBN|CBC|CBCA|THC)\s*\('::text;
create or replace view public.v_potency_results as
 SELECT r.package_tag,
    r.item,
    f_strain_from_item(r.item) AS strain,
    f_product_line(r.item, r.category, r.test_name) AS product_line,
    r.category AS metrc_category,
    r.packaged_licence AS licence,
    r.lab_facility AS lab,
    r.test_date,
    EXTRACT(year FROM r.test_date)::integer AS yr,
    to_char(r.test_date::timestamp with time zone, 'YYYY-MM'::text) AS month,
    EXTRACT(quarter FROM r.test_date)::integer AS quarter,
    r.test_name,
        CASE
            WHEN r.test_name ~~* '%mg/g%'::text THEN round(r.result / 10.0, 3)
            ELSE round(r.result, 3)
        END AS pct,
    r.overall_passed,
    r.source_harvests,
    t.target_min,
    t.status AS target_status,
    t.set_by AS target_set_by,
        CASE
            WHEN t.target_min IS NULL THEN NULL::boolean
            ELSE
            CASE
                WHEN r.test_name ~~* '%mg/g%'::text THEN r.result / 10.0
                ELSE r.result
            END >= t.target_min
        END AS hits_target,
        CASE
            WHEN t.target_min IS NULL THEN 'no target set'::text
            WHEN
            CASE
                WHEN r.test_name ~~* '%mg/g%'::text THEN r.result / 10.0
                ELSE r.result
            END >= t.target_min THEN 'at or above target'::text
            ELSE 'below target'::text
        END AS target_verdict,
    r.result AS raw_value,
        CASE
            WHEN r.test_name ~~* '%mg/g%'::text THEN 'mg/g'::text
            ELSE '%'::text
        END AS raw_unit
   FROM metrc_rpt_lab_results r
     LEFT JOIN potency_target t ON t.category = f_product_line(r.item, r.category, r.test_name) AND t.analyte = 'Total THC'::text
  WHERE f_is_ours(r.packaged_licence) AND r.test_name ~~* '%Total THC%'::text AND r.result IS NOT NULL;
create or replace view public.v_product_listing as
 WITH on_hand AS (
         SELECT f_strain_from_item(p.raw #>> '{Item,Name}'::text[]) AS strain,
            p.license AS licence,
            COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
            count(*) AS tags,
            round(sum(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))) FILTER (WHERE f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))), 2) AS lb_on_hand,
            sum((p.raw ->> 'Quantity'::text)::numeric) FILTER (WHERE NOT f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))) AS units_on_hand,
            max((p.raw ->> 'PackagedDate'::text)::date) AS newest_pack
           FROM metrc_packages p
          WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false
          GROUP BY (f_strain_from_item(p.raw #>> '{Item,Name}'::text[])), p.license, (COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text))
        ), coa AS (
         SELECT z.strain,
            z.total_thc,
            z.total_cbd,
            z.total_cannabinoids,
            z.total_terpenes,
            z.terpene_profile,
            z.cannabinoid_profile,
            z.document_id,
            z.package_tag
           FROM ( SELECT f_strain_from_item(c.package_tag) AS ignore_me,
                    COALESCE(f_strain_from_item(mp.raw #>> '{Item,Name}'::text[]), c.package_tag) AS strain,
                    c.total_thc,
                    c.total_cbd,
                    c.total_cannabinoids,
                    c.total_terpenes,
                    c.terpene_profile,
                    c.cannabinoid_profile,
                    c.document_id,
                    c.package_tag,
                    row_number() OVER (PARTITION BY (COALESCE(f_strain_from_item(mp.raw #>> '{Item,Name}'::text[]), c.package_tag)) ORDER BY c.parsed_at DESC NULLS LAST) AS rn
                   FROM coa_extract c
                     LEFT JOIN metrc_packages mp ON (mp.raw ->> 'Label'::text) = c.package_tag
                  WHERE f_is_ours(COALESCE(c.client_license, ''::text))) z
          WHERE z.rn = 1
        )
 SELECT l.strain,
    COALESCE(l.display_name, l.strain) AS display_name,
    l.strain_type,
    l.lineage,
    l.dominant_terpenes,
    l.flavour_notes,
    l.effect_notes,
    l.short_description,
    l.status AS listing_status,
    l.hero_image_path,
    ( SELECT count(*) AS count
           FROM strain_image i
          WHERE i.strain = l.strain) AS image_count,
    l.shopify_handle,
    coa.total_thc AS coa_total_thc,
    coa.total_cannabinoids AS coa_tac,
    coa.total_terpenes AS coa_total_terpenes,
    coa.terpene_profile AS coa_terpene_profile,
    coa.document_id AS coa_document_id,
    coa.package_tag AS coa_package_tag,
        CASE
            WHEN coa.document_id IS NULL THEN 'NO COA ON FILE — do not publish'::text
            WHEN coa.total_cannabinoids IS NULL THEN 'COA on file but TAC not parsed'::text
            WHEN coa.total_terpenes IS NULL THEN 'COA on file, TAC present, terpenes not parsed'::text
            ELSE 'COA complete'::text
        END AS coa_state,
    oh.licence,
    oh.category,
    oh.tags,
    oh.lb_on_hand,
    oh.units_on_hand,
    oh.newest_pack,
        CASE
            WHEN coa.document_id IS NULL THEN 'BLOCKED — no COA'::text
            WHEN l.strain_type IS NULL THEN 'BLOCKED — strain type not set'::text
            WHEN l.short_description IS NULL THEN 'BLOCKED — no description'::text
            WHEN (( SELECT count(*) AS count
               FROM strain_image i
              WHERE i.strain = l.strain)) = 0 THEN 'BLOCKED — no image'::text
            WHEN COALESCE(oh.lb_on_hand, 0::numeric) = 0::numeric AND COALESCE(oh.units_on_hand, 0::numeric) = 0::numeric THEN 'BLOCKED — nothing on hand'::text
            ELSE 'READY'::text
        END AS publish_readiness
   FROM strain_library l
     LEFT JOIN on_hand oh ON oh.strain = l.strain
     LEFT JOIN coa ON coa.strain = l.strain;
create or replace view public.v_production_forecast as
 SELECT to_char(date_trunc('month'::text, projected_availability::timestamp with time zone), 'YYYY-MM'::text) AS month,
    count(*) AS harvest_events,
    count(DISTINCT harvest_date) AS harvests,
    count(DISTINCT flower_room) AS rooms,
    sum(plants) AS plants,
    round(sum(projected_weight_lbs), 1) AS projected_lbs,
    round(sum(fresh_frozen_lbs), 1) AS fresh_frozen_lbs,
    round(sum(flower_after_ff_lbs), 1) AS flower_lbs_after_ff
   FROM harvest_schedule
  WHERE projected_availability IS NOT NULL
  GROUP BY (to_char(date_trunc('month'::text, projected_availability::timestamp with time zone), 'YYYY-MM'::text))
  ORDER BY (to_char(date_trunc('month'::text, projected_availability::timestamp with time zone), 'YYYY-MM'::text));
create or replace view public.v_proposals_for_owner as
 SELECT id,
    raised_by,
    raised_at,
    domain,
    target_object,
    severity,
    the_issue,
    the_evidence,
    what_needs_fixing,
    the_proposal,
    why_this_is_the_fix,
    how_it_never_repeats,
    rows_affected,
    pounds_affected,
    dollars_affected,
    risk_if_wrong,
    reversible,
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END AS rank
   FROM correction_proposal
  WHERE status = 'proposed'::text
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), (COALESCE(dollars_affected, 0::numeric)) DESC, (COALESCE(pounds_affected, 0::numeric)) DESC, raised_at;
create or replace view public.v_provisional_standards as
 SELECT 'production_yield_standard'::text AS source,
    production_yield_standard.key AS item,
    production_yield_standard.label AS description,
    production_yield_standard.value::text AS current_value,
    production_yield_standard.unit,
    production_yield_standard.evidence_status,
    production_yield_standard.set_by,
    production_yield_standard.updated_at
   FROM production_yield_standard
  WHERE production_yield_standard.evidence_status = 'provisional'::text
UNION ALL
 SELECT 'inventory_cost_rate'::text AS source,
    (((inventory_cost_rate.scope || ':'::text) || COALESCE(inventory_cost_rate.scope_key, '(all)'::text)) || ' / '::text) || inventory_cost_rate.material AS item,
    'Cost rate, '::text || inventory_cost_rate.material AS description,
    COALESCE(inventory_cost_rate.cost_per_lb::text || ' per lb'::text, inventory_cost_rate.cost_per_unit::text || ' per unit'::text) AS current_value,
    inventory_cost_rate.currency AS unit,
    inventory_cost_rate.evidence_status,
    inventory_cost_rate.set_by,
    inventory_cost_rate.updated_at
   FROM inventory_cost_rate
  WHERE inventory_cost_rate.evidence_status = 'provisional'::text
UNION ALL
 SELECT 'preroll_formulation'::text AS source,
    (preroll_formulation.brand || ' from '::text) || preroll_formulation.effective_from AS item,
    'Pre-roll flower:trim split'::text AS description,
    (round(preroll_formulation.flower_pct * 100::numeric) || '/'::text) || round(preroll_formulation.trim_pct * 100::numeric) AS current_value,
    'ratio'::text AS unit,
    preroll_formulation.evidence_status,
    preroll_formulation.set_by,
    preroll_formulation.updated_at
   FROM preroll_formulation
  WHERE preroll_formulation.evidence_status = 'provisional'::text;
create or replace view public.v_rate_confidence as
 SELECT count(*) AS rates_total,
    count(*) FILTER (WHERE is_placeholder) AS placeholder_rates,
    count(*) FILTER (WHERE NOT is_placeholder) AS approved_rates,
    count(*) FILTER (WHERE is_placeholder) > 0 AS any_placeholder,
        CASE
            WHEN count(*) FILTER (WHERE is_placeholder) = count(*) THEN 'EVERY rate is a planning placeholder — labour cost figures are illustrative, not measured'::text
            WHEN count(*) FILTER (WHERE is_placeholder) > 0 THEN 'Some rates are planning placeholders — labour cost is part measured, part illustrative'::text
            ELSE 'All rates are owner-approved'::text
        END AS disclosure
   FROM employee_rates
  WHERE effective_to IS NULL;
create or replace view public.v_real_loss as
 SELECT 'Plant attrition'::text AS loss_type,
    COALESCE(p.strain, 'not recorded'::text) AS scope,
    p.room AS location,
    count(*)::numeric AS units,
    'plants'::text AS unit_label,
    NULL::numeric AS pounds,
    'Plants retired without producing a harvest. This is capacity that cost money and returned nothing.'::text AS why_it_is_a_loss,
    'Compare to plants harvested for the same strain. A high count means culls, disease or death.'::text AS what_to_check
   FROM metrc_plants p
  WHERE p.source_state = 'inactive'::text AND NOT (EXISTS ( SELECT 1
           FROM metrc_harvests h
          WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || COALESCE(p.strain, '~'::text)) || '%'::text) AND h.harvest_start >= p.planted_on AND h.harvest_start <= (p.planted_on + 200)))
  GROUP BY (COALESCE(p.strain, 'not recorded'::text)), p.room
 HAVING count(*) > 5
UNION ALL
 SELECT 'Yield underperformance'::text AS loss_type,
    COALESCE(h.raw ->> 'SourceStrainNames'::text, 'not recorded'::text) AS scope,
    COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS location,
    1::numeric AS units,
    'harvest'::text AS unit_label,
    round((( SELECT avg(COALESCE((h2.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS avg
           FROM metrc_harvests h2
          WHERE COALESCE((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric)) * COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS pounds,
    'This harvest produced fewer saleable pounds than the company average conversion would predict from its wet weight.'::text AS why_it_is_a_loss,
    'Check drying and trim practice for this room, and whether the wet weight was recorded accurately.'::text AS what_to_check
   FROM metrc_harvests h
  WHERE COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric AND (COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric)) < (0.75 * (( SELECT avg(COALESCE((h2.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS avg
           FROM metrc_harvests h2
          WHERE COALESCE((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric)))
UNION ALL
 SELECT 'Destroyed after failing testing'::text AS loss_type,
    COALESCE(p.item_name, '(unnamed)'::text) AS scope,
    COALESCE(p.location, '(no location)'::text) AS location,
    1::numeric AS units,
    'package'::text AS unit_label,
        CASE p.uom
            WHEN 'g'::text THEN round(COALESCE(p.quantity, 0::numeric) / f_rule('grams_per_pound'::text), 2)
            WHEN 'kg'::text THEN round(COALESCE(p.quantity, 0::numeric) * 1000.0 / f_rule('grams_per_pound'::text), 2)
            WHEN 'lb'::text THEN round(COALESCE(p.quantity, 0::numeric), 2)
            WHEN 'oz'::text THEN round(COALESCE(p.quantity, 0::numeric) / 16.0, 2)
            ELSE NULL::numeric
        END AS pounds,
    'Material that failed testing AND was destroyed. Only destroyed material is a loss: per the owner, failed material is remediated in house, sold on for remediation, or destroyed, and this business buys failed material at a discount to remediate it. Failing a test is not losing the value.'::text AS why_it_is_a_loss,
    'Confirm the destruction is recorded in Metrc.'::text AS what_to_check
   FROM metrc_packages p
  WHERE p.lab_testing_state = 'TestFailed'::text AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND (EXISTS ( SELECT 1
           FROM failed_material_disposition fd
          WHERE fd.package_tag = p.tag AND fd.superseded_at IS NULL AND fd.disposition = 'destroy'::text))
UNION ALL
 SELECT 'Missed pull'::text AS loss_type,
    COALESCE(pl.cultivars, 'not recorded'::text) AS scope,
    pl.flower_room AS location,
    1::numeric AS units,
    'scheduled pull'::text AS unit_label,
    round(COALESCE(pl.proj_harvest_weight_lbs, 0::numeric), 1) AS pounds,
    'A pull was scheduled and never recorded. If nothing else was planted in its place, that is a full cycle of room capacity earning nothing.'::text AS why_it_is_a_loss,
    'Confirm whether the room was replanted. If it sat empty, that is the most expensive loss in cultivation.'::text AS what_to_check
   FROM harvest_pulls pl
  WHERE pl.harvest_date < (CURRENT_DATE - 14) AND NOT (EXISTS ( SELECT 1
           FROM metrc_harvests h
          WHERE h.harvest_start >= (pl.harvest_date - 5) AND h.harvest_start <= (pl.harvest_date + 21)));
create or replace view public.v_reason_settings as
 SELECT action_key,
    label,
    plain_english,
    enforced,
    require_code,
    require_note,
    min_note_chars,
    require_review_date,
    require_second_approver,
    ( SELECT count(*) AS count
           FROM reason_code_catalog c
          WHERE c.active AND (c.applies_to = '{}'::text[] OR (p.action_key = ANY (c.applies_to)))) AS codes_available,
    ( SELECT string_agg(c.code, ', '::text ORDER BY c.sort_order) AS string_agg
           FROM reason_code_catalog c
          WHERE c.active AND (c.applies_to = '{}'::text[] OR (p.action_key = ANY (c.applies_to)))) AS codes,
    COALESCE(set_by, 'not recorded'::text) AS set_by,
    updated_at,
        CASE
            WHEN enforced THEN 'ENFORCED - the action is refused without this'::text
            ELSE 'NOT ENFORCED - recorded but not gated'::text
        END AS status
   FROM reason_policy p;
create or replace view public.v_recurring_tasks as
 SELECT t.id AS task_id,
    t.title,
    t.status,
    t.priority,
    t.due_on,
    COALESCE(t.recurrence_parent_id, t.id) AS series_id,
        CASE
            WHEN t.recurrence_parent_id IS NULL THEN 'First task in the series'::text
            ELSE 'Created automatically from an earlier task'::text
        END AS series_position,
    r.every_days AS repeats_every_days,
    (COALESCE(t.due_on, CURRENT_DATE) + ((r.every_days || ' days'::text)::interval))::date AS next_occurrence_due_on,
    employee.full_name AS assigned_to,
    space.name AS space_name,
    t.tags,
    (( SELECT count(*) AS count
           FROM tasks series_member
          WHERE COALESCE(series_member.recurrence_parent_id, series_member.id) = COALESCE(t.recurrence_parent_id, t.id)))::integer AS tasks_in_series,
    t.completed_at,
    t.created_at
   FROM tasks t
     CROSS JOIN LATERAL ( SELECT GREATEST(1,
                CASE
                    WHEN (t.recurrence ->> 'every_days'::text) ~ '^[0-9]+$'::text THEN (t.recurrence ->> 'every_days'::text)::integer
                    ELSE 7
                END) AS every_days) r
     LEFT JOIN employees employee ON employee.id = t.assignee_employee_id
     LEFT JOIN spaces space ON space.id = t.space_id
  WHERE t.recurrence IS NOT NULL;
create or replace view public.v_report_catalogue as
 SELECT report_key,
    title,
    category,
    fact_view,
    date_column IS NOT NULL AS supports_date_range,
    date_column,
    array_length(dimensions, 1) AS dimension_count,
    array_length(measures, 1) AS measure_count,
    dimensions,
    measures,
    description,
    owner_note,
    array_length(dimensions, 1) * (1 + array_length(dimensions, 1) - 1) * array_length(dimensions, 1) *
        CASE
            WHEN date_column IS NOT NULL THEN 4
            ELSE 1
        END AS report_permutations
   FROM report_registry r
  WHERE enabled;
create or replace view public.v_report_coverage as
 WITH held AS (
         SELECT 'harvests_inactive'::text AS report_key,
            metrc_rpt_harvest_moisture.licence,
            min(metrc_rpt_harvest_moisture.finished_on) AS first_event,
            max(metrc_rpt_harvest_moisture.finished_on) AS last_event,
            count(*) AS rows_held,
            max(metrc_rpt_harvest_moisture.as_of_date) AS last_as_of
           FROM metrc_rpt_harvest_moisture
          GROUP BY metrc_rpt_harvest_moisture.licence
        UNION ALL
         SELECT 'packages_transferred'::text,
            metrc_rpt_package_transfers.licence,
            min(metrc_rpt_package_transfers.received_on) AS min,
            max(metrc_rpt_package_transfers.received_on) AS max,
            count(*) AS count,
            max(metrc_rpt_package_transfers.as_of_date) AS max
           FROM metrc_rpt_package_transfers
          GROUP BY metrc_rpt_package_transfers.licence
        UNION ALL
         SELECT 'wholesale_transfers'::text,
            metrc_rpt_wholesale.licence,
            min(metrc_rpt_wholesale.created_on) AS min,
            max(metrc_rpt_wholesale.created_on) AS max,
            count(*) AS count,
            max(metrc_rpt_wholesale.as_of_date) AS max
           FROM metrc_rpt_wholesale
          GROUP BY metrc_rpt_wholesale.licence
        UNION ALL
         SELECT 'packages_adjustments'::text,
            metrc_rpt_adjustments.licence,
            min(metrc_rpt_adjustments.adjusted_on) AS min,
            max(metrc_rpt_adjustments.adjusted_on) AS max,
            count(*) AS count,
            max(metrc_rpt_adjustments.as_of_date) AS max
           FROM metrc_rpt_adjustments
          GROUP BY metrc_rpt_adjustments.licence
        UNION ALL
         SELECT 'plants_waste'::text,
            metrc_rpt_plant_waste.licence,
            min(metrc_rpt_plant_waste.waste_date) AS min,
            max(metrc_rpt_plant_waste.waste_date) AS max,
            count(*) AS count,
            max(metrc_rpt_plant_waste.as_of_date) AS max
           FROM metrc_rpt_plant_waste
          GROUP BY metrc_rpt_plant_waste.licence
        UNION ALL
         SELECT 'plants_destroyed'::text,
            metrc_rpt_plants_destroyed.licence,
            min(metrc_rpt_plants_destroyed.phase_date) AS min,
            max(metrc_rpt_plants_destroyed.phase_date) AS max,
            count(*) AS count,
            max(metrc_rpt_plants_destroyed.as_of_date) AS max
           FROM metrc_rpt_plants_destroyed
          GROUP BY metrc_rpt_plants_destroyed.licence
        UNION ALL
         SELECT 'test_batches'::text,
            metrc_rpt_test_batches.licence,
            min(metrc_rpt_test_batches.test_date) AS min,
            max(metrc_rpt_test_batches.test_date) AS max,
            count(*) AS count,
            max(metrc_rpt_test_batches.as_of_date) AS max
           FROM metrc_rpt_test_batches
          GROUP BY metrc_rpt_test_batches.licence
        UNION ALL
         SELECT 'harvests'::text,
            metrc_rpt_harvests.licence,
            min(metrc_rpt_harvests.finished_date) AS min,
            max(metrc_rpt_harvests.finished_date) AS max,
            count(*) AS count,
            max(metrc_rpt_harvests.as_of_date) AS max
           FROM metrc_rpt_harvests
          GROUP BY metrc_rpt_harvests.licence
        UNION ALL
         SELECT 'packages_inventory'::text,
            metrc_rpt_packages_inventory.licence,
            min(metrc_rpt_packages_inventory.packaged_on) AS min,
            max(metrc_rpt_packages_inventory.packaged_on) AS max,
            count(*) AS count,
            max(metrc_rpt_packages_inventory.as_of_date) AS max
           FROM metrc_rpt_packages_inventory
          GROUP BY metrc_rpt_packages_inventory.licence
        UNION ALL
         SELECT 'inventory_point_in_time'::text,
            metrc_rpt_point_in_time.licence,
            min(metrc_rpt_point_in_time.as_of_date) AS min,
            max(metrc_rpt_point_in_time.as_of_date) AS max,
            count(*) AS count,
            max(metrc_rpt_point_in_time.as_of_date) AS max
           FROM metrc_rpt_point_in_time
          GROUP BY metrc_rpt_point_in_time.licence
        )
 SELECT t.report_key,
    t.title,
    t.cadence,
    t.menu_path,
    t.upload_priority,
    lic.licence AS required_for_licence,
    h.rows_held,
    h.first_event,
    h.last_event,
    h.last_as_of,
        CASE
            WHEN h.rows_held IS NULL THEN 'Never uploaded'::text
            WHEN t.cadence ~~ 'Monthly%'::text AND h.last_event < (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)::date - 1) THEN 'Gap - the last month is missing'::text
            WHEN t.cadence ~~ 'Quarterly%'::text AND h.last_event < (date_trunc('quarter'::text, CURRENT_DATE::timestamp with time zone)::date - 1) THEN 'Gap - the last quarter is missing'::text
            ELSE 'Covered'::text
        END AS coverage,
    COALESCE(h.last_event - 14, '2024-01-01'::date) AS export_from,
    CURRENT_DATE AS export_to,
        CASE
            WHEN h.rows_held IS NULL THEN 'Export everything Metrc will give you - nothing is held yet.'::text
            ELSE (('Export from '::text || to_char(COALESCE(h.last_event - 14, '2024-01-01'::date)::timestamp with time zone, 'DD Mon YYYY'::text)) || ' to today. The overlap is deliberate: re-importing a row corrects it, it never '::text) || 'duplicates, so a wider range is always safe.'::text
        END AS what_to_export
   FROM metrc_report_types t
     CROSS JOIN LATERAL unnest(t.required_licences) lic(licence)
     LEFT JOIN held h ON h.report_key = t.report_key AND COALESCE(h.licence, lic.licence) = lic.licence
  WHERE t.cadence !~~ 'On demand%'::text
  ORDER BY t.upload_priority, lic.licence;
create or replace view public.v_report_mapping_status as
 SELECT t.report_key,
    t.title,
    t.upload_priority,
    t.cadence,
    t.menu_path,
    t.what_it_adds,
    t.why_it_matters,
    t.api_covers_this,
    t.licence_scope,
    t.target_table,
    array_length(t.signature_cols, 1) AS detect_columns,
    t.signature_cols,
    t.key_cols,
    COALESCE(i.imports, 0::bigint) AS imports_done,
    i.last_import_at,
    i.last_file,
    i.last_rows,
        CASE
            WHEN i.last_import_at IS NULL THEN 'Never uploaded'::text
            WHEN t.cadence ~~ 'Monthly%'::text AND i.last_import_at < date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) THEN 'Overdue - this month not uploaded'::text
            WHEN t.cadence ~~ 'Yearly%'::text AND i.last_import_at < date_trunc('year'::text, CURRENT_DATE::timestamp with time zone) THEN 'Overdue - this year not uploaded'::text
            ELSE 'Up to date'::text
        END AS upload_status
   FROM metrc_report_types t
     LEFT JOIN LATERAL ( SELECT count(*) AS imports,
            max(m.imported_at) AS last_import_at,
            (array_agg(m.file_name ORDER BY m.imported_at DESC))[1] AS last_file,
            (array_agg(m.row_count ORDER BY m.imported_at DESC))[1] AS last_rows
           FROM metrc_report_imports m
          WHERE m.report_type = t.report_key) i ON true
  ORDER BY t.upload_priority;
create or replace view public.v_report_pull_status as
 SELECT report_key,
    metrc_report_name,
    licence,
    target_table,
    last_pulled_on,
    last_period,
    last_rows,
    CURRENT_DATE - last_pulled_on AS days_since_pull,
    pull_frequency,
        CASE
            WHEN target_table IS NULL THEN 'NO TARGET TABLE — parsed nowhere'::text
            WHEN last_pulled_on IS NULL THEN 'NEVER PULLED'::text
            WHEN (CURRENT_DATE - last_pulled_on) > 30 THEN 'STALE — over 30 days'::text
            WHEN (CURRENT_DATE - last_pulled_on) > 7 THEN 'ageing — over a week'::text
            ELSE 'current'::text
        END AS freshness,
    gotcha
   FROM metrc_report_catalog c
  WHERE active;
create or replace view public.v_report_retention_risk as
 SELECT report_key,
    metrc_report_name,
    licence,
    earliest_available,
    retention_days,
    CURRENT_DATE - retention_days AS window_opens_on,
        CASE
            WHEN retention_days IS NULL THEN NULL::integer
            ELSE GREATEST(0, CURRENT_DATE - retention_days - earliest_available)
        END AS days_already_lost,
    last_pulled_on,
    last_pulled_on IS NOT NULL AS archived_locally,
        CASE
            WHEN retention_days IS NULL THEN 'RETENTION UNKNOWN — measure it before assuming history is safe'::text
            WHEN earliest_available < (CURRENT_DATE - retention_days) THEN 'HISTORY ALREADY LOST — the window has closed past this report''s earliest data'::text
            WHEN earliest_available < (CURRENT_DATE - retention_days + 60) THEN 'CLOSING WITHIN 60 DAYS — pull and archive now'::text
            ELSE 'inside the window'::text
        END AS risk,
    retention_note
   FROM metrc_report_catalog c
  WHERE active;
create or replace view public.v_report_upload_due as
 WITH expected AS (
         SELECT t.report_key,
            t.title,
            t.upload_priority,
            t.cadence,
            t.menu_path,
            t.why_it_matters,
            t.what_it_adds,
            t.target_table,
            t.api_covers_this,
            lic.lic AS licence,
                CASE
                    WHEN t.cadence ~~ 'Monthly%'::text THEN (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) - '1 mon'::interval)::date
                    WHEN t.cadence ~~ 'Quarterly%'::text THEN (date_trunc('quarter'::text, CURRENT_DATE::timestamp with time zone) - '3 mons'::interval)::date
                    WHEN t.cadence ~~ 'Yearly%'::text THEN (date_trunc('year'::text, CURRENT_DATE::timestamp with time zone) - '1 year'::interval)::date
                    ELSE NULL::date
                END AS period_start,
                CASE
                    WHEN t.cadence ~~ 'Monthly%'::text THEN date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)::date + 5
                    WHEN t.cadence ~~ 'Quarterly%'::text THEN date_trunc('quarter'::text, CURRENT_DATE::timestamp with time zone)::date + 10
                    WHEN t.cadence ~~ 'Yearly%'::text THEN date_trunc('year'::text, CURRENT_DATE::timestamp with time zone)::date + 31
                    ELSE NULL::date
                END AS due_by
           FROM metrc_report_types t
             CROSS JOIN LATERAL unnest(t.required_licences) lic(lic)
          WHERE t.cadence !~~ 'On demand%'::text
        )
 SELECT e.report_key,
    e.title,
    e.upload_priority,
    e.cadence,
    e.menu_path,
    e.why_it_matters,
    e.what_it_adds,
    e.target_table,
    e.api_covers_this,
    e.licence,
    e.period_start,
    e.due_by,
    to_char(e.period_start::timestamp with time zone,
        CASE
            WHEN e.cadence ~~ 'Monthly%'::text THEN 'FMMonth YYYY'::text
            WHEN e.cadence ~~ 'Quarterly%'::text THEN '"Q"Q YYYY'::text
            ELSE 'YYYY'::text
        END) AS period_label,
    i.imported_at,
    i.file_name,
    i.row_count,
    i.imported_by,
    i.id IS NOT NULL AS received,
    CURRENT_DATE - e.due_by AS days_late,
        CASE
            WHEN i.id IS NOT NULL THEN 'Received'::text
            WHEN CURRENT_DATE <= e.due_by THEN 'Due by '::text || to_char(e.due_by::timestamp with time zone, 'DD Mon'::text)
            ELSE ('OVERDUE by '::text || (CURRENT_DATE - e.due_by)) || ' days'::text
        END AS upload_status,
        CASE
            WHEN i.id IS NOT NULL THEN 'ok'::text
            WHEN CURRENT_DATE <= e.due_by THEN 'due'::text
            WHEN e.cadence ~~ '%required%'::text THEN 'critical'::text
            ELSE 'elevated'::text
        END AS severity
   FROM expected e
     LEFT JOIN LATERAL ( SELECT m.id,
            m.report_type,
            m.license,
            m.file_name,
            m.row_count,
            m.mapped_to,
            m.imported_by,
            m.imported_at,
            m.period_start
           FROM metrc_report_imports m
          WHERE m.report_type = e.report_key AND COALESCE(m.license, e.licence) = e.licence AND m.period_start = e.period_start
          ORDER BY m.imported_at DESC
         LIMIT 1) i ON true
  ORDER BY (i.id IS NOT NULL), e.upload_priority, e.licence;
create or replace view public.v_request_scorecard as
 SELECT owner_requests.status,
    owner_requests.priority,
    count(*) AS requests,
    round(100.0 * count(*)::numeric / NULLIF(( SELECT count(*) AS count
           FROM owner_requests owner_requests_1), 0)::numeric, 1) AS pct_of_all
   FROM owner_requests
  GROUP BY owner_requests.status, owner_requests.priority
UNION ALL
 SELECT 'ALL REQUESTS'::text AS status,
    '-'::text AS priority,
    count(*) AS requests,
    100.0 AS pct_of_all
   FROM owner_requests;
create or replace view public.v_role_clearance_breaches as
 SELECT 'UNCLASSIFIED'::text AS breach_type,
    nr.view_key,
    nr.label,
    COALESCE(nr.surface, 'side'::text) AS surface,
    NULL::text AS role,
    NULL::integer AS role_rank,
    NULL::integer AS needs_rank,
    'This page matches the sensitive pattern but has no sensitive_page_policy row, so every role can see it. useNav hides only what is explicitly marked visible=false.'::text AS detail
   FROM nav_registry nr
  WHERE nr.enabled AND ((nr.surface = ANY (ARRAY['finance'::text, 'tax'::text, 'hr'::text])) OR nr.category ~~* '%human%'::text OR nr.view_key ~* 'payroll|valuation|cost|licence|license|secret|wage|salary|cash|overhead'::text) AND NOT (EXISTS ( SELECT 1
           FROM sensitive_page_policy p
          WHERE p.view_key = nr.view_key))
UNION ALL
 SELECT 'ABOVE CLEARANCE'::text AS breach_type,
    p.view_key,
    nr.label,
    COALESCE(nr.surface, 'side'::text) AS surface,
    r.role,
    r.rank AS role_rank,
    p.min_rank AS needs_rank,
    ((((('Role '::text || r.role) || ' (rank '::text) || r.rank) || ') can see a page needing rank '::text) || p.min_rank) || '. Insert nav_role_visibility (view_key, role, visible=false).'::text AS detail
   FROM sensitive_page_policy p
     JOIN nav_registry nr ON nr.view_key = p.view_key AND nr.enabled
     CROSS JOIN app_roles r
  WHERE r.rank < p.min_rank AND (r.role IN ( SELECT unnest(enum_range(NULL::app_role))::text AS unnest)) AND NOT (EXISTS ( SELECT 1
           FROM nav_role_visibility v
          WHERE v.view_key = p.view_key AND v.role = r.role AND v.visible = false));
create or replace view public.v_role_menu_matrix as
 SELECT n.category,
    n.label,
    n.view_key,
    n.admin_only,
    bool_or(v.visible) FILTER (WHERE v.role = 'owner'::text) AS owner,
    bool_or(v.visible) FILTER (WHERE v.role = 'executive'::text) AS executive,
    bool_or(v.visible) FILTER (WHERE v.role = 'manager'::text) AS manager,
    bool_or(v.visible) FILTER (WHERE v.role = 'member'::text) AS member,
    bool_or(v.visible) FILTER (WHERE v.role = 'limited'::text) AS limited,
    bool_or(v.visible) FILTER (WHERE v.role = 'guest'::text) AS guest
   FROM nav_registry n
     LEFT JOIN nav_role_visibility v ON v.view_key = n.view_key
  GROUP BY n.category, n.label, n.view_key, n.admin_only, n.category_order, n.item_order
  ORDER BY n.category_order, n.item_order;
create or replace view public.v_room_canopy_status as
 SELECT code,
    legacy_label,
    plant_capacity,
    cycle_days,
    sqft,
    sqft_source,
    round(sqft / NULLIF(plant_capacity, 0)::numeric, 2) AS sqft_per_plant,
    ( SELECT round(avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric), 2) AS round
           FROM grow_rooms g
          WHERE g.sqft IS NOT NULL AND g.active) AS sqft_per_plant_in_measured_rooms,
        CASE
            WHEN sqft IS NULL THEN round(plant_capacity::numeric * (( SELECT avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric) AS avg
               FROM grow_rooms g
              WHERE g.sqft IS NOT NULL AND g.active)))
            ELSE NULL::numeric
        END AS sqft_if_same_density,
        CASE
            WHEN sqft IS NOT NULL THEN 'Measured. Yield per square foot is calculated for this room.'::text
            ELSE (((((((('CANNOT BE MEASURED. No square footage on file, so this room is excluded from every '::text || 'yield per square foot figure — '::text) || plant_capacity) || ' plants of canopy are invisible '::text) || 'in the benchmark. At the '::text) || (( SELECT round(avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric), 2) AS round
               FROM grow_rooms g
              WHERE g.sqft IS NOT NULL AND g.active))) || ' square feet per plant the measured rooms run at, it would be about '::text) || round(plant_capacity::numeric * (( SELECT avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric) AS avg
               FROM grow_rooms g
              WHERE g.sqft IS NOT NULL AND g.active)))) || ' square feet — but that is inferred from two rooms, not measured, and is deliberately '::text) || 'not being used. Measure the room and enter it on Grow Rooms.'::text
        END AS status
   FROM grow_rooms r
  WHERE active
  ORDER BY code;
create or replace view public.v_room_history as
 SELECT pit.tag AS package_tag,
    pit.as_of_date AS observed_on,
    'snapshot'::text AS observation,
    pit.location AS room,
    pit.licence,
    pit.record_type,
    pit.name AS item,
    pit.strain,
    pit.category,
    'Inventory Point in Time export'::text AS source
   FROM metrc_rpt_point_in_time pit
  WHERE pit.location IS NOT NULL
UNION ALL
 SELECT p.raw ->> 'Label'::text AS package_tag,
    CURRENT_DATE AS observed_on,
    'current'::text AS observation,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS room,
    p.license AS licence,
    'Package'::text AS record_type,
    p.raw #>> '{Item,Name}'::text[] AS item,
    f_strain_from_item(p.raw #>> '{Item,Name}'::text[]) AS strain,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    'live package mirror'::text AS source
   FROM metrc_packages p
  WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false
UNION ALL
 SELECT h.raw ->> 'Name'::text AS package_tag,
    (h.raw ->> 'HarvestStartDate'::text)::date AS observed_on,
    'harvest'::text AS observation,
    NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text) AS room,
    h.license AS licence,
    'Harvest'::text AS record_type,
    h.raw ->> 'Name'::text AS item,
    f_strain_from_item(h.raw ->> 'Name'::text) AS strain,
    'Harvest'::text AS category,
    'harvest drying location (a LABEL, it does not move with the material)'::text AS source
   FROM metrc_harvests h
  WHERE NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text) IS NOT NULL;
create or replace view public.v_room_month_comparison as
 WITH rm AS (
         SELECT COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            to_char(h.harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, h.harvest_start::timestamp with time zone)::date AS month_date,
            count(*) AS harvests,
            sum(COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants,
            sum(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
            sum(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS packaged_g,
            sum(COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g,
            avg(
                CASE
                    WHEN (h.raw ->> 'FinishedDate'::text) IS NOT NULL THEN ((h.raw ->> 'FinishedDate'::text)::date) - h.harvest_start
                    ELSE NULL::integer
                END) AS avg_dry_days
           FROM metrc_harvests h
          WHERE h.harvest_start IS NOT NULL
          GROUP BY (COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text)), (to_char(h.harvest_start::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, h.harvest_start::timestamp with time zone)::date)
        ), scored AS (
         SELECT rm.room,
            rm.month,
            rm.month_date,
            rm.harvests,
            rm.plants,
            rm.wet_g,
            rm.packaged_g,
            rm.waste_g,
            rm.avg_dry_days,
                CASE
                    WHEN rm.wet_g > 0::numeric THEN round(100.0 * rm.packaged_g / rm.wet_g, 1)
                    ELSE NULL::numeric
                END AS conversion_pct,
                CASE
                    WHEN rm.plants > 0::numeric THEN round(rm.packaged_g / rm.plants, 1)
                    ELSE NULL::numeric
                END AS grams_per_plant,
            round(rm.avg_dry_days, 1) AS dry_days
           FROM rm
        )
 SELECT room,
    month,
    harvests,
    plants,
    round(wet_g / 453.592, 1) AS wet_lbs,
    round(packaged_g / 453.592, 1) AS saleable_lbs,
    conversion_pct,
    grams_per_plant,
    dry_days,
    max(conversion_pct) OVER (PARTITION BY room) AS room_best_conversion,
    min(conversion_pct) OVER (PARTITION BY room) AS room_worst_conversion,
    round(conversion_pct - avg(conversion_pct) OVER (PARTITION BY room), 1) AS versus_room_average,
    ( SELECT industry_benchmarks.average
           FROM industry_benchmarks
          WHERE industry_benchmarks.metric = 'Wet to saleable conversion'::text) AS industry_average_pct,
        CASE
            WHEN conversion_pct = max(conversion_pct) OVER (PARTITION BY room) THEN 'BEST MONTH for this room'::text
            WHEN conversion_pct = min(conversion_pct) OVER (PARTITION BY room) THEN 'WORST MONTH for this room'::text
            ELSE 'middle of the range'::text
        END AS standing,
    round(wet_g / 453.592 * (max(conversion_pct) OVER (PARTITION BY room) - conversion_pct) / 100.0, 1) AS pounds_lost_versus_room_best,
    round(wet_g / 453.592 * (max(conversion_pct) OVER (PARTITION BY room) - conversion_pct) / 100.0 * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_lost_versus_room_best,
    ((('This room hit '::text || max(conversion_pct) OVER (PARTITION BY room)) || ' percent in its best month and '::text) || conversion_pct) || ' percent here. Same room, same equipment - the difference is drying time and trim practice, not the building.'::text AS what_this_means,
        CASE
            WHEN dry_days IS NOT NULL THEN ('Average dry ran '::text || dry_days) || ' days this month.'::text
            ELSE 'Dry duration not recorded for this month.'::text
        END AS dry_evidence,
    month_date
   FROM scored s
  ORDER BY (round(wet_g / 453.592 * (max(conversion_pct) OVER (PARTITION BY room) - conversion_pct) / 100.0 * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_room_plant_counts as
 SELECT COALESCE(NULLIF(raw ->> 'LocationName'::text, ''::text), 'Not recorded'::text) AS room,
    raw ->> 'GrowthPhase'::text AS growth_phase,
    count(*) AS plants,
    count(DISTINCT NULLIF(raw ->> 'StrainName'::text, ''::text)) AS strains,
    string_agg(DISTINCT NULLIF(raw ->> 'StrainName'::text, ''::text), ', '::text) AS strain_list,
    min((raw ->> 'PlantedDate'::text)::date) AS earliest_planted,
    max((raw ->> 'PlantedDate'::text)::date) AS latest_planted
   FROM metrc_plants
  WHERE (raw ->> 'State'::text) = 'Tracked'::text
  GROUP BY (COALESCE(NULLIF(raw ->> 'LocationName'::text, ''::text), 'Not recorded'::text)), (raw ->> 'GrowthPhase'::text)
  ORDER BY (count(*)) DESC;
create or replace view public.v_room_plants_drill as
 SELECT a.our_name AS room,
    a.metrc_name AS metrc_room_name,
    p.raw ->> 'Label'::text AS plant_tag,
    p.raw ->> 'StrainName'::text AS strain,
    p.raw ->> 'GrowthPhase'::text AS growth_phase,
    p.source_state AS state,
    NULLIF(p.raw ->> 'PlantedDate'::text, ''::text)::date AS planted_on,
    NULLIF(p.raw ->> 'VegetativeDate'::text, ''::text)::date AS vegetative_on,
    NULLIF(p.raw ->> 'FloweringDate'::text, ''::text)::date AS flowering_on,
        CASE
            WHEN NULLIF(p.raw ->> 'FloweringDate'::text, ''::text) IS NOT NULL THEN CURRENT_DATE - ((p.raw ->> 'FloweringDate'::text)::date)
            ELSE NULL::integer
        END AS days_in_flower,
    NULLIF(p.raw ->> 'SublocationName'::text, ''::text) AS sublocation,
    p.raw ->> 'PlantBatchName'::text AS plant_batch,
    COALESCE((p.raw ->> 'IsOnHold'::text)::boolean, false) AS on_hold,
    COALESCE((p.raw ->> 'IsOnInvestigation'::text)::boolean, false) AS on_investigation,
    NULLIF(p.raw ->> 'LastModified'::text, ''::text)::timestamp with time zone AS metrc_last_modified
   FROM metrc_plants p
     JOIN room_alias a ON a.metrc_name = COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(none)'::text)
  WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text]);
create or replace view public.v_route_margin as
 SELECT e.product_route,
    e.product_family,
    e.sell_price_per_unit,
    e.packaging_cost_per_unit + e.labor_cost_per_unit + e.other_cost_per_unit AS conversion_cost_per_unit,
    e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit AS contribution_per_unit,
    e.input_grams_per_unit,
    e.yield_pct,
    round((e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit) / (e.input_grams_per_unit / (e.yield_pct / 100.0)), 4) AS margin_per_input_gram,
        CASE
            WHEN e.sell_price_per_unit > 0::numeric THEN round(100.0 * (e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit) / e.sell_price_per_unit, 1)
            ELSE NULL::numeric
        END AS gross_margin_pct,
    e.cycle_days,
    COALESCE(d.units_demanded, 0::numeric) AS units_demanded,
    COALESCE(d.units_committed, 0::numeric) AS units_committed,
    GREATEST(COALESCE(d.units_demanded, 0::numeric) - COALESCE(d.units_committed, 0::numeric), 0::numeric) AS units_open,
    round(GREATEST(COALESCE(d.units_demanded, 0::numeric) - COALESCE(d.units_committed, 0::numeric), 0::numeric) * e.input_grams_per_unit / (e.yield_pct / 100.0), 1) AS grams_needed_for_open_demand,
    e.active
   FROM product_economics e
     LEFT JOIN LATERAL ( SELECT sum(s.units_demanded) AS units_demanded,
            sum(s.units_committed) AS units_committed
           FROM demand_signals s
          WHERE s.product_route = e.product_route AND (s.period_end IS NULL OR s.period_end >= CURRENT_DATE)) d ON true
  WHERE e.active
  ORDER BY (round((e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit) / (e.input_grams_per_unit / (e.yield_pct / 100.0)), 4)) DESC NULLS LAST;
create or replace view public.v_rpt_2024_grown as
 WITH h AS (
         SELECT h_1.license AS licence,
            h_1.raw ->> 'Name'::text AS harvest,
            NULLIF(h_1.raw ->> 'DryingLocationName'::text, ''::text) AS room,
            (h_1.raw ->> 'HarvestStartDate'::text)::date AS harvested_on,
            NULLIF(h_1.raw ->> 'FinishedDate'::text, ''::text)::date AS finished_on,
            f_strain_from_item(h_1.raw ->> 'Name'::text) AS strain,
            f_to_pounds((h_1.raw ->> 'TotalWetWeight'::text)::numeric, 'Grams'::text) AS wet_lb,
            f_to_pounds((h_1.raw ->> 'TotalWasteWeight'::text)::numeric, 'Grams'::text) AS waste_lb,
            f_to_pounds((h_1.raw ->> 'TotalPackagedWeight'::text)::numeric, 'Grams'::text) AS packaged_lb,
            f_to_pounds((h_1.raw ->> 'CurrentWeight'::text)::numeric, 'Grams'::text) AS metrc_residual_lb,
            (h_1.raw ->> 'PlantCount'::text)::numeric AS plants
           FROM metrc_harvests h_1
          WHERE ((h_1.raw ->> 'HarvestStartDate'::text)::date) >= '2024-01-01'::date AND ((h_1.raw ->> 'HarvestStartDate'::text)::date) <= '2024-12-31'::date
        )
 SELECT licence,
    harvest,
    strain,
    room,
    harvested_on,
    finished_on,
    plants,
        CASE
            WHEN room = 'Freezer/Biomass Storage'::text THEN 'FRESH FROZEN (wet basis)'::text
            ELSE 'DRIED (dry basis)'::text
        END AS stream,
    round(wet_lb, 2) AS wet_lb,
    round(waste_lb, 2) AS waste_lb,
    round(wet_lb - waste_lb, 2) AS usable_wet_lb,
    round(packaged_lb, 2) AS packaged_off_lb,
    round(metrc_residual_lb, 2) AS metrc_residual_lb,
    round(GREATEST((wet_lb - waste_lb) * (f_rule('expected_moisture_pct_min'::text) / 100.0), 0::numeric), 2) AS water_lb_low,
    round(GREATEST((wet_lb - waste_lb) * (f_rule('expected_moisture_pct_max'::text) / 100.0), 0::numeric), 2) AS water_lb_high,
    round(GREATEST(metrc_residual_lb - (wet_lb - waste_lb) * (f_rule('expected_moisture_pct_max'::text) / 100.0), 0::numeric), 2) AS unexplained_lb,
    round(
        CASE
            WHEN (wet_lb - waste_lb) > 0::numeric THEN packaged_lb / (wet_lb - waste_lb) * 100::numeric
            ELSE NULL::numeric
        END, 1) AS dry_yield_pct,
    finished_on IS NULL AS still_open
   FROM h;
create or replace view public.v_rpt_2024_onhand as
 WITH p AS (
         SELECT p_1.license AS licence,
            p_1.raw ->> 'Label'::text AS tag,
            COALESCE(NULLIF(btrim(p_1.raw ->> 'LocationName'::text), ''::text), '(no room)'::text) AS room,
            COALESCE(NULLIF(p_1.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
            p_1.raw #>> '{Item,Name}'::text[] AS item,
            f_strain_from_item(p_1.raw #>> '{Item,Name}'::text[]) AS strain,
            NULLIF(p_1.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
            NULLIF(p_1.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
            NULLIF(p_1.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS received_from,
            NULLIF(p_1.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) AS received_from_licence,
            (p_1.raw ->> 'PackagedDate'::text)::date AS packaged_on,
            (p_1.raw ->> 'ReceivedDateTime'::text)::timestamp with time zone AS received_at,
            NULLIF(p_1.raw ->> 'FinishedDate'::text, ''::text)::timestamp with time zone AS finished_at,
            p_1.raw ->> 'LabTestingState'::text AS lab_state,
            COALESCE(NULLIF(p_1.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text) AS uom,
            COALESCE((p_1.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric) AS created_qty,
            COALESCE((p_1.raw ->> 'Quantity'::text)::numeric, 0::numeric) AS current_qty,
            (p_1.raw ->> 'LastModified'::text)::timestamp with time zone AS last_modified
           FROM metrc_packages p_1
        )
 SELECT licence,
    room,
    category,
    tag,
    item,
    strain,
    source_harvest,
    source_packages,
        CASE
            WHEN received_from_licence IS NULL THEN 'OURS — made here'::text
            WHEN f_is_ours(received_from_licence) THEN 'OURS — from our other licence'::text
            ELSE 'THIRD PARTY — bought in'::text
        END AS ownership,
    received_from,
    received_from_licence,
    packaged_on,
    received_at,
    lab_state,
    uom,
    round(f_to_pounds(created_qty, uom), 3) AS created_lb,
    round(f_to_pounds(current_qty, uom), 3) AS current_lb,
        CASE
            WHEN f_is_weight(uom) THEN NULL::numeric
            ELSE created_qty
        END AS created_units,
        CASE
            WHEN last_modified <= '2024-12-31 23:59:59+00'::timestamp with time zone THEN 'EXACT — untouched since 31 Dec 2024'::text
            ELSE 'CREATED QUANTITY — this tag was modified after period end'::text
        END AS qty_basis,
    last_modified > '2024-12-31 23:59:59+00'::timestamp with time zone AS modified_after_period,
    last_modified
   FROM p
  WHERE COALESCE(packaged_on, received_at::date) <= '2024-12-31'::date AND (finished_at IS NULL OR finished_at > '2024-12-31 23:59:59+00'::timestamp with time zone) AND created_qty > 0::numeric;
create or replace view public.v_rpt_2024_sold as
 SELECT a.invoice,
    a.order_date,
    a.buyer,
    a.buyer_licence,
        CASE
            WHEN a.buyer_licence ~~* 'MT%'::text THEN 'TRANSPORTER — not a sale'::text
            WHEN a.buyer_licence ~~* 'ML%'::text THEN 'LAB — not a sale'::text
            WHEN a.buyer_licence IS NULL THEN 'licence not recorded on the order'::text
            ELSE 'Arm''s length sale'::text
        END AS classification,
    it.value ->> 'product_name'::text AS product,
    it.value ->> 'product_category'::text AS category,
    it.value ->> 'cultivar'::text AS strain,
    NULLIF(it.value ->> 'metrc_package_label'::text, ''::text) AS metrc_tag,
    it.value ->> 'batch_name'::text AS batch,
    (it.value ->> 'order_quantity'::text)::numeric AS qty,
    it.value ->> 'order_unit_measurement'::text AS uom,
    round(COALESCE((it.value ->> 'order_price_raw'::text)::numeric, 0::numeric) / 100.0, 2) AS unit_price_usd,
    round(COALESCE((it.value ->> 'order_price_raw'::text)::numeric, 0::numeric) * COALESCE((it.value ->> 'order_quantity'::text)::numeric, 0::numeric) / 100.0, 2) AS line_total_usd,
    a.order_total_usd,
    a.collected_usd,
    a.payment_status,
    a.manifest,
    a.cancelled
   FROM ( SELECT apex_raw.payload ->> 'invoice_number'::text AS invoice,
            COALESCE((apex_raw.payload ->> 'order_date'::text)::date, (apex_raw.payload ->> 'created_at'::text)::date) AS order_date,
            (apex_raw.payload -> 'buyer'::text) ->> 'name'::text AS buyer,
            apex_raw.payload ->> 'buyer_state_license'::text AS buyer_licence,
            apex_raw.payload ->> 'payment_status'::text AS payment_status,
            NULLIF(apex_raw.payload ->> 'manifest_number'::text, ''::text) AS manifest,
            (apex_raw.payload ->> 'cancelled'::text)::boolean AS cancelled,
            round(COALESCE((apex_raw.payload ->> 'total_raw'::text)::numeric, 0::numeric) / 100.0, 2) AS order_total_usd,
            round(COALESCE((apex_raw.payload ->> 'total_payments_raw'::text)::numeric, 0::numeric) / 100.0, 2) AS collected_usd,
            apex_raw.payload -> 'items'::text AS items
           FROM apex_raw
          WHERE apex_raw.entity = 'shipping-orders'::text) a,
    LATERAL jsonb_array_elements(a.items) it(value)
  WHERE a.order_date >= '2024-01-01'::date AND a.order_date <= '2024-12-31'::date;
create or replace view public.v_rpt_coa_compliance as
 SELECT p.raw ->> 'Label'::text AS package_tag,
    p.license AS licence,
    (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
    EXTRACT(year FROM (p.raw ->> 'PackagedDate'::text)::date)::integer AS yr,
    EXTRACT(quarter FROM (p.raw ->> 'PackagedDate'::text)::date)::integer AS quarter,
    to_char(((p.raw ->> 'PackagedDate'::text)::date)::timestamp with time zone, 'YYYY-MM'::text) AS month,
    CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date) AS days_old,
        CASE
            WHEN (CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date)) > 365 THEN '4 · over a year'::text
            WHEN (CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date)) > 180 THEN '3 · 6-12 months'::text
            WHEN (CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date)) > 90 THEN '2 · 3-6 months'::text
            ELSE '1 · under 90 days'::text
        END AS age_band,
    p.raw #>> '{Item,Name}'::text[] AS item,
    f_strain_from_item(p.raw #>> '{Item,Name}'::text[]) AS strain,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    f_product_line(p.raw #>> '{Item,Name}'::text[], p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text) AS product_line,
    NULLIF(p.raw ->> 'LocationName'::text, ''::text) AS room,
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) THEN 'OURS'::text
            WHEN NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text) IS NULL THEN 'UNKNOWN — no originating facility recorded'::text
            ELSE 'THIRD PARTY — '::text || (p.raw ->> 'ItemFromFacilityName'::text)
        END AS ownership,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '—'::text) AS supplier,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS supplier_licence,
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN round(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3)
            ELSE NULL::numeric
        END AS lb,
        CASE
            WHEN NOT f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN (p.raw ->> 'Quantity'::text)::numeric
            ELSE NULL::numeric
        END AS units,
    p.raw ->> 'LabTestingState'::text AS metrc_lab_state,
    COALESCE((p.raw ->> 'IsOnHold'::text)::boolean, false) AS on_hold,
    c.package_tag IS NOT NULL AS has_coa,
    c.total_thc AS coa_total_thc,
    c.total_cannabinoids AS coa_tac,
    c.total_terpenes AS coa_terpenes,
    c.document_id AS coa_document_id,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
        CASE
            WHEN c.package_tag IS NOT NULL THEN '0 · COA ON FILE'::text
            WHEN (p.raw ->> 'LabTestingState'::text) ~~* '%fail%'::text THEN '5 · FAILED — do not sell, decide'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'RetestPassed'::text]) THEN '1 · TESTED, NO CERTIFICATE — fetch the document'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'SubmittedForTesting'::text THEN '2 · AT THE LABORATORY — awaiting result'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN '3 · NEVER SUBMITTED — intermediate stock'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'NotRequired'::text THEN '4 · TESTING NOT REQUIRED'::text
            ELSE '6 · '::text || COALESCE(p.raw ->> 'LabTestingState'::text, 'no state recorded'::text)
        END AS verdict,
        CASE
            WHEN (p.raw ->> 'LabTestingState'::text) ~~* '%fail%'::text THEN 'BLOCK — failed product on hand'::text
            WHEN c.package_tag IS NULL AND ((p.raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'RetestPassed'::text])) THEN 'FETCH — certificate exists at the lab'::text
            WHEN c.package_tag IS NULL AND (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text AND (CURRENT_DATE - ((p.raw ->> 'PackagedDate'::text)::date)) > 180 THEN 'REVIEW — untested over six months'::text
            WHEN c.package_tag IS NULL THEN 'monitor'::text
            ELSE 'ok'::text
        END AS action,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(not recorded)'::text) AS cultivated_by,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS cultivated_by_licence,
    COALESCE(( SELECT cl.label
           FROM company_licenses cl
          WHERE cl.license = p.license
         LIMIT 1), p.license) AS processed_by,
    p.license AS processed_by_licence,
    NOT f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) AS is_third_party,
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS ownership_label,
    NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest
   FROM metrc_packages p
     LEFT JOIN coa_extract c ON c.package_tag = (p.raw ->> 'Label'::text)
  WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false;
create or replace view public.v_rpt_discrepancies as
 SELECT 'OPEN — discrepancy register'::text AS bucket,
    d.discrepancy_key AS key,
    d.class,
    d.subject,
    (d.source_a || ' says: '::text) || d.source_a_says AS source_a,
    (d.source_b || ' says: '::text) || d.source_b_says AS source_b,
    d.resolved_by_doc AS resolves_with,
    d.first_seen::date AS first_seen,
    CURRENT_DATE - d.first_seen::date AS days_open,
        CASE
            WHEN (CURRENT_DATE - d.first_seen::date) > 7 THEN 'BREACH — the owner''s rule is nothing older than a week'::text
            ELSE 'inside the one-week rule'::text
        END AS clock,
    NULL::text AS outcome
   FROM discrepancy_register d
  WHERE d.resolved_at IS NULL
UNION ALL
 SELECT 'RESOLVED — discrepancy register'::text AS bucket,
    d.discrepancy_key AS key,
    d.class,
    d.subject,
    (d.source_a || ' says: '::text) || d.source_a_says AS source_a,
    (d.source_b || ' says: '::text) || d.source_b_says AS source_b,
    d.resolved_by_doc AS resolves_with,
    d.first_seen::date AS first_seen,
    d.resolved_at::date - d.first_seen::date AS days_open,
    'closed '::text || d.resolved_at::date AS clock,
    d.resolution_note AS outcome
   FROM discrepancy_register d
  WHERE d.resolved_at IS NOT NULL
UNION ALL
 SELECT 'WITHDRAWN — was never a real discrepancy'::text AS bucket,
    c.finding_key AS key,
    c.defect_kind AS class,
    c.check_key AS subject,
    'CLAIMED: '::text || c.claimed AS source_a,
    'ACTUALLY: '::text || c.actually AS source_b,
    c.evidence_sql AS resolves_with,
    c.found_at::date AS first_seen,
    COALESCE(c.fixed_at, now())::date - c.found_at::date AS days_open,
    c.impact AS clock,
    c.fix_note AS outcome
   FROM check_defect c
UNION ALL
 SELECT 'JOURNAL — '::text || j.status AS bucket,
    'entry '::text || j.entry_no::text AS key,
    j.entry_type AS class,
    j.subject,
    j.description AS source_a,
    j.reason AS source_b,
    j.basis AS resolves_with,
    j.entered_on::date AS first_seen,
    CURRENT_DATE - j.entered_on::date AS days_open,
    COALESCE(j.approved_by, 'awaiting approval'::text) AS clock,
    j.affects_report AS outcome
   FROM audit_journal j;
create or replace view public.v_rpt_inventory_reconciliation as
 SELECT make_date(y.yr, 1, 1) AS period_start,
    make_date(y.yr, 12, 31) AS period_end,
    y.yr::text AS financial_year,
    r.line_no,
    r.section,
    r.line_item,
    r.pounds,
    r.source AS basis_and_caveats
   FROM generate_series(2024, EXTRACT(year FROM CURRENT_DATE)::integer) y(yr)
     CROSS JOIN LATERAL f_inventory_reconciliation(make_date(y.yr, 1, 1), LEAST(make_date(y.yr, 12, 31), CURRENT_DATE)) r(line_no, section, line_item, pounds, source);
create or replace view public.v_rpt_testing_reconciliation as
 SELECT EXTRACT(year FROM COALESCE(m.created_on, m.received_on))::integer AS yr,
    m.destination_facility AS lab,
    m.destination_licence AS lab_licence,
    m.manifest_number,
    COALESCE(m.created_on, m.received_on) AS sent_on,
    t.package_tag,
    t.item,
    t.category,
    t.strain,
        CASE
            WHEN f_is_weight(t.shipped_uom) THEN round(f_to_pounds(t.shipped_qty, t.shipped_uom), 4)
            ELSE NULL::numeric
        END AS lb_sent,
        CASE
            WHEN NOT f_is_weight(t.shipped_uom) THEN t.shipped_qty
            ELSE NULL::numeric
        END AS units_sent,
    r.package_tag IS NOT NULL AS has_result,
    r.test_date AS tested_on,
    r.overall_passed AS passed,
        CASE
            WHEN r.package_tag IS NOT NULL THEN 'MATCHED — sample shipped and result returned'::text
            WHEN COALESCE(m.created_on, m.received_on) < '2025-01-10'::date THEN 'UNMATCHABLE — our lab-results sync begins 10 Jan 2025. The test may well '::text || 'have happened; we simply hold no result row. NOT a missing COA.'::text
            ELSE 'NO RESULT — shipped on a manifest, no result against this tag. CHASE IT.'::text
        END AS verdict
   FROM metrc_rpt_transfer_manifests m
     JOIN metrc_rpt_package_transfers t ON t.manifest_number = m.manifest_number
     LEFT JOIN LATERAL ( SELECT lr.package_tag,
            lr.test_date,
            lr.overall_passed
           FROM metrc_rpt_lab_results lr
          WHERE lr.package_tag = t.package_tag
          ORDER BY lr.test_date DESC NULLS LAST
         LIMIT 1) r ON true
  WHERE m.transfer_type = 'Lab Transfer'::text;
create or replace view public.v_sales_history as
 SELECT created_on AS sold_on,
    to_char(created_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
    manifest_number,
    recipient AS customer,
    COALESCE(raw ->> 'RecipientFacilityLicenseNumber'::text, (raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text) AS customer_license,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, ((raw -> '_delivery'::text) ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages_sent,
    COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, ((raw -> '_delivery'::text) ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric) AS packages_received,
    COALESCE(raw ->> 'ShipmentTypeName'::text, (raw -> '_delivery'::text) ->> 'ShipmentTypeName'::text) AS shipment_type,
    COALESCE(raw ->> 'ReceivedDateTime'::text, (raw -> '_delivery'::text) ->> 'ReceivedDateTime'::text)::date AS received_on,
        CASE
            WHEN COALESCE(raw ->> 'ReceivedDateTime'::text, (raw -> '_delivery'::text) ->> 'ReceivedDateTime'::text) IS NOT NULL THEN 'Delivered'::text
            WHEN created_on < (CURRENT_DATE - 3) THEN 'NOT CONFIRMED RECEIVED'::text
            ELSE 'In transit'::text
        END AS delivery_status,
        CASE
            WHEN COALESCE(raw ->> 'Id'::text, (raw -> '_delivery'::text) ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || COALESCE(raw ->> 'Id'::text, (raw -> '_delivery'::text) ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END AS manifest_link,
    license
   FROM metrc_transfers t
  WHERE direction = 'outgoing'::text
  ORDER BY created_on DESC NULLS LAST;
create or replace view public.v_schedulable as
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    d.name AS department,
    e.hours_basis,
    e.badge_expires,
    e.badge_expires IS NOT NULL AND e.badge_expires >= CURRENT_DATE AS licence_valid,
    e.status::text = 'active'::text AS employed,
    COALESCE(e.weekly_target_hours, 40::numeric) AS target_hours,
    (EXISTS ( SELECT 1
           FROM employee_availability a
          WHERE a.employee_id = e.id AND a.available = false AND (a.specific_date = CURRENT_DATE OR a.weekday = EXTRACT(dow FROM CURRENT_DATE)::integer))) AS blacked_out,
        CASE
            WHEN e.status::text <> 'active'::text THEN 'not employed'::text
            WHEN e.badge_expires IS NULL THEN 'no licence on file'::text
            WHEN e.badge_expires < CURRENT_DATE THEN 'licence expired'::text
            WHEN (EXISTS ( SELECT 1
               FROM employee_availability a
              WHERE a.employee_id = e.id AND a.available = false AND (a.specific_date = CURRENT_DATE OR a.weekday = EXTRACT(dow FROM CURRENT_DATE)::integer))) THEN 'unavailable today'::text
            ELSE 'schedulable'::text
        END AS schedulable_state
   FROM employees e
     LEFT JOIN departments d ON d.id = e.primary_department_id;
create or replace view public.v_schedule_revisions as
 SELECT r.room,
    r.event_type,
    r.original_date,
    r.new_date AS current_planned_date,
    r.previous_date,
    r.new_date - r.original_date AS days_moved_from_original,
    r.note,
    rc.label AS reason,
    r.revised_by,
    r.revised_at,
    r.superseded_by IS NOT NULL AS superseded,
    ( SELECT count(*) AS count
           FROM schedule_revision r2
          WHERE r2.room = r.room AND r2.original_date = r.original_date) AS times_this_date_moved,
        CASE
            WHEN r.resets_baseline THEN ('DISRUPTION — the baseline moved. This pull and everything after it in this room is measured against the new date, so one incident does not flag the rest of the year. The original '::text || r.original_date) || ' is kept and still visible.'::text
            WHEN r.new_date > r.original_date THEN ('Pushed LATER by '::text || (r.new_date - r.original_date)) || ' days, and the original commitment still stands in the adherence figure — moving a plan does not make a late take-down on time.'::text
            ELSE ('Pulled EARLIER by '::text || (r.original_date - r.new_date)) || ' days.'::text
        END AS what_this_means,
    r.resets_baseline,
    r.disruption_ref,
    ( SELECT count(*) AS count
           FROM schedule_revision r3
          WHERE r3.room = r.room AND r3.resets_baseline AND r3.revised_at >= date_trunc('year'::text, now()) AND r3.disruption_ref IS DISTINCT FROM r.disruption_ref) AS other_baseline_resets_this_year
   FROM schedule_revision r
     LEFT JOIN reason_code_catalog rc ON rc.code = r.reason_code
  ORDER BY r.revised_at DESC;
create or replace view public.v_schedule_vs_worked as
 WITH sched AS (
         SELECT employee_schedules.employee_id,
            employee_schedules.work_date,
            employee_schedules.zone,
            sum(EXTRACT(epoch FROM employee_schedules.planned_end - employee_schedules.planned_start) / 3600.0)::numeric(6,2) AS scheduled_hours
           FROM employee_schedules
          WHERE employee_schedules.planned_start IS NOT NULL AND employee_schedules.planned_end IS NOT NULL
          GROUP BY employee_schedules.employee_id, employee_schedules.work_date, employee_schedules.zone
        ), act AS (
         SELECT time_entries.employee_id,
            time_entries.work_date,
            sum(EXTRACT(epoch FROM time_entries.clock_out - time_entries.clock_in) / 3600.0 - COALESCE(time_entries.unpaid_lunch_min, 0)::numeric / 60.0)::numeric(6,2) AS worked_hours,
            count(*) FILTER (WHERE time_entries.clock_out IS NULL) AS open_punches,
            min(time_entries.clock_in) AS first_in,
            max(time_entries.clock_out) AS last_out
           FROM time_entries
          WHERE time_entries.clock_in IS NOT NULL
          GROUP BY time_entries.employee_id, time_entries.work_date
        )
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    COALESCE(s.work_date, a.work_date) AS work_date,
    s.zone,
    COALESCE(s.scheduled_hours, 0::numeric) AS scheduled_hours,
    COALESCE(a.worked_hours, 0::numeric) AS worked_hours,
    (COALESCE(a.worked_hours, 0::numeric) - COALESCE(s.scheduled_hours, 0::numeric))::numeric(6,2) AS variance_hours,
        CASE
            WHEN COALESCE(s.scheduled_hours, 0::numeric) = 0::numeric THEN NULL::numeric
            ELSE round(LEAST(COALESCE(a.worked_hours, 0::numeric) / s.scheduled_hours, 2::numeric) * 100::numeric, 1)
        END AS adherence_pct,
    GREATEST(COALESCE(a.worked_hours, 0::numeric) - 8::numeric, 0::numeric)::numeric(6,2) AS daily_ot_hours,
    a.first_in,
    a.last_out,
    COALESCE(a.open_punches, 0::bigint) AS open_punches,
        CASE
            WHEN a.employee_id IS NULL THEN 'no_show_or_unrecorded'::text
            WHEN s.employee_id IS NULL THEN 'unscheduled_work'::text
            WHEN a.open_punches > 0 THEN 'missing_punch'::text
            WHEN a.worked_hours > (s.scheduled_hours + 0.25) THEN 'over'::text
            WHEN a.worked_hours < (s.scheduled_hours - 0.25) THEN 'under'::text
            ELSE 'on_plan'::text
        END AS flag
   FROM sched s
     FULL JOIN act a ON a.employee_id = s.employee_id AND a.work_date = s.work_date
     JOIN employees e ON e.id = COALESCE(s.employee_id, a.employee_id);
create or replace view public.v_schema_object_source as
 SELECT c.relname::text AS object_name,
        CASE c.relkind
            WHEN 'v'::"char" THEN 'view'::text
            ELSE 'matview'::text
        END AS object_kind,
    pg_get_viewdef(c.oid) AS body
   FROM pg_class c
     JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"]))
UNION ALL
 SELECT p.proname::text AS object_name,
    'function'::text AS object_kind,
    pg_get_functiondef(p.oid) AS body
   FROM pg_proc p
     JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'::name AND (p.prokind = ANY (ARRAY['f'::"char", 'p'::"char"]))
UNION ALL
 SELECT 'data_assertion:'::text || d.assertion_key AS object_name,
    'assertion'::text AS object_kind,
    d.violation_sql AS body
   FROM data_assertion d
  WHERE d.enabled;
create or replace view public.v_secret_status as
 SELECT s.key,
    s.label,
    s.help,
        CASE
            WHEN s.value_is_set THEN 'SET'::text
            ELSE 'NOT SET'::text
        END AS status,
        CASE
            WHEN s.value_is_set AND s.value_last4 IS NOT NULL THEN '••••'::text || s.value_last4
            ELSE NULL::text
        END AS masked,
    s.updated_at,
    s.value_set_at AS last_set_at,
    COALESCE(u.display_name, 'unknown'::text) AS last_set_by
   FROM app_secrets s
     LEFT JOIN app_users u ON u.user_id = s.updated_by;
create or replace view public.v_section_help_coverage as
 SELECT page,
    count(*) AS sections_explained,
    count(*) FILTER (WHERE COALESCE(btrim(common_misreading), ''::text) = ''::text) AS no_misreading_recorded,
    max(updated_at) AS last_updated
   FROM section_help h
  GROUP BY page;
create or replace view public.v_sentinel_coverage as
 SELECT jobname,
    firing_watched,
    output_watched,
    output_probe,
    guarantee
   FROM ( SELECT j.jobname,
            true AS firing_watched,
            e.source_key IS NOT NULL AS output_watched,
            e.source_key AS output_probe,
                CASE
                    WHEN e.source_key IS NOT NULL THEN 'both - the schedule is watched AND the work it produces is checked'::text
                    ELSE 'FIRING ONLY - if this job runs and produces nothing, nothing notices'::text
                END AS guarantee
           FROM cron.job j
             LEFT JOIN sentinel_expectation e ON e.enabled AND j.jobname ~~ (('%'::text || replace(e.source_key, '_'::text, '%'::text)) || '%'::text)
          WHERE j.active
          ORDER BY (e.source_key IS NOT NULL), j.jobname) guarded_body
  WHERE ( SELECT is_executive() AS is_executive);
create or replace view public.v_sentinel_cron_silence as
 SELECT jobname,
    schedule,
    last_success,
    silent_minutes,
    usual_gap_minutes,
    runs_only_in_a_window,
    verdict,
    runs_ever
   FROM ( WITH runs AS (
                 SELECT d.jobid,
                    d.status,
                    d.start_time
                   FROM cron.job_run_details d
                  WHERE d.start_time > (now() - '14 days'::interval)
                ), gaps AS (
                 SELECT runs.jobid,
                    EXTRACT(epoch FROM runs.start_time - lag(runs.start_time) OVER (PARTITION BY runs.jobid ORDER BY runs.start_time)) AS gap
                   FROM runs
                  WHERE runs.status = 'succeeded'::text
                ), cadence AS (
                 SELECT gaps.jobid,
                    percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (gaps.gap::double precision)) AS usual_gap
                   FROM gaps
                  WHERE gaps.gap IS NOT NULL
                  GROUP BY gaps.jobid
                ), tally AS (
                 SELECT runs.jobid,
                    count(*) AS runs_ever,
                    count(*) FILTER (WHERE runs.status = 'succeeded'::text) AS ok,
                    max(runs.start_time) FILTER (WHERE runs.status = 'succeeded'::text) AS last_success
                   FROM runs
                  GROUP BY runs.jobid
                )
         SELECT j.jobname,
            j.schedule,
            t.last_success,
            round(EXTRACT(epoch FROM now() - t.last_success) / 60::numeric)::integer AS silent_minutes,
            round(c.usual_gap / 60::double precision)::integer AS usual_gap_minutes,
            split_part(j.schedule, ' '::text, 2) !~ '^([*]|[*]/[0-9]+)$'::text AS runs_only_in_a_window,
                CASE
                    WHEN COALESCE(t.runs_ever, 0::bigint) = 0 THEN 'not yet due - scheduled, never reached its first run'::text
                    WHEN COALESCE(t.ok, 0::bigint) = 0 THEN 'NEVER SUCCEEDED - it has run and failed every time'::text
                    WHEN split_part(j.schedule, ' '::text, 2) !~ '^([*]|[*]/[0-9]+)$'::text THEN 'ok (windowed)'::text
                    WHEN c.usual_gap IS NULL THEN 'ok (too few runs to judge)'::text
                    WHEN EXTRACT(epoch FROM now() - t.last_success)::double precision > (c.usual_gap * 3::double precision) THEN 'SILENT'::text
                    ELSE 'ok'::text
                END AS verdict,
            COALESCE(t.runs_ever, 0::bigint) AS runs_ever
           FROM cron.job j
             LEFT JOIN cadence c ON c.jobid = j.jobid
             LEFT JOIN tally t ON t.jobid = j.jobid
          WHERE j.active
          ORDER BY (
                CASE
                    WHEN COALESCE(t.runs_ever, 0::bigint) > 0 AND COALESCE(t.ok, 0::bigint) = 0 THEN 0
                    WHEN t.last_success IS NOT NULL AND EXTRACT(epoch FROM now() - t.last_success)::double precision > (COALESCE(c.usual_gap, '1000000000'::numeric::double precision) * 3::double precision) THEN 1
                    WHEN COALESCE(t.runs_ever, 0::bigint) = 0 THEN 2
                    ELSE 3
                END), j.jobname) guarded_body
  WHERE ( SELECT is_executive() AS is_executive);
create or replace view public.v_sheet_sync_status as
 SELECT id,
    name,
    sheet_tab,
    description,
    enabled,
    auto_poll,
    poll_minutes,
    google_file_id,
    sheet_gid,
    last_pushed_at,
    last_row_count,
    expected_every_minutes,
    ( SELECT count(*) AS count
           FROM sheet_rows r
          WHERE r.source_id = s.id) AS rows_held,
        CASE
            WHEN google_file_id IS NULL THEN 'Not configured — the sheet''s file identifier has not been set, so the bridge does not know what to read.'::text
            WHEN last_pushed_at IS NULL THEN 'Never received. The bridge has not managed a read yet — it may need signing in to Google once.'::text
            WHEN (now() - last_pushed_at) > ((expected_every_minutes || ' minutes'::text)::interval) THEN ((((('OVERDUE — last received '::text || to_char(last_pushed_at, 'DD Mon YYYY HH24:MI'::text)) || ', which is '::text) || round(EXTRACT(epoch FROM now() - last_pushed_at) / 60::numeric)) || ' minutes ago against an expected '::text) || expected_every_minutes) || ' minutes.'::text
            ELSE ((('Current — last received '::text || to_char(last_pushed_at, 'DD Mon YYYY HH24:MI'::text)) || ', '::text) || round(EXTRACT(epoch FROM now() - last_pushed_at) / 60::numeric)) || ' minutes ago.'::text
        END AS status,
    ( SELECT count(*) AS count
           FROM sheet_push_log l
          WHERE l.source_id = s.id AND NOT l.ok) AS failures
   FROM sheet_sources s
  ORDER BY name;
create or replace view public.v_source_coverage as
 WITH s AS (
         SELECT 'packages'::text AS domain,
            'metrc_packages (API mirror)'::text AS source,
            min((metrc_packages.raw ->> 'PackagedDate'::text)::date) AS earliest,
            max((metrc_packages.raw ->> 'PackagedDate'::text)::date) AS latest,
            count(*) AS rows,
            true AS is_primary
           FROM metrc_packages
          WHERE ((metrc_packages.raw ->> 'PackagedDate'::text)::date) IS NOT NULL
        UNION ALL
         SELECT 'harvests'::text,
            'metrc_harvests (API mirror)'::text,
            min((metrc_harvests.raw ->> 'HarvestStartDate'::text)::date) AS min,
            max((metrc_harvests.raw ->> 'HarvestStartDate'::text)::date) AS max,
            count(*) AS count,
            true
           FROM metrc_harvests
        UNION ALL
         SELECT 'harvest moisture'::text,
            'metrc_rpt_harvest_moisture'::text,
            min(metrc_rpt_harvest_moisture.finished_on) AS min,
            max(metrc_rpt_harvest_moisture.finished_on) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_harvest_moisture
        UNION ALL
         SELECT 'testing'::text,
            'metrc_rpt_lab_results'::text,
            min(metrc_rpt_lab_results.test_date) AS min,
            max(metrc_rpt_lab_results.test_date) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_lab_results
        UNION ALL
         SELECT 'testing'::text,
            'metrc_rpt_test_batches'::text,
            min(metrc_rpt_test_batches.test_date) AS min,
            max(metrc_rpt_test_batches.test_date) AS max,
            count(*) AS count,
            false
           FROM metrc_rpt_test_batches
        UNION ALL
         SELECT 'transfers'::text,
            'metrc_rpt_package_transfers'::text,
            min(metrc_rpt_package_transfers.received_on) AS min,
            max(metrc_rpt_package_transfers.received_on) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_package_transfers
        UNION ALL
         SELECT 'manifests'::text,
            'metrc_rpt_transfer_manifests'::text,
            min(COALESCE(metrc_rpt_transfer_manifests.created_on, metrc_rpt_transfer_manifests.received_on)) AS min,
            max(COALESCE(metrc_rpt_transfer_manifests.created_on, metrc_rpt_transfer_manifests.received_on)) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_transfer_manifests
        UNION ALL
         SELECT 'destruction'::text,
            'metrc_rpt_plants_destroyed'::text,
            min(metrc_rpt_plants_destroyed.phase_date) AS min,
            max(metrc_rpt_plants_destroyed.phase_date) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_plants_destroyed
        UNION ALL
         SELECT 'waste'::text,
            'metrc_rpt_plant_waste'::text,
            min(metrc_rpt_plant_waste.waste_date) AS min,
            max(metrc_rpt_plant_waste.waste_date) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_plant_waste
        UNION ALL
         SELECT 'adjustments'::text,
            'metrc_rpt_adjustments'::text,
            min(metrc_rpt_adjustments.adjusted_on) AS min,
            max(metrc_rpt_adjustments.adjusted_on) AS max,
            count(*) AS count,
            true
           FROM metrc_rpt_adjustments
        UNION ALL
         SELECT 'sales'::text,
            'apex_raw shipping-orders'::text,
            min((apex_raw.payload ->> 'order_date'::text)::date) AS min,
            max((apex_raw.payload ->> 'order_date'::text)::date) AS max,
            count(*) AS count,
            true
           FROM apex_raw
          WHERE apex_raw.entity = 'shipping-orders'::text AND (apex_raw.payload ->> 'order_date'::text) IS NOT NULL
        )
 SELECT domain,
    source,
    earliest,
    latest,
    rows,
    is_primary,
    min(earliest) OVER (PARTITION BY domain) AS domain_earliest,
    earliest - min(earliest) OVER (PARTITION BY domain) AS days_behind_best,
        CASE
            WHEN earliest = min(earliest) OVER (PARTITION BY domain) THEN 'DEEPEST SOURCE for this domain — use it to fill the others'::text
            ELSE ('shallower — '::text || (earliest - min(earliest) OVER (PARTITION BY domain))) || ' days later than the deepest source'::text
        END AS role
   FROM s;
create or replace view public.v_standard_history as
 SELECT h.key,
    c.label,
    h.value,
    h.unit,
    h.set_by,
    h.valid_from::date AS in_force_from,
    h.valid_to::date AS in_force_until,
    h.valid_to IS NULL AS current,
    h.superseded_by,
        CASE
            WHEN h.valid_to IS NULL THEN 'In force now'::text
            ELSE ((('Applied from '::text || to_char(h.valid_from, 'DD Mon YYYY'::text)) || ' to '::text) || to_char(h.valid_to, 'DD Mon YYYY'::text)) || ' — anything judged in that window used this value, not the current one.'::text
        END AS standing
   FROM conversion_factor_history h
     LEFT JOIN conversion_factors c ON c.key = h.key
  ORDER BY h.key, h.valid_from DESC;
create or replace view public.v_stock_ageing as
 SELECT p.tag,
    p.item_name,
    COALESCE(p.raw #>> '{Item,ProductCategoryName}'::text[], '(uncategorised)'::text) AS category,
    p.location,
    p.license,
    p.packaged_on,
    CURRENT_DATE - p.packaged_on AS days_held,
    round(f_to_pounds(p.quantity, p.uom), 3) AS lb,
    pol.ages AS category_ages,
    pol.stale_after,
        CASE
            WHEN pol.category IS NULL THEN 'NO POLICY — this category has never been reasoned about'::text
            WHEN hold.room IS NOT NULL THEN 'HELD ON PURPOSE — '::text || hold.why_held
            WHEN NOT pol.ages THEN 'DOES NOT AGE — '::text || pol.why
            WHEN ((CURRENT_DATE - p.packaged_on)::double precision * '1 day'::interval) > pol.stale_after THEN 'STALE — past '::text || pol.stale_after
            ELSE 'ok'::text
        END AS ageing_verdict,
        CASE
            WHEN pol.remnant_under_lb IS NOT NULL AND f_to_pounds(p.quantity, p.uom) < pol.remnant_under_lb THEN ('REMNANT — under '::text || pol.remnant_under_lb) || ' lb, should be finished out in Metrc rather than carried as stock'::text
            ELSE NULL::text
        END AS remnant_verdict,
    hold.room IS NOT NULL AS in_a_holding_room,
    hold.why_held
   FROM ( SELECT DISTINCT ON (d.tag) d.id,
            d.license,
            d.tag,
            d.item_name,
            d.quantity,
            d.uom,
            d.location,
            d.packaged_on,
            d.lab_testing_state,
            d.finished,
            d.raw,
            d.synced_at,
            d.source_state,
            d.provenance,
            d.report_as_of
           FROM metrc_packages d
          ORDER BY d.tag, (COALESCE(d.quantity, 0::numeric) > 0::numeric AND NOT COALESCE((d.raw ->> 'IsFinished'::text)::boolean, false)) DESC, (d.source_state = 'active'::text) DESC NULLS LAST, d.synced_at DESC NULLS LAST) p
     LEFT JOIN stock_ageing_policy pol ON pol.category = COALESCE(p.raw #>> '{Item,ProductCategoryName}'::text[], '(uncategorised)'::text)
     LEFT JOIN holding_room hold ON hold.suspends_ageing AND hold.room = p.location
  WHERE COALESCE(p.quantity, 0::numeric) > 0::numeric AND COALESCE(p.finished, false) = false AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text, 'intransit'::text]));
create or replace view public.v_stock_headline as
 WITH base AS (
         SELECT COALESCE(NULLIF(metrc_packages.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
            ((metrc_packages.raw ->> 'Quantity'::text)::numeric) / 453.59237 AS lb
           FROM ( SELECT DISTINCT ON (mp.tag) mp.id,
                    mp.license,
                    mp.tag,
                    mp.item_name,
                    mp.quantity,
                    mp.uom,
                    mp.location,
                    mp.packaged_on,
                    mp.lab_testing_state,
                    mp.finished,
                    mp.raw,
                    mp.synced_at,
                    mp.source_state,
                    mp.provenance,
                    mp.report_as_of
                   FROM metrc_packages mp
                  ORDER BY mp.tag, (COALESCE(mp.quantity, 0::numeric) > 0::numeric AND NOT COALESCE((mp.raw ->> 'IsFinished'::text)::boolean, false)) DESC, (mp.source_state = 'active'::text) DESC NULLS LAST, mp.synced_at DESC NULLS LAST) metrc_packages
          WHERE (metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text, 'intransit'::text])) AND NOT COALESCE((metrc_packages.raw ->> 'IsFinished'::text)::boolean, false) AND COALESCE((metrc_packages.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND (lower(COALESCE(metrc_packages.raw ->> 'UnitOfMeasureName'::text, ''::text)) = ANY (ARRAY['grams'::text, 'g'::text]))
        ), f AS (
         SELECT conversion_factors.value AS ratio
           FROM conversion_factors
          WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
        )
 SELECT round(sum(lb) FILTER (WHERE category ~~* '%bud%'::text), 1) AS dried_lb,
    round(sum(lb) FILTER (WHERE category ~~* '%fresh frozen%'::text), 1) AS fresh_frozen_wet_lb,
    count(*) FILTER (WHERE category ~~* '%fresh frozen%'::text) AS fresh_frozen_packages,
    ( SELECT f.ratio
           FROM f) AS configured_ratio,
    round(sum(lb) FILTER (WHERE category ~~* '%fresh frozen%'::text) / (( SELECT f.ratio
           FROM f)), 1) AS fresh_frozen_dry_equivalent_lb,
    'DRIED FLOWER MEANS BUDS — bulk grades A/B/C and premium 3.5 g packs. Shake and trim, concentrate and pre-rolls are NOT dried flower and each carries its own figure below; before 13 Aug 2026 this number was defined as "not fresh frozen" and swept all three in, counting 1,024.5 lb twice on one screen. DRIED AND FRESH FROZEN ARE STILL NEVER ADDED: dried flower is dry weight, fresh frozen is packaged at field moisture and is mostly water.'::text AS why_two_figures,
    ('The dry-equivalent shown here uses the CONFIGURED ratio of '::text || ((( SELECT f.ratio
           FROM f))::text)) || ', which is not yet confirmed — measured extraction gives 4.17. Show it only beside this caveat, never as the headline number.'::text AS ratio_caveat,
    round(sum(lb) FILTER (WHERE category ~~* '%shake%'::text OR category ~~* '%trim%'::text), 1) AS shake_and_trim_lb,
    round(sum(lb) FILTER (WHERE category ~~* '%concentrate%'::text), 1) AS concentrate_lb,
    round(sum(lb) FILTER (WHERE category ~~* '%roll%'::text), 1) AS prerolls_lb,
    round(sum(lb), 1) AS all_weight_bearing_lb
   FROM base;
create or replace view public.v_stock_on_hand as
 SELECT origin,
    stream,
    license,
    lab_state,
    location,
    supplier,
    origin_license,
    packages,
    grams,
    pounds,
    oldest_days,
    oldest_packaged,
    strains,
    units,
    unit_of_measure,
    sold_by_weight,
    quantity_shown,
    'Not recorded'::text AS stock_status,
        CASE
            WHEN stream = 'Fresh frozen'::text THEN round(pounds / NULLIF(f_rule('fresh_frozen_wet_to_dry'::text), 0::numeric), 1)
            ELSE pounds
        END AS pounds_dry_equivalent
   FROM ( WITH p AS (
                 SELECT DISTINCT ON (p_1.tag) p_1.license,
                    p_1.raw #>> '{Item,StrainName}'::text[] AS strain,
                    p_1.raw ->> 'LabTestingState'::text AS lab_state,
                    COALESCE(p_1.location, '(not recorded)'::text) AS location,
                    p_1.quantity,
                    p_1.raw ->> 'UnitOfMeasureName'::text AS uom,
                    f_is_weight(p_1.raw ->> 'UnitOfMeasureName'::text) AS is_weight,
                    f_to_pounds(p_1.quantity, p_1.raw ->> 'UnitOfMeasureName'::text) AS lb,
                    p_1.packaged_on,
                    p_1.tag,
                    p_1.raw ->> 'ItemFromFacilityLicenseNumber'::text AS origin_license,
                    p_1.raw ->> 'ReceivedFromFacilityName'::text AS received_from,
                    p_1.raw ->> 'ReceivedFromManifestNumber'::text AS manifest,
                        CASE
                            WHEN f_is_ours(p_1.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'Grown by us'::text
                            WHEN COALESCE(p_1.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) = ''::text THEN 'Origin not recorded'::text
                            ELSE 'Bought in'::text
                        END AS origin,
                        CASE
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN 'Fresh frozen'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%bud%'::text THEN 'Dried flower'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%shake%'::text OR (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%trim%'::text THEN 'Shake and trim'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%concentrate%'::text THEN 'Concentrate'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%roll%'::text THEN 'Pre-rolls'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%vape%'::text THEN 'Vape'::text
                            ELSE COALESCE(p_1.raw #>> '{Item,ProductCategoryName}'::text[], '(uncategorised)'::text)
                        END AS stream
                   FROM metrc_packages p_1
                  WHERE COALESCE(p_1.quantity, 0::numeric) > 0::numeric AND COALESCE((p_1.raw ->> 'IsFinished'::text)::boolean, false) = false AND (p_1.source_state = ANY (ARRAY['active'::text, 'onhold'::text, 'intransit'::text]))
                  ORDER BY p_1.tag, (COALESCE(p_1.quantity, 0::numeric) > 0::numeric AND NOT COALESCE((p_1.raw ->> 'IsFinished'::text)::boolean, false)) DESC, (p_1.source_state = 'active'::text) DESC NULLS LAST, p_1.synced_at DESC NULLS LAST
                )
         SELECT p.origin,
            p.stream,
            p.license,
            p.lab_state,
            p.location,
            COALESCE(NULLIF(p.received_from, ''::text),
                CASE
                    WHEN p.origin = 'Grown by us'::text THEN 'Twisted Growers'::text
                    ELSE '(supplier not recorded)'::text
                END) AS supplier,
            p.origin_license,
            count(*) AS packages,
            sum(p.quantity) FILTER (WHERE lower(p.uom) = ANY (ARRAY['g'::text, 'grams'::text])) AS grams,
            round(sum(p.lb), 1) AS pounds,
            max(CURRENT_DATE - p.packaged_on) AS oldest_days,
            min(p.packaged_on) AS oldest_packaged,
            count(DISTINCT p.strain) AS strains,
            round(sum(p.quantity) FILTER (WHERE NOT p.is_weight)) AS units,
            string_agg(DISTINCT p.uom, ', '::text) AS unit_of_measure,
            bool_and(p.is_weight) AS sold_by_weight,
                CASE
                    WHEN bool_and(p.is_weight) THEN round(sum(p.lb), 1)::text || ' lb'::text
                    ELSE (round(sum(p.quantity) FILTER (WHERE NOT p.is_weight))::text || ' '::text) || COALESCE(string_agg(DISTINCT p.uom, '/'::text) FILTER (WHERE NOT p.is_weight), 'units'::text)
                END AS quantity_shown
           FROM p
          GROUP BY p.origin, p.stream, p.license, p.lab_state, p.location, (COALESCE(NULLIF(p.received_from, ''::text),
                CASE
                    WHEN p.origin = 'Grown by us'::text THEN 'Twisted Growers'::text
                    ELSE '(supplier not recorded)'::text
                END)), p.origin_license
          ORDER BY (sum(p.quantity)) DESC) q;
create or replace view public.v_strain_performance as
 WITH h AS (
         SELECT COALESCE(NULLIF(metrc_harvests.raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
            (metrc_harvests.raw ->> 'PlantCount'::text)::integer AS plants,
            ((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592 AS packaged_lb,
            metrc_harvests.wet_weight / 453.592 AS wet_lb,
            metrc_harvests.harvest_start AS cut
           FROM metrc_harvests
          WHERE metrc_harvests.wet_weight > 0::numeric AND (metrc_harvests.raw ->> 'FinishedDate'::text) IS NOT NULL AND NOT (metrc_harvests.name ~~* '%FF%'::text OR COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text) ~~* '%freezer%'::text)
        ), m AS (
         SELECT h.strain,
            count(*) AS harvests,
            sum(h.plants) AS plants,
            round(sum(h.packaged_lb), 1) AS packaged_lb,
            round(sum(h.packaged_lb) * 453.592 / NULLIF(sum(h.plants), 0)::numeric, 1) AS grams_per_plant,
            round(100::numeric * sum(h.packaged_lb) / NULLIF(sum(h.wet_lb), 0::numeric), 1) AS conversion_pct,
            min(h.cut) AS first_grown,
            max(h.cut) AS last_grown
           FROM h
          WHERE h.plants > 0
          GROUP BY h.strain
        )
 SELECT m.strain,
    m.harvests,
    m.plants,
    m.packaged_lb,
    m.grams_per_plant,
    m.conversion_pct,
    m.first_grown,
    m.last_grown,
    round(m.grams_per_plant * 1140::numeric / 453.592, 1) AS lb_from_a_large_room,
    round(m.grams_per_plant * 1050::numeric / 453.592, 1) AS lb_from_a_small_room,
    round(m.grams_per_plant * 1140::numeric / 453.592 - f_rule_at('harvest_goal_lb'::text), 1) AS large_room_vs_goal,
        CASE
            WHEN m.harvests >= 8 THEN 'proven'::text
            WHEN m.harvests >= 4 THEN 'indicative'::text
            ELSE 'UNPROVEN — too few harvests to judge'::text
        END AS confidence,
    GREATEST(1, LEAST(10, round(m.grams_per_plant / (f_rule_at('grams_per_plant_for_contract'::text) / 5.0))::integer)) AS yield_score,
    m.grams_per_plant >= f_rule_at('grams_per_plant_for_contract'::text) AS meets_contract_yield,
        CASE
            WHEN m.last_grown < (CURRENT_DATE - 365) THEN 'not grown in over a year'::text
            WHEN m.last_grown < (CURRENT_DATE - 180) THEN 'not grown in six months'::text
            ELSE 'in rotation'::text
        END AS currency,
    COALESCE(s.status, 'unreviewed'::text) AS status,
    s.manual_score,
    s.sells_well,
    s.notes,
    s.max_plants_per_year,
    s.decided_by,
    s.decided_on,
    COALESCE(s.manual_score, GREATEST(1, LEAST(10, round(m.grams_per_plant / (f_rule_at('grams_per_plant_for_contract'::text) / 5.0))::integer))) AS ranking_score
   FROM m
     LEFT JOIN strain_scorecard s ON s.strain = m.strain
  WHERE m.plants >= 100;
create or replace view public.v_strain_register_reconciliation as
 WITH base AS (
         SELECT l.strain,
            btrim(l.strain) AS raw_name,
            f_strain_name_class(l.strain) AS not_a_strain,
            f_strip_product_form(l.strain) AS stripped
           FROM strain_library l
        ), cand AS (
         SELECT b.strain,
            b.raw_name,
            b.not_a_strain,
            b.stripped,
                CASE
                    WHEN b.stripped ~* '^TG '::text THEN b.stripped
                    ELSE 'TG '::text || b.stripped
                END AS stripped_tg
           FROM base b
        ), m AS (
         SELECT c.strain,
            c.raw_name,
            c.not_a_strain,
            c.stripped,
            c.stripped_tg,
            ( SELECT s.name
                   FROM metrc_strains s
                  WHERE lower(btrim(s.name)) = lower(c.raw_name)
                 LIMIT 1) AS hit_exact,
            ( SELECT s.name
                   FROM metrc_strains s
                  WHERE lower(btrim(s.name)) = lower(c.stripped)
                 LIMIT 1) AS hit_stripped,
            ( SELECT s.name
                   FROM metrc_strains s
                  WHERE lower(btrim(s.name)) = lower(c.stripped_tg)
                 LIMIT 1) AS hit_stripped_tg,
            ( SELECT (a.payload -> 'cultivar'::text) ->> 'name'::text
                   FROM apex_raw a
                  WHERE a.entity = 'products'::text AND ((a.payload -> 'cultivar'::text) ->> 'name'::text) IS NOT NULL AND lower(btrim((a.payload -> 'cultivar'::text) ->> 'name'::text)) = lower(c.stripped)
                 LIMIT 1) AS hit_apex
           FROM cand c
        )
 SELECT raw_name AS strain,
        CASE
            WHEN not_a_strain IS NOT NULL THEN 3
            WHEN hit_exact IS NOT NULL THEN 1
            WHEN hit_stripped IS NOT NULL THEN 2
            WHEN hit_stripped_tg IS NOT NULL THEN 2
            WHEN hit_apex IS NOT NULL THEN 4
            ELSE 5
        END AS rung,
        CASE
            WHEN not_a_strain IS NOT NULL THEN not_a_strain
            WHEN hit_exact IS NOT NULL THEN 'REGISTERED STRAIN'::text
            WHEN hit_stripped IS NOT NULL THEN 'STRAIN + PRODUCT FORM'::text
            WHEN hit_stripped_tg IS NOT NULL THEN 'STRAIN + PRODUCT FORM (TG prefix applied)'::text
            WHEN hit_apex IS NOT NULL THEN 'CANDIDATE - Apex sells it, Metrc has not registered it'::text
            ELSE 'UNRESOLVED - needs a person'::text
        END AS verdict,
    COALESCE(hit_exact, hit_stripped, hit_stripped_tg) AS metrc_strain,
    hit_apex AS apex_cultivar,
    stripped AS name_after_stripping,
        CASE
            WHEN not_a_strain IS NOT NULL THEN 'classified by f_strain_name_class'::text
            WHEN hit_exact IS NOT NULL THEN 'exact match in metrc_strains'::text
            WHEN hit_stripped IS NOT NULL THEN 'matched metrc_strains after stripping the product form'::text
            WHEN hit_stripped_tg IS NOT NULL THEN 'matched metrc_strains after stripping the form and applying the TG prefix'::text
            WHEN hit_apex IS NOT NULL THEN 'no Metrc registration; Apex products carry this cultivar'::text
            ELSE 'no match in metrc_strains (any form) and no Apex cultivar. Registering it in Metrc, or retiring the row, is an owner decision (rule A5).'::text
        END AS evidence,
    not_a_strain IS NULL AND COALESCE(hit_exact, hit_stripped, hit_stripped_tg) IS NOT NULL AS publishable_identity
   FROM m;
create or replace view public.v_supplier_costs as
 SELECT material_type,
    supplier,
    purchases,
    total_qty,
    avg_landed_cost_per_uom,
    best_landed_cost_per_uom,
    last_purchase,
    cost_rank,
    payment_terms,
    terms_days,
    approved,
    last_purchase AS last_purchase_date
   FROM ( WITH buys AS (
                 SELECT material_purchases.supplier,
                    material_purchases.material_type,
                    count(*) AS purchases,
                    sum(material_purchases.purchased_qty) AS total_qty,
                    round(avg((COALESCE(material_purchases.purchased_qty, 0::numeric) * COALESCE(material_purchases.unit_cost, 0::numeric) + COALESCE(material_purchases.freight, 0::numeric) + COALESCE(material_purchases.other_landed_cost, 0::numeric)) / NULLIF(material_purchases.purchased_qty, 0::numeric)), 4) AS avg_landed_cost_per_uom,
                    round(min((COALESCE(material_purchases.purchased_qty, 0::numeric) * COALESCE(material_purchases.unit_cost, 0::numeric) + COALESCE(material_purchases.freight, 0::numeric) + COALESCE(material_purchases.other_landed_cost, 0::numeric)) / NULLIF(material_purchases.purchased_qty, 0::numeric)), 4) AS best_landed_cost_per_uom,
                    max(material_purchases.purchase_date) AS last_purchase
                   FROM material_purchases
                  WHERE material_purchases.purchased_qty > 0::numeric
                  GROUP BY material_purchases.supplier, material_purchases.material_type
                )
         SELECT b.material_type,
            b.supplier,
            b.purchases,
            b.total_qty,
            b.avg_landed_cost_per_uom,
            b.best_landed_cost_per_uom,
            b.last_purchase,
                CASE
                    WHEN b.avg_landed_cost_per_uom = min(b.avg_landed_cost_per_uom) OVER (PARTITION BY b.material_type) THEN 'BEST COST'::text
                    ELSE NULL::text
                END AS cost_rank,
            v.payment_terms,
            v.terms_days,
            v.approved
           FROM buys b
             LEFT JOIN vendors v ON lower(v.name) = lower(b.supplier)
          ORDER BY b.material_type, b.avg_landed_cost_per_uom) q;
create or replace view public.v_supply_consumption as
 WITH produced AS (
         SELECT p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
            count(*) AS packages,
            sum(
                CASE
                    WHEN lower(COALESCE(p.uom, ''::text)) = ANY (ARRAY['ea'::text, 'each'::text]) THEN COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric)
                    ELSE 0::numeric
                END) AS eaches,
            sum(f_to_pounds(COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric), p.uom)) AS lb
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'PackagedDate'::text, ''::text) <> ''::text AND ((p.raw ->> 'PackagedDate'::text)::date) >= (CURRENT_DATE - 180)
          GROUP BY (p.raw #>> '{Item,ProductCategoryName}'::text[]), ((p.raw ->> 'PackagedDate'::text)::date)
        ), driven AS (
         SELECT pr.category,
            pr.packaged_on,
                CASE
                    WHEN pr.eaches > 0::numeric THEN pr.eaches
                    ELSE pr.packages::numeric
                END AS units_manufactured,
            pr.lb AS lb_packaged
           FROM produced pr
        )
 SELECT r.id AS rule_id,
    s.id AS supply_item_id,
    s.name AS supply_item,
    s.category AS supply_category,
    s.unit,
    r.driver,
    r.scope_key AS applies_to_category,
    r.qty_per_driver,
    r.set_by = 'Agent I (provisional)'::text AS rate_is_provisional,
    sum(
        CASE r.driver
            WHEN 'units_manufactured'::text THEN d.units_manufactured
            WHEN 'lb_packaged'::text THEN d.lb_packaged
            ELSE 0::numeric
        END) FILTER (WHERE d.packaged_on >= (CURRENT_DATE - 30)) AS drivers_30d,
    round(sum(
        CASE r.driver
            WHEN 'units_manufactured'::text THEN d.units_manufactured
            WHEN 'lb_packaged'::text THEN d.lb_packaged
            ELSE 0::numeric
        END) FILTER (WHERE d.packaged_on >= (CURRENT_DATE - 30)) * r.qty_per_driver, 0) AS consumed_30d,
    round(sum(
        CASE r.driver
            WHEN 'units_manufactured'::text THEN d.units_manufactured
            WHEN 'lb_packaged'::text THEN d.lb_packaged
            ELSE 0::numeric
        END) FILTER (WHERE d.packaged_on >= (CURRENT_DATE - 90)) * r.qty_per_driver / 3.0, 0) AS avg_monthly_90d
   FROM supply_consumption_rule r
     JOIN supply_items s ON s.id = r.supply_item_id
     LEFT JOIN driven d ON d.category = r.scope_key
  WHERE COALESCE(r.effective_to, CURRENT_DATE) >= CURRENT_DATE
  GROUP BY r.id, s.id, s.name, s.category, s.unit, r.driver, r.scope_key, r.qty_per_driver, r.set_by;
create or replace view public.v_supply_restock_due as
 WITH harv AS (
         SELECT max(metrc_rpt_harvest_moisture.finished_on) AS last_harvest,
            ( SELECT max(metrc_harvests.harvest_start) AS max
                   FROM metrc_harvests) AS last_started
           FROM metrc_rpt_harvest_moisture
        ), pull_days AS (
         SELECT COALESCE(( SELECT conversion_factors.value::integer AS value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'pull_interval_days'::text), 14) AS d
        )
 SELECT id AS supply_item_id,
    name AS supply_item,
    category AS supply_category,
    unit,
    vendor,
    lead_time_days,
    track_enabled,
    on_hand,
    reorder_level,
    reorder_qty,
    safety_stock,
    cover_days,
    cadence_kind,
    cadence_every,
    cadence_anchor,
    last_ordered_at,
        CASE cadence_kind
            WHEN 'daily'::text THEN COALESCE(last_ordered_at, cadence_anchor) + cadence_every
            WHEN 'weekly'::text THEN COALESCE(last_ordered_at, cadence_anchor) + 7 * cadence_every
            WHEN 'monthly'::text THEN (COALESCE(last_ordered_at, cadence_anchor) + ((cadence_every || ' month'::text)::interval))::date
            WHEN 'quarterly'::text THEN (COALESCE(last_ordered_at, cadence_anchor) + (((3 * cadence_every) || ' month'::text)::interval))::date
            WHEN 'annually'::text THEN (COALESCE(last_ordered_at, cadence_anchor) + ((cadence_every || ' year'::text)::interval))::date
            WHEN 'per_harvest'::text THEN (( SELECT harv.last_harvest
               FROM harv)) + (( SELECT pull_days.d
               FROM pull_days)) * cadence_every
            WHEN 'per_pull'::text THEN (( SELECT harv.last_harvest
               FROM harv)) + (( SELECT pull_days.d
               FROM pull_days)) * cadence_every
            ELSE NULL::date
        END AS next_due,
        CASE
            WHEN NOT track_enabled THEN 'NOT TRACKED'::text
            WHEN on_hand IS NULL THEN 'NEVER COUNTED'::text
            WHEN on_hand <= COALESCE(safety_stock, 0::numeric) AND safety_stock IS NOT NULL THEN 'CRITICAL — at or below safety stock'::text
            WHEN reorder_level IS NOT NULL AND on_hand <= reorder_level THEN 'REORDER NOW — below level'::text
            WHEN (cadence_kind = ANY (ARRAY['per_harvest'::text, 'per_pull'::text])) AND (( SELECT harv.last_harvest
               FROM harv)) IS NOT NULL AND COALESCE(last_ordered_at, '1900-01-01'::date) < (( SELECT harv.last_harvest
               FROM harv)) THEN 'DUE — a harvest has come off since the last order'::text
            WHEN (cadence_kind <> ALL (ARRAY['on_demand'::text, 'per_harvest'::text, 'per_pull'::text, 'per_batch'::text])) AND COALESCE(last_ordered_at, cadence_anchor) IS NULL THEN 'NO ANCHOR DATE SET'::text
            ELSE 'OK'::text
        END AS status
   FROM supply_items si;
create or replace view public.v_sync_digest as
 SELECT (started_at AT TIME ZONE 'America/New_York'::text)::date AS day,
    endpoint,
    license AS licence,
    count(*) AS attempts,
    count(*) FILTER (WHERE status = 'ok'::text) AS completed,
    count(*) FILTER (WHERE status = 'error'::text) AS failed,
    count(*) FILTER (WHERE status = 'running'::text) AS still_running,
    count(*) FILTER (WHERE status = 'ok'::text AND COALESCE(records, 0) = 0) AS completed_but_empty,
    sum(records) FILTER (WHERE status = 'ok'::text) AS records_in,
    round(100.0 * count(*) FILTER (WHERE status = 'error'::text)::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_failed,
    max("left"(error, 120)) FILTER (WHERE status = 'error'::text) AS last_error
   FROM metrc_sync_runs
  WHERE system = 'metrc'::text
  GROUP BY ((started_at AT TIME ZONE 'America/New_York'::text)::date), endpoint, license;
create or replace view public.v_sync_report as
 WITH named AS (
         SELECT r.id,
            r.endpoint,
            r.license,
            r.started_at,
            r.finished_at,
            r.status,
            r.records,
            r.error,
                CASE
                    WHEN r.endpoint ~~* 'transfers%'::text THEN 'Manifests sync'::text
                    WHEN r.endpoint ~~* 'packages%'::text THEN 'Packages sync'::text
                    WHEN r.endpoint ~~* 'harvests%'::text OR r.endpoint ~~* 'plants%'::text OR r.endpoint ~~* 'plantbatches%'::text THEN 'Cultivation sync'::text
                    WHEN r.endpoint = ANY (ARRAY['items'::text, 'strains'::text, 'locations'::text]) THEN 'Reference data sync'::text
                    WHEN r.endpoint ~~* 'sales%'::text THEN 'Sales sync'::text
                    WHEN r.endpoint ~~* 'lab%'::text THEN 'Lab results sync'::text
                    WHEN r.endpoint ~~* 'documents%'::text THEN 'Document fetch'::text
                    WHEN r.endpoint ~~* 'google_sheet%'::text THEN 'Google Sheet sync'::text
                    WHEN r.endpoint ~~* 'clickup%'::text THEN 'ClickUp sync'::text
                    ELSE r.endpoint
                END AS agent
           FROM metrc_sync_runs r
          WHERE r.system = 'metrc'::text
        )
 SELECT id AS run_id,
    endpoint,
    agent,
    license AS licence,
    (started_at AT TIME ZONE 'America/New_York'::text) AS started_local,
    (finished_at AT TIME ZONE 'America/New_York'::text) AS finished_local,
    round(EXTRACT(epoch FROM finished_at - started_at))::integer AS seconds,
    status,
    records,
        CASE
            WHEN status = 'ok'::text AND COALESCE(records, 0) > 0 THEN ('Completed — '::text || records) || ' records'::text
            WHEN status = 'ok'::text AND COALESCE(records, 0) = 0 THEN 'Completed but brought back NOTHING — check whether that is correct'::text
            WHEN status = 'running'::text AND started_at < (now() - '01:00:00'::interval) THEN 'STUCK — started over an hour ago and never finished'::text
            WHEN status = 'running'::text THEN 'Running'::text
            WHEN error ~~* '%401%'::text THEN 'FAILED — Metrc refused the credentials (401) for licence '::text || COALESCE(license, '?'::text)
            WHEN error ~~* '%400%'::text THEN 'FAILED — Metrc rejected the request (400). Usually a bad date range or page size.'::text
            WHEN error ~~* '%unique or exclusion%'::text THEN 'FAILED — our own database rejected the rows (missing unique constraint)'::text
            WHEN error ~~* '%timeout%'::text OR error ~~* '%timed out%'::text THEN 'FAILED — timed out'::text
            ELSE 'FAILED — '::text || "left"(COALESCE(error, 'no reason recorded'::text), 90)
        END AS what_happened,
    error AS full_error,
    status = 'ok'::text AND COALESCE(records, 0) = 0 AS completed_empty,
        CASE
            WHEN license = 'MC281714'::text THEN 'Cultivation'::text
            WHEN license = 'MP281909'::text THEN 'Manufacturing'::text
            WHEN license = 'both'::text THEN 'Both licences'::text
            WHEN license = '-'::text THEN 'Not licence-specific'::text
            ELSE 'UNRECOGNISED LICENCE — '::text || COALESCE(license, 'null'::text)
        END AS licence_name
   FROM named;
create or replace view public.v_tag_attribution as
 SELECT tag,
    max(manifest_number) AS latest_manifest,
    max(counterparty_licence) AS counterparty_licence,
    max(cultivator_licence) AS cultivator_licence,
    max(cultivator_name) AS cultivator_name,
    max(manufacturer_licence) AS manufacturer_licence,
    max(manufacturer_name) AS manufacturer_name,
    max(packager_licence) AS packager_licence,
    max(packager_name) AS packager_name,
    max(attribution_source) AS attribution_source,
        CASE
            WHEN max(cultivator_licence) IS NOT NULL OR max(manufacturer_licence) IS NOT NULL THEN 'attributed'::text
            ELSE 'UNATTRIBUTED - no cultivator, manufacturer or packager recorded on any COA or manifest'::text
        END AS attribution_status
   FROM tag_event e
  GROUP BY tag;
create or replace view public.v_tag_dwell as
 WITH ordered AS (
         SELECT tag_event.tag,
            tag_event.event_at,
            tag_event.event_type,
            tag_event.stage,
            tag_event.location,
            tag_event.manifest_number,
            tag_event.qty,
            tag_event.uom,
            lead(tag_event.event_at) OVER (PARTITION BY tag_event.tag ORDER BY tag_event.event_at, tag_event.id) AS next_at,
            lead(tag_event.event_type) OVER (PARTITION BY tag_event.tag ORDER BY tag_event.event_at, tag_event.id) AS next_type
           FROM tag_event
        )
 SELECT tag,
    event_type,
    stage,
    location,
    manifest_number,
    qty,
    uom,
    event_at,
    next_at,
    next_type,
    next_at IS NULL AS still_open,
    round(EXTRACT(epoch FROM COALESCE(next_at, now()) - event_at) / 86400.0, 1) AS days_here
   FROM ordered;
create or replace view public.v_tag_dwell_coverage as
 SELECT ( SELECT count(DISTINCT tag_event.tag) AS count
           FROM tag_event) AS tags_with_any_event,
    ( SELECT count(*) AS count
           FROM metrc_packages
          WHERE metrc_packages.tag IS NOT NULL) AS metrc_packages_total,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE p.tag IS NOT NULL AND NOT (EXISTS ( SELECT 1
                   FROM tag_event e
                  WHERE e.tag = p.tag))) AS packages_with_no_event,
    ( SELECT count(*) AS count
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL) AS coa_rows,
    ( SELECT count(*) AS count
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL AND coa_extract.report_date IS NOT NULL AND coa_extract.report_date !~ '^\s*\d{4}-\d{2}-\d{2}'::text AND coa_extract.report_date !~ '^\s*\d{1,2}/\d{1,2}/\d{4}'::text) AS coa_dates_unparseable,
    ( SELECT count(*) AS count
           FROM turnaround_target
          WHERE turnaround_target.set_by = 'placeholder'::text) AS targets_still_placeholder;
create or replace view public.v_tag_ledger as
 WITH shipped AS (
         SELECT t.package_tag,
            string_agg(DISTINCT m.manifest_number, ', '::text ORDER BY m.manifest_number) AS manifests,
            string_agg(DISTINCT m.destination_facility, ', '::text) AS destinations,
            string_agg(DISTINCT m.destination_licence, ', '::text) AS destination_licences,
            string_agg(DISTINCT m.transfer_type, ', '::text) AS transfer_types,
            max(COALESCE(m.created_on, m.received_on)) AS last_shipped_on,
            round(sum(t.shipped_lb), 3) AS shipped_lb,
            round(sum(t.shipper_wholesale_price), 2) AS shipper_value
           FROM metrc_rpt_package_transfers t
             JOIN metrc_rpt_transfer_manifests m ON m.manifest_number = t.manifest_number
          WHERE m.direction = 'outbound'::text
          GROUP BY t.package_tag
        )
 SELECT p.raw ->> 'Label'::text AS package_tag,
    p.raw #>> '{Item,Name}'::text[] AS item,
    f_strain_from_item(p.raw #>> '{Item,Name}'::text[]) AS strain,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(not recorded)'::text) AS harvested_by,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS harvested_by_licence,
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS ownership_label,
    COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND NOT COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) AS in_stock,
        CASE
            WHEN COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND NOT COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) THEN COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text)
            ELSE NULL::text
        END AS room,
        CASE
            WHEN COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND NOT COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) THEN p.license
            ELSE NULL::text
        END AS held_by_licence,
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN round(f_to_pounds(COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3)
            ELSE NULL::numeric
        END AS lb_on_hand,
    s.manifests AS outbound_manifests,
    s.destinations AS shipped_to,
    s.destination_licences AS shipped_to_licence,
    s.transfer_types,
    s.last_shipped_on,
    s.shipped_lb,
    s.shipper_value,
        CASE
            WHEN COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND NOT COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) THEN ((('IN STOCK — '::text || COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text)) || ' ('::text) || p.license) || ')'::text
            WHEN s.package_tag IS NOT NULL THEN ((((('SHIPPED '::text || to_char(s.last_shipped_on::timestamp with time zone, 'YYYY-MM-DD'::text)) || ' on manifest '::text) || s.manifests) || ' to '::text) || COALESCE(s.destinations, '?'::text)) ||
            CASE
                WHEN s.destination_licences ~* 'MT'::text THEN ' [TRANSPORTER — storage/haulage, not a sale]'::text
                WHEN s.transfer_types ~~* '%Lab%'::text THEN ' [LABORATORY — testing]'::text
                WHEN s.transfer_types ~~* '%Affiliated%'::text THEN ' [OUR OWN OTHER LICENCE — internal transfer between two legal entities]'::text
                ELSE ' [ARM''S LENGTH LICENSEE — check Apex for the sale]'::text
            END
            WHEN COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) THEN 'FINISHED — consumed or repackaged here, never shipped'::text
            ELSE 'ZERO QUANTITY — drawn down here, no outbound manifest'::text
        END AS where_is_it,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
    NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
    p.raw ->> 'LabTestingState'::text AS lab_state,
    c.package_tag IS NOT NULL AS has_coa,
    c.document_id AS coa_document_id
   FROM metrc_packages p
     LEFT JOIN shipped s ON s.package_tag = (p.raw ->> 'Label'::text)
     LEFT JOIN coa_extract c ON c.package_tag = (p.raw ->> 'Label'::text);
create or replace view public.v_tag_movement_forensic as
 WITH out_moves AS (
         SELECT t.package_tag,
            string_agg(DISTINCT m.manifest_number, ', '::text ORDER BY m.manifest_number) AS outbound_manifests,
            string_agg(DISTINCT m.destination_facility, ', '::text) AS shipped_to,
            string_agg(DISTINCT m.destination_licence, ', '::text) AS shipped_to_licence,
            string_agg(DISTINCT m.transfer_type, ', '::text) AS outbound_types,
            max(COALESCE(m.created_on, m.received_on)) AS last_shipped_on
           FROM metrc_rpt_package_transfers t
             JOIN metrc_rpt_transfer_manifests m ON m.manifest_number = t.manifest_number
          WHERE m.direction = 'outbound'::text
          GROUP BY t.package_tag
        )
 SELECT p.raw ->> 'Label'::text AS package_tag,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS current_room,
    p.license AS current_licence,
        CASE
            WHEN p.license = 'MC281714'::text THEN 'CULTIVATION'::text
            WHEN p.license = 'MP281909'::text THEN 'MANUFACTURING'::text
            ELSE p.license
        END AS current_department,
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN round(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3)
            ELSE NULL::numeric
        END AS lb_on_hand,
        CASE
            WHEN NOT f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN (p.raw ->> 'Quantity'::text)::numeric
            ELSE NULL::numeric
        END AS units_on_hand,
    p.raw #>> '{Item,Name}'::text[] AS item,
    f_strain_from_item(p.raw #>> '{Item,Name}'::text[]) AS strain,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
    p.raw ->> 'LabTestingState'::text AS lab_state,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(not recorded)'::text) AS cultivated_by,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS cultivated_by_licence,
    NOT f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) AS is_third_party,
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS ownership_label,
        CASE
            WHEN NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) IS NOT NULL THEN (('ARRIVED ON MANIFEST '::text || (p.raw ->> 'ReceivedFromManifestNumber'::text)) || ' from '::text) || COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '?'::text)
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN ('REPACKAGED here from '::text || array_length(string_to_array(p.raw ->> 'SourcePackageLabels'::text, ', '::text), 1)::text) || ' source tag(s)'::text
            WHEN NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL THEN 'MADE HERE off harvest '::text || (p.raw ->> 'SourceHarvestNames'::text)
            ELSE 'origin not recorded'::text
        END AS how_it_arrived,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '—'::text) AS received_from,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS received_from_licence,
    (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
    NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
    f_is_ours(COALESCE(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text)) AND NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) IS DISTINCT FROM p.license AS crossed_our_licences,
        CASE
            WHEN f_is_ours(COALESCE(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text)) AND NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) IS DISTINCT FROM p.license THEN ((('INTERNAL TRANSFER '::text || (p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text)) || ' -> '::text) || p.license) || ' — NOT A SALE'::text
            ELSE NULL::text
        END AS internal_move,
    o.outbound_manifests,
    o.shipped_to,
    o.shipped_to_licence,
    o.outbound_types,
    o.last_shipped_on,
        CASE
            WHEN o.package_tag IS NULL THEN 'STILL HELD — never shipped out'::text
            WHEN o.shipped_to_licence ~~* '%MT%'::text THEN 'went to a TRANSPORTER — storage or haulage, not a sale'::text
            WHEN o.outbound_types ~~* '%Lab%'::text THEN 'went to a LABORATORY — testing'::text
            WHEN o.outbound_types ~~* '%Affiliated%'::text THEN 'went to OUR OTHER LICENCE — internal, not a sale'::text
            ELSE 'went to another licensee — check Apex for the sale'::text
        END AS final_destination
   FROM metrc_packages p
     LEFT JOIN out_moves o ON o.package_tag = (p.raw ->> 'Label'::text)
  WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false;
create or replace view public.v_tag_provenance as
 SELECT p.raw ->> 'Label'::text AS package_tag,
    p.license AS held_by_licence,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS current_room,
    p.raw #>> '{Item,Name}'::text[] AS item,
    f_strain_from_item(p.raw #>> '{Item,Name}'::text[]) AS strain,
    COALESCE(NULLIF(p.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), '(none)'::text) AS category,
    (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
        CASE
            WHEN f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN round(f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3)
            ELSE NULL::numeric
        END AS lb,
        CASE
            WHEN NOT f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) THEN (p.raw ->> 'Quantity'::text)::numeric
            ELSE NULL::numeric
        END AS units,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(not recorded)'::text) AS harvested_by,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS harvested_by_licence,
        CASE
            WHEN NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) IS NULL THEN 'UNKNOWN'::text
            WHEN f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS harvested_by_ownership,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
        CASE
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN COALESCE(( SELECT cl.label
               FROM company_licenses cl
              WHERE cl.license = p.license
             LIMIT 1), p.license)
            ELSE NULL::text
        END AS repackaged_by,
        CASE
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN p.license
            ELSE NULL::text
        END AS repackaged_by_licence,
        CASE
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL THEN NULL::text
            WHEN f_is_ours(p.license) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS repackaged_by_ownership,
        CASE
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN array_length(string_to_array(p.raw ->> 'SourcePackageLabels'::text, ', '::text), 1)
            ELSE NULL::integer
        END AS source_tag_count,
    NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
        CASE
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~* '(concentrate|vape|edible|pre-?roll|infused|tincture|topical)'::text THEN COALESCE(( SELECT cl.label
               FROM company_licenses cl
              WHERE cl.license = p.license
             LIMIT 1), p.license)
            ELSE NULL::text
        END AS manufactured_by,
        CASE
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~* '(concentrate|vape|edible|pre-?roll|infused|tincture|topical)'::text THEN p.license
            ELSE NULL::text
        END AS manufactured_by_licence,
        CASE
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) !~* '(concentrate|vape|edible|pre-?roll|infused|tincture|topical)'::text THEN NULL::text
            WHEN f_is_ours(p.license) THEN 'OURS'::text
            ELSE 'THIRD PARTY'::text
        END AS manufactured_by_ownership,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '—'::text) AS shipped_to_us_by,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text), '—'::text) AS shipped_to_us_by_licence,
    (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
    (((((((((('HARVESTED BY '::text || COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '?'::text)) || ' ('::text) || COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), '?'::text)) || ')'::text) ||
        CASE
            WHEN NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) IS NOT NULL THEN ' · shipped to us on manifest '::text || (p.raw ->> 'ReceivedFromManifestNumber'::text)
            ELSE ''::text
        END) ||
        CASE
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN ' · REPACKAGED BY '::text || p.license
            ELSE ''::text
        END) ||
        CASE
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~* '(concentrate|vape|edible|pre-?roll|infused|tincture|topical)'::text THEN ' · MANUFACTURED BY '::text || p.license
            ELSE ''::text
        END) || ' · now in '::text) || COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text)) || ' under '::text) || p.license AS provenance,
    p.raw ->> 'LabTestingState'::text AS lab_state,
    c.package_tag IS NOT NULL AS has_coa,
    c.document_id AS coa_document_id
   FROM metrc_packages p
     LEFT JOIN coa_extract c ON c.package_tag = (p.raw ->> 'Label'::text)
  WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false;
create or replace view public.v_tag_turnaround as
 WITH j AS (
         SELECT tag_event.tag,
            min(tag_event.event_at) FILTER (WHERE tag_event.event_type = 'packaged'::text) AS packaged_at,
            min(tag_event.event_at) FILTER (WHERE tag_event.event_type = 'tested'::text) AS tested_at,
            max(tag_event.event_at) FILTER (WHERE tag_event.event_type = 'shipped'::text) AS shipped_at,
            max(tag_event.event_at) FILTER (WHERE tag_event.event_type = 'received'::text) AS received_at,
            max(tag_event.event_at) AS last_seen,
            count(*) AS events
           FROM tag_event
          GROUP BY tag_event.tag
        ), t AS (
         SELECT turnaround_target.stage,
            turnaround_target.target_days,
            turnaround_target.warn_at_pct
           FROM turnaround_target
          WHERE turnaround_target.scope = 'company'::text
        )
 SELECT tag,
    packaged_at,
    tested_at,
    shipped_at,
    received_at,
    last_seen,
    events,
    round(EXTRACT(epoch FROM tested_at - packaged_at) / 86400.0, 1) AS days_to_test,
    round(EXTRACT(epoch FROM shipped_at - packaged_at) / 86400.0, 1) AS days_to_ship,
    packaged_at IS NOT NULL AND shipped_at IS NULL AS still_on_hand,
        CASE
            WHEN packaged_at IS NOT NULL AND shipped_at IS NULL THEN round(EXTRACT(epoch FROM now() - packaged_at) / 86400.0, 1)
            ELSE NULL::numeric
        END AS days_on_hand,
    ( SELECT t.target_days
           FROM t
          WHERE t.stage = 'on hand'::text) AS target_on_hand_days,
        CASE
            WHEN packaged_at IS NULL OR shipped_at IS NOT NULL THEN NULL::text
            WHEN (EXTRACT(epoch FROM now() - packaged_at) / 86400.0) >= (( SELECT t.target_days
               FROM t
              WHERE t.stage = 'on hand'::text))::numeric THEN 'OVER TARGET'::text
            WHEN (EXTRACT(epoch FROM now() - packaged_at) / 86400.0) >= (( SELECT (t.target_days * t.warn_at_pct)::numeric / 100.0
               FROM t
              WHERE t.stage = 'on hand'::text)) THEN 'approaching'::text
            ELSE 'within target'::text
        END AS on_hand_status
   FROM j;
create or replace view public.v_task_timeline as
 SELECT t.id AS task_id,
    t.title,
    t.status,
    t.priority,
    t.space_id,
    t.team_id,
    t.assignee_employee_id,
    t.start_on,
    t.due_on,
        CASE
            WHEN t.start_on IS NOT NULL AND t.due_on IS NOT NULL THEN t.due_on - t.start_on
            ELSE NULL::integer
        END AS duration_days,
    COALESCE(p.predecessor_count, 0::bigint) AS predecessor_count,
    p.predecessor_names,
    p.blocking_predecessor_names,
        CASE
            WHEN p.unfinished_count > 0 THEN 'BLOCKED - predecessor not finished'::text
            WHEN p.conflict_count > 0 THEN 'SCHEDULE CONFLICT - starts before predecessor finishes'::text
            ELSE NULL::text
        END AS warning,
    t.created_at,
    t.updated_at
   FROM tasks t
     LEFT JOIN LATERAL ( SELECT count(*) AS predecessor_count,
            count(*) FILTER (WHERE pred.status IS DISTINCT FROM 'done'::text) AS unfinished_count,
            count(*) FILTER (WHERE t.start_on IS NOT NULL AND pred.due_on IS NOT NULL AND t.start_on < pred.due_on) AS conflict_count,
            string_agg(pred.title, ', '::text ORDER BY pred.title) AS predecessor_names,
            string_agg(pred.title, ', '::text ORDER BY pred.title) FILTER (WHERE pred.status IS DISTINCT FROM 'done'::text) AS blocking_predecessor_names
           FROM task_dependencies d
             JOIN tasks pred ON pred.id = d.depends_on_id
          WHERE d.task_id = t.id) p ON true;
create or replace view public.v_task_workload as
 SELECT e.id AS employee_id,
    e.full_name AS employee_name,
    t.due_on AS due_date,
    count(*) AS tasks_due,
    count(*) FILTER (WHERE t.priority = ANY (ARRAY['P0'::text, 'P1'::text])) AS high_priority_tasks,
        CASE
            WHEN count(*) > 5 THEN 'OVERLOADED'::text
            WHEN count(*) >= 4 THEN 'HEAVY'::text
            ELSE 'Normal'::text
        END AS workload_status
   FROM tasks t
     JOIN employees e ON e.id = t.assignee_employee_id
  WHERE t.status IS DISTINCT FROM 'done'::text AND t.due_on IS NOT NULL
  GROUP BY e.id, e.full_name, t.due_on
  ORDER BY e.full_name, t.due_on;
create or replace view public.v_testing_sla_matrix as
 SELECT COALESCE(s.rule_code, '—'::text) AS rule_id,
    COALESCE(s.product_family, pf.name, '—'::text) AS product_family,
    s.batch_size_min AS minimum_batch_size,
    s.batch_size_max AS maximum_batch_size,
    s.test_type,
    s.sample_qty AS sample_quantity,
    s.sample_prep_hours,
    s.laboratory,
    s.lead_days AS lab_lead_days,
        CASE
            WHEN s.active THEN 'Yes'::text
            ELSE 'No'::text
        END AS active
   FROM testing_slas s
     LEFT JOIN product_families pf ON pf.id = s.product_family_id
  ORDER BY s.product_family, s.batch_size_min;
create or replace view public.v_tile_drill_freshness as
 SELECT max(computed_at) AS computed_at,
    now() - max(computed_at) AS age,
    count(*) AS contracts,
    count(*) FILTER (WHERE verdict <> 'AGREE'::text) AS disagreeing,
        CASE
            WHEN max(computed_at) IS NULL THEN 'NEVER COMPUTED — the reconciliation has not run since this table was created'::text
            WHEN (now() - max(computed_at)) > '02:00:00'::interval THEN 'STALE — older than 2 hours, treat these verdicts as of '::text || max(computed_at)::text
            ELSE 'ok'::text
        END AS verdict
   FROM tile_drill_result;
create or replace view public.v_tile_drill_status as
 SELECT contract_key,
    page,
    tile_label,
    tile_value,
    drill_value,
    gap,
    verdict,
    computed_at
   FROM tile_drill_result r;
create or replace view public.v_tile_drill_status_live as
 SELECT contract_key,
    page,
    tile_label,
    tile_value,
    drill_value,
    gap,
    verdict
   FROM tg_check_tile_drill() tg_check_tile_drill(contract_key, page, tile_label, tile_value, drill_value, gap, verdict);
create or replace view public.v_transfer_line as
 SELECT manifest_number,
    package_tag,
    received_on,
    COALESCE(NULLIF(source_row ->> 'Origin Lic.'::text, ''::text), licence) AS origin_licence,
    COALESCE(NULLIF(source_row ->> 'Dest. Lic.'::text, ''::text), destination_licence) AS dest_licence,
    NULLIF(source_row ->> 'Origin Facility'::text, ''::text) AS origin_facility,
    COALESCE(NULLIF(destination_facility, ''::text), NULLIF(source_row ->> 'Destination Facility'::text, ''::text)) AS dest_facility,
    COALESCE(
        CASE
            WHEN (source_row ->> 'Weight Ship''d'::text) ~ '^[0-9]+(\.[0-9]+)?$'::text THEN (source_row ->> 'Weight Ship''d'::text)::numeric
            ELSE NULL::numeric
        END, shipped_lb) AS pounds,
        CASE
            WHEN (source_row ->> 'Weight Ship''d'::text) ~ '^[0-9]+(\.[0-9]+)?$'::text THEN 'Metrc Weight Ship''d'::text
            ELSE 'derived from item catalogue UoM'::text
        END AS weight_source,
    item,
    category,
    strain,
    status,
    source_row ->> 'Type'::text AS transfer_type,
    COALESCE(source_row ->> 'Voided'::text, 'False'::text) AS voided,
    f_is_ours(COALESCE(NULLIF(source_row ->> 'Origin Lic.'::text, ''::text), licence)) AS origin_is_ours,
    f_is_ours(COALESCE(NULLIF(source_row ->> 'Dest. Lic.'::text, ''::text), destination_licence)) AS dest_is_ours,
        CASE
            WHEN f_is_ours(COALESCE(NULLIF(source_row ->> 'Origin Lic.'::text, ''::text), licence)) AND f_is_ours(COALESCE(NULLIF(source_row ->> 'Dest. Lic.'::text, ''::text), destination_licence)) THEN 'INTERNAL'::text
            WHEN f_is_ours(COALESCE(NULLIF(source_row ->> 'Origin Lic.'::text, ''::text), licence)) THEN 'OUTBOUND'::text
            WHEN f_is_ours(COALESCE(NULLIF(source_row ->> 'Dest. Lic.'::text, ''::text), destination_licence)) THEN 'INBOUND'::text
            ELSE 'THIRD PARTY BOTH ENDS'::text
        END AS direction
   FROM metrc_rpt_package_transfers t;
create or replace view public.v_trap_scan as
 WITH objs AS (
         SELECT c.relname AS object_name,
            pg_get_viewdef(c.oid, true) AS def,
            'view'::text AS kind
           FROM pg_class c
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"])) AND c.relname <> 'v_trap_scan'::name
        UNION ALL
         SELECT p.proname,
            p.prosrc,
            'function'::text
           FROM pg_proc p
             JOIN pg_namespace n ON n.oid = p.pronamespace
          WHERE n.nspname = 'public'::name AND p.prokind = 'f'::"char" AND (p.proname <> ALL (ARRAY['f_quantity_text'::name, 'f_any_ours'::name, 'f_all_ours'::name, 'f_licence_in_set'::name]))
        )
 SELECT objs.object_name,
    'countable-items-dropped'::text AS trap,
    'critical'::text AS severity,
    'Converts to pounds under f_is_weight but never reports the count, so every countable item publishes as nothing and any total excludes it silently.'::text AS what_is_wrong,
    'Add a units column and use f_quantity_text(qty, uom). Cross-check v_countable_inventory.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'f_is_weight'::text AND objs.def ~* 'f_to_pounds'::text AND objs.def !~* '(f_quantity_text|as +[a-z_]*units|unit_of_measure)'::text
UNION ALL
 SELECT objs.object_name,
    'licence-list-vs-single-test'::text AS trap,
    'critical'::text AS severity,
    'Applies f_is_ours() to a certificate licence field. That field can hold "MC281714, MP281909" and f_is_ours returns FALSE on a list - it matches neither member and never errors. 621 of 983 certificates are stored that way.'::text AS what_is_wrong,
    'Use f_any_ours() / f_all_ours(), or f_licence_in_set() for membership.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~ 'f_is_ours\s*\(\s*[a-z_.]*(client_license|cert_license)'::text
UNION ALL
 SELECT objs.object_name,
    'substring-match-on-licence'::text AS trap,
    'elevated'::text AS severity,
    'Uses position()/LIKE against a licence number. A substring test matches quietly - it will not error, it will answer a slightly different question.'::text AS what_is_wrong,
    'Use f_licence_in_set() for exact membership after splitting on commas.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'position\s*\(\s*[("'']*\s*[a-z_.]*licen'::text OR objs.def ~* 'licen[a-z_]*\s+i?like\s+''%'::text
UNION ALL
 SELECT objs.object_name,
    'wet-and-dry-mixed'::text AS trap,
    'critical'::text AS severity,
    'Sums a weight in an object that touches fresh frozen with NO stream, basis or wet/dry separation anywhere in it. Fresh frozen is WET: 603.9 lb wet is 134.2 lb dry-equivalent at the configured 4.5.'::text AS what_is_wrong,
    'Separate the basis, or divide fresh frozen by f_rule(''fresh_frozen_wet_to_dry''). Name the column so the basis cannot be lost.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'fresh.?frozen'::text AND objs.def ~* 'sum\s*\('::text AND objs.def !~* '(wet|dry|_equiv|stream|basis|fresh_frozen_lbs|fresh_frozen_wet_to_dry)'::text
UNION ALL
 SELECT objs.object_name,
    'estimate-used-as-count'::text AS trap,
    'critical'::text AS severity,
    'Reads reltuples, a planner ESTIMATE that returns 0 on small or freshly written tables. Five populated tables were reported empty this way.'::text AS what_is_wrong,
    'Use select count(*).'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'reltuples'::text
UNION ALL
 SELECT objs.object_name,
    'ordering-decides-evidence'::text AS trap,
    'critical'::text AS severity,
    'Uses row_number()/distinct on to pick ONE row from conflicting sources. If those rows disagree on substance the ORDER BY is making the judgement, not the evidence, and it will never say so. On 7 Aug an ordering decided 142 of 191 ownership verdicts - reversing one word moved the answer from 19 packages to 156.'::text AS what_is_wrong,
    'State the reason in the object, and surface the disagreement in a companion view rather than resolving it silently. Disagreement is the finding.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE (objs.def ~* 'row_number\s*\(\s*\)\s*over'::text OR objs.def ~* 'distinct\s+on'::text) AND objs.def ~* '(cert|origin|licen|owner|depth|priority)'::text
UNION ALL
 SELECT objs.object_name,
    'transporter-in-revenue'::text AS trap,
    'critical'::text AS severity,
    'Computes revenue or a price without excluding transporter/storage destinations. An MT or MX licence destination is NEVER a sale - material goes to storage and comes back. $901,430 was booked as revenue this way.'::text AS what_is_wrong,
    'Exclude MT/MX destinations, and label every Metrc-derived price a DECLARED transfer price - Apex is the sales source of record.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* '(revenue|sale_price|realised|realized|price_per|total_price)'::text AND objs.def ~* 'sum\s*\('::text AND objs.def !~* '(MT[0-9]|MX[0-9]|transporter|destination_kind)'::text
UNION ALL
 SELECT objs.object_name,
    'truncated-tag'::text AS trap,
    'elevated'::text AS severity,
    'Joins or stores a Metrc tag without requiring the full 24 characters. Truncated tags have already collided - "3136" matches one of OUR packages and an outside one.'::text AS what_is_wrong,
    'Resolve full 24-character tags before any join, and reject an ambiguous match rather than storing it.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* '(right|substr|substring)\s*\(\s*[a-z_.]*(tag|label)'::text
UNION ALL
 SELECT objs.object_name,
    'count-star-on-aggregate'::text AS trap,
    'elevated'::text AS severity,
    'Uses count(*) against a view that is already aggregated, which returns the number of GROUPS, not the number of packages.'::text AS what_is_wrong,
    'Use sum(packages), or count the base rows.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'count\s*\(\s*\*\s*\)'::text AND objs.def ~* 'from\s+v_[a-z_]*(summary|by_|totals|position)'::text
UNION ALL
 SELECT objs.object_name,
    'repack-as-primary'::text AS trap,
    'elevated'::text AS severity,
    'Counts production or yield without excluding repackaged material. A repack keeps the original harvest name; counting it inflates production by up to 142%.'::text AS what_is_wrong,
    'Primary production is SourcePackageCount = 0. Filter on it explicitly.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* '(production|yield|harvested|packaged_lb)'::text AND objs.def ~* 'sum\s*\('::text AND objs.def ~* 'sourceharvestnames'::text AND objs.def !~* 'sourcepackagecount'::text
UNION ALL
 SELECT o.object_name,
    'no-registered-proof'::text AS trap,
    'elevated'::text AS severity,
    'Publishes findings to people but no brain_claims row names it in covers_object with a proof that reaches the figure independently. A rule with no check expires.'::text AS what_is_wrong,
    'Register a claim with covers_object set to this object and a proof_sql that derives the number from BASE TABLES. A proof that selects from the view it checks cannot fail and proves nothing.'::text AS what_to_do,
    o.kind
   FROM objs o
  WHERE o.def ~* 'what_is_wrong'::text AND o.kind = 'view'::text AND NOT (EXISTS ( SELECT 1
           FROM brain_claims b
          WHERE b.covers_object = o.object_name AND b.proof_sql !~* ('from\s+'::text || o.object_name::text)));
create or replace view public.v_true_cost_per_pound as
 SELECT to_char(harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
    date_trunc('month'::text, harvest_start::timestamp with time zone)::date AS month_date,
    count(*)::numeric AS harvests,
    sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants_harvested,
    round(sum(COALESCE((raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS wet_lbs,
    round(sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS saleable_lbs,
        CASE
            WHEN sum(COALESCE((raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
            ELSE NULL::numeric
        END AS wet_to_saleable_pct,
    ( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1) AS target_cost_per_pound,
    round(sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592 * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS period_cost_at_target,
        CASE
            WHEN sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) / (sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592), 1)
            ELSE NULL::numeric
        END AS plants_per_saleable_pound,
        CASE
            WHEN sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) > 0::numeric THEN round(sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592 / sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) * 453.592, 1)
            ELSE NULL::numeric
        END AS grams_per_plant
   FROM metrc_harvests h
  WHERE harvest_start IS NOT NULL
  GROUP BY (to_char(harvest_start::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, harvest_start::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, harvest_start::timestamp with time zone)::date) DESC;
create or replace view public.v_truncate_exposure as
 SELECT table_name,
    string_agg(DISTINCT grantee::text, ', '::text ORDER BY (grantee::text)) AS browser_facing_roles,
    (EXISTS ( SELECT 1
           FROM pg_trigger t
             JOIN pg_class c ON c.oid = t.tgrelid
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND c.relname = g.table_name::name AND NOT t.tgisinternal)) AS has_a_trigger_truncate_would_bypass
   FROM information_schema.role_table_grants g
  WHERE table_schema::name = 'public'::name AND privilege_type::text = 'TRUNCATE'::text AND (grantee::name = ANY (ARRAY['anon'::name, 'authenticated'::name, 'PUBLIC'::name]))
  GROUP BY table_name
  ORDER BY ((EXISTS ( SELECT 1
           FROM pg_trigger t
             JOIN pg_class c ON c.oid = t.tgrelid
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND c.relname = g.table_name::name AND NOT t.tgisinternal))) DESC, table_name;
create or replace view public.v_turnaround_watch as
 SELECT id,
    pipeline,
    brand,
    sku,
    category,
    material_name,
    source_kind,
    started,
    days_open,
    policy_max_days,
    policy_scope,
    turnaround_violation,
    no_policy_set,
    started AS started_date
   FROM ( SELECT r.id,
            p.name AS pipeline,
            r.brand,
            r.sku,
            r.category,
            r.material_name,
            r.source_kind,
            r.started_at::date AS started,
            round(EXTRACT(epoch FROM now() - r.started_at) / 86400::numeric, 1) AS days_open,
            pol.max_days AS policy_max_days,
            pol.scope AS policy_scope,
            pol.max_days IS NOT NULL AND (EXTRACT(epoch FROM now() - r.started_at) / 86400::numeric) > pol.max_days AS turnaround_violation,
            pol.max_days IS NULL AS no_policy_set
           FROM pipeline_runs r
             JOIN pipelines p ON p.id = r.pipeline_id
             LEFT JOIN LATERAL ( SELECT tp.max_days,
                    tp.scope
                   FROM turnaround_policies tp
                  WHERE tp.active AND (tp.applies_to = 'any'::text OR tp.applies_to = r.source_kind) AND (tp.scope = 'sku'::text AND tp.scope_value = r.sku OR tp.scope = 'item'::text AND tp.scope_value = r.material_name OR tp.scope = 'brand'::text AND tp.scope_value = r.brand OR tp.scope = 'category'::text AND tp.scope_value = r.category OR tp.scope = 'default'::text)
                  ORDER BY (
                        CASE tp.scope
                            WHEN 'sku'::text THEN 1
                            WHEN 'item'::text THEN 2
                            WHEN 'brand'::text THEN 3
                            WHEN 'category'::text THEN 4
                            ELSE 5
                        END)
                 LIMIT 1) pol ON true
          WHERE r.completed_at IS NULL
          ORDER BY (round(EXTRACT(epoch FROM now() - r.started_at) / 86400::numeric, 1)) DESC) q;
create or replace view public.v_unchallenged_findings as
 SELECT id,
    fingerprint,
    severity,
    what,
    the_arithmetic,
    record_count,
    who_is_accountable,
    'Nobody has attempted to refute this. Per brain/INDEX.md the Challenger defaults to REFUTED and makes a claim earn survival - an unchallenged finding has not earned anything yet.'::text AS why_it_matters
   FROM watchdog_findings f
  WHERE challenge_verdict IS NULL
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), record_count DESC NULLS LAST;
create or replace view public.v_under_utilised as
 WITH pol AS (
         SELECT attendance_policy.full_time_min_hours,
            attendance_policy.ot_weekly_threshold,
            attendance_policy.shortfall_tolerance_hours
           FROM attendance_policy
         LIMIT 1
        ), wk AS (
         SELECT t.employee_id,
            date_trunc('week'::text, t.work_date::timestamp with time zone)::date AS week_start,
            sum(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) AS worked_hours
           FROM time_entries t
          WHERE t.clock_in IS NOT NULL AND t.clock_out IS NOT NULL
          GROUP BY t.employee_id, (date_trunc('week'::text, t.work_date::timestamp with time zone)::date)
        )
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    d.name AS department,
    wk.week_start,
    COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold)::numeric AS target_hours,
    round(wk.worked_hours, 2) AS worked_hours,
    round(COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold) - wk.worked_hours, 2) AS short_hours,
    round(100.0 * wk.worked_hours / NULLIF(COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold), 0::numeric), 1) AS utilisation_pct,
        CASE
            WHEN e.hours_basis = 'weekly_minimum'::text THEN round((COALESCE(e.weekly_target_hours, 0::numeric) - wk.worked_hours) * r.rate * (1::numeric + COALESCE(r.burden_pct, 0::numeric)), 2)
            ELSE NULL::numeric
        END AS paid_for_unworked_loaded,
    e.hours_basis,
        CASE
            WHEN e.hours_basis = 'weekly_minimum'::text THEN 'below contracted minimum'::text
            ELSE 'below target'::text
        END AS shortfall_kind
   FROM wk
     CROSS JOIN pol
     JOIN employees e ON e.id = wk.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
     LEFT JOIN LATERAL ( SELECT r2.id,
            r2.employee_id,
            r2.basis,
            r2.rate,
            r2.ot_multiplier,
            r2.burden_pct,
            r2.effective_from,
            r2.effective_to,
            r2.approved_by,
            r2.note,
            r2.effective_from_date
           FROM employee_rates r2
          WHERE r2.employee_id = e.id AND r2.effective_from <= wk.week_start AND (r2.effective_to IS NULL OR r2.effective_to >= wk.week_start)
          ORDER BY r2.effective_from DESC
         LIMIT 1) r ON true
  WHERE COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold) >= pol.full_time_min_hours AND wk.worked_hours < (COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold) - pol.shortfall_tolerance_hours);
create or replace view public.v_unresolved_register as
 SELECT id,
    agent,
    headline,
    detail,
    action,
    drill_to,
    fingerprint,
    detected_at::date AS first_raised,
    CURRENT_DATE - detected_at::date AS days_open,
    severity AS raised_as,
        CASE
            WHEN severity = 'critical'::text AND (CURRENT_DATE - detected_at::date) >= 3 THEN 'critical'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 30 THEN 'critical'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 14 THEN 'elevated'::text
            WHEN severity = 'critical'::text THEN 'critical'::text
            ELSE severity
        END AS severity_now,
        CASE
            WHEN (CURRENT_DATE - detected_at::date) = 0 THEN 'Raised today.'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 30 THEN (('Open '::text || (CURRENT_DATE - detected_at::date)) || ' days. This has been asked every day '::text) || 'for a month and is now treated as critical whatever it was raised as.'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 14 THEN ('Open '::text || (CURRENT_DATE - detected_at::date)) || ' days and escalating.'::text
            ELSE ('Open '::text || (CURRENT_DATE - detected_at::date)) || ' days.'::text
        END AS how_long,
    metric,
    units,
    dollars
   FROM agent_findings f
  WHERE resolved_at IS NULL AND (severity = ANY (ARRAY['critical'::text, 'elevated'::text, 'watch'::text]));
create or replace view public.v_valuation_basis as
 SELECT stream,
    dollars_per_pound,
    basis,
    source_note,
    confirmed,
    set_by,
    set_at::date AS set_on,
    effective_from,
    ( SELECT count(*) AS count
           FROM valuation_overrides o
          WHERE o.stream = r.stream) AS overrides_on_this_stream,
        CASE
            WHEN confirmed THEN ((((((((('Rate of $'::text || dollars_per_pound) || ' per pound for '::text) || stream) || ', set by '::text) || COALESCE(set_by, 'unknown'::text)) || ' on '::text) || to_char(set_at, 'DD Mon YYYY'::text)) || '. Basis: '::text) || basis) || '.'::text
            ELSE ((((('UNCONFIRMED — $'::text || dollars_per_pound) || ' per pound is an inherited default that '::text) || 'nobody has set for '::text) || stream) || '. Every figure using it is an estimate. '::text) || 'Open Valuation Rates to set the real number.'::text
        END AS provenance
   FROM valuation_rates r
  WHERE effective_from = (( SELECT max(x.effective_from) AS max
           FROM valuation_rates x
          WHERE x.stream = r.stream AND x.effective_from <= CURRENT_DATE));
create or replace view public.v_watchdog_log as
 SELECT f.observed_at,
    f.observed_at::date AS observed_on,
    f.severity,
    f.what,
    f.where_it_is,
    f.who_is_accountable,
    f.when_it_started,
    f.why_it_matters,
    f.how_it_was_detected,
    f.what_to_do,
    f.the_arithmetic,
    f.record_count,
    f.pounds,
    f.dollars,
    f.drill,
    f.fingerprint,
    f.evidence,
    f.search_text,
    r.ran_at AS sweep_ran_at,
    r.ran_by AS sweep_ran_by,
    r.duration_ms AS sweep_ms,
    f.id AS finding_id,
    r.id AS run_id
   FROM watchdog_findings f
     LEFT JOIN watchdog_runs r ON r.id = f.run_id
  ORDER BY f.observed_at DESC, f.severity;
create or replace view public.v_watchdog_runs as
 SELECT ran_at,
    ran_at::date AS ran_on,
    ran_by,
    duration_ms,
    findings_raised,
    round(total_pounds_flagged, 1) AS pounds_flagged,
    round(total_dollars_flagged) AS dollars_flagged,
    id AS run_id
   FROM watchdog_runs
  ORDER BY ran_at DESC;
create or replace view public.v_watchdog_timeline as
 SELECT fingerprint,
    first_seen,
    last_seen,
    times_observed,
    days_persisting,
    severity,
    latest_state,
    accountable,
    peak_pounds,
    peak_dollars,
    drill,
    status,
    first_seen AS first_seen_date
   FROM ( SELECT watchdog_findings.fingerprint,
            min(watchdog_findings.observed_at)::date AS first_seen,
            max(watchdog_findings.observed_at)::date AS last_seen,
            count(*) AS times_observed,
            max(watchdog_findings.observed_at)::date - min(watchdog_findings.observed_at)::date AS days_persisting,
            max(watchdog_findings.severity) AS severity,
            (array_agg(watchdog_findings.what ORDER BY watchdog_findings.observed_at DESC))[1] AS latest_state,
            (array_agg(watchdog_findings.who_is_accountable ORDER BY watchdog_findings.observed_at DESC))[1] AS accountable,
            max(watchdog_findings.pounds) AS peak_pounds,
            max(watchdog_findings.dollars) AS peak_dollars,
            (array_agg(watchdog_findings.drill ORDER BY watchdog_findings.observed_at DESC))[1] AS drill,
                CASE
                    WHEN max(watchdog_findings.observed_at) < (now() - '2 days'::interval) THEN 'RESOLVED - last seen '::text || max(watchdog_findings.observed_at)::date
                    ELSE ('STILL OPEN after '::text || (CURRENT_DATE - min(watchdog_findings.observed_at)::date)) || ' days'::text
                END AS status
           FROM watchdog_findings
          GROUP BY watchdog_findings.fingerprint
          ORDER BY (max(watchdog_findings.observed_at)) DESC, (max(watchdog_findings.dollars)) DESC NULLS LAST) q;
create or replace view public.v_weight_audit as
 SELECT raw ->> 'UnitOfMeasureName'::text AS unit_of_measure,
    f_is_weight(raw ->> 'UnitOfMeasureName'::text) AS is_a_weight,
    count(*) AS packages,
    round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric), 1) AS total_quantity,
    round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)), 1) AS correct_pounds,
    round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1) AS pounds_if_all_treated_as_grams,
    round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)) - sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1) AS error_in_pounds,
        CASE
            WHEN NOT f_is_weight(raw ->> 'UnitOfMeasureName'::text) THEN ((((((('NOT A WEIGHT. '::text || count(*)) || ' packages counted in '::text) || (raw ->> 'UnitOfMeasureName'::text)) || '. These are units, not grams. Converting them to pounds produced a meaningless figure of '::text) || round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1)) || ' lb from '::text) || round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric))) || ' units.'::text
            WHEN lower(raw ->> 'UnitOfMeasureName'::text) = ANY (ARRAY['g'::text, 'grams'::text]) THEN 'Correct — grams converted properly.'::text
            ELSE ((((((('WRONG CONVERSION. '::text || count(*)) || ' packages are in '::text) || (raw ->> 'UnitOfMeasureName'::text)) || ' but were divided by 453.592 as if grams. True weight is '::text) || round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)), 1)) || ' lb, shown as '::text) || round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1)) || ' lb.'::text
        END AS verdict
   FROM metrc_packages p
  WHERE COALESCE((raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric
  GROUP BY (raw ->> 'UnitOfMeasureName'::text)
  ORDER BY (round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)), 1)) DESC NULLS LAST;
create or replace view public.v_weight_basis_gaps as
 SELECT c.relname AS relation,
        CASE c.relkind
            WHEN 'r'::"char" THEN 'table'::text
            WHEN 'v'::"char" THEN 'view'::text
            WHEN 'm'::"char" THEN 'matview'::text
            ELSE NULL::text
        END AS kind,
    a.attname AS column_name,
    w.basis,
    w.basis IS NULL AS undeclared,
    (EXISTS ( SELECT 1
           FROM pg_attribute m
          WHERE m.attrelid = c.oid AND m.attnum > 0 AND NOT m.attisdropped AND m.attname ~ '(dollar|revenue|price|cost|margin|amount|cash|value_at)'::text)) AS relation_also_carries_money
   FROM pg_class c
     JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'::name
     JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
     LEFT JOIN weight_basis_registry w ON w.relation = c.relname AND w.column_name = a.attname
  WHERE (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char"])) AND a.attname ~ '(pounds|_lb$|_lbs|lbs_|grams|weight)'::text AND a.attname !~ '(weighted|weight_in_parent)'::text;
create or replace view public.v_wholesale_reconciliation as
 WITH w AS (
         SELECT metrc_rpt_wholesale.manifest_number,
            max(metrc_rpt_wholesale.licence) AS licence,
            min(metrc_rpt_wholesale.created_on) AS created_on,
            sum(metrc_rpt_wholesale.amount) FILTER (WHERE NOT metrc_rpt_wholesale.voided) AS wholesale_value,
            max(metrc_rpt_wholesale.as_of_date) AS wholesale_as_of,
            count(*) AS wholesale_lines
           FROM metrc_rpt_wholesale
          GROUP BY metrc_rpt_wholesale.manifest_number
        ), p AS (
         SELECT metrc_rpt_package_transfers.manifest_number,
            max(metrc_rpt_package_transfers.licence) AS licence,
            sum(metrc_rpt_package_transfers.shipper_wholesale_price) AS package_value,
            max(metrc_rpt_package_transfers.as_of_date) AS package_as_of,
            count(*) AS package_lines
           FROM metrc_rpt_package_transfers
          GROUP BY metrc_rpt_package_transfers.manifest_number
        )
 SELECT COALESCE(w.manifest_number, p.manifest_number) AS manifest_number,
    COALESCE(w.licence, p.licence) AS licence,
    w.created_on,
    w.wholesale_value,
    p.package_value,
    round(COALESCE(w.wholesale_value, 0::numeric) - COALESCE(p.package_value, 0::numeric), 2) AS difference,
    w.wholesale_as_of,
    p.package_as_of,
    w.wholesale_lines,
    p.package_lines,
        CASE
            WHEN w.manifest_number IS NULL THEN 'In the package export only - no invoice line'::text
            WHEN p.manifest_number IS NULL AND w.created_on > p_max.as_of THEN ('Created after the package export was pulled on '::text || p_max.as_of) || '. Not a disagreement - a newer manifest.'::text
            WHEN p.manifest_number IS NULL THEN 'In the wholesale report only'::text
            WHEN abs(COALESCE(w.wholesale_value, 0::numeric) - COALESCE(p.package_value, 0::numeric)) < 0.01 THEN 'Agrees'::text
            ELSE 'DISAGREES - both report this manifest with a different value'::text
        END AS reading
   FROM w
     FULL JOIN p ON p.manifest_number = w.manifest_number
     CROSS JOIN ( SELECT max(metrc_rpt_package_transfers.as_of_date) AS as_of
           FROM metrc_rpt_package_transfers) p_max;
create or replace view public.v_widget_catalog_available as
 SELECT key,
    category,
    label,
    icon,
    table_ref AS source,
    drill,
    format,
    hot,
    widget_kind = 'metric'::text AND (drill IS NULL OR btrim(drill) = ''::text) AS has_no_drill,
    widget_kind,
    multi_instance,
    options_schema
   FROM widget_catalog
  WHERE enabled
  ORDER BY category, label;
create or replace view public.v_year_end_2025 as
 SELECT license,
    category,
    item,
    packages,
    quantity_estimate,
    uom,
    cost_per_unit,
    value_at_cost,
    basis,
    confidence
   FROM tg_inventory_as_of('2025-12-31'::date) tg_inventory_as_of(license, category, item, packages, quantity_estimate, uom, cost_per_unit, value_at_cost, basis, confidence);
create or replace view public.v_year_end_2025_coverage as
 WITH snapshot AS (
         SELECT tg_inventory_as_of.license,
            tg_inventory_as_of.category,
            tg_inventory_as_of.item,
            tg_inventory_as_of.packages,
            tg_inventory_as_of.quantity_estimate,
            tg_inventory_as_of.uom,
            tg_inventory_as_of.cost_per_unit,
            tg_inventory_as_of.value_at_cost,
            tg_inventory_as_of.basis,
            tg_inventory_as_of.confidence
           FROM tg_inventory_as_of('2025-12-31'::date) tg_inventory_as_of(license, category, item, packages, quantity_estimate, uom, cost_per_unit, value_at_cost, basis, confidence)
        )
 SELECT count(*) AS rows_total,
    count(*) FILTER (WHERE COALESCE(quantity_estimate, 0::numeric) > 0::numeric) AS rows_with_a_quantity,
    count(*) FILTER (WHERE COALESCE(quantity_estimate, 0::numeric) = 0::numeric) AS rows_with_no_quantity,
    count(*) FILTER (WHERE value_at_cost IS NULL) AS rows_with_no_value,
    count(*) FILTER (WHERE category = 'Uncategorised'::text) AS rows_with_no_category,
        CASE
            WHEN count(*) = 0 THEN NULL::numeric
            ELSE round(COALESCE(sum(value_at_cost), 0::numeric))
        END AS value_that_could_be_established,
        CASE
            WHEN count(*) = 0 THEN (((('NO ROWS ARE VISIBLE TO YOU, so there is no figure here to read. This is NOT a closing '::text || 'inventory of zero and it is NOT an all-clear. Either the point-in-time rebuild '::text) || 'returned nothing, or your account is not cleared to read the packages behind it. Do '::text) || 'not report $0 anywhere. For a filed return, export the Inventory Point-in-Time report '::text) || 'from the Metrc Reports Control Panel for 31 December 2025 and import it on the Report '::text) || 'Import page. That is the authoritative figure and nothing here replaces it.'::text
            ELSE (((((((((((('NOT FILEABLE AS IT STANDS. '::text || count(*) FILTER (WHERE COALESCE(quantity_estimate, 0::numeric) = 0::numeric)) || ' of '::text) || count(*)) || ' rows carry no quantity and '::text) || count(*) FILTER (WHERE category = 'Uncategorised'::text)) || ' carry no category, because Metrc''s interface exposes no historical snapshot — this '::text) || 'is rebuilt from the quantity each package was created with, which for most packages '::text) || 'as at 31 December 2025 is unknown. The $'::text) || round(COALESCE(sum(value_at_cost), 0::numeric))) || ' shown is only the fraction that could be established, not the closing inventory. '::text) || 'For a filed return, export the Inventory Point-in-Time report from the Metrc Reports '::text) || 'Control Panel for 31 December 2025 and import it on the Report Import page. That is '::text) || 'the authoritative figure and nothing here replaces it.'::text
        END AS what_this_means
   FROM snapshot;
create or replace view public.v_yield_by_harvest as
 WITH split AS (
         SELECT TRIM(BOTH FROM x.harvest_name) AS harvest_name,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom)) / NULLIF(array_length(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ','::text), 1), 0)::numeric AS made_lb,
            array_length(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ','::text), 1) AS harvests_named
           FROM metrc_packages p
             CROSS JOIN LATERAL unnest(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ','::text)) x(harvest_name)
          WHERE NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL
        )
 SELECT h.name AS harvest,
    h.raw ->> 'SourceStrainNames'::text AS strain,
    h.raw ->> 'DryingLocationName'::text AS room,
    h.harvest_start AS cut_on,
    (h.raw ->> 'FinishedDate'::text)::date AS finished_on,
    to_char(date_trunc('month'::text, COALESCE((h.raw ->> 'FinishedDate'::text)::date, h.harvest_start)::timestamp with time zone), 'YYYY-MM'::text) AS month,
    (h.raw ->> 'PlantCount'::text)::numeric AS plants,
    round(((h.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592, 1) AS wet_lb,
    round(((h.raw ->> 'TotalWasteWeight'::text)::numeric) / 453.592, 1) AS waste_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Buds'::text), 0::numeric), 1) AS dried_flower_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category ~~ 'Shake/Trim%'::text), 0::numeric), 1) AS trim_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Fresh Frozen Flower'::text), 0::numeric), 1) AS fresh_frozen_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE (s.category <> ALL (ARRAY['Buds'::text, 'Fresh Frozen Flower'::text])) AND s.category !~~ 'Shake/Trim%'::text), 0::numeric), 1) AS other_lb,
    round(COALESCE(sum(s.made_lb), 0::numeric), 1) AS total_made_lb,
        CASE
            WHEN ((h.raw ->> 'PlantCount'::text)::numeric) > 0::numeric THEN round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Buds'::text), 0::numeric) * 453.592 / ((h.raw ->> 'PlantCount'::text)::numeric), 1)
            ELSE NULL::numeric
        END AS grams_per_plant,
        CASE
            WHEN ((h.raw ->> 'TotalWetWeight'::text)::numeric) > 0::numeric THEN round(100.0 * COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Buds'::text), 0::numeric) / (((h.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592), 1)
            ELSE NULL::numeric
        END AS flower_yield_pct,
    bool_or(s.harvests_named > 1) AS weight_shared_with_other_harvests,
    h.license
   FROM metrc_harvests h
     LEFT JOIN split s ON s.harvest_name = h.name
  GROUP BY h.name, h.raw, h.harvest_start, h.license;
create or replace view public.v_zone_staffing as
 WITH req AS (
         SELECT z.id AS zone_id,
            z.name AS zone,
            z.department_id,
            r.headcount_required,
            r.hours_per_head,
            r.driver,
            r.weekday,
            r.shift,
            r.effective_from,
            r.effective_to
           FROM zones z
             LEFT JOIN zone_staffing_requirements r ON r.zone_id = z.id
          WHERE z.active
        ), sched AS (
         SELECT btrim(s.zone) AS zone,
            s.work_date,
            count(DISTINCT s.employee_id) AS scheduled_heads,
            sum(EXTRACT(epoch FROM s.planned_end - s.planned_start) / 3600.0) AS scheduled_hours
           FROM employee_schedules s
          WHERE s.zone IS NOT NULL
          GROUP BY (btrim(s.zone)), s.work_date
        ), act AS (
         SELECT btrim(s.zone) AS zone,
            t.work_date,
            count(DISTINCT t.employee_id) AS actual_heads,
            sum(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) AS actual_hours,
            sum((EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) * r.rate * (1::numeric + COALESCE(r.burden_pct, 0::numeric))) AS actual_cost_loaded
           FROM time_entries t
             JOIN employee_schedules s ON s.employee_id = t.employee_id AND s.work_date = t.work_date
             LEFT JOIN LATERAL ( SELECT r2.id,
                    r2.employee_id,
                    r2.basis,
                    r2.rate,
                    r2.ot_multiplier,
                    r2.burden_pct,
                    r2.effective_from,
                    r2.effective_to,
                    r2.approved_by,
                    r2.note,
                    r2.effective_from_date
                   FROM employee_rates r2
                  WHERE r2.employee_id = t.employee_id AND r2.effective_from <= t.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= t.work_date)
                  ORDER BY r2.effective_from DESC
                 LIMIT 1) r ON true
          WHERE t.clock_out IS NOT NULL
          GROUP BY (btrim(s.zone)), t.work_date
        )
 SELECT req.zone,
    req.zone_id,
    d.name AS department,
    COALESCE(sched.work_date, act.work_date) AS work_date,
    req.driver,
    req.headcount_required,
    COALESCE(sched.scheduled_heads, 0::bigint) AS scheduled_heads,
    COALESCE(act.actual_heads, 0::bigint) AS actual_heads,
    COALESCE(sched.scheduled_heads, 0::bigint) - COALESCE(req.headcount_required, 0) AS sched_vs_required,
    COALESCE(act.actual_heads, 0::bigint) - COALESCE(sched.scheduled_heads, 0::bigint) AS actual_vs_sched,
    round(COALESCE(sched.scheduled_hours, 0::numeric), 2) AS scheduled_hours,
    round(COALESCE(act.actual_hours, 0::numeric), 2) AS actual_hours,
    round(COALESCE(act.actual_cost_loaded, 0::numeric), 2) AS actual_cost_loaded,
        CASE
            WHEN req.headcount_required IS NULL THEN 'no requirement set'::text
            WHEN COALESCE(act.actual_heads, 0::bigint) < req.headcount_required THEN 'short'::text
            WHEN COALESCE(act.actual_heads, 0::bigint) > req.headcount_required THEN 'over'::text
            ELSE 'on plan'::text
        END AS staffing_flag
   FROM req
     LEFT JOIN sched ON sched.zone = req.zone
     LEFT JOIN act ON act.zone = req.zone AND act.work_date = sched.work_date
     LEFT JOIN departments d ON d.id = req.department_id;
create or replace view public.v_zone_vocabulary_drift as
 SELECT zone AS zone_named_on_a_schedule,
    count(*) AS schedule_rows,
    'This zone is named on a schedule but is not in the zone registry. Either add it with tg_add_zone or correct the schedule — free-text zones are how "F1" and "Flower Room #1" became two names for one room.'::text AS what_to_do
   FROM employee_schedules s
  WHERE NULLIF(btrim(COALESCE(zone, ''::text)), ''::text) IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM zone z
          WHERE z.zone_key = s.zone OR z.name = s.zone))
  GROUP BY zone;
