create materialized view if not exists public.mv_harvest_pkg_rollup as
 SELECT harvest_name,
    min(packaged_on) AS first_package_on,
    max(packaged_on) AS last_package_on,
    count(DISTINCT package_id) AS packages_made,
    count(DISTINCT package_id) FILTER (WHERE lab_state = 'TestFailed'::text) AS failed_packages,
    count(DISTINCT package_id) FILTER (WHERE lab_state = 'TestPassed'::text) AS passed_packages,
    count(DISTINCT package_id) FILTER (WHERE lab_state = 'NotSubmitted'::text) AS untested_packages,
    round(sum(quantity) FILTER (WHERE category ~~* '%bud%'::text) / 453.592, 2) AS bud_lb,
    round(sum(quantity) FILTER (WHERE category ~~* '%shake%'::text OR category ~~* '%trim%'::text) / 453.592, 2) AS shake_trim_lb,
    string_agg(DISTINCT category, ', '::text) AS categories_made
   FROM mv_package_harvest
  GROUP BY harvest_name;
