create or replace view public.v_actual_cost_per_pound as
 WITH pay AS (
         SELECT COALESCE(sum(v_payroll_forecast.loaded_weekly_cost), 0::numeric) AS weekly
           FROM v_payroll_forecast
        ), oh AS (
         SELECT COALESCE(sum(overhead_items.monthly_amount), 0::numeric) AS monthly,
            count(*) AS rows_recorded,
            bool_or(overhead_items.description ~~* '%wages included%'::text) AS includes_wages
           FROM overhead_items
        ), "out" AS (
         SELECT COALESCE(sum(v_true_cost_per_pound.saleable_lbs), 0::numeric) AS lbs,
            count(*) AS months
           FROM v_true_cost_per_pound
          WHERE v_true_cost_per_pound.month_date >= (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) - '6 mons'::interval)
        )
 SELECT ( SELECT "out".months
           FROM "out") AS months_counted,
    round(( SELECT "out".lbs
           FROM "out"), 1) AS saleable_pounds_in_period,
    round((( SELECT pay.weekly
           FROM pay)) * 52::numeric / 12::numeric, 0) AS payroll_per_month,
    round(( SELECT oh.monthly
           FROM oh), 0) AS overhead_per_month,
    round(
        CASE
            WHEN ( SELECT oh.includes_wages
               FROM oh) THEN ( SELECT oh.monthly
               FROM oh)
            ELSE (( SELECT oh.monthly
               FROM oh)) + (( SELECT pay.weekly
               FROM pay)) * 52::numeric / 12::numeric
        END, 0) AS total_cost_per_month,
    round((( SELECT oh.monthly
           FROM oh)) * (( SELECT "out".months
           FROM "out"))::numeric, 0) AS overhead_in_period,
    ( SELECT oh.rows_recorded
           FROM oh) AS overhead_lines_recorded,
        CASE
            WHEN (( SELECT "out".lbs
               FROM "out")) > 0::numeric THEN round(
            CASE
                WHEN ( SELECT oh.includes_wages
                   FROM oh) THEN ( SELECT oh.monthly
                   FROM oh)
                ELSE (( SELECT oh.monthly
                   FROM oh)) + (( SELECT pay.weekly
                   FROM pay)) * 52::numeric / 12::numeric
            END * (( SELECT "out".months
               FROM "out"))::numeric / (( SELECT "out".lbs
               FROM "out")), 2)
            ELSE NULL::numeric
        END AS actual_cost_per_pound,
    ( SELECT conversion_factors.value
           FROM conversion_factors
          WHERE conversion_factors.key = 'target_cost_per_lb'::text) AS assumed_cost_per_pound,
        CASE
            WHEN (( SELECT "out".lbs
               FROM "out")) > 0::numeric THEN round((( SELECT conversion_factors.value
               FROM conversion_factors
              WHERE conversion_factors.key = 'target_cost_per_lb'::text)) -
            CASE
                WHEN ( SELECT oh.includes_wages
                   FROM oh) THEN ( SELECT oh.monthly
                   FROM oh)
                ELSE (( SELECT oh.monthly
                   FROM oh)) + (( SELECT pay.weekly
                   FROM pay)) * 52::numeric / 12::numeric
            END * (( SELECT "out".months
               FROM "out"))::numeric / (( SELECT "out".lbs
               FROM "out")), 2)
            ELSE NULL::numeric
        END AS gap_per_pound,
        CASE
            WHEN ( SELECT oh.includes_wages
               FROM oh) THEN (((((('The $'::text || round(( SELECT oh.monthly
               FROM oh))) || ' a month is the WHOLE operating cost including '::text) || 'wages, confirmed by the owner. Payroll of $'::text) || round((( SELECT pay.weekly
               FROM pay)) * 52::numeric / 12::numeric)) || ' a month is inside that figure and is deliberately not added again. It is not itemised, so '::text) || 'the total is right but nothing can be attributed to a cause — connect QuickBooks or upload '::text) || 'a profit and loss statement to get the real lines.'::text
            ELSE 'Payroll plus recorded overhead.'::text
        END AS what_is_missing,
    ((((('Total operating cost of $'::text || round(( SELECT oh.monthly
           FROM oh))) || ' a month, wages included, over '::text) || (( SELECT "out".months
           FROM "out"))) || ' months, divided by the '::text) || round(( SELECT "out".lbs
           FROM "out"), 1)) || ' saleable pounds packaged in that period.'::text AS the_arithmetic;
create or replace view public.v_apex_metrc_coverage as
 SELECT link_status,
    count(*) AS orders,
    round(sum(COALESCE(total_dollars, 0::numeric)), 2) AS dollars,
    sum(COALESCE(metrc_manifests, 0::bigint)) AS manifests,
    sum(COALESCE(package_tags, 0::bigint)) AS package_tags,
    round(100.0 * count(*)::numeric / NULLIF(sum(count(*)) OVER (), 0::numeric), 1) AS pct_of_orders
   FROM v_apex_order_metrc_link
  GROUP BY link_status;
create or replace view public.v_auditor_verdict as
 WITH cov AS (
         SELECT count(*) FILTER (WHERE v_conformance_coverage.coverage = 'NEVER CHECKED'::text) AS never_checked,
            count(*) AS total
           FROM v_conformance_coverage
        ), reg AS (
         SELECT ( SELECT count(*) AS count
                   FROM policy_registry) AS policies_recorded,
            ( SELECT count(*) AS count
                   FROM finding_remediation) AS findings_recorded
        )
 SELECT cov.never_checked AS subjects_never_checked,
    cov.total AS subjects_total,
    round(100.0 * (cov.total - cov.never_checked)::numeric / NULLIF(cov.total, 0)::numeric, 1) AS coverage_pct,
    ( SELECT count(*) AS count
           FROM v_auditor_heartbeat
          WHERE v_auditor_heartbeat.heartbeat = ANY (ARRAY['NEVER REPORTED'::text, 'DARK'::text])) AS checkers_dark,
    ( SELECT count(*) AS count
           FROM v_auditor_heartbeat
          WHERE NOT v_auditor_heartbeat.fixture_proves_it_fails AND v_auditor_heartbeat.enabled) AS checkers_unproven,
        CASE
            WHEN reg.policies_recorded = 0 THEN NULL::bigint
            ELSE ( SELECT count(*) AS count
               FROM policy_registry
              WHERE policy_registry.active AND NOT policy_registry.enforced)
        END AS policies_on_memory_only,
        CASE
            WHEN reg.findings_recorded = 0 THEN NULL::bigint
            ELSE ( SELECT count(*) AS count
               FROM finding_remediation
              WHERE finding_remediation.state <> ALL (ARRAY['closed'::text, 'accepted_risk'::text]))
        END AS findings_open,
        CASE
            WHEN reg.findings_recorded = 0 THEN NULL::bigint
            ELSE ( SELECT count(*) AS count
               FROM finding_remediation
              WHERE (finding_remediation.state <> ALL (ARRAY['closed'::text, 'accepted_risk'::text])) AND finding_remediation.due_by < now())
        END AS findings_overdue,
        CASE
            WHEN reg.findings_recorded = 0 THEN NULL::bigint
            ELSE ( SELECT count(*) AS count
               FROM finding_remediation
              WHERE (finding_remediation.state <> ALL (ARRAY['closed'::text, 'accepted_risk'::text])) AND finding_remediation.severity = 'critical'::text)
        END AS findings_critical,
    ( SELECT round(sum(conformance_ledger.pounds), 1) AS round
           FROM conformance_ledger
          WHERE (conformance_ledger.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AND conformance_ledger.ran_at > (now() - '24:00:00'::interval)) AS pounds_in_question_24h,
    ( SELECT round(sum(conformance_ledger.dollars), 2) AS round
           FROM conformance_ledger
          WHERE (conformance_ledger.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AND conformance_ledger.ran_at > (now() - '24:00:00'::interval)) AS dollars_in_question_24h,
    concat_ws(' · '::text,
        CASE
            WHEN reg.policies_recorded = 0 THEN 'POLICY REGISTER EMPTY — rule enforcement is UNMEASURED, not clean'::text
            ELSE reg.policies_recorded || ' rules recorded'::text
        END,
        CASE
            WHEN reg.findings_recorded = 0 THEN 'REMEDIATION REGISTER EMPTY — open findings are UNCOUNTED, not zero'::text
            ELSE reg.findings_recorded || ' findings tracked'::text
        END, ((round(100.0 * (cov.total - cov.never_checked)::numeric / NULLIF(cov.total, 0)::numeric, 1) || '% of '::text) || cov.total) || ' subjects ever checked'::text) AS read_this_first
   FROM cov,
    reg;
create or replace view public.v_challenge_overdue as
 WITH sla AS (
         SELECT COALESCE(f_rule('challenge_sla_critical_hours'::text), 24::numeric) AS crit,
            COALESCE(f_rule('challenge_sla_elevated_hours'::text), 72::numeric) AS elev,
            COALESCE(f_rule('challenge_sla_default_hours'::text), 168::numeric) AS other
        )
 SELECT u.id,
    u.severity,
    "left"(u.what, 90) AS what,
    w.observed_at,
    round(EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric)::integer AS hours_old,
        CASE u.severity
            WHEN 'critical'::text THEN s.crit
            WHEN 'elevated'::text THEN s.elev
            ELSE s.other
        END::integer AS owed_within_hours,
    (round(EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric) -
        CASE u.severity
            WHEN 'critical'::text THEN s.crit
            WHEN 'elevated'::text THEN s.elev
            ELSE s.other
        END)::integer AS hours_overdue,
    u.the_arithmetic IS NULL AS has_no_arithmetic,
        CASE
            WHEN (EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric) <=
            CASE u.severity
                WHEN 'critical'::text THEN s.crit
                WHEN 'elevated'::text THEN s.elev
                ELSE s.other
            END THEN 'within the window'::text
            WHEN u.severity = 'critical'::text THEN 'OVERDUE - a critical claim nobody has tested'::text
            ELSE 'overdue'::text
        END AS standing
   FROM v_unchallenged_findings u
     JOIN watchdog_findings w ON w.id = u.id
     CROSS JOIN sla s
  ORDER BY ((EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric) >
        CASE u.severity
            WHEN 'critical'::text THEN s.crit
            WHEN 'elevated'::text THEN s.elev
            ELSE s.other
        END) DESC, (
        CASE u.severity
            WHEN 'critical'::text THEN 0
            WHEN 'elevated'::text THEN 1
            ELSE 2
        END), w.observed_at;
create or replace view public.v_cost_of_loss as
 SELECT scope_type,
    scope,
    harvests,
    wet_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    verdict,
    ( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1) AS cost_per_pound,
    round(waste_lbs * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS cost_of_waste,
    round((waste_pct - (( SELECT round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / NULLIF(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 0::numeric), 1) AS round
           FROM metrc_harvests))) / 100.0 * wet_lbs * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS excess_cost_vs_company_average
   FROM v_loss_ranking l
  WHERE wet_lbs > 0::numeric
  ORDER BY (round(waste_lbs * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_cost_per_pound as
 WITH months AS (
         SELECT date_trunc('month'::text, h.finished_on::timestamp with time zone)::date AS month,
            sum(h.dry_yield_lb) FILTER (WHERE h.drying_kind = 'dried'::text) AS dried_lb,
            sum(h.dry_yield_lb) FILTER (WHERE h.drying_kind ~~ 'fresh frozen%'::text) AS ff_wet_lb,
            count(*) AS harvests
           FROM v_harvest_water_and_yield h
          WHERE h.harvest_state = 'CLOSED'::text AND h.finished_on IS NOT NULL
          GROUP BY (date_trunc('month'::text, h.finished_on::timestamp with time zone)::date)
        ), rate AS (
         SELECT COALESCE(f_rule('fresh_frozen_wet_to_dry'::text), 4.5) AS ff_ratio
        ), overhead AS (
         SELECT sum(overhead_items.monthly_amount) AS monthly_overhead,
            max(overhead_items.source) AS overhead_source
           FROM overhead_items
          WHERE overhead_items.effective_to IS NULL
        )
 SELECT m.month,
    m.harvests,
    round(COALESCE(m.dried_lb, 0::numeric), 1) AS dried_lb,
    round(COALESCE(m.ff_wet_lb, 0::numeric), 1) AS fresh_frozen_wet_lb,
    round(COALESCE(m.ff_wet_lb, 0::numeric) / r.ff_ratio, 1) AS fresh_frozen_dry_equiv_lb,
    round(COALESCE(m.dried_lb, 0::numeric) + COALESCE(m.ff_wet_lb, 0::numeric) / r.ff_ratio, 1) AS saleable_dry_equiv_lb,
    o.monthly_overhead,
        CASE
            WHEN (COALESCE(m.dried_lb, 0::numeric) + COALESCE(m.ff_wet_lb, 0::numeric) / r.ff_ratio) > 0::numeric THEN round(o.monthly_overhead / (COALESCE(m.dried_lb, 0::numeric) + COALESCE(m.ff_wet_lb, 0::numeric) / r.ff_ratio), 2)
            ELSE NULL::numeric
        END AS cost_per_lb_this_month,
    round(sum(o.monthly_overhead) OVER w / NULLIF(sum(COALESCE(m.dried_lb, 0::numeric) + COALESCE(m.ff_wet_lb, 0::numeric) / r.ff_ratio) OVER w, 0::numeric), 2) AS cost_per_lb_trailing_12m,
    'PROVISIONAL — owner-stated overhead, not accounts. '::text || "left"(o.overhead_source, 160) AS numerator_provenance,
    (('Fresh frozen converted to dry-equivalent at '::text || r.ff_ratio) || ':1 before adding to dried flower '::text) || '(rule B3). Adding it wet would understate cost per pound by roughly 40%.'::text AS denominator_method,
    'A single month is not a cost per pound — harvests are lumpy on a 14-day pull cadence and '::text || 'overhead is constant. Read the trailing 12-month column.'::text AS how_to_read_it
   FROM months m
     CROSS JOIN rate r
     CROSS JOIN overhead o
  WINDOW w AS (ORDER BY m.month ROWS BETWEEN 11 PRECEDING AND CURRENT ROW);
create or replace view public.v_customers as
 SELECT c.id,
    c.name,
    c.state_license,
    c.terms_days,
    c.credit_limit,
    c.active,
    c.contact_name,
    c.email,
    c.cc_emails,
    c.phone,
        CASE
            WHEN c.email IS NULL THEN 'No email on file. Metrc carries no customer email addresses - this must be entered by a person.'::text
            ELSE 'Ready to send'::text
        END AS contact_status,
    h.shipments,
    h.first_shipment,
    h.last_shipment,
    h.packages_shipped,
    h.last_invoice,
    h.last_manifest,
    h.gross_weight_last,
    h.weight_unit_last,
    d.manifests_held,
        CASE
            WHEN h.shipments IS NULL THEN 'Never shipped to'::text
            WHEN h.last_shipment > (now() - '60 days'::interval) THEN 'Active'::text
            WHEN h.last_shipment > (now() - '180 days'::interval) THEN 'Quiet - no shipment in 60 days'::text
            ELSE 'Dormant - no shipment in 6 months'::text
        END AS trading_status,
    h.lab_samples,
    h.cultivation_shipments,
    h.manufacturing_shipments,
    h.bought_from_them
   FROM customers c
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE m.is_customer_sale) AS shipments,
            min(m.created_on) FILTER (WHERE m.is_customer_sale) AS first_shipment,
            max(m.created_on) FILTER (WHERE m.is_customer_sale) AS last_shipment,
            sum(((m.raw -> '_delivery'::text) ->> 'DeliveryPackageCount'::text)::integer) FILTER (WHERE m.is_customer_sale) AS packages_shipped,
            max((m.raw -> '_delivery'::text) ->> 'InvoiceNumber'::text) FILTER (WHERE m.is_customer_sale) AS last_invoice,
            max(m.manifest_number) FILTER (WHERE m.is_customer_sale) AS last_manifest,
            max(((m.raw -> '_delivery'::text) ->> 'GrossWeight'::text)::numeric) FILTER (WHERE m.is_customer_sale) AS gross_weight_last,
            max((m.raw -> '_delivery'::text) ->> 'GrossUnitOfWeightName'::text) FILTER (WHERE m.is_customer_sale) AS weight_unit_last,
            count(*) FILTER (WHERE m.movement = 'Laboratory sample'::text) AS lab_samples,
            count(*) FILTER (WHERE m.is_customer_sale AND m.operation = 'Cultivation'::text) AS cultivation_shipments,
            count(*) FILTER (WHERE m.is_customer_sale AND m.operation = 'Manufacturing'::text) AS manufacturing_shipments,
            count(*) FILTER (WHERE m.is_inbound_purchase) AS bought_from_them
           FROM v_manifest_ledger m
          WHERE m.recipient = c.metrc_facility_name OR m.shipper = c.metrc_facility_name) h ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS manifests_held
           FROM metrc_documents md
          WHERE md.doc_type = 'manifest'::text AND md.storage_path IS NOT NULL AND (md.manifest_number IN ( SELECT m2.manifest_number
                   FROM v_manifest_ledger m2
                  WHERE m2.recipient = c.metrc_facility_name))) d ON true
  WHERE (COALESCE(c.state_license, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text])) AND c.name !~~* '%twisted growers%'::text;
create or replace view public.v_department_staffing_average as
 WITH daily AS (
         SELECT v_department_labour.department_id,
            v_department_labour.department,
            v_department_labour.shift,
            v_department_labour.work_date,
            v_department_labour.week_start,
            v_department_labour.month_start,
            v_department_labour.heads,
            v_department_labour.hours,
            v_department_labour.total_cost_loaded
           FROM v_department_labour
        )
 SELECT d.department_id,
    d.department,
    d.shift,
    min(d.work_date) AS from_date,
    max(d.work_date) AS to_date,
    count(DISTINCT d.work_date) AS days_run,
    round(avg(d.heads), 2) AS avg_heads,
    min(d.heads) AS min_heads,
    max(d.heads) AS max_heads,
    round(avg(d.hours), 2) AS avg_hours_per_day,
    round(sum(d.total_cost_loaded), 2) AS total_cost_loaded,
    round(avg(d.total_cost_loaded), 2) AS avg_cost_per_day,
    req.headcount_required AS minimum_required,
        CASE
            WHEN req.headcount_required IS NULL THEN 'no minimum set'::text
            WHEN avg(d.heads) < req.headcount_required::numeric THEN 'below minimum'::text
            WHEN avg(d.heads) > req.headcount_required::numeric THEN 'above minimum'::text
            ELSE 'on minimum'::text
        END AS against_minimum
   FROM daily d
     LEFT JOIN LATERAL ( SELECT r.headcount_required
           FROM zone_staffing_requirements r
          WHERE r.department_id = d.department_id AND r.effective_from <= d.work_date AND (r.effective_to IS NULL OR r.effective_to >= d.work_date)
          ORDER BY r.effective_from DESC
         LIMIT 1) req ON true
  GROUP BY d.department_id, d.department, d.shift, req.headcount_required;
create or replace view public.v_document_links as
 SELECT p.tag AS key,
    'package'::text AS key_kind,
    p.item_name AS label,
    NULL::text AS coa_url,
        CASE
            WHEN (p.raw ->> 'LabTestingState'::text) = 'TestPassed'::text THEN (('Passed'::text || COALESCE(' on '::text || (((p.raw ->> 'LabTestingRecordedDate'::text)::date)::text), ''::text)) || COALESCE(', certificate valid to '::text || (((p.raw ->> 'LabTestResultExpirationDateTime'::text)::date)::text), ''::text)) || ' — the certificate document itself is not in the Metrc API. Import it, or fetch it from the laboratory.'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'TestFailed'::text THEN ('FAILED'::text || COALESCE(' on '::text || (((p.raw ->> 'LabTestingRecordedDate'::text)::date)::text), ''::text)) || ' — obtain the certificate from the laboratory for the failing analyte.'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN 'Never submitted for testing — no certificate exists.'::text
            ELSE 'Awaiting result'::text || COALESCE(', submitted '::text || (((p.raw ->> 'LabTestingStateDate'::text)::date)::text), ''::text)
        END AS coa_label,
    t.manifest_link AS manifest_url,
        CASE
            WHEN t.manifest_number IS NOT NULL THEN ((((('Manifest '::text || t.manifest_number) || ' — '::text) || COALESCE(t.shipper, '?'::text)) || ' to '::text) || COALESCE(t.recipient, '?'::text)) || COALESCE(' on '::text || t.created_on::text, ''::text)
            ELSE NULL::text
        END AS manifest_label,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS manifest_number
   FROM metrc_packages p
     LEFT JOIN v_metrc_transfer_ledger t ON t.manifest_number = NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text)
UNION ALL
 SELECT t.manifest_number AS key,
    'manifest'::text AS key_kind,
    (COALESCE(t.shipper, ''::text) || ' to '::text) || COALESCE(t.recipient, ''::text) AS label,
    NULL::text AS coa_url,
    NULL::text AS coa_label,
    t.manifest_link AS manifest_url,
    (((('Manifest '::text || t.manifest_number) || ' — '::text) || COALESCE(t.packages::text, '?'::text)) || ' packages'::text) || COALESCE(' on '::text || t.created_on::text, ''::text) AS manifest_label,
    t.manifest_number
   FROM v_metrc_transfer_ledger t
UNION ALL
 SELECT h.name AS key,
    'harvest'::text AS key_kind,
    h.name AS label,
    NULL::text AS coa_url,
    NULL::text AS coa_label,
    t.manifest_link AS manifest_url,
    ('Manifest '::text || t.manifest_number) || ' carried packages from this harvest'::text AS manifest_label,
    t.manifest_number
   FROM metrc_harvests h
     JOIN mv_package_harvest mph ON mph.harvest_name = h.name
     JOIN metrc_packages p2 ON p2.id = mph.package_id
     JOIN v_metrc_transfer_ledger t ON t.manifest_number = NULLIF(p2.raw ->> 'ReceivedFromManifestNumber'::text, ''::text);
create or replace view public.v_exposure as
 WITH tagged AS (
         SELECT f.finding_key,
            f.department,
            f.severity,
            f.severity_rank,
            f.pounds,
            f.dollars,
            f.what,
            "substring"(COALESCE(f.what, ''::text), '(M[0-9]{8,})'::text) AS package_tag
           FROM v_findings f
          WHERE f.state = 'open'::text AND NOT f.is_duplicate AND (f.pounds IS NOT NULL OR f.dollars IS NOT NULL)
        ), once_per_package AS (
         SELECT DISTINCT ON (tagged.package_tag) tagged.package_tag,
            tagged.department,
            tagged.severity,
            tagged.pounds,
            tagged.dollars,
            tagged.what
           FROM tagged
          WHERE tagged.package_tag IS NOT NULL
          ORDER BY tagged.package_tag, tagged.severity_rank, tagged.dollars DESC NULLS LAST
        )
 SELECT 'Physical stock flagged'::text AS measure,
    count(*)::numeric AS items,
    round(sum(once_per_package.pounds), 1) AS pounds,
    round(sum(once_per_package.dollars), 0) AS dollars,
    'Each package counted ONCE, at its most serious finding. This is real material we are holding.'::text AS means
   FROM once_per_package
UNION ALL
 SELECT 'Historical / aggregate findings'::text AS measure,
    count(*) AS items,
    round(sum(tagged.pounds), 1) AS pounds,
    round(sum(tagged.dollars), 0) AS dollars,
    'Waste and loss aggregates covering many harvests. NOT stock on hand - never add these to the line above.'::text AS means
   FROM tagged
  WHERE tagged.package_tag IS NULL
UNION ALL
 SELECT 'Naive sum of every finding (WRONG)'::text AS measure,
    count(*) AS items,
    round(sum(tagged.pounds), 1) AS pounds,
    round(sum(tagged.dollars), 0) AS dollars,
    'What you get by summing the column. Double counts packages and mixes history with stock. Shown so the error is visible, never to be quoted.'::text AS means
   FROM tagged;
create or replace view public.v_facility_live_map as
 SELECT 'Drying / Curing'::text AS area,
    m.room AS location,
    m.license,
    count(*)::numeric AS records,
    'harvests'::text AS record_type,
    round(sum(COALESCE(m.current_weight, m.wet_weight, 0::numeric)), 1) AS weight_on_hand,
    min(m.harvest_start) AS oldest_date,
    max(m.days_since_takedown)::numeric AS oldest_days,
    string_agg(DISTINCT m.stage, ' · '::text) AS stages,
    string_agg(DISTINCT m.strains, ', '::text) AS contents
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND COALESCE(m.room, ''::text) <> ''::text
  GROUP BY 'Drying / Curing'::text, m.room, m.license
UNION ALL
 SELECT 'Packaged inventory'::text AS area,
    COALESCE(p.location, '(no location)'::text) AS location,
    p.license,
    count(*)::numeric AS records,
    'packages'::text AS record_type,
    round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS weight_on_hand,
    min(p.packaged_on) AS oldest_date,
    max(CURRENT_DATE - p.packaged_on)::numeric AS oldest_days,
    string_agg(DISTINCT COALESCE(p.lab_testing_state, '—'::text), ' · '::text) AS stages,
    string_agg(DISTINCT p.item_name, ', '::text) AS contents
   FROM metrc_packages p
  WHERE p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])
  GROUP BY 'Packaged inventory'::text, (COALESCE(p.location, '(no location)'::text)), p.license
UNION ALL
 SELECT 'In transit'::text AS area,
    COALESCE(p.location, '(manifested)'::text) AS location,
    p.license,
    count(*)::numeric AS records,
    'packages'::text AS record_type,
    round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS weight_on_hand,
    min(p.packaged_on) AS oldest_date,
    max(CURRENT_DATE - p.packaged_on)::numeric AS oldest_days,
    'Leaving the facility'::text AS stages,
    string_agg(DISTINCT p.item_name, ', '::text) AS contents
   FROM metrc_packages p
  WHERE p.source_state = 'intransit'::text
  GROUP BY 'In transit'::text, (COALESCE(p.location, '(manifested)'::text)), p.license;
create or replace view public.v_facility_registry as
 WITH ranked AS (
         SELECT v_metrc_facility_names.facility_licence,
            v_metrc_facility_names.name_seen,
            v_metrc_facility_names.created_on,
            row_number() OVER (PARTITION BY v_metrc_facility_names.facility_licence ORDER BY v_metrc_facility_names.created_on DESC NULLS LAST) AS recency
           FROM v_metrc_facility_names
          WHERE v_metrc_facility_names.name_seen IS NOT NULL
        ), canon AS (
         SELECT ranked.facility_licence,
            max(ranked.name_seen) FILTER (WHERE ranked.recency = 1) AS facility_name,
            array_agg(DISTINCT ranked.name_seen ORDER BY ranked.name_seen) AS names_seen,
            count(DISTINCT ranked.name_seen) AS name_variants
           FROM ranked
          GROUP BY ranked.facility_licence
        )
 SELECT facility_licence,
    facility_name,
    f_facility_type(facility_licence) AS facility_type,
    f_company_key(facility_name) AS company_key,
    names_seen,
    name_variants,
    (((((facility_name || ' '::text) || array_to_string(names_seen, ' '::text)) || ' '::text) || facility_licence) || ' '::text) || f_facility_type(facility_licence) AS search_text
   FROM canon c;
create or replace view public.v_failed_by_strain as
 SELECT COALESCE(source_strain, '(unknown)'::text) AS strain,
    count(*) AS failed_source_tags,
    round(sum(source_created_lb), 2) AS failed_lb_in,
    count(DISTINCT failed_tag) AS consolidated_into,
    count(DISTINCT source_harvest) AS harvests_affected,
    count(*) FILTER (WHERE source_ownership ~~ 'THIRD PARTY%'::text) AS third_party_tags,
    count(*) FILTER (WHERE source_ownership ~~ 'OURS%'::text) AS our_tags,
    round(sum(source_created_lb) FILTER (WHERE source_ownership ~~ 'THIRD PARTY%'::text), 2) AS third_party_lb,
    round(sum(source_created_lb) FILTER (WHERE source_ownership ~~ 'OURS%'::text), 2) AS our_lb,
    string_agg(DISTINCT source_supplier, ', '::text) AS suppliers,
    min(source_packaged_on) AS first_failed,
    max(source_packaged_on) AS last_failed
   FROM v_failed_product_lineage
  WHERE source_tag IS NOT NULL
  GROUP BY (COALESCE(source_strain, '(unknown)'::text));
create or replace view public.v_failed_testing_by_origin as
 SELECT s.origin,
    s.supplier,
    s.origin_license,
    s.stream,
    s.license AS held_under,
    s.location,
    s.packages,
    s.pounds,
    s.oldest_days,
    s.strains,
    COALESCE(i.bought_as, 'unknown'::text) AS bought_as,
    round(s.pounds * (( SELECT conversion_factors.value
           FROM conversion_factors
          WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS value_at_our_cost,
        CASE
            WHEN s.origin = 'Grown by us'::text THEN 'OUR FAILURE - a genuine loss. We grew it, packaged it and it failed. Root cause is ours to find.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'failed for remediation'::text THEN 'BOUGHT FAILED ON PURPOSE - this is raw material, not a loss. It was purchased to remediate and process. Track the remediation yield, not the failure.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'biomass for extraction'::text THEN 'BIOMASS FOR EXTRACTION - bought to be processed, so a fail on flower testing may be irrelevant. Confirm the intended route.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'sound material'::text THEN ('SUPPLIER PROBLEM - we bought this as sound material and it failed. Raise it with '::text || s.supplier) || '.'::text
            ELSE 'INTENT NOT RECORDED - we cannot tell whether this was bought sound and failed, or bought failed on purpose to remediate. Set it on the Purchase Intent page before treating it as a loss.'::text
        END AS whose_problem,
        CASE
            WHEN s.origin = 'Grown by us'::text THEN 'Find the root cause, then decide remediate or destroy and record it in Metrc.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'failed for remediation'::text THEN 'Move it into remediation and record what comes out the other side.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'sound material'::text THEN 'Raise it with the supplier with the package tags and the certificate.'::text
            ELSE ('Set the purchase intent for '::text || COALESCE(s.supplier, 'this supplier'::text)) || ' so this stops being ambiguous.'::text
        END AS what_to_do
   FROM v_stock_on_hand s
     LEFT JOIN purchase_intent i ON i.origin_license = s.origin_license
  WHERE s.lab_state = 'TestFailed'::text
  ORDER BY s.pounds DESC;
create or replace view public.v_finding_causes as
 SELECT pattern_key,
    source,
    count(*) AS findings_that_clear_if_fixed,
    count(*) FILTER (WHERE severity = 'critical'::text) AS critical_instances,
    max(severity_rank) AS worst_severity_rank,
    (array_agg(severity ORDER BY severity_rank DESC))[1] AS worst_severity,
    min(first_raised) AS oldest_instance,
    max(last_seen) AS newest_instance,
    CURRENT_DATE - min(first_raised)::date AS days_open,
    count(*) FILTER (WHERE first_raised < (now() - '7 days'::interval)) AS instances_over_a_week,
    round(sum(pounds) FILTER (WHERE pounds > 0::numeric), 1) AS pounds_untrusted,
    round(sum(dollars) FILTER (WHERE dollars > 0::numeric)) AS dollars_untrusted,
    (array_agg(who_is_accountable ORDER BY first_raised) FILTER (WHERE who_is_accountable IS NOT NULL))[1] AS accountable,
    (array_agg(department ORDER BY first_raised) FILTER (WHERE department IS NOT NULL))[1] AS department,
    (array_agg(what ORDER BY first_raised))[1] AS example_finding,
    (array_agg(what_to_do ORDER BY first_raised) FILTER (WHERE what_to_do IS NOT NULL))[1] AS what_to_do
   FROM v_findings f
  WHERE resolved_at IS NULL AND NOT COALESCE(is_duplicate, false)
  GROUP BY pattern_key, source
  ORDER BY (max(severity_rank)) DESC, (count(*)) DESC;
create or replace view public.v_findings_live as
 SELECT f.finding_key,
    f.source,
    f.department,
    f.severity,
    f.what,
    f.where_it_is,
    f.who_is_accountable,
    f.why_it_matters,
    f.what_to_do,
    f.the_arithmetic,
    f.how_it_was_detected,
    f.when_it_started,
    f.evidence,
    f.record_count,
    f.pounds,
    f.dollars,
    f.first_raised,
    f.last_seen,
    f.times_seen,
    f.resolved_at,
    f.resolution_note,
    f.fingerprint,
    f.pattern_key,
    f.drill,
    f.state,
    f.severity_rank,
    f.occurrences_6mo,
    f.priority_band,
    f.canonical_key,
    f.is_duplicate,
    f.duplicate_of,
    COALESCE(fs.state, 'open'::text) AS work_state,
    COALESCE(o.owner_name, fs.owner_name, 'UNOWNED'::text) AS owner_name,
    o.escalates_to,
    fs.note AS work_note,
    fs.suppress_until,
    COALESCE(fs.state, 'open'::text) = 'suppressed'::text AND COALESCE(fs.suppress_until, CURRENT_DATE) >= CURRENT_DATE AS currently_suppressed,
    (f.department || ' · '::text) ||
        CASE
            WHEN POSITION((':'::text) IN (COALESCE(f.what, ''::text))) > 0 THEN btrim(split_part(f.what, ':'::text, 1))
            ELSE "left"(COALESCE(f.what, '(no description)'::text), 40)
        END AS group_key
   FROM v_findings f
     LEFT JOIN finding_state fs ON fs.finding_key = f.finding_key
     LEFT JOIN finding_owners o ON o.department = f.department;
create or replace view public.v_findings_priced as
 SELECT finding_key,
    source,
    department,
    severity,
    what,
    where_it_is,
    who_is_accountable,
    why_it_matters,
    what_to_do,
    the_arithmetic,
    how_it_was_detected,
    when_it_started,
    evidence,
    record_count,
    pounds,
    dollars,
    first_raised,
    last_seen,
    times_seen,
    resolved_at,
    resolution_note,
    fingerprint,
    pattern_key,
    drill,
    state,
    severity_rank,
    occurrences_6mo,
    priority_band,
    canonical_key,
    is_duplicate,
    duplicate_of,
    COALESCE(dollars, (( SELECT f_price_per_lb.rate
           FROM f_price_per_lb(f.department) f_price_per_lb(rate, basis)
         LIMIT 1)) * pounds) AS value_dollars,
        CASE
            WHEN dollars IS NOT NULL THEN 'valued by the agent that raised it'::text
            WHEN pounds IS NOT NULL THEN ( SELECT f_price_per_lb.basis
               FROM f_price_per_lb(f.department) f_price_per_lb(rate, basis)
             LIMIT 1)
            ELSE 'CANNOT BE PRICED — no dollars and no pounds recorded'::text
        END AS value_basis,
    dollars IS NULL AND pounds IS NULL AS unpriceable
   FROM v_findings f;
create or replace view public.v_finished_goods_onhand as
 SELECT p.category,
    p.source_sheet AS product_line,
    p.current_status,
    p.strain_flavor,
    p.product_description,
    p.infusion_type,
    p.size_g AS size_as_written,
    p.size_value,
    p.size_unit,
    p.production_batch,
    p.bulk_metrc_tag,
    p.prefill_metrc_tag,
    p.final_metrc_tag,
    p.final_tag_note,
    p.business_key,
    p.business_key_basis,
    p.cases_available,
    p.case_size,
    COALESCE(p.total_packaged, p.total_units_packaged) AS units_packaged,
    p.total_filled,
    p.total_units_filled,
    p.total_units,
    p.total_bulk,
    p.total_gram_equivalent,
    p.tac_pct,
    p.thc_pct,
    p.thca_pct,
    p.cannabinoid_reported,
    p.terpene_pct,
    p.terpene_status,
    p.creation_date,
    p.expiration_date,
    p.days_to_expiration AS days_to_expiry_per_sheet,
    p.expiration_date - CURRENT_DATE AS days_to_expiry_recomputed,
        CASE
            WHEN p.expiration_date IS NULL THEN 'no expiry date in the sheet'::text
            WHEN p.expiration_date < CURRENT_DATE THEN 'EXPIRED'::text
            WHEN p.expiration_date <= (CURRENT_DATE + 30) THEN 'expires within 30 days'::text
            WHEN p.expiration_date <= (CURRENT_DATE + 90) THEN 'expires within 90 days'::text
            ELSE 'in date'::text
        END AS expiry_bucket,
    p.expiry_flag AS expiry_flag_per_sheet,
    p.threshold_units,
    p.low_stock_flag AS low_stock_flag_per_sheet,
        CASE
            WHEN p.threshold_units IS NULL THEN NULL::boolean
            WHEN COALESCE(p.total_packaged, p.total_units_packaged, 0::numeric) < p.threshold_units THEN true
            ELSE false
        END AS low_stock_recomputed,
    p.coa_link,
    p.coa_link IS NOT NULL AS has_coa_link,
    p.inventory_check,
    p.location,
    p.notes,
    r.existence AS metrc_existence,
    r.quantity AS metrc_quantity_check,
    r.identity_check AS metrc_identity_check,
    r.metrc_qty,
    r.metrc_uom,
    r.comparison_basis,
    r.sheet_comparable,
        CASE
            WHEN p.final_metrc_tag IS NULL THEN 'no final tag to check'::text
            WHEN r.identity_check = 'STRAIN DOES NOT MATCH THE TAG'::text THEN 'DO NOT SELL WITHOUT CHECKING - the tag on this row belongs to a different product in Metrc'::text
            WHEN r.existence = 'not_in_mirror_and_no_manifest'::text THEN 'tag not yet in our Metrc mirror'::text
            WHEN r.quantity = 'differs'::text THEN 'quantity disagrees with Metrc'::text
            WHEN r.quantity = 'agree'::text THEN 'agrees with Metrc'::text
            ELSE 'not checked'::text
        END AS sales_confidence,
    p.source_sheet,
    p.source_row,
    p.sheet_key,
    p.source_file_id,
    p.as_of AS sheet_as_of,
    p.sheet_modified_at,
    p.synced_at,
    p.import_run_id
   FROM product_inventory p
     LEFT JOIN v_finished_goods_metrc_reconciliation r ON r.tag = p.final_metrc_tag
  WHERE p.still_in_sheet;
create or replace view public.v_flow_failed_split as
 SELECT round(sum(pounds) FILTER (WHERE origin_license = ANY (ARRAY['MC281714'::text, 'MP281909'::text])), 1) AS failed_ours_lb,
    round(sum(pounds) FILTER (WHERE origin_license IS NULL OR (origin_license <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]))), 1) AS failed_third_party_lb,
    count(*) FILTER (WHERE origin_license = ANY (ARRAY['MC281714'::text, 'MP281909'::text])) AS failed_ours_packages,
    count(*) FILTER (WHERE origin_license IS NULL OR (origin_license <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]))) AS failed_third_party_packages,
    COALESCE(string_agg(DISTINCT supplier, ', '::text) FILTER (WHERE origin_license IS NULL OR (origin_license <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]))), 'none'::text) AS third_party_suppliers,
    max(oldest_days) AS oldest_days
   FROM v_stock_on_hand
  WHERE lab_state = 'TestFailed'::text;
create or replace view public.v_fresh_frozen_equiv as
 SELECT origin,
    supplier,
    license,
    location,
    lab_state,
    packages,
    frozen_lb,
    dry_equivalent_lb,
    ratio_used,
    oldest_days,
    oldest_packaged,
    strains,
    the_arithmetic,
    why,
    oldest_packaged AS oldest_packaged_date
   FROM ( WITH f AS (
                 SELECT conversion_factors.value AS r
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
                )
         SELECT s.origin,
            s.supplier,
            s.license,
            s.location,
            s.lab_state,
            s.packages,
            s.pounds AS frozen_lb,
            round(s.pounds / (( SELECT f.r
                   FROM f)), 1) AS dry_equivalent_lb,
            ( SELECT f.r
                   FROM f) AS ratio_used,
            s.oldest_days,
            s.oldest_packaged,
            s.strains,
            ((((round(s.pounds, 1) || ' lb frozen / '::text) || (( SELECT f.r
                   FROM f))) || ' = '::text) || round(s.pounds / (( SELECT f.r
                   FROM f)), 1)) || ' lb dry-equivalent'::text AS the_arithmetic,
            'Fresh frozen still contains its water. Only the dry-equivalent figure may be compared with, or added to, dried flower.'::text AS why
           FROM v_stock_on_hand s
          WHERE s.stream = 'Fresh frozen'::text
          ORDER BY s.pounds DESC) q;
create or replace view public.v_guard_queue as
 SELECT 'overdue'::text AS queue,
    10 AS rank,
    s.finding_key AS subject,
    COALESCE(f.what, s.finding_key) AS detail,
    s.owning_agent AS owner,
    s.due_by AS since,
    round(EXTRACT(epoch FROM now() - s.due_by) / 3600::numeric)::integer AS hours,
    'past its deadline and still open'::text AS why
   FROM finding_state s
     LEFT JOIN v_findings f ON f.finding_key = s.finding_key
  WHERE (s.state = ANY (ARRAY['open'::text, 'acknowledged'::text, 'in_progress'::text])) AND s.due_by < now()
UNION ALL
 SELECT 'awaiting second check'::text AS queue,
    20 AS rank,
    c.finding_key AS subject,
    "left"(c.claim, 160) AS detail,
    c.proposed_by AS owner,
    c.proposed_at AS since,
    round(EXTRACT(epoch FROM now() - c.proposed_at) / 3600::numeric)::integer AS hours,
    ('proposed by '::text || c.proposed_by) || ', needs a DIFFERENT agent to derive it another way'::text AS why
   FROM finding_closure c
  WHERE c.verdict = 'pending'::text
UNION ALL
 SELECT
        CASE
            WHEN c.verdict = 'withdrawn'::text THEN 'closure WITHDRAWN'::text
            ELSE 'second check DISAGREED'::text
        END AS queue,
        CASE
            WHEN c.verdict = 'withdrawn'::text THEN 12
            ELSE 5
        END AS rank,
    c.finding_key AS subject,
    "left"(COALESCE(c.verdict_note, c.claim), 160) AS detail,
    COALESCE(c.second_by, c.proposed_by) AS owner,
    COALESCE(c.second_at, c.proposed_at) AS since,
    round(EXTRACT(epoch FROM now() - COALESCE(c.second_at, c.proposed_at)) / 3600::numeric)::integer AS hours,
        CASE
            WHEN c.verdict = 'withdrawn'::text THEN c.proposed_by || ' retracted its own closure; the finding is still open'::text
            ELSE ((c.proposed_by || ' claimed this was resolved and '::text) || COALESCE(c.second_by, 'the checker'::text)) || ' could not confirm it'::text
        END AS why
   FROM finding_closure c
  WHERE c.verdict = ANY (ARRAY['disagrees'::text, 'insufficient'::text, 'withdrawn'::text])
UNION ALL
 SELECT 'closed WITHOUT verification'::text AS queue,
    15 AS rank,
    s.finding_key AS subject,
    "left"(COALESCE(s.override_reason, ''::text), 160) AS detail,
    COALESCE(s.override_by, '?'::text) AS owner,
    s.override_at AS since,
    round(EXTRACT(epoch FROM now() - COALESCE(s.override_at, s.changed_at)) / 3600::numeric)::integer AS hours,
    'administrator override: closed with no independent check behind it'::text AS why
   FROM finding_state s
  WHERE s.override_reason IS NOT NULL
UNION ALL
 SELECT 'check has a known defect'::text AS queue,
    8 AS rank,
    d.check_key AS subject,
    "left"((d.claimed || ' -- actually: '::text) || d.actually, 160) AS detail,
    d.found_by AS owner,
    d.found_at AS since,
    round(EXTRACT(epoch FROM now() - d.found_at) / 3600::numeric)::integer AS hours,
    ((d.defect_kind || ' causing '::text) || d.impact) || '; every reading from this check is suspect until fixed'::text AS why
   FROM check_defect d
  WHERE d.fixed_at IS NULL
UNION ALL
 SELECT 'check never proven to fail'::text AS queue,
    40 AS rank,
    c.checker_key AS subject,
    COALESCE(c.title, c.checker_key) AS detail,
    COALESCE(c.runs_where, '?'::text) AS owner,
    NULL::timestamp with time zone AS since,
    NULL::integer AS hours,
    'no fixture demonstrates this check failing, so nothing shows it would catch the thing it watches'::text AS why
   FROM checker_registry c
  WHERE c.enabled AND NOT COALESCE(c.fixture_proves_it_fails, false)
UNION ALL
 SELECT 'route has no human owner'::text AS queue,
    50 AS rank,
    r.route_key AS subject,
    (r.route_key || ' -> '::text) || r.owning_agent AS detail,
    r.owning_agent AS owner,
    NULL::timestamp with time zone AS since,
    NULL::integer AS hours,
    'findings on this route reach an agent but escalate to nobody named'::text AS why
   FROM finding_route r
  WHERE r.enabled AND COALESCE(r.human_owner, ''::text) = ''::text;
create or replace view public.v_harvest_alerts as
 WITH r AS (
         SELECT harvest_alert_rules.rule_key,
            harvest_alert_rules.label,
            harvest_alert_rules.threshold,
            harvest_alert_rules.severity
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        )
 SELECT m.license,
    m.harvest,
    m.room,
    'Drying'::text AS area,
        CASE
            WHEN m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN ( SELECT r.severity
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)
            ELSE ( SELECT r.severity
               FROM r
              WHERE r.rule_key = 'dry_target_days'::text)
        END AS severity,
        CASE
            WHEN m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN ((('Dry window exceeded - day '::text || m.days_since_takedown) || ' of a '::text) || (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text))::integer) || '-day limit'::text
            ELSE 'Dry target reached - day '::text || m.days_since_takedown
        END AS alert,
    m.days_since_takedown::numeric AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE m.stage ~~ 'Drying%'::text AND m.days_since_takedown::numeric >= (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_target_days'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Weight reporting'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'weights_due_days'::text) AS severity,
    ('No weights reported '::text || m.days_since_takedown) || ' days after takedown'::text AS alert,
    m.days_since_takedown::numeric AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE COALESCE(m.wet_weight, 0::numeric) = 0::numeric AND m.days_since_takedown::numeric >= (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'weights_due_days'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Cycle'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'cure_max_days'::text) AS severity,
    ('Still unfinished '::text || m.days_since_takedown) || ' days after takedown - the next pull for this room is at risk'::text AS alert,
    m.days_since_takedown::numeric AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND m.days_since_takedown::numeric > (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'cure_max_days'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Waste'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'waste_pct_max'::text) AS severity,
    ((('Waste at '::text || m.waste_pct) || ' percent of wet weight - above the '::text) || (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'waste_pct_max'::text))::integer) || ' percent limit'::text AS alert,
    m.waste_pct AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE m.waste_pct > (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'waste_pct_max'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Yield'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'yield_pct_min'::text) AS severity,
    ((('Yield at '::text || m.yield_pct) || ' percent of wet weight - below the '::text) || (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'yield_pct_min'::text))::integer) || ' percent floor'::text AS alert,
    m.yield_pct AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE COALESCE(m.packaged_weight, 0::numeric) > 0::numeric AND m.yield_pct < (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'yield_pct_min'::text))
UNION ALL
 SELECT 'MC281714'::text AS license,
    'Pull #'::text || p.pull_no AS harvest,
    p.flower_room AS room,
    'Planner'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'pull_overdue_days'::text) AS severity,
    ((('Planned pull on '::text || p.harvest_date) || ' has no harvest recorded - '::text) || (CURRENT_DATE - p.harvest_date)) || ' days late'::text AS alert,
    (CURRENT_DATE - p.harvest_date)::numeric AS value,
    'Planned'::text AS stage,
    p.harvest_date AS reference_date
   FROM harvest_pulls p
  WHERE p.harvest_date < (CURRENT_DATE - (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'pull_overdue_days'::text))::integer) AND NOT (EXISTS ( SELECT 1
           FROM metrc_harvests h
          WHERE h.harvest_start >= (p.harvest_date - 3) AND h.harvest_start <= (p.harvest_date + 7)));
create or replace view public.v_harvest_cycle_by_room as
 SELECT flower_room,
    department,
    count(*) FILTER (WHERE cycle_days IS NOT NULL) AS cycles_measured,
    count(*) FILTER (WHERE breaches_rule) AS cycles_over_target,
    min(cycle_days) AS fastest_cycle_days,
    max(cycle_days) AS slowest_cycle_days,
    round(avg(cycle_days), 1) AS average_cycle_days,
    max(target_days) AS target_days,
    round(avg(cycle_days), 1) - max(target_days)::numeric AS average_slip_days,
    max(pull_start) AS last_pull_start,
    CURRENT_DATE - max(pull_start) AS days_since_last_pull,
    max(pull_start) + max(target_days) AS next_pull_due,
    CURRENT_DATE - (max(pull_start) + max(target_days)) AS days_overdue_now
   FROM v_harvest_cycle_compliance
  GROUP BY flower_room, department;
create or replace view public.v_harvest_economics as
 SELECT harvest,
    strain,
    room,
    harvest_start,
    plants,
    wet_lbs,
    packaged_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    cost_per_pound,
    cost_to_grow,
    cost_lost_to_waste,
    true_cost_per_saleable_pound,
    stage,
    harvest_start AS harvest_start_date
   FROM ( SELECT m.harvest,
            m.strains AS strain,
            m.room,
            m.harvest_start,
            m.plants,
            round(COALESCE(m.wet_weight, 0::numeric) / 453.592, 1) AS wet_lbs,
            round(COALESCE(m.packaged_weight, 0::numeric) / 453.592, 1) AS packaged_lbs,
            round(COALESCE(m.waste_weight, 0::numeric) / 453.592, 1) AS waste_lbs,
            m.waste_pct,
            m.yield_pct,
            ( SELECT cost_model.cost_per_pound
                   FROM cost_model
                  WHERE cost_model.scope = 'cultivation'::text
                  ORDER BY cost_model.effective_from DESC
                 LIMIT 1) AS cost_per_pound,
            round(COALESCE(m.wet_weight, 0::numeric) / 453.592 * (( SELECT cost_model.cost_per_pound
                   FROM cost_model
                  WHERE cost_model.scope = 'cultivation'::text
                  ORDER BY cost_model.effective_from DESC
                 LIMIT 1)), 0) AS cost_to_grow,
            round(COALESCE(m.waste_weight, 0::numeric) / 453.592 * (( SELECT cost_model.cost_per_pound
                   FROM cost_model
                  WHERE cost_model.scope = 'cultivation'::text
                  ORDER BY cost_model.effective_from DESC
                 LIMIT 1)), 0) AS cost_lost_to_waste,
                CASE
                    WHEN COALESCE(m.packaged_weight, 0::numeric) > 0::numeric THEN round(COALESCE(m.wet_weight, 0::numeric) / 453.592 * (( SELECT cost_model.cost_per_pound
                       FROM cost_model
                      WHERE cost_model.scope = 'cultivation'::text
                      ORDER BY cost_model.effective_from DESC
                     LIMIT 1)) / (COALESCE(m.packaged_weight, 0::numeric) / 453.592), 0)
                    ELSE NULL::numeric
                END AS true_cost_per_saleable_pound,
            m.stage
           FROM v_harvest_stage_map m
          WHERE COALESCE(m.wet_weight, 0::numeric) > 0::numeric
          ORDER BY m.harvest_start DESC NULLS LAST) q;
create or replace view public.v_harvest_lifecycle as
 WITH a AS (
         SELECT h.license,
            h.name AS harvest,
            COALESCE(h.raw ->> 'SourceStrainNames'::text, h.name) AS strain,
            COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            h.harvest_start AS takedown_actual,
            (h.raw ->> 'FinishedDate'::text)::date AS finished_actual,
            COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants,
            COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) AS wet_g,
            COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) AS waste_g,
            COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) AS packaged_g,
            h.raw ->> 'LabTestingState'::text AS lab_state
           FROM metrc_harvests h
          WHERE h.harvest_start IS NOT NULL
        ), p AS (
         SELECT pl.pull_no,
            pl.harvest_date AS planned_date,
            pl.flower_room,
            pl.cultivars,
            pl.dry_start AS planned_dry_start,
            pl.dry_day_10 AS planned_dry_target,
            pl.dry_day_14 AS planned_dry_deadline,
            pl.day2_replant_date AS planned_replant,
            pl.proj_harvest_weight_lbs AS planned_lbs,
            pl.original_total_plants AS planned_plants
           FROM harvest_pulls pl
        ), r AS (
         SELECT harvest_alert_rules.threshold,
            harvest_alert_rules.rule_key
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        )
 SELECT a.harvest,
    a.strain,
    a.room,
    a.license,
    p.pull_no AS planned_pull,
    p.planned_date,
    p.planned_plants,
    round(COALESCE(p.planned_lbs, 0::numeric), 1) AS planned_lbs,
    a.takedown_actual,
        CASE
            WHEN p.planned_date IS NULL THEN 'No matching plan'::text
            WHEN a.takedown_actual > p.planned_date THEN ('LATE by '::text || (a.takedown_actual - p.planned_date)) || ' days'::text
            WHEN a.takedown_actual < p.planned_date THEN ('Early by '::text || (p.planned_date - a.takedown_actual)) || ' days'::text
            ELSE 'On the planned date'::text
        END AS takedown_status,
    a.plants AS actual_plants,
        CASE
            WHEN p.planned_plants > 0::numeric THEN round(100.0 * a.plants / p.planned_plants, 1)
            ELSE NULL::numeric
        END AS plants_pct_of_plan,
    CURRENT_DATE - a.takedown_actual AS days_since_takedown,
    a.takedown_actual + (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_target_days'::text))::integer AS dry_target_date,
    a.takedown_actual + (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_max_days'::text))::integer AS dry_deadline_date,
        CASE
            WHEN a.finished_actual IS NOT NULL THEN 'Dry complete on '::text || a.finished_actual
            WHEN (CURRENT_DATE - a.takedown_actual)::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN (('DRY DEADLINE BLOWN - day '::text || (CURRENT_DATE - a.takedown_actual)) || ' of '::text) || (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text))::integer
            WHEN (CURRENT_DATE - a.takedown_actual)::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_target_days'::text)) THEN ('At dry target - day '::text || (CURRENT_DATE - a.takedown_actual)) || ', finish it'::text
            ELSE 'Drying on track - day '::text || (CURRENT_DATE - a.takedown_actual)
        END AS drying_status,
        CASE
            WHEN a.wet_g > 0::numeric THEN 'Reported'::text
            WHEN (CURRENT_DATE - a.takedown_actual)::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'weights_due_days'::text)) THEN ('WEIGHTS NOT REPORTED - '::text || (CURRENT_DATE - a.takedown_actual)) || ' days after takedown'::text
            ELSE ('Due within '::text || ((( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'weights_due_days'::text))::integer - (CURRENT_DATE - a.takedown_actual))) || ' days'::text
        END AS weights_status,
    round(a.wet_g / 453.592, 1) AS wet_lbs,
    round(a.waste_g / 453.592, 1) AS waste_lbs,
        CASE
            WHEN a.wet_g > 0::numeric THEN round(100.0 * a.waste_g / a.wet_g, 1)
            ELSE NULL::numeric
        END AS waste_pct,
    round(a.packaged_g / 453.592, 1) AS packaged_lbs,
        CASE
            WHEN a.wet_g > 0::numeric THEN round(100.0 * a.packaged_g / a.wet_g, 1)
            ELSE NULL::numeric
        END AS yield_pct,
        CASE
            WHEN COALESCE(p.planned_lbs, 0::numeric) > 0::numeric THEN round(a.packaged_g / 453.592 - p.planned_lbs, 1)
            ELSE NULL::numeric
        END AS lbs_vs_plan,
    ( SELECT count(*) AS count
           FROM mv_package_harvest k
          WHERE k.harvest_name = a.harvest) AS packages_made,
    ( SELECT count(*) AS count
           FROM allocation_requests ar
          WHERE ar.source_ref ~~* (('%'::text || a.harvest) || '%'::text) OR ar.strain ~~* (('%'::text || a.strain) || '%'::text)) AS allocation_requests,
    ( SELECT string_agg(DISTINCT ((((ar.requester_name || ' -> '::text) || COALESCE(ar.decider_name, 'awaiting decision'::text)) || ' ('::text) || ar.status) || ')'::text, '; '::text) AS string_agg
           FROM allocation_requests ar
          WHERE ar.source_ref ~~* (('%'::text || a.harvest) || '%'::text) OR ar.strain ~~* (('%'::text || a.strain) || '%'::text)) AS allocation_chain,
    ( SELECT count(*) AS count
           FROM mv_package_harvest k
             JOIN metrc_packages p2 ON p2.id = k.package_id
          WHERE k.harvest_name = a.harvest AND p2.source_state = 'intransit'::text) AS packages_shipped,
    a.lab_state,
        CASE
            WHEN a.finished_actual IS NULL AND (CURRENT_DATE - a.takedown_actual)::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN 'BLOCKING THE ROOM'::text
            WHEN a.wet_g = 0::numeric AND (CURRENT_DATE - a.takedown_actual)::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'weights_due_days'::text)) THEN 'MISSING WEIGHTS'::text
            WHEN p.planned_date IS NOT NULL AND a.takedown_actual > (p.planned_date + 2) THEN 'HARVESTED LATE'::text
            WHEN a.wet_g > 0::numeric AND (100.0 * a.waste_g / NULLIF(a.wet_g, 0::numeric)) > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'waste_pct_max'::text)) THEN 'EXCESS WASTE'::text
            WHEN a.finished_actual IS NOT NULL THEN 'Complete'::text
            ELSE 'On track'::text
        END AS verdict
   FROM a
     LEFT JOIN p ON p.flower_room = a.room AND a.takedown_actual >= (p.planned_date - 4) AND a.takedown_actual <= (p.planned_date + 10)
  ORDER BY (
        CASE
            WHEN a.finished_actual IS NULL THEN 0
            ELSE 1
        END), a.takedown_actual DESC;
create or replace view public.v_harvest_lineage_summary as
 SELECT harvest,
    license,
    room,
    stage,
    strains,
    plants,
    wet_weight,
    waste_weight,
    packaged_weight,
    waste_pct,
    yield_pct,
    days_since_takedown,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text)) AS packages_made,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text) AND p.lab_testing_state = 'TestPassed'::text) AS packages_passed,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text) AND p.source_state = 'intransit'::text) AS packages_shipped,
    ( SELECT round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS round
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS quantity_on_hand
   FROM v_harvest_stage_map m;
create or replace view public.v_harvest_plan_vs_actual as
 WITH r AS (
         SELECT harvest_alert_rules.rule_key,
            harvest_alert_rules.threshold
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        ), td AS (
         SELECT t.flower_room,
            t.takedown_start,
            t.takedown_end,
            row_number() OVER (PARTITION BY t.flower_room ORDER BY t.takedown_start) AS seq_plan
           FROM v_harvest_takedown t
             JOIN v_plan_room_floor f ON f.flower_room = t.flower_room
          WHERE t.is_material AND t.takedown_start >= f.floor_date
        ), pn AS (
         SELECT p.pull_no,
            p.harvest_date,
            p.flower_room,
            p.cultivars,
            p.original_total_plants,
            p.proj_harvest_weight_lbs,
            p.dry_day_14,
            row_number() OVER (PARTITION BY p.flower_room ORDER BY p.harvest_date) AS seq_plan
           FROM harvest_pulls p
        ), m AS (
         SELECT pn.pull_no,
            pn.harvest_date,
            pn.flower_room,
            pn.cultivars,
            pn.original_total_plants,
            pn.proj_harvest_weight_lbs,
            pn.dry_day_14,
            pn.seq_plan,
            td.takedown_start,
            td.takedown_end
           FROM pn
             LEFT JOIN td ON td.flower_room = pn.flower_room AND td.seq_plan = pn.seq_plan
        ), a AS (
         SELECT m_1.pull_no,
            string_agg(DISTINCT NULLIF(COALESCE(h.raw ->> 'DryingLocationName'::text, ''::text), ''::text), ', '::text) AS dry_rooms,
            string_agg(DISTINCT h.name, ', '::text) AS harvests,
            sum((h.raw ->> 'PlantCount'::text)::numeric) AS actual_plants,
            sum(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
            sum(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS pkg_g,
            sum(COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g
           FROM m m_1
             JOIN metrc_harvests h ON h.flower_room = m_1.flower_room AND h.harvest_start >= m_1.takedown_start AND h.harvest_start <= m_1.takedown_end
          GROUP BY m_1.pull_no
        )
 SELECT m.pull_no,
    m.harvest_date AS planned_date,
    m.flower_room,
    m.cultivars,
    m.original_total_plants AS planned_plants,
    round(m.proj_harvest_weight_lbs, 1) AS planned_lbs,
    m.takedown_start AS actual_date,
    a.dry_rooms AS actual_room,
    a.harvests,
    a.actual_plants,
    round(a.wet_g / 453.592, 1) AS actual_wet_lbs,
    round(a.pkg_g / 453.592, 1) AS actual_packaged_lbs,
    round(a.waste_g / 453.592, 1) AS actual_waste_lbs,
        CASE
            WHEN m.takedown_start IS NULL AND m.harvest_date >= CURRENT_DATE THEN 'Scheduled'::text
            WHEN m.takedown_start IS NULL THEN ((('NOT HARVESTED - '::text || (CURRENT_DATE - m.harvest_date)) || ' days past schedule, room '::text) || m.flower_room) || ' still standing'::text
            WHEN (m.takedown_start - m.harvest_date) > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'late_tolerance_days'::text))::integer THEN ('Late by '::text || (m.takedown_start - m.harvest_date)) || ' days'::text
            WHEN (m.harvest_date - m.takedown_start) > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'early_allowance_days'::text))::integer THEN ('Early by '::text || (m.harvest_date - m.takedown_start)) || ' days'::text
            ELSE 'On plan'::text
        END AS timing,
        CASE
            WHEN a.actual_plants IS NOT NULL AND m.original_total_plants > 0::numeric THEN round(100.0 * a.actual_plants / m.original_total_plants, 1)
            ELSE NULL::numeric
        END AS plants_pct_of_plan,
        CASE
            WHEN a.pkg_g > 0::numeric AND m.proj_harvest_weight_lbs > 0::numeric THEN round(100.0 * (a.pkg_g / 453.592) / m.proj_harvest_weight_lbs, 1)
            ELSE NULL::numeric
        END AS weight_pct_of_plan,
    m.dry_day_14 AS dry_deadline
   FROM m
     LEFT JOIN a ON a.pull_no = m.pull_no
  ORDER BY m.harvest_date DESC;
create or replace view public.v_harvest_yield_audit as
 WITH base AS (
         SELECT v.harvest,
            v.strain,
            v.room,
            v.finished_on,
            v.licence,
            v.plants,
            v.wet_in_lb,
            v.waste_lb,
            v.water_lost_lb,
            v.dry_yield_lb,
            v.water_pct,
            v.harvest_state,
            v.drying_kind,
            v.wet_in_lb * 453.592 / NULLIF(v.plants, 0::numeric) AS wet_g_plant,
            v.dry_yield_lb * 453.592 / NULLIF(v.plants, 0::numeric) AS dry_g_plant
           FROM v_harvest_water_and_yield v
          WHERE v.harvest_state = 'CLOSED'::text AND v.drying_kind = 'dried'::text AND COALESCE(v.plants, 0::numeric) > 0::numeric
        ), strain_norm AS (
         SELECT base.strain,
            percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (base.dry_g_plant::double precision)) AS strain_median_dry_g,
            count(*) AS strain_harvests
           FROM base
          GROUP BY base.strain
        )
 SELECT b.harvest,
    b.strain,
    b.room,
    b.finished_on,
    b.licence,
    b.plants,
    round(b.wet_in_lb, 1) AS wet_in_lb,
    round(b.dry_yield_lb, 1) AS dry_yield_lb,
    round(b.wet_g_plant, 1) AS wet_g_per_plant,
    round(b.dry_g_plant, 1) AS dry_g_per_plant,
    round(b.water_pct, 1) AS water_pct,
    round(b.plants * 70.6 / 453.592, 1) AS expected_dry_lb_at_target,
    round(b.dry_yield_lb - b.plants * 70.6 / 453.592, 1) AS vs_target_lb,
    round((b.dry_yield_lb - b.plants * 70.6 / 453.592) * 1100::numeric, 0) AS vs_target_dollars,
    round(s.strain_median_dry_g::numeric, 1) AS strain_median_dry_g,
    s.strain_harvests,
    round((b.dry_g_plant::double precision - s.strain_median_dry_g)::numeric, 1) AS vs_own_strain_g,
        CASE
            WHEN b.water_pct >= 70::numeric AND b.water_pct <= 77::numeric AND b.dry_g_plant >= 70.6 THEN 'OK - water in band, yield at target'::text
            WHEN b.water_pct >= 70::numeric AND b.water_pct <= 77::numeric AND b.dry_g_plant < 70.6 THEN 'YIELD SHORT, drying normal. The plants or the grow underperformed - not the dry room'::text
            WHEN b.water_pct > 77::numeric AND b.dry_g_plant < 70.6 THEN 'CHECK: more weight vanished in drying than drying explains, AND the yield is short. '::text || 'Either the wet weight was overstated at takedown or material left after weighing'::text
            WHEN b.water_pct > 77::numeric AND b.dry_g_plant >= 70.6 THEN 'water above band but yield is fine - wet weight likely overstated at takedown'::text
            WHEN b.water_pct < 70::numeric AND b.dry_g_plant < 70.6 THEN 'CHECK: too little water lost for a dried harvest AND yield short - the wet weight '::text || 'may have been understated to make a poor yield look normal'::text
            WHEN b.water_pct < 70::numeric THEN 'water below band - wet weight may be understated, though yield is at target'::text
            ELSE 'review'::text
        END AS audit_verdict,
        CASE
            WHEN b.dry_g_plant < 25::numeric THEN 'SEVERE - under 25 g per plant'::text
            WHEN b.dry_g_plant < 50::numeric THEN 'HIGH - under half target'::text
            WHEN b.dry_g_plant < 70.6 THEN 'watch - below target'::text
            ELSE 'none'::text
        END AS concern,
    (((((((((((((((((((((b.harvest || ' in '::text) || COALESCE(b.room, 'an unrecorded room'::text)) || ': '::text) || b.plants) || ' plants gave '::text) || round(b.dry_yield_lb, 1)) || ' lb dry = '::text) || round(b.dry_g_plant, 1)) || ' g per plant against the 70.6 g target ('::text) ||
        CASE
            WHEN b.dry_yield_lb >= (b.plants * 70.6 / 453.592) THEN 'ahead by '::text
            ELSE 'short by '::text
        END) || round(abs(b.dry_yield_lb - b.plants * 70.6 / 453.592), 1)) || ' lb, '::text) ||
        CASE
            WHEN b.dry_yield_lb >= (b.plants * 70.6 / 453.592) THEN '+'::text
            ELSE '-'::text
        END) || '$'::text) || round(abs((b.dry_yield_lb - b.plants * 70.6 / 453.592) * 1100::numeric), 0)) || '). Water loss was '::text) || round(b.water_pct, 1)) || '% against the 70-77% band. This strain''s own median is '::text) || round(s.strain_median_dry_g::numeric, 1)) || ' g per plant across '::text) || s.strain_harvests) || ' harvests.'::text AS in_plain_english
   FROM base b
     JOIN strain_norm s ON s.strain = b.strain;
create or replace view public.v_issue_attribution as
 WITH failed AS (
         SELECT 'Failed testing'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages AS items,
            v_stock_on_hand.pounds,
            round(v_stock_on_hand.pounds * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.lab_state = 'TestFailed'::text
        ), aged AS (
         SELECT 'Sitting over 180 days'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            round(v_stock_on_hand.pounds * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.oldest_days > 180
        ), untested AS (
         SELECT 'Never submitted for testing'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            round(v_stock_on_hand.pounds * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text
        ), nosupplier AS (
         SELECT 'Bought in with no supplier recorded'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            NULL::numeric AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.origin = 'Bought in'::text AND v_stock_on_hand.supplier = '(supplier not recorded)'::text
        )
 SELECT issue,
    origin,
    supplier,
    stream,
    items,
    pounds,
    dollars,
        CASE
            WHEN origin = 'Grown by us'::text THEN 'Ours to fix'::text
            ELSE 'Raise with '::text || supplier
        END AS accountable
   FROM ( SELECT failed.issue,
            failed.origin,
            failed.supplier,
            failed.stream,
            failed.items,
            failed.pounds,
            failed.dollars
           FROM failed
        UNION ALL
         SELECT aged.issue,
            aged.origin,
            aged.supplier,
            aged.stream,
            aged.packages,
            aged.pounds,
            aged.dollars
           FROM aged
        UNION ALL
         SELECT untested.issue,
            untested.origin,
            untested.supplier,
            untested.stream,
            untested.packages,
            untested.pounds,
            untested.dollars
           FROM untested
        UNION ALL
         SELECT nosupplier.issue,
            nosupplier.origin,
            nosupplier.supplier,
            nosupplier.stream,
            nosupplier.packages,
            nosupplier.pounds,
            nosupplier.dollars
           FROM nosupplier) x
  ORDER BY dollars DESC NULLS LAST, pounds DESC;
create or replace view public.v_issue_real_loss as
 SELECT loss_type,
    scope,
    location,
    units,
    unit_label,
    pounds,
    round(COALESCE(pounds, 0::numeric) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_at_cost,
    why_it_is_a_loss AS what_is_wrong,
    what_to_check AS what_to_do,
    ( SELECT m.harvest_start
           FROM v_harvest_stage_map m
          WHERE m.strains = r.scope OR m.harvest = r.scope
         LIMIT 1) AS harvest_date,
    ( SELECT m.room
           FROM v_harvest_stage_map m
          WHERE m.strains = r.scope OR m.harvest = r.scope
         LIMIT 1) AS room,
    ( SELECT m.days_since_takedown
           FROM v_harvest_stage_map m
          WHERE m.strains = r.scope OR m.harvest = r.scope
         LIMIT 1) AS days_since_takedown
   FROM v_real_loss r
  ORDER BY (round(COALESCE(pounds, 0::numeric) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_issue_yield_gap as
 SELECT room,
    count(*) AS harvests,
    round(avg(conversion_pct), 1) AS our_conversion_pct,
    round(avg(company_average_pct), 1) AS company_average_pct,
    round(avg(industry_average_pct), 1) AS industry_average_pct,
    round(sum(pounds_short_of_company_average), 1) AS pounds_short,
    round(sum(dollars_short), 0) AS dollars_short,
    round(sum(saleable_lbs), 1) AS saleable_lbs,
    round(sum(plants), 0) AS plants,
    max(harvest_date) AS most_recent_harvest,
    count(*) FILTER (WHERE conversion_pct < company_average_pct) AS harvests_below_our_average,
    max(harvest_date) AS most_recent_harvest_date
   FROM v_issue_yield_by_harvest y
  GROUP BY room;
create or replace view public.v_lab_report_only_packages as
 SELECT source_tag AS package_tag,
    max(source_item) AS item_name,
    max(laboratory) AS laboratory,
    max(test_date) AS test_date,
    count(*) AS analytes,
    bool_and(COALESCE(sample_passed, true)) AS all_passed,
    max(strain_or_blend) AS strain_or_blend,
    'Laboratory results exist for this package in the Metrc Lab Results report, and the packages API never returned them. Anything calling it untested from the API alone is wrong (rule C0b).'::text AS why_it_matters
   FROM v_lab_sample_link l
  WHERE NOT also_in_api_sync
  GROUP BY source_tag;
create or replace view public.v_leadership_cost_vs_output as
 SELECT COALESCE(d.name, 'not assigned'::text) AS department,
    count(e.id)::numeric AS headcount,
    round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)), 0) AS weekly_loaded_cost,
    round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)) * 52::numeric, 0) AS annual_loaded_cost,
    round(max(COALESCE(pf.loaded_weekly_cost, 0::numeric)), 0) AS highest_paid_weekly,
    ( SELECT string_agg(x.full_name, ', '::text) AS string_agg
           FROM ( SELECT e2.full_name
                   FROM employees e2
                     LEFT JOIN v_payroll_forecast p2 ON p2.full_name = e2.full_name
                  WHERE e2.primary_department_id = d.id AND e2.terminated_on IS NULL
                  ORDER BY (COALESCE(p2.loaded_weekly_cost, 0::numeric)) DESC
                 LIMIT 3) x) AS highest_paid_people,
        CASE
            WHEN d.name ~~* '%cultivation%'::text THEN ( SELECT round(sum(v_true_cost_per_pound.saleable_lbs), 1) AS round
               FROM v_true_cost_per_pound
              WHERE v_true_cost_per_pound.month_date >= (CURRENT_DATE - 90))
            ELSE NULL::numeric
        END AS saleable_lbs_90d,
        CASE
            WHEN d.name ~~* '%cultivation%'::text THEN round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)) * 13::numeric / NULLIF(( SELECT sum(v_true_cost_per_pound.saleable_lbs) AS sum
               FROM v_true_cost_per_pound
              WHERE v_true_cost_per_pound.month_date >= (CURRENT_DATE - 90)), 0::numeric), 0)
            ELSE NULL::numeric
        END AS labour_cost_per_saleable_pound_90d
   FROM departments d
     LEFT JOIN employees e ON e.primary_department_id = d.id AND e.terminated_on IS NULL
     LEFT JOIN v_payroll_forecast pf ON pf.full_name = e.full_name
  GROUP BY d.id, d.name
  ORDER BY (round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)) * 52::numeric, 0)) DESC NULLS LAST;
create or replace view public.v_ledger_validation as
 WITH rebuilt AS (
         SELECT v_package_events.package_tag,
            round(sum(v_package_events.lb_delta), 3) AS reconstructed_lb
           FROM v_package_events
          GROUP BY v_package_events.package_tag
        ), actual AS (
         SELECT p.raw ->> 'Label'::text AS package_tag,
            round(f_to_pounds(COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3) AS actual_lb
           FROM metrc_packages p
          WHERE f_is_weight(COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))
        )
 SELECT count(*) AS tags,
    count(*) FILTER (WHERE abs(r.reconstructed_lb - a.actual_lb) < 0.01) AS matches_within_0_01_lb,
    count(*) FILTER (WHERE abs(r.reconstructed_lb - a.actual_lb) >= 0.01) AS differs,
    round(100.0 * count(*) FILTER (WHERE abs(r.reconstructed_lb - a.actual_lb) < 0.01)::numeric / count(*)::numeric, 1) AS pct_reproduced,
    round(sum(r.reconstructed_lb), 1) AS total_reconstructed_lb,
    round(sum(a.actual_lb), 1) AS total_actual_lb,
    round(sum(r.reconstructed_lb) - sum(a.actual_lb), 1) AS total_variance_lb
   FROM rebuilt r
     JOIN actual a ON a.package_tag = r.package_tag;
create or replace view public.v_loss_analysis as
 WITH h AS (
         SELECT COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            COALESCE(metrc_harvests.raw ->> 'SourceStrainNames'::text, '(not recorded)'::text) AS strain,
            to_char(metrc_harvests.harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, metrc_harvests.harvest_start::timestamp with time zone)::date AS month_date,
            metrc_harvests.name AS harvest,
            metrc_harvests.harvest_start,
            COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) AS wet_g,
            COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) AS waste_g,
            COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) AS packaged_g,
            COALESCE((metrc_harvests.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants
           FROM metrc_harvests
          WHERE metrc_harvests.harvest_start IS NOT NULL
        )
 SELECT room,
    strain,
    month,
    month_date,
    count(*)::numeric AS harvests,
    sum(plants) AS plants,
    round(sum(wet_g) / 453.592, 1) AS wet_lbs,
    round(sum(waste_g) / 453.592, 1) AS waste_lbs,
    round(sum(packaged_g) / 453.592, 1) AS packaged_lbs,
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(waste_g) / sum(wet_g), 1)
            ELSE NULL::numeric
        END AS waste_pct,
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(packaged_g) / sum(wet_g), 1)
            ELSE NULL::numeric
        END AS yield_pct,
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(waste_g) / sum(wet_g) - (( SELECT 100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / NULLIF(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 0::numeric)
               FROM metrc_harvests)), 1)
            ELSE NULL::numeric
        END AS waste_pct_vs_company_average,
        CASE
            WHEN sum(wet_g) = 0::numeric THEN 'No weights recorded - cannot analyse'::text
            WHEN (100.0 * sum(waste_g) / sum(wet_g)) > 25::numeric THEN 'SEVERE - investigate this room and crew immediately'::text
            WHEN (100.0 * sum(waste_g) / sum(wet_g)) > 15::numeric THEN 'HIGH - above the acceptable band'::text
            WHEN (100.0 * sum(waste_g) / sum(wet_g)) > 10::numeric THEN 'ELEVATED - watch it'::text
            ELSE 'Within normal range'::text
        END AS loss_verdict,
    ( SELECT round(sum(h.waste_g) / 453.592 * 453.592 * max(v_route_margin.margin_per_input_gram), 0) AS round
           FROM v_route_margin) AS lost_margin_estimate,
    max(harvest_start) AS last_harvest
   FROM h
  GROUP BY room, strain, month, month_date
  ORDER BY (
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(waste_g) / sum(wet_g), 1)
            ELSE NULL::numeric
        END) DESC NULLS LAST;
create or replace view public.v_manifest_custody as
 WITH oriented AS (
         SELECT m.manifest_number,
            m.date_created,
            m.departure,
            m.arrival,
            m.is_lab_run,
            t.direction,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.destination_license
                    ELSE m.origin_license
                END AS ship_lic,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.origin_license
                    ELSE m.destination_license
                END AS dest_lic,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.destination_name
                    ELSE m.origin_name
                END AS ship_nm,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.origin_name
                    ELSE m.destination_name
                END AS dest_nm,
            m.transporter_name,
            m.transporter_license,
            t.raw ->> 'ShipperFacilityLicenseNumber'::text AS metrc_shipper
           FROM manifest_extract m
             LEFT JOIN metrc_transfers t ON t.manifest_number = m.manifest_number
        )
 SELECT o.manifest_number,
    o.date_created,
    o.direction,
    COALESCE(sd.name, o.ship_nm) AS shipped_by,
    o.ship_lic AS origin_license,
    COALESCE(dd.name, o.dest_nm) AS delivered_to,
    o.dest_lic AS destination_license,
        CASE
            WHEN o.dest_lic IS NULL THEN 'UNKNOWN'::text
            WHEN o.dest_lic ~~ 'IL%'::text THEN 'LABORATORY'::text
            WHEN o.dest_lic ~~ 'MX%'::text THEN 'TRANSPORTER'::text
            WHEN o.dest_lic ~~ 'MT%'::text THEN 'STORAGE / TRANSPORT - never a sale'::text
            WHEN o.dest_lic ~~ 'MR%'::text OR o.dest_lic ~~ 'RMD%'::text THEN 'RETAIL'::text
            ELSE 'LICENSEE'::text
        END AS destination_kind,
    COALESCE(o.transporter_name, td.name) AS carried_by,
    o.transporter_license,
    o.is_lab_run,
    o.departure,
    o.arrival,
    ( SELECT count(*) AS count
           FROM metrc_rpt_package_transfers p
          WHERE p.manifest_number = o.manifest_number) AS packages,
    o.metrc_shipper IS NOT NULL AND o.ship_lic IS NOT NULL AND o.metrc_shipper <> o.ship_lic AS shipper_disagrees_with_metrc
   FROM oriented o
     LEFT JOIN v_licence_directory sd ON sd.licence = o.ship_lic
     LEFT JOIN v_licence_directory dd ON dd.licence = o.dest_lic
     LEFT JOIN v_licence_directory td ON td.licence = o.transporter_license;
create or replace view public.v_manifest_discrepancy_audit as
 SELECT manifest_number,
    metrc_date,
    metrc_received,
    destination_licence,
    destination_facility,
    metrc_invoice_number,
    apex_invoices,
    apex_order_date,
    apex_delivery_date,
    date_gap_days,
    metrc_declared,
    apex_value,
    value_gap,
        CASE
            WHEN value_gap > 0::numeric THEN 'Apex sold MORE than Metrc declares'::text
            WHEN value_gap < 0::numeric THEN 'Metrc declares MORE than Apex sold'::text
            ELSE NULL::text
        END AS direction,
    money_lines,
    voided_lines,
    placeholder_lines,
    package_tags,
    apex_orders,
    status,
        CASE
            WHEN apex_orders > 1 THEN 'Invoice number covers several Apex orders — sum them before comparing'::text
            WHEN voided_lines > 0 THEN 'Metrc rows are voided on this manifest — confirm which were excluded'::text
            WHEN placeholder_lines > 0 THEN 'Metrc carries placeholder prices under $1.00 on this manifest'::text
            WHEN abs(date_gap_days) > 7 THEN 'Apex and Metrc dates are more than a week apart — likely a different shipment'::text
            WHEN package_tags = 0 THEN 'No package lines in the transfer export — open the manifest PDF'::text
            ELSE 'Compare the manifest PDF line by line against the Apex order'::text
        END AS where_to_look
   FROM v_manifest_reconciliation r
  WHERE destination_kind = 'SALE'::text AND value_gap IS NOT NULL AND abs(value_gap) > (( SELECT conversion_factors.value
           FROM conversion_factors
          WHERE conversion_factors.key = 'apex_metrc_rounding_tolerance_usd'::text));
create or replace view public.v_manifest_discrepancy_summary as
 SELECT to_char(date_trunc('month'::text, metrc_date::timestamp with time zone), 'YYYY-MM'::text) AS month,
    count(*) FILTER (WHERE destination_kind = 'SALE'::text) AS sale_manifests,
    count(*) FILTER (WHERE status = 'RECONCILED'::text) AS reconciled,
    count(*) FILTER (WHERE status ~~ 'VALUE DIFFERS%'::text) AS value_differs,
    count(*) FILTER (WHERE status = 'NO APEX ORDER for this invoice number'::text) AS no_apex_order,
    count(*) FILTER (WHERE status = 'NO INVOICE NUMBER on the Metrc record'::text) AS no_invoice_number,
    count(*) FILTER (WHERE status ~~ 'BEFORE THE KEY%'::text) AS before_key_existed,
    count(*) FILTER (WHERE destination_kind = 'LABORATORY SAMPLE'::text) AS lab_manifests,
    sum(package_tags) FILTER (WHERE destination_kind = 'LABORATORY SAMPLE'::text) AS lab_package_tags,
    count(*) FILTER (WHERE destination_kind = 'INTERNAL TRANSFER'::text) AS internal_manifests,
    count(*) FILTER (WHERE destination_kind = 'TRANSPORTER'::text) AS transporter_manifests,
    count(*) FILTER (WHERE destination_kind = 'UNKNOWN DESTINATION'::text) AS unknown_destination,
    round(sum(metrc_declared) FILTER (WHERE destination_kind = 'SALE'::text), 2) AS metrc_declared,
    round(sum(apex_value) FILTER (WHERE destination_kind = 'SALE'::text), 2) AS apex_value,
    round(sum(value_gap) FILTER (WHERE destination_kind = 'SALE'::text), 2) AS net_gap,
    round(100.0 * count(*) FILTER (WHERE status = 'RECONCILED'::text)::numeric / NULLIF(count(*) FILTER (WHERE destination_kind = 'SALE'::text AND metrc_date >= '2025-01-30'::date), 0)::numeric, 1) AS pct_reconciled
   FROM v_manifest_reconciliation
  GROUP BY (to_char(date_trunc('month'::text, metrc_date::timestamp with time zone), 'YYYY-MM'::text));
create or replace view public.v_master_balance as
 WITH grown AS (
         SELECT EXTRACT(year FROM metrc_rpt_harvest_moisture.finished_on)::integer AS period,
            round(sum(metrc_rpt_harvest_moisture.wet_lb), 1) AS wet_lb,
            round(sum(metrc_rpt_harvest_moisture.waste_lb), 1) AS waste_lb,
            round(sum(metrc_rpt_harvest_moisture.moisture_loss_lb), 1) AS moisture_lb,
            round(sum(metrc_rpt_harvest_moisture.packaged_lb), 1) AS packaged_lb,
            round(sum(metrc_rpt_harvest_moisture.wet_lb) - sum(metrc_rpt_harvest_moisture.waste_lb) - sum(metrc_rpt_harvest_moisture.moisture_loss_lb) - sum(metrc_rpt_harvest_moisture.packaged_lb), 4) AS unexplained_lb
           FROM metrc_rpt_harvest_moisture
          GROUP BY (EXTRACT(year FROM metrc_rpt_harvest_moisture.finished_on)::integer)
        ), bought AS (
         SELECT v_material_sourcing.yr AS period,
            round(sum(v_material_sourcing.lb_received), 1) AS bought_lb
           FROM v_material_sourcing
          WHERE v_material_sourcing.ownership ~~ 'THIRD PARTY%'::text
          GROUP BY v_material_sourcing.yr
        ), moved AS (
         SELECT EXTRACT(year FROM t_1.received_on)::integer AS period,
            round(sum(t_1.shipped_lb) FILTER (WHERE t_1.destination_licence !~* '^(MT|IL)'::text AND NOT f_is_ours(COALESCE(t_1.destination_licence, ''::text))), 1) AS arms_length_lb,
            round(sum(t_1.shipped_lb) FILTER (WHERE t_1.destination_licence ~* '^MT'::text), 1) AS to_warehouse_lb,
            round(sum(t_1.shipped_lb) FILTER (WHERE t_1.destination_licence ~* '^IL'::text), 1) AS to_lab_lb,
            round(sum(t_1.shipped_lb) FILTER (WHERE f_is_ours(COALESCE(t_1.destination_licence, ''::text))), 1) AS internal_lb,
            count(DISTINCT t_1.manifest_number) FILTER (WHERE t_1.destination_licence !~* '^(MT|IL)'::text AND NOT f_is_ours(COALESCE(t_1.destination_licence, ''::text))) AS arms_length_manifests,
            count(DISTINCT t_1.manifest_number) FILTER (WHERE f_is_ours(COALESCE(t_1.destination_licence, ''::text))) AS internal_manifests,
            count(DISTINCT t_1.manifest_number) FILTER (WHERE t_1.destination_licence ~* '^IL'::text) AS lab_manifests,
            count(DISTINCT t_1.manifest_number) AS all_manifests,
            count(*) AS all_lines,
            count(*) FILTER (WHERE NOT (EXISTS ( SELECT 1
                   FROM metrc_rpt_transfer_manifests m_1
                  WHERE m_1.manifest_number = t_1.manifest_number))) AS lines_without_a_header
           FROM metrc_rpt_package_transfers t_1
          GROUP BY (EXTRACT(year FROM t_1.received_on)::integer)
        ), lost AS (
         SELECT z.period,
            round(sum(z.lb), 1) AS destroyed_lb
           FROM ( SELECT EXTRACT(year FROM metrc_rpt_adjustments.adjusted_on)::integer AS period,
                    abs(f_to_pounds(metrc_rpt_adjustments.quantity, metrc_rpt_adjustments.uom)) AS lb
                   FROM metrc_rpt_adjustments
                  WHERE metrc_rpt_adjustments.quantity < 0::numeric
                UNION ALL
                 SELECT EXTRACT(year FROM metrc_rpt_plant_waste.waste_date)::integer AS "extract",
                    f_to_pounds(metrc_rpt_plant_waste.waste_qty, metrc_rpt_plant_waste.uom) AS f_to_pounds
                   FROM metrc_rpt_plant_waste) z
          GROUP BY z.period
        ), sold AS (
         SELECT EXTRACT(year FROM COALESCE((apex_raw.payload ->> 'order_date'::text)::date, (apex_raw.payload ->> 'created_at'::text)::date))::integer AS period,
            count(*) FILTER (WHERE NOT ((apex_raw.payload ->> 'cancelled'::text)::boolean)) AS live_orders,
            count(*) FILTER (WHERE (apex_raw.payload ->> 'cancelled'::text)::boolean) AS cancelled_orders,
            round(sum(COALESCE((apex_raw.payload ->> 'total_raw'::text)::numeric, 0::numeric) / 100.0) FILTER (WHERE NOT ((apex_raw.payload ->> 'cancelled'::text)::boolean)), 2) AS revenue_usd,
            round(sum(COALESCE((apex_raw.payload ->> 'total_payments_raw'::text)::numeric, 0::numeric) / 100.0) FILTER (WHERE NOT ((apex_raw.payload ->> 'cancelled'::text)::boolean)), 2) AS collected_usd
           FROM apex_raw
          WHERE apex_raw.entity = 'shipping-orders'::text
          GROUP BY (EXTRACT(year FROM COALESCE((apex_raw.payload ->> 'order_date'::text)::date, (apex_raw.payload ->> 'created_at'::text)::date))::integer)
        ), tagged AS (
         SELECT EXTRACT(year FROM COALESCE((a.payload ->> 'order_date'::text)::date, (a.payload ->> 'created_at'::text)::date))::integer AS period,
            count(*) AS apex_lines,
            count(NULLIF(btrim(it.value ->> 'metrc_package_label'::text), ''::text)) AS lines_with_metrc_tag
           FROM apex_raw a,
            LATERAL jsonb_array_elements(a.payload -> 'items'::text) it(value)
          WHERE a.entity = 'shipping-orders'::text AND NOT ((a.payload ->> 'cancelled'::text)::boolean)
          GROUP BY (EXTRACT(year FROM COALESCE((a.payload ->> 'order_date'::text)::date, (a.payload ->> 'created_at'::text)::date))::integer)
        )
 SELECT g.period,
    g.wet_lb,
    g.waste_lb,
    g.moisture_lb,
    g.packaged_lb,
    g.unexplained_lb AS metrc_mass_unexplained_lb,
    m.arms_length_manifests,
    m.internal_manifests,
    m.lab_manifests,
    s.live_orders,
    s.revenue_usd,
    s.collected_usd,
    round(COALESCE(s.revenue_usd, 0::numeric) - COALESCE(s.collected_usd, 0::numeric), 2) AS outstanding_usd,
    s.cancelled_orders,
    t.apex_lines,
    t.lines_with_metrc_tag,
        CASE
            WHEN COALESCE(g.unexplained_lb, 0::numeric) = 0::numeric THEN 'MASS BALANCED — 0.0000 lb'::text
            ELSE ('MASS UNBALANCED — '::text || g.unexplained_lb) || ' lb'::text
        END AS mass_verdict,
        CASE
            WHEN (COALESCE(s.revenue_usd, 0::numeric) - COALESCE(s.collected_usd, 0::numeric)) = 0::numeric THEN 'CASH BALANCED — nothing outstanding'::text
            ELSE 'OUTSTANDING $'::text || round(COALESCE(s.revenue_usd, 0::numeric) - COALESCE(s.collected_usd, 0::numeric), 2)
        END AS cash_verdict,
        CASE
            WHEN COALESCE(t.lines_with_metrc_tag, 0::bigint) = 0 THEN (('NO TAG LINK — 0 of '::text || COALESCE(t.apex_lines, 0::bigint)) || ' Apex lines carry a Metrc tag. '::text) || 'Rebuilt on buyer licence + date instead; see v_invoice_manifest_match.'::text
            ELSE round(100.0 * t.lines_with_metrc_tag::numeric / NULLIF(t.apex_lines, 0)::numeric, 1) || '% of Apex lines carry a Metrc tag'::text
        END AS link_verdict,
    b.bought_lb,
    m.arms_length_lb,
    m.to_warehouse_lb,
    m.to_lab_lb,
    m.internal_lb,
    l.destroyed_lb,
    m.all_manifests,
    m.all_lines,
    m.lines_without_a_header
   FROM grown g
     LEFT JOIN bought b ON b.period = g.period
     LEFT JOIN moved m ON m.period = g.period
     LEFT JOIN lost l ON l.period = g.period
     LEFT JOIN sold s ON s.period = g.period
     LEFT JOIN tagged t ON t.period = g.period;
create or replace view public.v_matview_health as
 SELECT p.matview,
    COALESCE(f.computed_at, r.last_ok_at) AS computed_at,
    COALESCE(f.age, now() - r.last_ok_at) AS age,
    p.max_age,
    p.refresh_fn,
    f.scheduled_refresh,
    COALESCE(f.age, now() - r.last_ok_at) IS NULL OR COALESCE(f.age, now() - r.last_ok_at) > p.max_age AS is_stale,
    (( SELECT count(*) AS count
           FROM matview_refresh_run x
          WHERE x.matview = p.matview AND x.ok AND x.run_by = 'watcher'::text AND x.started_at > (now() - '24:00:00'::interval)))::integer AS heals_last_24h,
    p.heals_per_day_ok,
    (( SELECT count(*) AS count
           FROM matview_refresh_run x
          WHERE x.matview = p.matview AND NOT x.ok AND x.started_at > (now() - '24:00:00'::interval)))::integer AS failures_last_24h,
        CASE
            WHEN COALESCE(f.age, now() - r.last_ok_at) IS NULL THEN 'NEVER REFRESHED ON RECORD — treated as stale until one succeeds and gives it a clock'::text
            WHEN COALESCE(f.age, now() - r.last_ok_at) > p.max_age THEN 'STALE — older than '::text || p.max_age
            ELSE 'ok'::text
        END AS verdict,
    p.why,
        CASE
            WHEN f.computed_at IS NOT NULL THEN 'the view''s own computed_at'::text
            WHEN r.last_ok_at IS NOT NULL THEN 'last successful refresh in matview_refresh_run'::text
            ELSE 'no clock of any kind yet'::text
        END AS clock_source
   FROM matview_heal_policy p
     LEFT JOIN v_matview_freshness f ON f.matview = p.matview
     LEFT JOIN LATERAL ( SELECT max(x.started_at) AS last_ok_at
           FROM matview_refresh_run x
          WHERE x.matview = p.matview AND x.ok) r ON true
  WHERE p.active;
create or replace view public.v_metrc_harvest_yields as
 WITH h AS (
         SELECT mh.license,
            mh.name AS harvest_name,
            COALESCE(mh.raw ->> 'SourceStrainNames'::text, 'not recorded'::text) AS strain,
            COALESCE(mh.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            mh.harvest_start,
            (mh.raw ->> 'FinishedDate'::text)::date AS finished_on,
            COALESCE((mh.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants,
            COALESCE((mh.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) AS wet_g,
            COALESCE((mh.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) AS waste_g,
            COALESCE((mh.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) AS packaged_g,
            COALESCE((mh.raw ->> 'CurrentWeight'::text)::numeric, 0::numeric) AS current_g,
            mh.raw ->> 'LabTestingState'::text AS lab_state
           FROM metrc_harvests mh
        ), plan AS (
         SELECT p.pull_no,
            p.harvest_date,
            p.flower_room,
            p.cultivars,
            p.original_total_plants AS planned_plants,
            p.proj_harvest_weight_lbs AS planned_lbs
           FROM harvest_pulls p
        )
 SELECT h.harvest_name,
    h.strain,
    h.room,
    h.harvest_start AS takedown_date,
    h.finished_on,
    m.stage AS current_stage,
    m.days_since_takedown,
    pl.pull_no AS planned_pull,
    pl.planned_plants,
    h.plants AS actual_plants,
    round(COALESCE(pl.planned_lbs, 0::numeric), 1) AS projected_lbs,
    round(h.wet_g / 453.592, 1) AS actual_wet_lbs,
    round(h.packaged_g / 453.592, 1) AS actual_packaged_lbs,
        CASE
            WHEN COALESCE(pl.planned_lbs, 0::numeric) > 0::numeric THEN round(100.0 * (h.packaged_g / 453.592) / pl.planned_lbs, 1)
            ELSE NULL::numeric
        END AS pct_of_projection,
        CASE
            WHEN COALESCE(pl.planned_lbs, 0::numeric) > 0::numeric THEN round(h.packaged_g / 453.592 - pl.planned_lbs, 1)
            ELSE NULL::numeric
        END AS variance_lbs,
    round(h.waste_g / 453.592, 1) AS waste_lbs,
        CASE
            WHEN h.wet_g > 0::numeric THEN round(100.0 * h.waste_g / h.wet_g, 1)
            ELSE NULL::numeric
        END AS waste_pct,
        CASE
            WHEN h.wet_g > 0::numeric THEN round(100.0 * h.packaged_g / h.wet_g, 1)
            ELSE NULL::numeric
        END AS yield_pct,
    ( SELECT count(*) AS count
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AS allocation_requests,
    ( SELECT string_agg(DISTINCT a.requester_name, ', '::text) AS string_agg
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AS requested_by,
    ( SELECT string_agg(DISTINCT a.decider_name, ', '::text) AS string_agg
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS approved_by,
    ( SELECT round(sum(COALESCE(a.approved_quantity, a.quantity)), 1) AS round
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS allocated_quantity,
    ( SELECT string_agg(DISTINCT a.destination, ', '::text) AS string_agg
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS allocated_to,
    ( SELECT string_agg(DISTINCT a.purpose, ' · '::text) AS string_agg
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS allocated_for,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text)) AS packages_made,
    ( SELECT string_agg(DISTINCT NULLIF(p.raw ->> 'ProductCategoryName'::text, ''::text), ', '::text) AS string_agg
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text)) AS manufactured_into,
    ( SELECT round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS round
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS still_on_hand,
    ( SELECT string_agg(DISTINCT p.location, ', '::text) AS string_agg
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS sitting_in,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND p.lab_testing_state = 'TestPassed'::text) AS passed_testing,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND p.source_state = 'intransit'::text) AS shipped_out,
    h.lab_state,
    h.license
   FROM h
     LEFT JOIN v_harvest_stage_map m ON m.harvest = h.harvest_name
     LEFT JOIN plan pl ON pl.flower_room = h.room AND h.harvest_start >= (pl.harvest_date - 4) AND h.harvest_start <= (pl.harvest_date + 10)
  ORDER BY h.harvest_start DESC NULLS LAST;
create or replace view public.v_moisture_summary as
 SELECT stream,
    count(*) AS harvests,
    round(sum(wet_lb), 1) AS wet_lb,
    round(sum(packaged_lb), 1) AS packaged_lb,
    round(sum(recorded_waste_lb), 1) AS waste_lb,
    round(sum(moisture_lb), 1) AS evaporated_lb,
    round(sum(metrc_current_weight_lb), 1) AS metrc_says_lb,
    round(sum(reconciliation_gap_lb), 1) AS gap_lb,
    round(100::numeric * sum(moisture_lb) / NULLIF(sum(wet_lb), 0::numeric), 1) AS moisture_pct,
    round(100::numeric * sum(packaged_lb) / NULLIF(sum(wet_lb), 0::numeric), 1) AS conversion_pct,
    'Every pound of wet weight ends up in exactly one of three places: packaged product, recorded waste, or water that evaporated. This proves the three add back.'::text AS what_this_proves
   FROM v_moisture_accounting
  WHERE finished IS NOT NULL
  GROUP BY stream;
create or replace view public.v_own_vs_bought as
 SELECT stream,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric), 1) AS grown_lb,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Bought in'::text), 0::numeric), 1) AS bought_lb,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Origin not recorded'::text), 0::numeric), 1) AS unknown_origin_lb,
    round(sum(pounds), 1) AS total_lb,
    round(100::numeric * COALESCE(sum(pounds) FILTER (WHERE origin = 'Bought in'::text), 0::numeric) / NULLIF(sum(pounds), 0::numeric), 1) AS pct_bought_in
   FROM v_stock_on_hand
  GROUP BY stream
  ORDER BY (round(sum(pounds), 1)) DESC;
create or replace view public.v_package_event_class as
 SELECT e.package_tag,
    e.event_date,
    e.event,
    e.lb_delta,
    e.licence,
    e.room,
    e.counterparty,
        CASE
            WHEN e.event = 'CREATED'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN 'CREATED_FROM_PACKAGE'::text
            WHEN e.event = 'CREATED'::text AND NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL THEN 'PRODUCED_FROM_HARVEST'::text
            WHEN e.event = 'CREATED'::text THEN 'CREATED_NO_SOURCE'::text
            ELSE e.event
        END AS event_class,
    f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), e.licence)) AS is_ours,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text) AS origin_company,
    COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, ''::text), '(uncategorised)'::text) AS category,
    COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'StrainName'::text, ''::text), f_strain_from_item((p.raw -> 'Item'::text) ->> 'Name'::text)) AS strain,
    f_product_line((p.raw -> 'Item'::text) ->> 'Name'::text, (p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, NULL::text) AS product_line,
    COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) AS pkg_finished,
    COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS current_room
   FROM v_package_events e
     LEFT JOIN metrc_packages p ON (p.raw ->> 'Label'::text) = e.package_tag;
create or replace view public.v_position_by_ownership as
 WITH p AS (
         SELECT mp.tag,
            COALESCE(NULLIF(mp.location, ''::text), '(no location recorded)'::text) AS location,
            mp.license,
            mp.lab_testing_state,
            f_to_pounds(mp.quantity, mp.uom) AS lb,
            f_material_origin(mp.tag) AS g
           FROM metrc_packages mp
          WHERE mp.quantity > 0::numeric
        ), tagged AS (
         SELECT p.tag,
            p.location,
            p.license,
            p.lab_testing_state,
            p.lb,
            p.g,
            jsonb_array_length(COALESCE(p.g -> 'origin_licences'::text, '[]'::jsonb)) AS origins,
                CASE
                    WHEN (p.g ->> 'all_ours'::text)::boolean THEN 'ours'::text
                    WHEN ((p.g ->> 'any_outside'::text)::boolean) AND jsonb_array_length(COALESCE(p.g -> 'origin_licences'::text, '[]'::jsonb)) <= 1 THEN 'third_party'::text
                    WHEN (p.g ->> 'any_outside'::text)::boolean THEN 'blended'::text
                    ELSE 'unresolved'::text
                END AS side
           FROM p
        ), s AS (
         SELECT COALESCE(soh.stream, 'not classified'::text) AS stream,
            soh.license,
            soh.lab_state
           FROM v_stock_on_hand soh
         LIMIT 0
        )
 SELECT license,
    COALESCE(lab_testing_state, 'no test state recorded'::text) AS lab_state,
    location,
    round(sum(lb) FILTER (WHERE side = 'ours'::text), 1) AS ours_lb,
    round(sum(lb) FILTER (WHERE side = 'third_party'::text), 1) AS third_party_lb,
    round(sum(lb) FILTER (WHERE side = 'blended'::text), 1) AS blended_lb,
    round(sum(lb) FILTER (WHERE side = 'unresolved'::text), 1) AS unresolved_lb,
    round(sum(lb), 1) AS collectively_lb,
    count(*) FILTER (WHERE side = 'ours'::text) AS ours_packages,
    count(*) FILTER (WHERE side = 'third_party'::text) AS third_party_packages,
    count(*) FILTER (WHERE side = 'blended'::text) AS blended_packages,
    count(*) FILTER (WHERE side = 'unresolved'::text) AS unresolved_packages,
    count(*) AS collectively_packages,
    round(100.0 * sum(lb) FILTER (WHERE side = 'third_party'::text) / NULLIF(sum(lb), 0::numeric), 1) AS pct_third_party,
        CASE
            WHEN sum(lb) FILTER (WHERE side = ANY (ARRAY['blended'::text, 'unresolved'::text])) > 0::numeric THEN ((round(sum(lb) FILTER (WHERE side = ANY (ARRAY['blended'::text, 'unresolved'::text])), 1) || ' lb cannot be attributed to either side — blended from several origins with no '::text) || 'record of the proportions. ours + third party will NOT equal collectively, and '::text) || 'making them balance would require inventing the split.'::text
            ELSE NULL::text
        END AS why_it_does_not_add_up
   FROM tagged t
  GROUP BY license, (COALESCE(lab_testing_state, 'no test state recorded'::text)), location;
create or replace view public.v_potency_by_strain as
 SELECT strain,
    product_line,
    yr,
    count(*) AS tests,
    count(DISTINCT package_tag) AS tags,
    count(DISTINCT month) AS months_tested,
    round(avg(pct), 2) AS mean_pct,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (pct::double precision))::numeric, 2) AS median_pct,
    round(min(pct), 2) AS min_pct,
    round(max(pct), 2) AS max_pct,
    round(stddev_samp(pct), 2) AS consistency_sd,
    max(target_min) AS target_min,
    count(*) FILTER (WHERE hits_target) AS at_or_above_target,
        CASE
            WHEN max(target_min) IS NULL THEN NULL::numeric
            ELSE round(100.0 * count(*) FILTER (WHERE hits_target)::numeric / count(*)::numeric, 1)
        END AS pct_hitting_target,
    min(test_date) AS first_tested,
    max(test_date) AS last_tested
   FROM v_potency_results
  WHERE strain IS NOT NULL
  GROUP BY strain, product_line, yr;
create or replace view public.v_potency_tac as
 WITH a AS (
         SELECT v_potency_analytes.package_tag,
            v_potency_analytes.item,
            v_potency_analytes.strain,
            v_potency_analytes.product_line,
            v_potency_analytes.licence,
            v_potency_analytes.lab,
            v_potency_analytes.test_date,
            v_potency_analytes.yr,
            v_potency_analytes.month,
            v_potency_analytes.quarter,
            v_potency_analytes.analyte,
            v_potency_analytes.pct
           FROM v_potency_analytes
        )
 SELECT package_tag,
    item,
    strain,
    product_line,
    licence,
    lab,
    test_date,
    yr,
    month,
    quarter,
    max(pct) FILTER (WHERE analyte = 'TOTAL THC'::text) AS total_thc,
    max(pct) FILTER (WHERE analyte = 'TOTAL CBD'::text) AS total_cbd,
    max(pct) FILTER (WHERE analyte = 'THCA'::text) AS thca,
    max(pct) FILTER (WHERE analyte = 'CBG'::text) AS cbg,
    max(pct) FILTER (WHERE analyte = 'CBN'::text) AS cbn,
    max(pct) FILTER (WHERE analyte = 'CBC'::text) AS cbc,
    max(pct) FILTER (WHERE analyte = 'THCV'::text) AS thcv,
    round(COALESCE(max(pct) FILTER (WHERE analyte = 'TOTAL THC'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'TOTAL CBD'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBG'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBN'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBC'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'THCV'::text), 0::numeric), 3) AS tac_computed,
    count(*) AS analytes_reported,
    max(pct) FILTER (WHERE analyte = 'THC'::text) AS thc_delta9,
    max(pct) FILTER (WHERE analyte = 'CBDA'::text) AS cbda,
    max(pct) FILTER (WHERE analyte = 'CBD'::text) AS cbd,
    max(pct) FILTER (WHERE analyte = 'CBGA'::text) AS cbga,
    round(COALESCE(max(pct) FILTER (WHERE analyte = 'TOTAL THC'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'TOTAL CBD'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBG'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBN'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBC'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'THCV'::text), 0::numeric), 3) AS tac_decarb,
    round(COALESCE(max(pct) FILTER (WHERE analyte = 'THCA'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'THC'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBDA'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBD'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBGA'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBG'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBN'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'CBC'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'THCV'::text), 0::numeric) + COALESCE(max(pct) FILTER (WHERE analyte = 'THCVA'::text), 0::numeric), 3) AS tac_asis,
    'COMPUTED — Metrc carries no TAC line. Confirm against the laboratory PDF which convention it prints.'::text AS tac_note
   FROM a
  GROUP BY package_tag, item, strain, product_line, licence, lab, test_date, yr, month, quarter;
create or replace view public.v_potency_vs_target as
 SELECT product_line AS category,
    'Total THC'::text AS analyte,
    yr,
    COALESCE(max(target_status), 'not registered'::text) AS target_status,
    max(target_min) AS target_min,
    max(target_set_by) AS target_set_by,
    count(*) AS tests,
    count(DISTINCT strain) AS strains,
    round(avg(pct), 2) AS mean_pct,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (pct::double precision))::numeric, 2) AS median_pct,
    round(min(pct), 2) AS min_pct,
    round(max(pct), 2) AS max_pct,
    count(*) FILTER (WHERE hits_target) AS at_or_above_target,
        CASE
            WHEN max(target_min) IS NULL THEN NULL::numeric
            ELSE round(100.0 * count(*) FILTER (WHERE hits_target)::numeric / count(*)::numeric, 1)
        END AS pct_hitting_target,
        CASE
            WHEN max(target_min) IS NULL THEN 'NO TARGET SET — '::text || COALESCE(max(target_status), 'category not registered'::text)
            ELSE (('target '::text || max(target_min)) || '% set by '::text) || COALESCE(max(target_set_by), '?'::text)
        END AS verdict
   FROM v_potency_results
  GROUP BY product_line, 'Total THC'::text, yr;
create or replace view public.v_production_true_position as
 WITH f AS (
         SELECT conversion_factors.value AS r
           FROM conversion_factors
          WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
        ), o AS (
         SELECT v_stock_on_hand.origin,
            v_stock_on_hand.stream,
            sum(v_stock_on_hand.pounds) AS lb
           FROM v_stock_on_hand
          GROUP BY v_stock_on_hand.origin, v_stock_on_hand.stream
        )
 SELECT origin,
    stream,
    round(lb, 1) AS as_recorded_lb,
        CASE
            WHEN stream = 'Fresh frozen'::text THEN round(lb / (( SELECT f.r
               FROM f)), 1)
            ELSE round(lb, 1)
        END AS dry_equivalent_lb,
        CASE
            WHEN stream = 'Fresh frozen'::text THEN ('Divided by '::text || (( SELECT f.r
               FROM f))) || ' - frozen material still holds its water'::text
            ELSE 'Already dry - no conversion needed'::text
        END AS adjustment,
    round(100::numeric *
        CASE
            WHEN stream = 'Fresh frozen'::text THEN lb / (( SELECT f.r
               FROM f))
            ELSE lb
        END / sum(
        CASE
            WHEN stream = 'Fresh frozen'::text THEN lb / (( SELECT f.r
               FROM f))
            ELSE lb
        END) OVER (), 1) AS pct_of_true_production
   FROM o
  ORDER BY (
        CASE
            WHEN stream = 'Fresh frozen'::text THEN round(lb / (( SELECT f.r
               FROM f)), 1)
            ELSE round(lb, 1)
        END) DESC;
create or replace view public.v_pull_yield as
 WITH linked AS (
         SELECT v_harvest_pull_link.harvest_id,
            v_harvest_pull_link.harvest_name,
            v_harvest_pull_link.takedown_date,
            v_harvest_pull_link.room_actual,
            v_harvest_pull_link.room_planned,
            v_harvest_pull_link.is_fresh_frozen,
            v_harvest_pull_link.pull_no,
            v_harvest_pull_link.pull_planned_date,
            v_harvest_pull_link.days_from_planned_pull,
            v_harvest_pull_link.planned_plants,
            v_harvest_pull_link.projected_flower_after_ff_lb,
            v_harvest_pull_link.wet_weight,
            v_harvest_pull_link.package_count,
            v_harvest_pull_link.link_note,
            v_harvest_pull_link.name_date_disagreement
           FROM v_harvest_pull_link
          WHERE v_harvest_pull_link.pull_no IS NOT NULL
        ), pkg_single AS (
         SELECT l.pull_no,
            l.is_fresh_frozen,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text) AS created_lb
           FROM linked l
             JOIN metrc_packages p ON (p.raw ->> 'SourceHarvestNames'::text) = l.harvest_name AND COALESCE((p.raw ->> 'SourceHarvestCount'::text)::integer, 1) = 1
        ), pkg_multi AS (
         SELECT DISTINCT l.pull_no,
            p.id AS package_id,
            f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text) AS created_lb
           FROM metrc_packages p
             CROSS JOIN LATERAL unnest(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ', '::text)) hn(harvest_name)
             JOIN linked l ON l.harvest_name = btrim(hn.harvest_name)
          WHERE COALESCE((p.raw ->> 'SourceHarvestCount'::text)::integer, 1) > 1
        ), agg AS (
         SELECT pkg_single.pull_no,
            sum(pkg_single.created_lb) FILTER (WHERE NOT pkg_single.is_fresh_frozen AND pkg_single.category ~~* '%bud%'::text) AS dried_bud_lb,
            sum(pkg_single.created_lb) FILTER (WHERE NOT pkg_single.is_fresh_frozen AND (pkg_single.category ~~* '%shake%'::text OR pkg_single.category ~~* '%trim%'::text)) AS shake_trim_lb,
            sum(pkg_single.created_lb) FILTER (WHERE pkg_single.is_fresh_frozen) AS fresh_frozen_lb
           FROM pkg_single
          GROUP BY pkg_single.pull_no
        ), multi AS (
         SELECT pkg_multi.pull_no,
            sum(pkg_multi.created_lb) AS multi_lb,
            count(*) AS multi_packages
           FROM pkg_multi
          GROUP BY pkg_multi.pull_no
        ), h AS (
         SELECT linked.pull_no,
            count(*) AS harvests,
            count(*) FILTER (WHERE linked.is_fresh_frozen) AS fresh_frozen_harvests,
            string_agg(DISTINCT linked.room_actual, '/'::text ORDER BY linked.room_actual) AS rooms_actual,
            bool_or(linked.room_actual IS DISTINCT FROM linked.room_planned) AS room_drifted,
            sum(linked.wet_weight) / 453.592 AS wet_lb
           FROM linked
          GROUP BY linked.pull_no
        )
 SELECT pl.pull_no,
    pl.harvest_date AS pull_planned_date,
    pl.flower_room AS room_planned,
    h.rooms_actual,
    h.room_drifted,
    pl.planned_plants,
    h.harvests,
    h.fresh_frozen_harvests,
    round(h.wet_lb, 1) AS wet_lb,
    round(a.dried_bud_lb, 1) AS dried_bud_lb,
    round(a.shake_trim_lb, 1) AS shake_trim_lb,
    round(a.fresh_frozen_lb, 1) AS fresh_frozen_lb,
    round(m.multi_lb, 1) AS multi_harvest_lb_unallocated,
    m.multi_packages AS multi_harvest_packages,
    round(pl.projected_flower_after_ff_lb, 1) AS plan_dried_lb,
    f_rule('pull_target_dried_lb'::text) AS owner_target_dried_lb,
    round(a.dried_bud_lb - pl.projected_flower_after_ff_lb, 1) AS vs_plan_lb,
    round(a.dried_bud_lb - f_rule('pull_target_dried_lb'::text), 1) AS vs_owner_target_lb,
        CASE
            WHEN h.harvests IS NULL THEN 'NO HARVESTS LINKED to this pull. Either it has not happened yet, or it happened and was not recorded in Metrc. If the date has passed, this is urgent.'::text
            WHEN a.dried_bud_lb IS NULL AND h.fresh_frozen_harvests = h.harvests THEN 'No dried flower - every harvest in this pull was taken as fresh frozen, which is packaged wet and must never be added to a dried figure.'::text
            WHEN a.dried_bud_lb IS NULL THEN 'No dried flower packaged yet. Harvest to availability runs about 28 days, so a recent pull reads empty until curing finishes.'::text
            WHEN m.multi_lb > 0::numeric THEN ((('FLOOR, not a total. A further '::text || m.multi_packages) || ' package(s) holding '::text) || round(m.multi_lb, 1)) || ' lb draw on this pull AND others, and are NOT included - splitting them across pulls is an owner decision not yet made. They are listed against every pull they touch, so they must never simply be added.'::text
            ELSE 'Complete for single-harvest packages. No multi-harvest packages touch this pull.'::text
        END AS completeness_note
   FROM harvest_plan_2026 pl
     LEFT JOIN h ON h.pull_no = pl.pull_no
     LEFT JOIN agg a ON a.pull_no = pl.pull_no
     LEFT JOIN multi m ON m.pull_no = pl.pull_no
  ORDER BY pl.pull_no;
create or replace view public.v_real_loss_summary as
 SELECT loss_type,
    count(*)::numeric AS occurrences,
    round(sum(COALESCE(units, 0::numeric)), 0) AS units,
    round(sum(COALESCE(pounds, 0::numeric)), 1) AS pounds_affected,
    round(sum(COALESCE(pounds, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_at_target_cost,
    max(why_it_is_a_loss) AS why_it_is_a_loss
   FROM v_real_loss
  GROUP BY loss_type
  ORDER BY (round(sum(COALESCE(pounds, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_reconciliation_status as
 WITH facts AS (
         SELECT v_cross_source_reconciliation.fact,
            v_cross_source_reconciliation.unit,
            COALESCE(abs(v_cross_source_reconciliation.value_difference), 0::numeric) AS difference,
            COALESCE(v_cross_source_reconciliation.value_not_covered, 0::numeric) AS not_covered,
            v_cross_source_reconciliation.verdict
           FROM v_cross_source_reconciliation
        ), explained AS (
         SELECT reconciliation_exception.fact,
            sum(COALESCE(reconciliation_exception.amount, 0::numeric)) AS explained_amount,
            count(*) AS exceptions
           FROM reconciliation_exception
          WHERE reconciliation_exception.resolved_on IS NULL
          GROUP BY reconciliation_exception.fact
        )
 SELECT f.fact,
    f.unit,
    f.difference,
    COALESCE(e.explained_amount, 0::numeric) AS explained,
    f.difference - COALESCE(e.explained_amount, 0::numeric) AS unexplained,
    COALESCE(e.exceptions, 0::bigint) AS open_exceptions,
        CASE
            WHEN f.difference = 0::numeric AND f.not_covered = 0::numeric THEN 'BALANCES'::text
            WHEN (f.difference - COALESCE(e.explained_amount, 0::numeric)) = 0::numeric THEN 'balances once explained'::text
            ELSE 'UNEXPLAINED DIFFERENCE - this is the one that matters'::text
        END AS status
   FROM facts f
     LEFT JOIN explained e USING (fact)
  ORDER BY (f.difference - COALESCE(e.explained_amount, 0::numeric)) DESC, f.fact;
create or replace view public.v_reconciliation_unresolved as
 SELECT manifest_number,
    licence,
    created_on,
    wholesale_value,
    package_as_of,
    ('Raised on the same day the package export was pulled. An as-of date cannot '::text || 'resolve time of day, so this cannot be judged either way. It resolves itself '::text) || 'on the next package export.'::text AS why
   FROM v_wholesale_reconciliation
  WHERE reading = 'In the wholesale report only'::text AND COALESCE(wholesale_value, 0::numeric) > 0::numeric AND created_on = (( SELECT max(metrc_rpt_package_transfers.as_of_date) AS max
           FROM metrc_rpt_package_transfers));
create or replace view public.v_report_standard as
 SELECT w.view_key,
    w.label,
    w.category,
    w.page_kind,
    w.table_ref,
    w.object_kind,
    w.fields,
    w.date_columns,
    w.roles_who_can_see,
    w.in_report_registry,
    w.page_kind = 'report'::text AS needs_toolbar,
    w.date_columns > 0 AS can_filter_by_date,
    w.fields >= 3 AS worth_filtering,
    w.roles_who_can_see > 0 AS someone_can_open_it,
    w.claims_proving_it > 0 AS figure_is_proven,
        CASE
            WHEN w.page_kind = 'application'::text THEN 'EXEMPT - hand-built screen, no report toolbar'::text
            WHEN w.roles_who_can_see = 0 THEN 'FAILS - nobody can open it'::text
            WHEN n.date_policy = 'not_applicable'::text THEN 'MEETS THE STANDARD - date control OMITTED, a date is meaningless here'::text
            WHEN w.date_columns = 0 THEN 'DEFECT - the source carries a date and this view drops it. Fix the view, do NOT omit the control'::text
            WHEN w.fields < 3 THEN 'THIN - too few fields to be worth filtering'::text
            ELSE 'MEETS THE STANDARD'::text
        END AS standard,
    'THE STANDARD: every report page carries the SAME toolbar - the 27-preset date range with editable From/To, global search, per-column filters, sort, column chooser, group-by with subtotals, export to PDF/CSV/Excel/Sheets carrying the active filters, drill to the raw Metrc record, and owner_note displayed. Same position, same wording, same shortcuts.'::text AS what_good_looks_like,
    'OWNER RULING: where a date is genuinely meaningless, OMIT the control - do not grey it out. Where the source HAS a date the view dropped, that is a defect: fix the view. Never omit to hide a missing date.'::text AS what_to_do,
    n.date_policy
   FROM v_page_wiring w
     JOIN nav_registry n ON n.view_key = w.view_key;
create or replace view public.v_report_upload_alerts as
 SELECT d.report_key,
    d.title,
    d.licence,
    d.period_label,
    d.due_by,
    d.days_late,
    d.severity,
    d.upload_status,
    d.cadence,
    d.menu_path,
    d.why_it_matters,
    u.user_id,
    COALESCE(u.display_name, u.role::text) AS recipient,
    u.role::text AS role,
    r.notify_in_app,
    r.notify_email,
    (((('Metrc report not uploaded: '::text || d.title) || ' ('::text) || d.licence) || ') for '::text) || d.period_label AS subject,
    (((((((((((d.title || ' for '::text) || d.period_label) || ' on licence '::text) || d.licence) || ' has not been uploaded. '::text) || d.upload_status) || '. '::text) || d.why_it_matters) || '  Export it from Metrc at: '::text) || d.menu_path) || '  then upload it on Settings > Metrc Report Imports. No mapping is needed'::text) || ' - the file is identified automatically from its columns.'::text AS body
   FROM v_report_upload_due d
     JOIN report_alert_recipients r ON true
     JOIN app_users u ON u.role::text = r.role
  WHERE NOT d.received AND (r.min_severity = 'due'::text OR r.min_severity = 'elevated'::text AND (d.severity = ANY (ARRAY['elevated'::text, 'critical'::text])) OR r.min_severity = 'critical'::text AND d.severity = 'critical'::text);
create or replace view public.v_room_best_vs_worst as
 SELECT room,
    max(conversion_pct) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_conversion,
    max(month) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_month,
    max(grams_per_plant) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_grams_per_plant,
    max(dry_days) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_dry_days,
    min(conversion_pct) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_conversion,
    max(month) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_month,
    max(grams_per_plant) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_grams_per_plant,
    max(dry_days) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_dry_days,
    round(max(conversion_pct) FILTER (WHERE standing = 'BEST MONTH for this room'::text) - min(conversion_pct) FILTER (WHERE standing = 'WORST MONTH for this room'::text), 1) AS spread_points,
    round(sum(dollars_lost_versus_room_best), 0) AS total_dollars_lost_versus_own_best,
    ('This room is capable of '::text || max(conversion_pct) FILTER (WHERE standing = 'BEST MONTH for this room'::text)) || ' percent - it has already done it. Everything below that is practice, not capacity.'::text AS what_this_means
   FROM v_room_month_comparison
  GROUP BY room
  ORDER BY (round(sum(dollars_lost_versus_room_best), 0)) DESC NULLS LAST;
create or replace view public.v_room_board as
 SELECT gr.code AS room,
    'Flower room'::text AS room_type,
    (( SELECT count(*) AS count
           FROM metrc_plants p
          WHERE p.room ~~* (('%'::text || replace(gr.code, 'F'::text, 'Flower Room #'::text)) || '%'::text) AND (p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))))::numeric AS plants_now,
    ( SELECT string_agg(DISTINCT p.strain, ', '::text) AS string_agg
           FROM metrc_plants p
          WHERE p.room ~~* (('%'::text || replace(gr.code, 'F'::text, 'Flower Room #'::text)) || '%'::text) AND (p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))) AS strains_now,
    NULL::numeric AS weight_on_hand,
    ( SELECT min(hp.harvest_date) AS min
           FROM harvest_pulls hp
          WHERE hp.flower_room = gr.code AND hp.harvest_date >= CURRENT_DATE) AS next_event_date,
    'Next scheduled pull'::text AS next_event,
    (( SELECT hp.harvest_date - CURRENT_DATE
           FROM harvest_pulls hp
          WHERE hp.flower_room = gr.code AND hp.harvest_date >= CURRENT_DATE
          ORDER BY hp.harvest_date
         LIMIT 1))::numeric AS days_until,
    ( SELECT hp.cultivars
           FROM harvest_pulls hp
          WHERE hp.flower_room = gr.code AND hp.harvest_date >= CURRENT_DATE
          ORDER BY hp.harvest_date
         LIMIT 1) AS next_event_detail,
    gr.plant_capacity,
    gr.cycle_days
   FROM grow_rooms gr
  WHERE gr.active
UNION ALL
 SELECT m.room,
    'Post-harvest room'::text AS room_type,
    sum(m.plants) AS plants_now,
    string_agg(DISTINCT m.strains, ', '::text) AS strains_now,
    round(sum(COALESCE(m.current_weight, m.wet_weight, 0::numeric)), 1) AS weight_on_hand,
    min(m.harvest_start + 14) AS next_event_date,
    'Dry deadline (day 14)'::text AS next_event,
    min(m.harvest_start + 14 - CURRENT_DATE)::numeric AS days_until,
    string_agg(DISTINCT m.stage, ' · '::text) AS next_event_detail,
    NULL::integer AS plant_capacity,
    NULL::integer AS cycle_days
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND COALESCE(m.room, ''::text) <> ''::text
  GROUP BY m.room;
create or replace view public.v_room_position_over_time as
 SELECT room,
    licence,
    record_type,
    count(*) FILTER (WHERE observed_on = '2025-01-01'::date) AS at_2024_year_end,
    count(*) FILTER (WHERE observed_on = '2026-08-06'::date) AS at_2026_08_06,
    count(*) FILTER (WHERE observation = 'current'::text) AS now,
    count(DISTINCT observed_on) AS dates_observed
   FROM v_room_history
  WHERE observation = ANY (ARRAY['snapshot'::text, 'current'::text])
  GROUP BY room, licence, record_type;
create or replace view public.v_sales_history_monthly as
 SELECT licence AS license,
    f_operation(licence) AS operation,
    to_char(created_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
    date_trunc('month'::text, created_on::timestamp with time zone)::date AS month_date,
    count(*) FILTER (WHERE is_customer_sale)::numeric AS manifests_sent,
    count(DISTINCT recipient) FILTER (WHERE is_customer_sale)::numeric AS customers,
    sum(COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric)) FILTER (WHERE is_customer_sale) AS packages_sold,
    sum(COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric)) FILTER (WHERE is_customer_sale) AS packages_confirmed,
    count(*) FILTER (WHERE is_customer_sale AND (raw ->> 'ReceivedDateTime'::text) IS NULL)::numeric AS manifests_unconfirmed,
    count(*) FILTER (WHERE movement = 'Internal move'::text)::numeric AS internal_moves,
    count(*) FILTER (WHERE movement = 'Laboratory sample'::text)::numeric AS lab_samples,
    count(*) FILTER (WHERE is_inbound_purchase)::numeric AS bought_in,
    string_agg(DISTINCT recipient, ', '::text) FILTER (WHERE is_customer_sale) AS customer_list
   FROM v_manifest_ledger m
  WHERE created_on IS NOT NULL
  GROUP BY licence, (to_char(created_on::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, created_on::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, created_on::timestamp with time zone)::date) DESC;
create or replace view public.v_schedule_compliance as
 WITH r AS (
         SELECT harvest_alert_rules.rule_key,
            harvest_alert_rules.threshold
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        ), td AS (
         SELECT t.flower_room,
            t.takedown_start,
            t.takedown_end,
            t.takedown_days,
            row_number() OVER (PARTITION BY t.flower_room ORDER BY t.takedown_start) AS seq_plan
           FROM v_harvest_takedown t
             JOIN v_plan_room_floor f ON f.flower_room = t.flower_room
          WHERE t.is_material AND t.takedown_start >= f.floor_date
        ), pn AS (
         SELECT p.pull_no,
            p.harvest_date,
            p.flower_room,
            p.cultivars,
            p.original_total_plants,
            p.proj_harvest_weight_lbs,
            p.facility_days_since_last_pull,
            row_number() OVER (PARTITION BY p.flower_room ORDER BY p.harvest_date) AS seq_plan
           FROM harvest_pulls p
        ), pulls AS (
         SELECT pn.pull_no,
            pn.harvest_date,
            pn.flower_room,
            pn.cultivars,
            pn.original_total_plants,
            pn.proj_harvest_weight_lbs,
            pn.facility_days_since_last_pull,
            pn.seq_plan,
            td.takedown_start AS actual_date,
            td.takedown_end,
            td.takedown_days,
            (( SELECT r.threshold
                   FROM r
                  WHERE r.rule_key = 'early_allowance_days'::text))::integer AS early_ok,
            (( SELECT r.threshold
                   FROM r
                  WHERE r.rule_key = 'late_tolerance_days'::text))::integer AS late_ok
           FROM pn
             LEFT JOIN td ON td.flower_room = pn.flower_room AND td.seq_plan = pn.seq_plan
        )
 SELECT 'Pull'::text AS event_type,
    pl.pull_no,
    pl.flower_room AS room,
    pl.cultivars,
    pl.harvest_date AS scheduled_date,
    pl.actual_date,
        CASE
            WHEN pl.actual_date IS NOT NULL THEN pl.actual_date - pl.harvest_date
            WHEN pl.harvest_date < CURRENT_DATE THEN CURRENT_DATE - pl.harvest_date
            ELSE NULL::integer
        END AS days_off_schedule,
        CASE
            WHEN pl.actual_date IS NULL AND pl.harvest_date >= CURRENT_DATE THEN 'Scheduled'::text
            WHEN pl.actual_date IS NULL THEN ((('NOT HARVESTED - '::text || (CURRENT_DATE - pl.harvest_date)) || ' days past schedule, room '::text) || pl.flower_room) || ' still standing'::text
            WHEN (pl.actual_date - pl.harvest_date) > pl.late_ok THEN ('LATE by '::text || (pl.actual_date - pl.harvest_date)) || ' days'::text
            WHEN (pl.harvest_date - pl.actual_date) > pl.early_ok THEN ('Early by '::text || (pl.harvest_date - pl.actual_date)) || ' days'::text
            ELSE 'On schedule'::text
        END AS compliance,
    pl.original_total_plants AS planned_plants,
    round(COALESCE(pl.proj_harvest_weight_lbs, 0::numeric), 1) AS planned_lbs,
    pl.facility_days_since_last_pull AS planned_gap_days,
    NULL::text AS room_now,
    NULL::numeric AS days_in_dry,
    pl.takedown_end,
    pl.takedown_days,
        CASE
            WHEN pl.actual_date IS NOT NULL THEN ((('room '::text || pl.flower_room) || ', material takedown '::text) || pl.seq_plan) || ' of the plan era'::text
            ELSE 'no material takedown yet for room '::text || pl.flower_room
        END AS matched_by,
    GREATEST(COALESCE(pl.actual_date, CURRENT_DATE) - pl.harvest_date, 0) AS days_late,
    GREATEST(pl.harvest_date - COALESCE(pl.actual_date, pl.harvest_date), 0) AS days_early,
        CASE
            WHEN pl.actual_date IS NULL AND pl.harvest_date < CURRENT_DATE THEN 'Open-ended. No takedown exists for this pull, so lateness is measured from today and grows daily.'::text
            WHEN pl.actual_date IS NOT NULL AND pl.takedown_days > 1 THEN ('Takedown ran '::text || pl.takedown_days) || ' days; measured from the first cut. The plan models the pull the same way - day2_replant_date is harvest_date + 1 on all 26 rows - so this is like for like, not leniency.'::text
            ELSE NULL::text
        END AS match_note,
    pl.flower_room,
    NULL::text AS drying_location
   FROM pulls pl
UNION ALL
 SELECT 'Dry'::text AS event_type,
    NULL::integer AS pull_no,
    m.room,
    m.strains AS cultivars,
    m.harvest_start AS scheduled_date,
    m.harvest_start + (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_max_days'::text))::integer AS actual_date,
        CASE
            WHEN m.stage ~~ 'Drying%'::text AND m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN (m.days_since_takedown::numeric - (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)))::integer
            ELSE NULL::integer
        END AS days_off_schedule,
        CASE
            WHEN m.stage !~~ 'Drying%'::text AND m.stage <> 'Curing / Trim'::text THEN 'Dry complete'::text
            WHEN m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN ('DRY DEADLINE BLOWN by '::text || (m.days_since_takedown::numeric - (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)))::integer) || ' days'::text
            WHEN m.days_since_takedown::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_target_days'::text)) THEN 'At dry target - finish now'::text
            ELSE 'On schedule'::text
        END AS compliance,
    m.plants AS planned_plants,
    round(COALESCE(m.wet_weight, 0::numeric) / 453.592, 1) AS planned_lbs,
    NULL::numeric AS planned_gap_days,
    m.room AS room_now,
    m.days_since_takedown AS days_in_dry,
    NULL::date AS takedown_end,
    NULL::integer AS takedown_days,
    'NOT MEASURED - actual_date on a Dry row is harvest_start + dry_max_days, which is the deadline, not an observation'::text AS matched_by,
    NULL::integer AS days_late,
    NULL::integer AS days_early,
    'Drying has no measured completion date in Metrc. Any lateness shown here is derived from the deadline, not from an event.'::text AS match_note,
    NULL::text AS flower_room,
    m.room AS drying_location
   FROM v_harvest_stage_map m
  WHERE m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text]);
create or replace view public.v_shipped_full as
 WITH lines AS (
         SELECT t.manifest_number,
            t.package_tag,
            t.item,
            NULLIF(t.strain, ''::text) AS strain_recorded,
            f_strain_from_item(t.item) AS strain_from_item,
            t.category,
            t.shipped_qty,
            t.shipped_uom,
            t.shipped_lb,
            t.shipper_wholesale_price,
            t.destination_facility,
            t.destination_licence,
            t.status,
            t.received_on,
            t.licence AS our_licence,
            o.origin
           FROM metrc_rpt_package_transfers t
             LEFT JOIN mv_package_origin o ON o.tag = t.package_tag
        )
 SELECT tr.created_on AS shipped_on,
    l.manifest_number,
    tr.direction,
    tr.shipper,
    COALESCE(tr.recipient, l.destination_facility) AS recipient,
    f_facility_type(l.destination_licence) AS recipient_type,
    f_is_transporter(l.destination_licence) AS recipient_is_a_transporter,
    l.package_tag,
    l.item,
    COALESCE(l.strain_recorded, l.strain_from_item) AS strain,
    l.category,
    l.shipped_qty,
    l.shipped_uom,
    round(l.shipped_lb, 2) AS pounds,
    l.shipper_wholesale_price AS value_usd,
        CASE
            WHEN (l.origin ->> 'all_ours'::text)::boolean THEN 'OURS — we grew it'::text
            WHEN (l.origin ->> 'any_outside'::text)::boolean THEN 'THIRD PARTY — '::text || COALESCE((l.origin -> 'origin_names'::text) ->> 0, 'origin not named'::text)
            WHEN l.origin IS NULL THEN 'NOT IN THE PACKAGE MIRROR — lineage unknown'::text
            ELSE 'UNRESOLVED — lineage does not say'::text
        END AS whose_material,
    (l.origin ->> 'all_ours'::text)::boolean AS is_ours,
    l.origin -> 'origin_names'::text AS originator,
    l.origin -> 'origin_licences'::text AS originator_licences,
    l.origin ->> 'item_field_says'::text AS item_field_licence,
    l.origin -> 'inbound_manifests'::text AS came_in_on_manifest,
    l.origin -> 'source_harvests'::text AS source_harvests,
    (l.origin ->> 'lineage_packages'::text)::integer AS lineage_depth,
    d_coa.storage_path AS certificate_link,
        CASE
            WHEN d_coa.storage_path IS NOT NULL THEN 'on file'::text
            WHEN p.lab_testing_state = 'TestPassed'::text THEN 'passed, certificate not yet fetched from Metrc'::text
            WHEN p.lab_testing_state = 'TestFailed'::text THEN 'FAILED testing'::text
            WHEN p.lab_testing_state IS NULL THEN 'no test state recorded'::text
            ELSE p.lab_testing_state
        END AS certificate_says,
    d_man.storage_path AS manifest_link,
        CASE
            WHEN d_man.storage_path IS NOT NULL THEN 'on file'::text
            ELSE 'manifest document not yet fetched'::text
        END AS manifest_document,
        CASE
            WHEN l.strain_recorded IS NOT NULL THEN 'recorded on the manifest'::text
            WHEN l.strain_from_item IS NOT NULL THEN 'READ FROM THE ITEM NAME — not recorded'::text
            ELSE 'not stated anywhere — the item names only a product form'::text
        END AS strain_source,
        CASE
            WHEN l.strain_recorded IS NOT NULL AND l.strain_from_item IS NOT NULL AND lower(replace(l.strain_recorded, '.'::text, ''::text)) <> lower(replace(l.strain_from_item, '.'::text, ''::text)) AND lower(l.strain_recorded) !~~ (('%'::text || lower(l.strain_from_item)) || '%'::text) AND lower(l.strain_from_item) !~~ (('%'::text || lower(l.strain_recorded)) || '%'::text) THEN ('CONFLICT — the item name says "'::text || l.strain_from_item) || '"'::text
            ELSE NULL::text
        END AS strain_conflict
   FROM lines l
     LEFT JOIN metrc_transfers tr ON tr.manifest_number = l.manifest_number
     LEFT JOIN metrc_packages p ON p.tag = l.package_tag
     LEFT JOIN metrc_documents d_coa ON d_coa.package_tag = l.package_tag AND d_coa.doc_type ~~* '%coa%'::text
     LEFT JOIN metrc_documents d_man ON d_man.manifest_number = l.manifest_number AND d_man.doc_type ~~* '%manifest%'::text;
create or replace view public.v_stock_by_department as
 SELECT COALESCE(d.name, o.department, 'UNMAPPED'::text) AS department,
    d.color AS department_color,
    COALESCE(d.sort, 99) AS department_sort,
    rd.room IS NULL AS using_licence_fallback,
    o.licence,
    o.room,
    o.stage,
    o.room_role,
    o.category,
    count(*) FILTER (WHERE o.ownership ~~* '%our%'::text) AS our_lines,
    round(sum(o.lb) FILTER (WHERE o.ownership ~~* '%our%'::text), 1) AS ours_lb,
    round(sum(o.lb) FILTER (WHERE o.ownership !~~* '%our%'::text), 1) AS third_party_lb,
    round(sum(o.lb), 1) AS total_lb,
    sum(o.tags) AS tags,
    sum(o.units) AS units,
    sum(o.failed) AS failed,
    sum(o.no_coa) AS no_coa
   FROM v_onhand_by_room_stage o
     LEFT JOIN room_department rd ON rd.room = o.room
     LEFT JOIN departments d ON d.id = rd.department_id
  GROUP BY (COALESCE(d.name, o.department, 'UNMAPPED'::text)), d.color, (COALESCE(d.sort, 99)), (rd.room IS NULL), o.licence, o.room, o.stage, o.room_role, o.category;
create or replace view public.v_stock_summary as
 SELECT origin,
    stream,
    packages,
    sold_by_weight,
    f_uom_label(unit_of_measure) AS unit_of_measure,
    total_lb,
    units,
    sellable_lb,
    failed_lb,
    failed_ours_lb,
    failed_third_party_lb,
    failed_third_party_suppliers,
    out_for_testing_lb,
    untested_lb,
    sellable_units,
    untested_units,
    oldest_days,
    suppliers
   FROM ( SELECT v_stock_on_hand.origin,
            v_stock_on_hand.stream,
            sum(v_stock_on_hand.packages) AS packages,
            bool_and(v_stock_on_hand.sold_by_weight) AS sold_by_weight,
            max(v_stock_on_hand.unit_of_measure) AS unit_of_measure,
            round(sum(v_stock_on_hand.pounds), 1) AS total_lb,
            sum(v_stock_on_hand.units) AS units,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestPassed'::text), 0::numeric), 1) AS sellable_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text), 0::numeric), 1) AS failed_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND f_is_ours(v_stock_on_hand.origin_license)), 0::numeric), 1) AS failed_ours_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND NOT f_is_ours(v_stock_on_hand.origin_license)), 0::numeric), 1) AS failed_third_party_lb,
            COALESCE(string_agg(DISTINCT v_stock_on_hand.supplier, ', '::text) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND NOT f_is_ours(v_stock_on_hand.origin_license)), 'none'::text) AS failed_third_party_suppliers,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state ~~ '%ubmitted%'::text AND v_stock_on_hand.lab_state <> 'NotSubmitted'::text), 0::numeric), 1) AS out_for_testing_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text), 0::numeric), 1) AS untested_lb,
            COALESCE(sum(v_stock_on_hand.units) FILTER (WHERE v_stock_on_hand.lab_state = 'TestPassed'::text), 0::numeric) AS sellable_units,
            COALESCE(sum(v_stock_on_hand.units) FILTER (WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text), 0::numeric) AS untested_units,
            max(v_stock_on_hand.oldest_days) AS oldest_days,
            string_agg(DISTINCT v_stock_on_hand.supplier, ', '::text) AS suppliers
           FROM v_stock_on_hand
          GROUP BY v_stock_on_hand.origin, v_stock_on_hand.stream
          ORDER BY v_stock_on_hand.origin, (COALESCE(round(sum(v_stock_on_hand.pounds), 1), sum(v_stock_on_hand.units))) DESC) q;
create or replace view public.v_storage_limit_status as
 SELECT l.stream,
    NULLIF(l.location, ''::text) AS location,
    l.max_lb,
    l.max_age_days,
    l.warn_at_pct,
    l.note,
    round(COALESCE(s.on_hand_lb, 0::numeric), 1) AS on_hand_lb,
    COALESCE(s.oldest_days, 0) AS oldest_days,
        CASE
            WHEN l.max_lb IS NULL THEN NULL::numeric
            ELSE round(100::numeric * COALESCE(s.on_hand_lb, 0::numeric) / l.max_lb, 1)
        END AS pct_of_limit,
        CASE
            WHEN l.max_lb IS NULL AND l.max_age_days IS NULL THEN 'NO LIMIT SET - an owner needs to decide this'::text
            WHEN l.max_lb IS NOT NULL AND COALESCE(s.on_hand_lb, 0::numeric) > l.max_lb THEN 'OVER THE STORAGE LIMIT'::text
            WHEN l.max_age_days IS NOT NULL AND COALESCE(s.oldest_days, 0) > l.max_age_days THEN 'MATERIAL OLDER THAN THE LIMIT'::text
            WHEN l.max_lb IS NOT NULL AND COALESCE(s.on_hand_lb, 0::numeric) > (l.max_lb * l.warn_at_pct / 100::numeric) THEN 'APPROACHING THE LIMIT'::text
            ELSE 'Within limits'::text
        END AS status
   FROM storage_limits l
     LEFT JOIN ( SELECT v_stock_on_hand.stream,
            sum(v_stock_on_hand.pounds) AS on_hand_lb,
            max(v_stock_on_hand.oldest_days) AS oldest_days
           FROM v_stock_on_hand
          GROUP BY v_stock_on_hand.stream) s ON s.stream = l.stream;
create or replace view public.v_strain_name_proposal as
 WITH norm AS (
         SELECT r_1.strain,
            r_1.name_after_stripping AS stripped,
                CASE
                    WHEN r_1.name_after_stripping ~* '^TG '::text THEN r_1.name_after_stripping
                    ELSE 'TG '::text || r_1.name_after_stripping
                END AS with_prefix
           FROM v_strain_register_reconciliation r_1
          WHERE r_1.rung = 5
        ), n AS (
         SELECT norm.strain,
            norm.stripped,
            norm.with_prefix,
            lower(regexp_replace(norm.with_prefix, '[^a-zA-Z0-9]'::text, ''::text, 'g'::text)) AS key,
            array_length(string_to_array(btrim(norm.with_prefix), ' '::text), 1) AS toks
           FROM norm
        ), reg AS (
         SELECT metrc_strains.name,
            lower(regexp_replace(metrc_strains.name, '[^a-zA-Z0-9]'::text, ''::text, 'g'::text)) AS key,
            array_length(string_to_array(btrim(metrc_strains.name), ' '::text), 1) AS toks
           FROM metrc_strains
          GROUP BY metrc_strains.name, (lower(regexp_replace(metrc_strains.name, '[^a-zA-Z0-9]'::text, ''::text, 'g'::text))), (array_length(string_to_array(btrim(metrc_strains.name), ' '::text), 1))
        )
 SELECT n.strain AS library_name,
    n.stripped AS name_after_stripping,
    r.name AS proposed_metrc_strain,
    round(similarity(n.key, r.key)::numeric, 3) AS tiebreak_score,
    n.toks AS tokens_in_name,
    abs(length(n.key) - length(r.key)) AS character_gap,
    ('PROPOSED - a person must confirm. Same token count and a character gap of '::text || abs(length(n.key) - length(r.key))) || '. This is a spelling or spacing variant, NOT a decided match.'::text AS status,
    'Confirm in Metrc that these are the same strain, then record the ruling. If they are different strains, register the missing one at source (rule D2).'::text AS what_to_do
   FROM n
     JOIN reg r ON n.toks = r.toks AND abs(length(n.key) - length(r.key)) <= 2 AND similarity(n.key, r.key) >= 0.70::double precision
  ORDER BY (round(similarity(n.key, r.key)::numeric, 3)) DESC;
create or replace view public.v_supply_demand as
 WITH sold AS (
         SELECT v_material_requirement.apex_category AS category,
            v_material_requirement.brand,
            sum(v_material_requirement.units) FILTER (WHERE v_material_requirement.order_date >= (CURRENT_DATE - 90)) AS units_90d,
            sum(v_material_requirement.units) FILTER (WHERE v_material_requirement.order_date >= (CURRENT_DATE - 365)) AS units_365d
           FROM v_material_requirement
          GROUP BY v_material_requirement.apex_category, v_material_requirement.brand
        ), grown AS (
         SELECT count(*)::numeric AS plants_now
           FROM metrc_plants
        )
 SELECT si.id AS supply_item_id,
    si.name AS supply_item,
    si.category AS supply_category,
    si.unit,
    si.on_hand,
    si.reorder_level,
    si.reorder_qty,
    si.safety_stock,
    si.lead_time_days,
    si.vendor,
    si.track_enabled,
    r.driver,
    r.scope,
    r.scope_key,
    r.qty_per_driver,
        CASE r.driver
            WHEN 'units_sold'::text THEN COALESCE(( SELECT sum(s.units_90d) AS sum
               FROM sold s
              WHERE r.scope = 'global'::text OR r.scope = 'category'::text AND s.category = r.scope_key OR r.scope = 'brand'::text AND s.brand = r.scope_key), 0::numeric)
            WHEN 'plants_grown'::text THEN ( SELECT grown.plants_now
               FROM grown)
            ELSE NULL::numeric
        END AS driver_qty_90d,
    round(
        CASE r.driver
            WHEN 'units_sold'::text THEN COALESCE(( SELECT sum(s.units_90d) AS sum
               FROM sold s
              WHERE r.scope = 'global'::text OR r.scope = 'category'::text AND s.category = r.scope_key OR r.scope = 'brand'::text AND s.brand = r.scope_key), 0::numeric)
            WHEN 'plants_grown'::text THEN ( SELECT grown.plants_now
               FROM grown)
            ELSE 0::numeric
        END * r.qty_per_driver, 0) AS required_90d
   FROM supply_items si
     LEFT JOIN supply_consumption_rule r ON r.supply_item_id = si.id AND CURRENT_DATE >= r.effective_from AND (r.effective_to IS NULL OR CURRENT_DATE < r.effective_to);
create or replace view public.v_supply_position as
 WITH on_order AS (
         SELECT l.supply_item_id,
            sum(GREATEST(COALESCE(l.qty, 0::numeric) - COALESCE(l.received_good, 0::numeric) - COALESCE(l.received_damaged, 0::numeric), 0::numeric)) AS qty_on_order,
            min(COALESCE(po.promised_on, po.required_on)) AS next_arrival,
            string_agg(DISTINCT po.po_code, ', '::text) AS open_pos
           FROM purchase_order_lines l
             JOIN purchase_orders po ON po.id = l.purchase_order_id
          WHERE l.supply_item_id IS NOT NULL AND (COALESCE(po.status, 'open'::text) <> ALL (ARRAY['received'::text, 'cancelled'::text, 'closed'::text]))
          GROUP BY l.supply_item_id
        )
 SELECT s.name AS supply_item,
    s.category,
    s.unit,
    s.on_hand,
    s.reorder_level,
    s.safety_stock,
    s.lead_time_days,
    s.cost_per_unit,
    c.consumed_30d,
    c.avg_monthly_90d,
    c.rate_is_provisional,
        CASE
            WHEN c.avg_monthly_90d > 0::numeric AND s.on_hand IS NOT NULL THEN round((s.on_hand + COALESCE(o.qty_on_order, 0::numeric)) / (c.avg_monthly_90d / 30.0), 1)
            ELSE NULL::numeric
        END AS days_of_cover,
        CASE
            WHEN s.on_hand IS NOT NULL AND c.avg_monthly_90d > 0::numeric AND s.lead_time_days IS NOT NULL THEN round(c.avg_monthly_90d / 30.0 * s.lead_time_days::numeric, 0)
            ELSE NULL::numeric
        END AS needed_during_lead_time,
    round(COALESCE(c.consumed_30d, 0::numeric) * COALESCE(s.cost_per_unit, 0::numeric), 2) AS spend_30d,
        CASE
            WHEN c.avg_monthly_90d IS NULL OR c.avg_monthly_90d = 0::numeric THEN 'NO CONSUMPTION RULE — nothing tells the platform what draws this item down, so it cannot say when to reorder.'::text
            WHEN s.on_hand IS NULL THEN ('ON HAND NOT COUNTED — usage is measured at '::text || round(c.avg_monthly_90d / 30.0, 1)) || '/day, so the moment somebody counts this shelf the reorder point and keep-on-hand level compute themselves.'::text
            WHEN (s.on_hand + COALESCE(o.qty_on_order, 0::numeric)) <= round(c.avg_monthly_90d / 30.0 * COALESCE(s.lead_time_days, 14)::numeric + COALESCE(s.safety_stock, c.avg_monthly_90d / 30.0 * COALESCE(s.lead_time_days, 14)::numeric * 0.25), 0) THEN 'REORDER NOW — on hand plus on order is at or below the reorder point'::text
            WHEN COALESCE(o.qty_on_order, 0::numeric) > 0::numeric THEN (('ON ORDER — '::text || o.qty_on_order) || ' arriving'::text) || COALESCE(' '::text || to_char(o.next_arrival::timestamp with time zone, 'DD Mon'::text), ''::text)
            ELSE 'OK'::text
        END AS status,
    s.vendor,
    COALESCE(o.qty_on_order, 0::numeric) AS on_order,
    s.on_hand + COALESCE(o.qty_on_order, 0::numeric) AS available,
    o.next_arrival,
    o.open_pos,
    round(c.avg_monthly_90d / 30.0, 1) AS avg_daily_usage,
    round(c.avg_monthly_90d / 30.0 * COALESCE(s.lead_time_days, 14)::numeric + COALESCE(s.safety_stock, c.avg_monthly_90d / 30.0 * COALESCE(s.lead_time_days, 14)::numeric * 0.25), 0) AS reorder_point_recommended,
    round(c.avg_monthly_90d / 30.0 * (COALESCE(s.lead_time_days, 14) + COALESCE(s.cover_days, 30))::numeric + COALESCE(s.safety_stock, c.avg_monthly_90d / 30.0 * COALESCE(s.lead_time_days, 14)::numeric * 0.25), 0) AS keep_on_hand_recommended
   FROM supply_items s
     LEFT JOIN v_supply_consumption c ON c.supply_item_id = s.id
     LEFT JOIN on_order o ON o.supply_item_id = s.id;
create or replace view public.v_sync_failures_pending as
 SELECT system,
    endpoint,
    license,
    status,
    records,
    started_at,
    finished_at,
    error
   FROM v_all_sync_runs r
  WHERE (lower(COALESCE(status, ''::text)) = ANY (ARRAY['error'::text, 'failed'::text, 'failure'::text])) AND started_at > COALESCE(( SELECT max(alert_outbox.created_at) AS max
           FROM alert_outbox
          WHERE alert_outbox.source = 'sync_digest'::text), now() - '24:00:00'::interval);
create or replace view public.v_sync_item as
 SELECT sync_item.source_key,
    sync_item.source_label,
    sync_item.fn,
    sync_item.item_key,
    sync_item.item_label,
    sync_item.query_param,
    sync_item.extra_params,
    sync_item.note,
    sync_item.enabled,
    sync_item.supported,
    sync_item.sort,
    NULL::bigint AS rows_stored,
    NULL::timestamp with time zone AS last_success_at,
    NULL::text AS last_status,
    NULL::boolean AS due,
    NULL::text AS due_text,
    sync_item.system_label,
    sync_item.source_name,
    sync_item.pulls,
    sync_item.target
   FROM sync_item
UNION ALL
 SELECT 'apex'::text AS source_key,
    'Apex Trading (sales)'::text AS source_label,
    'apex-sync'::text AS fn,
    s.entity AS item_key,
    COALESCE(e.label, s.entity) AS item_label,
    'entity'::text AS query_param,
    '{"force": "1"}'::jsonb AS extra_params,
    NULL::text AS note,
    true AS enabled,
    true AS supported,
    70 +
        CASE s.kind
            WHEN 'money'::text THEN 0
            WHEN 'core'::text THEN 1
            WHEN 'crm'::text THEN 2
            WHEN 'document'::text THEN 3
            ELSE 4
        END AS sort,
    s.rows_stored,
    s.last_success_at,
    s.last_status,
    s.due,
    s.due_text,
    'Apex Trading'::text AS system_label,
    'Apex Trading API — app.apextrading.com, the sales source of record'::text AS source_name,
    COALESCE(e.why, 'Apex '::text || s.entity) AS pulls,
    ('apex_raw (entity = '::text || s.entity) || ')'::text AS target
   FROM v_apex_entity_status s
     JOIN apex_entity e ON e.entity = s.entity;
create or replace view public.v_tag_resolver as
 WITH universe AS (
         SELECT z.tag
           FROM ( SELECT DISTINCT upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag
                   FROM metrc_packages
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_package_transfers.package_tag)) AS upper
                   FROM metrc_rpt_package_transfers
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_package_transfers.source_package)) AS upper
                   FROM metrc_rpt_package_transfers
                  WHERE NULLIF(btrim(metrc_rpt_package_transfers.source_package), ''::text) IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_point_in_time.tag)) AS upper
                   FROM metrc_rpt_point_in_time
                  WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_packages_inventory.package_tag)) AS upper
                   FROM metrc_rpt_packages_inventory
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper
                   FROM metrc_rpt_lab_results
                  WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_adjustments.package_tag)) AS upper
                   FROM metrc_rpt_adjustments
                  WHERE metrc_rpt_adjustments.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_test_batches.package_tag)) AS upper
                   FROM metrc_rpt_test_batches
                  WHERE metrc_rpt_test_batches.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(s.s)) AS upper
                   FROM metrc_packages p,
                    LATERAL unnest(string_to_array(COALESCE(p.raw ->> 'SourcePackageLabels'::text, ''::text), ','::text)) s(s)
                  WHERE btrim(s.s) <> ''::text) z
          WHERE z.tag IS NOT NULL AND z.tag <> ''::text
        ), mirror AS (
         SELECT DISTINCT ON ((upper(btrim(metrc_packages.raw ->> 'Label'::text)))) upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag,
            metrc_packages.license,
            metrc_packages.source_state,
            metrc_packages.raw
           FROM metrc_packages
          ORDER BY (upper(btrim(metrc_packages.raw ->> 'Label'::text))), (metrc_packages.raw ->> 'LastModified'::text) DESC NULLS LAST
        ), mirror_lic AS (
         SELECT upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag,
            string_agg(DISTINCT metrc_packages.license, ' + '::text ORDER BY metrc_packages.license) AS licences
           FROM metrc_packages
          GROUP BY (upper(btrim(metrc_packages.raw ->> 'Label'::text)))
        ), legs AS (
         SELECT upper(btrim(v_transfer_line.package_tag)) AS tag,
            count(*) AS legs_total,
            count(*) FILTER (WHERE v_transfer_line.voided = 'True'::text) AS legs_voided,
            bool_or(v_transfer_line.direction = 'OUTBOUND'::text AND v_transfer_line.voided <> 'True'::text) AS any_out,
            bool_or(v_transfer_line.direction = 'INBOUND'::text AND v_transfer_line.voided <> 'True'::text) AS any_in,
            bool_or(v_transfer_line.direction = 'INTERNAL'::text AND v_transfer_line.voided <> 'True'::text) AS any_internal,
            min(v_transfer_line.received_on) AS first_moved,
            max(v_transfer_line.received_on) AS last_moved,
            string_agg(DISTINCT v_transfer_line.manifest_number, ', '::text) AS manifests_all,
            round(sum(v_transfer_line.pounds) FILTER (WHERE v_transfer_line.direction = 'OUTBOUND'::text AND v_transfer_line.voided <> 'True'::text), 3) AS lb_out,
            round(sum(v_transfer_line.pounds) FILTER (WHERE (v_transfer_line.direction = ANY (ARRAY['INBOUND'::text, 'INTERNAL'::text])) AND v_transfer_line.voided <> 'True'::text), 3) AS lb_in
           FROM v_transfer_line
          GROUP BY (upper(btrim(v_transfer_line.package_tag)))
        ), last_leg AS (
         SELECT DISTINCT ON ((upper(btrim(v_transfer_line.package_tag)))) upper(btrim(v_transfer_line.package_tag)) AS tag,
            v_transfer_line.manifest_number,
            v_transfer_line.direction,
            v_transfer_line.received_on,
            v_transfer_line.pounds,
            v_transfer_line.weight_source,
            v_transfer_line.voided,
            v_transfer_line.status,
            v_transfer_line.origin_licence,
            v_transfer_line.origin_facility,
            v_transfer_line.dest_licence,
            v_transfer_line.dest_facility,
            v_transfer_line.item,
            v_transfer_line.category,
            v_transfer_line.strain
           FROM v_transfer_line
          ORDER BY (upper(btrim(v_transfer_line.package_tag))), (v_transfer_line.voided = 'True'::text), v_transfer_line.received_on DESC NULLS LAST, v_transfer_line.manifest_number DESC
        ), consumed AS (
         SELECT upper(btrim(metrc_rpt_package_transfers.source_package)) AS tag,
            count(DISTINCT metrc_rpt_package_transfers.manifest_number) AS n_manifests,
            min(metrc_rpt_package_transfers.manifest_number) AS a_manifest,
            count(DISTINCT upper(btrim(metrc_rpt_package_transfers.package_tag))) AS n_children,
            min(upper(btrim(metrc_rpt_package_transfers.package_tag))) AS a_child,
            min(metrc_rpt_package_transfers.received_on) AS first_seen,
            max(metrc_rpt_package_transfers.received_on) AS last_seen
           FROM metrc_rpt_package_transfers
          WHERE NULLIF(btrim(metrc_rpt_package_transfers.source_package), ''::text) IS NOT NULL
          GROUP BY (upper(btrim(metrc_rpt_package_transfers.source_package)))
        ), lineage AS (
         SELECT DISTINCT upper(btrim(s.s)) AS anc_tag,
            upper(btrim(p.raw ->> 'Label'::text)) AS child_tag
           FROM metrc_packages p,
            LATERAL unnest(string_to_array(COALESCE(p.raw ->> 'SourcePackageLabels'::text, ''::text), ','::text)) s(s)
          WHERE btrim(s.s) <> ''::text
        ), lineage_any AS (
         SELECT lineage.anc_tag,
            count(*) AS n_children,
            min(lineage.child_tag) AS a_child
           FROM lineage
          GROUP BY lineage.anc_tag
        ), child_inbound AS (
         SELECT l.anc_tag,
            count(DISTINCT li.manifest_number) AS n_manifests,
            min(li.manifest_number) AS a_manifest,
            min(COALESCE(li.origin_facility, li.origin_licence)) AS a_sender,
            min(li.received_on) AS first_received,
            min(l.child_tag) AS a_child
           FROM lineage l
             JOIN v_transfer_line li ON upper(btrim(li.package_tag)) = l.child_tag AND (li.direction = ANY (ARRAY['INBOUND'::text, 'INTERNAL'::text])) AND li.voided <> 'True'::text
          GROUP BY l.anc_tag
        ), child_origin AS (
         SELECT l.anc_tag,
            min(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) AS licence,
            min(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text)) AS name,
            bool_or(f_is_ours(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text))) AS any_ours
           FROM lineage l
             JOIN metrc_packages p ON upper(btrim(p.raw ->> 'Label'::text)) = l.child_tag
          GROUP BY l.anc_tag
        ), seen AS (
         SELECT z.tag,
            string_agg(z.src, ' + '::text ORDER BY z.src) AS also_seen_in
           FROM ( SELECT DISTINCT upper(btrim(metrc_rpt_point_in_time.tag)) AS tag,
                    'point-in-time snapshot'::text AS src
                   FROM metrc_rpt_point_in_time
                  WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_packages_inventory.package_tag)) AS upper,
                    'packages-inventory report'::text
                   FROM metrc_rpt_packages_inventory
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper,
                    'Metrc lab results'::text
                   FROM metrc_rpt_lab_results
                  WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_adjustments.package_tag)) AS upper,
                    'adjustments report'::text
                   FROM metrc_rpt_adjustments
                  WHERE metrc_rpt_adjustments.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_test_batches.package_tag)) AS upper,
                    'test-batches report'::text
                   FROM metrc_rpt_test_batches
                  WHERE metrc_rpt_test_batches.package_tag IS NOT NULL) z
          GROUP BY z.tag
        ), core AS (
         SELECT u.tag,
            m.tag IS NOT NULL AS in_mirror,
                CASE
                    WHEN m.tag IS NOT NULL THEN 'HELD'::text
                    WHEN ll.direction = 'OUTBOUND'::text THEN 'SHIPPED OUT'::text
                    WHEN ll.direction = 'INBOUND'::text THEN 'RECEIVED'::text
                    WHEN ll.direction = 'INTERNAL'::text THEN 'MOVED BETWEEN OUR LICENCES'::text
                    WHEN ll.direction IS NOT NULL THEN 'THIRD PARTY BOTH ENDS'::text
                    WHEN cs.tag IS NOT NULL THEN 'CONSUMED HERE'::text
                    WHEN ci.anc_tag IS NOT NULL THEN 'UPSTREAM AT THE SENDER'::text
                    WHEN la.anc_tag IS NOT NULL AND co.licence IS NOT NULL AND NOT co.any_ours THEN 'UPSTREAM AT AN OUTSIDE CULTIVATOR'::text
                    WHEN la.anc_tag IS NOT NULL THEN 'LINEAGE ONLY'::text
                    WHEN sn.tag IS NOT NULL THEN 'REPORT SIGHTING ONLY'::text
                    ELSE 'NOT RESOLVED'::text
                END AS resolution,
            m.license AS mirror_licence,
            ml.licences AS mirror_licences_all,
            m.source_state AS mirror_state,
            NULLIF(m.raw ->> 'LocationName'::text, ''::text) AS mirror_room,
                CASE
                    WHEN m.tag IS NOT NULL THEN f_quantity_text(COALESCE((m.raw ->> 'Quantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(m.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text))
                    ELSE NULL::text
                END AS mirror_quantity,
            ll.manifest_number,
            ll.direction,
            ll.received_on AS moved_on,
            ll.pounds,
            ll.weight_source,
            ll.status AS manifest_status,
            ll.voided AS manifest_voided,
            ll.origin_licence,
            ll.origin_facility,
            ll.dest_licence,
            ll.dest_facility,
            COALESCE(NULLIF(m.raw #>> '{Item,Name}'::text[], ''::text), ll.item) AS item,
            COALESCE(NULLIF(m.raw #>> '{Item,ProductCategoryName}'::text[], ''::text), ll.category) AS category,
            g.legs_total,
            g.legs_voided,
            g.any_out,
            g.any_in,
            g.any_internal,
            g.first_moved,
            g.last_moved,
            g.manifests_all,
            g.lb_out,
            g.lb_in,
            cs.n_manifests AS consumed_manifests,
            cs.a_manifest AS consumed_a_manifest,
            cs.n_children AS consumed_children,
            cs.a_child AS consumed_a_child,
            ci.n_manifests AS child_manifests,
            ci.a_manifest AS child_a_manifest,
            ci.a_sender AS child_sender,
            ci.first_received AS child_received,
            ci.a_child AS child_tag,
            la.n_children AS lineage_children,
            la.a_child AS lineage_a_child,
            sn.also_seen_in
           FROM universe u
             LEFT JOIN mirror m ON m.tag = u.tag
             LEFT JOIN mirror_lic ml ON ml.tag = u.tag
             LEFT JOIN legs g ON g.tag = u.tag
             LEFT JOIN last_leg ll ON ll.tag = u.tag
             LEFT JOIN consumed cs ON cs.tag = u.tag
             LEFT JOIN child_inbound ci ON ci.anc_tag = u.tag
             LEFT JOIN lineage_any la ON la.anc_tag = u.tag
             LEFT JOIN child_origin co ON co.anc_tag = u.tag
             LEFT JOIN seen sn ON sn.tag = u.tag
        ), outside AS (
         SELECT l.anc_tag,
            min(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text)) AS licence,
            min(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text)) AS name
           FROM lineage l
             JOIN metrc_packages p ON upper(btrim(p.raw ->> 'Label'::text)) = l.child_tag
          GROUP BY l.anc_tag
        )
 SELECT c.tag,
    c.in_mirror,
    c.resolution,
    c.mirror_licence,
    c.mirror_licences_all,
    c.mirror_state,
    c.mirror_room,
    c.mirror_quantity,
    c.manifest_number,
    c.direction,
    c.moved_on,
    c.pounds,
    c.weight_source,
    c.manifest_status,
    c.manifest_voided,
    c.origin_licence,
    c.origin_facility,
    c.dest_licence,
    c.dest_facility,
    c.item,
    c.category,
    c.legs_total,
    c.legs_voided,
    c.any_out,
    c.any_in,
    c.any_internal,
    c.first_moved,
    c.last_moved,
    c.manifests_all,
    c.lb_out,
    c.lb_in,
    c.consumed_manifests,
    c.consumed_a_manifest,
    c.consumed_children,
    c.consumed_a_child,
    c.child_manifests,
    c.child_a_manifest,
    c.child_sender,
    c.child_received,
    c.child_tag,
    c.lineage_children,
    c.lineage_a_child,
    c.also_seen_in,
    c.resolution <> 'NOT RESOLVED'::text AS resolved,
    c.resolution = ANY (ARRAY['HELD'::text, 'SHIPPED OUT'::text, 'RECEIVED'::text, 'MOVED BETWEEN OUR LICENCES'::text, 'THIRD PARTY BOTH ENDS'::text, 'CONSUMED HERE'::text, 'UPSTREAM AT THE SENDER'::text]) AS resolves_to_package_or_manifest,
    c.resolution = ANY (ARRAY['NOT RESOLVED'::text, 'LINEAGE ONLY'::text, 'UPSTREAM AT AN OUTSIDE CULTIVATOR'::text]) AS needs_a_person,
    c.resolution = ANY (ARRAY['SHIPPED OUT'::text, 'RECEIVED'::text, 'MOVED BETWEEN OUR LICENCES'::text, 'THIRD PARTY BOTH ENDS'::text, 'CONSUMED HERE'::text, 'UPSTREAM AT THE SENDER'::text]) AS absence_is_expected,
        CASE c.resolution
            WHEN 'HELD'::text THEN ((((((('We hold this package. It is in the Metrc mirror under '::text || COALESCE(c.mirror_licences_all, '(no licence)'::text)) || ', state '::text) || COALESCE(c.mirror_state, '(unknown)'::text)) || ', room '::text) || COALESCE(c.mirror_room, '(no room)'::text)) || ', quantity '::text) || COALESCE(c.mirror_quantity, '(no quantity recorded)'::text)) || '.'::text
            WHEN 'SHIPPED OUT'::text THEN ((((((((((((('It LEFT us. Manifest '::text || COALESCE(c.manifest_number, '(unnumbered)'::text)) || ' carried it from '::text) || COALESCE(c.origin_facility, c.origin_licence, 'our facility'::text)) || ' to '::text) || COALESCE(c.dest_facility, c.dest_licence, '(destination not named)'::text)) || COALESCE((' ('::text || c.dest_licence) || ')'::text, ''::text)) || ' on '::text) || COALESCE(c.moved_on::text, '(no date)'::text)) || ', '::text) || COALESCE(c.pounds::text, '?'::text)) || ' lb by '::text) || COALESCE(c.weight_source, 'unknown basis'::text)) || '.'::text) ||
            CASE
                WHEN c.manifest_voided = 'True'::text THEN ' THAT MANIFEST IS VOIDED.'::text
                ELSE ''::text
            END
            WHEN 'RECEIVED'::text THEN (((((((((('It CAME to us. Manifest '::text || COALESCE(c.manifest_number, '(unnumbered)'::text)) || ' from '::text) || COALESCE(c.origin_facility, c.origin_licence, '(sender not named)'::text)) || COALESCE((' ('::text || c.origin_licence) || ')'::text, ''::text)) || ' on '::text) || COALESCE(c.moved_on::text, '(no date)'::text)) || ', '::text) || COALESCE(c.pounds::text, '?'::text)) || ' lb by '::text) || COALESCE(c.weight_source, 'unknown basis'::text)) || '.'::text
            WHEN 'MOVED BETWEEN OUR LICENCES'::text THEN ((((((('It moved between our own two licences on manifest '::text || COALESCE(c.manifest_number, '(unnumbered)'::text)) || ' ('::text) || COALESCE(c.origin_licence, '?'::text)) || ' to '::text) || COALESCE(c.dest_licence, '?'::text)) || ') on '::text) || COALESCE(c.moved_on::text, '(no date)'::text)) || '. Not a sale.'::text
            WHEN 'THIRD PARTY BOTH ENDS'::text THEN ((((('A third-party package. Manifest '::text || COALESCE(c.manifest_number, '(unnumbered)'::text)) || ' runs from '::text) || COALESCE(c.origin_facility, c.origin_licence, '?'::text)) || ' to '::text) || COALESCE(c.dest_facility, c.dest_licence, '?'::text)) || ' and NEITHER end is one of our licences.'::text
            WHEN 'CONSUMED HERE'::text THEN ((((('It was used up here. Metrc names it as the SOURCE PACKAGE of '::text || COALESCE(c.consumed_children, 0::bigint)) || ' package(s) that then travelled — for example '::text) || COALESCE(c.consumed_a_child, '?'::text)) || ' on manifest '::text) || COALESCE(c.consumed_a_manifest, '?'::text)) || '. The child moved; this parent never did.'::text
            WHEN 'UPSTREAM AT THE SENDER'::text THEN ((((((('It is the SENDER''S OWN upstream package, not ours. What arrived here was its child '::text || COALESCE(c.child_tag, '?'::text)) || ', on manifest '::text) || COALESCE(c.child_a_manifest, '?'::text)) || ' from '::text) || COALESCE(c.child_sender, '(sender not named)'::text)) || ' on '::text) || COALESCE(c.child_received::text, '(no date)'::text)) || '.'::text
            WHEN 'UPSTREAM AT AN OUTSIDE CULTIVATOR'::text THEN ((((((('THIRD PARTY, and we know whose. Metrc names it as the source of '::text || COALESCE(c.lineage_children, 0::bigint)) || ' package(s) we hold — for example '::text) || COALESCE(c.lineage_a_child, '?'::text)) || ' — and that package''s item was defined by '::text) || COALESCE(o.name, 'an outside licensee'::text)) || ' ('::text) || COALESCE(o.licence, 'licence not named'::text)) || '), not by us. We never held the parent, so it can never be in our mirror. What IS missing is the inbound manifest that brought the child here: it is in no transfer report we have imported.'::text
            WHEN 'LINEAGE ONLY'::text THEN (((('Metrc names it as the source of '::text || COALESCE(c.lineage_children, 0::bigint)) || ' package(s) we hold — for example '::text) || COALESCE(c.lineage_a_child, '?'::text)) || ' — but neither it nor that child appears on any manifest we have imported, '::text) || 'and the child names no outside licensee either.'::text
            WHEN 'REPORT SIGHTING ONLY'::text THEN ('It appears in '::text || COALESCE(c.also_seen_in, 'a Metrc report'::text)) || ' and nowhere else. No manifest line, no mirror row, no lineage.'::text
            ELSE 'Nothing found. Not in the package mirror, on no manifest line, named as no source package, '::text || 'in no lineage and in no Metrc report we have imported.'::text
        END AS resolution_detail,
        CASE c.resolution
            WHEN 'HELD'::text THEN 'Not applicable — it IS in the mirror.'::text
            WHEN 'SHIPPED OUT'::text THEN 'EXPECTED, and it will never change. Metrc stops returning a package to the shipping facility once the receiver has accepted it. The mirror holds what we possess, not what we once possessed. This is correct behaviour, not a defect.'::text
            WHEN 'RECEIVED'::text THEN 'The manifest shows it arriving, but the Metrc packages endpoint returns no row for it — normally because it has since been repackaged or finished. Follow the child tags before calling it a gap.'::text
            WHEN 'MOVED BETWEEN OUR LICENCES'::text THEN 'EXPECTED while a transfer is in flight, or after the receiving licence repackaged it under a new tag.'::text
            WHEN 'THIRD PARTY BOTH ENDS'::text THEN 'EXPECTED. We do not mirror other facilities'' packages and never will. The line is visible only because the manifest passed through a report we import.'::text
            WHEN 'CONSUMED HERE'::text THEN 'EXPECTED. A parent package stops existing once it is fully packaged out. Metrc keeps the reference on the child, not a standing package row.'::text
            WHEN 'UPSTREAM AT THE SENDER'::text THEN 'EXPECTED. Metrc carries the sender''s own source labels through onto the package they ship us. We never held that parent, so it can never be in our mirror.'::text
            WHEN 'UPSTREAM AT AN OUTSIDE CULTIVATOR'::text THEN 'The parent being absent is EXPECTED — it is another licensee''s package. The missing piece is OURS to fix: import the inbound transfer report covering the date the child arrived, and this tag resolves to a manifest like every other. Until then it stays a named third-party parent with no custody line behind it.'::text
            WHEN 'LINEAGE ONLY'::text THEN 'NOT expected. Either the transfer report covering the child has not been imported, or the parent is one of our own older packages the mirror no longer returns. Import the missing report, or pull the package by tag from Metrc.'::text
            WHEN 'REPORT SIGHTING ONLY'::text THEN 'NOT expected. A tag in a report but on no manifest means the transfer report covering its dates has not been imported. Import that report.'::text
            ELSE 'A tag with no evidence anywhere is either a mistyped tag in a source file or a report we have never imported. Find the report that names it, then import it. Per the owner ruling of 12 Aug 2026 there is a tag for every item and a manifest for every tag, so this state should be empty.'::text
        END AS what_would_change_it,
    o.licence AS outside_cultivator_licence,
    o.name AS outside_cultivator_name
   FROM core c
     LEFT JOIN outside o ON o.anc_tag = c.tag;
create or replace view public.v_third_party_stock as
 SELECT supplier,
    origin_license,
    stream,
    held_under,
    lab_state,
    location,
    packages,
    pounds,
    oldest_days,
    oldest_packaged,
    strains,
    why_separate,
    oldest_packaged AS oldest_packaged_date,
    grams
   FROM ( SELECT v_stock_on_hand.supplier,
            v_stock_on_hand.origin_license,
            v_stock_on_hand.stream,
            v_stock_on_hand.license AS held_under,
            v_stock_on_hand.lab_state,
            v_stock_on_hand.location,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            v_stock_on_hand.oldest_days,
            v_stock_on_hand.grams,
            v_stock_on_hand.oldest_packaged,
            v_stock_on_hand.strains,
            'Bought in from another licence. Must be tracked, allocated and costed separately from what we grow.'::text AS why_separate
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.origin <> 'Grown by us'::text
          ORDER BY v_stock_on_hand.pounds DESC) q;
create or replace view public.v_trace_completeness as
 SELECT package_tag,
    held_by_licence,
    current_room,
    item,
    strain,
    category,
    packaged_on,
    lb,
    units,
    harvested_by,
    harvested_by_licence,
    harvested_by_ownership,
    repackaged_by,
    manufactured_by,
    source_harvest,
    source_packages,
    inbound_manifest,
    has_coa,
    provenance,
    harvested_by <> '(not recorded)'::text AS has_harvester,
    harvested_by_ownership <> 'UNKNOWN'::text AS has_ownership,
    source_harvest IS NOT NULL OR source_packages IS NOT NULL OR category = 'Seeds'::text AS has_lineage,
    inbound_manifest IS NOT NULL OR harvested_by_ownership = 'OURS'::text AS arrival_explained,
        CASE
            WHEN harvested_by = '(not recorded)'::text THEN 'FAIL — no harvesting facility recorded'::text
            WHEN harvested_by_ownership = 'UNKNOWN'::text THEN 'FAIL — ownership cannot be determined'::text
            WHEN source_harvest IS NULL AND source_packages IS NULL AND category <> 'Seeds'::text THEN 'FAIL — no source harvest and no source package'::text
            WHEN inbound_manifest IS NULL AND harvested_by_ownership = 'THIRD PARTY'::text AND source_packages IS NULL THEN 'FAIL — third-party material with no inbound manifest and no source tag'::text
            WHEN category = 'Seeds'::text AND source_harvest IS NULL THEN 'PASS — Seeds, exempt from source lineage (start of the chain)'::text
            ELSE 'PASS — fully traced'::text
        END AS trace_verdict
   FROM v_tag_provenance;
create or replace view public.v_unit_costs as
 SELECT 'Vape'::text AS stream,
    '0.5 g cartridge'::text AS sku,
    0.5 AS g,
    v_cost_of_goods.vape_05g_unit_cost AS unit_cost,
    round(v_cost_of_goods.vape_05g_unit_cost * 453.592 / 0.5) AS per_pound
   FROM v_cost_of_goods
UNION ALL
 SELECT 'Vape'::text AS stream,
    '1.0 g cartridge'::text AS sku,
    1.0 AS g,
    v_cost_of_goods.vape_10g_unit_cost AS unit_cost,
    round(v_cost_of_goods.vape_10g_unit_cost * 453.592 / 1.0) AS per_pound
   FROM v_cost_of_goods
UNION ALL
 SELECT 'Concentrate'::text AS stream,
    '1.0 g badder'::text AS sku,
    1.0 AS g,
    v_cost_of_goods.badder_1g_unit_cost AS unit_cost,
    round(v_cost_of_goods.badder_1g_unit_cost * 453.592 / 1.0) AS per_pound
   FROM v_cost_of_goods
UNION ALL
 SELECT 'Concentrate'::text AS stream,
    '3.5 g badder'::text AS sku,
    3.5 AS g,
    v_cost_of_goods.badder_35g_unit_cost AS unit_cost,
    round(v_cost_of_goods.badder_35g_unit_cost * 453.592 / 3.5) AS per_pound
   FROM v_cost_of_goods;
create or replace view public.v_unrequested_material as
 SELECT origin,
    supplier,
    stream,
    license,
    location,
    lab_state,
    packages,
    pounds,
    oldest_days,
    'No approved allocation covers this material. Under the owner rule nothing may move until Vincent approves it - and that applies to bought-in material as much as our own.'::text AS why_it_matters
   FROM v_stock_on_hand s
  WHERE NOT (EXISTS ( SELECT 1
           FROM allocation_requests r
          WHERE r.status = 'approved'::text AND (COALESCE(r.stream, ''::text) = s.stream OR COALESCE(r.material_name, ''::text) ~~* (('%'::text || s.stream) || '%'::text))))
  ORDER BY pounds DESC;
create or replace view public.v_watchdog_current as
 SELECT observed_at,
    observed_on,
    severity,
    what,
    where_it_is,
    who_is_accountable,
    when_it_started,
    why_it_matters,
    how_it_was_detected,
    what_to_do,
    the_arithmetic,
    record_count,
    pounds,
    dollars,
    drill,
    fingerprint,
    evidence,
    search_text,
    sweep_ran_at,
    sweep_ran_by,
    sweep_ms,
    finding_id,
    run_id
   FROM v_watchdog_log
  WHERE run_id = (( SELECT max(watchdog_runs.id) AS max
           FROM watchdog_runs))
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), (COALESCE(dollars, 0::numeric)) DESC;
create or replace view public.v_weekend_watch as
 SELECT 'Scheduled pull'::text AS event_type,
    p.pull_no,
    p.flower_room AS room,
    p.cultivars AS detail,
    p.harvest_date AS event_date,
    TRIM(BOTH FROM to_char(p.harvest_date::timestamp with time zone, 'Day'::text)) AS falls_on,
    p.harvest_date - CURRENT_DATE AS days_away,
        CASE
            WHEN p.harvest_date < CURRENT_DATE THEN 'PAST - check it was not slipped'::text
            WHEN (p.harvest_date - CURRENT_DATE)::numeric <= (( SELECT harvest_alert_rules.threshold
               FROM harvest_alert_rules
              WHERE harvest_alert_rules.rule_key = 'weekend_warning_days'::text)) THEN 'PLAN A WEEKEND CREW OR SECOND SHIFT NOW'::text
            ELSE 'Upcoming - plan coverage'::text
        END AS action
   FROM harvest_pulls p
  WHERE (EXTRACT(dow FROM p.harvest_date) = ANY (ARRAY[0::numeric, 6::numeric])) AND p.harvest_date >= (CURRENT_DATE - 14)
UNION ALL
 SELECT 'Dry deadline (day 14)'::text AS event_type,
    NULL::integer AS pull_no,
    m.room,
    m.strains AS detail,
    m.harvest_start + 14 AS event_date,
    TRIM(BOTH FROM to_char((m.harvest_start + 14)::timestamp with time zone, 'Day'::text)) AS falls_on,
    m.harvest_start + 14 - CURRENT_DATE AS days_away,
        CASE
            WHEN (m.harvest_start + 14) < CURRENT_DATE THEN 'PAST - confirm it was finished on time'::text
            WHEN (m.harvest_start + 14 - CURRENT_DATE)::numeric <= (( SELECT harvest_alert_rules.threshold
               FROM harvest_alert_rules
              WHERE harvest_alert_rules.rule_key = 'weekend_warning_days'::text)) THEN 'PLAN A WEEKEND CREW OR SECOND SHIFT NOW'::text
            ELSE 'Upcoming - plan coverage'::text
        END AS action
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND (EXTRACT(dow FROM m.harvest_start + 14) = ANY (ARRAY[0::numeric, 6::numeric]))
  ORDER BY 5;
create or replace view public.v_weight_basis_collisions as
 SELECT relation,
    kind,
    count(DISTINCT basis) AS distinct_bases,
    string_agg(DISTINCT basis, ', '::text ORDER BY basis) AS bases_present,
    count(*) FILTER (WHERE undeclared) AS undeclared_columns,
    bool_or(relation_also_carries_money) AS carries_money
   FROM v_weight_basis_gaps
  GROUP BY relation, kind
 HAVING count(DISTINCT basis) > 1 OR count(*) FILTER (WHERE undeclared) > 0;
create or replace view public.v_year_end_2025_summary as
 SELECT license,
    category,
    count(*)::numeric AS line_items,
    sum(packages) AS packages,
    round(sum(quantity_estimate), 1) AS quantity_estimate,
    round(sum(COALESCE(value_at_cost, 0::numeric)), 2) AS value_at_cost
   FROM v_year_end_2025
  GROUP BY ROLLUP(license, category)
  ORDER BY license, (round(sum(COALESCE(value_at_cost, 0::numeric)), 2)) DESC NULLS LAST;
create or replace view public.v_yield_vs_target as
 SELECT month,
    month_date,
    harvests,
    plants,
    wet_lb,
    waste_lb,
    dried_flower_lb,
    trim_lb,
    fresh_frozen_lb,
    packaged_lb,
    target_lb,
    round(avg(dried_flower_lb) OVER w3, 1) AS rolling_3_month_avg,
    round(avg(dried_flower_lb) OVER w6, 1) AS rolling_6_month_avg,
    round(avg(dried_flower_lb) OVER w3 - target_lb, 1) AS rolling_3_vs_target,
        CASE
            WHEN avg(dried_flower_lb) OVER w3 >= target_lb THEN 'ON TARGET (3-month average)'::text
            ELSE 'BELOW TARGET (3-month average)'::text
        END AS rolling_status,
    flower_vs_target_lb AS this_month_vs_target,
        CASE
            WHEN dried_flower_lb >= target_lb THEN 'met'::text
            ELSE 'below'::text
        END AS this_month_status,
        CASE
            WHEN harvests < 8 THEN (('Only '::text || harvests) || ' harvest(s) closed this month - '::text) || 'the 14-day pull cadence means some months carry fewer. Judge on the rolling average.'::text
            ELSE NULL::text
        END AS caveat,
    how_this_is_counted
   FROM v_monthly_yield m
  WINDOW w3 AS (ORDER BY month_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w6 AS (ORDER BY month_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW);
create or replace view public.v_zone_now as
 SELECT z.id AS zone_id,
    z.name AS zone,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    count(f.employee_id) AS on_floor_now,
    req.headcount_required AS required,
    count(f.employee_id) - COALESCE(req.headcount_required, 0) AS variance,
    round(COALESCE(sum(f.cost_so_far_loaded), 0::numeric), 2) AS cost_so_far_loaded,
    round(COALESCE(avg(f.hours_so_far), 0::numeric), 2) AS avg_hours_so_far,
    count(*) FILTER (WHERE f.licence_lapsed) AS lapsed_licences,
    count(*) FILTER (WHERE COALESCE(f.late_minutes, 0) > 0) AS late_today,
        CASE
            WHEN req.headcount_required IS NULL THEN 'no requirement set'::text
            WHEN count(f.employee_id) < req.headcount_required THEN 'SHORT'::text
            WHEN count(f.employee_id) > req.headcount_required THEN 'over'::text
            ELSE 'on plan'::text
        END AS coverage_flag
   FROM zones z
     LEFT JOIN departments d ON d.id = z.department_id
     LEFT JOIN v_on_the_floor f ON f.zone = z.name
     LEFT JOIN LATERAL ( SELECT r.headcount_required
           FROM zone_staffing_requirements r
          WHERE (r.zone_id = z.id OR r.department_id = z.department_id) AND r.effective_from <= CURRENT_DATE AND (r.effective_to IS NULL OR r.effective_to >= CURRENT_DATE) AND (r.weekday IS NULL OR r.weekday = EXTRACT(dow FROM CURRENT_DATE)::integer)
          ORDER BY r.zone_id, r.effective_from DESC
         LIMIT 1) req ON true
  WHERE z.active
  GROUP BY z.id, z.name, d.name, req.headcount_required;
create materialized view if not exists public.mv_harvest_yields as
 SELECT harvest_name,
    strain,
    room,
    takedown_date,
    finished_on,
    current_stage,
    days_since_takedown,
    planned_pull,
    planned_plants,
    actual_plants,
    projected_lbs,
    actual_wet_lbs,
    actual_packaged_lbs,
    pct_of_projection,
    variance_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    allocation_requests,
    requested_by,
    approved_by,
    allocated_quantity,
    allocated_to,
    allocated_for,
    packages_made,
    manufactured_into,
    still_on_hand,
    sitting_in,
    passed_testing,
    shipped_out,
    lab_state,
    license
   FROM v_metrc_harvest_yields;
create materialized view if not exists public.mv_room_board as
 SELECT room,
    room_type,
    plants_now,
    strains_now,
    weight_on_hand,
    next_event_date,
    next_event,
    days_until,
    next_event_detail,
    plant_capacity,
    cycle_days
   FROM v_room_board;
create or replace view public.v_customer_directory as
 WITH sales AS (
         SELECT COALESCE((m.raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text, m.raw ->> 'RecipientFacilityLicenseNumber'::text) AS facility_licence,
            m.recipient AS name_on_manifest,
            m.is_customer_sale,
            m.is_inbound_purchase,
            m.movement,
            m.operation,
            m.created_on,
            m.manifest_number,
            m.documents,
            m.raw
           FROM v_manifest_ledger m
          WHERE COALESCE(m.recipient, ''::text) !~~* '%twisted%'::text
        ), agg AS (
         SELECT s.facility_licence,
            count(*) FILTER (WHERE s.is_customer_sale) AS customer_sales,
            count(*) FILTER (WHERE s.movement = 'Laboratory sample'::text) AS lab_samples,
            count(*) FILTER (WHERE s.is_customer_sale AND s.operation = 'Cultivation'::text) AS from_cultivation,
            count(*) FILTER (WHERE s.is_customer_sale AND s.operation = 'Manufacturing'::text) AS from_manufacturing,
            min(s.created_on) FILTER (WHERE s.is_customer_sale) AS first_sale,
            max(s.created_on) FILTER (WHERE s.is_customer_sale) AS last_sale,
            sum(((s.raw -> '_delivery'::text) ->> 'DeliveryPackageCount'::text)::integer) FILTER (WHERE s.is_customer_sale) AS packages_shipped,
            max(s.manifest_number) FILTER (WHERE s.is_customer_sale) AS last_manifest,
            count(*) FILTER (WHERE s.is_customer_sale AND s.documents > 0) AS manifests_with_document,
            max(s.name_on_manifest) AS fallback_name
           FROM sales s
          WHERE s.facility_licence IS NOT NULL
          GROUP BY s.facility_licence
        )
 SELECT r.facility_licence,
    COALESCE(r.facility_name, a.fallback_name) AS facility,
    r.facility_type,
    r.company_key,
    initcap(r.company_key) AS company,
    count(*) OVER (PARTITION BY r.company_key) AS sibling_facilities,
    sum(a.customer_sales) OVER (PARTITION BY r.company_key) AS company_total_sales,
    a.customer_sales,
    a.lab_samples,
    a.from_cultivation,
    a.from_manufacturing,
    a.first_sale,
    a.last_sale,
    a.packages_shipped,
    a.last_manifest,
    a.manifests_with_document,
    fc.ship_to_line1,
    fc.ship_to_line2,
    fc.ship_to_town,
    fc.ship_to_postcode,
    fc.contact_name,
    fc.email,
    fc.cc_emails,
    fc.phone,
    fc.delivery_notes,
    fc.receiving_hours,
    fc.terms_days,
    fc.credit_limit,
    fc.do_not_ship,
    fc.updated_at AS contact_updated_at,
        CASE
            WHEN r.facility_type = 'Independent Testing Laboratory'::text THEN 'Testing laboratory - not a customer'::text
            WHEN fc.email IS NOT NULL AND fc.ship_to_line1 IS NOT NULL THEN 'Ready to send'::text
            WHEN fc.email IS NOT NULL THEN 'Email held, ship-to address still needed'::text
            WHEN fc.facility_licence IS NOT NULL THEN 'Started - email still needed'::text
            ELSE 'Nothing on file - staff add it when building the first order'::text
        END AS record_status,
        CASE
            WHEN a.customer_sales = 0 THEN 'No customer sales'::text
            WHEN a.last_sale > (now() - '60 days'::interval) THEN 'Active'::text
            WHEN a.last_sale > (now() - '180 days'::interval) THEN 'Quiet - nothing in 60 days'::text
            ELSE 'Dormant - nothing in 6 months'::text
        END AS trading_status,
    (((r.search_text || ' '::text) || COALESCE(fc.email, ''::text)) || ' '::text) || COALESCE(fc.ship_to_town, ''::text) AS search_text
   FROM v_facility_registry r
     JOIN agg a ON a.facility_licence = r.facility_licence
     LEFT JOIN facility_contacts fc ON fc.facility_licence = r.facility_licence;
create or replace view public.v_findings_rolled as
 SELECT group_key,
    department,
    min(severity_rank) AS severity_rank,
    (array_agg(severity ORDER BY v_findings_live.severity_rank))[1] AS severity,
    count(*) AS occurrences,
    max(owner_name) AS owner_name,
    round(sum(dollars), 0) AS dollars,
    round(sum(pounds), 1) AS pounds,
    min(first_raised)::date AS first_seen,
    max(last_seen)::date AS last_seen,
    (array_agg(what ORDER BY v_findings_live.severity_rank, first_raised))[1] AS example,
    (array_agg(what_to_do ORDER BY v_findings_live.severity_rank) FILTER (WHERE what_to_do IS NOT NULL))[1] AS what_to_do,
    count(*) FILTER (WHERE work_state <> 'open'::text) AS being_worked,
        CASE
            WHEN count(*) = 1 THEN 'single finding'::text
            ELSE count(*) || ' occurrences — drill in to see each one'::text
        END AS scale
   FROM v_findings_live
  WHERE state = 'open'::text AND NOT is_duplicate AND NOT currently_suppressed
  GROUP BY group_key, department;
create or replace view public.v_harvest_accountability as
 WITH h AS (
         SELECT a.harvest,
            a.strain,
            a.room,
            a.finished_on,
            a.licence,
            a.plants,
            a.wet_in_lb,
            a.dry_yield_lb,
            a.wet_g_per_plant,
            a.dry_g_per_plant,
            a.water_pct,
            a.expected_dry_lb_at_target,
            a.vs_target_lb,
            a.vs_target_dollars,
            a.strain_median_dry_g,
            a.strain_harvests,
            a.vs_own_strain_g,
            a.audit_verdict,
            a.concern,
            a.in_plain_english,
            COALESCE('F'::text || "substring"(a.harvest, '(?i)-\s*\d{7,8}.*?f\s*[-]?\s*([1-4])'::text), '(no room in the harvest name)'::text) AS flower_room,
            a.room AS drying_room
           FROM v_harvest_yield_audit a
        )
 SELECT h.harvest,
    h.strain,
    h.flower_room,
    h.drying_room,
    h.finished_on,
    h.plants,
    h.wet_in_lb,
    h.dry_yield_lb,
    h.dry_g_per_plant,
    h.water_pct,
    h.expected_dry_lb_at_target,
    h.vs_target_lb,
    h.vs_target_dollars,
    h.strain_median_dry_g,
    h.vs_own_strain_g,
    h.audit_verdict,
    h.concern,
    COALESCE(g.full_name, 'NOBODY ASSIGNED'::text) AS grower,
    COALESCE(g.basis, 'no grow assignment covers this harvest'::text) AS grower_basis,
    COALESCE(d.full_name, 'NOBODY ASSIGNED'::text) AS dry_room_lead,
    COALESCE(d.basis, 'no dry assignment covers this harvest'::text) AS dry_lead_basis,
        CASE
            WHEN h.audit_verdict ~~ 'YIELD SHORT, drying normal%'::text THEN COALESCE(g.full_name, 'NOBODY ASSIGNED'::text) || ' (grow) — drying was normal, so this is the room or the plants'::text
            WHEN h.audit_verdict ~~ 'CHECK: more weight vanished%'::text THEN COALESCE(d.full_name, 'NOBODY ASSIGNED'::text) || ' (dry room) and whoever weighed at takedown — water loss is above the band'::text
            WHEN h.audit_verdict ~~ 'CHECK: too little water%'::text THEN 'whoever weighed at takedown — the wet weight looks understated'::text
            WHEN h.concern = 'none'::text THEN 'no action'::text
            ELSE 'review with both'::text
        END AS points_at,
    h.in_plain_english
   FROM h
     LEFT JOIN LATERAL f_harvest_accountable(h.harvest, h.flower_room, h.drying_room, h.finished_on, 'grow'::text) g(employee_id, full_name, basis) ON true
     LEFT JOIN LATERAL f_harvest_accountable(h.harvest, h.flower_room, h.drying_room, h.finished_on, 'dry'::text) d(employee_id, full_name, basis) ON true;
create or replace view public.v_harvest_forensic as
 SELECT harvest_name,
    license,
    strain,
    drying_room,
    harvest_type,
    harvest_started,
    first_package_taken_off,
    last_package_taken_off,
    harvest_closed,
    dry_days_to_first_package,
    packaging_window_days,
    total_days_start_to_now,
    plants,
    wet_lb,
    packaged_lb,
    waste_lb,
    still_in_room_lb,
    bud_lb,
    shake_trim_lb,
    categories_made,
    packages_made,
    passed_packages,
    failed_packages,
    untested_packages,
    lab_state,
    on_hold,
    wet_g_per_plant,
    packaged_g_per_plant,
    conversion_pct,
    waste_pct_of_wet,
    wet_to_dry_ratio,
    harvest_state,
    drying_verdict,
    what_is_wrong,
    severity,
    harvest_started AS harvest_started_date
   FROM ( WITH h AS (
                 SELECT metrc_harvests.name AS harvest_name,
                    metrc_harvests.license,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text), '(not recorded)'::text) AS drying_room,
                    metrc_harvests.raw ->> 'HarvestType'::text AS harvest_type,
                    metrc_harvests.harvest_start,
                    (metrc_harvests.raw ->> 'FinishedDate'::text)::date AS finished_date,
                    (metrc_harvests.raw ->> 'PlantCount'::text)::integer AS plants,
                    metrc_harvests.wet_weight AS wet_g,
                    metrc_harvests.waste_weight AS waste_g,
                    (metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric AS packaged_g,
                    (metrc_harvests.raw ->> 'CurrentWeight'::text)::numeric AS current_g,
                    metrc_harvests.package_count,
                    metrc_harvests.raw ->> 'LabTestingState'::text AS lab_state,
                    (metrc_harvests.raw ->> 'IsOnHold'::text)::boolean AS on_hold
                   FROM metrc_harvests
                )
         SELECT h.harvest_name,
            h.license,
            h.strain,
            h.drying_room,
            h.harvest_type,
            h.harvest_start AS harvest_started,
            pk.first_package_on AS first_package_taken_off,
            pk.last_package_on AS last_package_taken_off,
            h.finished_date AS harvest_closed,
            pk.first_package_on - h.harvest_start AS dry_days_to_first_package,
            pk.last_package_on - pk.first_package_on AS packaging_window_days,
            COALESCE(h.finished_date, CURRENT_DATE) - h.harvest_start AS total_days_start_to_now,
            h.plants,
            round(h.wet_g / 453.592, 2) AS wet_lb,
            round(h.packaged_g / 453.592, 2) AS packaged_lb,
            round(h.waste_g / 453.592, 2) AS waste_lb,
            round(h.current_g / 453.592, 2) AS still_in_room_lb,
            pk.bud_lb,
            pk.shake_trim_lb,
            pk.categories_made,
            COALESCE(pk.packages_made, 0::bigint) AS packages_made,
            COALESCE(pk.passed_packages, 0::bigint) AS passed_packages,
            COALESCE(pk.failed_packages, 0::bigint) AS failed_packages,
            COALESCE(pk.untested_packages, 0::bigint) AS untested_packages,
            h.lab_state,
            h.on_hold,
            round(h.wet_g / NULLIF(h.plants, 0)::numeric, 1) AS wet_g_per_plant,
            round(h.packaged_g / NULLIF(h.plants, 0)::numeric, 1) AS packaged_g_per_plant,
            round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1) AS conversion_pct,
            round(h.waste_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1) AS waste_pct_of_wet,
            round(h.wet_g / NULLIF(h.packaged_g, 0::numeric), 2) AS wet_to_dry_ratio,
                CASE
                    WHEN h.finished_date IS NULL THEN 'STILL OPEN - not finished'::text
                    ELSE 'Finished'::text
                END AS harvest_state,
                CASE
                    WHEN pk.first_package_on IS NULL THEN 'NOTHING PACKAGED YET - no dry time can be measured'::text
                    WHEN (pk.first_package_on - h.harvest_start) < 7 THEN ('DRIED TOO FAST: '::text || (pk.first_package_on - h.harvest_start)) || ' days. Under 7 days locks in moisture and chlorophyll - harsh smoke and mould risk.'::text
                    WHEN (pk.first_package_on - h.harvest_start) >= 7 AND (pk.first_package_on - h.harvest_start) <= 16 THEN ('DRY TIME NORMAL: '::text || (pk.first_package_on - h.harvest_start)) || ' days, inside the 10 to 14 day target.'::text
                    WHEN (pk.first_package_on - h.harvest_start) >= 17 AND (pk.first_package_on - h.harvest_start) <= 30 THEN ('DRIED TOO LONG: '::text || (pk.first_package_on - h.harvest_start)) || ' days. Every extra day past 14 burns off saleable weight permanently.'::text
                    ELSE ('DRY TIME FAR OVER: '::text || (pk.first_package_on - h.harvest_start)) || ' days from cut to first package. This is not drying, this is product sitting.'::text
                END AS drying_verdict,
                CASE
                    WHEN h.finished_date IS NULL AND (CURRENT_DATE - h.harvest_start) > 21 THEN ((((('OPEN TOO LONG: cut '::text || (CURRENT_DATE - h.harvest_start)) || ' days ago, still not closed. '::text) || round(h.current_g / 453.592, 2)) || ' lb is sitting in '::text) || h.drying_room) || ' unsold, and its unfinished conversion drags the monthly average down.'::text
                    WHEN h.finished_date IS NULL THEN 'IN PROCESS: normal. Exclude from conversion averages until it closes.'::text
                    WHEN h.plants IS NULL OR h.plants = 0 THEN 'NO PLANT COUNT RECORDED: yield per plant cannot be computed.'::text
                    WHEN h.wet_g = 0::numeric THEN 'NO WET WEIGHT RECORDED: conversion cannot be computed.'::text
                    WHEN h.packaged_g = 0::numeric THEN ('CLOSED WITH ZERO PACKAGED: '::text || round(h.wet_g / 453.592, 2)) || ' lb went in and no package came out. Either weight went unrecorded or the close was premature.'::text
                    WHEN (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) > 0.35 THEN ('CONVERSION IMPLAUSIBLY HIGH at '::text || round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1)) || ' percent. Fresh flower is 75 to 80 percent water, so this means the WET weight was recorded too LOW - not that the harvest did well. Check the takedown scale.'::text
                    WHEN (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) < 0.15 THEN ('CONVERSION LOW at '::text || round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1)) || ' percent against a 20 to 25 percent norm. Either real loss in dry and trim, or the wet weight was recorded too HIGH.'::text
                    ELSE ('NORMAL: '::text || round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1)) || ' percent sits inside the 20 to 25 percent wet-to-packaged norm for indoor flower.'::text
                END AS what_is_wrong,
                CASE
                    WHEN h.finished_date IS NULL AND (CURRENT_DATE - h.harvest_start) > 21 THEN 'CRITICAL'::text
                    WHEN h.finished_date IS NOT NULL AND h.packaged_g = 0::numeric THEN 'CRITICAL'::text
                    WHEN h.finished_date IS NULL THEN 'INFO'::text
                    WHEN h.plants IS NULL OR h.plants = 0 OR h.wet_g = 0::numeric THEN 'HIGH'::text
                    WHEN (pk.first_package_on - h.harvest_start) > 16 OR (pk.first_package_on - h.harvest_start) < 7 THEN 'HIGH'::text
                    WHEN (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) > 0.35 OR (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) < 0.15 THEN 'MEDIUM'::text
                    ELSE 'OK'::text
                END AS severity
           FROM h
             LEFT JOIN mv_harvest_pkg_rollup pk ON pk.harvest_name = h.harvest_name) q;
create or replace view public.v_issue_attribution_summary as
 SELECT issue,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric), 1) AS ours_lb,
    round(COALESCE(sum(dollars) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric)) AS ours_dollars,
    round(COALESCE(sum(pounds) FILTER (WHERE origin <> 'Grown by us'::text), 0::numeric), 1) AS bought_in_lb,
    round(COALESCE(sum(dollars) FILTER (WHERE origin <> 'Grown by us'::text), 0::numeric)) AS recoverable_dollars,
    string_agg(DISTINCT supplier, ', '::text) FILTER (WHERE origin <> 'Grown by us'::text) AS suppliers_involved,
    'Money against bought-in material is potentially recoverable from the supplier. Money against our own material is a genuine loss.'::text AS note
   FROM v_issue_attribution
  GROUP BY issue
  ORDER BY (round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric), 1)) DESC;
create or replace view public.v_late_violations as
 SELECT event_type,
    room,
    cultivars AS detail,
    scheduled_date,
    actual_date,
    days_off_schedule,
        CASE
            WHEN compliance ~~ 'MISSED%'::text THEN 'VIOLATION - never happened'::text
            WHEN compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text THEN 'VIOLATION - ran late'::text
            WHEN compliance ~~ 'Early%'::text THEN 'Acceptable - early'::text
            ELSE 'On schedule'::text
        END AS rule_verdict,
        CASE
            WHEN compliance ~~ 'MISSED%'::text OR compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text THEN 'Every day late pushes the next cycle in this room. Weekend crew or second shift is the remedy, never a slipped date.'::text
            ELSE NULL::text
        END AS why_it_matters
   FROM v_schedule_compliance
  WHERE compliance <> 'Scheduled'::text
  ORDER BY (
        CASE
            WHEN compliance ~~ 'MISSED%'::text THEN 0
            WHEN compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text THEN 1
            ELSE 2
        END), days_off_schedule DESC NULLS LAST;
create or replace view public.v_platform_it as
 WITH sync_state AS (
         SELECT v_all_sync_runs.system,
            max(v_all_sync_runs.started_at) AS last_run,
            count(*) FILTER (WHERE v_all_sync_runs.status ~~* '%err%'::text OR v_all_sync_runs.status ~~* '%fail%'::text) AS failed
           FROM v_all_sync_runs
          WHERE v_all_sync_runs.started_at > (now() - '7 days'::interval)
          GROUP BY v_all_sync_runs.system
        )
 SELECT 'SYNCS'::text AS area,
    'Data coming in'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE sync_state.last_run < (now() - '48:00:00'::interval)) > 0 THEN 'bad'::text
            WHEN count(*) FILTER (WHERE sync_state.failed > 0) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE sync_state.last_run < (now() - '48:00:00'::interval))::text || ' of '::text) || count(*)::text) || ' systems dark over 48h'::text AS headline,
    COALESCE(string_agg((sync_state.system || ' — '::text) ||
        CASE
            WHEN sync_state.last_run IS NULL THEN 'never'::text
            ELSE round(EXTRACT(epoch FROM now() - sync_state.last_run) / 3600::numeric)::text || 'h ago'::text
        END, ' · '::text ORDER BY sync_state.last_run NULLS FIRST) FILTER (WHERE sync_state.last_run < (now() - '48:00:00'::interval)), 'every system has run inside 48 hours'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE sync_state.last_run < (now() - '48:00:00'::interval)) AS bad_items,
    'metrc-sync-runs'::text AS drill
   FROM sync_state
UNION ALL
 SELECT 'SCHEDULED JOBS'::text AS area,
    'Cron'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_cron_health.verdict ~~* '%fail%'::text AND v_cron_health.verdict !~~* '%recover%'::text) > 0 THEN 'bad'::text
            WHEN count(*) FILTER (WHERE v_cron_health.failed_24h > 0) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE v_cron_health.verdict ~~* '%fail%'::text AND v_cron_health.verdict !~~* '%recover%'::text)::text || ' of '::text) || count(*)::text) || ' jobs failing now'::text AS headline,
    COALESCE(string_agg((v_cron_health.jobname || ' — '::text) || v_cron_health.verdict, ' · '::text ORDER BY v_cron_health.hours_since_success DESC) FILTER (WHERE v_cron_health.verdict ~~* '%fail%'::text AND v_cron_health.verdict !~~* '%recover%'::text), 'no scheduled job is currently failing'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE v_cron_health.verdict ~~* '%fail%'::text AND v_cron_health.verdict !~~* '%recover%'::text) AS bad_items,
    'cron_health'::text AS drill
   FROM v_cron_health
  WHERE v_cron_health.active
UNION ALL
 SELECT 'DATA FRESHNESS'::text AS area,
    'Materialised views'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_matview_freshness.verdict ~~* '%stale%'::text OR v_matview_freshness.verdict ~~* '%no refresh%'::text AND NOT v_matview_freshness.has_clock) > 0 THEN 'bad'::text
            WHEN count(*) FILTER (WHERE NOT v_matview_freshness.has_clock) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE NOT v_matview_freshness.has_clock)::text || ' of '::text) || count(*)::text) || ' cannot prove their own freshness (no clock — not the same as stale)'::text AS headline,
    COALESCE(string_agg((v_matview_freshness.matview || ' — '::text) || v_matview_freshness.verdict, ' · '::text ORDER BY v_matview_freshness.matview) FILTER (WHERE NOT v_matview_freshness.has_clock OR v_matview_freshness.verdict ~~* '%stale%'::text), 'every matview carries a clock and is fresh'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE NOT v_matview_freshness.has_clock) AS bad_items,
    'maint:dashboards'::text AS drill
   FROM v_matview_freshness
UNION ALL
 SELECT 'FINDINGS'::text AS area,
    'Watchdog — open now'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_watchdog_current.severity ~~* 'crit%'::text) > 0 THEN 'bad'::text
            WHEN count(*) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*)::text || ' open · '::text) || count(*) FILTER (WHERE v_watchdog_current.severity ~~* 'crit%'::text)::text) || ' critical'::text AS headline,
    COALESCE(string_agg(v_watchdog_current.what, ' · '::text ORDER BY v_watchdog_current.observed_at DESC) FILTER (WHERE v_watchdog_current.severity ~~* 'crit%'::text), 'no critical findings open'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE v_watchdog_current.severity ~~* 'crit%'::text) AS bad_items,
    'intelligence_briefing'::text AS drill
   FROM v_watchdog_current
UNION ALL
 SELECT 'AGENTS'::text AS area,
    'Scheduled agents'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_agent_health.status ~~* '%never%'::text) > 0 THEN 'bad'::text
            WHEN count(*) FILTER (WHERE v_agent_health.status ~~* '%overdue%'::text OR v_agent_health.status ~~* '%late%'::text OR v_agent_health.errors_24h > 0) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE v_agent_health.status ~~* '%never%'::text OR v_agent_health.status ~~* '%overdue%'::text OR v_agent_health.status ~~* '%late%'::text)::text || ' of '::text) || count(*)::text) || ' scheduled agents not reporting'::text AS headline,
    COALESCE(string_agg((v_agent_health.display_name || ' — '::text) || v_agent_health.status, ' · '::text ORDER BY v_agent_health.display_name) FILTER (WHERE v_agent_health.status ~~* '%never%'::text OR v_agent_health.status ~~* '%overdue%'::text OR v_agent_health.status ~~* '%late%'::text), 'every scheduled agent ran inside its window'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE v_agent_health.status ~~* '%never%'::text OR v_agent_health.status ~~* '%overdue%'::text OR v_agent_health.status ~~* '%late%'::text) AS bad_items,
    'agent_health'::text AS drill
   FROM v_agent_health
  WHERE v_agent_health.enabled AND v_agent_health.expected_every_mins IS NOT NULL
UNION ALL
 SELECT 'AGENTS'::text AS area,
    'On-demand agents (invoked, not scheduled)'::text AS subsystem,
    'good'::text AS state,
    count(*)::text || ' lane agents available on demand — no cadence, so never "late"'::text AS headline,
    string_agg(v_agent_health.display_name, ' · '::text ORDER BY v_agent_health.display_name) AS detail,
    count(*) AS items,
    0::bigint AS bad_items,
    'agent_health'::text AS drill
   FROM v_agent_health
  WHERE v_agent_health.enabled AND v_agent_health.expected_every_mins IS NULL
UNION ALL
 SELECT 'REVIEWS'::text AS area,
    'Agents disagreeing'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_agent_agreement.agreement ~~* '%disagree%'::text) > 0 THEN 'bad'::text
            WHEN count(*) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    count(*) FILTER (WHERE v_agent_agreement.agreement ~~* '%disagree%'::text)::text || ' subjects where agents disagree'::text AS headline,
    COALESCE(string_agg((v_agent_agreement.subject || ' — '::text) || COALESCE(v_agent_agreement.what_is_wrong, v_agent_agreement.agreement), ' · '::text ORDER BY v_agent_agreement.pct_apart DESC NULLS LAST) FILTER (WHERE v_agent_agreement.agreement ~~* '%disagree%'::text), 'no open disagreement between agents'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE v_agent_agreement.agreement ~~* '%disagree%'::text) AS bad_items,
    'agent_health'::text AS drill
   FROM v_agent_agreement
UNION ALL
 SELECT 'BRAIN'::text AS area,
    'Written claims vs the database'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE brain_claims.drifted) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE brain_claims.drifted)::text || ' of '::text) || count(*)::text) || ' brain claims have drifted — documents to update, not data that is wrong'::text AS headline,
    COALESCE(string_agg((brain_claims.claim_key || ' — '::text) || brain_claims.brain_file, ' · '::text ORDER BY brain_claims.claim_key) FILTER (WHERE brain_claims.drifted), 'every written claim still matches the database'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE brain_claims.drifted) AS bad_items,
    'intelligence_briefing'::text AS drill
   FROM brain_claims
UNION ALL
 SELECT 'LOOP'::text AS area,
    'Automations'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_loop_health.verdict ~~* '%fail%'::text AND v_loop_health.verdict !~~* '%recover%'::text) > 0 THEN 'bad'::text
            WHEN count(*) FILTER (WHERE v_loop_health.verdict ~~* '%recover%'::text) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE v_loop_health.verdict ~~* '%fail%'::text AND v_loop_health.verdict !~~* '%recover%'::text)::text || ' of '::text) || count(*)::text) || ' loops failing now'::text AS headline,
    COALESCE(string_agg((v_loop_health.jobname || ' — '::text) || v_loop_health.verdict, ' · '::text ORDER BY v_loop_health.jobname) FILTER (WHERE v_loop_health.verdict ~~* '%fail%'::text), 'every loop is running clean'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE v_loop_health.verdict ~~* '%fail%'::text AND v_loop_health.verdict !~~* '%recover%'::text) AS bad_items,
    'cron_health'::text AS drill
   FROM v_loop_health
  WHERE v_loop_health.active
UNION ALL
 SELECT 'SCREEN TRUTH'::text AS area,
    'Tiles vs their own drills'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE v_tile_drill_status.verdict !~~ 'AGREE%'::text) > 0 THEN 'bad'::text
            ELSE 'good'::text
        END AS state,
    ((count(*) FILTER (WHERE v_tile_drill_status.verdict !~~ 'AGREE%'::text)::text || ' of '::text) || count(*)::text) || ' tiles disagree with their own drill'::text AS headline,
    COALESCE(string_agg((v_tile_drill_status.tile_label || ' — '::text) || v_tile_drill_status.verdict, ' · '::text ORDER BY v_tile_drill_status.tile_label) FILTER (WHERE v_tile_drill_status.verdict !~~ 'AGREE%'::text), 'every registered tile reconciles to its drill'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE v_tile_drill_status.verdict !~~ 'AGREE%'::text) AS bad_items,
    'stock_on_hand'::text AS drill
   FROM v_tile_drill_status
UNION ALL
 SELECT 'YOUR DECISIONS'::text AS area,
    'Proposals awaiting you'::text AS subsystem,
        CASE
            WHEN count(*) FILTER (WHERE correction_proposal.severity = 'critical'::text) > 0 THEN 'bad'::text
            WHEN count(*) > 0 THEN 'watch'::text
            ELSE 'good'::text
        END AS state,
    ((count(*)::text || ' waiting · '::text) || count(*) FILTER (WHERE correction_proposal.severity = 'critical'::text)::text) || ' critical'::text AS headline,
    COALESCE(string_agg((correction_proposal.target_object || ' — '::text) || "left"(correction_proposal.the_issue, 90), ' · '::text ORDER BY (
        CASE correction_proposal.severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), correction_proposal.raised_at) FILTER (WHERE correction_proposal.severity = ANY (ARRAY['critical'::text, 'elevated'::text])), 'nothing is waiting on you'::text) AS detail,
    count(*) AS items,
    count(*) FILTER (WHERE correction_proposal.severity = 'critical'::text) AS bad_items,
    'intelligence_briefing'::text AS drill
   FROM correction_proposal
  WHERE correction_proposal.status = 'proposed'::text;
create or replace view public.v_potency_by_strain_analyte as
 SELECT v_potency_analytes.strain,
    v_potency_analytes.product_line,
    v_potency_analytes.analyte,
    v_potency_analytes.yr,
    count(*) AS tests,
    count(DISTINCT v_potency_analytes.package_tag) AS tags,
    round(avg(v_potency_analytes.pct), 2) AS mean_pct,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (v_potency_analytes.pct::double precision))::numeric, 2) AS median_pct,
    round(min(v_potency_analytes.pct), 2) AS min_pct,
    round(max(v_potency_analytes.pct), 2) AS max_pct,
    round(stddev_samp(v_potency_analytes.pct), 2) AS consistency_sd,
    min(v_potency_analytes.test_date) AS first_tested,
    max(v_potency_analytes.test_date) AS last_tested
   FROM v_potency_analytes
  WHERE v_potency_analytes.strain IS NOT NULL
  GROUP BY v_potency_analytes.strain, v_potency_analytes.product_line, v_potency_analytes.analyte, v_potency_analytes.yr
UNION ALL
 SELECT v_potency_tac.strain,
    v_potency_tac.product_line,
    'TAC (computed)'::text AS analyte,
    v_potency_tac.yr,
    count(*) AS tests,
    count(DISTINCT v_potency_tac.package_tag) AS tags,
    round(avg(v_potency_tac.tac_computed), 2) AS mean_pct,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (v_potency_tac.tac_computed::double precision))::numeric, 2) AS median_pct,
    round(min(v_potency_tac.tac_computed), 2) AS min_pct,
    round(max(v_potency_tac.tac_computed), 2) AS max_pct,
    round(stddev_samp(v_potency_tac.tac_computed), 2) AS consistency_sd,
    min(v_potency_tac.test_date) AS first_tested,
    max(v_potency_tac.test_date) AS last_tested
   FROM v_potency_tac
  WHERE v_potency_tac.strain IS NOT NULL AND v_potency_tac.tac_computed > 0::numeric
  GROUP BY v_potency_tac.strain, v_potency_tac.product_line, v_potency_tac.yr;
create or replace view public.v_room_board_complete as
 WITH held AS (
         SELECT o.room,
            max(o.department) AS department,
            max(o.room_role) AS room_role,
            max(o.licence) AS licence,
            round(sum(o.lb), 1) AS lb_held,
            sum(o.tags) AS tags_held,
            sum(o.units) AS units_held,
            round(sum(o.lb) FILTER (WHERE o.ownership !~~* '%our%'::text), 1) AS third_party_lb,
            sum(o.failed) AS failed_tags,
            sum(o.no_coa) AS tags_without_coa,
            count(DISTINCT o.category) AS categories
           FROM v_onhand_by_room_stage o
          GROUP BY o.room
        ), standing AS (
         SELECT x.metrc_location,
            count(*)::numeric AS plants_standing,
            count(DISTINCT x.strain_name)::text AS strains_standing
           FROM ( SELECT COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(none)'::text) AS metrc_location,
                    p.raw ->> 'StrainName'::text AS strain_name
                   FROM metrc_plants p
                  WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text])) x
          GROUP BY x.metrc_location
        ), spine AS (
         SELECT held.room
           FROM held
        UNION
         SELECT v_room_board.room
           FROM v_room_board
        UNION
         SELECT room_alias.our_name
           FROM room_alias
        )
 SELECT sp.room,
    COALESCE(h.department, 'UNASSIGNED'::text) AS department,
    (sp.room || ' — '::text) || COALESCE(h.department, 'UNASSIGNED'::text) AS room_qualified,
    COALESCE(h.room_role, r.room_type, 'Unclassified'::text) AS room_role,
    h.licence,
    COALESCE(a.holds_plants, false) AS is_flower_room,
        CASE
            WHEN COALESCE(a.holds_plants, false) THEN COALESCE(s.plants_standing, 0::numeric)
            ELSE NULL::numeric
        END AS plants_now,
        CASE
            WHEN COALESCE(a.holds_plants, false) THEN COALESCE(s.strains_standing, '0'::text)
            ELSE NULL::text
        END AS strains_now,
    r.cycle_days,
    r.next_event,
    r.next_event_date,
    r.days_until,
    h.lb_held,
    h.tags_held,
    h.units_held,
    h.third_party_lb,
    h.failed_tags,
    h.tags_without_coa,
    h.categories,
        CASE
            WHEN COALESCE(a.holds_plants, false) AND r.days_until IS NOT NULL AND r.days_until < 0::numeric THEN ('OVER — '::text || abs(r.days_until)::integer) || ' days past'::text
            WHEN COALESCE(a.holds_plants, false) AND r.days_until IS NOT NULL AND r.days_until <= 7::numeric THEN ('PULLING — '::text || r.days_until::integer) || ' days'::text
            WHEN COALESCE(a.holds_plants, false) AND COALESCE(s.plants_standing, 0::numeric) > 0::numeric THEN 'ON PLAN'::text
            WHEN COALESCE(a.holds_plants, false) THEN 'TURNING'::text
            WHEN COALESCE(h.lb_held, 0::numeric) > 0::numeric THEN 'HOLDING STOCK'::text
            ELSE 'EMPTY'::text
        END AS state,
        CASE
            WHEN COALESCE(h.failed_tags, 0::numeric) > 0::numeric THEN 'bad'::text
            WHEN COALESCE(a.holds_plants, false) AND r.days_until IS NOT NULL AND r.days_until < 0::numeric THEN 'bad'::text
            WHEN COALESCE(a.holds_plants, false) AND r.days_until IS NOT NULL AND r.days_until <= 7::numeric THEN 'watch'::text
            ELSE 'good'::text
        END AS tone,
    a.metrc_name AS metrc_room_name,
    COALESCE(a.holds_plants, false) AS room_holds_plants,
        CASE
            WHEN NOT COALESCE(a.holds_plants, false) THEN ('Metrc holds no plants in this room by design — it is a '::text || lower(COALESCE(h.room_role, r.room_type, 'post-harvest area'::text))) || '. Material here is tracked by package tag, not by plant.'::text
            WHEN COALESCE(s.plants_standing, 0::numeric) = 0::numeric THEN ('Metrc shows no vegetative or flowering plant in '::text || COALESCE(a.metrc_name, sp.room)) || ' right now — an empty room between cycles is the normal state after a pull.'::text
            ELSE NULL::text
        END AS why_no_plants
   FROM spine sp
     LEFT JOIN held h ON h.room = sp.room
     LEFT JOIN v_room_board r ON r.room = sp.room
     LEFT JOIN room_alias a ON a.our_name = sp.room
     LEFT JOIN standing s ON s.metrc_location = a.metrc_name;
create or replace view public.v_schedule_adherence as
 SELECT event_type,
    room,
    cultivars,
    scheduled_date,
        CASE
            WHEN event_type = 'Pull'::text THEN actual_date
            ELSE NULL::date
        END AS observed_date,
        CASE
            WHEN event_type <> 'Pull'::text THEN NULL::integer
            WHEN actual_date IS NOT NULL THEN actual_date - scheduled_date
            WHEN scheduled_date < CURRENT_DATE THEN CURRENT_DATE - scheduled_date
            ELSE NULL::integer
        END AS days_late,
        CASE
            WHEN event_type <> 'Pull'::text THEN 'NOT MEASURED — this row''s actual date is computed as harvest_start plus the drying window, so it can never differ from plan. Drying adherence is unmeasured, not compliant. The real completion is in metrc_packages.packaged_on and nothing has been wired to it.'::text
            WHEN actual_date IS NULL AND scheduled_date >= CURRENT_DATE THEN 'NOT YET HAPPENED'::text
            WHEN actual_date IS NULL THEN ((('OVERDUE by '::text || (CURRENT_DATE - scheduled_date)) || ' days — VIOLATION, room '::text) || COALESCE(flower_room, room)) || ' is still standing and the count grows daily'::text
            WHEN actual_date < scheduled_date THEN ('EARLY by '::text || (scheduled_date - actual_date)) || ' days — acceptable'::text
            WHEN actual_date = scheduled_date THEN 'ON THE DAY'::text
            ELSE ('LATE by '::text || (actual_date - scheduled_date)) || ' days — VIOLATION'::text
        END AS adherence,
    event_type = 'Pull'::text AND (actual_date > scheduled_date OR actual_date IS NULL AND scheduled_date < CURRENT_DATE) AS is_violation,
    event_type <> 'Pull'::text AS is_unmeasured,
    planned_lbs,
    planned_plants,
    flower_room,
    event_type = 'Pull'::text AND actual_date IS NULL AND scheduled_date < CURRENT_DATE AS is_open_ended
   FROM v_schedule_compliance sc
  WHERE scheduled_date IS NOT NULL;
create or replace view public.v_schedule_cost_detail as
 WITH r AS (
         SELECT ( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'pull_target_dried_lb'::text) AS lb_per_pull,
            ( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'room_cycle_days'::text) AS cycle_days
        ), late AS (
         SELECT sc.room,
            sc.cultivars,
            sc.scheduled_date,
            sc.actual_date,
            sc.actual_date - sc.scheduled_date AS days_late
           FROM v_schedule_compliance sc
          WHERE sc.event_type = 'Pull'::text AND sc.actual_date IS NOT NULL AND sc.scheduled_date IS NOT NULL AND sc.actual_date > sc.scheduled_date
        )
 SELECT l.room,
    l.cultivars,
    l.scheduled_date,
    l.actual_date,
    l.days_late,
    round(r.lb_per_pull / r.cycle_days, 4) AS lb_per_room_day,
    round(l.days_late::numeric * (r.lb_per_pull / r.cycle_days), 1) AS pounds_at_risk,
    cr.cost_per_lb AS cost_per_lb_then,
    round(l.days_late::numeric * (r.lb_per_pull / r.cycle_days) * cr.cost_per_lb, 0) AS dollars_at_risk,
    floor(l.days_late::numeric / r.cycle_days)::integer AS whole_cycles_lost,
    date_trunc('month'::text, l.scheduled_date::timestamp with time zone)::date AS month,
    date_trunc('quarter'::text, l.scheduled_date::timestamp with time zone)::date AS quarter,
    date_trunc('year'::text, l.scheduled_date::timestamp with time zone)::date AS year
   FROM late l
     CROSS JOIN r
     LEFT JOIN LATERAL ( SELECT ic.cost_per_lb
           FROM inventory_cost_rate ic
          WHERE ic.material = 'manufacture_average'::text AND ic.effective_from <= l.scheduled_date AND (ic.effective_to IS NULL OR ic.effective_to >= l.scheduled_date)
          ORDER BY ic.effective_from DESC
         LIMIT 1) cr ON true;
create or replace view public.v_schedule_scorecard as
 SELECT event_type,
    count(*) FILTER (WHERE compliance = 'On schedule'::text OR compliance = 'Dry complete'::text OR compliance = 'Scheduled'::text)::numeric AS on_schedule,
    count(*) FILTER (WHERE compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text)::numeric AS late,
    count(*) FILTER (WHERE compliance ~~ 'MISSED%'::text)::numeric AS missed,
    count(*) FILTER (WHERE compliance ~~ 'Early%'::text)::numeric AS early,
    count(*)::numeric AS total,
    round(100.0 * count(*) FILTER (WHERE compliance = ANY (ARRAY['On schedule'::text, 'Dry complete'::text, 'Scheduled'::text]))::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_on_schedule,
    round(avg(days_off_schedule) FILTER (WHERE days_off_schedule > 0), 1) AS average_days_late
   FROM v_schedule_compliance
  GROUP BY event_type;
create or replace view public.v_schedule_variance as
 SELECT sc.event_type,
    sc.room,
    sc.cultivars,
    sc.scheduled_date,
    sc.actual_date,
    sc.actual_date - sc.scheduled_date AS days_late,
        CASE
            WHEN sc.actual_date IS NULL THEN 'not yet happened'::text
            WHEN sc.actual_date = sc.scheduled_date THEN 'on the day'::text
            WHEN sc.actual_date > sc.scheduled_date THEN (sc.actual_date - sc.scheduled_date) || ' days late'::text
            ELSE abs(sc.actual_date - sc.scheduled_date) || ' days early'::text
        END AS timing,
    v.reason_code,
    rc.label AS reason,
    rc.requires_note,
    v.note,
    v.accountable,
    v.corrective_action,
    v.resolved,
    v.resolved_by,
    v.resolved_at,
    v.recorded_by,
    v.updated_by,
    v.updated_at,
        CASE
            WHEN sc.actual_date IS NULL THEN NULL::text
            WHEN sc.actual_date = sc.scheduled_date THEN NULL::text
            WHEN v.reason_code IS NULL THEN 'No reason recorded yet — only the grower knows why this slipped, and the platform will not invent one.'::text
            ELSE NULL::text
        END AS what_is_missing,
    sc.planned_lbs,
    sc.planned_plants
   FROM v_schedule_compliance sc
     LEFT JOIN schedule_variance v ON v.event_type = sc.event_type AND v.room = sc.room AND v.scheduled_date = sc.scheduled_date
     LEFT JOIN reason_code_catalog rc ON rc.code = v.reason_code
  WHERE sc.scheduled_date IS NOT NULL;
create or replace view public.v_supply_reorder as
 SELECT supply_item_id,
    supply_item,
    supply_category,
    unit,
    vendor,
    lead_time_days,
    on_hand,
    reorder_level,
    reorder_qty,
    safety_stock,
    track_enabled,
    driver,
    required_90d,
        CASE
            WHEN NOT track_enabled THEN 'NOT TRACKED'::text
            WHEN on_hand IS NULL THEN 'NEVER COUNTED'::text
            WHEN reorder_level IS NULL THEN 'NO REORDER LEVEL SET'::text
            WHEN on_hand <= COALESCE(safety_stock, 0::numeric) THEN 'CRITICAL — at or below safety stock'::text
            WHEN on_hand <= reorder_level THEN 'REORDER NOW'::text
            WHEN required_90d IS NOT NULL AND required_90d > 0::numeric AND on_hand < required_90d THEN 'SHORT OF 90-DAY DEMAND'::text
            ELSE 'OK'::text
        END AS status,
        CASE
            WHEN on_hand IS NOT NULL AND reorder_level IS NOT NULL AND on_hand <= reorder_level THEN GREATEST(COALESCE(reorder_qty, reorder_level - on_hand), 0::numeric)
            ELSE NULL::numeric
        END AS suggested_order_qty
   FROM v_supply_demand;
create or replace view public.v_supply_reorder_board as
 SELECT supply_item,
    category,
    vendor,
    unit,
    on_hand,
    on_order,
    available,
    reorder_point_recommended AS reorder_at,
    keep_on_hand_recommended AS keep_on_hand,
    GREATEST(COALESCE(keep_on_hand_recommended, 0::numeric) - COALESCE(available, 0::numeric), 0::numeric) AS order_this_many,
    round(GREATEST(COALESCE(keep_on_hand_recommended, 0::numeric) - COALESCE(available, 0::numeric), 0::numeric) * COALESCE(cost_per_unit, 0::numeric), 2) AS order_cost,
    avg_daily_usage,
    days_of_cover,
    next_arrival,
    open_pos,
    rate_is_provisional,
    status
   FROM v_supply_position
  ORDER BY (
        CASE
            WHEN status ~~ 'REORDER NOW%'::text THEN 1
            WHEN status ~~ 'ON HAND NOT COUNTED%'::text THEN 2
            WHEN status ~~ 'ON ORDER%'::text THEN 3
            ELSE 4
        END), (COALESCE(days_of_cover, 9999::numeric));
create or replace view public.v_trace_breaks as
 SELECT trace_verdict,
    count(*) AS tags,
    round(sum(lb), 2) AS lb,
    sum(units) AS units,
    count(*) FILTER (WHERE harvested_by_ownership = 'THIRD PARTY'::text) AS third_party
   FROM v_trace_completeness
  WHERE trace_verdict ~~ 'FAIL%'::text
  GROUP BY trace_verdict;
create materialized view if not exists public.mv_harvest_dry_stats as
 SELECT harvest_name,
    harvest_started_date,
    harvest_name ~* '\mFF\M'::text AS is_fresh_frozen,
    dry_days_to_first_package
   FROM v_harvest_forensic
  WHERE harvest_started_date IS NOT NULL;
create or replace view public.v_cultivation_scoreboard as
 SELECT v_harvest_accountability.grower AS person,
    'grow'::text AS stage,
    v_harvest_accountability.flower_room AS area,
    count(*) AS harvests,
    sum(v_harvest_accountability.plants) AS plants,
    round(sum(v_harvest_accountability.dry_yield_lb), 1) AS dry_yield_lb,
    round(avg(v_harvest_accountability.dry_g_per_plant), 1) AS avg_g_per_plant,
    70.6 AS target_g_per_plant,
    round(avg(v_harvest_accountability.dry_g_per_plant) - 70.6, 1) AS vs_target_g,
    round(avg(v_harvest_accountability.vs_own_strain_g), 1) AS vs_own_strain_g,
    round(sum(v_harvest_accountability.vs_target_lb), 1) AS vs_target_lb,
    sum(v_harvest_accountability.vs_target_dollars) AS vs_target_dollars,
    round(avg(v_harvest_accountability.water_pct), 1) AS avg_water_pct,
    count(*) FILTER (WHERE v_harvest_accountability.concern <> 'none'::text) AS harvests_of_concern,
    count(*) FILTER (WHERE v_harvest_accountability.audit_verdict ~~ 'CHECK%'::text) AS harvests_flagged,
    min(v_harvest_accountability.finished_on) AS first_harvest,
    max(v_harvest_accountability.finished_on) AS last_harvest
   FROM v_harvest_accountability
  GROUP BY v_harvest_accountability.grower, v_harvest_accountability.flower_room
UNION ALL
 SELECT v_harvest_accountability.dry_room_lead AS person,
    'dry'::text AS stage,
    v_harvest_accountability.drying_room AS area,
    count(*) AS harvests,
    sum(v_harvest_accountability.plants) AS plants,
    round(sum(v_harvest_accountability.dry_yield_lb), 1) AS dry_yield_lb,
    round(avg(v_harvest_accountability.dry_g_per_plant), 1) AS avg_g_per_plant,
    70.6 AS target_g_per_plant,
    round(avg(v_harvest_accountability.dry_g_per_plant) - 70.6, 1) AS vs_target_g,
    round(avg(v_harvest_accountability.vs_own_strain_g), 1) AS vs_own_strain_g,
    round(sum(v_harvest_accountability.vs_target_lb), 1) AS vs_target_lb,
    sum(v_harvest_accountability.vs_target_dollars) AS vs_target_dollars,
    round(avg(v_harvest_accountability.water_pct), 1) AS avg_water_pct,
    count(*) FILTER (WHERE v_harvest_accountability.concern <> 'none'::text) AS harvests_of_concern,
    count(*) FILTER (WHERE v_harvest_accountability.audit_verdict ~~ 'CHECK%'::text) AS harvests_flagged,
    min(v_harvest_accountability.finished_on) AS first_harvest,
    max(v_harvest_accountability.finished_on) AS last_harvest
   FROM v_harvest_accountability
  GROUP BY v_harvest_accountability.dry_room_lead, v_harvest_accountability.drying_room;
create or replace view public.v_dry_room_performance as
 SELECT drying_room,
    count(*) AS harvests,
    sum(plants) AS plants,
    round(sum(wet_lb), 1) AS wet_lb,
    round(sum(packaged_lb), 1) AS packaged_lb,
    round(sum(still_in_room_lb), 1) AS sitting_unfinished_lb,
    round(avg(dry_days_to_first_package), 1) AS avg_dry_days,
    min(dry_days_to_first_package) AS fastest_dry_days,
    max(dry_days_to_first_package) AS slowest_dry_days,
    count(*) FILTER (WHERE dry_days_to_first_package::numeric > f_rule('dry_window_max_days'::text)) AS dried_too_long,
    count(*) FILTER (WHERE dry_days_to_first_package < 7) AS dried_too_fast,
    count(*) FILTER (WHERE harvest_state ~~ 'STILL OPEN%'::text) AS still_open,
    round(sum(packaged_lb) / NULLIF(sum(wet_lb), 0::numeric) * 100::numeric, 1) AS conversion_pct
   FROM v_harvest_forensic
  GROUP BY drying_room
  ORDER BY (sum(plants)) DESC NULLS LAST;
create or replace view public.v_dry_time_discipline as
 WITH rules AS (
         SELECT ( SELECT harvest_alert_rules.threshold
                   FROM harvest_alert_rules
                  WHERE harvest_alert_rules.rule_key = 'dry_target_days'::text) AS lo,
            ( SELECT harvest_alert_rules.threshold
                   FROM harvest_alert_rules
                  WHERE harvest_alert_rules.rule_key = 'dry_max_days'::text) AS hi
        ), scored AS (
         SELECT f.harvest_name,
            f.license,
            f.strain,
            f.drying_room,
            f.harvest_type,
            f.harvest_started,
            f.first_package_taken_off,
            f.last_package_taken_off,
            f.harvest_closed,
            f.dry_days_to_first_package,
            f.packaging_window_days,
            f.total_days_start_to_now,
            f.plants,
            f.wet_lb,
            f.packaged_lb,
            f.waste_lb,
            f.still_in_room_lb,
            f.bud_lb,
            f.shake_trim_lb,
            f.categories_made,
            f.packages_made,
            f.passed_packages,
            f.failed_packages,
            f.untested_packages,
            f.lab_state,
            f.on_hold,
            f.wet_g_per_plant,
            f.packaged_g_per_plant,
            f.conversion_pct,
            f.waste_pct_of_wet,
            f.wet_to_dry_ratio,
            f.harvest_state,
            f.drying_verdict,
            f.what_is_wrong,
            f.severity,
            f.harvest_started_date,
            f.harvest_name ~* '\mFF\M'::text AS is_ff
           FROM v_harvest_forensic f
          WHERE f.harvest_started_date IS NOT NULL
        )
 SELECT to_char(date_trunc('month'::text, s.harvest_started_date::timestamp with time zone), 'YYYY-MM'::text) AS month,
    to_char(date_trunc('month'::text, s.harvest_started_date::timestamp with time zone), 'Mon'::text) AS month_label,
    count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package IS NOT NULL) AS harvests_scored,
    count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package IS NULL) AS harvests_not_yet_packaged,
    count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package::numeric >= r.lo AND s.dry_days_to_first_package::numeric <= r.hi) AS inside_window,
    round(100.0 * count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package::numeric >= r.lo AND s.dry_days_to_first_package::numeric <= r.hi)::numeric / NULLIF(count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package IS NOT NULL), 0)::numeric) AS pct_inside_window,
    round(avg(s.dry_days_to_first_package) FILTER (WHERE NOT s.is_ff), 1) AS avg_dry_days,
    count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package::numeric > r.hi) AS dried_too_long,
    count(*) FILTER (WHERE NOT s.is_ff AND s.dry_days_to_first_package::numeric < r.lo) AS pulled_too_fast,
    r.lo AS window_from_days,
    r.hi AS window_to_days,
    count(*) FILTER (WHERE s.is_ff) AS fresh_frozen_excluded
   FROM scored s
     CROSS JOIN rules r
  GROUP BY (date_trunc('month'::text, s.harvest_started_date::timestamp with time zone)), r.lo, r.hi
  ORDER BY (to_char(date_trunc('month'::text, s.harvest_started_date::timestamp with time zone), 'YYYY-MM'::text));
create or replace view public.v_harvest_issues as
 SELECT v.harvest_name,
    v.license,
    v.strain,
    v.drying_room,
    v.harvest_type,
    v.harvest_started,
    v.first_package_taken_off,
    v.last_package_taken_off,
    v.harvest_closed,
    v.dry_days_to_first_package,
    v.packaging_window_days,
    v.total_days_start_to_now,
    v.plants,
    v.wet_lb,
    v.packaged_lb,
    v.waste_lb,
    v.still_in_room_lb,
    v.bud_lb,
    v.shake_trim_lb,
    v.categories_made,
    v.packages_made,
    v.passed_packages,
    v.failed_packages,
    v.untested_packages,
    v.lab_state,
    v.on_hold,
    v.wet_g_per_plant,
    v.packaged_g_per_plant,
    v.conversion_pct,
    v.waste_pct_of_wet,
    v.wet_to_dry_ratio,
    v.harvest_state,
    v.drying_verdict,
    v.what_is_wrong,
    v.severity,
    v.is_fresh_frozen,
    v.metrc_current_weight_wet_lb,
    v.really_left_dry_lb,
    v.corrected_verdict,
    v.weight_reality_check,
    v.harvest_started_date,
    sm.stage AS stage_now,
    mat.rooms AS material_now_in,
        CASE
            WHEN sm.stage ~~* 'Drying%'::text THEN ('Genuinely drying: '::text || sm.stage) || '.'::text
            WHEN sm.stage IS NOT NULL THEN ('NOT DRYING — this harvest is in '::text || sm.stage) || '. The drying_room column is only where it DRIED.'::text
            ELSE 'No live stage recorded — check whether this harvest should be closed in Metrc.'::text
        END AS process_note
   FROM ( SELECT q.harvest_name,
            q.license,
            q.strain,
            q.drying_room,
            q.harvest_type,
            q.harvest_started,
            q.first_package_taken_off,
            q.last_package_taken_off,
            q.harvest_closed,
            q.dry_days_to_first_package,
            q.packaging_window_days,
            q.total_days_start_to_now,
            q.plants,
            q.wet_lb,
            q.packaged_lb,
            q.waste_lb,
            q.still_in_room_lb,
            q.bud_lb,
            q.shake_trim_lb,
            q.categories_made,
            q.packages_made,
            q.passed_packages,
            q.failed_packages,
            q.untested_packages,
            q.lab_state,
            q.on_hold,
            q.wet_g_per_plant,
            q.packaged_g_per_plant,
            q.conversion_pct,
            q.waste_pct_of_wet,
            q.wet_to_dry_ratio,
            q.harvest_state,
            q.drying_verdict,
            q.what_is_wrong,
            q.severity,
            q.is_fresh_frozen,
            q.metrc_current_weight_wet_lb,
            q.really_left_dry_lb,
            q.corrected_verdict,
            q.weight_reality_check,
            q.harvest_started AS harvest_started_date
           FROM ( WITH r AS (
                         SELECT (f_rule('expected_moisture_pct_min'::text) + f_rule('expected_moisture_pct_max'::text)) / 200.0 AS loss
                        )
                 SELECT h.harvest_name,
                    h.license,
                    h.strain,
                    h.drying_room,
                    h.harvest_type,
                    h.harvest_started,
                    h.first_package_taken_off,
                    h.last_package_taken_off,
                    h.harvest_closed,
                    h.dry_days_to_first_package,
                    h.packaging_window_days,
                    h.total_days_start_to_now,
                    h.plants,
                    h.wet_lb,
                    h.packaged_lb,
                    h.waste_lb,
                    h.still_in_room_lb,
                    h.bud_lb,
                    h.shake_trim_lb,
                    h.categories_made,
                    h.packages_made,
                    h.passed_packages,
                    h.failed_packages,
                    h.untested_packages,
                    h.lab_state,
                    h.on_hold,
                    h.wet_g_per_plant,
                    h.packaged_g_per_plant,
                    h.conversion_pct,
                    h.waste_pct_of_wet,
                    h.wet_to_dry_ratio,
                    h.harvest_state,
                    h.drying_verdict,
                    h.what_is_wrong,
                    h.severity,
                        CASE
                            WHEN h.drying_room = 'Freezer/Biomass Storage'::text OR h.harvest_type ~~* '%fresh%frozen%'::text THEN true
                            ELSE false
                        END AS is_fresh_frozen,
                    round(h.still_in_room_lb, 1) AS metrc_current_weight_wet_lb,
                    GREATEST(round(h.wet_lb * (1::numeric - (( SELECT r.loss
                           FROM r))) - h.packaged_lb, 1), 0::numeric) AS really_left_dry_lb,
                        CASE
                            WHEN h.drying_room = 'Freezer/Biomass Storage'::text OR h.harvest_type ~~* '%fresh%frozen%'::text THEN (('FRESH FROZEN — not a fault. This is packaged wet at field moisture without drying, so '::text || round(h.conversion_pct, 1)) || ' percent recovery is exactly what it should be. The '::text) || 'dried-flower conversion rule does not apply to it and is not being used here.'::text
                            WHEN h.conversion_pct >= 20::numeric AND h.conversion_pct <= 25::numeric THEN ('NORMAL — '::text || round(h.conversion_pct, 1)) || ' percent sits inside the 20 to 25 percent norm.'::text
                            WHEN h.conversion_pct > 25::numeric AND h.conversion_pct <= 35::numeric THEN (('ABOVE THE NORM — '::text || round(h.conversion_pct, 1)) || ' percent is above the 20 to 25 percent '::text) || 'band. Good, unless the wet weight was recorded low.'::text
                            WHEN h.conversion_pct >= 15::numeric AND h.conversion_pct < 20::numeric THEN (('BELOW THE NORM — '::text || round(h.conversion_pct, 1)) || ' percent is under the 20 to 25 percent '::text) || 'band. Weight was lost somewhere between the cut and the package.'::text
                            WHEN h.conversion_pct IS NULL THEN 'NOT YET MEASURABLE — nothing has been packaged off it yet.'::text
                            ELSE (('OUTSIDE ANY NORMAL RANGE — '::text || round(h.conversion_pct, 1)) || ' percent against a 20 to '::text) || '25 percent norm. Check the takedown scale and the packaged weights.'::text
                        END AS corrected_verdict,
                        CASE
                            WHEN h.still_in_room_lb > 0::numeric THEN (((('Metrc shows '::text || round(h.still_in_room_lb, 1)) || ' lb still on this harvest, but that is WET '::text) || 'weight. The dry-equivalent still to come off is about '::text) || GREATEST(round(h.wet_lb * (1::numeric - (( SELECT r.loss
                               FROM r))) - h.packaged_lb, 1), 0::numeric)) || ' lb. The difference is water that evaporated and was never entered as moisture loss.'::text
                            ELSE NULL::text
                        END AS weight_reality_check
                   FROM v_harvest_forensic h
                  WHERE h.severity <> 'OK'::text AND NOT (h.drying_room = 'Freezer/Biomass Storage'::text AND (h.severity = ANY (ARRAY['MEDIUM'::text, 'LOW'::text])))
                  ORDER BY (
                        CASE h.severity
                            WHEN 'CRITICAL'::text THEN 1
                            WHEN 'HIGH'::text THEN 2
                            WHEN 'MEDIUM'::text THEN 3
                            ELSE 4
                        END), h.total_days_start_to_now DESC) q) v
     LEFT JOIN v_harvest_stage_map sm ON sm.harvest = v.harvest_name
     LEFT JOIN LATERAL ( SELECT string_agg(((x.location || ' ('::text) || x.lb) || ' lb)'::text, ' · '::text ORDER BY x.lb DESC) AS rooms
           FROM ( SELECT p.location,
                    round(sum(f_to_pounds(p.quantity, p.uom)), 1) AS lb
                   FROM ( SELECT DISTINCT ON (d.tag) d.id,
                            d.license,
                            d.tag,
                            d.item_name,
                            d.quantity,
                            d.uom,
                            d.location,
                            d.packaged_on,
                            d.lab_testing_state,
                            d.finished,
                            d.raw,
                            d.synced_at,
                            d.source_state,
                            d.provenance,
                            d.report_as_of
                           FROM metrc_packages d
                          ORDER BY d.tag, (COALESCE(d.quantity, 0::numeric) > 0::numeric AND NOT COALESCE((d.raw ->> 'IsFinished'::text)::boolean, false)) DESC, (d.source_state = 'active'::text) DESC NULLS LAST, d.synced_at DESC NULLS LAST) p
                  WHERE (p.raw ->> 'SourceHarvestNames'::text) ~~* (('%'::text || v.harvest_name) || '%'::text) AND COALESCE(p.quantity, 0::numeric) > 0::numeric AND COALESCE(p.finished, false) = false
                  GROUP BY p.location
                  ORDER BY (round(sum(f_to_pounds(p.quantity, p.uom)), 1)) DESC
                 LIMIT 4) x) mat ON true;
create or replace view public.v_harvest_mass_ledger as
 SELECT harvest_name,
    harvest_started,
    harvest_closed,
    drying_room,
    strain,
    plants,
    harvest_state,
    line_1_wet_weight_in,
    line_2_water_evaporated,
    line_3_dry_weight_available,
    line_4_packaged_out,
    line_5_waste_recorded,
    line_6_still_to_package,
    line_7_metrc_still_shows,
    line_8_water_not_yet_entered,
    line_9_water_recorded_by_us,
    line_10_entered_in_metrc,
    metrc_adjustment_ref,
    conversion_pct_of_wet,
    recovery_pct_of_dry,
    the_full_arithmetic,
    harvest_started AS harvest_started_date
   FROM ( WITH r AS (
                 SELECT (f_rule('expected_moisture_pct_min'::text) + f_rule('expected_moisture_pct_max'::text)) / 200.0 AS loss
                )
         SELECT h.harvest_name,
            h.harvest_started,
            h.harvest_closed,
            h.drying_room,
            h.strain,
            h.plants,
                CASE
                    WHEN h.harvest_closed IS NOT NULL THEN 'CLOSED'::text
                    ELSE 'OPEN'::text
                END AS harvest_state,
            round(h.wet_lb, 1) AS line_1_wet_weight_in,
            round(h.wet_lb * (( SELECT r.loss
                   FROM r)), 1) AS line_2_water_evaporated,
            round(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))), 1) AS line_3_dry_weight_available,
            round(h.packaged_lb, 1) AS line_4_packaged_out,
            round(h.waste_lb, 1) AS line_5_waste_recorded,
            GREATEST(round(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))) - h.packaged_lb - COALESCE(h.waste_lb, 0::numeric), 1), 0::numeric) AS line_6_still_to_package,
            round(h.still_in_room_lb, 1) AS line_7_metrc_still_shows,
            GREATEST(round(h.still_in_room_lb - GREATEST(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))) - h.packaged_lb, 0::numeric), 1), 0::numeric) AS line_8_water_not_yet_entered,
            COALESCE(e.moisture_loss_lb, 0::numeric) AS line_9_water_recorded_by_us,
            e.recorded_in_metrc AS line_10_entered_in_metrc,
            e.metrc_adjustment_ref,
            round(100.0 * h.packaged_lb / NULLIF(h.wet_lb, 0::numeric), 1) AS conversion_pct_of_wet,
            round(100.0 * h.packaged_lb / NULLIF(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))), 0::numeric), 1) AS recovery_pct_of_dry,
            ((((((((((((((('Wet in '::text || round(h.wet_lb, 1)) || ' lb, less water '::text) || round(h.wet_lb * (( SELECT r.loss
                   FROM r)), 1)) || ' lb, leaves '::text) || round(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))), 1)) || ' lb dry. Packaged '::text) || round(h.packaged_lb, 1)) || ' lb and wasted '::text) || round(COALESCE(h.waste_lb, 0::numeric), 1)) || ' lb, so '::text) || GREATEST(round(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))) - h.packaged_lb - COALESCE(h.waste_lb, 0::numeric), 1), 0::numeric)) || ' lb is still to come off. Metrc shows '::text) || round(h.still_in_room_lb, 1)) || ' lb because '::text) || GREATEST(round(h.still_in_room_lb - GREATEST(h.wet_lb * (1::numeric - (( SELECT r.loss
                   FROM r))) - h.packaged_lb, 0::numeric), 1), 0::numeric)) || ' lb of water has not been entered there yet.'::text AS the_full_arithmetic
           FROM v_harvest_forensic h
             LEFT JOIN LATERAL ( SELECT m.id,
                    m.harvest_name,
                    m.wet_lb_at_entry,
                    m.packaged_lb_at_entry,
                    m.metrc_showed_lb,
                    m.moisture_loss_lb,
                    m.method,
                    m.recorded_in_metrc,
                    m.metrc_adjustment_ref,
                    m.entered_by,
                    m.entered_at,
                    m.note
                   FROM moisture_loss_entries m
                  WHERE m.harvest_name = h.harvest_name
                  ORDER BY m.entered_at DESC
                 LIMIT 1) e ON true
          WHERE h.wet_lb > 0::numeric
          ORDER BY (
                CASE
                    WHEN h.harvest_closed IS NOT NULL THEN 0
                    ELSE 1
                END), h.harvest_started DESC) q;
create or replace view public.v_harvest_still_in_room as
 WITH r AS (
         SELECT (f_rule('expected_moisture_pct_min'::text) + f_rule('expected_moisture_pct_max'::text)) / 200.0 AS loss
        )
 SELECT harvest_name,
    harvest_started,
    drying_room,
    total_days_start_to_now AS days_open,
    last_package_taken_off,
    round(wet_lb, 1) AS wet_lb,
    round(wet_lb * (1::numeric - (( SELECT r.loss
           FROM r))), 1) AS expected_dry_lb,
    round(packaged_lb, 1) AS packaged_lb,
    round(waste_lb, 1) AS waste_lb,
    round(still_in_room_lb, 1) AS old_figure_wet_minus_dry,
    GREATEST(round(wet_lb * (1::numeric - (( SELECT r.loss
           FROM r))) - packaged_lb, 1), 0::numeric) AS really_left_lb,
    CURRENT_DATE - last_package_taken_off AS days_since_last_package,
        CASE
            WHEN (wet_lb * (1::numeric - (( SELECT r.loss
               FROM r))) - packaged_lb) <= 0.5 THEN ((('Nothing meaningful left. The dry yield this harvest should give ('::text || round(wet_lb * (1::numeric - (( SELECT r.loss
               FROM r))), 1)) || ' lb) has already been packaged ('::text) || round(packaged_lb, 1)) || ' lb). It is open in Metrc only because nobody closed it out.'::text
            WHEN (CURRENT_DATE - last_package_taken_off) <= 7 THEN ((round(wet_lb * (1::numeric - (( SELECT r.loss
               FROM r))) - packaged_lb, 1) || ' lb of dry yield still to come off, and packages were taken off '::text) || (CURRENT_DATE - last_package_taken_off)) || ' days ago — this harvest is still working.'::text
            ELSE (((round(wet_lb * (1::numeric - (( SELECT r.loss
               FROM r))) - packaged_lb, 1) || ' lb of dry yield unaccounted for, and nothing has been packaged off it for '::text) || (CURRENT_DATE - last_package_taken_off)) || ' days. Either it is sitting forgotten, '::text) || 'or the wet weight was recorded too high.'::text
        END AS what_it_really_means
   FROM v_harvest_forensic h
  WHERE harvest_closed IS NULL
  ORDER BY total_days_start_to_now DESC;
create or replace view public.v_issue_late as
 SELECT event_type,
    room,
    detail,
    scheduled_date,
    actual_date,
    days_off_schedule,
    rule_verdict,
    ('THE ISSUE: '::text || rule_verdict) || '. Late is never acceptable under the standing rule.'::text AS what_is_wrong,
    'Weekend crew or a second shift - never a slipped date. Review with the cultivation lead.'::text AS what_to_do
   FROM v_late_violations
  WHERE rule_verdict ~~ 'VIOLATION%'::text
  ORDER BY days_off_schedule DESC NULLS LAST;
create or replace view public.v_moisture_loss_register as
 WITH r AS (
         SELECT (f_rule('expected_moisture_pct_min'::text) + f_rule('expected_moisture_pct_max'::text)) / 200.0 AS loss
        )
 SELECT h.harvest_name,
    h.harvest_started,
    h.harvest_closed,
    h.drying_room,
    h.strain,
    round(h.wet_lb, 1) AS wet_lb,
    round(h.packaged_lb, 1) AS packaged_lb,
    round(h.waste_lb, 1) AS waste_lb,
    round(h.still_in_room_lb, 1) AS metrc_shows_remaining_lb,
    round(h.wet_lb * (( SELECT r.loss
           FROM r)), 1) AS expected_moisture_loss_lb,
    GREATEST(round(h.wet_lb * (1::numeric - (( SELECT r.loss
           FROM r))) - h.packaged_lb, 1), 0::numeric) AS really_left_lb,
        CASE
            WHEN mx.moisture_loss_lb IS NOT NULL AND mx.moisture_loss_lb > 0::numeric THEN 0::numeric
            ELSE GREATEST(round(h.still_in_room_lb - GREATEST(h.wet_lb * (1::numeric - (( SELECT r.loss
               FROM r))) - h.packaged_lb, 0::numeric), 1), 0::numeric)
        END AS phantom_lb,
        CASE
            WHEN h.harvest_closed IS NOT NULL THEN 'CLOSED'::text
            ELSE 'OPEN'::text
        END AS harvest_state,
    COALESCE(mx.moisture_loss_lb, e.moisture_loss_lb) AS recorded_loss_lb,
    COALESCE(e.method,
        CASE
            WHEN mx.moisture_loss_lb IS NOT NULL THEN 'Metrc Harvests-Inactive report'::text
            ELSE NULL::text
        END) AS recorded_method,
    COALESCE(e.entered_by,
        CASE
            WHEN mx.moisture_loss_lb IS NOT NULL THEN 'recorded in Metrc'::text
            ELSE NULL::text
        END) AS entered_by,
    COALESCE(e.entered_at::date, mx.finished_on) AS recorded_on,
    COALESCE(e.recorded_in_metrc, mx.moisture_loss_lb IS NOT NULL) AS recorded_in_metrc,
    e.metrc_adjustment_ref,
    e.note AS recorded_note,
    e.id IS NULL AND COALESCE(mx.moisture_loss_lb, 0::numeric) = 0::numeric AS needs_recording,
        CASE
            WHEN mx.moisture_loss_lb IS NOT NULL AND mx.moisture_loss_lb > 0::numeric THEN (((('RECORDED IN METRC — '::text || round(mx.moisture_loss_lb, 1)) || ' lb of moisture loss on the Harvests-Inactive report ('::text) || round(COALESCE(mx.moisture_pct, 0::numeric), 1)) || '%). Nothing to do. The Metrc API carries '::text) || 'no moisture field, only a residual, which is why the remaining weight still shows.'::text
            WHEN mx.harvest_batch IS NOT NULL AND f_harvest_is_fresh_frozen(h.harvest_name) THEN 'FRESH FROZEN — packaged wet and never dried, so zero moisture loss is CORRECT. '::text || 'Not a gap.'::text
            WHEN e.id IS NULL AND h.harvest_closed IS NOT NULL THEN 'NOT IN METRC — closed harvest with no moisture loss on the Harvests-Inactive '::text || 'report. Record it in Metrc against this harvest.'::text
            WHEN e.id IS NULL THEN 'OPEN HARVEST — still packaging off, so remaining weight is expected. Moisture is '::text || 'only recorded when the harvest closes.'::text
            WHEN NOT e.recorded_in_metrc THEN ((((((('RECORDED HERE, NOT YET IN METRC — '::text || e.moisture_loss_lb) || ' lb entered by '::text) || e.entered_by) || ' on '::text) || e.entered_at::date) || ' by '::text) || e.method) || '.'::text
            ELSE ((((((((('DONE — '::text || e.moisture_loss_lb) || ' lb by '::text) || e.method) || ', entered by '::text) || e.entered_by) || ' on '::text) || e.entered_at::date) || ', Metrc adjustment '::text) || e.metrc_adjustment_ref) || '.'::text
        END AS status
   FROM v_harvest_forensic h
     LEFT JOIN LATERAL ( SELECT m.harvest_batch,
            m.moisture_loss_lb,
            m.moisture_pct,
            m.finished_on
           FROM metrc_rpt_harvest_moisture m
          WHERE m.harvest_batch = h.harvest_name
          ORDER BY m.imported_at DESC
         LIMIT 1) mx ON true
     LEFT JOIN LATERAL ( SELECT m.id,
            m.harvest_name,
            m.wet_lb_at_entry,
            m.packaged_lb_at_entry,
            m.metrc_showed_lb,
            m.moisture_loss_lb,
            m.method,
            m.recorded_in_metrc,
            m.metrc_adjustment_ref,
            m.entered_by,
            m.entered_at,
            m.note
           FROM moisture_loss_entries m
          WHERE m.harvest_name = h.harvest_name
          ORDER BY m.entered_at DESC
         LIMIT 1) e ON true
  WHERE h.still_in_room_lb > 0::numeric AND h.wet_lb > 0::numeric
  ORDER BY (
        CASE
            WHEN h.harvest_closed IS NOT NULL THEN 0
            ELSE 1
        END), (e.id IS NULL) DESC, (h.still_in_room_lb - GREATEST(h.wet_lb * (1::numeric - (( SELECT r.loss
           FROM r))) - h.packaged_lb, 0::numeric)) DESC;
create or replace view public.v_monthly_conversion_truth as
 SELECT to_char(harvest_started::timestamp with time zone, 'YYYY-MM'::text) AS month,
    count(*) AS harvests_cut,
    count(*) FILTER (WHERE harvest_state = 'Finished'::text) AS harvests_closed,
    count(*) FILTER (WHERE harvest_state ~~ 'STILL OPEN%'::text) AS still_open,
    sum(plants) AS plants,
    round(sum(wet_lb), 1) AS wet_lb,
    round(sum(packaged_lb), 1) AS packaged_lb,
    round(sum(still_in_room_lb), 1) AS sitting_unfinished_lb,
    round(sum(packaged_lb) FILTER (WHERE harvest_state = 'Finished'::text) / NULLIF(sum(wet_lb) FILTER (WHERE harvest_state = 'Finished'::text), 0::numeric) * 100::numeric, 1) AS conversion_pct_closed_only,
    round(avg(dry_days_to_first_package), 1) AS avg_dry_days,
    count(*) FILTER (WHERE dry_days_to_first_package > 16) AS dried_too_long,
    count(*) FILTER (WHERE dry_days_to_first_package < 7) AS dried_too_fast,
        CASE
            WHEN count(*) FILTER (WHERE harvest_state ~~ 'STILL OPEN%'::text) > 0 THEN ((count(*) FILTER (WHERE harvest_state ~~ 'STILL OPEN%'::text) || ' of '::text) || count(*)) || ' harvests from this month are still open. This month CANNOT be judged yet.'::text
            WHEN round(sum(packaged_lb) / NULLIF(sum(wet_lb), 0::numeric) * 100::numeric, 1) >= 20::numeric AND round(sum(packaged_lb) / NULLIF(sum(wet_lb), 0::numeric) * 100::numeric, 1) <= 28::numeric THEN 'NORMAL. Inside the 20-25 percent commercial norm.'::text
            WHEN round(sum(packaged_lb) / NULLIF(sum(wet_lb), 0::numeric) * 100::numeric, 1) > 30::numeric THEN 'SUSPECT HIGH. Check whether wet weight was recorded low at takedown.'::text
            ELSE 'BELOW NORM. Investigate dry duration and trim standard.'::text
        END AS how_to_read_this_month
   FROM v_harvest_forensic
  WHERE harvest_started IS NOT NULL
  GROUP BY (to_char(harvest_started::timestamp with time zone, 'YYYY-MM'::text))
  ORDER BY (to_char(harvest_started::timestamp with time zone, 'YYYY-MM'::text)) DESC;
create or replace view public.v_overdue_harvests as
 SELECT harvest_name,
    harvest_started,
    drying_room,
    strain,
    plants,
    total_days_start_to_now AS days_open,
    f_rule('harvest_open_max_days'::text) AS limit_days,
    total_days_start_to_now::numeric - f_rule('harvest_open_max_days'::text) AS days_over,
    last_package_taken_off,
    CURRENT_DATE - last_package_taken_off AS days_since_last_package,
    round(packaged_lb, 1) AS packaged_lb,
    (((((((((('Cut '::text || harvest_started) || ', still open after '::text) || total_days_start_to_now) || ' days against the '::text) || f_rule('harvest_open_max_days'::text)) || ' day limit from the 2026 harvest '::text) || 'calendar — '::text) || (total_days_start_to_now::numeric - f_rule('harvest_open_max_days'::text))) || ' days over. '::text) ||
        CASE
            WHEN last_package_taken_off IS NULL THEN 'Nothing has ever been packaged off it.'::text
            ELSE ((('Last package taken off '::text || last_package_taken_off) || ', '::text) || (CURRENT_DATE - last_package_taken_off)) || ' days ago.'::text
        END) || ' Finish packaging it and close it out in Metrc.'::text AS what_to_do
   FROM v_harvest_forensic h
  WHERE harvest_closed IS NULL AND total_days_start_to_now::numeric > f_rule('harvest_open_max_days'::text)
  ORDER BY total_days_start_to_now DESC;
create or replace view public.v_plan_vs_actual_harvest as
 SELECT p.pull_no,
    p.harvest_date AS planned_date,
    p.day_of_week,
    p.flower_room,
    p.room_cycle_no,
    p.planned_plants,
    round(p.projected_harvest_lb, 1) AS projected_lb,
    round(p.projected_fresh_frozen_lb, 1) AS projected_fresh_frozen_lb,
    round(p.projected_flower_after_ff_lb, 1) AS projected_flower_lb,
    a.actual_date,
    a.actual_plants,
    round(a.actual_wet_lb, 1) AS actual_wet_lb,
    round(a.actual_packaged_lb, 1) AS actual_packaged_lb,
    a.harvests_recorded,
    a.actual_date - p.harvest_date AS days_off_plan,
    round(a.actual_packaged_lb - p.projected_harvest_lb, 1) AS pounds_vs_plan,
    round(a.actual_wet_lb * 453.592 / NULLIF(a.actual_plants, 0)::numeric, 1) AS actual_wet_g_per_plant,
    round(p.projected_harvest_g / NULLIF(p.planned_plants, 0::numeric), 1) AS planned_g_per_plant,
        CASE
            WHEN a.actual_date IS NULL AND p.harvest_date > CURRENT_DATE THEN 'SCHEDULED — not due yet'::text
            WHEN a.actual_date IS NULL THEN ((('MISSED — planned for '::text || p.harvest_date) || ' and no harvest is recorded in Metrc for '::text) || p.flower_room) || ' near that date.'::text
            WHEN abs(a.actual_date - p.harvest_date) <= 3 THEN ((('ON PLAN — pulled '::text || a.actual_date) || ', within three days of the planned '::text) || p.harvest_date) || '.'::text
            WHEN a.actual_date > p.harvest_date THEN ('LATE — pulled '::text || (a.actual_date - p.harvest_date)) || ' days after plan. Every late pull pushes the next cycle in this room.'::text
            ELSE ('EARLY — pulled '::text || (p.harvest_date - a.actual_date)) || ' days before plan.'::text
        END AS schedule_verdict
   FROM harvest_plan_2026 p
     LEFT JOIN LATERAL ( SELECT min(f.harvest_started) AS actual_date,
            sum(f.plants) AS actual_plants,
            sum(f.wet_lb) AS actual_wet_lb,
            sum(f.packaged_lb) AS actual_packaged_lb,
            count(*) AS harvests_recorded
           FROM v_harvest_forensic f
          WHERE f.harvest_name ~~* ('%'::text || p.flower_room) AND f.harvest_started >= (p.harvest_date - 10) AND f.harvest_started <= (p.harvest_date + 10)) a ON true
  ORDER BY p.pull_no;
create or replace view public.v_real_loss_v2 as
 WITH f AS (
         SELECT ( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text) AS cost,
            ( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'dry_window_max_days'::text) AS dmax,
            ( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'dry_window_min_days'::text) AS dmin
        ), bench AS (
         SELECT round(avg(v_harvest_forensic.conversion_pct), 1) AS good_conv
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.harvest_state = 'Finished'::text AND v_harvest_forensic.conversion_pct >= 10::numeric AND v_harvest_forensic.conversion_pct <= 35::numeric AND v_harvest_forensic.dry_days_to_first_package::numeric >= (( SELECT f.dmin
                   FROM f)) AND v_harvest_forensic.dry_days_to_first_package::numeric <= (( SELECT f.dmax
                   FROM f)) AND v_harvest_forensic.harvest_name !~~* '%FF%'::text
        ), failed_ours AS (
         SELECT 'Failed testing - our own material'::text AS loss_type,
            'OURS - genuine loss'::text AS whose,
            'CERTAIN'::text AS confidence,
            sum(v_stock_on_hand.packages) AS occurrences,
            round(sum(v_stock_on_hand.pounds), 1) AS pounds,
            round(sum(v_stock_on_hand.pounds) * (( SELECT f.cost
                   FROM f))) AS dollars,
            'We grew it, packaged it, and it failed. It cannot be sold as flower.'::text AS why_it_is_a_loss,
            'our failed pounds x cost per pound'::text AS the_arithmetic,
            'failed_testing_by_origin'::text AS drill
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND v_stock_on_hand.origin = 'Grown by us'::text
         HAVING sum(v_stock_on_hand.packages) > 0::numeric
        ), failed_supplier AS (
         SELECT 'Failed testing - bought as sound material'::text AS loss_type,
            'SUPPLIER - raise it with them'::text AS whose,
            'CERTAIN'::text AS confidence,
            sum(s.packages) AS occurrences,
            round(sum(s.pounds), 1) AS pounds,
            round(sum(s.pounds) * (( SELECT f.cost
                   FROM f))) AS dollars,
            'Purchased as sound material and failed. Recoverable from the supplier.'::text AS why_it_is_a_loss,
            'failed pounds bought as sound x cost per pound'::text AS the_arithmetic,
            'failed_testing_by_origin'::text AS drill
           FROM v_stock_on_hand s
             JOIN purchase_intent i ON i.origin_license = s.origin_license
          WHERE s.lab_state = 'TestFailed'::text AND i.bought_as = 'sound material'::text
         HAVING sum(s.packages) > 0::numeric
        ), drytime AS (
         SELECT 'Weight lost to over-drying'::text AS loss_type,
            'OURS - genuine loss'::text AS whose,
            'ESTIMATE'::text AS confidence,
            count(*) AS occurrences,
            round(sum(GREATEST(0::numeric, v_harvest_forensic.wet_lb * ((( SELECT bench.good_conv
                   FROM bench)) - v_harvest_forensic.conversion_pct) / 100::numeric)), 1) AS pounds,
            round(sum(GREATEST(0::numeric, v_harvest_forensic.wet_lb * ((( SELECT bench.good_conv
                   FROM bench)) - v_harvest_forensic.conversion_pct) / 100::numeric)) * (( SELECT f.cost
                   FROM f))) AS dollars,
            ('Harvests dried past the '::text || (( SELECT f.dmax
                   FROM f))) || ' day window converted below those that dried inside it.'::text AS why_it_is_a_loss,
            ('wet lb x (benchmark '::text || (( SELECT bench.good_conv
                   FROM bench))) || '% minus own conversion) x cost per pound'::text AS the_arithmetic,
            'harvest_issues'::text AS drill
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.harvest_state = 'Finished'::text AND v_harvest_forensic.harvest_name !~~* '%FF%'::text AND v_harvest_forensic.dry_days_to_first_package::numeric > (( SELECT f.dmax
                   FROM f)) AND v_harvest_forensic.conversion_pct IS NOT NULL AND v_harvest_forensic.conversion_pct < (( SELECT bench.good_conv
                   FROM bench))
        ), zeropkg AS (
         SELECT 'Closed with nothing packaged'::text AS loss_type,
            'OURS - needs investigation'::text AS whose,
            'NEEDS INVESTIGATION'::text AS confidence,
            count(*) AS occurrences,
            round(sum(v_harvest_forensic.wet_lb * (( SELECT bench.good_conv
                   FROM bench)) / 100::numeric), 1) AS pounds,
            round(sum(v_harvest_forensic.wet_lb * (( SELECT bench.good_conv
                   FROM bench)) / 100::numeric) * (( SELECT f.cost
                   FROM f))) AS dollars,
            'Marked finished with no package ever taken off.'::text AS why_it_is_a_loss,
            'wet lb x benchmark conversion x cost per pound'::text AS the_arithmetic,
            'harvest_issues'::text AS drill
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.harvest_state = 'Finished'::text AND COALESCE(v_harvest_forensic.packaged_lb, 0::numeric) = 0::numeric AND v_harvest_forensic.wet_lb > 0::numeric AND v_harvest_forensic.harvest_name !~~* '%FF%'::text
        )
 SELECT failed_ours.loss_type,
    failed_ours.whose,
    failed_ours.confidence,
    failed_ours.occurrences,
    failed_ours.pounds,
    failed_ours.dollars,
    failed_ours.why_it_is_a_loss,
    failed_ours.the_arithmetic,
    failed_ours.drill
   FROM failed_ours
UNION ALL
 SELECT failed_supplier.loss_type,
    failed_supplier.whose,
    failed_supplier.confidence,
    failed_supplier.occurrences,
    failed_supplier.pounds,
    failed_supplier.dollars,
    failed_supplier.why_it_is_a_loss,
    failed_supplier.the_arithmetic,
    failed_supplier.drill
   FROM failed_supplier
UNION ALL
 SELECT drytime.loss_type,
    drytime.whose,
    drytime.confidence,
    drytime.occurrences,
    drytime.pounds,
    drytime.dollars,
    drytime.why_it_is_a_loss,
    drytime.the_arithmetic,
    drytime.drill
   FROM drytime
UNION ALL
 SELECT zeropkg.loss_type,
    zeropkg.whose,
    zeropkg.confidence,
    zeropkg.occurrences,
    zeropkg.pounds,
    zeropkg.dollars,
    zeropkg.why_it_is_a_loss,
    zeropkg.the_arithmetic,
    zeropkg.drill
   FROM zeropkg
  ORDER BY 6 DESC NULLS LAST;
create or replace view public.v_room_contents as
 WITH loc AS (
         SELECT DISTINCT metrc_locations.license,
            metrc_locations.name
           FROM metrc_locations
        ), pkg AS (
         SELECT metrc_packages.license,
            metrc_packages.location AS name,
            count(*) AS packages,
            round(sum(f_to_pounds(metrc_packages.quantity, metrc_packages.uom)) FILTER (WHERE f_is_weight(metrc_packages.uom)), 1) AS packaged_dry_lb,
            sum(metrc_packages.quantity) FILTER (WHERE NOT f_is_weight(metrc_packages.uom)) AS packaged_units,
            count(*) FILTER (WHERE COALESCE(metrc_packages.finished, false)) AS finished_packages
           FROM metrc_packages
          WHERE metrc_packages.location IS NOT NULL
          GROUP BY metrc_packages.license, metrc_packages.location
        ), pl AS (
         SELECT metrc_plants.license,
            metrc_plants.room AS name,
            count(*) AS plants,
            string_agg(DISTINCT metrc_plants.strain, ', '::text) AS plant_strains
           FROM metrc_plants
          WHERE metrc_plants.room IS NOT NULL
          GROUP BY metrc_plants.license, metrc_plants.room
        ), harv AS (
         SELECT v_harvest_forensic.license,
            v_harvest_forensic.drying_room AS name,
            count(*) FILTER (WHERE v_harvest_forensic.harvest_state ~~ 'STILL OPEN%'::text) AS open_harvests,
            round(sum(v_harvest_forensic.still_in_room_lb) FILTER (WHERE v_harvest_forensic.harvest_state ~~ 'STILL OPEN%'::text), 1) AS unpackaged_wet_lb
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.drying_room IS NOT NULL
          GROUP BY v_harvest_forensic.license, v_harvest_forensic.drying_room
        ), tp AS (
         SELECT v_third_party_stock.held_under AS license,
            v_third_party_stock.location AS name,
            sum(v_third_party_stock.packages)::bigint AS third_party_packages,
            round(sum(v_third_party_stock.pounds), 1) AS third_party_dry_lb,
            string_agg(DISTINCT v_third_party_stock.supplier, ', '::text) AS third_party_suppliers
           FROM v_third_party_stock
          WHERE v_third_party_stock.location IS NOT NULL
          GROUP BY v_third_party_stock.held_under, v_third_party_stock.location
        )
 SELECT l.license,
    l.name AS location,
    COALESCE(pl.plants, 0::bigint) AS plants,
    pl.plant_strains,
    COALESCE(h.open_harvests, 0::bigint) AS open_harvests,
    COALESCE(h.unpackaged_wet_lb, 0::numeric) AS unpackaged_wet_lb,
    round(COALESCE(h.unpackaged_wet_lb, 0::numeric) * (1::numeric - f_rule('expected_moisture_pct_max'::text) / 100.0), 1) AS unpackaged_dry_equiv_low,
    round(COALESCE(h.unpackaged_wet_lb, 0::numeric) * (1::numeric - f_rule('expected_moisture_pct_min'::text) / 100.0), 1) AS unpackaged_dry_equiv_high,
    COALESCE(p.packages, 0::bigint) AS packages,
    COALESCE(p.packaged_dry_lb, 0::numeric) AS packaged_dry_lb,
    COALESCE(p.packaged_units, 0::numeric) AS packaged_units,
    COALESCE(t.third_party_packages, 0::bigint) AS third_party_packages,
    COALESCE(t.third_party_dry_lb, 0::numeric) AS third_party_dry_lb,
    t.third_party_suppliers,
    COALESCE(p.finished_packages, 0::bigint) AS finished_packages,
        CASE
            WHEN COALESCE(pl.plants, 0::bigint) = 0 AND COALESCE(p.packages, 0::bigint) = 0 AND COALESCE(h.open_harvests, 0::bigint) = 0 THEN 'EMPTY - no plants, no harvest material, no packages'::text
            ELSE TRIM(BOTH ' + '::text FROM (
            CASE
                WHEN COALESCE(pl.plants, 0::bigint) > 0 THEN 'living plants + '::text
                ELSE ''::text
            END ||
            CASE
                WHEN COALESCE(h.open_harvests, 0::bigint) > 0 THEN 'unpackaged harvest material (WET) + '::text
                ELSE ''::text
            END) ||
            CASE
                WHEN COALESCE(p.packages, 0::bigint) > 0 THEN 'packages'::text
                ELSE ''::text
            END)
        END AS what_is_here
   FROM loc l
     LEFT JOIN pkg p ON p.license = l.license AND p.name = l.name
     LEFT JOIN pl ON pl.license = l.license AND pl.name = l.name
     LEFT JOIN harv h ON h.license = l.license AND h.name = l.name
     LEFT JOIN tp t ON t.license = l.license AND t.name = l.name
  ORDER BY l.license, (COALESCE(p.packaged_dry_lb, 0::numeric) + COALESCE(pl.plants, 0::bigint)::numeric) DESC;
create or replace view public.v_room_turn_audit as
 SELECT room,
    plant_capacity,
    harvest_started,
    cultivars,
    plants,
    wet_lb,
    prev,
    room_turn_days,
    required_days,
    verdict,
    harvest_started AS harvest_started_date
   FROM ( WITH cyc AS (
                 SELECT g.code AS room,
                    g.plant_capacity,
                    f.harvest_started,
                    count(*) AS cultivars,
                    sum(f.plants) AS plants,
                    round(sum(f.wet_lb), 1) AS wet_lb
                   FROM v_harvest_forensic f
                     JOIN grow_rooms g ON f.harvest_name ~~* ('%'::text || g.code)
                  WHERE g.active AND f.harvest_started IS NOT NULL AND f.drying_room <> 'Freezer/Biomass Storage'::text
                  GROUP BY g.code, g.plant_capacity, f.harvest_started
                ), seq AS (
                 SELECT cyc.room,
                    cyc.plant_capacity,
                    cyc.harvest_started,
                    cyc.cultivars,
                    cyc.plants,
                    cyc.wet_lb,
                    lag(cyc.harvest_started) OVER (PARTITION BY cyc.room ORDER BY cyc.harvest_started) AS prev
                   FROM cyc
                )
         SELECT seq.room,
            seq.plant_capacity,
            seq.harvest_started,
            seq.cultivars,
            seq.plants,
            seq.wet_lb,
            seq.prev,
            seq.harvest_started - seq.prev AS room_turn_days,
            f_rule('room_cycle_days'::text) AS required_days,
                CASE
                    WHEN seq.prev IS NULL THEN 'FIRST — nothing before it in this room'::text
                    WHEN abs((seq.harvest_started - seq.prev)::numeric - f_rule('room_cycle_days'::text)) <= 2::numeric THEN ('PASS — '::text || (seq.harvest_started - seq.prev)) || ' days, inside the 56 day cycle allowing the Sunday/Monday stagger'::text
                    WHEN (seq.harvest_started - seq.prev)::numeric > f_rule('room_cycle_days'::text) THEN ((('FAIL — '::text || (seq.harvest_started - seq.prev)) || ' days, '::text) || ((seq.harvest_started - seq.prev)::numeric - f_rule('room_cycle_days'::text))) || ' days LATE. The room sat idle and pushed the next cycle.'::text
                    ELSE ((('FAIL — '::text || (seq.harvest_started - seq.prev)) || ' days, '::text) || (f_rule('room_cycle_days'::text) - (seq.harvest_started - seq.prev)::numeric)) || ' days EARLY.'::text
                END AS verdict
           FROM seq
          ORDER BY seq.room, seq.harvest_started) q;
create or replace view public.v_room_yield as
 SELECT g.code AS room,
    g.plant_capacity,
        CASE
            WHEN g.plant_capacity >= 210 THEN 'Larger room'::text
            ELSE 'Standard room'::text
        END AS room_size,
    count(*) AS closed_harvests,
    sum(h.plants) AS plants_harvested,
    round(sum(h.packaged_lb), 1) AS packaged_lb,
    round(sum(h.packaged_lb) * 453.592 / NULLIF(sum(h.plants), 0)::numeric, 1) AS grams_per_plant,
    f_rule('target_grams_per_plant'::text) AS target_grams_per_plant,
    round(100.0 * (sum(h.packaged_lb) * 453.592 / NULLIF(sum(h.plants), 0)::numeric) / NULLIF(f_rule('target_grams_per_plant'::text), 0::numeric), 1) AS pct_of_plan,
    round(avg(h.conversion_pct), 1) AS conversion_pct,
    round(avg(h.dry_days_to_first_package), 1) AS avg_dry_days,
    round(avg(h.packaging_window_days), 1) AS avg_packaging_window_days
   FROM v_harvest_forensic h
     JOIN grow_rooms g ON h.harvest_name ~~* ('%'::text || g.code)
  WHERE h.harvest_closed IS NOT NULL AND h.packaged_lb > 0::numeric AND g.active AND h.drying_room <> 'Freezer/Biomass Storage'::text
  GROUP BY g.code, g.plant_capacity
  ORDER BY (round(sum(h.packaged_lb) * 453.592 / NULLIF(sum(h.plants), 0)::numeric, 1)) DESC;
create or replace view public.v_room_yield_per_sqft as
 WITH r AS (
         SELECT f_rule('target_grams_per_sqft'::text) AS target
        )
 SELECT h.drying_room,
    g.code,
    g.sqft,
    g.plant_capacity,
    count(*) AS harvests,
    sum(h.plants) AS plants,
    round(sum(h.packaged_lb), 1) AS packaged_lb,
    round(sum(h.packaged_lb) * 453.592 / NULLIF(g.sqft, 0::numeric) / NULLIF(count(*), 0)::numeric, 1) AS grams_per_sqft_per_cycle,
    ( SELECT r.target
           FROM r) AS target_grams_per_sqft,
    round(100.0 * (sum(h.packaged_lb) * 453.592 / NULLIF(g.sqft, 0::numeric) / NULLIF(count(*), 0)::numeric) / NULLIF(( SELECT r.target
           FROM r), 0::numeric), 1) AS pct_of_plan,
        CASE
            WHEN g.sqft_source ~~ 'DERIVED%'::text THEN 'Square footage is derived from the harvest calendar, not measured. Provisional.'::text
            ELSE 'Square footage on file.'::text
        END AS caveat
   FROM v_harvest_forensic h
     JOIN grow_rooms g ON g.code = split_part(h.harvest_name, ' '::text, array_length(string_to_array(h.harvest_name, ' '::text), 1))
  WHERE h.harvest_closed IS NOT NULL AND h.packaged_lb > 0::numeric AND g.active
  GROUP BY h.drying_room, g.code, g.sqft, g.plant_capacity, g.sqft_source
  ORDER BY g.code;
create or replace view public.v_schedule_cost_by_period as
 SELECT 'month'::text AS period_type,
    v_schedule_cost_detail.month AS period_start,
    count(*) AS late_pulls,
    sum(v_schedule_cost_detail.days_late) AS days_late,
    round(sum(v_schedule_cost_detail.pounds_at_risk), 1) AS pounds_at_risk,
    round(sum(v_schedule_cost_detail.dollars_at_risk), 0) AS dollars_at_risk,
    sum(v_schedule_cost_detail.whole_cycles_lost) AS whole_cycles_lost,
    max(v_schedule_cost_detail.cost_per_lb_then) AS cost_per_lb_used
   FROM v_schedule_cost_detail
  GROUP BY v_schedule_cost_detail.month
UNION ALL
 SELECT 'quarter'::text AS period_type,
    v_schedule_cost_detail.quarter AS period_start,
    count(*) AS late_pulls,
    sum(v_schedule_cost_detail.days_late) AS days_late,
    round(sum(v_schedule_cost_detail.pounds_at_risk), 1) AS pounds_at_risk,
    round(sum(v_schedule_cost_detail.dollars_at_risk), 0) AS dollars_at_risk,
    sum(v_schedule_cost_detail.whole_cycles_lost) AS whole_cycles_lost,
    max(v_schedule_cost_detail.cost_per_lb_then) AS cost_per_lb_used
   FROM v_schedule_cost_detail
  GROUP BY v_schedule_cost_detail.quarter
UNION ALL
 SELECT 'year'::text AS period_type,
    v_schedule_cost_detail.year AS period_start,
    count(*) AS late_pulls,
    sum(v_schedule_cost_detail.days_late) AS days_late,
    round(sum(v_schedule_cost_detail.pounds_at_risk), 1) AS pounds_at_risk,
    round(sum(v_schedule_cost_detail.dollars_at_risk), 0) AS dollars_at_risk,
    sum(v_schedule_cost_detail.whole_cycles_lost) AS whole_cycles_lost,
    max(v_schedule_cost_detail.cost_per_lb_then) AS cost_per_lb_used
   FROM v_schedule_cost_detail
  GROUP BY v_schedule_cost_detail.year
  ORDER BY 1, 2;
create or replace view public.v_schedule_discipline as
 SELECT count(*) FILTER (WHERE rule_verdict ~~ 'VIOLATION%'::text)::numeric AS violations,
    count(*) FILTER (WHERE rule_verdict = 'Acceptable - early'::text)::numeric AS early_acceptable,
    count(*) FILTER (WHERE rule_verdict = 'On schedule'::text)::numeric AS on_schedule,
    count(*)::numeric AS total_events,
    round(100.0 * count(*) FILTER (WHERE rule_verdict ~~ 'VIOLATION%'::text)::numeric / NULLIF(count(*), 0)::numeric, 1) AS violation_rate_pct,
    round(avg(days_off_schedule) FILTER (WHERE rule_verdict ~~ 'VIOLATION%'::text), 1) AS average_days_late,
    max(days_off_schedule) FILTER (WHERE rule_verdict ~~ 'VIOLATION%'::text) AS worst_days_late,
    ( SELECT count(*) AS count
           FROM v_weekend_watch
          WHERE v_weekend_watch.action ~~ 'PLAN A WEEKEND%'::text) AS weekend_events_needing_a_crew
   FROM v_late_violations;
create or replace view public.v_source_conflicts as
 WITH pairs AS (
         SELECT p.field_key,
            p.why,
            p.tolerance,
            p.tolerance_unit,
            r.harvest_batch AS subject,
                CASE p.field_key
                    WHEN 'harvest.wet_lb'::text THEN r.wet_lb
                    WHEN 'harvest.packaged_lb'::text THEN r.packaged_lb
                    WHEN 'harvest.waste_lb'::text THEN r.waste_lb
                    ELSE NULL::numeric
                END AS report_value,
                CASE p.field_key
                    WHEN 'harvest.wet_lb'::text THEN h.wet_lb
                    WHEN 'harvest.packaged_lb'::text THEN h.packaged_lb
                    WHEN 'harvest.waste_lb'::text THEN h.waste_lb
                    ELSE NULL::numeric
                END AS api_value,
            r.as_of_date AS report_as_of,
            ( SELECT max(metrc_harvests.synced_at)::date AS max
                   FROM metrc_harvests) AS api_as_of
           FROM source_precedence p
             CROSS JOIN metrc_rpt_harvest_moisture r
             LEFT JOIN v_harvest_forensic h ON h.harvest_name = r.harvest_batch
          WHERE p.winner = 'conflict'::text AND p.field_key ~~ 'harvest.%'::text
        )
 SELECT field_key,
    subject,
    report_value,
    api_value,
    round(abs(report_value - api_value), 3) AS difference,
    tolerance,
    tolerance_unit,
    report_as_of,
    api_as_of,
    api_as_of - report_as_of AS api_newer_by_days,
    why,
        CASE
            WHEN report_as_of IS NULL THEN 'The report carries no as-of date.'::text
            WHEN api_as_of > report_as_of THEN 'The report is the older snapshot; the difference may be age.'::text
            ELSE 'The report is at least as recent as the API. A genuine contradiction.'::text
        END AS reading
   FROM pairs
  WHERE report_value IS NOT NULL AND api_value IS NOT NULL AND abs(report_value - api_value) > COALESCE(tolerance, 0::numeric);
create or replace view public.v_zone_board as
 SELECT zone_key,
    name,
    department,
    rooms,
    capacity,
    what_happens_here,
    active,
    sort,
    cardinality(rooms) AS room_count,
    ( SELECT round(sum(b.lb_held), 1) AS round
           FROM v_room_board_complete b
          WHERE b.metrc_room_name = ANY (z.rooms)) AS lb_in_zone,
    ( SELECT sum(b.plants_now) AS sum
           FROM v_room_board_complete b
          WHERE b.metrc_room_name = ANY (z.rooms)) AS plants_in_zone,
        CASE
            WHEN cardinality(rooms) = 0 THEN 'Not tied to a room — this zone is an area, a line or a bench.'::text
            ELSE NULL::text
        END AS why_no_rooms
   FROM zone z
  WHERE active
  ORDER BY sort, name;
create or replace view public.v_cultivation_meeting_pack as
 SELECT 1 AS agenda_no,
    'Open harvests not closed out'::text AS agenda_item,
    ( SELECT ((((count(*)::text || ' harvests, '::text) || round(sum(v_harvest_forensic.still_in_room_lb), 0)::text) || ' lb sitting, oldest '::text) || max(v_harvest_forensic.total_days_start_to_now)::text) || ' days'::text
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.harvest_state ~~ 'STILL OPEN%'::text AND v_harvest_forensic.total_days_start_to_now > 21) AS the_number,
    'This is the single biggest problem in cultivation right now. Product that is cut but never closed cannot be sold, cannot be tested, and makes every conversion number in the business wrong.'::text AS why_it_matters,
    'Name a date for each open lot. Anything past 21 days gets closed this week or gets a written reason.'::text AS the_ask,
    'Cultivation lead'::text AS owner,
    'harvest_issues'::text AS fix_report
UNION ALL
 SELECT 2 AS agenda_no,
    'Drying discipline'::text AS agenda_item,
    ( SELECT ((((((('Average '::text || round(avg(v_harvest_forensic.dry_days_to_first_package), 1)::text) || ' days to first package. '::text) || count(*) FILTER (WHERE v_harvest_forensic.dry_days_to_first_package > 16)::text) || ' dried too long, '::text) || count(*) FILTER (WHERE v_harvest_forensic.dry_days_to_first_package < 7)::text) || ' dried too fast, only '::text) || count(*) FILTER (WHERE v_harvest_forensic.dry_days_to_first_package >= 7 AND v_harvest_forensic.dry_days_to_first_package <= 16)::text) || ' inside the 10-14 day window'::text
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.dry_days_to_first_package IS NOT NULL) AS the_number,
    'Over-drying burns off saleable weight permanently. Under-drying locks in moisture and risks mould. Neither is recoverable after the fact.'::text AS why_it_matters,
    'Agree one written dry protocol and hold every room to it. Report exceptions weekly.'::text AS the_ask,
    'Post-harvest lead'::text AS owner,
    'harvest_forensic'::text AS fix_report
UNION ALL
 SELECT 3 AS agenda_no,
    'Drying room comparison'::text AS agenda_item,
    ( SELECT string_agg(((((v_dry_room_performance.drying_room || ': '::text) || COALESCE(v_dry_room_performance.avg_dry_days::text, 'n/a'::text)) || ' days avg, '::text) || v_dry_room_performance.conversion_pct::text) || ' pct'::text, ' | '::text ORDER BY v_dry_room_performance.plants DESC) AS string_agg
           FROM v_dry_room_performance) AS the_number,
    'Same company, same genetics, wildly different dry times and conversion by room. That gap is practice, not capacity.'::text AS why_it_matters,
    'Explain why the rooms differ. Bring the room logs.'::text AS the_ask,
    'Cultivation lead'::text AS owner,
    'dry_room_performance'::text AS fix_report
UNION ALL
 SELECT 4 AS agenda_no,
    'Harvests closed with zero packaged'::text AS agenda_item,
    ( SELECT ((count(*)::text || ' harvests closed out with no package at all, '::text) || round(sum(v_harvest_forensic.wet_lb), 1)::text) || ' lb of wet weight unaccounted'::text
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.harvest_state = 'Finished'::text AND v_harvest_forensic.packaged_lb = 0::numeric) AS the_number,
    'Weight went in and nothing came out on the record. This is the kind of gap a regulator asks about first.'::text AS why_it_matters,
    'Account for every one of these in writing.'::text AS the_ask,
    'Compliance'::text AS owner,
    'harvest_issues'::text AS fix_report
UNION ALL
 SELECT 5 AS agenda_no,
    'Weight recording integrity'::text AS agenda_item,
    ( SELECT count(*)::text || ' harvests recorded above 35 percent wet-to-packaged, which is not physically typical'::text
           FROM v_harvest_forensic
          WHERE v_harvest_forensic.conversion_pct > 35::numeric) AS the_number,
    'Fresh flower is 75 to 80 percent water. A conversion above roughly 30 percent means the wet weight was recorded too low at takedown, not that the harvest did unusually well.'::text AS why_it_matters,
    'One scale, one method, one person accountable at takedown.'::text AS the_ask,
    'Cultivation lead'::text AS owner,
    'harvest_forensic'::text AS fix_report
UNION ALL
 SELECT 6 AS agenda_no,
    'Month by month, closed harvests only'::text AS agenda_item,
    ( SELECT string_agg(((((((t.month || ': '::text) || COALESCE(t.conversion_pct_closed_only::text, 'n/a'::text)) || ' pct ('::text) || t.harvests_closed) || ' closed, '::text) || t.still_open) || ' open)'::text, ' | '::text ORDER BY t.month DESC) AS string_agg
           FROM ( SELECT v_monthly_conversion_truth.month,
                    v_monthly_conversion_truth.harvests_cut,
                    v_monthly_conversion_truth.harvests_closed,
                    v_monthly_conversion_truth.still_open,
                    v_monthly_conversion_truth.plants,
                    v_monthly_conversion_truth.wet_lb,
                    v_monthly_conversion_truth.packaged_lb,
                    v_monthly_conversion_truth.sitting_unfinished_lb,
                    v_monthly_conversion_truth.conversion_pct_closed_only,
                    v_monthly_conversion_truth.avg_dry_days,
                    v_monthly_conversion_truth.dried_too_long,
                    v_monthly_conversion_truth.dried_too_fast,
                    v_monthly_conversion_truth.how_to_read_this_month
                   FROM v_monthly_conversion_truth
                 LIMIT 6) t) AS the_number,
    'Judging a month before its harvests close produces a false collapse. Only closed harvests can be measured.'::text AS why_it_matters,
    'Review the trend on closed harvests only.'::text AS the_ask,
    'Cultivation lead'::text AS owner,
    'monthly_conversion_truth'::text AS fix_report;
create or replace view public.v_flow_stages as
 SELECT stage_no,
    stage,
    units,
    unit,
    pounds,
    oldest_days,
    drill,
    note
   FROM ( SELECT 0 AS stage_no,
            'Blocked - failed'::text AS stage,
            ( SELECT sum(v_stock_on_hand.packages) AS sum
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'TestFailed'::text) AS units,
            'packages'::text AS unit,
            ( SELECT round(sum(v_stock_on_hand.pounds), 1) AS round
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'TestFailed'::text) AS pounds,
            ( SELECT max(v_stock_on_hand.oldest_days) AS max
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'TestFailed'::text) AS oldest_days,
            'failed_testing_by_origin'::text AS drill,
            'Failed testing - remediate or destroy'::text AS note
        UNION ALL
         SELECT 1,
            'Growing'::text,
            (( SELECT count(*) AS count
                   FROM metrc_plants
                  WHERE metrc_plants.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])))::numeric AS count,
            'plants'::text,
            NULL::numeric AS "numeric",
            NULL::integer AS int4,
            'room_board'::text,
            'Plants standing in the rooms now. Harvested and destroyed plants are excluded - they are not growing.'::text
        UNION ALL
         SELECT 2,
            'Open harvests'::text,
            (( SELECT count(*) AS count
                   FROM v_harvest_still_in_room))::numeric AS count,
            'harvests'::text,
            ( SELECT round(sum(v_harvest_still_in_room.really_left_lb), 1) AS round
                   FROM v_harvest_still_in_room) AS round,
            ( SELECT max(v_harvest_still_in_room.days_since_last_package) AS max
                   FROM v_harvest_still_in_room) AS max,
            'harvest_issues'::text,
            'Dry yield still to be packaged off. Dry-equivalent, not wet.'::text
        UNION ALL
         SELECT 3,
            'Awaiting test'::text,
            ( SELECT sum(v_stock_on_hand.packages) AS sum
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text) AS sum,
            'packages'::text,
            ( SELECT round(sum(v_stock_on_hand.pounds), 1) AS round
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text) AS round,
            ( SELECT max(v_stock_on_hand.oldest_days) AS max
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text) AS max,
            'lab_results'::text,
            'Never sent to the laboratory'::text
        UNION ALL
         SELECT 4,
            'At the laboratory'::text,
            ( SELECT sum(v_stock_on_hand.packages) AS sum
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state ~~ '%ubmitted%'::text AND v_stock_on_hand.lab_state <> 'NotSubmitted'::text) AS sum,
            'packages'::text,
            ( SELECT round(sum(v_stock_on_hand.pounds), 1) AS round
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state ~~ '%ubmitted%'::text AND v_stock_on_hand.lab_state <> 'NotSubmitted'::text) AS round,
            ( SELECT max(v_stock_on_hand.oldest_days) AS max
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state ~~ '%ubmitted%'::text AND v_stock_on_hand.lab_state <> 'NotSubmitted'::text) AS max,
            'lab_turnaround'::text,
            'Awaiting a result'::text
        UNION ALL
         SELECT 5,
            'Sellable'::text,
            ( SELECT sum(v_stock_on_hand.packages) AS sum
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'TestPassed'::text) AS sum,
            'packages'::text,
            ( SELECT round(sum(v_stock_on_hand.pounds), 1) AS round
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'TestPassed'::text) AS round,
            ( SELECT max(v_stock_on_hand.oldest_days) AS max
                   FROM v_stock_on_hand
                  WHERE v_stock_on_hand.lab_state = 'TestPassed'::text) AS max,
            'stock_on_hand'::text,
            'Passed and free to move'::text
        UNION ALL
         SELECT 6,
            'In transit'::text,
            (( SELECT count(*) AS count
                   FROM metrc_packages
                  WHERE metrc_packages.source_state = 'intransit'::text AND NOT COALESCE(metrc_packages.finished, false)))::numeric AS count,
            'packages'::text,
            ( SELECT round(sum(f_to_pounds(metrc_packages.quantity, metrc_packages.uom)), 1) AS round
                   FROM metrc_packages
                  WHERE metrc_packages.source_state = 'intransit'::text AND NOT COALESCE(metrc_packages.finished, false)) AS round,
            ( SELECT max(CURRENT_DATE - ((metrc_packages.raw ->> 'PackagedDate'::text)::date)) AS max
                   FROM metrc_packages
                  WHERE metrc_packages.source_state = 'intransit'::text AND NOT COALESCE(metrc_packages.finished, false) AND COALESCE(metrc_packages.raw ->> 'PackagedDate'::text, ''::text) <> ''::text) AS max,
            'in_transit'::text,
            'On an active transfer the destination has not accepted. OURS until the receiver signs - owner ruling 11 Aug 2026. If rejected, it comes back.'::text) q
  ORDER BY stage_no;
create or replace view public.v_goal_status as
 WITH recent AS (
         SELECT v_monthly_conversion_truth.month,
            v_monthly_conversion_truth.harvests_cut,
            v_monthly_conversion_truth.harvests_closed,
            v_monthly_conversion_truth.wet_lb,
            v_monthly_conversion_truth.packaged_lb,
            v_monthly_conversion_truth.conversion_pct_closed_only,
            v_monthly_conversion_truth.avg_dry_days
           FROM v_monthly_conversion_truth
          ORDER BY v_monthly_conversion_truth.month DESC
         LIMIT 1
        )
 SELECT g.metric_key,
    g.metric_label,
    g.unit,
    g.target,
    g.target_max,
    g.direction,
    g.benchmark_note,
    ( SELECT recent.month
           FROM recent) AS measured_month,
    a.actual,
    a.basis,
        CASE
            WHEN a.actual IS NULL THEN 'no data'::text
            WHEN g.direction = 'between'::text OR g.target_max IS NOT NULL THEN
            CASE
                WHEN a.actual >= g.target AND (g.target_max IS NULL OR a.actual <= g.target_max) THEN 'on target'::text
                ELSE 'off target'::text
            END
            WHEN g.direction = 'at_most'::text THEN
            CASE
                WHEN a.actual <= g.target THEN 'on target'::text
                ELSE 'off target'::text
            END
            ELSE
            CASE
                WHEN a.actual >= g.target THEN 'on target'::text
                ELSE 'off target'::text
            END
        END AS status
   FROM cultivation_goals g
     CROSS JOIN LATERAL ( SELECT
                CASE g.metric_key
                    WHEN 'packaged_lb_per_month'::text THEN ( SELECT recent.packaged_lb
                       FROM recent)
                    WHEN 'conversion_pct'::text THEN ( SELECT recent.conversion_pct_closed_only
                       FROM recent)
                    WHEN 'dry_days'::text THEN ( SELECT recent.avg_dry_days
                       FROM recent)
                    ELSE NULL::numeric
                END AS actual,
                CASE g.metric_key
                    WHEN 'packaged_lb_per_month'::text THEN 'v_monthly_conversion_truth.packaged_lb, most recent month'::text
                    WHEN 'conversion_pct'::text THEN 'v_monthly_conversion_truth.conversion_pct_closed_only, closed harvests only'::text
                    WHEN 'dry_days'::text THEN 'v_monthly_conversion_truth.avg_dry_days, most recent month'::text
                    WHEN 'grams_per_sqft'::text THEN 'UNCOMPUTABLE - the owner has ruled there is no square footage recorded anywhere in this business, and grow_rooms.sqft is null by design. Never estimate it.'::text
                    WHEN 'packaged_lb_per_pull'::text THEN 'NOT YET WIRED - needs facility pulls resolved from harvest_plan_2026.pull_no. A count of metrc harvest rows is the WRONG denominator.'::text
                    WHEN 'facility_pulls_per_month'::text THEN 'NOT YET WIRED - same reason as packaged_lb_per_pull.'::text
                    ELSE 'NOT YET WIRED - no verified source has been agreed for this metric. Left null deliberately rather than filled with a plausible figure.'::text
                END AS basis) a
  WHERE g.enabled;
create or replace view public.v_held_unpackaged_flower as
 SELECT drying_room AS room,
    count(*) AS open_harvests,
    round(sum(wet_lb), 1) AS wet_lb,
    round(sum(packaged_lb), 1) AS packaged_off_lb,
    round(sum(old_figure_wet_minus_dry), 1) AS metrc_residual_lb,
    round(sum(really_left_lb), 1) AS really_held_lb,
    round(sum(old_figure_wet_minus_dry) - sum(really_left_lb), 1) AS water_not_product_lb,
    max(days_open) AS longest_open_days
   FROM v_harvest_still_in_room
  GROUP BY drying_room;
create or replace view public.v_moisture_loss_progress as
 SELECT harvest_state,
    count(*) AS harvests,
    round(sum(phantom_lb), 1) AS phantom_lb,
    count(*) FILTER (WHERE NOT needs_recording) AS recorded_here,
    count(*) FILTER (WHERE recorded_in_metrc) AS recorded_in_metrc,
    count(*) FILTER (WHERE needs_recording) AS still_to_do,
    round(sum(phantom_lb) FILTER (WHERE needs_recording), 1) AS lb_still_to_do,
    round(COALESCE(sum(recorded_loss_lb), 0::numeric), 1) AS lb_recorded_so_far
   FROM v_moisture_loss_register
  GROUP BY harvest_state
  ORDER BY harvest_state;
create or replace view public.v_money_position as
 WITH b AS (
         SELECT 'Sellable now'::text AS band,
            1 AS ord,
            'good'::text AS tone,
            'TestPassed'::text AS st,
            'Test passed and free to move'::text AS note
        UNION ALL
         SELECT 'At the laboratory'::text,
            2,
            'watch'::text,
            'OUT'::text,
            'Awaiting a result'::text
        UNION ALL
         SELECT 'Never submitted'::text,
            3,
            'bad'::text,
            'NotSubmitted'::text,
            'Cannot legally be sold until submitted'::text
        UNION ALL
         SELECT 'Failed testing'::text,
            4,
            'bad'::text,
            'TestFailed'::text,
            'Out of the flow until remediated or destroyed'::text
        ), agg AS (
         SELECT b.band,
            b.ord,
            b.tone,
            b.note,
            round(sum(s.pounds), 1) AS pounds,
            sum(s.units) AS units,
            round(sum(s.pounds * f_rate_for(s.stream))) AS dollars
           FROM b
             JOIN v_stock_on_hand s ON b.st = 'OUT'::text AND s.lab_state ~~ '%ubmitted%'::text AND s.lab_state <> 'NotSubmitted'::text OR b.st <> 'OUT'::text AND s.lab_state = b.st
          GROUP BY b.band, b.ord, b.tone, b.note
        )
 SELECT agg.band,
    agg.ord,
    agg.pounds,
    agg.dollars,
    agg.tone,
    'stock_proof'::text AS drill,
    agg.note,
    ((('Every package behind this figure opens from here — tag, product, cultivar, harvest, dates, '::text || 'certificate and manifest. '::text) || COALESCE(agg.units, 0::numeric)) || ' countable units are held separately and '::text) || 'carry no pound figure.'::text AS how_this_was_valued,
    ( SELECT count(*) AS count
           FROM valuation_rates
          WHERE NOT valuation_rates.confirmed) AS rates_not_yet_confirmed,
    COALESCE(agg.units, 0::numeric) AS units_not_weighed
   FROM agg
UNION ALL
 SELECT 'Still in the rooms'::text AS band,
    5 AS ord,
    round(( SELECT sum(v_harvest_still_in_room.really_left_lb) AS sum
           FROM v_harvest_still_in_room), 1) AS pounds,
    round((( SELECT sum(v_harvest_still_in_room.really_left_lb) AS sum
           FROM v_harvest_still_in_room)) * f_rate_for('Dried flower'::text)) AS dollars,
    'warn'::text AS tone,
    'moisture_loss_register'::text AS drill,
    'Dry yield not yet packaged off'::text AS note,
    ('DRY-EQUIVALENT, not wet. Metrc shows '::text || round(( SELECT sum(v_harvest_still_in_room.old_figure_wet_minus_dry) AS sum
           FROM v_harvest_still_in_room), 1)) || ' lb because the evaporated water has never been entered there. Every harvest and its arithmetic opens from here.'::text AS how_this_was_valued,
    ( SELECT count(*) AS count
           FROM valuation_rates
          WHERE NOT valuation_rates.confirmed) AS rates_not_yet_confirmed,
    0 AS units_not_weighed
  ORDER BY 2;
create or replace view public.v_yield_versus_industry as
 SELECT month,
    harvests_cut,
    harvests_closed,
    still_open,
    plants AS plants_harvested,
    wet_lb AS wet_lbs,
    packaged_lb AS saleable_lbs,
    sitting_unfinished_lb,
    conversion_pct_closed_only AS our_conversion_pct,
    20 AS industry_average_pct,
    25 AS industry_good_pct,
    round(packaged_lb * 453.592 / NULLIF(plants, 0)::numeric, 1) AS our_grams_per_plant,
    '50 to 75 (density-derived)'::text AS industry_grams_per_plant_range,
    round(plants::numeric / NULLIF(packaged_lb, 0::numeric), 1) AS our_plants_per_pound,
    avg_dry_days,
    dried_too_long,
    dried_too_fast,
        CASE
            WHEN still_open > 0 THEN ((('CANNOT BE JUDGED YET — '::text || still_open) || ' of '::text) || harvests_cut) || ' harvests still open'::text
            WHEN conversion_pct_closed_only > 30::numeric THEN 'SUSPECT HIGH — check wet weight recording'::text
            WHEN conversion_pct_closed_only >= 25::numeric THEN 'GOOD'::text
            WHEN conversion_pct_closed_only >= 20::numeric THEN 'AT INDUSTRY AVERAGE'::text
            ELSE 'BELOW INDUSTRY AVERAGE'::text
        END AS industry_verdict,
    how_to_read_this_month
   FROM v_monthly_conversion_truth m
  ORDER BY month DESC;
create materialized view if not exists public.mv_flow_stages as
 SELECT stage_no,
    stage,
    units,
    unit,
    pounds,
    oldest_days,
    drill,
    note
   FROM v_flow_stages;
create or replace view public.mv_department_dashboard as
 SELECT b.department,
    b.ord,
        CASE
            WHEN b.department = 'Command'::text AND b.ord = 1 THEN 'Dried flower on hand'::text
            ELSE b.kpi
        END AS kpi,
        CASE
            WHEN b.department = 'Command'::text AND b.ord = 1 THEN ( SELECT v_stock_headline.dried_lb
               FROM v_stock_headline)
            WHEN b.department = 'Metrc'::text AND b.ord = 1 THEN ( SELECT count(DISTINCT mp.tag)::numeric AS count
               FROM metrc_packages mp)
            WHEN b.department = 'Settings'::text AND b.ord = 2 THEN ( SELECT count(*)::numeric AS count
               FROM conversion_factors cf
              WHERE cf.set_by !~* '(owner|vinny)'::text)
            WHEN b.department = 'Inventory'::text AND b.ord = 1 THEN ( SELECT round(sum(
                    CASE
                        WHEN v.stream = 'Fresh frozen'::text THEN v.grams / f_rule('fresh_frozen_wet_to_dry'::text)
                        ELSE v.grams
                    END) / 453.59237, 1) AS round
               FROM v_stock_on_hand v)
            WHEN b.department = 'Inventory'::text AND b.ord = 2 THEN ( SELECT round(sum(v.grams) FILTER (WHERE v.lab_state = 'TestPassed'::text) / 453.59237, 1) AS round
               FROM v_stock_on_hand v)
            WHEN b.department = 'Inventory'::text AND b.ord = 3 THEN ( SELECT round(sum(v.grams) FILTER (WHERE v.lab_state = 'NotSubmitted'::text) / 453.59237, 1) AS round
               FROM v_stock_on_hand v)
            WHEN b.department = 'Inventory'::text AND b.ord = 4 THEN ( SELECT round(sum(v.grams) FILTER (WHERE v.origin = 'Bought in'::text) / 453.59237, 1) AS round
               FROM v_stock_on_hand v)
            WHEN b.department = 'Inventory'::text AND b.ord = 5 THEN ( SELECT round(sum(a.lb), 1) AS round
               FROM v_stock_ageing a
              WHERE a.ageing_verdict ~~ 'STALE%'::text)
            WHEN b.kpi = 'Moisture loss not recorded'::text THEN COALESCE(b.value, 0::numeric)
            ELSE b.value
        END AS value,
    b.unit,
    b.tone,
        CASE
            WHEN b.department = 'Command'::text AND b.ord = 1 THEN ('Dried only. Fresh frozen '::text || (( SELECT to_char(v_stock_headline.fresh_frozen_wet_lb, 'FM999999.0'::text) AS to_char
               FROM v_stock_headline))) || ' lb is held separately at wet weight and is never added to this.'::text
            WHEN b.department = 'Metrc'::text AND b.ord = 1 THEN 'Distinct tags. 715 tags appear twice because the package moved between our two licences — that is one package, not two.'::text
            WHEN b.department = 'Settings'::text AND b.ord = 2 THEN 'Conversion factors not set by the owner. Each one is a number the platform is using that he has not confirmed.'::text
            WHEN b.department = 'Inventory'::text AND b.ord = 1 THEN ( SELECT ((('Fresh frozen counted at dry-equivalent (wet ÷ '::text || f_rule('fresh_frozen_wet_to_dry'::text)) || ', owner-set). Wet-basis total: '::text) || to_char(sum(v.grams) / 453.59237, 'FM999999.0'::text)) || ' lb.'::text
               FROM v_stock_on_hand v)
            WHEN b.department = 'Inventory'::text AND b.ord = 5 THEN ( SELECT ('Per the owner ageing policy: categories that age, past their own limit, holding rooms suspend. '::text || count(*)) || ' packages. A raw 180-day age with no policy would say far more — that is not the ruling.'::text
               FROM v_stock_ageing a
              WHERE a.ageing_verdict ~~ 'STALE%'::text)
            ELSE b.context
        END AS context,
    b.drill,
    b.computed_at
   FROM mv_department_dashboard_base b
UNION ALL
 SELECT s.department,
    s.ord,
    s.kpi,
    s.value,
    s.unit,
    s.tone,
    s.context,
    s.drill,
    s.computed_at
   FROM mv_dept_dash_supplement s;
create materialized view if not exists public.mv_department_dashboard_base as
 WITH r AS (
         SELECT f_rule('ageing_stock_days'::text) AS age,
            f_rule('harvest_open_max_days'::text) AS hopen,
            f_rule('fresh_frozen_wet_to_dry'::text) AS ff,
            f_rule('dry_window_max_days'::text) AS drymax,
            f_rule('dry_window_min_days'::text) AS drymin
        ), tot AS (
         SELECT round(sum(v_stock_on_hand.pounds), 1) AS lb_all,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestPassed'::text), 1) AS lb_sellable,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text), 1) AS lb_failed,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND f_is_ours(v_stock_on_hand.origin_license)), 1) AS lb_failed_ours,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND NOT f_is_ours(v_stock_on_hand.origin_license)), 1) AS lb_failed_theirs,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text), 1) AS lb_untested,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state ~~ '%ubmitted%'::text AND v_stock_on_hand.lab_state <> 'NotSubmitted'::text), 1) AS lb_out,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.origin = 'Bought in'::text), 1) AS lb_bought,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.oldest_days::numeric > (( SELECT r.age
                   FROM r))), 1) AS lb_old,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.stream = 'Concentrate'::text), 1) AS lb_conc,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.stream = 'Fresh frozen'::text), 1) AS lb_ff,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.stream = 'Shake and trim'::text), 1) AS lb_shake,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.stream = 'Pre-rolls'::text), 1) AS lb_pr,
            round(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.stream = 'Pre-rolls'::text AND v_stock_on_hand.lab_state = 'NotSubmitted'::text), 1) AS lb_pr_untested,
            round(sum(v_stock_on_hand.pounds * f_rate_for(v_stock_on_hand.stream))) AS val_all,
            round(sum(v_stock_on_hand.pounds * f_rate_for(v_stock_on_hand.stream)) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text)) AS val_failed,
            round(sum(v_stock_on_hand.pounds * f_rate_for(v_stock_on_hand.stream)) FILTER (WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text)) AS val_untested
           FROM v_stock_on_hand
        ), rooms AS (
         SELECT round(sum(v_harvest_still_in_room.really_left_lb), 1) AS lb_dry_equiv,
            round(sum(v_harvest_still_in_room.old_figure_wet_minus_dry), 1) AS lb_metrc_wet,
            count(*) AS open_h
           FROM v_harvest_still_in_room
        ), phantom AS (
         SELECT count(*) AS n,
            round(sum(v_moisture_loss_register.phantom_lb), 1) AS lb
           FROM v_moisture_loss_register
          WHERE v_moisture_loss_register.harvest_state = 'CLOSED'::text AND v_moisture_loss_register.needs_recording AND v_moisture_loss_register.phantom_lb > 0::numeric
        ), lab AS (
         SELECT count(*) AS n,
            round(sum(v_missing_lab_results.pounds), 1) AS lb
           FROM v_missing_lab_results
        ), find AS (
         SELECT count(DISTINCT watchdog_findings.fingerprint) AS n
           FROM watchdog_findings
          WHERE watchdog_findings.observed_at > (now() - '48:00:00'::interval)
        ), h AS (
         SELECT count(*) FILTER (WHERE v_harvest_forensic.harvest_closed IS NULL AND v_harvest_forensic.total_days_start_to_now::numeric > (( SELECT r.hopen
                   FROM r))) AS open21,
            round(avg(v_harvest_forensic.dry_days_to_first_package) FILTER (WHERE v_harvest_forensic.dry_days_to_first_package IS NOT NULL), 1) AS avg_dry,
            count(*) FILTER (WHERE v_harvest_forensic.dry_days_to_first_package::numeric > (( SELECT r.drymax
                   FROM r))) AS dried_long,
            round(avg(v_harvest_forensic.conversion_pct) FILTER (WHERE v_harvest_forensic.harvest_closed IS NOT NULL), 1) AS conv
           FROM v_harvest_forensic
        )
 SELECT department,
    ord,
    kpi,
    value,
    unit,
    tone,
    context,
    drill,
    now() AS computed_at
   FROM ( SELECT 'Command'::text AS department,
            1 AS ord,
            'Total on hand, dry-equivalent'::text AS kpi,
            ( SELECT tot.lb_all
                   FROM tot) AS value,
            'lb'::text AS unit,
            'info'::text AS tone,
            'Every package in Metrc under our licences.'::text AS context,
            'stock_on_hand'::text AS drill
        UNION ALL
         SELECT 'Command'::text AS text,
            2,
            'In the rooms, dry-equivalent'::text AS text,
            ( SELECT rooms.lb_dry_equiv
                   FROM rooms) AS lb_dry_equiv,
            'lb'::text AS text,
            'warn'::text AS text,
            ( SELECT ((('Metrc shows '::text || rooms.lb_metrc_wet) || ' lb wet across '::text) || rooms.open_h) || ' open harvests. This is the dry-equivalent — the rest is water.'::text
                   FROM rooms),
            'moisture_loss_register'::text AS text
        UNION ALL
         SELECT 'Command'::text AS text,
            3,
            'Harvests open too long'::text AS text,
            ( SELECT h.open21
                   FROM h) AS open21,
            ''::text AS text,
            'bad'::text AS text,
            ( SELECT ('Past the '::text || r.hopen) || ' day limit from the 2026 calendar.'::text
                   FROM r),
            'harvest_issues'::text AS text
        UNION ALL
         SELECT 'Command'::text AS text,
            4,
            'Moisture loss not recorded'::text AS text,
            ( SELECT phantom.lb
                   FROM phantom) AS lb,
            'lb'::text AS text,
            'bad'::text AS text,
            ( SELECT phantom.n || ' closed harvests still showing water in Metrc.'::text
                   FROM phantom),
            'moisture_loss_register'::text AS text
        UNION ALL
         SELECT 'Command'::text AS text,
            5,
            'Out at the laboratory, no result'::text AS text,
            ( SELECT lab.lb
                   FROM lab) AS lb,
            'lb'::text AS text,
            'bad'::text AS text,
            ( SELECT lab.n || ' packages submitted and never reported back.'::text
                   FROM lab),
            'metrc_rpt_lab'::text AS text
        UNION ALL
         SELECT 'Command'::text AS text,
