            'intelligence_briefing'::text AS text
        UNION ALL
         SELECT 'Cultivation'::text AS text,
            1,
            'In the rooms, dry-equivalent'::text AS text,
            ( SELECT rooms.lb_dry_equiv
                   FROM rooms) AS lb_dry_equiv,
            'lb'::text AS text,
