create or replace view public.v_strain_conflicts as
 SELECT v.manifest_number,
    v.package_tag,
    v.item,
    v.strain_column_says,
    v.item_name_says,
    v.destination_facility,
    v.shipped_qty,
    v.value_usd,
    v.what_is_wrong,
    v.ladder_verdict,
    v.ladder_strain,
    v.decided_by_rung,
    v.ladder_evidence,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( WITH candidate AS (
                 SELECT t.manifest_number,
                    t.package_tag,
                    t.item,
                    t.strain AS strain_column_says,
                    f_strain_from_item(t.item) AS item_name_says,
                    t.destination_facility,
                    t.shipped_qty,
                    t.shipper_wholesale_price AS value_usd
                   FROM metrc_rpt_package_transfers t
                  WHERE t.strain IS NOT NULL AND t.strain <> ''::text AND f_strain_from_item(t.item) IS NOT NULL AND lower(replace(replace(t.strain, '.'::text, ''::text), ','::text, ''::text)) <> lower(replace(replace(f_strain_from_item(t.item), '.'::text, ''::text), ','::text, ''::text)) AND lower(t.strain) !~~ (('%'::text || lower(f_strain_from_item(t.item))) || '%'::text) AND lower(f_strain_from_item(t.item)) !~~ (('%'::text || lower(t.strain)) || '%'::text)
                ), judged AS (
                 SELECT c.manifest_number,
                    c.package_tag,
                    c.item,
                    c.strain_column_says,
                    c.item_name_says,
                    c.destination_facility,
                    c.shipped_qty,
                    c.value_usd,
                    l.strain AS ladder_strain,
                    l.verdict AS ladder_verdict,
                    l.decided_by_rung,
                    l.evidence AS ladder_evidence
                   FROM candidate c
                     CROSS JOIN LATERAL f_strain_by_tag(c.package_tag, c.strain_column_says) l(strain, verdict, decided_by_rung, decided_by, contributors, evidence)
                )
         SELECT j.manifest_number,
            j.package_tag,
            j.item,
            j.strain_column_says,
            j.item_name_says,
            j.destination_facility,
            j.shipped_qty,
            j.value_usd,
                CASE
                    WHEN j.ladder_strain IS NOT NULL AND lower(j.ladder_strain) = lower(btrim(j.item_name_says)) THEN (('Metrc seed-to-sale says "'::text || j.ladder_strain) || '", which matches the ITEM NAME. '::text) || 'The Metrc STRAIN FIELD is the wrong one and must be corrected at source (D2).'::text
                    ELSE 'Neither name is supported by seed-to-sale, and no certificate or independent '::text || 'manifest settles it. This one needs a person (A5).'::text
                END AS what_is_wrong,
            j.ladder_verdict,
            j.ladder_strain,
            j.decided_by_rung,
            j.ladder_evidence
           FROM judged j
          WHERE NOT j.ladder_verdict ~~ 'BLEND%'::text AND NOT (j.ladder_strain IS NOT NULL AND lower(j.ladder_strain) = lower(btrim(j.strain_column_says)))) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.package_tag;
create or replace view public.v_tag_certificate_final as
 SELECT v.tag,
    v.certificate_on_tag,
    v.certificate_hops,
    v.certificate_document,
    v.certificate_source,
    v.certificate_date,
    v.certificate_route,
    v.certificate_basis,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( SELECT c.tag,
            COALESCE(c.certificate_on_tag, hc.certified_via_tag) AS certificate_on_tag,
            c.certificate_hops,
            c.certificate_document,
            COALESCE(c.certificate_source, ((hc.certificate_source || ' (via harvest lot '::text) || thl.harvest) || ')'::text) AS certificate_source,
            COALESCE(c.certificate_date, hc.report_date) AS certificate_date,
                CASE
                    WHEN c.certificate_source IS NOT NULL THEN 'PACKAGE LINEAGE'::text
                    WHEN hc.harvest IS NOT NULL THEN 'HARVEST LOT'::text
                    ELSE NULL::text
                END AS certificate_route,
                CASE
                    WHEN c.certificate_source IS NOT NULL AND c.certificate_hops = 0 THEN 'ON THE TAG ITSELF'::text
                    WHEN c.certificate_source IS NOT NULL THEN ('INHERITED — '::text || c.certificate_hops) || ' hop(s) up the package lineage'::text
                    WHEN hc.harvest IS NOT NULL THEN ('INHERITED — same harvest lot ('::text || thl.harvest) || ')'::text
                    WHEN pcat.cat = ANY (ARRAY['Seeds'::text, 'Immature Plants'::text]) THEN 'NOT TESTED — seeds and immature plants are not lab tested'::text
                    WHEN thl.tag IS NOT NULL THEN 'NOT IMPORTED — the harvest lot has no certificate either'::text
                    ELSE 'NO LINEAGE — no parent package and no harvest'::text
                END AS certificate_basis
           FROM mv_tag_certificate c
             LEFT JOIN mv_tag_harvest_link thl ON thl.tag = c.tag AND c.certificate_source IS NULL
             LEFT JOIN mv_harvest_certificate hc ON hc.harvest = thl.harvest
             LEFT JOIN LATERAL ( SELECT (mp.raw -> 'Item'::text) ->> 'ProductCategoryName'::text AS cat
                   FROM metrc_packages mp
                  WHERE upper(btrim(mp.raw ->> 'Label'::text)) = c.tag
                 LIMIT 1) pcat ON true) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_tag_coa_gap as
 SELECT v.tag,
    v.item,
    v.category,
    v.strain,
    v.ownership,
    v.grown_or_processed_by,
    v.licence,
    v.room,
    v.tag_status,
    v.packaged_on,
    v.first_received,
    v.last_shipped,
    v.moved_on,
    v.manifests_in,
    v.received_from,
    v.manifests_out,
    v.shipped_to,
    v.on_hand_lb,
    v.shipped_lb,
    v.coa_basis,
    v.coa_found_on_tag,
    v.coa_hops,
    v.coa_document,
    v.source_harvests,
    v.source_packages,
    v.known_from,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( SELECT m.tag,
            m.item,
            m.category,
            m.strain,
            m.ownership,
            m.grown_or_processed_by,
            m.licence,
            m.room,
            m.tag_status,
            m.packaged_on,
            m.first_received,
            m.last_shipped,
            COALESCE(m.last_shipped, m.first_received, m.packaged_on) AS moved_on,
            m.manifests_in,
            m.received_from,
            m.manifests_out,
            m.shipped_to,
            m.on_hand_lb,
            m.shipped_lb,
            f.certificate_basis AS coa_basis,
            f.certificate_on_tag AS coa_found_on_tag,
            f.certificate_hops AS coa_hops,
            f.certificate_document AS coa_document,
            m.source_harvests,
            m.source_packages,
            m.known_from
           FROM v_tag_master m
             JOIN v_tag_certificate_final f ON f.tag = m.tag
          WHERE f.certificate_source IS NULL AND f.certificate_basis !~~ 'NOT TESTED%'::text) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_tag_evidence as
 SELECT e.tag,
    e.item_name,
    e.lab_testing_state,
        CASE
            WHEN e.evidence_source = ANY (ARRAY['direct'::text, 'inherited'::text]) THEN e.evidence_source
            WHEN cr.package_tag IS NULL THEN e.evidence_source
            WHEN cr.found_at_depth = 0 THEN 'certificate on file'::text
            ELSE 'inherited'::text
        END AS evidence_source,
    COALESCE(e.certificate_id, b.lab_report_id) AS certificate_id,
    COALESCE(e.certificate_date, b.report_date) AS certificate_date,
    COALESCE(e.total_thc, b.total_thc) AS total_thc,
        CASE
            WHEN e.certificate_inherited_from IS NOT NULL THEN e.certificate_inherited_from
            WHEN cr.found_at_depth > 0 THEN cr.certificate_on_package
            ELSE NULL::text
        END AS certificate_inherited_from,
    COALESCE(e.certificate_document, b.storage_path) AS certificate_document,
    e.lab_result_date,
    e.lab_name,
    e.manifest_number,
    e.manifest_document,
        CASE
            WHEN e.evidence_source = ANY (ARRAY['direct'::text, 'inherited'::text]) THEN e.why_no_certificate
            WHEN b.storage_path IS NOT NULL THEN NULL::text
            ELSE e.why_no_certificate
        END AS why_no_certificate,
    e.why_no_manifest,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM coa_extract c
              WHERE c.package_tag = e.tag)) THEN 'direct — the certificate document names this tag'::text
            WHEN e.certificate_inherited_from IS NOT NULL THEN 'inherited — a parsed certificate names ancestor '::text || e.certificate_inherited_from
            WHEN cr.found_at_depth = 0 AND b.printed_tag IS NOT NULL AND b.printed_tag <> e.tag THEN ('certificate on file — Metrc''s lab result for this tag names this certificate, and the document itself prints a DIFFERENT tag, '::text || b.printed_tag) || '. One certificate covers a whole batch; this tag is a member the document does not list by name.'::text
            WHEN cr.found_at_depth = 0 THEN 'certificate on file — Metrc''s lab result for this tag names this certificate; the document itself prints no tag we could read, so it does not name this package'::text
            WHEN cr.found_at_depth > 0 THEN ('inherited via Metrc — the lab result for ancestor '::text || cr.certificate_on_package) || ' names this certificate'::text
            WHEN e.evidence_source = 'lab result only'::text THEN 'lab result only — Metrc holds the result and that laboratory attached no certificate document'::text
            ELSE 'none — no certificate on this tag, its lineage, or any Metrc lab result'::text
        END AS certificate_grade,
    cr.found_at_depth AS certificate_hops,
    cr.cert_client AS certificate_client,
    cr.cert_license AS certificate_client_license
   FROM mv_tag_evidence e
     LEFT JOIN v_certificate_resolved cr ON cr.package_tag = e.tag
     LEFT JOIN LATERAL ( SELECT d.storage_path,
            c.lab_report_id,
            c.report_date,
            c.total_thc,
            c.package_tag_on_document AS printed_tag
           FROM metrc_lab_results l
             JOIN metrc_documents d ON d.metrc_id = l.document_file_id AND d.doc_type = 'coa'::text
             LEFT JOIN coa_extract c ON c.document_id = l.document_file_id
          WHERE l.package_tag = cr.certificate_on_package AND l.document_file_id IS NOT NULL
         LIMIT 1) b ON true;
create or replace view public.v_tag_lifecycle as
 WITH pkg AS (
         SELECT DISTINCT ON (p.tag) p.tag,
            p.item_name,
            p.license,
            p.location,
            p.packaged_on,
            p.quantity,
            p.uom,
            p.finished,
            p.source_state,
            p.raw
           FROM metrc_packages p
          WHERE p.tag IS NOT NULL
          ORDER BY p.tag, (COALESCE(p.quantity, 0::numeric) > 0::numeric AND NOT COALESCE(p.finished, false)) DESC, (p.source_state = 'active'::text) DESC NULLS LAST, p.synced_at DESC NULLS LAST
        ), harv AS (
         SELECT k_1.tag,
            h_1.name AS harvest_name,
            h_1.harvest_start,
            h_1.flower_room,
            (h_1.raw ->> 'FinishedDate'::text)::date AS harvest_finished_on
           FROM pkg k_1
             LEFT JOIN metrc_harvests h_1 ON h_1.name = split_part(COALESCE(k_1.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text, 1)
        ), outb AS (
         SELECT DISTINCT ON (t.package_tag) t.package_tag,
            t.manifest_number,
            t.received_on AS shipped_on,
            t.destination_facility,
            t.destination_licence,
            COALESCE(t.source_row ->> 'Type'::text, '(type not recorded)'::text) AS transfer_type,
            NULLIF(btrim(t.source_row ->> 'Created by User'::text), ''::text) AS manifest_created_by,
            NULLIF(btrim(t.source_row ->> 'Received by User'::text), ''::text) AS manifest_received_by
           FROM metrc_rpt_package_transfers t
          ORDER BY t.package_tag, t.received_on DESC NULLS LAST
        ), inv AS (
         SELECT DISTINCT ON (o_1.package_tag) o_1.package_tag,
            s.invoice_number,
            s.total_usd,
            s.payment_status,
            s.order_date
           FROM outb o_1
             JOIN mv_forensic_sales s ON NOT s.cancelled AND (s.manifest_number = o_1.manifest_number OR s.buyer_licence = o_1.destination_licence AND s.order_date >= (o_1.shipped_on - 7) AND s.order_date <= (o_1.shipped_on + 7))
          ORDER BY o_1.package_tag, (s.manifest_number = o_1.manifest_number) DESC, s.order_date
        )
 SELECT k.tag,
    k.item_name,
    COALESCE(k.raw #>> '{Item,ProductCategoryName}'::text[], '(uncategorised)'::text) AS category,
    k.raw #>> '{Item,StrainName}'::text[] AS strain,
    k.license AS held_under_licence,
    h.harvest_name AS stage1_harvest,
    h.harvest_start AS stage1_cut_on,
    h.flower_room AS stage1_grown_in,
    COALESCE(h.harvest_name, 'NOT FROM A HARVEST OF OURS — bought in or made from another package'::text) AS stage1_note,
    k.packaged_on AS stage2_packaged_on,
    NULLIF(k.raw ->> 'SourcePackageLabels'::text, ''::text) AS stage2_made_from_packages,
    NULLIF(k.raw ->> 'ProductionBatchNumber'::text, ''::text) AS stage2_production_batch,
    (k.raw ->> 'LabTestingStateDate'::text)::date AS stage3_submitted_on,
    (k.raw ->> 'LabTestingRecordedDate'::text)::date AS stage3_result_on,
    k.raw ->> 'LabTestingState'::text AS stage3_lab_state,
    ev.lab_name AS stage3_laboratory,
    ev.certificate_id AS stage3_certificate,
    ev.certificate_date AS stage3_certificate_date,
    ev.certificate_document AS stage3_coa_document,
    ev.evidence_source AS stage3_evidence_basis,
    COALESCE(ev.why_no_certificate,
        CASE
            WHEN ev.certificate_document IS NULL THEN 'No certificate document held for this tag.'::text
            ELSE NULL::text
        END) AS stage3_note,
    o.manifest_number AS stage4_manifest,
    o.shipped_on AS stage4_shipped_on,
    o.destination_facility AS stage4_shipped_to,
    o.destination_licence AS stage4_buyer_licence,
    o.transfer_type AS stage4_transfer_type,
    o.manifest_created_by AS stage4_created_by,
    o.manifest_received_by AS stage4_received_by,
    ( SELECT d.storage_path
           FROM metrc_documents d
          WHERE d.manifest_number = o.manifest_number AND d.doc_type ~~* '%manifest%'::text
         LIMIT 1) AS stage4_manifest_document,
        CASE
            WHEN o.manifest_number IS NULL THEN 'STILL HELD — this tag has not left our licences, so there is no manifest yet.'::text
            ELSE NULL::text
        END AS stage4_note,
    i.invoice_number AS stage5_apex_invoice,
    i.order_date AS stage5_invoice_date,
    i.total_usd AS stage5_invoice_usd,
    i.payment_status AS stage5_payment_status,
        CASE
            WHEN o.manifest_number IS NULL THEN 'Not shipped, so nothing to invoice.'::text
            WHEN i.invoice_number IS NULL AND f_is_ours(o.destination_licence) THEN 'INTERNAL MOVE between our own licences — not a sale, no invoice expected.'::text
            WHEN i.invoice_number IS NULL AND NOT f_can_be_a_customer(o.destination_licence) THEN 'Destination is a laboratory or a transporter — not a sale, no invoice expected.'::text
            WHEN i.invoice_number IS NULL THEN 'NO APEX INVOICE FOUND for this shipment. This is a gap to investigate.'::text
            ELSE NULL::text
        END AS stage5_note,
    COALESCE(k.finished, false) AS stage6_finished,
    (k.raw ->> 'FinishedDate'::text)::date AS stage6_finished_on,
    k.location AS audit_room,
    round(f_to_pounds(k.quantity, k.uom), 3) AS audit_lb,
    k.quantity AS audit_quantity,
    k.uom AS audit_uom,
        CASE
            WHEN COALESCE(k.finished, false) THEN 'CLOSED — nothing physical to inspect. The record '::text || 'is the evidence.'::text
            WHEN COALESCE(k.quantity, 0::numeric) = 0::numeric THEN 'ZERO QUANTITY but not marked finished — the tag '::text || 'should be closed out in Metrc.'::text
            WHEN o.manifest_number IS NOT NULL AND o.shipped_on IS NOT NULL THEN ((('SHIPPED on '::text || o.shipped_on) || ' to '::text) || COALESCE(o.destination_facility, 'a licensee'::text)) || '. Not on site.'::text
            WHEN COALESCE(k.location, ''::text) = ''::text THEN 'ON SITE but Metrc records no room. Find it by tag.'::text
            ELSE ((('ON SITE — '::text || k.location) || ', licence '::text) || k.license) || '. Inspect the physical tag against this record.'::text
        END AS where_to_audit,
    ((('https://'::text || COALESCE(( SELECT lower(btrim(s.value)) AS lower
           FROM integration_secrets s
          WHERE s.name = 'METRC_STATE'::text), 'ma'::text)) || '.metrc.com/industry/'::text) || k.license) || '/packages'::text AS metrc_screen
   FROM pkg k
     LEFT JOIN harv h ON h.tag = k.tag
     LEFT JOIN v_tag_evidence ev ON ev.tag = k.tag
     LEFT JOIN outb o ON o.package_tag = k.tag
     LEFT JOIN inv i ON i.package_tag = k.tag;
create or replace view public.v_tag_master as
 SELECT v.tag,
    v.item,
    v.category,
    v.strain,
    v.licence,
    v.ownership,
    v.grown_or_processed_by,
    v.room,
    v.packaged_on,
    v.finished,
    v.finished_on,
    v.on_hand_lb,
    v.source_harvests,
    v.source_packages,
    v.manifests_in,
    v.received_from,
    v.first_received,
    v.manifests_out,
    v.shipped_to,
    v.last_shipped,
    v.shipped_lb,
    v.coa_document,
    v.coa_report_date,
    v.total_thc,
    v.total_cbd,
    v.total_terpenes,
    v.total_cannabinoids,
    v.coa_client,
    v.coa_client_licence,
    v.manifest_on_coa,
    v.sample_id,
    v.coa_status,
    v.metrc_lab_rows,
    v.metrc_last_test,
    v.metrc_any_fail,
    v.point_in_time_history,
    v.known_from,
    v.tag_status,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( WITH universe AS (
                 SELECT DISTINCT upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag
                   FROM metrc_packages
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_package_transfers.package_tag)) AS upper
                   FROM metrc_rpt_package_transfers
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_point_in_time.tag)) AS upper
                   FROM metrc_rpt_point_in_time
                  WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_packages_inventory.package_tag)) AS upper
                   FROM metrc_rpt_packages_inventory
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_lab_results.package_tag)) AS upper
                   FROM metrc_rpt_lab_results
                  WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(coa_extract.package_tag)) AS upper
                   FROM coa_extract
                  WHERE coa_extract.package_tag IS NOT NULL
                UNION
                 SELECT DISTINCT upper(btrim(metrc_rpt_adjustments.package_tag)) AS upper
                   FROM metrc_rpt_adjustments
                  WHERE metrc_rpt_adjustments.package_tag IS NOT NULL
                ), pkg AS (
                 SELECT upper(btrim(metrc_packages.raw ->> 'Label'::text)) AS tag,
                    metrc_packages.license,
                    metrc_packages.raw,
                    row_number() OVER (PARTITION BY (upper(btrim(metrc_packages.raw ->> 'Label'::text))) ORDER BY (metrc_packages.raw ->> 'LastModified'::text) DESC NULLS LAST) AS rn
                   FROM metrc_packages
                ), xfer_item AS (
                 SELECT upper(btrim(metrc_rpt_package_transfers.package_tag)) AS tag,
                    max(metrc_rpt_package_transfers.item) AS item,
                    max(metrc_rpt_package_transfers.category) AS category,
                    max(metrc_rpt_package_transfers.strain) AS strain
                   FROM metrc_rpt_package_transfers
                  GROUP BY (upper(btrim(metrc_rpt_package_transfers.package_tag)))
                ), inbound AS (
                 SELECT upper(btrim(v_transfer_line.package_tag)) AS tag,
                    string_agg(DISTINCT v_transfer_line.manifest_number, ', '::text) AS manifests,
                    min(v_transfer_line.received_on) AS first_received,
                    string_agg(DISTINCT COALESCE(v_transfer_line.origin_facility, v_transfer_line.origin_licence), ', '::text) AS froms,
                    round(sum(v_transfer_line.pounds), 3) AS lb
                   FROM v_transfer_line
                  WHERE (v_transfer_line.direction = ANY (ARRAY['INBOUND'::text, 'INTERNAL'::text])) AND v_transfer_line.voided <> 'True'::text
                  GROUP BY (upper(btrim(v_transfer_line.package_tag)))
                ), outbound AS (
                 SELECT upper(btrim(v_transfer_line.package_tag)) AS tag,
                    string_agg(DISTINCT v_transfer_line.manifest_number, ', '::text) AS manifests,
                    max(v_transfer_line.received_on) AS last_shipped,
                    string_agg(DISTINCT COALESCE(v_transfer_line.dest_facility, v_transfer_line.dest_licence), ', '::text) AS tos,
                    round(sum(v_transfer_line.pounds), 3) AS lb
                   FROM v_transfer_line
                  WHERE (v_transfer_line.direction = ANY (ARRAY['OUTBOUND'::text, 'INTERNAL'::text])) AND v_transfer_line.voided <> 'True'::text
                  GROUP BY (upper(btrim(v_transfer_line.package_tag)))
                ), coa AS (
                 SELECT upper(btrim(coa_extract.package_tag)) AS tag,
                    count(*) AS n_coa,
                    max(coa_extract.document_id) AS document_id,
                    max(coa_extract.report_date) AS report_date,
                    max(coa_extract.total_thc) AS total_thc,
                    max(coa_extract.total_cbd) AS total_cbd,
                    max(coa_extract.total_terpenes) AS total_terpenes,
                    max(coa_extract.total_cannabinoids) AS total_cannabinoids,
                    max(coa_extract.client_name) AS coa_client,
                    max(coa_extract.client_license) AS coa_client_licence,
                    max(coa_extract.manifest_on_coa) AS manifest_on_coa,
                    max(coa_extract.sample_id) AS sample_id
                   FROM coa_extract
                  WHERE coa_extract.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(coa_extract.package_tag)))
                ), lab AS (
                 SELECT upper(btrim(metrc_rpt_lab_results.package_tag)) AS tag,
                    count(*) AS n_lab,
                    max(metrc_rpt_lab_results.test_date)::text AS last_test,
                    bool_or(lower(COALESCE(metrc_rpt_lab_results.overall_passed, ''::text)) = ANY (ARRAY['false'::text, 'fail'::text, 'failed'::text, 'no'::text])) AS any_fail
                   FROM metrc_rpt_lab_results
                  WHERE metrc_rpt_lab_results.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(metrc_rpt_lab_results.package_tag)))
                ), pit AS (
                 SELECT upper(btrim(metrc_rpt_point_in_time.tag)) AS tag,
                    string_agg(DISTINCT (metrc_rpt_point_in_time.as_of_date::text || ' @ '::text) || COALESCE(metrc_rpt_point_in_time.location, '(no room)'::text), ' | '::text) AS snapshots
                   FROM metrc_rpt_point_in_time
                  WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
                  GROUP BY (upper(btrim(metrc_rpt_point_in_time.tag)))
                )
         SELECT u.tag,
            COALESCE((p.raw -> 'Item'::text) ->> 'Name'::text, xi.item) AS item,
            COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, ''::text), xi.category, '(unknown)'::text) AS category,
            COALESCE(NULLIF((p.raw -> 'Item'::text) ->> 'StrainName'::text, ''::text), xi.strain, f_strain_from_item((p.raw -> 'Item'::text) ->> 'Name'::text)) AS strain,
            p.license AS licence,
                CASE
                    WHEN p.raw IS NULL THEN 'UNKNOWN — tag not in package mirror'::text
                    WHEN f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), ''::text)) THEN 'OURS'::text
                    ELSE 'THIRD PARTY'::text
                END AS ownership,
            COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text) AS grown_or_processed_by,
            COALESCE(NULLIF(p.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS room,
            (p.raw ->> 'PackagedDate'::text)::date AS packaged_on,
            COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) AS finished,
            (p.raw ->> 'FinishedDate'::text)::date AS finished_on,
                CASE
                    WHEN p.raw IS NULL THEN NULL::numeric
                    ELSE round(f_to_pounds(COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(p.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3)
                END AS on_hand_lb,
            NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvests,
            NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
            ib.manifests AS manifests_in,
            ib.froms AS received_from,
            ib.first_received,
            ob.manifests AS manifests_out,
            ob.tos AS shipped_to,
            ob.last_shipped,
            ob.lb AS shipped_lb,
            c.document_id AS coa_document,
            c.report_date AS coa_report_date,
            c.total_thc,
            c.total_cbd,
            c.total_terpenes,
            c.total_cannabinoids,
            c.coa_client,
            c.coa_client_licence,
            c.manifest_on_coa,
            c.sample_id,
                CASE
                    WHEN c.tag IS NOT NULL THEN 'COA MATCHED ON TAG'::text
                    WHEN l.tag IS NOT NULL THEN 'NO COA — Metrc lab result only'::text
                    ELSE 'NO COA AND NO LAB RESULT'::text
                END AS coa_status,
            l.n_lab AS metrc_lab_rows,
            l.last_test AS metrc_last_test,
            l.any_fail AS metrc_any_fail,
            pit.snapshots AS point_in_time_history,
            concat_ws(' + '::text,
                CASE
                    WHEN p.raw IS NOT NULL THEN 'package mirror'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ib.tag IS NOT NULL THEN 'inbound manifest'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ob.tag IS NOT NULL THEN 'outbound manifest'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN c.tag IS NOT NULL THEN 'COA'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN l.tag IS NOT NULL THEN 'Metrc lab'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN pit.tag IS NOT NULL THEN 'point-in-time'::text
                    ELSE NULL::text
                END) AS known_from,
                CASE
                    WHEN p.raw IS NULL AND ob.tag IS NOT NULL THEN 'SHIPPED — no package record held'::text
                    WHEN p.raw IS NULL THEN 'NOT IN PACKAGE MIRROR'::text
                    WHEN COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) AND ob.tag IS NOT NULL THEN 'CLOSED — shipped out'::text
                    WHEN COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) THEN 'CLOSED — consumed or adjusted'::text
                    WHEN ob.tag IS NOT NULL THEN 'OPEN — partially shipped'::text
                    ELSE 'ON HAND'::text
                END AS tag_status
           FROM universe u
             LEFT JOIN pkg p ON p.tag = u.tag AND p.rn = 1
             LEFT JOIN xfer_item xi ON xi.tag = u.tag
             LEFT JOIN inbound ib ON ib.tag = u.tag
             LEFT JOIN outbound ob ON ob.tag = u.tag
             LEFT JOIN coa c ON c.tag = u.tag
             LEFT JOIN lab l ON l.tag = u.tag
             LEFT JOIN pit ON pit.tag = u.tag) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_third_party_chain as
 SELECT v.supplier,
    v.origin_license,
    v.inbound_manifest,
    v.received_on,
    v.tag,
    v.item_name,
    v.strain,
    v.category,
    v.held_under,
    v.location,
    v.received_qty,
    v.remaining_qty,
    v.uom,
    v.consumed_qty,
    v.pct_consumed,
    v.lab_state,
    v.lab_state_on,
    v.production_batch,
    v.made_from,
    v.finished,
    v.days_since_received,
    v."position",
    v.flag,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( WITH inc AS (
                 SELECT p.tag,
                    p.item_name,
                    p.license AS held_under,
                    p.location,
                    p.quantity,
                    p.uom,
                    p.packaged_on,
                    p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS origin_license,
                    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '(supplier not recorded)'::text) AS supplier,
                    p.raw ->> 'ReceivedFromManifestNumber'::text AS inbound_manifest,
                    (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
                    (p.raw ->> 'ReceivedQuantity'::text)::numeric AS received_qty,
                    (p.raw ->> 'CreatedQuantity'::text)::numeric AS created_qty,
                    p.raw ->> 'LabTestingState'::text AS lab_state,
                    (p.raw ->> 'LabTestingStateDate'::text)::date AS lab_state_on,
                    p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
                    p.raw #>> '{Item,StrainName}'::text[] AS strain,
                    p.raw ->> 'SourcePackageLabels'::text AS made_from,
                    p.raw ->> 'SourceProductionBatchNumbers'::text AS production_batch,
                    (p.raw ->> 'IsFinished'::text)::boolean AS finished
                   FROM metrc_packages p
                  WHERE (COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text])) AND COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ''::text
                )
         SELECT inc.supplier,
            inc.origin_license,
            inc.inbound_manifest,
            inc.received_on,
            inc.tag,
            inc.item_name,
            inc.strain,
            inc.category,
            inc.held_under,
            inc.location,
            inc.received_qty,
            inc.quantity AS remaining_qty,
            inc.uom,
            round(COALESCE(inc.received_qty, 0::numeric) - COALESCE(inc.quantity, 0::numeric)) AS consumed_qty,
                CASE
                    WHEN COALESCE(inc.received_qty, 0::numeric) > 0::numeric THEN round(100::numeric * (COALESCE(inc.received_qty, 0::numeric) - COALESCE(inc.quantity, 0::numeric)) / inc.received_qty, 1)
                    ELSE NULL::numeric
                END AS pct_consumed,
            inc.lab_state,
            inc.lab_state_on,
            inc.production_batch,
            inc.made_from,
            inc.finished,
            CURRENT_DATE - inc.received_on AS days_since_received,
                CASE
                    WHEN inc.quantity = 0::numeric AND inc.finished THEN 'FULLY USED - consumed into product or sold'::text
                    WHEN inc.quantity = 0::numeric THEN 'Drawn to zero but not marked finished'::text
                    WHEN COALESCE(inc.received_qty, 0::numeric) = COALESCE(inc.quantity, 0::numeric) THEN 'UNTOUCHED - nothing drawn from it yet'::text
                    ELSE ('PARTLY USED - '::text || round(100::numeric * (COALESCE(inc.received_qty, 0::numeric) - COALESCE(inc.quantity, 0::numeric)) / NULLIF(inc.received_qty, 0::numeric), 1)) || ' percent drawn'::text
                END AS "position",
                CASE
                    WHEN inc.lab_state = 'TestFailed'::text THEN ('FAILED TESTING - recover from '::text || inc.supplier) || ' before writing anything off'::text
                    WHEN inc.quantity > 0::numeric AND (CURRENT_DATE - inc.received_on) > 90 THEN ('SITTING '::text || (CURRENT_DATE - inc.received_on)) || ' DAYS - purchased material tying up cash'::text
                    WHEN inc.lab_state = 'NotSubmitted'::text AND inc.quantity > 0::numeric THEN 'NEVER SUBMITTED FOR TESTING'::text
                    ELSE 'Normal'::text
                END AS flag
           FROM inc
          ORDER BY inc.received_on DESC NULLS LAST, inc.supplier) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_third_party_cycle_time as
 SELECT supplier,
    count(*) AS packages,
    round(sum(qty_received)) AS qty_in,
    round(sum(qty_remaining)) AS qty_still_here,
    round(avg(days_receipt_to_test), 1) AS avg_days_to_test,
    round(avg(days_receipt_to_first_output), 1) AS avg_days_to_first_output,
    round(avg(days_receipt_to_first_sale), 1) AS avg_days_receipt_to_sale,
    max(days_since_received) AS oldest_untouched_days,
    count(*) FILTER (WHERE "position" ~~ 'SITTING%'::text) AS sitting_untouched,
    count(*) FILTER (WHERE "position" ~~ 'COMPLETE%'::text) AS completed,
    round(avg(recovery_pct), 1) AS avg_recovery_pct
   FROM v_third_party_lifecycle
  GROUP BY supplier
  ORDER BY (round(sum(qty_received))) DESC NULLS LAST;
create or replace view public.v_third_party_downstream as
 SELECT src.supplier,
    src.tag AS source_tag,
    src.item_name AS source_item,
    src.strain,
    src.received_qty,
    src.uom AS source_uom,
    child.tag AS made_into_tag,
    child.item_name AS made_into,
    child.raw #>> '{Item,ProductCategoryName}'::text[] AS made_into_category,
    child.quantity AS made_qty,
    child.uom AS made_uom,
    child.packaged_on AS made_on,
    child.raw ->> 'LabTestingState'::text AS made_lab_state,
    child.license AS made_under
   FROM v_third_party_chain src
     JOIN metrc_packages child ON string_to_array(replace(COALESCE(child.raw ->> 'SourcePackageLabels'::text, ''::text), ' '::text, ''::text), ','::text) @> ARRAY[src.tag]
  ORDER BY src.supplier, src.received_on DESC NULLS LAST;
create or replace view public.v_third_party_forensic as
 SELECT v.tag,
    v.item,
    v.category,
    v.strain,
    v.supplier,
    v.supplier_licence,
    v.our_licence,
    v.inbound_manifest,
    v.delivered_by,
    v.date_received,
    v.date_supplier_packaged,
    v.lb_received,
    v.age_on_arrival_days,
    v.current_room,
    v.current_sublocation,
    v.lb_on_hand,
    v.date_processed,
    v.children,
    v.made_into,
    v.made_lb,
    v.child_tags,
    v.date_sold,
    v.outbound_manifest,
    v.sold_to,
    v.lb_sold,
    v.lb_adjusted,
    v.destroy_reason,
    v.destroy_note,
    v.destroyed_by,
    v.date_destroyed,
    v.days_held_total,
    v.days_to_process,
    v.days_to_sell,
    v.days_unsold_still_here,
    v.ageing_band,
    v.date_tested,
    v.lab_tests,
    v.lab_failures,
    v.total_thc_pct,
    v.moisture_pct,
    v.lab_name,
    v.failed_tests,
    v.lab_result,
    v.status,
    v.metrc_link,
    v.metrc_package_id,
    v.manifest_document,
    v.destroy_rows_verbatim,
    v.year_received,
    v.lab_state,
    v.initial_lab_state,
    v.lab_state_date,
    v.contains_remediated,
    v.remediation_date,
    v.contains_decontaminated,
    v.decontamination_date,
    v.date_failed,
    v.exit_child_tags,
    v.exit_manifest,
    v.exit_sold_to,
    v.exit_shipped_on,
    v.exit_lb,
    v.exit_sold_usd,
    v.exit_sold_as,
    v.location_history,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( WITH pk AS (
                 SELECT DISTINCT ON ((upper(btrim(p.raw ->> 'Label'::text)))) upper(btrim(p.raw ->> 'Label'::text)) AS tag,
                    p.raw,
                    p.license
                   FROM metrc_packages p
                  WHERE NOT f_is_ours(COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text), ''::text)) AND NULLIF(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                  ORDER BY (upper(btrim(p.raw ->> 'Label'::text))), (p.raw ->> 'LastModified'::text) DESC NULLS LAST
                ), outb AS (
                 SELECT upper(btrim(v_transfer_line.package_tag)) AS tag,
                    min(v_transfer_line.received_on) AS first_shipped,
                    max(v_transfer_line.received_on) AS last_shipped,
                    string_agg(DISTINCT v_transfer_line.manifest_number, ', '::text) AS manifests,
                    string_agg(DISTINCT COALESCE(v_transfer_line.dest_facility, v_transfer_line.dest_licence), ', '::text) AS to_whom,
                    round(sum(v_transfer_line.pounds), 3) AS lb
                   FROM v_transfer_line
                  WHERE v_transfer_line.direction = 'OUTBOUND'::text AND v_transfer_line.voided <> 'True'::text
                  GROUP BY (upper(btrim(v_transfer_line.package_tag)))
                ), exit_trace AS (
                 SELECT upper(btrim(t.source_package)) AS parent_tag,
                    string_agg(DISTINCT t.package_tag, ', '::text) AS child_tags,
                    string_agg(DISTINCT t.manifest_number, ', '::text) AS child_manifests,
                    string_agg(DISTINCT t.destination_facility, ', '::text) AS child_sold_to,
                    min(t.received_on) AS child_shipped_on,
                    round(sum(COALESCE(
                        CASE
                            WHEN (t.source_row ->> 'Weight Ship''d'::text) ~ '^[0-9.]+$'::text THEN (t.source_row ->> 'Weight Ship''d'::text)::numeric
                            ELSE NULL::numeric
                        END, t.shipped_lb)), 3) AS child_lb,
                    round(sum(NULLIF(t.source_row ->> 'Receiver Wholesale Price'::text, ''::text)::numeric), 2) AS child_sold_usd,
                    string_agg(DISTINCT t.item, ' | '::text) AS child_sold_as
                   FROM metrc_rpt_package_transfers t
                  WHERE NULLIF(btrim(t.source_package), ''::text) IS NOT NULL AND COALESCE(t.source_row ->> 'Voided'::text, 'False'::text) <> 'True'::text
                  GROUP BY (upper(btrim(t.source_package)))
                ), kids AS (
                 SELECT btrim(pt.tag) AS tag,
                    count(*) AS children,
                    min((c.raw ->> 'PackagedDate'::text)::date) AS first_processed,
                    string_agg(DISTINCT COALESCE((c.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, '?'::text), ', '::text) AS made_into,
                    string_agg(DISTINCT upper(btrim(c.raw ->> 'Label'::text)), ', '::text) AS child_tags,
                    round(sum(f_to_pounds(COALESCE((c.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(c.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)) / GREATEST(array_length(string_to_array(c.raw ->> 'SourcePackageLabels'::text, ', '::text), 1), 1)::numeric), 3) AS made_lb
                   FROM metrc_packages c
                     JOIN LATERAL unnest(string_to_array(c.raw ->> 'SourcePackageLabels'::text, ', '::text)) pt(tag) ON true
                  WHERE NULLIF(c.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL
                  GROUP BY (btrim(pt.tag))
                ), adj AS (
                 SELECT upper(btrim(metrc_rpt_adjustments.package_tag)) AS tag,
                    round(sum(f_to_pounds(metrc_rpt_adjustments.quantity, metrc_rpt_adjustments.uom)), 3) AS lb,
                    string_agg(DISTINCT metrc_rpt_adjustments.reason, ', '::text) AS reasons,
                    string_agg(DISTINCT metrc_rpt_adjustments.source_row ->> 'Note'::text, ' | '::text) AS notes,
                    string_agg(DISTINCT metrc_rpt_adjustments.source_row ->> 'User'::text, ', '::text) AS by_whom,
                    max(metrc_rpt_adjustments.adjusted_on) AS on_date,
                    jsonb_agg(metrc_rpt_adjustments.source_row ORDER BY metrc_rpt_adjustments.adjusted_on) AS verbatim
                   FROM metrc_rpt_adjustments
                  WHERE metrc_rpt_adjustments.quantity IS NOT NULL AND f_is_weight(metrc_rpt_adjustments.uom)
                  GROUP BY (upper(btrim(metrc_rpt_adjustments.package_tag)))
                ), lab AS (
                 SELECT upper(btrim(metrc_lab_results.package_tag)) AS tag,
                    count(*) AS tests,
                    count(*) FILTER (WHERE metrc_lab_results.passed IS FALSE) AS failures,
                    min(metrc_lab_results.result_date) AS first_tested,
                    string_agg(DISTINCT metrc_lab_results.lab_facility, ', '::text) AS labs,
                    max(metrc_lab_results.result) FILTER (WHERE metrc_lab_results.test_name ~~* 'Total THC (%%)%%'::text) AS thc,
                    max(metrc_lab_results.result) FILTER (WHERE metrc_lab_results.test_name ~~* 'Moisture Content%%'::text) AS moisture,
                    string_agg(DISTINCT metrc_lab_results.test_name, ' | '::text) FILTER (WHERE metrc_lab_results.passed IS FALSE) AS failed_tests,
                    max(metrc_lab_results.result_date) FILTER (WHERE metrc_lab_results.passed IS FALSE) AS last_fail_date
                   FROM metrc_lab_results
                  WHERE metrc_lab_results.package_tag IS NOT NULL
                  GROUP BY (upper(btrim(metrc_lab_results.package_tag)))
                ), loc AS (
                 SELECT upper(btrim(metrc_rpt_point_in_time.tag)) AS tag,
                    string_agg(((metrc_rpt_point_in_time.as_of_date::text || ' @ '::text) || COALESCE(metrc_rpt_point_in_time.location, '?'::text)) || COALESCE(' / '::text || metrc_rpt_point_in_time.sublocation, ''::text), '  →  '::text ORDER BY metrc_rpt_point_in_time.as_of_date) AS history
                   FROM metrc_rpt_point_in_time
                  WHERE metrc_rpt_point_in_time.record_type = 'Package'::text
                  GROUP BY (upper(btrim(metrc_rpt_point_in_time.tag)))
                )
         SELECT pk.tag,
            (pk.raw -> 'Item'::text) ->> 'Name'::text AS item,
            COALESCE((pk.raw -> 'Item'::text) ->> 'ProductCategoryName'::text, '(unknown)'::text) AS category,
            COALESCE(NULLIF((pk.raw -> 'Item'::text) ->> 'StrainName'::text, ''::text), f_strain_from_item((pk.raw -> 'Item'::text) ->> 'Name'::text)) AS strain,
            COALESCE(NULLIF(pk.raw ->> 'ItemFromFacilityName'::text, ''::text), '(unknown)'::text) AS supplier,
            NULLIF(pk.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) AS supplier_licence,
            pk.license AS our_licence,
            NULLIF(pk.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
            NULLIF(pk.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS delivered_by,
            "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date AS date_received,
            (pk.raw ->> 'PackagedDate'::text)::date AS date_supplier_packaged,
            round(f_to_pounds(COALESCE((pk.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric), COALESCE(NULLIF(pk.raw ->> 'UnitOfMeasureName'::text, ''::text), 'Grams'::text)), 3) AS lb_received,
                CASE
                    WHEN NULLIF(pk.raw ->> 'ReceivedDateTime'::text, ''::text) IS NOT NULL AND ((pk.raw ->> 'PackagedDate'::text)::date) IS NOT NULL THEN "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date - ((pk.raw ->> 'PackagedDate'::text)::date)
                    ELSE NULL::integer
                END AS age_on_arrival_days,
            COALESCE(NULLIF(pk.raw ->> 'LocationName'::text, ''::text), '(no room)'::text) AS current_room,
            NULLIF(pk.raw ->> 'SublocationName'::text, ''::text) AS current_sublocation,
            round(( SELECT COALESCE(sum(f_to_pounds(cp.quantity, cp.uom)), 0::numeric) AS "coalesce"
                   FROM metrc_packages cp
                  WHERE cp.tag = pk.tag AND (cp.source_state = ANY (ARRAY['active'::text, 'intransit'::text])) AND NOT COALESCE(cp.finished, false)), 3) AS lb_on_hand,
            kids.first_processed AS date_processed,
            kids.children,
            kids.made_into,
            kids.made_lb,
            kids.child_tags,
            outb.first_shipped AS date_sold,
            outb.manifests AS outbound_manifest,
            outb.to_whom AS sold_to,
            outb.lb AS lb_sold,
            adj.lb AS lb_adjusted,
            adj.reasons AS destroy_reason,
            adj.notes AS destroy_note,
            adj.by_whom AS destroyed_by,
            adj.on_date AS date_destroyed,
                CASE
                    WHEN "left"(pk.raw ->> 'ReceivedDateTime'::text, 10) <> ''::text THEN COALESCE(outb.first_shipped, kids.first_processed, adj.on_date, CURRENT_DATE) - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date
                    ELSE NULL::integer
                END AS days_held_total,
                CASE
                    WHEN "left"(pk.raw ->> 'ReceivedDateTime'::text, 10) <> ''::text AND kids.first_processed IS NOT NULL THEN kids.first_processed - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date
                    ELSE NULL::integer
                END AS days_to_process,
                CASE
                    WHEN "left"(pk.raw ->> 'ReceivedDateTime'::text, 10) <> ''::text AND outb.first_shipped IS NOT NULL THEN outb.first_shipped - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date
                    ELSE NULL::integer
                END AS days_to_sell,
                CASE
                    WHEN COALESCE((pk.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND "left"(pk.raw ->> 'ReceivedDateTime'::text, 10) <> ''::text THEN CURRENT_DATE - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date
                    ELSE NULL::integer
                END AS days_unsold_still_here,
                CASE
                    WHEN COALESCE((pk.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND "left"(pk.raw ->> 'ReceivedDateTime'::text, 10) <> ''::text THEN
                    CASE
                        WHEN (CURRENT_DATE - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date) > 180 THEN 'OVER 180 DAYS — CASH TIED UP'::text
                        WHEN (CURRENT_DATE - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date) > 90 THEN '90-180 days'::text
                        WHEN (CURRENT_DATE - "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date) > 30 THEN '30-90 days'::text
                        ELSE 'under 30 days'::text
                    END
                    ELSE NULL::text
                END AS ageing_band,
            lab.first_tested AS date_tested,
            lab.tests AS lab_tests,
            lab.failures AS lab_failures,
            lab.thc AS total_thc_pct,
            lab.moisture AS moisture_pct,
            lab.labs AS lab_name,
            lab.failed_tests,
                CASE
                    WHEN lab.tag IS NULL THEN 'NO LAB RESULT IMPORTED'::text
                    WHEN lab.failures > 0 THEN 'FAILED'::text
                    WHEN lab.tests < 20 THEN ('PASSED — partial panel ('::text || lab.tests) || ' tests)'::text
                    ELSE ('PASSED — full panel ('::text || lab.tests) || ' tests)'::text
                END AS lab_result,
                CASE
                    WHEN adj.lb <= '-1'::integer::numeric AND COALESCE(lab.failures, 0::bigint) = 0 AND COALESCE(adj.notes, ''::text) = ''::text THEN 'DESTROYED — NO REASON GIVEN'::text
                    WHEN adj.lb <= '-1'::integer::numeric AND COALESCE(lab.failures, 0::bigint) = 0 THEN 'DESTROYED — no failing lab test'::text
                    WHEN adj.lb <= '-1'::integer::numeric THEN 'DESTROYED after a failed test'::text
                    WHEN COALESCE((pk.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric THEN 'ON HAND'::text
                    WHEN outb.tag IS NOT NULL AND kids.tag IS NOT NULL THEN 'PROCESSED THEN SOLD'::text
                    WHEN outb.tag IS NOT NULL THEN 'SOLD AS-IS'::text
                    WHEN ex.parent_tag IS NOT NULL THEN 'PROCESSED THEN SOLD — via child tag'::text
                    WHEN kids.tag IS NOT NULL THEN 'PROCESSED INTO PRODUCT'::text
                    ELSE 'UNEXPLAINED — record stops with nothing recorded'::text
                END AS status,
            ('https://ma.metrc.com/industry/'::text || pk.license) || '/packages'::text AS metrc_link,
            pk.raw ->> 'Id'::text AS metrc_package_id,
            mdoc.storage_path AS manifest_document,
            adj.verbatim AS destroy_rows_verbatim,
            EXTRACT(year FROM "left"(pk.raw ->> 'ReceivedDateTime'::text, 10)::date)::integer AS year_received,
            pk.raw ->> 'LabTestingState'::text AS lab_state,
            pk.raw ->> 'InitialLabTestingState'::text AS initial_lab_state,
            NULLIF(pk.raw ->> 'LabTestingStateDate'::text, ''::text)::date AS lab_state_date,
            (pk.raw ->> 'ContainsRemediatedProduct'::text)::boolean AS contains_remediated,
            NULLIF(pk.raw ->> 'RemediationDate'::text, ''::text) AS remediation_date,
            (pk.raw ->> 'ContainsDecontaminatedProduct'::text)::boolean AS contains_decontaminated,
            NULLIF(pk.raw ->> 'DecontaminationDate'::text, ''::text) AS decontamination_date,
            lab.last_fail_date AS date_failed,
            ex.child_tags AS exit_child_tags,
            ex.child_manifests AS exit_manifest,
            ex.child_sold_to AS exit_sold_to,
            ex.child_shipped_on AS exit_shipped_on,
            ex.child_lb AS exit_lb,
            ex.child_sold_usd AS exit_sold_usd,
            ex.child_sold_as AS exit_sold_as,
            loc.history AS location_history
           FROM pk
             LEFT JOIN outb ON outb.tag = pk.tag
             LEFT JOIN kids ON kids.tag = pk.tag
             LEFT JOIN adj ON adj.tag = pk.tag
             LEFT JOIN lab ON lab.tag = pk.tag
             LEFT JOIN exit_trace ex ON ex.parent_tag = pk.tag
             LEFT JOIN loc ON loc.tag = pk.tag
             LEFT JOIN ( SELECT metrc_documents.manifest_number,
                    min(metrc_documents.storage_path) AS storage_path
                   FROM metrc_documents
                  WHERE metrc_documents.doc_type = 'manifest'::text
                  GROUP BY metrc_documents.manifest_number) mdoc ON mdoc.manifest_number = NULLIF(pk.raw ->> 'ReceivedFromManifestNumber'::text, ''::text)) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_third_party_lifecycle as
 SELECT v.supplier,
    v.origin_license,
    v.inbound_manifest,
    v.received_on,
    v.tag,
    v.item_name,
    v.strain,
    v.category,
    v.held_under,
    v.location,
    v.qty_received,
    v.qty_remaining,
    v.uom,
    v.qty_consumed,
    v.lab_state,
    v.tested_on,
    v.days_receipt_to_test,
    v.products_made,
    v.became,
    v.output_qty,
    v.output_passed,
    v.output_failed,
    v.first_output_on,
    v.days_receipt_to_first_output,
    v.recovery_pct,
    v.first_shipped_on,
    v.outbound_manifests,
    v.sold_to,
    v.days_receipt_to_first_sale,
    v.days_since_received,
    v."position",
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( WITH inbound AS (
                 SELECT p.tag,
                    p.item_name,
                    p.license AS held_under,
                    p.location,
                    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '(supplier not recorded)'::text) AS supplier,
                    p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS origin_license,
                    p.raw ->> 'ReceivedFromManifestNumber'::text AS inbound_manifest,
                    (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
                    (p.raw ->> 'ReceivedQuantity'::text)::numeric AS qty_received,
                    p.quantity AS qty_remaining,
                    p.uom,
                    p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
                    p.raw #>> '{Item,StrainName}'::text[] AS strain,
                    p.raw ->> 'LabTestingState'::text AS lab_state,
                    (p.raw ->> 'LabTestingRecordedDate'::text)::date AS tested_on,
                    (p.raw ->> 'IsFinished'::text)::boolean AS finished,
                    (p.raw ->> 'FinishedDate'::text)::date AS finished_on
                   FROM metrc_packages p
                  WHERE (COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text])) AND COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ''::text
                ), made AS (
                 SELECT i_1.tag AS parent_tag,
                    count(*) AS children,
                    min(c.packaged_on) AS first_output_on,
                    max(c.packaged_on) AS last_output_on,
                    round(sum(c.quantity)) AS output_qty,
                    string_agg(DISTINCT c.raw #>> '{Item,ProductCategoryName}'::text[], ', '::text) AS became,
                    count(*) FILTER (WHERE (c.raw ->> 'LabTestingState'::text) = 'TestPassed'::text) AS output_passed,
                    count(*) FILTER (WHERE (c.raw ->> 'LabTestingState'::text) = 'TestFailed'::text) AS output_failed
                   FROM inbound i_1
                     JOIN metrc_packages c ON (c.raw ->> 'SourcePackageLabels'::text) ~~ (('%'::text || i_1.tag) || '%'::text)
                  GROUP BY i_1.tag
                ), sold AS (
                 SELECT i_1.tag AS parent_tag,
                    min(t.created_on) AS first_shipped_on,
                    count(DISTINCT t.manifest_number) AS outbound_manifests,
                    string_agg(DISTINCT t.recipient, ', '::text) AS sold_to
                   FROM inbound i_1
                     JOIN metrc_packages c ON (c.raw ->> 'SourcePackageLabels'::text) ~~ (('%'::text || i_1.tag) || '%'::text)
                     JOIN v_metrc_transfer_ledger t ON t.direction = 'outgoing'::text AND t.created_on >= c.packaged_on
                  GROUP BY i_1.tag
                )
         SELECT i.supplier,
            i.origin_license,
            i.inbound_manifest,
            i.received_on,
            i.tag,
            i.item_name,
            i.strain,
            i.category,
            i.held_under,
            i.location,
            i.qty_received,
            i.qty_remaining,
            i.uom,
            round(COALESCE(i.qty_received, 0::numeric) - COALESCE(i.qty_remaining, 0::numeric)) AS qty_consumed,
            i.lab_state,
            i.tested_on,
            i.tested_on - i.received_on AS days_receipt_to_test,
            m.children AS products_made,
            m.became,
            m.output_qty,
            m.output_passed,
            m.output_failed,
            m.first_output_on,
            m.first_output_on - i.received_on AS days_receipt_to_first_output,
                CASE
                    WHEN COALESCE(i.qty_received, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(m.output_qty, 0::numeric) / i.qty_received, 1)
                    ELSE NULL::numeric
                END AS recovery_pct,
            s.first_shipped_on,
            s.outbound_manifests,
            s.sold_to,
            s.first_shipped_on - i.received_on AS days_receipt_to_first_sale,
            CURRENT_DATE - i.received_on AS days_since_received,
                CASE
                    WHEN i.qty_remaining = 0::numeric AND s.first_shipped_on IS NOT NULL THEN ('COMPLETE - received, processed and sold in '::text || (s.first_shipped_on - i.received_on)) || ' days'::text
                    WHEN i.qty_remaining = 0::numeric AND m.children IS NOT NULL THEN 'PROCESSED - made into product, not yet traced to a sale'::text
                    WHEN i.qty_remaining = 0::numeric THEN 'DRAWN TO ZERO - no output package traced. Investigate.'::text
                    WHEN m.children IS NOT NULL THEN ((('IN PROCESS - part drawn, '::text || round(i.qty_remaining)) || ' '::text) || i.uom) || ' left'::text
                    WHEN (CURRENT_DATE - i.received_on) > 90 THEN ('SITTING '::text || (CURRENT_DATE - i.received_on)) || ' DAYS UNTOUCHED - purchased cash doing nothing'::text
                    ELSE 'RECEIVED - not yet drawn'::text
                END AS "position"
           FROM inbound i
             LEFT JOIN made m ON m.parent_tag = i.tag
             LEFT JOIN sold s ON s.parent_tag = i.tag
          ORDER BY i.received_on DESC NULLS LAST) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_third_party_remarks as
 SELECT v.tag,
    v.supplier,
    v.category,
    v.strain,
    v.date_supplier_packaged,
    v.date_received,
    v.age_on_arrival_days,
    v.date_processed,
    v.date_sold,
    v.date_destroyed,
    v.days_held_total,
    v.days_to_process,
    v.days_unsold_still_here,
    v.current_room,
    v.lb_on_hand,
    v.status,
    v.remarks,
    td.coa_certificate_id,
    td.coa_document_link,
    td.manifest_no,
    td.manifest_document_link,
    td.apex_invoice_no,
    td.apex_invoice_usd
   FROM ( SELECT f.tag,
            f.supplier,
            f.category,
            f.strain,
            f.date_supplier_packaged,
            f.date_received,
            f.age_on_arrival_days,
            f.date_processed,
            f.date_sold,
            f.date_destroyed,
            f.days_held_total,
            f.days_to_process,
            f.days_unsold_still_here,
            f.current_room,
            f.lb_on_hand,
            f.status,
            concat_ws(' '::text, ('Supplier packaged this '::text || COALESCE(f.date_supplier_packaged::text, 'on an unrecorded date'::text)) || '.'::text,
                CASE
                    WHEN f.date_received IS NOT NULL THEN (('WE TOOK DELIVERY '::text || f.date_received::text) || COALESCE(' on manifest '::text || f.inbound_manifest, ''::text)) ||
                    CASE
                        WHEN f.age_on_arrival_days IS NOT NULL THEN (' — already '::text || f.age_on_arrival_days) || ' DAYS OLD ON ARRIVAL. That age is the SUPPLIER''S, not ours.'::text
                        ELSE '.'::text
                    END
                    ELSE 'No delivery date recorded.'::text
                END,
                CASE
                    WHEN f.date_processed IS NOT NULL THEN ((((((((('USED IN OUR PROCESSING ON '::text || f.date_processed::text) || ' — '::text) || COALESCE(f.days_to_process::text, '?'::text)) || ' days after delivery — made into '::text) || COALESCE(f.made_into, 'product'::text)) || ' ('::text) || COALESCE(f.made_lb::text, '?'::text)) || ' lb'::text) || COALESCE(', child tags '::text || "left"(f.child_tags, 120), ''::text)) || ').'::text
                    ELSE ''::text
                END,
                CASE
                    WHEN f.date_sold IS NOT NULL THEN (((('Sold '::text || f.date_sold::text) || ' to '::text) || COALESCE(f.sold_to, ''::text)) || COALESCE(' on manifest '::text || f.outbound_manifest, ''::text)) || '.'::text
                    ELSE ''::text
                END,
                CASE
                    WHEN f.status ~~ 'DESTROYED%'::text THEN (((((((('DESTROYED '::text || COALESCE(f.date_destroyed::text, ''::text)) || ' by '::text) || COALESCE(f.destroyed_by, 'unknown'::text)) || ', reason '::text) || COALESCE(f.destroy_reason, 'NONE'::text)) || ', note "'::text) || COALESCE(f.destroy_note, 'none given'::text)) || '".'::text) ||
                    CASE
                        WHEN COALESCE(f.lab_failures, 0::bigint) = 0 THEN ' NO FAILING LAB TEST EXISTS FOR THIS TAG.'::text
                        ELSE ''::text
                    END
                    ELSE ''::text
                END,
                CASE
                    WHEN f.lb_on_hand > 0::numeric THEN (((((((('STILL ON HAND: '::text || f.lb_on_hand) || ' lb in '::text) || f.current_room) || COALESCE(' / '::text || f.current_sublocation, ''::text)) || ', unsold '::text) || COALESCE(f.days_unsold_still_here::text, '?'::text)) || ' days ('::text) || COALESCE(f.ageing_band, ''::text)) || ').'::text
                    WHEN f.date_processed IS NULL AND f.date_sold IS NULL AND f.status !~~ 'DESTROYED%'::text THEN 'NO OUTCOME RECORDED — open item.'::text
                    ELSE ''::text
                END) AS remarks
           FROM v_third_party_forensic f) v
     LEFT JOIN mv_tag_documents td ON td.tag = v.tag;
create or replace view public.v_tower_inventory as
 WITH f AS (
         SELECT conversion_factors.value AS r
           FROM conversion_factors
          WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
        ), s AS MATERIALIZED (
         SELECT v_stock_on_hand.origin,
            v_stock_on_hand.stream,
            v_stock_on_hand.license,
            v_stock_on_hand.lab_state,
            v_stock_on_hand.location,
            v_stock_on_hand.supplier,
            v_stock_on_hand.origin_license,
            v_stock_on_hand.packages,
            v_stock_on_hand.grams,
            v_stock_on_hand.pounds,
            v_stock_on_hand.oldest_days,
            v_stock_on_hand.oldest_packaged,
            v_stock_on_hand.strains,
            v_stock_on_hand.units,
            v_stock_on_hand.unit_of_measure,
            v_stock_on_hand.sold_by_weight,
            v_stock_on_hand.quantity_shown,
            v_stock_on_hand.stock_status
           FROM v_stock_on_hand
        ), tp AS MATERIALIZED (
         SELECT v_third_party_lifecycle.supplier,
            v_third_party_lifecycle.origin_license,
            v_third_party_lifecycle.inbound_manifest,
            v_third_party_lifecycle.received_on,
            v_third_party_lifecycle.tag,
            v_third_party_lifecycle.item_name,
            v_third_party_lifecycle.strain,
            v_third_party_lifecycle.category,
            v_third_party_lifecycle.held_under,
            v_third_party_lifecycle.location,
            v_third_party_lifecycle.qty_received,
            v_third_party_lifecycle.qty_remaining,
            v_third_party_lifecycle.uom,
            v_third_party_lifecycle.qty_consumed,
            v_third_party_lifecycle.lab_state,
            v_third_party_lifecycle.tested_on,
            v_third_party_lifecycle.days_receipt_to_test,
            v_third_party_lifecycle.products_made,
            v_third_party_lifecycle.became,
            v_third_party_lifecycle.output_qty,
            v_third_party_lifecycle.output_passed,
            v_third_party_lifecycle.output_failed,
            v_third_party_lifecycle.first_output_on,
            v_third_party_lifecycle.days_receipt_to_first_output,
            v_third_party_lifecycle.recovery_pct,
            v_third_party_lifecycle.first_shipped_on,
            v_third_party_lifecycle.outbound_manifests,
            v_third_party_lifecycle.sold_to,
            v_third_party_lifecycle.days_receipt_to_first_sale,
            v_third_party_lifecycle.days_since_received,
            v_third_party_lifecycle."position"
           FROM v_third_party_lifecycle
        ), sl AS MATERIALIZED (
         SELECT v_storage_limit_status.stream,
            v_storage_limit_status.location,
            v_storage_limit_status.max_lb,
            v_storage_limit_status.max_age_days,
            v_storage_limit_status.warn_at_pct,
            v_storage_limit_status.note,
            v_storage_limit_status.on_hand_lb,
            v_storage_limit_status.oldest_days,
            v_storage_limit_status.pct_of_limit,
            v_storage_limit_status.status
           FROM v_storage_limit_status
        )
 SELECT 'onhand_dried_flower_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Dried flower on hand, all licences'::text AS label,
    'stock'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.stream = 'Dried flower'::text
UNION ALL
 SELECT 'onhand_fresh_frozen_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Fresh frozen on hand, as recorded (still holds its water)'::text AS label,
    'stock'::text AS grp,
    'fresh_frozen_equiv'::text AS drill
   FROM s
  WHERE s.stream = 'Fresh frozen'::text
UNION ALL
 SELECT 'onhand_fresh_frozen_dry_equiv_lb'::text AS metric,
    round(sum(s.pounds) / (( SELECT f.r
           FROM f)), 1) AS value,
    'Fresh frozen in dry-equivalent pounds - the only figure comparable to dried flower'::text AS label,
    'stock'::text AS grp,
    'fresh_frozen_equiv'::text AS drill
   FROM s
  WHERE s.stream = 'Fresh frozen'::text
UNION ALL
 SELECT 'onhand_shake_trim_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Shake and trim on hand'::text AS label,
    'stock'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.stream = 'Shake and trim'::text
UNION ALL
 SELECT 'onhand_concentrate_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Concentrate on hand'::text AS label,
    'stock'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.stream = 'Concentrate'::text
UNION ALL
 SELECT 'onhand_total_dry_equiv_lb'::text AS metric,
    round(sum(
        CASE
            WHEN s.stream = 'Fresh frozen'::text THEN s.pounds / (( SELECT f.r
               FROM f))
            ELSE s.pounds
        END), 1) AS value,
    'Everything on hand in like-for-like dry-equivalent pounds'::text AS label,
    'stock'::text AS grp,
    'production_true_position'::text AS drill
   FROM s
UNION ALL
 SELECT 'onhand_grown_by_us_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'On hand that we grew'::text AS label,
    'origin'::text AS grp,
    'own_vs_bought'::text AS drill
   FROM s
  WHERE s.origin = 'Grown by us'::text
UNION ALL
 SELECT 'onhand_bought_in_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'On hand that we bought in'::text AS label,
    'origin'::text AS grp,
    'third_party_stock'::text AS drill
   FROM s
  WHERE s.origin = 'Bought in'::text
UNION ALL
 SELECT 'pct_bought_in'::text AS metric,
    round(100.0 * sum(s.pounds) FILTER (WHERE s.origin = 'Bought in'::text) / NULLIF(sum(s.pounds), 0::numeric), 1) AS value,
    'Percent of everything on hand that was bought in'::text AS label,
    'origin'::text AS grp,
    'own_vs_bought'::text AS drill
   FROM s
UNION ALL
 SELECT 'third_party_suppliers'::text AS metric,
    count(DISTINCT s.supplier)::numeric AS value,
    'Suppliers we currently hold material from'::text AS label,
    'origin'::text AS grp,
    'third_party_stock'::text AS drill
   FROM s
  WHERE s.origin = 'Bought in'::text
UNION ALL
 SELECT 'third_party_untouched_pkgs'::text AS metric,
    count(*)::numeric AS value,
    'Purchased packages received and never drawn from'::text AS label,
    'origin'::text AS grp,
    'third_party_lifecycle'::text AS drill
   FROM tp
  WHERE tp."position" ~~ 'RECEIVED%'::text OR tp."position" ~~ 'SITTING%'::text
UNION ALL
 SELECT 'third_party_sitting_over_90d'::text AS metric,
    count(*)::numeric AS value,
    'Purchased packages sitting untouched over 90 days'::text AS label,
    'origin'::text AS grp,
    'third_party_lifecycle'::text AS drill
   FROM tp
  WHERE tp."position" ~~ 'SITTING%'::text
UNION ALL
 SELECT 'sellable_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Test-passed and sellable'::text AS label,
    'quality'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.lab_state = 'TestPassed'::text
UNION ALL
 SELECT 'failed_testing_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Failed testing and held'::text AS label,
    'quality'::text AS grp,
    'failed_testing_by_origin'::text AS drill
   FROM s
  WHERE s.lab_state = 'TestFailed'::text
UNION ALL
 SELECT 'never_submitted_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Never submitted for testing'::text AS label,
    'quality'::text AS grp,
    'lab_results'::text AS drill
   FROM s
  WHERE s.lab_state = 'NotSubmitted'::text
UNION ALL
 SELECT 'out_for_testing_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Out for testing right now'::text AS label,
    'quality'::text AS grp,
    'lab_results'::text AS drill
   FROM s
  WHERE s.lab_state ~~ '%ubmitted%'::text AND s.lab_state <> 'NotSubmitted'::text
UNION ALL
 SELECT 'oldest_stock_days'::text AS metric,
    max(s.oldest_days)::numeric AS value,
    'Age of the oldest thing we own, in days'::text AS label,
    'ageing'::text AS grp,
    'stock_on_hand'::text AS drill
   FROM s
UNION ALL
 SELECT 'stock_over_180d_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'On hand sitting over 180 days'::text AS label,
    'ageing'::text AS grp,
    'stock_on_hand'::text AS drill
   FROM s
  WHERE s.oldest_days > 180
UNION ALL
 SELECT 'limits_breached'::text AS metric,
    count(*)::numeric AS value,
    'Storage limits currently breached'::text AS label,
    'control'::text AS grp,
    'storage_limit_status'::text AS drill
   FROM sl
  WHERE sl.status = ANY (ARRAY['OVER THE STORAGE LIMIT'::text, 'MATERIAL OLDER THAN THE LIMIT'::text])
UNION ALL
 SELECT 'limits_not_set'::text AS metric,
    count(*)::numeric AS value,
    'Storage limits nobody has set yet'::text AS label,
    'control'::text AS grp,
    'storage_limits'::text AS drill
   FROM sl
  WHERE sl.status ~~ 'NO LIMIT%'::text
UNION ALL
 SELECT 'open_questions'::text AS metric,
    count(*)::numeric AS value,
    'Questions the platform needs answered'::text AS label,
    'control'::text AS grp,
    'open_questions'::text AS drill
   FROM open_questions
  WHERE open_questions.status = 'open'::text
UNION ALL
 SELECT 'allocations_pending'::text AS metric,
    count(*)::numeric AS value,
    'Allocations waiting on Vincent'::text AS label,
    'control'::text AS grp,
    'allocation_queue'::text AS drill
   FROM allocation_requests
  WHERE allocation_requests.status = 'pending'::text;
create or replace view public.v_tower_inventory_grouped as
 SELECT grp AS section,
    label,
    value,
    drill,
    metric,
        CASE grp
            WHEN 'stock'::text THEN 'What we are holding, by product stream'::text
            WHEN 'origin'::text THEN 'Grown by us versus bought in'::text
            WHEN 'quality'::text THEN 'Testing position'::text
            WHEN 'ageing'::text THEN 'How long it has been sitting'::text
            WHEN 'control'::text THEN 'Controls and things awaiting a decision'::text
            ELSE NULL::text
        END AS section_note
   FROM mv_tower_inventory
  ORDER BY (
        CASE grp
            WHEN 'stock'::text THEN 1
            WHEN 'origin'::text THEN 2
            WHEN 'quality'::text THEN 3
            WHEN 'ageing'::text THEN 4
            ELSE 5
        END), value DESC NULLS LAST;
create or replace view public.v_unmatched_manifest_dossier as
 SELECT f.manifest_number,
    f.diagnosis,
    f.shipped_on,
    t.source_row ->> 'Created'::text AS created_on,
    t.source_row ->> 'Received'::text AS received_on_raw,
    t.source_row ->> 'Created by User'::text AS created_by_user,
    t.source_row ->> 'Received by User'::text AS received_by_user,
    COALESCE(t.source_row ->> 'Type'::text, f.transfer_type) AS transfer_type,
    t.source_row ->> 'Voided'::text AS voided,
    t.source_row ->> 'Inv. Nbr'::text AS metrc_invoice_number,
    f.buyer,
    f.buyer_licence,
    t.source_row ->> 'Dest. Facility Type'::text AS destination_facility_type,
    COALESCE(t.source_row ->> 'Origin Facility'::text, t.licence) AS origin_facility,
    t.source_row ->> 'Origin Lic.'::text AS origin_licence,
    t.source_row ->> 'Origin Facility Type'::text AS origin_facility_type,
    t.package_tag,
    t.item,
    t.category,
    t.strain,
    p.location AS room_when_last_seen,
    p.license AS held_under_licence,
    p.packaged_on,
    p.lab_testing_state,
    p.raw ->> 'SourceHarvestNames'::text AS came_from_harvest,
    p.raw ->> 'SourcePackageLabels'::text AS came_from_packages,
    p.raw ->> 'ProductionBatchNumber'::text AS production_batch,
    t.shipped_qty,
    t.shipped_uom,
    t.received_qty,
    round(COALESCE(t.shipped_lb, 0::numeric), 3) AS shipped_lb,
    t.gross_weight,
    t.source_row ->> 'Weight % Var'::text AS weight_pct_variance,
    t.source_row ->> 'Count % Var'::text AS count_pct_variance,
    t.shipper_wholesale_price AS metrc_declared_usd,
    t.receiver_wholesale_price AS receiver_declared_usd,
    t.status,
    f.apex_candidate_buyer,
    f.apex_candidate_invoice,
    f.apex_candidate_date,
    f.apex_candidate_usd,
    f.apex_candidate_days_apart,
    f.what_to_do
   FROM v_unmatched_manifest_forensic f
     JOIN metrc_rpt_package_transfers t ON t.manifest_number = f.manifest_number
     LEFT JOIN LATERAL ( SELECT mp.location,
            mp.license,
            mp.packaged_on,
            mp.lab_testing_state,
            mp.raw
           FROM metrc_packages mp
          WHERE mp.tag = t.package_tag
          ORDER BY (mp.source_state = 'active'::text) DESC, mp.synced_at DESC
         LIMIT 1) p ON true;
create or replace view public.v_unmatched_manifest_forensic as
 WITH unmatched_lines AS (
         SELECT s.manifest_number,
            s.package_tag,
            s.pounds,
            s.shipped_on,
            s.buyer,
            s.buyer_licence,
            s.transfer_type
           FROM v_forensic_sold_by_tag s
          WHERE s.invoice_match = 'NO APEX INVOICE'::text AND NOT s.internal_transfer AND (COALESCE(s.transfer_type, ''::text) <> ALL (ARRAY['Lab Transfer'::text, 'Vendor Sample Transfer'::text])) AND s.shipped_on >= '2025-01-30'::date AND f_can_be_a_customer(s.buyer_licence)
        ), per_manifest AS (
         SELECT u.manifest_number,
            max(u.shipped_on) AS shipped_on,
            max(u.buyer) AS buyer,
            max(u.buyer_licence) AS buyer_licence,
            max(u.transfer_type) AS transfer_type,
            count(DISTINCT u.package_tag) AS tags,
            round(sum(COALESCE(u.pounds, 0::numeric)), 1) AS lb
           FROM unmatched_lines u
          GROUP BY u.manifest_number
        ), metrc_money AS (
         SELECT t.manifest_number,
            round(sum(COALESCE(t.shipper_wholesale_price, 0::numeric)), 2) AS metrc_declared_usd,
            max(NULLIF(btrim(COALESCE(t.source_row ->> 'Inv. Nbr'::text, ''::text)), ''::text)) AS metrc_invoice_number
           FROM metrc_rpt_package_transfers t
             JOIN unmatched_lines u ON u.manifest_number = t.manifest_number AND u.package_tag = t.package_tag
          GROUP BY t.manifest_number
        ), apex AS (
         SELECT regexp_replace(COALESCE(apex_raw.payload ->> 'buyer_state_license'::text, ''::text), '\D'::text, ''::text, 'g'::text) AS digits,
            NULLIF(btrim(COALESCE(apex_raw.payload ->> 'invoice_number'::text, ''::text)), ''::text) AS invoice_number,
            (apex_raw.payload -> 'buyer'::text) ->> 'name'::text AS apex_buyer,
            (apex_raw.payload ->> 'order_date'::text)::date AS order_date,
            (apex_raw.payload ->> 'total'::text)::numeric AS total_usd
           FROM apex_raw
          WHERE apex_raw.entity = 'shipping-orders'::text AND COALESCE(apex_raw.payload ->> 'order_date'::text, ''::text) <> ''::text
        ), by_invoice AS (
         SELECT DISTINCT ON (p_1.manifest_number) p_1.manifest_number,
            a.apex_buyer,
            a.order_date,
            a.invoice_number,
            a.total_usd,
            abs(a.order_date - p_1.shipped_on) AS days_apart,
            'invoice number'::text AS matched_on
           FROM per_manifest p_1
             JOIN metrc_money mm_1 ON mm_1.manifest_number = p_1.manifest_number
             JOIN apex a ON a.invoice_number = mm_1.metrc_invoice_number
          ORDER BY p_1.manifest_number, (abs(a.order_date - p_1.shipped_on))
        ), by_digits AS (
         SELECT DISTINCT ON (p_1.manifest_number) p_1.manifest_number,
            a.apex_buyer,
            a.order_date,
            a.invoice_number,
            a.total_usd,
            abs(a.order_date - p_1.shipped_on) AS days_apart,
            'licence digits + date'::text AS matched_on
           FROM per_manifest p_1
             JOIN apex a ON a.digits = regexp_replace(COALESCE(p_1.buyer_licence, ''::text), '\D'::text, ''::text, 'g'::text) AND a.digits <> ''::text AND abs(a.order_date - p_1.shipped_on) <= 14
          WHERE NOT (EXISTS ( SELECT 1
                   FROM by_invoice bi
                  WHERE bi.manifest_number = p_1.manifest_number))
          ORDER BY p_1.manifest_number, (abs(a.order_date - p_1.shipped_on))
        ), candidate AS (
         SELECT by_invoice.manifest_number,
            by_invoice.apex_buyer,
            by_invoice.order_date,
            by_invoice.invoice_number,
            by_invoice.total_usd,
            by_invoice.days_apart,
            by_invoice.matched_on
           FROM by_invoice
        UNION ALL
         SELECT by_digits.manifest_number,
            by_digits.apex_buyer,
            by_digits.order_date,
            by_digits.invoice_number,
            by_digits.total_usd,
            by_digits.days_apart,
            by_digits.matched_on
           FROM by_digits
        )
 SELECT p.manifest_number,
    p.shipped_on,
    p.buyer,
    p.buyer_licence,
    p.transfer_type,
    p.tags,
    p.lb,
    mm.metrc_declared_usd,
    mm.metrc_invoice_number,
        CASE
            WHEN c.matched_on = 'invoice number'::text THEN 'INVOICE NUMBER MATCHES — Metrc and Apex hold the same invoice. The standing '::text || 'rule never compared it.'::text
            WHEN c.matched_on IS NOT NULL THEN ('LICENCE FORMAT — Apex holds an order for this party, found on licence '::text || 'DIGITS. The standing rule compares the licence exactly and Apex stores '::text) || 'it as free text.'::text
            ELSE 'ABSENT FROM APEX — no order for this party by invoice number, licence digits '::text || 'or date. This one is genuinely not in Apex.'::text
        END AS diagnosis,
    c.apex_buyer AS apex_candidate_buyer,
    c.invoice_number AS apex_candidate_invoice,
    c.order_date AS apex_candidate_date,
    c.total_usd AS apex_candidate_usd,
    c.days_apart AS apex_candidate_days_apart,
        CASE
            WHEN c.matched_on IS NOT NULL THEN ('Confirm and repair the standing match rule: add the Metrc invoice number '::text || 'as the first key and compare licences on digits. One change closes '::text) || 'every manifest matched this way.'::text
            ELSE 'Not in Apex by any key. Check the deal-docs endpoint — marked required, '::text || 'never synced. If genuinely uninvoiced, that is a billing recovery.'::text
        END AS what_to_do,
    c.matched_on
   FROM per_manifest p
     LEFT JOIN metrc_money mm ON mm.manifest_number = p.manifest_number
     LEFT JOIN candidate c ON c.manifest_number = p.manifest_number;
create or replace view public.v_unmatched_manifest_tags as
 SELECT f.manifest_number,
    f.shipped_on,
    f.buyer,
    f.buyer_licence,
    f.diagnosis,
    s.package_tag,
    s.item,
    s.category,
    s.strain,
    round(COALESCE(s.pounds, 0::numeric), 3) AS lb,
    NULL::numeric AS shipped_qty,
    NULL::text AS shipped_uom,
    NULL::numeric AS received_qty,
    NULL::numeric AS metrc_declared_usd,
    s.status,
    f.apex_candidate_invoice,
    f.apex_candidate_usd,
    s.product_line,
    f.apex_candidate_date
   FROM v_unmatched_manifest_forensic f
     JOIN v_forensic_sold_by_tag s ON s.manifest_number = f.manifest_number AND s.invoice_match = 'NO APEX INVOICE'::text;

