create policy zsr_read on public.zone_staffing_requirements as permissive for select to authenticated using (( SELECT f_can_read_hr() AS f_can_read_hr));
create policy zsr_write on public.zone_staffing_requirements as permissive for all to authenticated using (f_can_decide_hr()) with check (f_can_decide_hr());
create policy zones_read on public.zones as permissive for select to authenticated using (true);

